window.VingeRecordCases = [{"year":2026,"client":"KEYTO Group","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Kommersiella avtal","GDPR"],"title":"Vinge företräder KEYTO Group i samband med förvärvet av Säkra Larm","caption":"Förvärv · 24 september 2026","preamble":"KEYTO fortsätter att bredda sitt utbud av hushållstjänster genom förvärvet av Säkra Larm, vilket etablerar hemsäkerhet som ett nytt affärsområde inom KEYTO. Tillskottet av Säkra Larm markerar ytterligare ett steg i KEYTO:s ambition att vara en ledande \"one-stop destination\" för tjänster kopplade till hemmet.","body":"Vinges team bestod huvudsakligen av Jonas Bergström, Gustav Wahlberg och Ian Linde (M&A), William Karo Persson (Arbetsrätt), Malin Dejke och Felicia Sandén (Kommersiella avtal), Siri Blomberg (GDPR) samt Diana Kanold (Projekt assistent).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-keyto-group-i-samband-med-forvarvet-av-sakra-larm/","sector":"Konsumenttjänster","date":"2026-09-24","month":9},{"year":2026,"client":"Ingrid Capacity","work":"Partnerskap","disciplines":["M&A"],"title":"Vinge har företrätt Ingrid Capacity vid ingåendet av ett strategiskt partnerskap med Mirova avseende ett strategiskt partnerskap för en storskalig BESS-portfölj i Norden","caption":"Partnerskap · 24 september 2026","preamble":"Ingrid Capacity och Mirova, ett dotterbolag till Natixis Investment Managers med inriktning på hållbara investeringar, tillkännager ett gränsöverskridande partnerskap avseende två BESS-projekt om totalt 145 MW/290 MWh i Sverige och Finland. Ingrid Capacity kommer att utveckla, driva och optimera båda systemen. Vinge har företrätt Ingrid Capacity vid ingåendet av partnerskapet.","body":"Med projekten i partnerskapet med Mirova når Ingrid mer än 950 MWh batterilager i drift och under förvaltning.\n\nI sitt första BESS-partnerskap i Norden investerar Mirova 65 miljoner euro i två av Ingrids storskaliga lagringssystem:\n• Pedersöre, Finland: ett batterilagerprojekt på 45 MW / 90 MWh som är klart för byggstart.\n• Vaggeryd, Sverige: ett batterilagerprojekt på 100 MW / 200 MWh i elområde SE3, som väntas vara klart för byggstart 2027.\n\nSom vertikalt integrerad BESS-specialist kommer Ingrid Capacity att utveckla, driva och optimera båda systemen. Ingrid kommer att tillhandahålla teknisk och kommersiell projektförvaltning, EPC-ledning samt optimeringstjänster. Genom partnerskapet tillför Ingrid Capacity nu 145 MW/290 MWh till sin portfölj av projekt under byggnation eller i drift. Med dessa två projekt kommer Ingrid Capacity att ha 950 MWh i projekt under förvaltning.\n\nVinges team bestod huvudsakligen av Johan Larsson, Per Kling, Viktor Ejlertsson och Lucas Eriksson (M&A).\n\nFör fler detaljer om transaktionen hänvisas till Ingrid Capacitys pressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-ingrid-capacity-vid-ingaendet-av-ett-strategiskt-partnerskap-med-mirova-avseende-ett-strategiskt-partnerskap-for-en-storskalig-bess-portfolj-i-norden/","date":"2026-09-24","month":9},{"year":2026,"client":"Bankerna bakom Verdane och Telenor","work":"Partnerskap","disciplines":["Bank och finans"],"title":"Vinge biträder finansierande banker i samband med Verdane och Telenors partnerskap avseende Telenor Connexion","caption":"Partnerskap · 23 september 2026","preamble":"Vinge har biträtt ett syndikat av nordiska och nordeuropeiska banker i samband med finansieringen av Verdane och Telenors etablering av ett nytt partnerskap avseende Telenor Connexion. Inom ramen för partnerskapet kommer Verdane och Telenor gemensamt att investera i Telenor Connexion, en ledande leverantör av IoT-lösningar. Transaktionen slutfördes den 10 september 2026 och värderar Telenor Connexion till 7,5 miljarder kronor.","body":"Telenor Connexion tillhandahåller IoT-tjänster och uppkopplingslösningar till stora internationella kunder och har en global verksamhet, med 31 miljoner IoT SIM-kort i drift och tjänster levererade i mer än 200 länder.\n\nVinges team bestod huvudsakligen av Albert Wållgren, Kamyar Najmi, William Carlberg Johansson, Jakob Rehnström och Pontus Tegström.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-finansierande-banker-i-samband-med-verdane-och-telenors-partnerskap-avseende-telenor-connexion/","sector":"Telekom","date":"2026-09-23","month":9},{"year":2026,"client":"Accru Partners och Axcel","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Accru Partners vid emission av seniora säkerställda obligationer","caption":"Obligationsemission · 23 september 2026","preamble":"Vinge biträder Accru Partners, och dess ägare Axcel, vid Accru Partners första emission av seniora säkerställda obligationer om EUR 550 miljoner.","body":"ABG Sundal Collier AB, Danske Bank A/S, Danmark, Sverige Filial, DNB Carnegie Investment Bank AB (publ), Nordea Bank Abp, Nykredit Bank A/S och Skandinaviska Enskilda Banken AB (publ) agerade joint bookrunners. Emissionen är den största ratade nordiska high yield-obligationen från en förstagångsemittent på marknaden hittills.\n\nDärutöver har Accru Partners säkerställt en super senior revolverande kreditfacilitet om EUR 125 miljoner för att skapa utrymme för framtida tilläggsförvärv och andra allmänna företagsändamål.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, William Carlberg Johansson och Sara Eirefors.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-accru-partners-vid-emission-av-seniora-sakerstallda-obligationer/","sector":"Private equity","date":"2026-09-23","month":9},{"year":2026,"client":"Sveafastigheter","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Sveafastigheter vid emission av obligationer om EUR 350 miljoner","caption":"Obligationsemission · 23 september 2026","preamble":"Vinge har biträtt Sveafastigheter AB (publ) vid dess emission av seniora icke-säkerställda obligationer om EUR 350 miljoner under Sveafastigheters befintliga EMTN-program med ett rambelopp om EUR 2 miljarder.","body":"Obligationerna har en löptid om 5,5 år med förfall den 2 mars 2032 och en kupong om 4,50 procent. Emissionslikviden avses användas för allmänna företagsändamål, inklusive finansiering i samband med fusionen med KlaraBo.\n\nCitigroup Global Markets Europe AG agerade som Global Coordinator, varvid Citigroup Global Markets Europe AG och Goldman Sachs Bank Europe SE agerade som Joint Bookrunners.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, Ida Redander och Anna Wisborg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sveafastigheter-vid-emission-av-obligationer-om-eur-350-miljoner/","sector":"Fastigheter","date":"2026-09-23","month":9},{"year":2026,"client":"Qflow Group","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Qflow vid emissioner av seniora säkerställda obligationer","caption":"Obligationsemission · 23 september 2026","preamble":"Vinge har biträtt Qflow Group AB (publ) i samband med två efterföljande emissioner av seniora säkerställda obligationer om totalt SEK 600 miljoner under bolagets befintliga obligationsramverk.","body":"Efter godkännande från obligationsinnehavarna genom ett skriftligt förfarande, vilket även ökade rambeloppet från SEK 1,2 miljarder till SEK 1,6 miljarder, genomförde Qflow en tap-emission om SEK 400 miljoner. Ytterligare seniora säkerställda obligationer om SEK 200 miljoner, initierade genom s.k. reverse inquiry, emitterades därefter, varvid det totala utestående nominella beloppet under ramverket uppgick till SEK 1 600 miljoner.\n\nDanske Bank A/S, Danmark, Sverige Filial och Pareto Securities AB agerade som joint bookrunners vid båda emissionerna.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda, Felix Möller, Anna Wisborg, Julia Gudmundsson och Pontus Tegström.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-qflow-vid-emissioner-av-seniora-sakerstallda-obligationer/","sector":"Bygg och infrastruktur","date":"2026-09-23","month":9},{"year":2026,"client":"Revivo Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Revivo Group vid förvärv av IdeaPaint","caption":"Förvärv · 21 september 2026","preamble":"Revivo Group fortsätter sin expansion i Finland genom förvärvet av IdeaPaint Oy, ett Tammerforsbaserat bolag specialiserat på industriell ytbehandling.","body":"Vinge, genom Johan Winnerblad, biträder Revivo Group i förvärvet.\n\nLäs klientens pressmeddelandet här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-revivo-group-vid-forvarv-av-ideapaint/","sector":"Industri","date":"2026-09-21","month":9},{"year":2026,"client":"Fortinova Fastigheter","work":"Obligationsemission","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge biträder Fortinova Fastigheter AB (publ) vid bolagets första gröna obligationsemission om 200 miljoner kronor","caption":"Obligationsemission · 18 september 2026","preamble":"Vinge har biträtt Fortinova Fastigheter AB (publ) (”Fortinova”) i samband med bolagets första emission av icke-säkerställda gröna seniora obligationer om 200 miljoner kronor, under ett ramverk om upp till 600 miljoner kronor. Nordea agerade sole bookrunner i samband med emissionen.","body":"Obligationerna löper med rörlig ränta om 3M STIBOR plus + 300 baspunkter och har en löptid om 3,25 år. Emissionslikviden kommer enligt obligationsvillkoren att användas för allmänna företagsändamål och i enlighet med Fortinovas nyligen etablerade gröna ramverk. Fortinova avser att uppta obligationerna till handel på Nasdaq Stockholms lista för gröna obligationer inom 60 dagar från emissionsdagen.\n\nFortinova är ett växande fastighetsbolag vars affärsidé sedan starten 2010 har bestått av att förvärva, utveckla och förvalta främst bostadsfastigheter vilka, enligt Fortinovas bedömning, har dokumenterade starka kassaflöden. Fortinova har ett geografiskt fokus på tillväxtkommuner i västra Sverige som koncernen bedömer har en god tillväxtprofil och är attraktiva orter att bo, arbeta och leva i.\n\nVinges team bestod av Wibeke Sorling, Lionardo Ojeda, Edin Agic och Sofia Haggren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-fortinova-fastigheter-ab-publ-vid-bolagets-forsta-grona-obligationsemission-om-200-miljoner-kronor/","sector":"Fastigheter","date":"2026-09-18","month":9},{"year":2026,"client":"Morrow Bank","work":"Avyttring","disciplines":["M&A","Finansiella tillståndsfrågor","Kommersiella avtal","IT, Telekom och Outsourcing","Arbetsrätt","Immaterialrätt"],"title":"Vinge har företrätt Morrow Bank AB (publ) i samband med bankens försäljning av delar av MedMera Bank samt försäljning av NPL-portföljer","caption":"Avyttring · 15 september 2026","preamble":"Vinge har företrätt Morrow Bank AB (publ) vid avyttringen av delar av MedMera Banks verksamhet till ett ledande globalt kreditinvesteringsbolag. Avyttringen är strukturerad som en aktieförsäljning och prissatt till en premie om cirka 90 miljoner kronor över det egna kapitalets värde per slutförandedagen. Transaktionen omfattar delar av MedMeras bankverksamhet såsom IT-infrastruktur, organisation och ledning, medan Morrow Bank behåller MedMeras presterande lån, inlåning, kunder, varumärket MedMera, Coop-partnerskapsavtalet samt nyckelpersoner.","body":"Avyttringen följer Morrow Banks offentliggörande den 8 juni 2026 om strategiska alternativ för vissa icke-kärntillgångar efter förvärvet av MedMera. I en separat transaktion har Morrow Bank även avtalat om att sälja sina norska och finska NPL-portföljer. Portföljerna uppgick till cirka 1,5 miljarder kronor per den 31 augusti 2026. Transaktionerna förenklar verksamheten, påskyndar integrationen av MedMera och stärker fokus på lönsam tillväxt.\n\nVinges team bestod huvudsakligen av Samra Tesser, Viktor Ramhult, Mana Sohrabi och Ebba Dahlberg (M&A), Emma Stuart-Beck, Elias Bohlin och Rebecka Björnestedt (Financial Services), Eva Fredrikson, Mario Saad och Katja Häglund (Kommersiella Avtal & IT), Sam Seddigh och Louisa Fagarsan (Arbetsrätt), Axel Lennartsson (IP) samt Cecilia Loctander (Transaction Support Senior Coordinator).\n\nTransaktionerna förutsätter sedvanliga regulatoriska godkännanden och förväntas slutföras före utgången av 2026.\n\nFör detaljer om transaktion hänvisas till Morrow Banks pressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-morrow-bank-ab-publ-i-samband-med-bankens-forsaljning-av-delar-av-medmera-bank-samt-forsaljning-av-npl-portfoljer/","sector":"Bank och finans","date":"2026-09-15","month":9},{"year":2026,"client":"HealthCap","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder HealthCap vid investering i AMRA Medical","caption":"Kapitalanskaffning · 15 september 2026","preamble":"HealthCap investerar i AMRA Medical AB, ett bolag som analyserar helkropps-MR-bilder för att klassificera och kvantifiera en individs muskel- och fettvävnad i hela kroppen, och sätter detta i relation till människors hälsa och sjukdomar.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Gustav Wahlberg, Daniel Wendelsson, Isabelle Asserståhl, Avidh Tajik, Johanna Fjellström och Emma Gustavsson.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-healthcap-vid-investering-i-amra-medical/","sector":"Life science","date":"2026-09-15","month":9},{"year":2026,"client":"Scaleup Europe Fund (EQT)","work":"Kapitalanskaffning","disciplines":["M&A","GDPR","Immaterialrätt","Arbetsrätt","Kommersiella avtal","FDI","EU‑ och konkurrensrätt"],"title":"Vinge har biträtt EQT-förvaltade Scaleup Europe Fund i samband med dess investering i Tandem Health","caption":"Kapitalanskaffning · 15 september 2026","preamble":"Vinge har biträtt EQT-förvaltade Scaleup Europe Fund som huvudinvesterare i Tandem Healths 100 miljoner USD serie B investeringsrunda, i vilken även befintliga investerare Kinnevik, Northzone, Amino Collective och Visionaries deltog. Tandem Health är ett AI-vårdbolag baserat i Stockholm som grundades år 2023. Tandem Health verkar som en AI-partner inom sjukvården på den europeiska marknaden och erbjuder en medicinsk AI-assistent för vårdpersonal inom ramen för patientbesök.","body":"Vinges team bestod huvudsakligen av Christina Kokko, Kim Bergman Aldevinge, Hedvig Merkel och Lina Björkman (M&A), Nicklas Thorgerzon (Dataskydd), Axel Lennartsson (IP), William Karo Persson (Arbetsrätt), Christoffer Nordin, Mario Saad, Avidh Tajik och Dennis Hultman (Kommersiella Avtal) samt Sebastian Örndahl (Konkurrensrätt och FDI).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-eqt-forvaltade-scaleup-europe-fund-i-samband-med-dess-investering-i-tandem-health/","sector":"Life science","date":"2026-09-15","month":9},{"year":2026,"client":"SBP Kredit","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt SBP Kredit AB (publ) i samband med värdepapperisering med en nordisk bank som senior långivare","caption":"Finansiering · 14 september 2026","preamble":"Transaktionen omfattar ett rambelopp om en miljard kronor och skapar förutsättningar för en väsentligt utökad utlåningskapacitet. Avtalet är strukturerat i enlighet med EU:s värdepapperiseringsförordning och innebär att kvalificerade lån löpande kan överlåtas till ett särskilt bolag inom SBP-koncernen.","body":"SBP Kredit erbjuder finansieringslösningar till svenska fastighetsägare och fastighetsutvecklare.\n\nVinges team bestod av Henrik Ossborn, Josefine Edström, Caroline Krassén, Elias Bohlin, William Carlberg Johansson och Sara Eirefors.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-sbp-kredit-ab-publ-i-samband-med-vardepapperisering-med-en-nordisk-bank-som-senior-langivare/","sector":"Bank och finans","date":"2026-09-14","month":9},{"year":2026,"client":"Svenska Handelsfastigheter","work":"Förvärv","disciplines":["Fastigheter och Entreprenad","Miljörätt"],"title":"Vinge har företrätt Svenska Handelsfastigheter i affär med Skandia Fastigheter avseende förvärv av fastigheter i Torslanda och Hässleholm","caption":"Förvärv · 14 september 2026","preamble":"Vinge har företrätt Svenska Handelsfastigheter vid en affär med Skandia Fastigheter bestående av förvärv av fastigheten Hässleholm Förrådet 1 och fastigheten Göteborg Amhult 109:2.","body":"Fastigheterna omfattar tilsammans en handelsyta om 12 300 kvm, varav fastigheten i Hässleholm omfattar 8 841 kvm och är fullt uthyrd med Willys, Elgiganten och JYSK som stora hyresgäster. Fastigheten i Torslanda omfattar 3 460 kvm och är fullt uthyrd till bland annat Lindex, Kronans Apotek och Handelsbanken.\n\nVinges team bestod av Niclas Winnberg, Amanda Strömblad, Madelene Andersson och Wilma Hellman.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-svenska-handelsfastigheter-i-affar-med-skandia-fastigheter-avseende-forvarv-av-fastigheter-i-torslanda-och-hassleholm/","sector":"Fastigheter","date":"2026-09-14","month":9},{"year":2026,"client":"Northmill Group","work":"Kapitalanskaffning","disciplines":["Bank och finans"],"title":"Vinge har biträtt Northmill Group AB i samband med dess emission av supplementärkapitalinstrument (T2)","caption":"Kapitalanskaffning · 11 september 2026","preamble":"Vinge har biträtt Northmill Group AB vid dess framgångsrika emission av T2-obligationer om 150 miljoner kronor med en rörlig kupong om 3-månaders STIBOR + 475 punkter.","body":"Emissionen utgör Northmills andra Tier 2-obligation och optimerar Northmills kapitalstruktur och ger strategisk flexibilitet i strävan efter fortsatt stark och lönsam tillväxt. Northmill Group är moderbolag till Northmill Bank, en svensk utmanarbank som erbjuder finansiella tjänster för både privatpersoner och företag. Emissionen följer på Northmills första Tier 2-utgivning i november 2025 samt en framgångsrik utgivning av en Additional Tier 1-obligation i april 2026.\n\nArctic Securities AS, filial Sverige, agerade sole bookrunner i samband med obligationsemissionen.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda, Caroline Krassén och Anna Wisborg.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-northmill-group-ab-i-samband-med-dess-emission-av-supplementarkapitalinstrument-t2/","sector":"Bank och finans","date":"2026-09-11","month":9},{"year":2026,"client":"IK Partners och Francks Kylindustri","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder IK Partners och Francks Kylindustri i samband med förvärvet av Helsingborgs Kylteknik","caption":"Förvärv · 11 september 2026","preamble":"Vinge företräder IK Partners och deras portföljbolag Francks Kylindustri i samband med förvärvet av Helsingborgs Kylteknik, ett bolag specialiserat inom kylteknik och kylservice i södra Sverige. Förvärvet stärker Francks Kylindustris position i södra Sverige och breddar koncernens erbjudande inom kylindustrin.","body":"Francks Kylindustri är en ledande aktör inom kyl- och värmepumpslösningar med verksamhet i Sverige, Norge, Finland, Danmark och Nederländerna. Helsingborgs Kylteknik, grundat 1990, är specialiserat på kylteknisk service och erbjuder installation, service och underhåll av kylanläggningar.\n\nVinges team bestod av Johanna Wiberg, Fredrik Eriksson Oppliger och Ellenor Eckerborn (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ik-partners-och-francks-kylindustri-i-samband-med-forvarvet-av-helsingborgs-kylteknik/","sector":"Industri","date":"2026-09-11","month":9},{"year":2026,"client":"Säljarna av Berg Propulsion","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder säljarna av Berg Propulsion","caption":"Avyttring · 10 september 2026","preamble":"Vinge har biträtt säljarna i samband med försäljningen av Berg Propulsion till Kongsberg Maritime.","body":"Berg Propulsion, med säte på Hönö i Göteborgs norra skärgård, utvecklar och tillverkar kompletta framdrivningssystem och propellrar för den internationella marinindustrin.\n\nVinges team bestod av Magnus Pauli, Hanna Marberg, Amelia Rihs, Anna Palmérus, Fredrik Löwenclou, Amanada Stoltz med flera.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-saljarna-av-berg-propulsion/","sector":"Industri","date":"2026-09-10","month":9},{"year":2026,"client":"Naval Group","work":"Avtal","disciplines":["FDI","Immaterialrätt","Offentlig upphandling","Corporate Commercial","Kommersiella avtal"],"title":"Naval Group tecknar avtal om fyra försvars- och interventionsfregatter (FDI) till svenska marinen","caption":"Avtal · 8 september 2026","preamble":"Vinge har biträtt Naval Group i samband med förhandlingarna med Försvarets materielverk (FMV) avseende upphandling av fyra försvars- och interventionsfregatter (FDI) till svenska marinen. Avtalet undertecknades den 31 augusti 2026 i Stockholm. Naval Group har valts ut av den svenska regeringen som strategisk partner för att snabbt stärka och modernisera marinens förmåga.","body":"Vinges team leddes av Eva Fredrikson och Daniel Wendelsson och bestod även av Malin Malm Waerme, Anders Leissner, Mario Saad, Fredrik Löwenclou och Paula Bäckdén.","href":"https://www.vinge.se/uppdrag/naval-group-tecknar-avtal-om-fyra-forsvars-och-interventionsfregatter-fdi-till-svenska-marinen/","date":"2026-09-08","month":9},{"year":2026,"client":"Axcel och Sanviva","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","Bank och finans","Arbetsrätt","FDI"],"title":"Vinge företräder Axcel och Sanviva vid förvärven av DermaCura och YourRad","caption":"Förvärv · 7 september 2026","preamble":"Vinge har företrätt Axcel Elevate I och Sanviva i samband med förvärven av DermaCura och YourRad.","body":"DermaCura är ett nederländskt familjeföretag inom specialiserade medicintekniska produkter för patienter med kroniska hudsjukdomar. Genom förvärvet av DermaCura stärker Sanviva sin position i Benelux-området och expanderar produktportföljen med intilliggande produkter inom dermatologi. YourRad är ett entreprenörslett bolag inom distribution av strålbehandlingsutrustning, förbrukningsartiklar och relaterade medicintekniska produkter i Norden. Genom förvärvet av YourRad stärker Sanviva sin position i Norden och expanderar produktportföljen till specialiserade produkter inom strålbehandling och onkologi.\n\nSanviva är ett distributionsnätverk för medicintekniska produkter som kombinerar lokal försäljning, distribution och marknadskunskap för att ge leverantörer tillgång till hälso- och sjukvårdsmarknader i Europa. Sanviva är verksamma i Norden och Benelux med en produktportfölj som innefattar bland annat sårvård, stomivård, in vitro-diagnostik och närliggande produkter.\n\nVinges team bestod av Christina Kokko, Egil Svensson, Ida Appelgren, Lina Björkman och Celina Kristiansson (M&A), Christoffer Nordin och Katja Häglund (Corporate Commercial), Nilufer Nouri (Bank och Finans), Louisa Fagarasan och Linn Aho (Arbetsrätt), Dagne Sabockis (FDI) och Filippa Bergkvist (Transaction Support Coordinator).\n\nLäs klientens pressmeddelande här och här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-sanviva-vid-forvarven-av-dermacura-och-yourrad/","date":"2026-09-07","month":9},{"year":2026,"client":"Formica","work":"Övrigt","disciplines":["M&A"],"title":"Vinge biträder Formica","caption":"Övrigt · 6 september 2026","preamble":"Vinge har biträtt Formica vid förvärv av CodeIT-koncernen med verksamhet i Norge och Sverige.","body":"Vinges team leddes av Magnus Pauli, huvudsakligen biträdd av Emma Jansson, samt Advokatfirman Thommessen avseende norska frågor.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-formica/","date":"2026-09-06","month":9},{"year":2026,"client":"Revivo Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Revivo Group vid förvärv av Premator","caption":"Förvärv · 3 september 2026","preamble":"Revivo Group AB har förvärvat samtliga aktier i Premator AB, moderbolag i en koncern med verksamhet inom avancerad ytbehandling med lång erfarenhet av blästring, rostskyddsmålning och relaterade tjänster. Verksamheten bedrivs i Sverige, Norge och Danmark.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Gustav Wahlberg.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-revivo-group-vid-forvarv-av-premator/","date":"2026-09-03","month":9},{"year":2026,"client":"Säljarna","work":"Avyttring","disciplines":["M&A","EU‑ och konkurrensrätt","Immaterialrätt","Arbetsrätt"],"title":"Vinge företräder säljarna vid försäljning av Nextory till Bonnier Books","caption":"Avyttring · 2 september 2026","preamble":"Vinge har agerat legal rådgivare till säljarna i samband med Bonnier Books förvärv av Nextory, en av Europas ledande streamingtjänster för ljudböcker och e-böcker. Bonnier Books förvärvar samtliga aktier i Nextory och affären omfattar Nextorys verksamhet i Sverige och internationellt. Förvärvet är en kontantaffär och parterna har kommit överens om att inte offentliggöra köpeskillingen. Transaktionen är villkorad av sedvanliga regulatoriska godkännanden.","body":"Nextory grundades 2015 av serieentreprenörerna Shadi Bitar och Ninos Malki med visionen att göra böcker mer tillgängliga och få fler människor att läsa och lyssna. Sedan starten har bolaget vuxit från en svensk utmanare till en internationell bokplattform och erbjuder i dag över 1,4 miljoner titlar på tio marknader i Europa.\n\nBonnier Books samlar Bonniers samtliga bokförlag i Sverige och internationellt samt ljud- och e-bokstjänsten BookBeat. Koncernen har förlagsverksamhet i sju länder och ger ut böcker under mer än 100 olika förlag och imprints. BookBeat lanserades 2015 och har i dag över 1,2 miljoner betalande användare på tio marknader och en omsättning om cirka 1,7 miljarder kronor.\n\nVinges team bestod huvudsakligen av Johan Larsson, Edvard Gustafsson och Ida Appelgren (M&A Corporate), Marcus Glader och Jakob Rosini Jeanrond (Konkurrensrätt), Arvid Axelryd (Immaterialrätt), Sam Seddigh (Arbetsrätt) samt Ellinore Boström Andersson och Filippa Bergkvist (Transaction Support).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-saljarna-vid-forsaljning-av-nextory-till-bonnier-books/","date":"2026-09-02","month":9},{"year":2026,"client":"Nimlas","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Nimlas i samband med sex strategiska förvärv som stärker koncernens position på den svenska installationsmarknaden","caption":"Förvärv · 2 september 2026","preamble":"Nimlas, med KLAR Partners som huvudägare, är en av Nordens ledande installationskoncerner med närmare 140 bolag och 5 000 medarbetare i Sverige, Finland och Norge.","body":"Nimlas har förvärvat Keyvent Öst, J. Svensson Service i Norr, Building Management Systems Technology & Green Tech Solutions AB, Svenska VVS & elanläggningar, Jönköpings Rörtjänst, och EF Rör. Genom förvärven tar Nimlas Sverige ytterligare steg i sin tillväxtstrategi 5-50-500; 5 miljarder i omsättning, 50 nya bolag och 500 miljoner i resultat – och breddar koncernens erbjudande inom VVS, el, ventilation, fastighetsautomation och datanätverk.\n\nVinges team bestod huvudsakligen av Johanna Wiberg, Fredrik Eriksson Oppliger, Alex Forsberg och Sara Hammond (M&A), Mario Saad och Avidh Tajik (Kommersiella avtal) och Louisa Fagarasan (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-nimlas-i-samband-med-sex-strategiska-forvarv-som-starker-koncernens-position-pa-den-svenska-installationsmarknaden/","date":"2026-09-02","month":9},{"year":2026,"client":"Aspira Partners","work":"Övrigt","disciplines":["Private Funds","Företagsbeskattning"],"title":"Vinge har biträtt Aspira Partners vid etableringen av Aspira Fund I","caption":"Övrigt · 31 augusti 2026","preamble":"Vinge har biträtt Aspira Partners (\"Aspira\") vid etableringen och fondresningen av Aspiras debutfond, Aspira Fund I (D) AB och Aspira Fund I (E) AB (gemensamt \"Fonden\").","body":"Fonden, som övertecknades, stängde vid sin hard cap om 270 miljoner euro i externt kapital. Investerarbasen utgörs av ett flertal välrenommerade institutionella investerare från kontinentaleuropa, Norden och Nordamerika. Connaught (EU) B.V. agerade placement agent.\n\nAspira investerar i grundarledda SME-bolag i Norden med fokus på verksamhetskritiska B2B-företag inom business services, specialiserad industri och teknologi med tydliga möjligheter för buy-and-build och organisk tillväxt. Sedan fondresningen inleddes har Fonden genomfört fyra plattformsinvesteringar.\n\nVinges team bestod huvudsakligen av Mattias Schömer, Martin Cronsioe, Marcus Andersson, Tobias Onegård Karlsson, Liva Bihre, Jenny Tolander, Sara Link, Nils Unckel, Mikaela Reinhammar, Anton Sjökvist, Emelie Svanberg, Erik Kochbati, Anna Neubüser, Felicia Andersson och Emelie Zingmark.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-aspira-partners-vid-etableringen-av-aspira-fund-i/","date":"2026-08-31","month":8},{"year":2026,"client":"Consolid Equity","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder Consolid Equity vid försäljningen av Road Mobility Services till Nalka","caption":"Avyttring · 28 augusti 2026","preamble":"Vinge har biträtt Consolid Equity vid försäljningen av Road Mobility Services till Nalka. I samband med transaktionen kommer Consolid, entreprenörer och ledning att återinvestera och kvarstå som minoritetsägare vid sidan av Nalka som ny majoritetsägare.","body":"Road Mobility Services samlar högpresterande företag inom akut vägassistans, däckservice och verkstadsservice längs stora trafikleder i Europa. Bolaget driver i dag 83 egna verkstäder i fyra länder och har genom sitt omfattande nätverk tillgång till fler än 3 000 betrodda partners över hela Europa. I samband med ägarförändringen tillträder Anders Jensen, VD för Cary Group, som ny styrelseordförande i Road Mobility Services.\n\nVinges team har huvudsakligen bestått av Christina Kokko, Johanna Wiberg, Elsie Nassar, Edvard Gustafsson, Olof Löfvenberg, Matilda Hamner och Karl Womack (M&A), Sebastian Örndahl och David Olander (Konkurrensrätt och FDI), Henrik Ossborn, Calle Tengwall Pagels och Nilufer Nouri (Bank och finans), samt Julia Ulander Kull och Emy Rydén (Transaction Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-consolid-equity-vid-forsaljningen-av-road-mobility-services-till-nalka/","date":"2026-08-28","month":8},{"year":2026,"client":"IK Partners och Selatek","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder IK Partners och Selatek i samband med förvärvet av Jamo Sikring","caption":"Förvärv · 21 augusti 2026","preamble":"Vinge företräder IK Partners och deras portföljbolag Selatek AB (“Selatek”) i samband med förvärvet av JAMO SIKRING A/S (“Jamo Sikring”), en dansk specialist inom installation, service och löpande kontroll av brandtekniska anläggningar. Förvärvet innebär att Selatek etablerar verksamhet i Danmark och stärker samtidigt koncernens position inom brandsäkerhet och säkerhetsservice i Norden.","body":"Selatek har huvudkontor i Stockholm och är specialiserat på säkerhet, el- och automationslösningar inom fastigheter, infrastruktur och industrimiljöer. Jamo Sikring, med huvudkontor i Rødovre, Danmark är specialiserat på installation, service och löpande kontroll av brandtekniska system.\n\nVinges team bestod av Jonas Bergström, Johanna Wiberg, Johanna Barfoed och Robert Sande (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ik-partners-och-selatek-i-samband-med-forvarvet-av-jamo-sikring/","date":"2026-08-21","month":8},{"year":2026,"client":"Xamera Group","work":"Förvärv","disciplines":["M&A","IT, Telekom och Outsourcing"],"title":"Vinge biträder Xamera Group vid förvärv av finska Integrify","caption":"Förvärv · 20 augusti 2026","preamble":"Xamera Group, delägt av Helix Kapital, har förvärvat samtliga aktier i finska Integrify, en ledande finsk aktör inom teknikfokuserad och hyrköpsbaserad kompetensförsörjning till industri-, försvars- och techsektorn.","body":"Genom förvärvet skapas en nordisk plattform som möjliggör accelererad tillväxt på både den svenska och finska marknaden.\n\nVinge, genom Johan Winnerblad, biträdde Xamera Group i transaktionen.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-xamera-group-vid-forvarv-av-finska-integrify/","date":"2026-08-20","month":8},{"year":2026,"client":"Advania","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Advania vid förvärvet av Cortex Consult A/S","caption":"Förvärv · 18 augusti 2026","preamble":"Vinge har företrätt Advania vid förvärvet av Cortex Consult A/S, ett danskt IT-tjänsteföretag med över 25 års erfarenhet av hanterade IT-tjänster, molnlösningar och cybersäkerhet för kunder inom flera olika branscher.","body":"Cortex Consult tillhandahåller drift och övervakning av IT-infrastruktur, molntjänster, backup-lösningar samt IT-support och har byggt upp en stark position som betrodd IT-partner med fokus på långsiktiga kundrelationer. Genom förvärvet stärker Advania sitt erbjudande inom managed services och tar ett viktigt steg i sin expansion på den danska marknaden.\n\nVinges team bestod av Peter Sundgren, Jonatan Stentorp, Lina Björkman och Filippa Olsson (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-advania-vid-forvarvet-av-cortex-consult-a-s/","date":"2026-08-18","month":8},{"year":2026,"client":"Radonova Laboratories","work":"Förvärv","disciplines":[],"title":"Vinge biträder Radonova Laboratories vid förvärv av norska Skandinavisk Radoninvest","caption":"Förvärv · 14 augusti 2026","preamble":"Radonova Laboratories, ett dotterbolag till Lagercrantz Group, har förvärvat samtliga aktier i norska Skandinavisk Radoninvest. Båda bolagen är verksamma inom området radonmätning.","body":"Vinge, genom Johan Winnerblad, biträdde Radonova Laboratories i transaktionen.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-radonova-laboratories-vid-forvarv-av-norska-skandinavisk-radoninvest/","date":"2026-08-14","month":8},{"year":2026,"client":"KLAR Partners","work":"Avyttring","disciplines":["EU‑ och konkurrensrätt","M&A"],"title":"Vinge har företrätt KLAR Partners i samband med försäljningen av Swoosh Group till Serwent","caption":"Avyttring · 13 augusti 2026","preamble":"Swoosh är en ledande leverantör av tjänster för underjordisk infrastruktur i Sverige. Bolaget erbjuder inspektion, rensning, reparation och underhåll av avloppsrör till kommuner, industriella aktörer och fastighetsägare via 23 arbetsställen runt om i landet. Swoosh sysselsätter idag cirka 450 medarbetare och genererar intäkter om närmare 700 miljoner kronor.","body":"Transaktionen är villkorad av sedvanliga regulatoriska godkännanden och förväntas slutföras under hösten 2026.\n\nVinges team bestod huvudsakligen av Johanna Wiberg, Sara Hill, Sara Hammond och Viktor Ejlertsson (M&A), David Olander (EU, Competition & Regulatory), samt Jasmina Skandari och Ellinore Boström Andersson (Transaction Support).\n\nFör fler detaljer om transaktionen hänvisas till KLAR Partners pressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-klar-partners-i-samband-med-forsaljningen-av-swoosh-group-till-serwent/","date":"2026-08-13","month":8},{"year":2026,"client":"Montrose by Carnegie","work":"Tillstånd","disciplines":["Finansiella tillståndsfrågor","Bank och finans"],"title":"Vinge har biträtt Montrose by Carnegie AB i ansökan om värdepappersrörelsetillstånd","caption":"Tillstånd · 12 augusti 2026","preamble":"Vinge har framgångsrikt biträtt Montrose by Carnegie AB i samband med bolagets ansökan till Finansinspektionen om tillstånd att bedriva värdepappersrörelsetillstånd. Tillståndet meddelades av Finansinspektionen den 2 juli 2026.","body":"Montrose by Carnegie AB är en digital investeringsplattform för handel med värdepapper och en del av DNB Carnegie-koncernen.\n\nVinges team bestod av Nils Unckel, Athina Poulidas Josefsson och Julia Gudmundsson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-montrose-by-carnegie-ab-i-ansokan-om-vardepappersrorelsetillstand/","date":"2026-08-12","month":8},{"year":2026,"client":"Mjällby AIF","work":"Avyttring","disciplines":["Sport, Event, Spel och Media"],"title":"Vinge företräder Mjällby AIF i samband med försäljningen av Elliot Stroud till Hull City AFC","caption":"Avyttring · 10 augusti 2026","preamble":"Vinge har företrätt de regerande allsvenska mästarna Mjällby AIF i samband med deras försäljning av den svenske landslagsspelaren Elliot Stroud till Premier League-laget Hull City AFC.","body":"Vinges team bestod av Johan Cederblad och Mario Saad.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-mjallby-aif-i-samband-med-forsaljningen-av-elliot-stroud-till-hull-city-afc/","date":"2026-08-10","month":8},{"year":2026,"client":"Altor","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","Bank och finans","Regulatoriska tvister","Kommersiella avtal","Immaterialrätt","Arbetsrätt"],"title":"Vinge företräder Altor i budet på Sleep Cycle","caption":"Övrigt · 7 augusti 2026","preamble":"Snark BidCo, ett bolag kontrollerat av Altor Fund V (No. 1) och Altor Fund V (No. 2), lämnade ett offentligt uppköpserbjudande till aktieägarna i Sleep Cycle att överlåta samtliga aktier till Snark BidCo. Aktierna i Sleep Cycle är upptagna till handel på Nasdaq Stockholm. Efter utgången av den förlängda acceptfristen kontrollerar Snark BidCo cirka 79,2 procent av aktiekapitalet och rösterna i Sleep Cycle. Det totala värdet av erbjudandet upgick till cirka 497 miljoner kronor.","body":"Vinges team består huvudsakligen av David Andersson, Maximilian Bengtsson, Elias Kröger, Johannes Ekbom (Kapitalmarknad och publik M&A), Albert Wållgren, Linn Adelwald, Kamyar Najmi, Oliva Altheden (Bank och finans), Marcus Glader, Fredrik Hellström, Joar Lindén (Regulatory), Mathilda Persson, Nicklas Thorgerzon (Kommersiella avtal, IT, och GDPR), Arvid Axelryd, Isabelle Asserståhl (IP) och Sam Seddigh samt Alice Göransson (Arbetsrätt)","href":"https://www.vinge.se/uppdrag/vinge-foretrader-altor-i-budet-pa-sleep-cycle/","date":"2026-08-07","month":8},{"year":2026,"client":"SEB Kort","work":"Samgående","disciplines":["Arbetsrätt","Finansiella tillståndsfrågor","M&A"],"title":"Vinge företräder SEB Kort i samband med gränsöverskridande fusion med AirPlus","caption":"Samgående · 6 augusti 2026","preamble":"Vinge har företrätt SEB Kort i samband med en gränsöverskridande fusion varigenom dotterbolaget AirPlus uppgått i SEB Kort genom absorption.","body":"SEB Kort är ett svenskt bankaktiebolag inom SEB-koncernen som är ledande inom betalkort i Europa. Tillsammans med AirPlus har SEB Kort omkring 1 400 medarbetare och är dessutom ledande när det gäller lösningar för reseadministration i Europa.\n\nVinges team bestod av Matthias Pannier, Josef Groow, Alex Forsberg och Viktor Ejlertsson (M&A), Caroline Krassén, Elias Bohlin och David Flodin (Finansiella tjänster) samt Sam Seddigh och Alice Göransson (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-seb-kort-i-samband-med-gransoverskridande-fusion-med-airplus/","date":"2026-08-06","month":8},{"year":2026,"client":"Altor- och Stena-ägda Gunnebo","work":"Avyttring","disciplines":["M&A","Kommersiella avtal","Immaterialrätt","EU‑ och konkurrensrätt","Bank och finans","Carve-Outs"],"title":"Vinge företräder Altor- och Stena-ägda Gunnebo i samband med försäljning av Gunnebo Entrance Control AB till ASSA Abloy","caption":"Avyttring · 4 augusti 2026","preamble":"Vinge har företrätt Gunnebo i samband med försäljningen av Gunnebo Entrance Control AB till ASSA Abloy.","body":"Gunnebo är en global ledare inom säkerhetslösningar och erbjuder innovativa produkter och tjänster för att skydda och kontrollera flödet av människor genom sina två separata affärsområden Gunnebo Entrance Control och Gunnebo Safe Storage. Försäljningen av Gunnebo Entrance Control AB utgör en viktig milstolpe i Gunnebos strategiska utveckling och efter transaktionens genomförande kommer Gunnebo att fokusera uteslutande på Gunnebo Safe Storage. ASSA Abloy är en global ledare inom accesslösningar och genom förvärvet av Gunnebo Entrance Control AB är planen att stärka ASSA Abloys position på marknaden genom att komplettera kärnverksamheten med ytterligare produkter och lösningar, där Gunnebo Entrance Control AB kommer vara en del av ASSA Abloys division Entrance Systems.\n\nTransaktionen är villkorad av sedvanliga regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Matthias Pannier, Nina Bonnier, Egil Svensson, Josef Groow, Adam Karlsson, Filippa Olsson (M&A), Mathilda Persson, Eva Fredriksson, Katja Häglund och Siri Blomberg (Kommersiella avtal), Arvid Axelryd och Ian Jonsson (Immaterialrätt), Marcus Glader, Fredrik Hellström och Alva Chambert (EU- och konkurrensrätt), Linn Adelwald och William Carlberg Johansson (Bank och finans), Johanna Engström och Caroline Löv (Transaktionsstöd).\n\nLäs Gunnebos pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-altor-och-stena-agda-gunnebo-i-samband-med-forsaljning-av-gunnebo-entrance-control-ab-till-assa-abloy/","date":"2026-08-04","month":8},{"year":2026,"client":"Precise Biometrics","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Precise Biometrics i samband med företrädesemission","caption":"Kapitalanskaffning · 24 juli 2026","preamble":"Vinge företräder Precise Biometrics AB (publ) i samband med en företrädesemission om cirka 110 miljoner kronor. Vinges team består av Christian Lindhé, Michaela Ådén, Agaton Lindgren och Nathalie Wikman.","body":null,"href":"https://www.vinge.se/uppdrag/vinge-foretrader-precise-biometrics-i-samband-med-foretradesemission/","date":"2026-07-24","month":7},{"year":2026,"client":"Summit Partners","work":"Kapitalanskaffning","disciplines":["M&A","FDI","Corporate Commercial"],"title":"Vinge företräder Summit Partners i samband med dess investering på över 1 miljard USD i Keyfactor","caption":"Kapitalanskaffning · 20 juli 2026","preamble":"Vinge har, tillsammans med Kirkland & Ellis, företrätt Summit Partners i samband med en strategisk tillväxtinvestering i Keyfactor, en ledande leverantör av förtroendeinfrastruktur. Investeringen kommer att bidra till att accelerera bolagets globala expansion och tillväxtinitiativ och möjliggöra produktinnovation, geografisk expansion, kompetensförsörjning och strategiska förvärv.","body":"Summit Partners är ett globalt tillväxtinvesteringsbolag som sedan grundandet 1984 har investerat i mer än 550 bolag inom teknik, hälsovård och andra tillväxtsektorer.\n\nTransaktionen är föremål för tillämpliga regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Manon de Cooman, Chris Bastholm och Robert Sande (M&A), Johanna Fjellström (Arbetsrätt), Alva Skott (IP), Madelene Andersson (Fastighet), Nicklas Thorgerzon och Siri Blomberg (Corporate Commercial och IT) samt Fredrik Löwenclou och Victoria Gunnerek (Regulatory).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-summit-partners-i-samband-med-dess-investering-pa-over-1-miljard-usd-i-keyfactor/","date":"2026-07-20","month":7},{"year":2026,"client":"VAROPreem","work":"Förvärv","disciplines":["M&A","EU‑ och konkurrensrätt"],"title":"Vinge har biträtt VAROPreem i samband med förvärvet av Sunpine","caption":"Förvärv · 10 juli 2026","preamble":"Vinge har biträtt VAROPreem i samband med dess förvärv av Sunpine från Sveaskog, Södra Skogsägarna och Lawter.","body":"Sunpine är världens största bioraffinaderi för råtallolja och producerar en högkvalitativ förnybar råvara som används vid tillverkning av avancerade biodrivmedel, däribland hydrerad vegetabilisk olja (HVO) och hållbart flygbränsle (SAF). Det omdöpta bolaget, VAROPreem Sunpine, kommer att bygga vidare på sin världsledande teknik och produktionskapacitet, integrerad med VAROPreems verksamhet för förnybara bränslen i Europa.\n\nVinges team bestod av Samra Tesser, Carl Fredrik Wachtmeister och Ian Linde (M&A) samt Daniel Wendelsson, David Olander, Dagne Sabockis och Lovisa Arpi (Competition & Regulatory).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-varopreem-i-samband-med-forvarvet-av-sunpine/","date":"2026-07-10","month":7},{"year":2026,"client":"Consolid Equity","work":"Övrigt","disciplines":["M&A","Bank och finans","Corporate Commercial","Fastigheter och Entreprenad","Immaterialrätt"],"title":"Vinge har biträtt Consolid Equity i samband med etableringen av Petra Group","caption":"Övrigt · 8 juli 2026","preamble":"Vinge har företrätt Consolid Equity Investment AB (\"Consolid Equity\") vid förvärvet av Ström & Gulliksson, en av Nordens ledande patentbyråer. Förvärvet utgör en del av etableringen av Petra Group, en europeisk plattform med syftet att konsolidera patentbyråer runtom i Europa för att kombinera expertis och resurser inom primärt patent och varumärken. Consolid fungerar som en strategisk samarbetspartner i den nya gruppen.","body":"Petra Group innefattar vid etableringen, utöver Ström & Gulliksson, även de holländska patentbyråerna De Vries & Metman, Knijff Trademark Attorneys och V.O. Patents & Trademarks. Plattformen har etablerats med ambitionen att genom ytterligare förvärv skapa en ledande europeisk aktör inom immaterialrättsliga tjänster.\n\nVinges team bestod huvudsakligen av Johanna Wiberg, Desirée Hagenfeldt, Carl Fredrik Wachtmeister, Johanna Barfoed, Chris Bastholm, Olivia Altheden, Anna Neubüser (M&A), Henrik Ossborn och Nilufer Nouri (Bank & Finans), Siri Blomberg (Corporate Commercial), Hanna Kövamees (Fastighet), Emma Gustavsson (IPR) samt Caroline Löv (transaktionskoordinator).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-consolid-equity-i-samband-med-etableringen-av-petra-group/","date":"2026-07-08","month":7},{"year":2026,"client":"Scandic","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt Scandic med nya kreditfaciliteter om 7,5 miljarder kronor","caption":"Finansiering · 8 juli 2026","preamble":"Vinge har företrätt Scandic Hotels Group AB (publ) i samband med ett kreditfacilitetsavtal om 7 500 000 000 SEK med ett syndikat av banker, arrangerad av DNB Carnegie Investment Bank AB och Nordea Bank Abp, filial i Sverige.","body":"Kreditfaciliteterna syftar till att bl.a. refinansiera existerande skuld och finansiera det planerade förvärvet av Dalata Hotel-koncernen samtidigt som koncernens finansiella flexibilitet stärks. Finansieringen har en löptid på tre år med en option till förlängning på ytterligare två år.\n\nScandic är det största hotellföretaget i Norden med omkring 68 000 hotellrum fördelade på cirka 320 hotell i drift och under utveckling. Scandic är noterat på Nasdaq Stockholm.\n\nVinges team har bestått av Albert Wållgren, Linn Adelwald, Calle Tengwall Pagels och Anna Wisborg.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-scandic-med-nya-kreditfaciliteter-om-7-5-miljarder-kronor/","date":"2026-07-08","month":7},{"year":2026,"client":"Vitamin Well och dess majoritetsägare Cinven","work":"Kapitalanskaffning","disciplines":["M&A","FDI","Bank och finans"],"title":"Vinge har biträtt Vitamin Well och dess majoritetsägare Cinven, Bridgepoint och grundarna vid Vitamin Wells samgående med EMPWR","caption":"Kapitalanskaffning · 3 juli 2026","preamble":"Vinge har biträtt Vitamin Well och dess majoritetsägare Cinven, grundarna av Vitamin Well samt Bridgepoint i samband med Vitamin Wells förvärv av EMPWR Nutrition Group från majoritetssäljaren Waterland Private Equity Investments.","body":"EMPWR Nutrition Group är baserat i Belgien och producerar och utvecklar (\"CDMO\") nutritional bars, med fyra produktionssanläggningar i Kroatien, Nederländerna, USA och Kanada och över 1 500 anställda och fler än 100 kunder globalt. EMPWR Nutrition Group är en viktig tillverkningspartner för Vitamin Well och producerar hela sortimentet av Barebells-bars för den globala marknaden. Vitamin Well grundades år 2006 och har sitt huvudkontor i Stockholm. koncernen är en snabbväxande aktör inom funktionella livsmedel och drycker som erbjuder premiumprodukter för konsumenter, med cirka 750 anställda och produkter som säljs på över 50 marknader. Som en del av transaktionen kommer Waterland Private Equity Investments att återinvestera och bli minoritetsägare i Vitamin Well.\n\nTransaktionen är villkorad av sedvanliga regulatoriska godkännanden.\n\nVinges team bestod av Daniel Rosvall, Kim Bergman Aldevinge och Michella Said (M&A), Sebastian Örndahl och Alva Chambert (Konkurrensrätt och FDI), Albert Wållgren, Karl-Gustaw Tobola och Nilufer Nouri (Bank och Finans) samt Emy Rydén (Koordinator för transaktionsstöd). Vidare bistod Covington som lokalt ombud i förhållande till USA, NautaDutilh bistod som lokalt ombud i förhållande till Nederländerna och Belgien, Gowling bistod som lokalt ombud i förhållande till Kanada och Divjak, Topic, Bahtijarevic & Krka bistod som lokalt ombud i förhållande till Kroatien.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-vitamin-well-och-dess-majoritetsagare-cinven-bridgepoint-och-grundarna-vid-vitamin-wells-samgaende-med-empwr/","date":"2026-07-03","month":7},{"year":2026,"client":"Morrow Bank","work":"Kapitalanskaffning","disciplines":["Bank och finans","Rekonstruktioner och obestånd"],"title":"Vinge har biträtt Morrow Bank i samband med dess emissioner av primärkapitalinstrument (AT1) och supplementärkapitalinstrument (Tier 2)","caption":"Kapitalanskaffning · 3 juli 2026","preamble":"Emissionerna omfattade eviga AT1-obligationer om NOK 300 miljoner med en rörlig kupong om 3-månaders NIBOR + 425 baspunkter och första inlösenrätt 2031 samt efterställda Tier 2-obligationer om SEK 200 miljoner med en rörlig kupong om 3-månaders STIBOR + 325 baspunkter och första inlösenrätt 2031. Obligationerna avses tas upp till handel på Nasdaq Stockholm.","body":"Transaktionerna genomfördes som en del av finansieringen av Morrow Banks förvärv av MedMera Bank AB.\n\nNordea Bank Abp agerade sole manager i samband med obligationsemissionerna.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda, Julia Gudmundsson, Nilufer Nouri och Pontus Tegström","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-morrow-bank-i-samband-med-dess-emissioner-av-primarkapitalinstrument-at1-och-supplementarkapitalinstrument-tier-2/","date":"2026-07-03","month":7},{"year":2026,"client":"GreenChem","work":"Förvärv","disciplines":["M&A","Immaterialrätt","Arbetsrätt","Kommersiella avtal","Miljörätt","Fastigheter och Entreprenad","Regulatoriska tvister"],"title":"Vinge företräder GreenChem vid förvärvet av Arom-dekor Kemi","caption":"Förvärv · 1 juli 2026","preamble":"Vinge har biträtt GreenChem Holding B.V., en ledande europeisk leverantör av kemiska produkter och lösningar, i samband med bolagets förvärv av Arom-dekor Kemi AB från Vilokan AB.","body":"Arom-dekor Kemi är en väletablerad aktör inom kemikaliedistribution i Norden. Genom förvärvet stärker GreenChem sin närvaro på den nordiska marknaden och breddar sitt befintliga erbjudande inom hållbara kemiska produkter.\n\nVinges team bestod huvudsakligen av Anders Strid, Petronella Hallberg och Beatrice Gustafsson (M&A), Kim Larsson (IP), Annie Einarsson (arbetsrätt), Ivar Johannson och Aleksander Bajic (kommersiella avtal), Stina Larsson (miljörätt), Adnan Durakovic (fastighet) samt Fredrik Löwenclou (regulatoriska frågor).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-greenchem-vid-forvarvet-av-arom-dekor-kemi/","date":"2026-07-01","month":7},{"year":2026,"client":"Wihlborgs Fastigheter","work":"Förvärv","disciplines":["Bank och finans"],"title":"Vinge företräder Wihlborgs Fastigheter i samband med finansieringen av fastighetsförvärv värde 13,3 miljarder kronor","caption":"Förvärv · 29 juni 2026","preamble":"Vinge företräder Wihlborgs Fastigheter AB (publ) i samband med finansieringen av förvärvet av Castellums samlade fastighetsbestånd i Malmö, Lund och Helsingborg. Finansieringen har säkerställts via Danske Bank, SEB och Swedbank.","body":"Förvärvet genomförs som en verksamhetsaffär och omfattar 95 fastigheter och 635 000 kvadratmeter uthyrningsbar area till ett underliggande fastighetsvärde om 13,3 miljarder kronor. Genom förvärvet kompletterar Wihlborgs sitt bestånd i Öresundsregionen och skapar förutsättningar för fortsatt långsiktig tillväxt.\n\nWihlborgs Fastigheter AB (publ) är ett fastighetsbolag med fokus på kommersiella fastigheter i Öresundsregionen och är noterat på Nasdaq Stockholm, Large Cap. Förvärvet är villkorat av godkännande från Konkurrensverket och Inspektionen för strategiska produkter (ISP), med planerat tillträde den 1 oktober.\n\nVinges team bestod av Henrik Ossborn och Jolinn Uhlin.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-wihlborgs-fastigheter-i-samband-med-finansieringen-av-fastighetsforvarv-varde-13-3-miljarder-kronor/","date":"2026-06-29","month":6},{"year":2026,"client":"Ambea","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","M&A","Bank och finans","Kommersiella avtal","EU‑ och konkurrensrätt","FDI","Offentlig upphandling","Företagsbeskattning","Corporate Crime & Compliance"],"title":"Vinge biträder Ambea i budet på Humana","caption":"Övrigt · 29 juni 2026","preamble":"Ambea AB (publ) har lämnat ett offentligt uppköpserbjudande till aktieägarna i Humana AB. Erbjudandet värderar samtliga aktier i Humana till cirka 2,96 miljarder kronor. Vederlaget består av en kombination av aktier, kontanter och en CVR (contingent value right).","body":"Vinges team består huvudsakligen av Sofie Bjärtun, Linnéa Dolk, Anna Svensson, Lorin Arabi och Samuel Rapp (Kapitalmarknad och publik M&A), Christina Kokko, Samra Tesser, Elsie Nassar och Hedvig Merkel (M&A), Albert Wållgren, Josefine Lanker, Kamyar Najmi och Sara Eirefors (Bank och finans), Eva Fredrikson, Christoffer Nordin, Nicklas Thorgerzon och Mario Saad (Kommersiella avtal), Marcus Glader, Jakob Rosini Jeanrond, Martin Bergqvist, Daniel Wendelsson och Kristoffer Sällfors (Konkurrensrätt, offentlig upphandling och FDI), Maria Schultzberg, Victor Ericsson, Erik Kochbati, Marcus Svärd, Elsa Kalén och Axel Åshuvud (Skatt), Vilma Simonius (Compliance) samt Alice Vångell (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ambea-i-budet-pa-humana/","date":"2026-06-29","month":6},{"year":2026,"client":"Gamma Waves","work":"Kapitalanskaffning","disciplines":["M&A","Immaterialrätt","Kommersiella avtal","Arbetsrätt"],"title":"Vinge har biträtt Gamma Waves i Sportways finansieringsrunda om 20 miljoner euro","caption":"Kapitalanskaffning · 24 juni 2026","preamble":"Vinge har agerat juridisk rådgivare till Gamma Waves i samband med Sportways finansieringsrunda om 20 miljoner euro. Rundan leddes av Gamma Waves, tillsammans med fortsatt deltagande från befintliga aktieägare, och värderar Sportway till cirka 92 miljoner euro (omkring 1 miljard kronor) post-money.","body":"Sportway grundades 2017 och är ett teknik- och mediebolag som genom AI och automatisering gör det möjligt för idrottsförbund, ligor, klubbar och mediebolag att producera, distribuera och kommersialisera direktsänt sportinnehåll i stor skala. Bolaget är i dagsläget verksamt i fler än 20 länder, samarbetar med över 70 idrottsförbund och ligor och producerar mer än 250 000 direktsända sportevenemang varje år. Kapitaltillskottet ger Sportway ytterligare resurser för att accelerera internationell expansion, produktutveckling och strategiska förvärv.\n\nGamma Waves är en investeringsplattform med permanent kapital som verkar i skärningspunkten mellan sport-IP och sportteknik. Gamma Waves team förenar framgångsrika ägare, operatörer och idrottare från den globala sportvärlden med erfarna tillväxt- och teknikinvesterare.\n\nVinges team bestod huvudsakligen av Johan Larsson och Gustav Wahlberg (M&A Corporate), Ian Jonsson (Immaterialrätt), Ida Petterson (Arbetsrätt) och Mario Saad (Corporate Commercial).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-gamma-waves-i-sportways-finansieringsrunda-om-20-miljoner-euro/","date":"2026-06-24","month":6},{"year":2026,"client":"Spotlight Group","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","EU‑ och konkurrensrätt"],"title":"Vinge biträder Spotlight Group i samband med budet från Kriptown","caption":"Övrigt · 17 juni 2026","preamble":"Vinge biträder Spotlight Group AB (publ) i samband med att Kriptown SAS har lämnat ett offentligt kontant uppköpserbjudande till aktieägarna i Spotlight Group","body":"Erbjudandet uppgår till 33 kronor per aktie vilket motsvarar en premie om cirka 94 procent i förhållande till stängningskursen för Spotlight Groups aktier på Spotlight Stock Market sista hadelsdagen före offentliggörandet av erbjudandet. Aktieägare som kontrollerar cirka 69 procent av samtliga aktier och röster i Spotlight Group har ovillkorligen åtagit sig att acceptera erbjudandet. Spotlights oberoende budkommitté har rekommenderat aktieägarna att acceptera erbjudandet.\n\nVinges team består av Anders Strid och Edin Agic (Capital Markets) samt Anna Palmérus och Fredrik Löwenclou (EU/Competition & Regulatory).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-spotlight-group-i-samband-med-budet-fran-kriptown/","date":"2026-06-17","month":6},{"year":2026,"client":"EQT IX","work":"Avyttring","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt EQT IX i samband med avyttring av dess innehav i Beijer Ref AB (publ)","caption":"Avyttring · 16 juni 2026","preamble":"Vinge har biträtt EQT IX (”EQT”) i samband med nedförsäljning av samtliga sina återstående aktier av serie B i Beijer Ref AB (publ) i en så kallad accelererad bookbuilding-process genomförd den 15 juni 2026.","body":"Totalt placerades 30,7 miljoner aktier av serie B till ett pris om 132 kronor per aktie, motsvarande ett sammanlagt värde om cirka 4,1 miljarder kronor.\n\nVinges team bestod av Sofie Bjärtun, Linnéa Dolk och Izabella Barisa.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-eqt-ix-i-samband-med-avyttring-av-dess-innehav-i-beijer-ref-ab-publ/","date":"2026-06-16","month":6},{"year":2026,"client":"Accent Equity VI och minoritetsägarna","work":"Avyttring","disciplines":["M&A","FDI","Arbetsrätt"],"title":"Vinge har biträtt Accent Equity VI och minoritetsägarna vid deras försäljning av Malte Månson","caption":"Avyttring · 8 juni 2026","preamble":"Vinge har biträtt Accent Equity VI och minoritetsägarna vid deras försäljning av Malte Månson till Citira, en europeisk aktör inom däckhantering och portföljbolag till Norvestor. Malte Månson är en fristående aktör inom service och reparationer av kommersiella fordon med ett verkstadsnätverk som omfattar 28 platser i Sverige och är auktoriserade av märken såsom MAN, DAF, IVECO, Mercedes-Benz, Setra, VDL och EVO. Malte Månson har en omsättning om 800 miljoner kronor och över 300 anställda.","body":"Transaktionen är föremål för sedvanliga regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Kim Bergman Aldevinge och Matilda Hamner (M&A/Riskkapital), Fredrik Hellström och Sara Stålebring (Konkurrensrätt och FDI), Sam Seddigh och Linn Aho (Arbetsrätt) och Caroline Löv (Transaction Support Coordinator).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-accent-equity-vi-och-minoritetsagarna-vid-deras-forsaljning-av-malte-manson/","date":"2026-06-08","month":6},{"year":2026,"client":"InArea","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge biträder InArea vid ingående av kreditavtal om 450 miljoner SEK med SEB","caption":"Finansiering · 3 juni 2026","preamble":"InAreas nya kreditavtal består av ett term loan och en revolverande kreditfacilitet, vilka ersätter bolagets befintliga kreditfaciliteter. Kreditavtalet innehåller även en möjlighet att utöka låneramen med en s.k. incremental facility om upp till 200 miljoner SEK.","body":"InArea Group är en svensk golvkoncern bestående av lokalt marknadsledande och entreprenörsdrivna företag inom golvläggning, plattsättning och avjämning. Med en samlad årsomsättning på cirka 3 miljarder SEK och över tusen medarbetare är InArea Group störst i Sverige inom sitt segment och har även en stark närvaro i Finland och Norge. Koncernen levererar kvalitativa golventreprenader till en bred och professionell kundkrets i bygg- och fastighetssektorn, och bedriver ett aktivt hållbarhetsarbete med socialt, miljömässigt och ekonomiskt ansvarstagande.\n\nVinges team bestod av Oscar Bengtsson Kindgren och Nicolas Ek. Christian Lindhé är klientansvarig delägare.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-inarea-vid-ingaende-av-kreditavtal-om-450-miljoner-sek-med-seb/","date":"2026-06-03","month":6},{"year":2026,"client":"Arrangörsbankerna","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt arrangörsbankerna i samband med St1 Biokrafts lånefinansiering om EUR 260 miljoner","caption":"Finansiering · 3 juni 2026","preamble":"Vinge har biträtt arrangörsbankerna, ING Bank N.V., ABN AMRO Bank N.V., DNB Bank ASA, Nordea Bank Abp, OP Corporate Bank plc, Coöperatieve Rabobank U.A., SpareBank 1 Sør-Norge ASA och Swedbank AB, i samband med St1 Biokraft AB:s finansiering om EUR 260 miljoner.","body":"St1 Biokraft ägs av HitecVision och St1 och hanterar hela värdekedjan för biogas i Norden, från inköp av råvara till produktion, försäljning och distribution. Bolaget har en produktionskapacitet om över 550 GWh och ett mål att producera 3 TWh biometan och uppnå 6 TWh i distribution år 2030, med fokus på tunga transporter, sjöfart och industriella applikationer. Finansieringen syftar till att stödja den fortsatta expansionen av bolagets integrerade nordiska biogasplattform samt till att refinansiera befintlig skuldsättning.\n\nING Bank N.V. agerar som facilitetsagent och säkerhetsagent.\n\nVinges team bestod huvudsakligen av Henrik Ossborn, Josefine Edström, Karl-Gustaw Tobola och Olivia Carlsten (Finansiering), samt Malin Ohlin och Mario Saad (Corporate Commercial).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-arrangorsbankerna-i-samband-med-st1-biokrafts-lanefinansiering-om-eur-260-miljoner/","date":"2026-06-03","month":6},{"year":2026,"client":"Trinax Group","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Bank och finans","Immaterialrätt","Corporate Commercial","Fastigheter och Entreprenad","Miljörätt"],"title":"Vinge biträder Trinax Group vid förvärv av AddMobile och Scudo Solutions","caption":"Förvärv · 3 juni 2026","preamble":"Trinax Group har förvärvat svenska AddMobile och finska Scudo Solutions, vilka är verksamma inom mjukvara för arbetsorderhantering respektive projekt- och kostnadshantering. De två förvärven breddar gruppens erbjudande genom hela värdekedjan, från beställarens budget och kalkyl till entreprenörens fältarbete, samtidigt som den geografiska närvaron i Finland stärks.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Emma Lundberg (M&A), Louisa Fagarasan (Employment & Benefits), Jolinn Uhlin (Corporate Banking & Finance), Emma Gustavsson (IP), Katja Häglund och Avidh Tajik (Corporate Commercial) samt Amanda Strömblad (Real Estate & Environment).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-trinax-group-vid-forvarv-av-addmobile-och-scudo-solutions/","date":"2026-06-03","month":6},{"year":2026,"client":"Axcel","work":"Kapitalanskaffning","disciplines":["M&A","Corporate Commercial","FDI"],"title":"Vinge företräder Axcel i samband med investeringen i Sanviva","caption":"Kapitalanskaffning · 3 juni 2026","preamble":"Vinge har företrätt det nordiska riskkapitalbolaget Axcel i samband med etableringen av Sanviva, ett nytt europeiskt distributionsnätverk för medicintekniska produkter.","body":"Sanviva samlar distributörerna Apodan, PartnerMed, AllweCare och XboXLab som är verksamma i Norden och Benelux med en produktportfölj som innefattar bland annat sårvård, stomivård och in vitro-diagnostik. Sanviva har för närvarande cirka 60 anställda i Danmark, Sverige, Norge, Finland, Belgien och Nederländerna.\n\nInvesteringen i Sanviva gjordes genom Axcel Elevate I, Axcels fond för små och medelstora bolag med fokus på teknik, företagstjänster samt hälso- och sjukvård\n\nVinges team bestod av Christina Kokko, Egil Svensson, Ida Appelgren, Manon de Cooman och Lina Björkman (M&A), Christoffer Nordin (Corporate Commercial), Dagne Sabockis och Julia Rydin (FDI) och Filippa Bergkvist (Transaction Support Coordinator).\n\nLäs klientens pressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-i-samband-med-investeringen-i-sanviva/","date":"2026-06-03","month":6},{"year":2026,"client":"Platzer","work":"Förvärv","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge företräder Platzer vid förvärv av logistikfastighet i Sörred Logistikpark","caption":"Förvärv · 2 juni 2026","preamble":"Vinge har företrätt Platzer vid förvärv av fastigheten Sörred 8:15 i Sörred Logistikpark på Hisingen i Göteborg. Förvärvet genomförs enligt den förvärvsoption som Platzer har i det gemensamma JV-bolaget med Catena, vilken ger förtur att förvärva färdigställda projekt till marknadsvärde. Köpeskillingen utgår från ett underliggande fastighetsvärde om 570 mkr med avdrag för latent skatt. Tillträde beräknas ske den 1 juli 2026.","body":"Fastigheten är en modern logistikprodukt omfattande cirka 29 700 kvm uthyrbar area och är fullt uthyrd till Speed Group på ett tioårigt hyresavtal. Byggnaden avses att miljöcertifieras enligt BREEAM Excellent.\n\nVinges team bestod huvudsakligen av Olof Jisland, Kristoffer Larson och Simon Gille-Johnson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-platzer-vid-forvarv-av-logistikfastighet-i-sorred-logistikpark/","date":"2026-06-02","month":6},{"year":2026,"client":"Ägarna","work":"Övrigt","disciplines":["M&A"],"title":"Vinge biträder ägarna vid ägarförändring i Norteam","caption":"Övrigt · 2 juni 2026","preamble":"Evolver Equity blir ny huvudägare i Norteam AB, en snabbväxande svensk specialist inom Microsoft Cloud. Medgrundaren Martin Norström återinvesterar i den nya bolagssgruppen och intar rollen som koncern-VD. Investeringen markerar starten på en nordisk tillväxtresa med ambitionen att bygga en ledande leverantör av Microsoft-baserade IT-tjänster för små och medelstora företag – och att nå 1 miljard kronor i intäkter inom 3–5 år.","body":"Vinge, genom Johan Winnerblad och Gustav Wahlberg, biträder Norteams ägare i transaktionen.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-agarna-vid-agarforandring-i-norteam/","date":"2026-06-02","month":6},{"year":2026,"client":"TSG","work":"Förvärv","disciplines":["M&A","Corporate Commercial","Bank och finans","EU‑ och konkurrensrätt","Arbetsrätt","Fastigheter och Entreprenad","Miljörätt","Immaterialrätt"],"title":"Vinge biträder TSG vid förvärv av Processkontroll GT","caption":"Förvärv · 1 juni 2026","preamble":"TSG, en europeisk ledare inom tekniska tjänster för hållbara mobilitetslösningar och kritisk energiinfrastruktur, har förvärvat Procsskontroll GT, en specialist på infrastruktur för komprimerad och flytande gas.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Egil Svensson och Emma Lundberg (M&A), Mario Saad, Katja Häglund och Dante Lalouni (Corporate Commercial), Gabriel Chabo (Corporate Banking & Finance), Sara Stålebring och Hilda Ivarson (EU, Competition & Regulatory), William Karo Persson (Employment & Benefits), Stina Larsson och Sara Franson (Real Estate & Environment), Emma Gustavsson (IP) samt Julia Ulander Kull (Transaction Support Coordinator).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-tsg-vid-forvarv-av-processkontroll-gt/","date":"2026-06-01","month":6},{"year":2026,"client":"Mirova","work":"Finansiering","disciplines":["M&A","Miljörätt","Bank och finans"],"title":"Vinge har biträtt Mirova vid finansieringen av vindkraftsparkerna Fågelås, Dållebo och Boarp","caption":"Finansiering · 1 juni 2026","preamble":"Finansieringen, som tillhandahållits av Danske Bank och La Banque Postale, består av ett flertal faciliteter om sammanlagt cirka 100 MEUR, innefattande bland annat ett långfristigt amorterande lån och garantifaciliteter.","body":"Mirova, ett dotterbolag till Natixis Investment Managers som fokuserar på hållbara investeringar, förvärvade vindkraftsportföljen från Eolus i december 2025. Tillgångarna omfattas av ett 15-årigt elhandelsavtal (PPA) som täcker en väsentlig del av den årliga elproduktionen.\n\nVinges team bestod av Christoffer Thalin, Tilda Hall, Oscar Bengtsson och Irma Softic.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-mirova-vid-finansieringen-av-vindkraftsparkerna-fagelas-dallebo-och-boarp/","date":"2026-06-01","month":6},{"year":2026,"client":"Nordion Energi","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Nordion Energi AB i samband med förvärv av aktier i Kalmar Energi","caption":"Förvärv · 29 maj 2026","preamble":"Nordion Energi förvärvar hela E.ON Sverige ABs innehav i Kalmar Energi och i samband med tillträdet avyttra Kalmar Energis elhandelsverksamhet till Siljansvik AB (publ).","body":"Nordion Energi AB kommer att tillsammans med Kalmar Kommunbolag AB (50/50) äga Kalmar Energi Holding AB som tillsammans med dess dotterbolag bedriver verksamhet inom elnät, fjärrvärme och fiber. Elhandelsverksamheten, som bedrivs i dotterbolaget Kalmar Energi Försäljning AB, kommer att avyttras till Siljansvik AB (publ). Tillträde av transaktionerna förväntas under sommaren 2026 efter erhållande av relevanta myndighetsgodkännanden samt beslut i kommunfullmäktige.\n\nVinges team har huvudsakligen bestått av Christoffer Thalin, Niklas Törnell, Lisa Bourghardt, Henrik Borna, Cecilia Cronqvist, Agaton Lindgren, Oskar Bengtsson Kindgren, Jonatan Karlsson, Joar Lindén, Markus Hedbys, Irma Softic, Johan Severinsson och Agnes Tell.\n\nLäs klientens pressmeddelanden här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-nordion-energi-ab-i-samband-med-forvarv-av-aktier-i-kalmar-energi/","date":"2026-05-29","month":5},{"year":2026,"client":"Latour","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder Latour vid aktieförsäljningar i ASSA ABLOY och Securitas om 2,5 miljarder SEK i vardera bolag","caption":"Avyttring · 27 maj 2026","preamble":"Vinge har biträtt Investmentaktiebolaget Latour (publ) i samband med försäljningen av delar av deras aktieinnehav i ASSA ABLOY och Securitas till ett totalt värde om 5 miljarder kronor.","body":"Aktierna har sålts till svenska och internationella institutionella investerare genom två accelererade bookbuilding-processer arrangerade av SEB och J.P. Morgan. Latour kvarstår som huvudägare och största aktieägare i såväl ASSA ABLOY som Securitas. Genom försäljningarna skapar Latour ytterligare förutsättningar att fortsätta investera i sin helägda industrirörelse.\n\nVinges team har bestått av Anders Strid och Edin Agic.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-latour-vid-aktieforsaljningar-i-assa-abloy-och-securitas-om-2-5-miljarder-sek-i-vardera-bolag/","date":"2026-05-27","month":5},{"year":2026,"client":"Hybridge Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Hybridge Group vid förvärv av NESC","caption":"Förvärv · 27 maj 2026","preamble":"Hybridge Group och konsultföretaget NESC går samman. Genom samgåendet stärker Hybridge Group sitt erbjudande inom prefabricerade stomlösningar.","body":"Vinge, genom Johan Winnerblad, biträder Hybridge Group i förvärvet\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-hybridge-group-vid-forvarv-av-nesc/","date":"2026-05-27","month":5},{"year":2026,"client":"Natur & Kultur","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","IT, Telekom och Outsourcing","GDPR","Arbetsrätt","Immaterialrätt"],"title":"Vinge företräder Natur & Kultur i samband med förvärvet av Majema","caption":"Förvärv · 27 maj 2026","preamble":"Natur & Kultur har förvärvat 80 procent av aktierna i läromedelsförlaget Majema. Förvärvet är ett strategiskt och långsiktigt steg i Natur & Kulturs satsning på läromedel.","body":"Natur & Kulturs och Majemas produktportföljer kompletterar varandra väl, vilket innebär goda möjligheter till värdefullt erfarenhetsutbyte. En stark och lönsam läromedelsverksamhet skapar i sin tur bättre förutsättningar för Natur & Kultur att genom priser, stipendier och stöd främja bildning, kultur och humanistiska värden.\n\nVinges team bestod i huvudsak av Maria Dahlin Kolvik, Viktor Ramhult, Sofia Sallnäs, Hedvig Merkel och Robert Sande (M&A), Christoffer Nordin, Malin Dejke och Katja Häglund (Kommersiella avtal, IT och GDPR), William Karo Persson och Ida Pettersson (Arbetsrätt), David Olander och Hilda Ivarsson (UDI), Arvid Axelryd och Melinda Oldenburg (Immaterialrätt) och Johanna Engström (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-natur-kultur-i-samband-med-forvarvet-av-majema/","date":"2026-05-27","month":5},{"year":2026,"client":"HealthCap","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder HealthCap vid investering i Neobiomics","caption":"Kapitalanskaffning · 22 maj 2026","preamble":"HealthCap investerar i Neobiomics AB, som utvecklar produkter inom neonatalområdet. Neobiomics främsta produkt, Proprems, är ett probiotiskt kosttillskott utvecklat för barn som fötts för tidigt.","body":"Vinges team bestod av Johan Winnerblad och Mana Sohrabi.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-healthcap-vid-investering-i-neobiomics/","date":"2026-05-22","month":5},{"year":2026,"client":"Sveafastigheter","work":"Samgående","disciplines":["Kapitalmarknad och publik M&A","Bank och finans","M&A","Fastigheter och Entreprenad","FDI","Arbetsrätt"],"title":"Vinge företräder Sveafastigheter i dess fusion med KlaraBo","caption":"Samgående · 22 maj 2026","preamble":"Vinge företräder Sveafastigheter AB (publ) i dess fusion med KlaraBo Sverige AB.","body":"I samband med fusionen förvärvar KlaraBo en fastighetsportfölj från SBB omfattande totalt cirka 4 100 lägenheter. Genom transaktionen skapas ett större bostadsfastighetsbolag med cirka 26 500 lägenheter och med ett fastighetsbestånd om cirka 47 miljarder kronor, vilket gör det sammanslagna bolaget mer än dubbelt så stort mätt i fastighetsvärde jämfört med det näst största noterade bostadsfastighetsbolaget på Nasdaq Stockholm.\n\nVinges team bestod huvudsakligen av Rikard Lindahl, Joel Magnusson, Anna Svensson, Elias Kröger och Nora Karlsson (Kapitalmarknad och publik M&A), Mikael Ståhl, Lionardo Ojeda, Ida Redander och William Carlberg Johansson (Bank och finans), Nina Bonnier, Alex Forsberg och Lina Björkman (M&A), Kristoffer Larson och Madelene Andersson (Fastighet), Joar Lindén och Emil Bobovac (Konkurrensrätt och FDI), Sam Seddigh och William Karo Persson (Arbetsrätt), samt Emy Rydén (Transaction Support Senior Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-sveafastigheter-i-dess-fusion-med-klarabo/","date":"2026-05-22","month":5},{"year":2026,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Lagercrantz Group vid förvärv av Stalon","caption":"Förvärv · 21 maj 2026","preamble":"Lagercrantz Group Aktiebolag har förvärvat 88% av aktierna i Stalon AB, en svensk tillverkare av ljuddämpare för jaktvapen. Bolaget är baserat i Stalon utanför Vilhelmina, där bolaget bedriver utveckling och produktion i egna lokaler.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Sara Hammond, Christoffer Nordin, Dennis Hultman, Linn Aho, Wilma Hellman och Sara Stålebring.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-vid-forvarv-av-stalon/","date":"2026-05-21","month":5},{"year":2026,"client":"PPI Public Property Invest","work":"Börsnotering","disciplines":["Kapitalmarknad och publik M&A","Bank och finans","Fastigheter och Entreprenad","GDPR","IT, Telekom och Outsourcing","Arbetsrätt","Företagsbeskattning","EU‑ och konkurrensrätt","Regulatoriska tvister"],"title":"Vinge biträder PPI Public Property Invest AB (publ) i samband med gränsöverskridande fusion och notering på Nasdaq Stockholm och Euronext Oslo Børs","caption":"Börsnotering · 20 maj 2026","preamble":"Vinge har företrätt PPI Public Property Invest AB (publ) (”PPI”) i samband med dess notering på Nasdaq Stockholm och sekundärnotering på Euronext Oslo Børs. Noteringen genomförs genom en gränsöverskridande fusion varigenom PPI övertar Public Property Invest ASA, vars aktier tidigare var noterade på Euronext Oslo Børs.","body":"PPI är en svensk fastighetskoncern med en långsiktig strategi att äga, förvalta och utveckla samhällsfastigheter i Norden på ett hållbart sätt. Portföljen består huvudsakligen av samhällsfastigheter med hyresgäster inom den offentliga sektorn, centralt belägna i större städer i Sverige, Norge, Finland och Danmark. Fastigheterna inrymmer verksamheter av väsentlig betydelse för samhället. Per den 31 december 2025 ägde och förvaltade PPI cirka 2,2 miljoner kvadratmeter fördelat på 850 fastigheter med ett uppskattat bruttovärde om cirka 53 miljarder norska kronor.\n\nVinges team bestod huvudsakligen av Jesper Schönbeck, Rikard Lindahl, Joel Magnusson, Lorin Arabi, Maximilian Bengtsson, William Söder och Vilma Henricsson (Kapitalmarknad och publik M&A), Mikael Ståhl, Kamyar Najmi och Olivia Altheden (Bank och finans), Niclas Winnberg, Kristoffer Larson, Madelene Andersson, Amanda Strömblad, Sara Franson och Wilma Hellman (Fastighet), Niclas Lindblom (Entreprenad), Nicklas Thorgerzon, Elis Allmark och Katja Hägglund (IT/GDPR), Victor Ericsson, Elsa Kalén, Marcus Svärd och Isabell Bitar (Skatt), Sam Seddigh, Emil Lindwall och Agnes Pigg (Arbetsrätt), David Olander (EU- och konkurrensrätt), Vilma Simonius (Regelefterlevnad), Diana Kanold (Paralegal), Gabriella Balbo (Transaction Support Senior Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ppi-public-property-invest-ab-publ-i-samband-med-gransoverskridande-fusion-och-notering-pa-nasdaq-stockholm-och-euronext-oslo-bors/","date":"2026-05-20","month":5},{"year":2026,"client":"Triton","work":"Avyttring","disciplines":["M&A","Kommersiella avtal","IT, Telekom och Outsourcing","Bank och finans","Arbetsrätt","Immaterialrätt","Regulatoriska tvister"],"title":"Vinge företräder Triton vid försäljning av Aleris","caption":"Avyttring · 18 maj 2026","preamble":"Vinge har företrätt Triton i samband med försäljningen av Aleris till Mehiläinen Group.","body":"Aleris, med huvudkontor i Stockholm, är en skandinavisk vårdgivare specialiserad på högkvalitativ specialistvård och bedriver verksamhet vid omkring 100 enheter i Sverige, Norge och Danmark, med cirka 5 300 medarbetare. Aleris hanterar årligen cirka 3,8 miljoner patientbesök inom planerad kirurgi, psykisk hälsa och medicinsk diagnostik. Triton förvärvade Aleris 2019 och har sedan dess utvecklat bolaget till en fokuserad specialistvårdsplattform med stärkt klinisk kvalitet, kortare väntetider och investeringar i digital infrastruktur. Försäljningen till Mehiläinen Group återspeglar nästa steg i Aleris utveckling och bygger på bolagens gemensamma ambition att vidareutveckla specialistvård, digitala tjänster och klinisk kvalitet i de nordiska marknaderna.\n\nTransaktionen är föremål för tillämpliga regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Samra Tesser, Kim Bergman, Johanna Barfoed, Maximilian Bengtsson, Chris Bastholm och Sara Eirefors (M&A), Mario Saad, Siri Blomberg, och Filippa Eriksson (Corporate Commercial och IT), Julia Gudmundsson (Bank och finans), Agnes Pigg (Arbetsrätt), Vilma Simonius, (IP), David Olander (Regulatory), samt Emy Rydén (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-triton-vid-forsaljning-av-aleris/","date":"2026-05-18","month":5},{"year":2026,"client":"L5 Navigation","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder L5 Navigation vid förvärv av Lundaman Instrument","caption":"Förvärv · 13 maj 2026","preamble":"L5 Navigation Systems AB har förvärvat aktierna i Lundaman Instrument AB. Lundaman utvecklar och levererar vågsystem för hjullastare och truckar med fokus på entreprenad, återvinning, industri och materialhantering.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Alva Thörn, Emelie Liljeblad, Linn Aho, Felicia Sandén och Ian Jonsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-l5-navigation-vid-forvarv-av-lundaman-instrument/","date":"2026-05-13","month":5},{"year":2026,"client":"Aonic","work":"Obligationsemission","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge biträder Aonic vid emission av ytterligare seniora säkerställda obligationer om EUR 25 miljoner","caption":"Obligationsemission · 12 maj 2026","preamble":"Vinge har biträtt Aonic AB (publ) i samband med emissionen av ytterligare seniora säkerställda obligationer om EUR 25 miljoner, samt parallellt skriftligt förfarande för ökning av ramverket för obligationerna till EUR 150 miljoner.","body":"Obligationerna har emitterats under bolagets befintliga seniora säkerställda ramverk med rörlig ränta. Emissionslikviden kommer att användas för att finansiera förvärvet av ett europeiskt forskningsteknologibolag i syfte att expandera bolagets mobil- och webbaserade belöningsplattformar. Aonic driver proprietära plattformar för användarförvärv som används av många av världens största mobilspelsutvecklare, samt utvecklar och publicerar ett brett utbud av egna multiplattformsspel.\n\nVinges team bestod av Albert Wållgren, Arvid Weimers, William Carlberg Johansson och Sara Eirefors.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-aonic-vid-emission-av-ytterligare-seniora-sakerstallda-obligationer-om-eur-25-miljoner/","date":"2026-05-12","month":5},{"year":2026,"client":"Consolid Equity och övriga säljare","work":"Avyttring","disciplines":["M&A","EU‑ och konkurrensrätt","Bank och finans"],"title":"Vinge har biträtt Consolid Equity och övriga säljare vid försäljningen av Sertion till Altor","caption":"Avyttring · 11 maj 2026","preamble":"Vinge har biträtt Consolid Equity och övriga säljare vid försäljningen av Sertion-koncernen till Altor. I samband med transaktionen kommer entreprenörer och ledning att återinvestera och kvarstå som nyckelägare, i partnerskap med Altor för att accelerera koncernens nästa tillväxtfas på befintliga marknader och i nya geografier.","body":"Transaktionen är villkorad av sedvanliga regulatoriska godkännanden.\n\nSertion är en ledande nordisk specialist inom komplexa rörledningsinstallationer och betjänar ett brett spektrum av kommersiella, industriella och infrastrukturella slutmarknader där tillförlitlighet, teknisk expertis och säkerhet är avgörande. Koncernen verkar över hela rörledningens värdekedja – från projektering och prefabrikation till installation, service och löpande drift – och levererar sina tjänster genom 16 lokala bolag och cirka 1 000 anställda i Sverige, Norge och Danmark. Sertion har sitt huvudkontor i Stockholm, omsätter cirka 3 miljarder kronor och är verksamt inom design, installation och service av vatten-, värme- och sanitetssystem, industriell rördragning samt energigaslösningar.\n\nVinges team har huvudsakligen bestått av Christina Kokko, Desirée Hagenfeldt, Elsie Nassar, Nicolina Lavdas, Anna Neubüser och Lucas Eriksson (M&A), David Olander (Konkurrensrätt och FDI), Linn Adelwald och William Carlberg Johansson (Bank och finans), samt Emelie Schoning och Jasmina Skandrani (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-consolid-equity-och-ovriga-saljare-vid-forsaljningen-av-sertion-till-altor/","date":"2026-05-11","month":5},{"year":2026,"client":"Stendörren","work":"Obligationsemission","disciplines":["Kapitalmarknad och publik M&A","Bank och finans"],"title":"Vinge biträder Stendörren vid emission av gröna hybridobligationer","caption":"Obligationsemission · 7 maj 2026","preamble":"Vinge har biträtt Stendörren Fastigheter AB vid dess emission av gröna hybridobligationer om SEK 400 miljoner (inom en ram om SEK 800 miljoner).","body":"Hybridobligationerna har en evig löptid och emitterades med en ränta om STIBOR 3m + 375 baspunkter per år fram till första ordinarie inlösendag. I enlighet med villkoren avses hybridobligationerna upptas till handel på Nasdaq Stockholms lista för gröna obligationer.\n\nSB1 Markets, filial i Sverige och Danske Bank A/S, Danmark, Sverige Filial agerade joint bookrunners i transaktionen.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, Julia Gudmundsson, Pontus Tegström och Jakob Rehnström.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-stendorren-vid-emission-av-grona-hybridobligationer/","date":"2026-05-07","month":5},{"year":2026,"client":"Ingrid Capacity","work":"Obligationsemission","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge biträder Ingrid Capacity vid emissionen av seniora säkerställda obligationer om 400 miljoner kronor","caption":"Obligationsemission · 7 maj 2026","preamble":"Vinge har biträtt Ingrid Capacity AB (publ), i samband med dess emission av seniora säkerställda obligationer om 400 miljoner kronor, inom ett totalt rambelopp om 1 miljard kronor.","body":"Ingrid Capacity är ett ledande svenskt bolag som utvecklar, äger och driver storskaliga batterilager. Batterianläggningarna bidrar till att stabilisera det nordiska elnätet och underlättar omställningen till förnybar energi.\n\nObligationerna omfattas av ett gemensamt säkerhetspaket enligt ett borgenärsavtal (intercreditor agreement) och ett vattenfallsarrangemang med en supersenior kreditgivare.\n\nDNB Carnegie Investment Bank AB (publ) och Skandinaviska Enskilda Banken AB (publ) agerade joint bookrunners i transaktionen.\n\nVinges team bestod av Albert Wållgren, Arvid Weimers, Anna Wisborg och Olivia Altheden.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ingrid-capacity-vid-emissionen-av-seniora-sakerstallda-obligationer-om-400-miljoner-kronor/","date":"2026-05-07","month":5},{"year":2026,"client":"Cinven","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","IT, Telekom och Outsourcing","Bank och finans","Arbetsrätt","Fastigheter och Entreprenad","EU‑ och konkurrensrätt","Immaterialrätt"],"title":"Vinge företräder Cinven vid förvärv av Ongoing Warehouse","caption":"Förvärv · 6 maj 2026","preamble":"Vinge har företrätt Cinven i samband med förvärvet av Ongoing Warehouse.","body":"Ongoing Warehouse, som grundades 2008 och har sitt huvudkontor i Göteborg, är en ledande leverantör av molnbaserade Warehouse Management System (\"WMS\")-lösningar för logistikintensiva företag, inklusive tredjepartslogistiker (”3PL”) och bolag som driver egna lager. Plattformen levererar realtidskontroll av lager, varuhantering, kundkommunikation och avancerad analys som effektiviserar verksamheter och minskar manuellt arbete.\n\nTransaktionen är föremål för tillämpliga regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Samra Tesser, Amanda Steen, Mana Sohrabi, Chris Bastholm och Emelie Liljeblad (M&A), Eva Fredrikson, Nicklas Thorgerzon, Avidh Tajik, Siri Blomberg, Katja Häglund och Filippa Eriksson (Corporate Commercial och IT), Helena Göransson, Karl-Gustaw Tobola, Ida Redander och Olivia Altheden (Bank och finans), Johanna Fjellström and Alice Göransson (Arbetsrätt), Ian Jonson (IP), Wilma Hellman (Fastighet), David Olander och Kate Björk Öhrfelt (Regulatory) samt Filippa Bergkvist (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-cinven-vid-forvarv-av-ongoing-warehouse/","date":"2026-05-06","month":5},{"year":2026,"client":"Fazer","work":"Förvärv","disciplines":["M&A","EU‑ och konkurrensrätt","Finansiella tillståndsfrågor","Arbetsrätt","Fastigheter och Entreprenad","Kommersiella avtal","Immaterialrätt","Bank och finans","GDPR"],"title":"Vinge företräder Fazer i samband med dess förvärv av Aroma","caption":"Förvärv · 6 maj 2026","preamble":"Fazer har ingått avtal avseende förvärv av Konfektyrfabriken Aroma AB, en svensk godistillverkare känd för sina klassiska godisprodukter såsom Geléhallon, Hallonbåtar, Röda Hjärtan och Gräddkola. Förvärvet stärker Fazers position på den svenska godismarknaden, särskilt inom lösviktsgodis, godispåsar och säsongsprodukter. Förvärvet är villkorat av sedvanliga myndighetsgodkännanden.","body":"Vinges team bestod huvudsakligen av Johan Larsson, Philip Moré och Emelie Liljeblad (M&A), Marcus Glader, David Olander, Martin Bergqvist och Sara Stålebring (Konkurrensrätt och FDI), Johan Cederblad (Tillstånd och regulatoriska frågor), William Karo Persson (Arbetsrätt), Madelene Andersson (Fastighetsrätt), Mario Saad och Filippa Eriksson (Kommersiella avtal), Axel Lennartsson (Immaterialrätt), Karl-Gustaw Tobola och Jakob Rehnström (Bank och finans), Nicklas Thorgerzon (GDPR) och Gabriella Balbo (Transaction Support Senior Coordinator).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-fazer-i-samband-med-dess-forvarv-av-aroma/","date":"2026-05-06","month":5},{"year":2026,"client":"Investor","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder Investor i samband med Electrolux Groups företrädesemission","caption":"Kapitalanskaffning · 6 maj 2026","preamble":"Vinge företräder Investor AB (publ) (”Investor”) i samband med Electrolux Groups företrädesemission om cirka 9 miljarder kronor. Investor har åtagit sig att teckna sin pro rata-andel, motsvarande cirka 1,7 miljarder kronor, och därutöver att garantera ytterligare cirka 1,7 miljarder kronor.","body":"Vinges team består huvudsakligen av Sofie Bjärtun, Joel Magnusson och Nora Karlsson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-investor-i-samband-med-electrolux-groups-foretradesemission/","date":"2026-05-06","month":5},{"year":2026,"client":"Interogo Long-Term Equity","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Interogo Long-Term Equity vid dess minoritetsinvestering i Desotec i partnerskap med EQT","caption":"Kapitalanskaffning · 6 maj 2026","preamble":"Vinge företräder Interogo Long-Term Equity vid dess minoritetsinvestering i Desotec, ett ledande företag inom miljölösningar. Investeringen genomförs i partnerskap med EQT, som är majoritetsägare i bolaget efter att ha förvärvat en majoritetsandel i Desotec från Private Equity-fonder förvaltade av Blackstone.","body":"Desotec grundades 1990 och har sitt huvudkontor i Roeselare, Belgien. Bolaget tillhandahåller mobila filtreringslösningar som minskar skadliga utsläpp och föroreningar i vätskor och gaser, och hjälper industriella kunder att följa allt strängare regelverk och ställa om mot mer hållbar verksamhet med lägre miljöpåverkan. Bolagets \"Filtration-as-a-Service\"-modell gör det möjligt för kunder att eliminera föroreningar samtidigt som utsläpp och kostnader minskas genom reaktivering och återanvändning av kol. Desotec har fler än 2 000 kunder, driver Europas största nätverk för reaktivering av aktivt kol och expanderar aktivt sin närvaro i Nordamerika.\n\nInterogo Long-Term Equity är teamet för långsiktiga investeringar i aktier inom Interogo Holding. Teamet riktar in sig på betydande minoritetsinnehav i lönsamma och hållbara västeuropeiska noterade och privata bolag med starka marknadspositioner, dokumenterad historik och tydlig potential för värdeskapande. Interogo Holdings långsiktiga aktieinvesteringar rådges av Interogo Long-Term Equity och förvaltas av Interogo Fund Management.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Linus Adolfsson och Alexander Rüdén (M&A).\n\nLäs mer i klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-interogo-long-term-equity-vid-dess-minoritetsinvestering-i-desotec-i-partnerskap-med-eqt/","date":"2026-05-06","month":5},{"year":2026,"client":"Turbine Capital och Almi Invest GreenTech","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Turbine Capital och Almi Invest GreenTech i investering i Enairon","caption":"Kapitalanskaffning · 5 maj 2026","preamble":"Turbine Capital leder en investeringsrunda på 45 MSEK i det svenska bolaget Enairon tillsammans med Almi Invest GreenTech, European Innovation Council Fund samt befintliga investerare. Enairon är ett svenskt industribolag baserat i Halmstad, som utvecklar en patenterad teknik för tryckluft baserad på vatten och gravitation riktad mot industribolag globalt där tryckluft är en central del av produktionen.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Ellenor Eckerborn.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-turbine-capital-och-almi-invest-greentech-i-investering-i-enairon/","date":"2026-05-05","month":5},{"year":2026,"client":"Anaqua","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har företrätt Anaqua, ett portföljbolag till Nordic Capital, i samband med förvärvet av Patrix","caption":"Förvärv · 30 april 2026","preamble":"Vinge har företrätt Anaqua, Inc., ett portföljbolag till Nordic Capital, i samband med förvärvet av Patrix Aktiebolag, en leverantör av programvara och tjänster för hantering av immateriella rättigheter. Förvärvet utgör ett strategiskt tillskott till Anaquas plattform och stärker ytterligare företagets närvaro i Europa.","body":"Patrix är en leverantör av programvara och tjänster för hantering av immateriella rättigheter, mest känd för sin flaggskeppslösning Patricia®, ett av de mest etablerade och mest använda systemen för hantering av immateriella rättigheter på marknaden. Patricia-plattformen har betjänat sin kundbas, som främst består av advokatbyråer, i trettio år och används aktivt av nästan 400 kunder. Patrix har sitt huvudkontor i Göteborg, Sverige.\n\nAnaqua är den ledande leverantören av teknik och tjänster för innovation och hantering av immateriella rättigheter och betjänar IP-experter inom både företag och advokatbyråer. Anaqua har sitt huvudkontor i Boston, USA, med kontor i USA, Europa, Asien och Australien.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Manon de Cooman, Michella Said, Sebastian Holmberg (M&A), Anders Leissner (Sanktioner), Sam Seddigh, Emil Lindwall (Arbetsrätt), Nicklas Thorgerzon, Therese Baltzarsson (IT / GDPR), Mario Saad, Malin Dejke (Kommersiella Avtal), Ian Jonson, Melinda Oldenburg (Immateriella Rättigheter), Hedvig Merkel (Fastighet) och Jasmina Skandrani (Transaction Support).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-anaqua-ett-portfoljbolag-till-nordic-capital-i-samband-med-forvarvet-av-patrix/","date":"2026-04-30","month":4},{"year":2026,"client":"Delar av konsortiet","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder delar av konsortiet i samband med budet på Cint","caption":"Övrigt · 27 april 2026","preamble":"Budet lämnades genom ett konsortium bestående av Triton Fund 6, Bolero, Patrick Comer och Brett Schnittlich. Erbjudandet värderar samtliga aktier i Cint till cirka 1 989 miljoner kronor. Aktierna i Cint är upptagna till handel på Nasdaq Stockholm, Mid Cap.","body":"Vinge biträder Bolero samt, i förhållande till svensk rätt, Patrick Comer och Brett Schnittlich.\n\nVinges team består av Dain Hård Nevonen, Linnéa Dolk och Maximilian Bengtsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-delar-av-konsortiet-i-samband-med-budet-pa-cint/","date":"2026-04-27","month":4},{"year":2026,"client":"Nordea och SEB","work":"Finansiering","disciplines":["Bank och finans"],"title":"Nordea och SEB ingår kreditavtal om 2 miljarder SEK med Humble Group","caption":"Finansiering · 27 april 2026","preamble":"Den 22 april 2026 ingick Nordea och SEB ett kreditavtal om totalt 2 miljarder SEK (med en s.k. accordion-option om ytterligare 400 miljoner SEK) med Humble Group AB.","body":"Det nya kreditavtalet består av ett term loan och en revolverande kreditfacilitet, vilka ersätter bolagets befintliga kreditfaciliteter som ursprungligen ingicks den 25 juli 2023. De nya faciliteterna har en löptid om tre år vardera, med möjlighet till förlängning i upp till ytterligare två år.\n\nHumble Group är en svensk koncern som specialiserar sig på att skapa värde och accelerera tillväxt i små och medelstora bolag inom dagligvarusektorn (FMCG). Genom ett entreprenöriellt arbetssätt och aktivt ägande fokuserar Humble Group på att utveckla sina verksamheter för att möta framtidens konsumentbehov. Bolaget äger ett flertal varumärken, har ett globalt distributionsnätverk och produktionsanläggningar, där dotterbolagen verkar självständigt inom sina respektive affärsområden medan koncernen tillhandahåller strategisk styrning och stöd. Huvudkontoret ligger i Stockholm.\n\nNordea och SEB biträddes av Vinge i samband med transaktionen. Vinges team bestod av Helena Göransson, Kamyar Najmi och Nilufer Nouri.","href":"https://www.vinge.se/uppdrag/nordea-och-seb-ingar-kreditavtal-om-2-miljarder-sek-med-humble-group/","date":"2026-04-27","month":4},{"year":2026,"client":"Northmill","work":"Kapitalanskaffning","disciplines":["Bank och finans"],"title":"Vinge har biträtt Northmill i samband med dess första emission av primärkapitalinstrument (AT1)","caption":"Kapitalanskaffning · 27 april 2026","preamble":"Vinge har biträtt Northmill Group AB vid dess emission av AT1-obligationer om 275 miljoner kronor med en rörlig kupong om 3-månaders STIBOR + 690 punkter. AT1-obligationerna har en evig löptid med en första inlösenrätt efter fem år och avses upptas till handel på Nasdaq Transfer Market och därefter Nasdaq Stockholm.","body":"Emissionen utgör Northmills första Additional Tier 1-obligation och stärker dess kapitalbas samt lägger grunden för fortsatt lönsam tillväxt. Northmill Group AB är moderbolag till Northmill Bank, en nordisk digital utmanarbank som erbjuder finansiella tjänster för både privatpersoner och företag.\n\nArctic Securities AS, filial Sverige och Nordea Bank Abp agerade joint bookrunners i samband med obligationsemissionen.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda, Nilufer Nouri och Jakob Rehnström.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-northmill-i-samband-med-dess-forsta-emission-av-primarkapitalinstrument-at1/","date":"2026-04-27","month":4},{"year":2026,"client":"ABG Sundal Collier","work":"Obligationsemission","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge biträder ABG Sundal Collier vid Conaptos emission av ytterligare seniora säkerställda obligationer om 500 miljoner kronor","caption":"Obligationsemission · 24 april 2026","preamble":"Vinge har biträtt ABG Sundal Collier som arrangör i samband med Conapto Holding AB (publ) emission av ytterligare seniora säkerställda obligationer om 500 miljoner kronor under dess ramverk om 2 miljarder kronor.","body":"Emissionslikviden kommer att användas för investeringar i bolagets datacenter. Conapto, ett portföljbolag till den europeiska infrastrukturfonden Marguerite, är en ledande leverantör av datacenter colocation. Emissionen initierades genom omvända förfrågningar.\n\nVinges team bestod av Mikael Ståhl, Arvid Weimers och Olivia Carlsten.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-abg-sundal-collier-vid-conaptos-emission-av-ytterligare-seniora-sakerstallda-obligationer-om-500-miljoner-kronor/","date":"2026-04-24","month":4},{"year":2026,"client":"GBL","work":"Förvärv","disciplines":["M&A","EU‑ och konkurrensrätt","Arbetsrätt","Bank och finans"],"title":"Vinge företräder GBL i samband med förvärvet av BUKO Group","caption":"Förvärv · 24 april 2026","preamble":"Vinge företräder, tillsammans med Latham & Watkins, Groupe Bruxelles Lambert (”GBL”) (Euronext Brussels: GBLB) i samband med förvärvet av BUKO Group, en ledande aktör inom tillfällig trafikledning, från fonder som förvaltas av Equistone Partners Europe och grundarfamiljen, medan bolagets ledning kommer att återinvestera tillsammans med GBL. Transaktionen, som är föremål för sedvanliga godkännanden, kommer att innebära en kapitalinvestering om EUR 0,5 miljarder från GBL.","body":"BUKO är en ledande europeisk leverantör av lösningar för låghastighets-TTM och trafiksäkerhet, som främst bistår i samband med investeringar i allmännyttiga sektorer, byggprojekt och evenemang. BUKO levererar helhetslösningar för efterlevnad av regulatoriska säkerhetsbestämmelser och säkert trafikflöde, som omfattar design och planering, godkännanden, utplacering och insamling samt hantering på plats av vägskyltar och säkerhetsutrustning, med ett växande fokus på digitala trafikledningslösningar. BUKO har en betydande närvaro i Nederländerna (som är dess hemmamarknad), Sverige och Storbritannien och är även aktivt i Tyskland. BUKOs personalstyrka uppgår till nära 1 000 personer.\n\nGBL är ett etablerat investmentbolag som har varit börsnoterat i över 70 år, med ett substansvärde om EUR 14 miljarder vid utgången av december 2025. Som en ledande och aktiv investerare i Europa fokuserar GBL på långsiktigt värdeskapande med stöd av en stabil familjeägarkrets.\n\nVinges team bestod främst av Christina Kokko, Linus Adolfsson, Ellenor Eckerborn (M&A), Sebastian Örndahl, Lovisa Arpi (EU, Competition and Regulatory), William Karo Persson, Linn Aho (Employment), Karl-Gustaw Tobola (Banking and Finance) samt Emy Rydén (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-gbl-i-samband-med-forvarvet-av-buko-group/","date":"2026-04-24","month":4},{"year":2026,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Lagercrantz Group vid förvärv av verksamheten i FMK Trafikprodukter","caption":"Förvärv · 24 april 2026","preamble":"Lagercrantz Group har genom dotterbolaget Nordic Road Safety ingått avtal om att förvärva rörelsen och tillgångarna i FMK Trafikprodukter – ett nischbolag inom CE-certifierade vägräckessystem för den svenska och nordiska infrastrukturmarknaden.","body":"Vinge, genom Johan Winnerblad, biträder Lagercrantz Group i förvärvet.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-vid-forvarv-av-verksamheten-i-fmk-trafikprodukter/","date":"2026-04-24","month":4},{"year":2026,"client":"Sobro","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Sobro vid investering i Västkustens Konstruktionsbyrå","caption":"Kapitalanskaffning · 23 april 2026","preamble":"Västkustens Konstruktionsbyrå har valt att bredda sitt ägande med Sobro som ny ägarpartner och majoritetsägare. Grundarna kvarstår som VD respektive CTO och betydande delägare. Västkustens Konstruktionsbyrå är ett teknikkonsultbolag med bas i Göteborg med spetskompetens inom projektledning, konstruktion och projektering.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Lovisa Jonassen, Linn Aho, Dennis Hultman, Sara Stålebring, Ian Jonson, Alex Öberg och Avidh Tajik.\n\nLäs klientes pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sobro-vid-investering-i-vastkustens-konstruktionsbyra/","date":"2026-04-23","month":4},{"year":2026,"client":"Egetis Therapeutics","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Egetis Therapeutics i samband med en riktad nyemission","caption":"Kapitalanskaffning · 22 april 2026","preamble":"Vinge har företrätt Egetis Therapeutics AB (publ) (”Egetis Therapeutics”), noterat på Nasdaq Stockholm, i samband med en riktad nyemission varigenom Egetis Therapeutics tillfördes 350 miljoner kronor före transaktionskostnader.","body":"Emissionen riktades till ett antal internationella och svenska institutionella investerare på grundval av ett accelererat bookbuilding-förfarande.\n\nVinges team bestod av Dain Hård Nevonen, Lorin Arabi och Elias Kröger.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-egetis-therapeutics-i-samband-med-en-riktad-nyemission-2/","date":"2026-04-22","month":4},{"year":2026,"client":"Wismo Automotive","work":"Avyttring","disciplines":["M&A","Arbetsrätt"],"title":"Vinge företrädde Wismo Automotive med dotterbolag vid avyttring av samtliga aktier i J Bil Skadecenter AB","caption":"Avyttring · 21 april 2026","preamble":"Vinge företrädde Wismo Automotive med dotterbolag vid avyttring av samtliga aktier i J Bil Skadecenter AB.","body":"Vinges team leddes av Wibeke Sorling (Partner, M&A) med övriga teammedlemmar Hanna Marberg (M&A) och Marcus Bergström (M&A) samt Yohanna Öhrnegård (Partner, Employment).","href":"https://www.vinge.se/uppdrag/vinge-foretradde-wismo-automotive-med-dotterbolag-vid-avyttring-av-samtliga-aktier-i-j-bil-skadecenter-ab/","date":"2026-04-21","month":4},{"year":2026,"client":"Indutrade","work":"Förvärv","disciplines":["M&A","Arbetsrätt"],"title":"Vinge företräder Indutrade AB i förvärv av AXOTAN Aktiebolag","caption":"Förvärv · 21 april 2026","preamble":"Vinge företräder Indutrade AB i förvärv av AXOTAN Aktiebolag.","body":"Vinges team leddes av Wibeke Sorling (Partner, M&A), med team-medlemmarna Hanna Marberg (M&A), Annie Einarsson (Employment) och Ivar Johansson (M&A) samt Fredrik Löwenclou (FDI).\n\nAxontan Aktiebolag är en distributör av produkter inom hälsa/sjukvård, främst stomi- och sårvård.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-indutrade-ab-i-forvarv-av-axotan-aktiebolag/","date":"2026-04-21","month":4},{"year":2026,"client":"Alder","work":"Finansiering","disciplines":["Bank och finans","Finansiella tillståndsfrågor","Private Funds"],"title":"Vinge har biträtt Alder vid etableringen av Alder Strategic Opportunities Fund I samt med ett fondkreditfacilitetsavtal i samband med fondresningen","caption":"Finansiering · 20 april 2026","preamble":"Vinge har biträtt Alder vid etableringen av continuation-fonden Alder Strategic Opportunities Fund I AB. I samband med etableringen förvärvar fonden portföljbolagen SI och SMG från Alder II. Vinge biträdde även Alder vid ingåendet av ett fondkreditfacilitetsavtal med SEB.","body":"Fondens investerarbas utgörs av ett antal erfarna institutionella investerare, med Pantheon som huvudinvesterare. Fonden är klassificerad som en s.k. Artikel 9-fond, i linje med Alders investeringsprinciper och den integrerade hållbarhetsstrategin i bolagen.\n\nVinges team bestod huvudsakligen av Mattias Schömer, Martin Cronsioe, Nils Unckel, Helena Göransson, Semir Omerbasic, Morgan Ödman, Jonna Bondemark, Liva Bihre, Kamyar Najmi, William Carlberg Johansson, Marcus Svärd samt Felicia Andersson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-alder-vid-etableringen-av-alder-strategic-opportunities-fund-i-samt-med-ett-fondkreditfacilitetsavtal-i-samband-med-fondresningen/","date":"2026-04-20","month":4},{"year":2026,"client":"IK Partners","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","IT, Telekom och Outsourcing","Fastigheter och Entreprenad","Miljörätt","Immaterialrätt","Bank och finans","EU‑ och konkurrensrätt"],"title":"Vinge har biträtt IK Partners i samband med förvärvet av Selatek","caption":"Förvärv · 20 april 2026","preamble":"Vinge har biträtt IK Partners (“IK”) i samband med IK Fund X:s förvärv av SELATEK Holding AB (“Selatek”), en ledande svensk plattformskoncern för tekniska installationer, från Amplio Private Equity AB och minoritetsägarna.","body":"Selatek har sitt huvudkontor i Stockholm och är specialiserat på säkerhet, el- och automationslösningar inom fastigheter, infrastruktur och industrimiljöer. Koncernen bedriver verksamhet på mer än 30 orter i södra och mellersta Sverige, med över 900 heltidsanställda och närmare 6 000 kunder. Under IK:s ägande kommer Selatek att fortsätta att eftersträva organisk tillväxt och påskynda sin expansion i Norden genom strategiska förvärv och operativa förbättringar.\n\nTransaktionen är villkorad av sedvanliga regulatoriska godkännanden.\n\nVinges team bestod av Jonas Bergström, Johanna Wiberg, Carl Fredrik Wachtmeister, Sara Hill, Lovisa Jonassen, Hedvig Merkel och Filippa Olsson (M&A), Mario Saad, Katja Häglund och Filippa Eriksson (Kommersiella Avtal och IT), Niclas Lindblom och Sara Franson (Entreprenad), Simon Söderholm och Louisa Fagarasan (Arbetsrätt), Wilma Hellman (Fastighet och Miljö), Axel Lennartsson och Maja Helm (Immateriella Rättigheter), Jolinn Uhlin och Olivia Altheden (Bank & Finans), Kateryna Lazarchuk och Vilma Simonius (Regelefterlevnad), David Olander, Hedvig Josefson, Lovisa Arpi, Hilda Ivarsson, Isak Lefvert och Emil Bobovac (EU, Competition & Regulatory) samt Fanny Askelöf och Caroline Löv (Transaction Support).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-ik-partners-i-samband-med-forvarvet-av-selatek/","date":"2026-04-20","month":4},{"year":2026,"client":"Right Side Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Right Side Group, ett portföljbolag till Alder, i samband med förvärvet av Brandkonsultbyrån i Sverige","caption":"Förvärv · 17 april 2026","preamble":"Brandkonsultbyrån i Sverige är en teknisk konsult inom byggnadstekniskt brandskydd, utrymningssäkerhet och riskhantering. Sammangåendet stärker koncernens position som en ledande aktör inom brand, risk och säkerhet i Norden.","body":"Vinges team bestod av Johan Larsson och Alex Forsberg.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-right-side-group-ett-portfoljbolag-till-alder-i-samband-med-forvarvet-av-brandkonsultbyran-i-sverige/","date":"2026-04-17","month":4},{"year":2026,"client":"Vidia Climate Fund","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","Bank och finans","Arbetsrätt"],"title":"Vinge företräder Vidia Climate Fund I i samband med förvärvet och förvärvsfinansieringen av ABEKA El & Kraftanläggningar AB","caption":"Förvärv · 17 april 2026","preamble":"Vinge har agerat som legal rådgivare till Vidia Climate Fund I i samband med förvärvet och förvärvsfinansieringen av ABEKA El & Kraftanläggningar AB från Bravida och vissa minoritetsägare. ABEKA El & Kraftanläggningar AB är en högspecialiserad leverantör av elnätstjänster och projektledning.","body":"Vinges team bestod huvudsakligen av Magnus Hedsund, Niklas Törnell, Johan Severinsson och Einar Dahlberg (M&A), Henrik Ossborn och Agaton Lindgren (bank och finans), Ludvig Montan och Clara Klingspor (kommersiella avtal) och Karin Hultgren (arbetsrätt).\n\nLäs klientens pressmeddelande här","href":"https://www.vinge.se/uppdrag/vinge-foretrader-vidia-climate-fund-i-i-samband-med-forvarvet-och-forvarvsfinansieringen-av-abeka-el-kraftanlaggningar-ab/","date":"2026-04-17","month":4},{"year":2026,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Lagercrantz Group vid förvärv av Nivex Topsafe","caption":"Förvärv · 17 april 2026","preamble":"Lagercrantz Group AB (publ) har förvärvat aktierna i Nivex Topsafe AB, som med verksamhet i Sverige och Polen är en ledande aktör på den svenska marknaden för säker förvaring såsom säkerhets- och brandskåp samt säkra rum.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Sofia Sallnäs och Ellenor Eckerborn.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-vid-forvarv-av-nivex-topsafe/","date":"2026-04-17","month":4},{"year":2026,"client":"SAGA Diagnostics","work":"Avyttring","disciplines":["M&A"],"title":"Vinge rådgivare i försäljningen av SAGA Diagnostics","caption":"Avyttring · 16 april 2026","preamble":"Vinge agerade som legal rådgivare avseende svensk rätt i samband med försäljningen av SAGA Diagnostics till Roches helägda dotterbolag Foundation Medicine.","body":"Vinges team bestod av Christina Kokko, Christian Lindhé, Maria Schultzberg och Karin Gynnerstedt.","href":"https://www.vinge.se/uppdrag/vinge-radgivare-i-forsaljningen-av-saga-diagnostics/","date":"2026-04-16","month":4},{"year":2026,"client":"Platzer","work":"Övrigt","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge företräder Platzer i kombinationsaffär med Göteborgs Hamn avseende fastigheter i Arendal","caption":"Övrigt · 8 april 2026","preamble":"Vinge har företrätt Platzer vid en kombinationsaffär med Göteborgs Hamn bestående av försäljning av fastigheten Arendal 1:28, delar av fastigheterna Arendal 1:29 och Arendal 1:31 samt förvärv av del av fastigheten Arendal 764:291.","body":"De fastigheter som Platzer avyttrar består av mark, vatten och byggnader om 61 000 kvm kontor. Som del av kombinationsaffären avyttrar Platzer även 22 000 kvm logistikbyggrätter och förvärvar en fullt uthyrd logistikbyggnad om 24 000 kvm från Göteborgs Hamn.\n\nBåde tillträde och frånträde av fastigheterna är villkorat av beslut i kommunfullmäktige och beräknas ske tidigast under fjärde kvartalet 2026.\n\nVinges team består huvudsakligen av Olof Jisland, Kristoffer Larson, Simon Gille-Johnson och Wilma Hellman.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-platzer-i-kombinationsaffar-med-goteborgs-hamn-avseende-fastigheter-i-arendal/","date":"2026-04-08","month":4},{"year":2026,"client":"SEB","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt SEB, Swedbank och Danske Bank i samband med en bryggkreditfacilitet till Catena","caption":"Finansiering · 2 april 2026","preamble":"Vinge har biträtt Skandinaviska Enskilda Banken AB (publ), Swedbank AB (publ) och Danske Bank A/S i deras roller som mandated lead arrangers och bookrunners i samband med ingåendet av en bryggkreditfacilitet om 4 360 000 000 SEK, 195 000 000 EUR och 170 000 000 DKK till Catena AB (publ).","body":"Faciliteten syftar till att finansiera Catenas förvärv av en nordisk logistikportfölj från Urban Partners samt att refinansiera befintlig skuldsättning i den nordiska logistikportföljen. Förvärvet omfattar totalt 20 moderna logistikfastigheter i Sverige, i Finland och i Danmark, med en total uthyrbar yta om 612 000 kvm. Skandinaviska Enskilda Banken AB (publ) agerade som coordinator och Danske Bank A/S som agent.\n\nVinges team bestod av Helena Göransson, Karl-Gustaw Tobola och Julia Gudmundsson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-seb-swedbank-och-danske-bank-i-samband-med-en-bryggkreditfacilitet-till-catena/","date":"2026-04-02","month":4},{"year":2026,"client":"Grundarna av Nordic Knots","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder grundarna av Nordic Knots i samband med en investering i bolaget av Imaginary Ventures och ytterligare investerare","caption":"Kapitalanskaffning · 2 april 2026","preamble":"Vinge har företrätt grundarna av Nordic Knots i samband med en investering i bolaget ledd av Imaginary Ventures, tillsammans med ytterligare investerare såsom Creades, IRIS Ventures och St Dominique Capital.","body":"Nordic Knots är ett Stockholmsbaserat designbolag inom premiumsegmentet för heminredning, grundat 2016. Bolaget har en omsättning om cirka SEK 670 miljoner under de senaste tolv månaderna, med en genomsnittlig årlig tillväxttakt om drygt 60 procent under de senaste tre åren. Bolagets största marknad är USA som står för cirka 69 procent av försäljningen, med viktiga europeiska marknader såsom Storbritannien, Frankrike och Sverige. Nordic Knots har en flaggskeppsbutik i New York och ett showroom i Stockholm.\n\nInvesteringen leddes av Imaginary Ventures, en USA-baserad specialistfond med fokus på premium- och varumärkesdrivna bolag, med tidigare investeringar i bland annat Skims, Westman Atelier och Reformation.\n\nVinges team bestod av bland andra Jonas Bergström, Maria Dahlin Kolvik, Egil Svensson och Matilda Hamner (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-grundarna-av-nordic-knots-i-samband-med-en-investering-i-bolaget-av-imaginary-ventures-och-ytterligare-investerare/","date":"2026-04-02","month":4},{"year":2026,"client":"Precise Biometrics","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Precise Biometrics","caption":"Övrigt · 27 mars 2026","preamble":"Vinge har biträtt Precise Biometrics AB i samband med fusionen med Fingerprint Cards AB.","body":"Vinges team har huvudsakligen bestått av Christian Lindhé och Jesper Ottergren samt Michaela Ådén, Agaton Lindgren, Jasmine Elgh, Karin Hultgren och Tove Hallbäck.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-precise-biometrics/","date":"2026-03-27","month":3},{"year":2026,"client":"Xspray Pharma","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Xspray Pharma i samband med dess företrädesemission","caption":"Kapitalanskaffning · 26 mars 2026","preamble":"Vinge har biträtt Xspray Pharma AB (publ) i samband med en företrädesemission om cirka 83 miljoner kronor före transaktionskostnader med en övertilldelningsemission om cirka 30 miljoner kronor.","body":"Xspray är ett läkemedelsföretag som specialiserar sig på att använda sin patenterade HyNap-teknologi för att utveckla förbättrade versioner av befintliga protein-kinashämmare (PKI:er) för cancerbehandling.\n\nVinges team har bestått av Dain Hård Nevonen, Louise Nässén, Amanda Sandström och Nora Karlsson (Kapitalmarknad och publik M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-xspray-pharma-i-samband-med-dess-foretradesemission/","date":"2026-03-26","month":3},{"year":2026,"client":"Diamyd Medical","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder Diamyd Medical i samband med riktade emissioner av aktier och teckningsoptioner om upp till 1 166 miljoner kronor","caption":"Kapitalanskaffning · 25 mars 2026","preamble":"Vinge företräder Diamyd Medical Aktiebolag (”Diamyd Medical”), noterat på Nasdaq First North Growth Market, i samband med riktade emissioner av aktier och teckningsoptioner som tillför Diamyd Medical cirka 1 166 miljoner kronor före avdrag för transaktionskostnader, om samtliga teckningsoptioner utnyttjas.","body":"Emissionerna riktades till nya amerikanska sektorspecialiserade investerare. En av emissionerna av teckningsoptioner förutsätter extra bolagsstämmas godkännande.\n\nVinges team bestod av Dain Hård Nevonen, Lorin Arabi, Elias Kröger och Johannes Ekbom (Kapitalmarknad och publik M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-diamyd-medical-i-samband-med-riktade-emissioner-av-aktier-och-teckningsoptioner-om-upp-till-1-166-miljoner-kronor/","date":"2026-03-25","month":3},{"year":2026,"client":"Resurs","work":"Partnerskap","disciplines":["M&A","Kommersiella avtal","IT, Telekom och Outsourcing","GDPR","Finansiella tillståndsfrågor","Immaterialrätt"],"title":"Vinge agerade legal rådgivare till Resurs vid dess strategiska partnerskap med Kustom","caption":"Partnerskap · 25 mars 2026","preamble":"Vinge agerade legal rådgivare till Resurs vid dess strategiska partnerskap med Kustom (tidigare Klarna Checkout), en snabbväxande aktör inom digital handel. Partnerskapet gör det möjligt för Resurs att accelerera sin strategiska utveckling genom att erbjuda en checkout till sina handlare, baserad på Kustoms marknadsledande infrastruktur.","body":"Samarbetet markerar ett strategiskt steg för Resurs i ambitionen att bli den marknadsledande omnikanalsaktören för handlare som vill erbjuda såväl privatpersoner som företag smarta finansieringslösningar. Partnerskapet innebär även att Resurs genomför en investering i Kustom och att Resurs VD Magnus Fredin tillträder som styrelseledamot i Kustoms styrelse. Affären beräknas slutföras under april månad, varefter parterna inleder ett gemensamt arbete med produktintegration.\n\nVinges team bestod huvudsakligen av Christina Kokko, Fredrik Eriksson Oppliger och Nicolina Lavdas (M&A), Mathilda Persson och Siri Blomberg (Kommersiella avtal, IT och GDPR), Caroline Krassén och Elias Bohlin (Finansiella tjänster) och Alva Skott (IP) samt Victor Ericsson.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-agerade-legal-radgivare-till-resurs-vid-dess-strategiska-partnerskap-med-kustom/","date":"2026-03-25","month":3},{"year":2026,"client":"Morrow Bank","work":"Förvärv","disciplines":["M&A","Finansiella tillståndsfrågor","Kapitalmarknad och publik M&A","IT, Telekom och Outsourcing","Kommersiella avtal","Arbetsrätt","Immaterialrätt","EU‑ och konkurrensrätt"],"title":"Vinge har företrätt Morrow Bank AB (publ) vid förvärv av MedMera Bank AB","caption":"Förvärv · 24 mars 2026","preamble":"Vinge har företrätt Morrow Bank AB (publ) vid förvärvet av samtliga aktier i MedMera Bank AB från Kooperativa Förbundet till ett totalt vederlag om 1 960 miljoner kronor. Transaktionen positionerar Morrow Bank som en ledande nordisk plattform inom konsumentfinansiering med en kombinerad bruttoutlåning om 28,2 miljarder kronor.","body":"Morrow Bank är en nordisk nischbank noterad på Nasdaq Stockholm som erbjuder digitala och flexibla finansieringslösningar till privatpersoner i Norge, Sverige och Finland. MedMera Bank är en digital bank som sedan 2007 erbjuder banktjänster inom sparande och lån, med cirka 135 000 kunder och en historiskt stark koppling till Coop-sfären. Transaktionen etablerar ett långsiktigt partnerskap med Coop och dess över 4 miljoner medlemmar, där Kooperativa Förbundet kvarstår som en av de större aktieägarna i den sammanslagna banken.\n\nVinges team bestod huvudsakligen av Samra Tesser, Mana Sohrabi och Viktor Ejlertsson (M&A), Emma Stuart-Beck, Elias Bohlin och Rebecka Björnestedt (Financial Services), Rikard Lindahl, Carl Lexenberg och Hilda Andreasson (Kapitalmarknad och Publik M&A), Mario Saad, Therese Baltzarsson, Elis Allmark, Siri Blomberg och Katja Häglund (Kommersiella Avtal & IT), Sam Seddigh och Louisa Fagarsan (Arbetsrätt), Axel Lennartsson (IP), Sebastian Örndahl och David Olander (EU, Competition & Regulatory) samt Julia Ulander Kull (Transaction Support Coordinator).\n\nTransaktionen är föremål för sedvanliga myndighetsgodkännanden.\n\nFör detaljer om transaktion hänvisas till Morrow Banks pressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-morrow-bank-ab-publ-vid-forvarv-av-medmera-bank-ab/","date":"2026-03-24","month":3},{"year":2026,"client":"NEWS","work":"Avyttring","disciplines":["M&A","Bank och finans","Fastigheter och Entreprenad","Immaterialrätt","Arbetsrätt"],"title":"Vinge företräder NEWS, ett portföljbolag till Litorina, vid försäljningen av Skandinavisk Kommunalteknik, FANN VA-Teknik och Alunda Polyeten till Wienerberger AG","caption":"Avyttring · 24 mars 2026","preamble":"Vinge företräder Northern Environmental and Water Solutions AB (“NEWS”), ett portföljbolag till Litorina, i samband med försäljningen av de operativa dotterbolagen Skandinavisk Kommunalteknik, FANN VA-Teknik och Alunda Polyeten till Wienerberger AG (Vienna Stock Exchange: WIE). Transaktionen förväntas slutföras under Q2 2026.","body":"NEWS erbjuder ett komplett sortiment av avloppslösningar utanför det gravitationsbaserade kommunala systemet genom sina dotterbolag, däribland SKT, som grundades i slutet av 1970-talet och är marknadsledande inom tryckbaserade avloppslösningar i Norden. SKT har sitt säte i Sverige och bedriver även verksamhet i Norge, Finland och Danmark. FANN, grundat 1990, fokuserar på individuella avloppslösningar som huvudsakligen baseras på passiv avloppsreningsteknik och är verksamt främst i Sverige, Finland och Norge. Alunda Polyeten erbjuder skräddarsydd tillverkning av produkter för SKT och FANN.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Linus Adolfsson, Alva Thörn och Viktor Ejlertsson (M&A), Josefine Edström, Josefine Lanker och Gabriel Chabo (Bank och Finans), Simon Gille-Johnson (Fastighetsrätt), Axel Lennartsson (IP), samt Simon Söderholm (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-news-ett-portfoljbolag-till-litorina-vid-forsaljningen-av-skandinavisk-kommunalteknik-fann-va-teknik-och-alunda-polyeten-till-wienerberger-ag/","date":"2026-03-24","month":3},{"year":2026,"client":"TrueLayer","work":"Förvärv","disciplines":["M&A","Finansiella tillståndsfrågor"],"title":"Vinge agerade svensk legal rådgivare till TrueLayer vid förvärvet av Zimpler","caption":"Förvärv · 24 mars 2026","preamble":"Vinge agerade svensk legal rådgivare till TrueLayer, Europas ledande nätverk för öppna bankbetalningar, vid förvärvet av Zimpler, det snabbast växande betalningsnätverket i Norden.","body":"Genom transaktionen skapas ett kombinerat nätverk som betjänar över 20 miljoner användare. Affären förenar två av Europas mest innovativa fintech-bolag och stärker TrueLayers position som en ledande kraft inom den europeiska betalningsbranschen.\n\nVinges team bestod huvudsakligen av Matthias Pannier och Alex Forsberg (M&A), Emma Stuart-Beck, Caroline Krassén, David Flodin och Ebba Gäbel (Finansiella tillståndsfrågor).","href":"https://www.vinge.se/uppdrag/vinge-agerade-svensk-legal-radgivare-till-truelayer-vid-forvarvet-av-zimpler/","date":"2026-03-24","month":3},{"year":2026,"client":"Hansa Biopharma","work":"Finansiering","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Hansa Biopharma i samband med ingående av finansieringsavtal","caption":"Finansiering · 23 mars 2026","preamble":"Vinge har företrätt Hansa Biopharma AB (publ), ett biofarmabolag i kommersiell fas som utvecklar innovativa, livräddande och livsförändrande behandlingar för patienter med sällsynta immunologiska sjukdomstillstånd, noterat på Nasdaq Stockholm, i samband med ett amerikanskt konvertibellåneförvärvsavtal avseende seniora icke-säkerställda konvertibla skuldebrev med ett sammanlagt nominellt belopp om 30 miljoner USD.","body":"Vinges team bestod av Dain Hård Nevonen, Joel Magnusson, Elias Kröger och Nell Silander (Kapitalmarknad och publik M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-hansa-biopharma-i-samband-med-ingaende-av-finansieringsavtal/","date":"2026-03-23","month":3},{"year":2026,"client":"EcoDataCenters","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder vid datacenterleverantören EcoDataCenters emission av ytterligare seniora icke-säkerställda obligationer om 500 miljoner kronor","caption":"Obligationsemission · 19 mars 2026","preamble":"Vinge har biträtt i samband med EcoDC Holding AB (publ) emission av ytterligare seniora icke-säkerställda obligationer om 500 miljoner kronor under dess ramverk om 2 miljarder kronor.","body":"EcoDataCenter är en svensk datacenterleverantör med fokus på hållbara och säkra datacenterlösningar, och ägs av den svenska fondförvaltaren Areim AB.\n\nEcoDataCenter avser att ansöka om notering av obligationerna på Nasdaq Stockholm inom 60 dagar från emissionsdagen. Emissionslikviden kommer att användas för allmänna bolagsändamål.\n\nEmissionen initierades genom omvända förfrågningar. ABG Sundal Collier and Nordea Bank Abp agerade bookrunners.\n\nVinges team bestod av Arvid Weimers, August Ahlin och Olivia Carlsten.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-datacenterleverantoren-ecodatacenters-emission-av-ytterligare-seniora-icke-sakerstallda-obligationer-om-500-miljoner-kronor/","date":"2026-03-19","month":3},{"year":2026,"client":"Cinclus Pharma","work":"Finansiering","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Cinclus Pharma i samband med ingående av finansieringsavtal","caption":"Finansiering · 16 mars 2026","preamble":"Vinge har företrätt Cinclus Pharma Holding AB (publ), ett läkemedelsbolag i sen klinisk fas som utvecklar nästa generations behandlingar för magsyrarelaterade sjukdomar noterat på Nasdaq Stockholm, i samband med ett långsiktigt strukturerat kreditavtal om totalt upp till 28 miljoner EUR uppdelat i fyra trancher, varav två konvertibler.","body":"Vinges team bestod av Dain Hård Nevonen, Louise Nässén och Hilda Andreasson (Kapitalmarknad och publik M&A) samt av Arvid Weimers, John Andrén och Olivia Carlsten (Bank och finans).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-cinclus-pharma-i-samband-med-ingaende-av-finansieringsavtal/","date":"2026-03-16","month":3},{"year":2026,"client":"Studentbostäder","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Studentbostäder i Norden AB (publ) vid emission av obligationer om SEK 500 miljoner och förtida inlösen av utestående obligationer","caption":"Obligationsemission · 12 mars 2026","preamble":"Vinge biträder Studentbostäder i Norden AB (publ) vid dess emission av seniora, icke-säkerställda obligationer om SEK 500 miljoner (inom en ram om SEK 750 miljoner) och med bolagets parallella frivilliga förtida inlösen av tidigare emitterade obligationer.","body":"Obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms lista för hållbara obligationer. Obligationerna har en löptid om 3,25 år och emitterades med en ränta om STIBOR 3m + 500 baspunkter. Arctic Securities AS, filial Sverige och SB1 Markets, filial i Sverige agerade som joint bookrunners i transaktionen.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, August Ahlin och Nilufer Nouri.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-studentbostader-i-norden-ab-publ-vid-emission-av-obligationer-om-sek-500-miljoner-och-fortida-inlosen-av-utestaende-obligationer/","date":"2026-03-12","month":3},{"year":2026,"client":"Skeptiva","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har biträtt Skeptiva AB i samband med en kapitalanskaffning","caption":"Kapitalanskaffning · 11 mars 2026","preamble":"Skeptiva bygger nästa generations cybersäkerhetsförsvar mot bedrägerier. Skeptiva har utvecklat en AI-applikation som upptäcker attacker och varnar användaren i realtid.","body":"I nyemissionen deltog en grupp av investerare bestående av erfarna grundare, CISOs och ledare inom cybersäkerhet.\n\nVinges team bestod av Filip Öhrner och Maja Helm.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-skeptiva-ab-i-samband-med-en-kapitalanskaffning/","date":"2026-03-11","month":3},{"year":2026,"client":"Main Capital","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Immaterialrätt","Kommersiella avtal","IT, Telekom och Outsourcing","GDPR","FDI"],"title":"Vinge har företrätt Main Capital vid förvärvet av Good Solutions Sweden AB","caption":"Förvärv · 11 mars 2026","preamble":"Good Solutions Sweden AB (”Good Solutions”) tillhandahåller en mjukvarulösning som hjälper fabriker att identifiera och minska produktionsförluster. Mjukvaran omvandlar data från maskiner och operatörer till insikter som kan användas för att effektivisera produktionen och öka lönsamheten.","body":"Good Solutions grundades 2005 och har huvudkontor i Göteborg. Bolagets mjukvara används i fler än 280 fabriker inom bland annat livsmedels- och dryckesindustrin, läkemedelsindustrin och fordonsindustrin.\n\nVinges team bestod av Filip Öhrner, Kim Bergman Aldevinge, Lovisa Jonassen och Robert Sande (M&A), Johanna Fjellström och Linn Aho (Arbetsrätt), Ian Jonson och Filippa Eriksson (IP), Nicklas Thorgerzon och Therese Baltzarsson (Kommersiella avtal, IT och GDPR), David Olander (FDI) och Filippa Bergkvist (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-main-capital-vid-forvarvet-av-good-solutions-sweden-ab/","date":"2026-03-11","month":3},{"year":2026,"client":"Studsvik","work":"Förvärv","disciplines":["M&A","Kapitalmarknad och publik M&A","Miljörätt","Fastigheter och Entreprenad","Kommersiella avtal","GDPR","IT, Telekom och Outsourcing","Immaterialrätt","Arbetsrätt","Bank och finans"],"title":"Vinge företräder Studsvik AB (publ) vid förvärvet av Kärnfull Next AB","caption":"Förvärv · 10 mars 2026","preamble":"Vinge har företrätt Studsvik AB (publ) i samband med förvärvet av Kärnfull Next AB, ett bolag som utvecklar metoder för att bygga små modulära kärnreaktorer.","body":"Genom förvärvet utökar Studsvik sin kapacitet för utveckling av teknikoberoende SMR-projekt och expanderar sin roll till att utveckla nya kärnkraftsprojekt. Grundarna av Kärnfull Next ansluter till ledningsgruppen när Studsvik bygger en plattform för kärnkraftstjänster som täcker hela livscykeln.\n\nTransaktionen är föremål för sedvanliga regulatoriska godkännanden.\n\nVinges team bestod främst av Matthias Pannier, Peter Sundgren, Edvard Gustafsson och Ida Appelgren (M&A), Rikard Lindahl och Maximilian Bengtsson (Kapitalmarknad och Publik M&A), Johan Cederblad och Stina Larsson (Tillstånd och Miljörätt), Wilma Hellman (Fastighetsrätt), Malin Ohlin och Christoffer Nordin (Kommersiella avtal), Nicklas Thorgerzon (IT och GDPR), Daniel Wendelsson och Hilda Ivarsson (FDI), Emma Gustavsson och Alex Öberg (IP), Simon Söderholm och Ida Pettersson (Arbetsrätt), Gabriel Chabo (Bank och finans) och Jasmina Skandrani (Transaktionssupport).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-studsvik-ab-publ-vid-forvarvet-av-karnfull-next-ab/","date":"2026-03-10","month":3},{"year":2026,"client":"Advania","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Advania vid förvärvet av Evolv Robotics","caption":"Förvärv · 5 mars 2026","preamble":"Vinge har företrätt Advania vid förvärvet av Evolv Robotics, ett snabbväxande isländskt mjukvarubolag specialiserat på digital arbetsflödesautomatisering.","body":"Evolv Robotics har utvecklat och implementerat både standardiserade och skräddarsydda intelligenta mjukvaruagenter som kombinerar digital arbetskraft och artificiell intelligens för att automatisera komplexa arbetsflöden, i syfte att förbättra effektiviteten och kvaliteten inom funktioner som ekonomi, inköp och HR för kunder inom flera branscher i både den privata och den offentliga sektorn på Island.\n\nGenom förvärvet stärker Advania sina tjänster inom robotic process automation och tar ett viktigt steg i sin strategi att bli en stark partner inom automatiseringsområdet på den europeiska marknaden.\n\nTransaktionen är villkorad av sedvanliga regulatoriska godkännanden.\n\nVinges team bestod av Peter Sundgren, Ulrich Ziche och Jonatan Stentorp (M&A), och Noelia Martinez (Regulatory).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-advania-vid-forvarvet-av-evolv-robotics/","date":"2026-03-05","month":3},{"year":2026,"client":"Atria Sverige","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Atria Sverige vid investering i Cookin Food","caption":"Kapitalanskaffning · 4 mars 2026","preamble":"Atria Sverige har förvärvat 25 procent i det svenska färdigmatsbolaget Cookin Food Sweden AB. Transaktionen genomförs genom förvärv av aktier i Bite Delight AB, som äger Cookin Food Sweden AB. Atria har en option att förvärva de återstående aktierna i Bite Delight AB efter år 2028.","body":"Vinges team bestod i huvudsak Johan Winnerblad och Helena Liljenberg.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-atria-sverige-vid-investering-i-cookin-food/","date":"2026-03-04","month":3},{"year":2026,"client":"Revivo Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Revivo Group vid förvärv av Solidenergy","caption":"Förvärv · 3 mars 2026","preamble":"Revivo Group, ett portföljbolag till Helix Kapital, har förvärvat Solidenergy, en ledande leverantör av ytbehandlingstjänster på den norska marknaden. Bolaget verkar inom energi, offshore och infrastruktur och har huvudkontor i Ågotnes utanför Bergen. Solidenergy sysselsätter cirka 600 medarbetare.","body":"Vinge, genom Johan Winnerblad, biträdde Revivo Group i förvärvet.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-revivo-group-vid-forvarv-av-solidenergy/","date":"2026-03-03","month":3},{"year":2026,"client":"Oncopeptides","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Oncopeptides i samband med dess företrädesemission","caption":"Kapitalanskaffning · 3 mars 2026","preamble":"Vinge har företrätt Oncopeptides AB (publ) i samband med en delvis garanterad företrädesemission som förväntas tillföra Oncopeptides cirka 200 miljoner kronor före avdrag för transaktionskostnader.","body":"Oncopeptides är ett biotechbolag inriktat på forskning, utveckling och kommersialisering av behandlingar mot svårbehandlade hematologiska sjukdomar. Bolaget använder sin patentskyddade PDC-plattform för att utveckla peptidlänkade läkemedel som snabbt och selektivt levererar cellgifter in i cancerceller.\n\nVinges team har bestått av Dain Hård Nevonen, Joel Magnusson, Amanda Sandström och Johannes Ekbom.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-oncopeptides-i-samband-med-dess-foretradesemission-2/","date":"2026-03-03","month":3},{"year":2026,"client":"Poseidon Diving Group","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder i samband med försäljningen av Poseidon Diving Group","caption":"Avyttring · 2 mars 2026","preamble":"Vinge biträder säljarna i samband med försäljningen av Poseidon Diving Group AB till Argo Defence Group AB. Poseidon som grundades 1958 är en ledande tillverkare av avancerad dyk- och andningsutrustning.","body":"Vinges team har huvudsakligen bestått av Anders Strid och Edin Agic.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-i-samband-med-forsaljningen-av-poseidon-diving-group/","date":"2026-03-02","month":3},{"year":2026,"client":"Ledningen","work":"Avyttring","disciplines":["M&A","Företagsbeskattning"],"title":"Vinge har biträtt ledningen i atNorth i samband med försäljningen av atNorth till CPP Investments och Equinix","caption":"Avyttring · 2 mars 2026","preamble":"Vinge har biträtt ledningen för atNorth vid försäljningen av atNorth till Canada Pension Plan Investment Board (CPP Investments) och Equinix (EMEA) Management, Inc. från Partners Group och minoritetsägarna.","body":"atNorth är en ledande nordisk aktör inom datacentersinfrastruktur och tillhandahåller datacenter med fokus på ökad effektivitet, hållbarhet och skalbarhet. atNorths anläggningar erbjuder skräddarsydda lösningar för kunder med höga krav på prestanda och tillförlitlighet.\n\nTransaktionen är villkorad av sedvanliga regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Peter Sundgren, Kim Bergman Aldevinge, Nina Bonnier, Josef Groow, Jonatan Stentorp och Adam Karlsson (M&A), och Maria Schultzberg (Skatt).\n\nLäs atNorths pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-ledningen-i-atnorth-i-samband-med-forsaljningen-av-atnorth-till-cpp-investments-och-equinix/","date":"2026-03-02","month":3},{"year":2026,"client":"Bain Capital","work":"Kapitalanskaffning","disciplines":["M&A","IT, Telekom och Outsourcing","Fastigheter och Entreprenad","Immaterialrätt","Arbetsrätt","EU‑ och konkurrensrätt"],"title":"Vinge företräder Bain Capital i samband med dess majoritetsinvestering i Tingstad koncernen","caption":"Kapitalanskaffning · 2 mars 2026","preamble":"Vinge har tillsammans med Kirkland & Ellis företrätt Bain Capital i samband med förvärvet av en majoritetsandel i Aktiebolaget Tingstad Papper (\"Tingstad\") och dess dotterbolag.","body":"Tingstad är en ledande svensk familjeägd specialistdistributör av icke-livsmedelsrelaterade förbrukningsvaror, med en bred och diversifierad kundbas inom detaljhandel, fastighetsförvaltning och dagligvaruhandel. Tingstad har byggt upp långvariga kundrelationer som grundar sig i stark kategorikompetens, en differentierad egenmärkesportfölj och en förstklassig lager- och logistikinfrastruktur.\n\nBain Capital är en ledande global privat investeringsfirma med djup expertis i Norden genom befintliga portföljbolag. Investeringen kommer att genomföras genom att Bain Capital förvärvar en majoritetsandel i Tingstad, i partnerskap med ägaren Paul Jigberg som kommer att behålla en minoritetsägarandel, samt ledningsgruppen och de anställda, för att stödja Tingstads nästa tillväxtfas.\n\nVinges team bestod huvudsakligen av Jonas Bergström, Matthias Pannier, Per Kling, Johanna Barfoed och Nora Karlsson (M&A), Mathilda Persson, Siri Blomberg, Dante Lalouni, Christoffer Nordin och Therese Baltzarsson (IT/CC), Niclas Winnberg och Hedvig Merkel (Fastighet), Filippa Eriksson och Emma Gustavsson (IP), William Karo Persson och Linn Aho (Arbetsrätt) samt David Olander (EU & Konkurrens).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-bain-capital-i-samband-med-dess-majoritetsinvestering-i-tingstad-koncernen/","date":"2026-03-02","month":3},{"year":2026,"client":"Smart Eye","work":"Förvärv","disciplines":["Kapitalmarknad och publik M&A","M&A","Regulatoriska tvister"],"title":"Vinge biträder Smart Eye vid förvärv av Sightic Analytics","caption":"Förvärv · 24 februari 2026","preamble":"Smart Eye har ingått avtal om förvärv av samtliga aktier i Sightic Analytics för en fast köpeskilling om 60,5 MSEK som ska erläggas med nyemitterade aktier i Smart Eye och en tilläggsköpeskilling om maximalt 50 MSEK, vilken är villkorad av att vissa finansiella respektive operativa mål uppfylls.","body":"Sightic Analytics utvecklar teknik för alkohol- och drogdetektering och identifiering av uppmärksamhetsrelaterade risker genom avancerad ögonanalys och artificiell intelligens. Tillträdet är är villkorat av att Inspektionen för Strategiska Produkter lämnar Smart Eyes ansökan utan åtgärd.\n\nVinges team har huvudsakligen bestått av Anders Strid, Hanna Marberg (M&A), Edin Agic (Kapitalmarknad) samt Victoria Gunnerek och Fredrik Löwenclou (Regulatoriska frågor).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-smart-eye-vid-forvarv-av-sightic-analytics/","date":"2026-02-24","month":2},{"year":2026,"client":"Axcel och Accru Partners","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Bank och finans","Kommersiella avtal","IT, Telekom och Outsourcing","GDPR","Fastigheter och Entreprenad","Regulatoriska tvister"],"title":"Vinge företräder Axcel och Accru Partners vid förvärven av Baker Tilly Uppsala AB och Baker Tilly Guide AB","caption":"Förvärv · 22 februari 2026","preamble":"Vinge har företrätt Axcel VII och Accru Partners i samband med förvärven av Baker Tilly Uppsala AB och Baker Tilly Guide AB.","body":"Baker Tilly Uppsala AB och Baker Tilly Guide AB är entreprenörsledda, lokala företag med expertis inom redovisning, revision, skatt, och rådgivningstjänster. Efter förvärven består Accru Partners av totalt 61 självständiga byråer inom nämnda verksamhetsområden.\n\nVinges team bestod av Christina Kokko, Egil Svensson, Michella Lina Said, Chris Bastholm och Emelie Herlitz (M&A), Linn Aho och Simon Söderholm (Arbetsrätt), Sofia Haggren (Bank och finans), Mario Saad (Kommersiella avtal), Elis Allmark (IT), Nicklas Thorgerzon (GDPR), Madelene Andersson, Sara Franson och Hedvig Merkel (Fastighet), Jonna Bondemark och Isabelle Asserståhl (Regulatoriska frågor), Gulestan Ali och Vilma Simonius (Regelefterlevnad) samt Jessica Öijer (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-accru-partners-vid-forvarven-av-baker-tilly-uppsala-ab-och-baker-tilly-guide-ab/","date":"2026-02-22","month":2},{"year":2026,"client":"Nimlas","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Kommersiella avtal"],"title":"Vinge rådgivare när Nimlas expanderar med dubbla förvärv inom elbranschen","caption":"Förvärv · 20 februari 2026","preamble":"Vinge har biträtt Nimlas i samband med förvärven av Uppsala Elcentral AB och Tjädermo's El AB – två strategiska affärer som stärker koncernens position på den svenska elinstallationsmarknaden.","body":"Nimlas, med KLAR Partners som huvudägare, är en av Nordens ledande installationskoncerner med över 140 bolag i Sverige, Finland och Norge.\n\nGenom förvärven av Uppsala Elcentral och Tjädermo's El tar Nimlas Sverige ytterligare kliv i sin tillväxtstrategi, där elbranschen utgör en viktig hörnsten.\n\nFörvärven är i linje med Nimlas koncernens tillväxtstrategi 2-20-2; 2 miljarder SEK i EBITA, 20 miljarder SEK i omsättning och expansion till 2 nya marknader.\n\nVinges team bestod huvudsakligen av Johanna Wiberg, Fredrik Eriksson Oppliger och Alex Forsberg (M&A), Johanna Fjellström (Arbetsrätt) samt Mario Saad och Malin Dejke (Kommersiella avtal).","href":"https://www.vinge.se/uppdrag/vinge-radgivare-nar-nimlas-expanderar-med-dubbla-forvarv-inom-elbranschen/","date":"2026-02-20","month":2},{"year":2026,"client":"Zengun","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Zengun vid emission av obligationer om SEK 750 miljoner och förtida inlösen av utestående obligationer","caption":"Obligationsemission · 20 februari 2026","preamble":"Vinge biträder Zengun Group AB (publ) vid dess emission av seniora säkerställda obligationer om SEK 750 miljoner (inom en ram om SEK 1,500 miljoner) och med bolagets parallella frivillig förtida inlösen av tidigare emitterade obligationer.","body":"Obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms lista för företagsobligationer. Obligationerna har en löptid om fyra år och emitterades med en ränta om STIBOR 3m + 450 baspunkter. ABG Sundal Collier och DNB Carnegie Investment Bank AB (publ) agerade som joint bookrunners i transaktionen.\n\nVinges team bestod av Magnus Pauli, Lionardo Ojeda, Edin Agic och Sofia Haggren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-zengun-vid-emission-av-obligationer-om-sek-750-miljoner-och-fortida-inlosen-av-utestaende-obligationer/","date":"2026-02-20","month":2},{"year":2026,"client":"Sluta Gräva","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Sluta Gräva vid förvärv av Stavrex","caption":"Förvärv · 18 februari 2026","preamble":"Vinge har biträtt Sluta Gräv, ett portföljbolag till Sobro, vid förvärv av Stavrex. Tillsammans bildar bolagen Nordens ledande leverantör av markskruv, med marknadens bredaste erbjudande.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Ida Appelgren.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-sluta-grava-vid-forvarv-av-stavrex/","date":"2026-02-18","month":2},{"year":2026,"client":"Stendörren","work":"Obligationsemission","disciplines":["Bank och finans","Rekonstruktioner och obestånd"],"title":"Vinge biträder Stendörren vid emission av ytterligare gröna obligationer","caption":"Obligationsemission · 18 februari 2026","preamble":"Vinge har biträtt Stendörren Fastigheter AB vid dess emission av ytterligare seniora, icke-säkerställda gröna obligationer om SEK 300 miljoner (inom en ram om SEK 800 miljoner kronor).","body":"Obligationerna har emitterats under bolagets befintliga ramverk om totalt SEK 800 miljoner, varav obligationer om SEK 400 miljoner emitterats tidigare. Obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms lista för hållbara obligationer.\n\nNordea Bank Abp och Skandinaviska Enskilda Banken AB (publ) agerade joint bookrunners i transaktionen.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda och Julia Gudmundsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-stendorren-vid-emission-av-ytterligare-grona-obligationer/","date":"2026-02-18","month":2},{"year":2026,"client":"DNB Carnegie","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder DNB Carnegie i samband med en obligationsemission om 130 miljoner euro för att finansiera Incore Invests förvärv av CoreOrchestration","caption":"Obligationsemission · 16 februari 2026","preamble":"Vinge har biträtt DNB Carnegie Investment Bank AB (publ), i egenskap av sole bookrunner, i samband med en emission av seniora säkerställda obligationer om 130 miljoner euro inom en ram om 200 miljoner euro.","body":"Emissionslikviden från obligationerna ska bland annat användas av emittenten för att finansiera Incore Invests förvärv av CoreOrchestration AB från Worldline i en så kallad carve-out-transaktion. Förvärvet förväntas slutföras under första kvartalet 2026. CoreOrchestration möjliggör, genom sin SaaS-baserade betalningsorkestreringsplattform PaymentIQ, för handlare att centralt hantera, optimera och skala betalningsflöden över flera leverantörer och marknader.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda, William Carlberg Johansson och Julia Gudmundsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-dnb-carnegie-i-samband-med-en-obligationsemission-om-130-miljoner-euro-for-att-finansiera-incore-invests-forvarv-av-coreorchestration/","date":"2026-02-16","month":2},{"year":2026,"client":"BAE Systems Bofors","work":"Förvärv","disciplines":["M&A","Miljörätt","Arbetsrätt","Internationell handel","Bank och finans"],"title":"Vinge har biträtt BAE Systems Bofors vid förvärvet av Aston Harald Mekaniska Verkstad","caption":"Förvärv · 12 februari 2026","preamble":"BAE Systems är en världsledande försvarskoncern med närvaro i Sverige bland annat genom BAE Systems Bofors i Karlskoga, en leverantör av vapensystem, artilleri och ammunition. Förvärvet är strategiskt motiverat och syftar till att stärka den svenska försvarsindustrins produktionskapacitet.","body":"Aston Harald är en Kristinehamnsbaserad leverantör av precisionsbearbetade komponenter inom försvars- och flygindustrin och har sedan länge varit en viktig leverantör till BAE Systems. Genom att integrera Aston Harald i koncernen säkrar BAE Systems en viktig del av sin leveranskedja och ökar sin förmåga att möta den växande efterfrågan på försvarssystem som ARCHER, TRIDON samt marinpjäserna 40 Mk4 och 57 Mk3. Slutförandet av transaktionen är föremål för sedvanliga villkor.\n\nVinges team bestod huvudsakligen av Jonas Bergström, Peter Sundgren, Viktor Ramhult, Johanna Barfoed, Nora Karlsson (M&A), Johan Cederblad, Stina Larsson (Miljö), Louisa Fagarasan (Arbetsrätt), Eva Fredrikson, Siri Blomberg, Axel Lennartsson, Malin Dejke (IT/CC), Anders Leissner (Internationell handel och Compliance) och Gabriel Chabo (Bank och finans).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-bae-systems-bofors-vid-forvarvet-av-aston-harald-mekaniska-verkstad-aston-harald/","date":"2026-02-12","month":2},{"year":2026,"client":"Sertion","work":"Förvärv","disciplines":["M&A","Corporate Commercial","Arbetsrätt"],"title":"Vinge har biträtt Sertion AB i samband med förvärvet av Svensk Anläggning och Driftteknik AB","caption":"Förvärv · 10 februari 2026","preamble":"Genom förvärvet tar Sertion ytterligare ett steg i sin utveckling som en ledande internationell infrastruktur- och installationskoncern inom komplexa VVS-system, teknisk infrastruktur och industriella rörledningar. Svensk Anläggning och Driftteknik AB är specialiserade inom certifierad svetsning och installation av industriella rörledningar.","body":"Vinges team bestod huvudsakligen av Christina Kokko, Desirée Hagenfeldt, Amanda Steen, Sara Eirefors (M&A), Alva Chambert (Regulatory), Ludvig Montan (Corporate Commercial), William Karo Persson (Arbetsrätt) och Julia Ulander Kull (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-sertion-ab-sertion-i-samband-med-forvarvet-av-svensk-anlaggning-och-driftteknik-ab/","date":"2026-02-10","month":2},{"year":2026,"client":"Mirova","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Mirova i förvärvet av vindkraftsparkerna Boarp, Dållebo och Fågelås","caption":"Förvärv · 10 februari 2026","preamble":"Vinge har biträtt Mirova, ett dotterbolag till Natixis Investment Managers som fokuserar på hållbara investeringar, i samband med förvärvet av de tre svenska landbaserade vindkraftsparkerna Boarp, Dållebo och Fågelås.","body":"23 december 2025 avtalade och slutförde Mirova förvärvet av de tre svenska landbaserade vindkraftsparkerna Fågelås, Dållebo och Boarp från Eolus AB. Mirova har förvärvat 100 procent av ägandet i de tre vindparkerna, som är utrustade med de senaste Vestas-turbinerna och ett nyligen undertecknat 15-årigt pris- och leveranssäkringsavtal (“PPA”) som täcker en betydande del av anläggningarnas årliga elproduktion.\n\nVinges team bestod huvudsakligen av Christoffer Thalin, Tilda Hall, Agnes Tell, Emma Sääf, Isabelle Ivarsson, Jesper Ottergren, Johan Cederblad, Jonatan Karlsson, Markus Hedbys, Nicolas Ek, Sofie Nordgren och Jasmine Elgh.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-mirova-i-forvarvet-av-vindkraftsparkerna-boarp-dallebo-och-fagelas/","date":"2026-02-10","month":2},{"year":2026,"client":"Bridgepoint","work":"Förvärv","disciplines":["M&A","Immaterialrätt","GDPR","Kommersiella avtal","Bank och finans","Regulatoriska tvister","Arbetsrätt","Fastigheter och Entreprenad"],"title":"Vinge har biträtt Bridgepoint med att tillsammans med Polaris förvärva ett majoritetsinnehav i PDSVISION, en global ledare inom digital engineering","caption":"Förvärv · 10 februari 2026","preamble":"PDSVISION, med huvudkontor i Stockholm, är verksamt i Nordamerika, Europa och Asien. Bolaget levererar integrerad programvara och tjänster som stödjer digital transformation inom produktutveckling och tillverkning, vilket hjälper kunder att förbättra produktiviteten och påskynda resan från koncept till produktion.","body":"PDSVISION har byggt upp en abonnemangsdriven verksamhet med cirka 1,7 miljarder kronor i intäkter, präglad av långvariga kundrelationer och stark organisk tillväxt.\n\nTransaktionen är föremål för sedvanliga regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Daniel Rosvall, Kim Bergman Aldevinge, Mana Sohrabi, Alex Forsberg, Anna Neubüser och Matilda Hamner (M&A), Albert Wållgren, Karl-Gustaw Tobola och Gabriel Chabo (Bank och finans), Mario Saad, Katja Häglund (Kommersiella avtal, IT och GDPR), Gulestan Ali (Regulatoriska frågor), Sam Seddigh, Agnes Pigg (Arbetsrätt), Axel Lennartsson (Immaterialrätt), Hedvig Merkel (Fastighetsrätt), Noelia Martinez och Hilda Ivarsson (Konkurrensrätt och FDI), Ulrich Ziche (rörande tysk rätt) och Julia Ulander Kull (Koordinator för transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-bridgepoint-med-att-tillsammans-med-polaris-forvarva-ett-majoritetsinnehav-i-pdsvision-en-global-ledare-inom-digital-engineering/","date":"2026-02-10","month":2},{"year":2026,"client":"GleSYS","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt GleSYS i samband med ingående av kreditfacilitetsavtal","caption":"Finansiering · 10 februari 2026","preamble":"Vinge har biträtt GleSYS i samband med ingående av ett kreditfacilitetsavtal med Swedbank och Falkenbergs Sparbank.","body":"Kreditfacilitetsavtalet ska användas till att, bland annat, finansiera förvärvet av verksamhet inom managed private cloud i Finland och datacenteranläggningar i Pori och Tammerfors, refinansiera existerande skuld samt för allmänna företagsändamål.\n\nGleSYS är en ledande nordisk leverantör av moln- och IaaS-tjänster (Infrastructure as a Service) och stöds av Cube Infrastructure Managers, en europeisk infrastrukturfond.\n\nVinges team bestod av Helena Göransson, Calle Tengwall Pagels, Rebecka Margolin och Katja Häglund.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-glesys-i-samband-med-ingaende-av-kreditfacilitetsavtal/","date":"2026-02-10","month":2},{"year":2026,"client":"Viva Wine Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har företrätt Viva Wine Group AB i samband med förvärvet av det norska dryckesbolaget Alpha Brands","caption":"Förvärv · 9 februari 2026","preamble":"Vinge har företrätt Viva Wine Group AB i samband med förvärvet av 60 procent av aktierna i det norska dryckesbolaget Alpha Brands, till en initial kontant köpeskilling om 33 MNOK, med en eventuell tilläggsköpeskilling baserat på bolagets resultatutveckling.","body":"Alpha Brands är ett norskt bolag med försäljning av drycker till dagligvaruhandeln inom kategorin ”NoLo”, d.v.s. alkoholfria och alkoholsvaga drycker. I och med förvärvet av Alpha Brands stärker Viva Wine Group sin ställning både på den norska marknaden och inom denna växande kategori.\n\nVinges team bestod av Anna Jonsson, Michaela Ådén, Lisa Bourghardt, Hedvig Josefson, Tilda Hall och Tove Hallbäck.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-viva-wine-group-ab-i-samband-med-forvarvet-av-det-norska-dryckesbolaget-alpha-brands/","date":"2026-02-09","month":2},{"year":2026,"client":"HAKI Safety","work":"Förvärv","disciplines":["M&A","Bank och finans","Arbetsrätt","Immaterialrätt"],"title":"Vinge företräder HAKI Safety AB (publ) i samband med förvärvet av Newbow Aerospace Limited","caption":"Förvärv · 9 februari 2026","preamble":"Newbow Aerospace är en brittisk marknadsledande tillverkare och leverantör av markstödsutrustning, Ground Support Equipment, GSE, som används till säkert och effektivt underhåll av flygplan.","body":"Newbow Aerospace tillverkar och säljer specialutvecklade produkter och lösningar för säkert underhåll av flygplansdäck. Kunderna återfinns globalt och är såväl civila som militära. Företagets huvudkontor och tillverkning finns i Redditch, Worcestershire, England.\n\nVinges team bestod av Anna Edström, Niklas Törnell, Agnes Tell (M&A) samt Lisa Bourghardt (IP), Tove Hallbäck (arbetsrätt) och Irma Softic (Bank & Finans).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-haki-safety-ab-publ-i-samband-med-forvarvet-av-newbow-aerospace-limited/","date":"2026-02-09","month":2},{"year":2026,"client":"ERG","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder ERG vid avyttring av ERG Sweden Holding AB","caption":"Avyttring · 9 februari 2026","preamble":"Vinge har biträtt ERG POWER GENERATION S.P.A. i samband med avyttringen av ERG Sweden Holding AB, och indirekt Furukraft AB, till Nordetic AB.","body":"Genom affären avyttrar ERG sina svenska innehav genom ERG Sweden Holding AB, som är moderbolag till Furukraft AB.\n\nVinge agerade rådgivare till säljaren i hela processen, med ansvar för den legala hanteringen av aktieöverlåtelsen och den övergripande transaktionsstrukturen.\n\nI teamet ingick Christoffer Thalin, Agnes Tell, Einar Dahlberg, Emma Sääf, Irma Softic, Johan Cederblad, Johan Severinsson, Lisa Bourghardt och Tilda Hall.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-erg-vid-avyttring-av-erg-sweden-holding-ab/","date":"2026-02-09","month":2},{"year":2026,"client":"Borgo","work":"Kapitalanskaffning","disciplines":["Bank och finans"],"title":"Vinge biträder Borgo vid bolagets första emission av primärkapitalinstrument (AT1)","caption":"Kapitalanskaffning · 29 januari 2026","preamble":"Vinge har biträtt Borgo AB (publ) i samband med dess framgångsrika emission av primärkapitalinstrument (s.k. AT1-obligationer) om 350 miljoner kronor med en rörlig kupong om 3-månaders STIBOR + 390 punkter.","body":"AT1-obligationerna har en evig löptid med en första inlösenrätt efter fem år, och de avses upptas till handel på Nasdaq Stockholm. SEB agerade sole manager i samband med obligationsemissionen.\n\nBorgo är ett kreditmarknadsbolag som står under Finansinspektionens tillsyn och som erbjuder bolån och sparkonton på den svenska marknaden. Bolånen distribueras via ICA Banken, Ikano Bank, Lån & Spar Bank, Sparbanken Syd, Söderberg & Partners och Ålandsbanken. Genom en struktur där flera starka aktörer går samman som ägare och förmedlare av krediter, kombinerat med moderna processer, skapas förutsättningar för att kunna erbjuda attraktiva bolån till konsumenter, samt attraktiva sparkonton, på ett ekonomiskt hållbart vis.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, Caroline Krassén, August Ahlin och Nilufer Nouri.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-borgo-vid-bolagets-forsta-emission-av-primarkapitalinstrument-at1/","date":"2026-01-29","month":1},{"year":2026,"client":"J Bil","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder J Bil vid förvärv av Appelskog Bil AB","caption":"Förvärv · 29 januari 2026","preamble":"Vinge företrädde köparen J Bil AB vid förvärv av samtliga aktier i Appelskog Bil AB.","body":"Vinges team leddes av Wibeke Sorling (Partner, M&A) med övriga teammedlemmar Marcus Bergström (M&A), Emma Näsholm (Employment) och Sofia Haggren (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-j-bil-vid-forvarv-av-appelskog-bil-ab/","date":"2026-01-29","month":1},{"year":2026,"client":"United Lithium Corp.","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt United Lithium Corp. i samband med förvärv av Swedish Minerals AB","caption":"Förvärv · 29 januari 2026","preamble":"United Lithium är ett prospekterings- och utvecklingsbolag med fokus på den globala efterfrågan på litium, uran och sällsynta jordartsmetaller.","body":"Bolaget inriktar sig på litium-, uran- och sällsynta jordartsmetallprojekt i politiskt säkra jurisdiktioner med avancerad infrastruktur som möjliggör snabb och kostnadseffektiv prospektering, utveckling och potentiella produktionsmöjligheter.\n\nSwedish Minerals urandivision kontrollerar en av de största privatägda uranportföljerna inom EU. Kombinationen av de två bolagen positionerar dem som en ledande nordiskbaserad prospektör som stödjer Europas accelererande omställning till ren energi och kärnkraftens renässans.\n\nVinges team bestod av Christina Kokko, Alva Chambert, Emelie Herlitz, Ulrich Ziche, Daniel Wendelsson, Johan Cederblad och Stina Larsson.\n\nLäs United Lithium:s pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-united-lithium-corp-i-samband-med-forvarv-av-swedish-minerals-ab/","date":"2026-01-29","month":1},{"year":2026,"client":"KEYTO Group","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Immaterialrätt","Kommersiella avtal","GDPR"],"title":"Vinge företräder KEYTO Group i samband med förvärvet av Hemfixarna","caption":"Förvärv · 29 januari 2026","preamble":"KEYTO fortsätter dess tillväxtresa genom att stärka sitt erbjudande i Sverige genom förvärvet av Hemfixarna Nordic AB.","body":"Vinges team bestod huvudsakligen av Jonas Bergström, Gustav Wahlberg och Ian Linde (M&A), William Karo Persson (Arbetsrätt), Ian Jonsson och Filippa Eriksson (IP), Hedvig Ekdahl och Avidh Tajik (Kommersiella avtal), Elis Allmark och Katja Häglund (IT & GDPR) samt Filippa Bergkvist (Transaction Support).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-keyto-group-i-samband-med-forvarvet-av-hemfixarna/","date":"2026-01-29","month":1},{"year":2026,"client":"Fidelio Capital","work":"Förvärv","disciplines":["M&A","Corporate Commercial","GDPR","Arbetsrätt","Regulatoriska tvister","Immaterialrätt"],"title":"Vinge har biträtt Fidelio Capital AB vid deras förvärv av Avy AB","caption":"Förvärv · 28 januari 2026","preamble":"Vinge har biträtt Fidelio Capital AB vid bolagets förvärv av Avy AB, ett ledande nordiskt teknikbolag inom digitala tjänster för fastighetsbranschen.","body":"Avy är känt för sin starka produkt och moderna teknologi med en tydlig satsning på data och AI för att förbättra drift, kommunikation och tjänster inom bostadsfastigheter. Produkten används av fastighetsägare i hela Norden och närmare 500 000 hushåll. Förvärvet är en del i Fidelios vision om att expandera verksamheten genom bland annat företagsförvärv och digital utveckling inom fastighetsförvaltning.\n\nVinges team bestod huvudsakligen av Jonas Bergström, Johanna Wiberg, Fredrik Eriksson Oppliger, Ellenor Eckerborn, Sara Eirefors (M&A), Matilda Persson, Siri Blomberg (Corporate Commercial), Katja Hägglund (GDPR), Johanna Fjellström, Linn Aho (Arbetsrätt), Nils Unckel, Karin Rättzén (Regulatory), Ian Jonson (IP), Jasmina Skandrani (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-fidelio-capital-ab-vid-deras-forvarv-av-avy-ab/","date":"2026-01-28","month":1},{"year":2026,"client":"Sveafastigheter","work":"Obligationsemission","disciplines":["Rekonstruktioner och obestånd","Bank och finans"],"title":"Vinge biträder Sveafastigheter AB (publ) vid etableringen av dess EMTN-program samt emission av obligationer om totalt EUR 300 miljoner","caption":"Obligationsemission · 23 januari 2026","preamble":"Vinge har biträtt Sveafastigheter AB (publ) som svensk legal rådgivare vid dess etablering av ett euro medium-term note-program (”EMTN-program”) med ett rambelopp om EUR 2 miljarder, samt dess emission av seniora icke-säkerställda obligationer om totalt EUR 300 miljoner under EMTN-prgrammet.","body":"Den 20 januari 2026 emitterade Sveafastigheter obligationer till ett belopp om 300 miljoner euro med en löptid om fem år och en kupong om 4,375 procent, varvid emissionslikviden delvis ska användas för att refinansiera Sveafastigheters utestående obligationer med ISIN SE0022244018. Goldman Sachs Bank Europe SE, J.P. Morgan SE, Danske Bank A/S, Nordea Bank Abp, Skandinaviska Enskilda Banken AB (publ) och Swedbank AB (publ) agerade som dealers i samband med transaktionen. Offering circular godkändes av Euronext Dublin den 5 januari 2026.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, August Ahlin, Calle Tengwall Pagels, William Carlberg Johansson och Ida Appelgren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sveafastigheter-ab-publ-vid-etableringen-av-dess-emtn-program-samt-emission-av-obligationer-om-totalt-eur-300-miljoner/","date":"2026-01-23","month":1},{"year":2026,"client":"EQT","work":"Samgående","disciplines":["Kapitalmarknad och publik M&A","M&A"],"title":"Vinge företräder EQT AB vid dess samgående med Coller Capital","caption":"Samgående · 22 januari 2026","preamble":"Vinge företräder EQT AB vid dess förvärv av Coller Capital, ett globalt bolag inom secondaries med närmare 50 USD miljarder i förvaltat kapital från institutionella, private wealth och försäkringsrelaterade kunder.","body":"Samgåendet stärker EQT:s ambition att bygga den mest attraktiva och storskaliga aktören på den privata marknaden, med branschledande avkastning och kundlösningar på global basis. Tillsammans kommer bolagen kunna stärka relationer och affärsmöjligheter med institutionella investerare, private wealth- och försäkringsrelaterade kunder, samtidigt som det skapar en global EQT-plattform inom private equity, infrastructure, real estate och secondaries.\n\nKöpeskillingen om 3,2 USD miljarder kommer att finansieras genom nyemitterade stamaktier i EQT, med upp till ytterligare 500 USD miljoner i tilläggsköpeskilling som finansieras kontant.\n\nVinges team bestod huvudsakligen av Sofie Bjärtun, Joel Magnusson, Maximilian Bengtsson (Kapitalmarknad & publik M&A), Marcus Glader, Noelia Martinez (Regulatory), Mattias Schömer och Morgan Ödman (Företagsbeskattning).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-eqt-ab-vid-dess-samgaende-med-coller-capital/","date":"2026-01-22","month":1},{"year":2026,"client":"Nordic Re-Finance","work":"Finansiering","disciplines":["M&A","Bank och finans"],"title":"Vinge företräder Nordic Re-Finance AB i samband med en svensk järnvägsfinansiering","caption":"Finansiering · 21 januari 2026","preamble":"Vinge har som svenskt legalt ombud företrätt Nordic Re-Finance AB, en ledande aktör inom lokleasingsektorn i Skandinavien, i samband med ingåendet av ett skuldpaket om totalt EUR 250M, fullt underwritat av Natixis CIB.","body":"Kreditfacilitetsavtalet möjliggör en refinansiering av bolagets befintliga skuldsättning, stödjer bolagets fortsatta tillväxtstrategi och inkluderar en grön facilitet som kommer möjliggöra en acceleration av bolagets elektrifieringsplaner och expansion till nya europeiska marknader.\n\nNordic Re-Finance AB stöds av Infranity, en fransk kapitalförvaltare specialiserad på investeringar inom hållbar infrastruktur.\n\nVinges team bestod huvudsakligen av Helena Göransson, Calle Tengwall Pagels och Rebecka Margolin (Bank och finans) samt Matthias Pannier, Sara Hammond (M&A) och Victor Ericsson (Skatt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-nordic-re-finance-ab-i-samband-med-en-svensk-jarnvagsfinansiering/","date":"2026-01-21","month":1},{"year":2026,"client":"Eleda","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Eleda i samband med Eleda Norge AS förvärv av Nettpartner Bane AS","caption":"Förvärv · 19 januari 2026","preamble":"Vinge, tillsammans med Advokatfirmaet Thommessen har biträtt Eleda i samband med Eleda Norge AS förvärv av Nettpartner Bane AS från Å Energi-ägda Nettpartner AS.","body":"Nettpartner Bane AS tillhandahåller kontaktlednings-, spår- och signaltjänster på järnvägs- och spårvägsmarknaden i Norge, med huvudfokus på kontaktledningar. Genom förvärvet breddar Eleda sitt erbjudande ytterligare inom järnvägsunderhåll i såväl Norge som Sverige. Slutförandet av transaktionen är föremål för sedvanliga villkor, inklusive godkännande från Konkurrensverket i Norge.\n\nVinges team bestod av Christina Kokko och Per Kling.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-eleda-i-samband-med-eleda-norge-as-forvarv-av-nettpartner-bane-as/","date":"2026-01-19","month":1},{"year":2026,"client":"KEYTO Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder KEYTO Group i samband med förvärvet av Smartify","caption":"Förvärv · 19 januari 2026","preamble":"KEYTO fortsätter dess tillväxtresa genom att stärka sitt erbjudande i Sverige genom förvärvet av Smartify Sverige AB.","body":"Vinges team bestod huvudsakligen av Jonas Bergström, Gustav Wahlberg och Ian Linde (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-keyto-group-i-samband-med-forvarvet-av-smartify/","date":"2026-01-19","month":1},{"year":2026,"client":"Orexo","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt Orexo i samband med avyttring av rättigheterna till Zubsolv i USA","caption":"Avyttring · 14 januari 2026","preamble":"Vinge har biträtt Orexo avseende svensk rätt i samband med avyttringen av de amerikanska rättigheterna avseende Zubsolv till Dexcel Pharma USA.","body":"Köpeskillingen uppgick till USD 91 miljoner. Orexo är därutöver berättigad till en tilläggsköpeskilling om upp till USD 16,8 miljoner, baserat på framtida nettoförsäljning av Zubsolv under 2026 och 2027. Steptoe LLP var huvudsakligt legalt ombud i samband med transaktionen och Vinge företrädde Orexo i förhållande till svensk rätt.\n\nVinges team bestod av Rikard Lindahl, Viveka Classon, Kim Bergman Aldevinge och Sara Stålebring.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-orexo-i-samband-med-avyttring-av-rattigheterna-till-zubsolv-i-usa/","date":"2026-01-14","month":1},{"year":2026,"client":"Revivo Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Revivo Group vid förvärv av Haapanen","caption":"Förvärv · 14 januari 2026","preamble":"Revivo Group, en heltäckande leverantör av kvalificerade ytbehandlingstjänster, förvärvar Haapanen, som är ett väletablerat finskt specialistbolag.","body":"Revivo Group, en heltäckande leverantör av kvalificerade ytbehandlingstjänster, förvärvar Haapanen, som är ett väletablerat finskt specialistbolag med lång erfarenhet av att leverera ytbehandlingstjänster till kunder inom tillverkningsindustrin, försvarssektorn och infrastruktur.\n\nVinges team bestod i huvudsak av Johan Winnerblad och Gustav Wahlberg.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-revivo-group-vid-forvarv-av-haapanen/","date":"2026-01-14","month":1},{"year":2026,"client":"Morrow Bank","work":"Samgående","disciplines":["Bank och finans","Finansiella tillståndsfrågor"],"title":"Vinge biträder Morrow Bank i samband med gränsöverskridande fusion och listbyte från Oslo Børs till Nasdaq Stockholm","caption":"Samgående · 12 januari 2026","preamble":"Vinge har biträtt Morrow Bank i samband med en omvänd gränsöverskridande fusion och noteringen på Nasdaq Stockholm, varvid Morrow Bank AB övertar Morrow Bank ASA, tidigare noterat på Oslo Børs. Vinge har tidigare hjälpt Morrow Bank att erhålla ett svenskt banktillstånd.","body":"– Noteringen speglar den omvandling som vi har genomfört under de senaste tre åren. Vi har byggt upp en skalbar plattform som levererar effektivitet, solid kreditprestanda och vinsttillväxt jämfört med våra nordiska konkurrenter inom konsumentfinansiering. Flytten till Sverige minskar kapitalkraven och säkerställer att vi konkurrerar på lika villkor, säger Øyvind Oanes, verkställande direktör för Morrow Bank.\n\nVinges team bestod i huvudsak av Emma Stuart-Beck, Elias Bohlin, Henrik Schön, Caroline Krassén, David Flodin, Ebba Gäbel och Felicia Sandén (Financial Services), Rikard Lindahl, Joel Magnusson, Carl Lexenberg och Julia Jönsson (Corporate Public), Siri Blomberg (IT&GDPR), Sam Seddigh, Simon Söderholm, Alice Göransson och Louisa Fagarasan (Arbetsrätt), Ian Jonsson och Filippa Eriksson (IP), Hedvig Ekdahl och Therese Baltzarsson (CC), Hedvig Merkel (Fastighet), Victor Ericsson, Maria Schultzberg och Vilma Henrikson (Skatt) och Diana Kanold och Alice Vångell (VDR).\n\nLäs klientens pressmeddelande här och här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-morrow-bank-i-samband-med-gransoverskridande-fusion-och-listbyte-fran-oslo-bors-till-nasdaq-stockholm/","date":"2026-01-12","month":1},{"year":2026,"client":"Dunlop Aircraft Tyres","work":"Obligationsemission","disciplines":["Bank och finans","Rekonstruktioner och obestånd"],"title":"Vinge biträder Dunlop Aircraft Tyres vid emission av seniora säkerställda obligationer om 93 miljoner USD","caption":"Obligationsemission · 8 januari 2026","preamble":"Vinge har biträtt Dunlop, i samband med dess emission av seniora säkerställda obligationer om 93 miljoner USD, inom ett totalt rambelopp om 120 miljoner USD.","body":"Dunlop är en ledande, oberoende global designer och leverantör av högkvalitativa flygplansdäck för de kommersiella, militära och fraktflygmarknaderna och är ett portföljbolag till Liberty Hall Capital Partners.\n\nObligationerna omfattas av ett gemensamt säkerhetspaket enligt ett borgenärsavtal (intercreditor agreement) och ett vattenfallsarrangemang med en supersenior kreditgivare.\n\nPareto Securities AB agerade sole bookrunner i transaktionen.\n\nVinges team bestod av Albert Wållgren, Arvid Weimers och William Carlberg Johansson","href":"https://www.vinge.se/uppdrag/vinge-bitrader-dunlop-aircraft-tyres-dunlop-vid-emission-av-seniora-sakerstallda-obligationer-om-93-miljoner-usd/","date":"2026-01-08","month":1},{"year":2025,"client":"Stockwik Förvaltning","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Stockwik Förvaltning vid förvärv av Labino","caption":"Förvärv · 19 december 2025","preamble":"Vinge biträder Stockwik Förvaltning vid förvärvet av Labino, en världsledande svensk tillverkare av industriella UV-ljusarmaturer.","body":"Vinge biträder Stockwik Förvaltning vid förvärvet av Labino, en världsledande svensk tillverkare av industriella UV-ljusarmaturer.\n\nStockwik Förvaltning har ingått avtal om att förvärva samtliga aktier i Labino, en världsledande svensk tillverkare av UV-ljusarmaturer för industriellt bruk, exempelvis för oförstörande provning inom flygindustrin. Transaktionen är villkorad av sedvanliga regulatoriska godkännanden.\n\nVinge, genom Johan Winnerblad, biträder Stockwik Förvaltning i förvärvet.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-stockwik-forvaltning-vid-forvarv-av-labino/","date":"2025-12-19","month":12},{"year":2025,"client":"Revivo Group","work":"Förvärv","disciplines":[],"title":"Vinge biträder Revivo Group vid förvärv av Nordisk Ytbehandling","caption":"Förvärv · 19 december 2025","preamble":"Vinge har biträtt Revivo Group vid förvärvet av Nordisk Ytbehandling, ett etablerat entreprenadbolag i Nyköping med specialistkompetens inom blästring samt rost- och brandskyddsmålning mot industri- och infrastruktursektorn.","body":"Revivo Group, en heltäckande leverantör av kvalificerade ytbehandlingstjänster, förvärvar Nordisk Ytbehandling, ett välrenommerat entreprenadbolag med säte i Nyköping specialiserat på blästring, rostskyddsmålning och brandskyddsmålning med en stabil kundbas inom industri och infrastruktur.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Gustav Wahlberg och David Olander.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-revivo-group-vid-forvarv-av-nordisk-ytbehandling/","date":"2025-12-19","month":12},{"year":2025,"client":"NCS Colour","work":"Avyttring","disciplines":["M&A"],"title":"Vinge har biträtt vid försäljning av NCS Colour","caption":"Avyttring · 19 december 2025","preamble":"Vinge har biträtt Sobro och övriga ägare när Helix Kapital går in som ny ägarpartner i NCS Colour tillsammans med ledningsteamet.","body":"Vinge har biträtt Sobro och övriga ägare när Helix Kapital går in som ny ägarpartner i NCS Colour tillsammans med ledningsteamet. NCS Colour grundades 1945 och har vuxit till den centrala branschstandarden för färgkommunikation inom färgindustrin, arkitekt- och designsektorn.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Nicolina Lavdas och Fanny Askelöf.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-vid-forsaljning-av-ncs-colour/","date":"2025-12-19","month":12},{"year":2025,"client":"Smart Eye Aktiebolag","work":"Obligationsemission","disciplines":["M&A"],"title":"Vinge biträder Smart Eye Aktiebolag (publ) vid bolagets första obligationsemission om 300 miljoner kronor","caption":"Obligationsemission · 12 december 2025","preamble":"Vinge har biträtt Smart Eye Aktiebolag (publ) (”Smart Eye”) i samband med bolagets första emission av icke-säkerställda seniora obligationer om 300 miljoner kronor, under ett ramverk om upp till 600 miljoner kronor. Skandinaviska Enskilda Banken AB (publ) agerade sole bookrunner i samband med emissionen.","body":"Smart Eye är ett svenskt teknikbolag inom Human Insight AI, teknik som förstår, stöder och förutspår mänskligt beteende i komplexa miljöer. Smart Eye:s teknik är integrerad i nästa generations fordon och erbjuder insikter inom bland annat fordons-, luftfarts- och rymdindustrin.\n\nObligationerna löper med rörlig ränta om 3M STIBOR plus + 700 baspunkter och har en löptid om tre år. Emissionslikviden kommer enligt obligationsvillkoren att användas för att (i) refinansiera befintliga skulder, och (ii) finansiera allmänna bolagsändamål (inklusive transaktionskostnader och förvärv). Smart Eye avser att uppta obligationerna till handel på Nasdaq Stockholms företagsobligationslista inom 12 månader från emissionsdagen och på Nasdaq Transfer Market inom 30 dagar.\n\nVinges team bestod av Anders Strid, Lionardo Ojeda, Edin Agic och Sofia Haggren.","href":"https://www.vinge.se/uppdrag/vinge-smart-eye-aktiebolag-publ-vid-bolagets-forsta-obligationsemission-om-300-miljoner-kronor/","date":"2025-12-12","month":12},{"year":2025,"client":"Nordstjernan","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Nordstjernan i samband med investeringen i Circura Group","caption":"Kapitalanskaffning · 12 december 2025","preamble":"Vinge har företrätt Nordstjernan i samband med investeringen i nyetablerade Circura Group.","body":"Circura Group, som består av Circura Sverige, Remount (Finland), Vokstr (Norge) och Circura Danmark, etableras av Adelis Equity Partners, Nordstjernan och entreprenörer och är en ledande nordisk aktör inom fastighetsunderhåll.\n\nCircura Group kommer att ha en omsättning på över 10 miljarder kronor och sysselsätta 2 500 medarbetare i de fyra nordiska länderna. Gruppen kommer att bibehålla sin decentraliserade modell i syfte att säkerställa kundfokus och lokalt entreprenörskap, samtidigt som man utnyttjar gemensamma resurser inom digitalisering och hållbarhet. Nordstjernan blir ny minoritetsägare i Circura Group och bidrar med branscherfarenhet och kapital för fortsatt tillväxt.\n\nVinges team bestod av Christina Kokko, Johanna Wiberg och Egil Svensson.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-nordstjernan-i-samband-med-investeringen-i-circura-group/","date":"2025-12-12","month":12},{"year":2025,"client":"Axcel VI och Currentum","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har företrätt Axcel VI och Currentum vid förvärv av Klarins Rör","caption":"Förvärv · 9 december 2025","preamble":"Vinge har företrätt Axcel VI och Currentum-koncernen vid förvärvet av Klarins Rör i Göteborg AB (”Klarins Rör”).","body":"Bolaget levererar tjänster relaterade till systemlösningar och projektering samt installation och driftsättning i Storgöteborg. Under 2024 omsatte Klarins Rör cirka 58 miljoner kronor.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Egil Svensson, Alexander Rüdén och Ian Linde (M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-axcel-vi-och-currentum-vid-forvarv-av-klarins-ror/","date":"2025-12-09","month":12},{"year":2025,"client":"RK Projektledning","work":"Avyttring","disciplines":["M&A"],"title":"Vinge har biträtt vid försäljningen av RK Projektledning till Qflow","caption":"Avyttring · 5 december 2025","preamble":"Vinge har biträtt säljarna i samband med försäljningen av samtliga aktier i RK Projektledning AB till Qflow Group.","body":"Vinge har biträtt säljarna i samband med försäljningen av samtliga aktier i RK Projektledning AB till Qflow Group. RK Projektledning tillhandahåller konsulttjänster och utbildningar inom infrastrukturbranschen.\n\nVinges team har huvudsakligen bestått av Anders Strid, Hanna Marberg (projektledning M&A) samt Amanda Stoltz (VDR).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-vid-forsaljningen-av-rk-projektledning-till-qflow/","date":"2025-12-05","month":12},{"year":2025,"client":"Inter IKEA","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Inter IKEA i samband med förvärv av skogsmark i Lettland och Litauen","caption":"Förvärv · 5 december 2025","preamble":"Vinge biträder IKEA Forestry Investment AB (ett bolag inom Inter IKEA-koncernen) vid förvärv av bolag i Lettland och Litauen från Dasos Timberland Fund II (en fond förvaltad av CapMan Natural Capital).","body":"Vinge biträder IKEA Forestry Investment AB (ett bolag inom Inter IKEA-koncernen) vid förvärv av bolag i Lettland och Litauen från Dasos Timberland Fund II (en fond förvaltad av CapMan Natural Capital). Bolagen äger totalt cirka 24.000 hektar mark utspritt över Lettland och Litauen. Förvärvet är villkorat av godkännande från berörda myndigheter.\n\nVinges team bestod av Björn Mullaart, Niklas Törnell och Jonatan Karlsson.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-inter-ikea-i-samband-med-forvarv-av-skogsmark-i-lettland-och-litauen/","date":"2025-12-05","month":12},{"year":2025,"client":"Valcon","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Valcon vid förvärvet av Bricobomba","caption":"Förvärv · 5 december 2025","preamble":"Bricobomba AB är ett svenskt företag med expertis inom data och AI. Förvärvet kommer att stärka Valcons kapacitet i Norden och ytterligare utöka företagets förmåga att leverera heltäckande data- och AI-baserade tjänster på paneuropeisk nivå.","body":"Vinges team bestod av Matthias Pannier, Manon de Cooman och Chris Bastholm (M&A), Sam Seddigh och William Karo Persson (Arbetsrätt), Hanna Kövamees (Fastighet), Mario Saad och Malin Dejke (Kommersiella avtal), Elis Allmark (IT) samt Ian Jonson (IP).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-valcon-vid-forvarvet-av-bricobomba/","date":"2025-12-05","month":12},{"year":2025,"client":"Bolero","work":"Avyttring","disciplines":["M&A","Kapitalmarknad och publik M&A","Bolagsrätt"],"title":"Vinge har biträtt Bolero i samband med försäljning av aktier i Ambea AB (publ)","caption":"Avyttring · 2 december 2025","preamble":"Vinge har biträtt Bolero Holdings S.à r.l. i samband med nedförsäljning av aktier i Ambea AB (publ) i en så kallad accelererad bookbuilding-process genomförd den 1 december 2025.","body":"Totalt placerades 4 165 262 aktier till ett pris om 137 kronor per aktie, motsvarande ett sammanlagt värde om cirka 570 miljoner kronor.\n\nVinges team bestod av Dain Hård Nevonen, Linnéa Dolk och Louise Nässén.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-bolero-i-samband-med-forsaljning-av-aktier-i-ambea-ab-publ-1/","date":"2025-12-02","month":12},{"year":2025,"client":"Segers Fabriker","work":"Avyttring","disciplines":["M&A","Kapitalmarknad och publik M&A","Bolagsrätt"],"title":"Vinge har biträtt vid försäljningen av Segers Fabriker","caption":"Avyttring · 2 december 2025","preamble":"Vinge har biträtt säljarna i samband med försäljningen av Segers Fabriker AB till Norrstigen. Segers är ett familjeföretag i Borås med verksamhet i Sverige, Estland och Ukraina, som sedan 1943 har utvecklat och sålt yrkeskläder för hotell, restaurang och vård","body":"Vinge har biträtt säljarna i samband med försäljningen av Segers Fabriker AB till Norrstigen. Segers är ett familjeföretag i Borås med verksamhet i Sverige, Estland och Ukraina, som sedan 1943 har utvecklat och sålt yrkeskläder för hotell, restaurang och vård.\n\nVinges team har huvudsakligen bestått av Anders Strid, Amelia Rihs (M&A projektledning), Carl Lönnqvist och Anna Högsten (IP), Fredrik Löwenclou (regulatoriskt) samt Amanda Stoltz (VDR).\n\nCensor M&A har agerat finansiell rådgivare och projektledare.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-vid-forsaljningen-av-segers-fabriker/","date":"2025-12-02","month":12},{"year":2025,"client":"Intea Fastigheter","work":"Kapitalanskaffning","disciplines":["M&A","Bolagsrätt"],"title":"Vinge har biträtt Intea Fastigheter i samband med en riktad emission om cirka 500 miljoner kronor","caption":"Kapitalanskaffning · 1 december 2025","preamble":"Vinge har biträtt fastighetsbolaget Intea Fastigheter AB (publ) i samband med en riktad emission av aktier av serie D varigenom bolaget tillförs cirka 500 miljoner kronor före transaktionskostnader. En del av emissionen förutsätter efterföljande godkännande vid en extra bolagsstämma.","body":"Bolaget avser att använda emissionslikviden för att kunna tillvarata affärsmöjligheter i nuvarande marknad och samtidigt bibehålla en flexibel och balanserad kapitalstruktur. Inteas aktier av serie B och D är noterade på Nasdaq Stockholm, Mid Cap.\n\nVinges team bestod av Linnéa Dolk, Maximilian Bengtsson och Hannah Mark.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-intea-fastigheter-i-samband-med-en-riktad-emission-om-cirka-500-miljoner-kronor/","date":"2025-12-01","month":12},{"year":2025,"client":"Kaelus","work":"Avyttring","disciplines":["M&A","EU‑ och konkurrensrätt"],"title":"Vinge biträder vid försäljning av Kaelus till Baylin Technologies","caption":"Avyttring · 1 december 2025","preamble":"Baylin Technologies, noterat vid Torontobörsen, har träffat avtal om att förvärva samtliga aktier i svenska Kaelus för cirka 285 milj kr i syfte att skapa en global ledare inom trådlös teknologi.","body":"Affären är villkorad av sedvanliga regulatoriska godkännanden.\n\nVinge, genom framförallt Johan Winnerblad, Per Kling, Emma Lundberg och Fredrik Hellström, har biträtt aktieägarna i Kaelus.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-kaelus-till-baylin-technologies/","date":"2025-12-01","month":12},{"year":2025,"client":"EcoDataCenters","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder vid datacenterleverantören EcoDataCenters emission av seniora icke-säkerställda obligationer om 500 miljoner kronor","caption":"Obligationsemission · 28 november 2025","preamble":"Vinge har biträtt ABG Sundal Collier i samband med EcoDC Holding AB (publ) emission av seniora icke-säkerställda obligationer om 500 miljoner kronor, inom ett ramverk om upp till 2 miljarder kronor.","body":"EcoDataCenter är en svensk datacenterleverantör med fokus på hållbara och säkra datacenterlösningar, och ägs av den svenska fondförvaltaren Areim AB.\n\nObligationerna löper med rörlig ränta och har en löptid om fyra år. EcoDataCenter avser att ansöka om notering av obligationerna på Nasdaq Transfer Market inom 60 dagar och sedan Nasdaq Stockholm inom 12 månader. Emissionslikviden kommer att användas för bland annat byggande av datacenter samt allmänna företagsändamål.\n\nVinges team bestod av Arvid Weimers, John Andrén och Olivia Carlsten.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-datacenterleverantoren-ecodatacenters-emission-av-seniora-icke-sakerstallda-obligationer-om-500-miljoner-kronor/","date":"2025-11-28","month":11},{"year":2025,"client":"Northmill Group","work":"Kapitalanskaffning","disciplines":["Bank och finans","Finansiella tillståndsfrågor"],"title":"Vinge har biträtt Northmill Group AB i samband med dess emission av supplementärkapitalinstrument (T2)","caption":"Kapitalanskaffning · 26 november 2025","preamble":"Vinge har biträtt Northmill Group AB vid dess framgångsrika emission av T2-obligationer om 100 miljoner kronor med en rörlig kupong om 3-månaders STIBOR + 650 punkter.","body":"Emissionen utgör Northmills första Tier 2-obligation och stärker dess kapitalbas samt lägger grunden för fortsatt lönsam tillväxt. Kapitalet gör det också möjligt att uppnå tidigare kommunicerade finansiella mål och understryker bankens ställning som en innovativ aktör. Northmill Group är moderbolag till Northmill Bank, en svensk utmanarbank som erbjuder finansiella tjänster för både privatpersoner och företag.\n\nDNB Carnegie agerade sole bookrunner i samband med obligationsemissionen.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda, Caroline Krassén och Nilufer Nouri.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-northmill-group-ab-i-samband-med-dess-emission-av-sekundarkapitalinstrument-t2/","date":"2025-11-26","month":11},{"year":2025,"client":"Fortinova Fastigheter","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","Arbetsrätt","Fastigheter och Entreprenad","Immaterialrätt"],"title":"Vinge har företrätt Fortinova Fastigheter i samband med dess listbyte till Nasdaq Stockholm","caption":"Övrigt · 19 november 2025","preamble":"Vinge har företrätt Fortinova Fastigheter AB (publ) i samband med dess listbyte från Nasdaq First North Premier Growth Market till Nasdaq Stockholm. Prospektet offentliggjordes den 12 november 2025 och handeln på Nasdaq Stockholm inleddes den 19 november 2025, på dagen fem år sedan första noteringen.","body":"Fortinova är ett expansivt fastighetsbolag med säte i Varberg och vars affärsidé sedan starten 2010 har bestått av att förvärva, utveckla och förvalta främst bostadsfastigheter med dokumenterade positiva kassaflöden. Koncernen har en målsättning att generera positiv avkastning över tid, oberoende av marknadens utveckling. Fortinova har ett geografiskt fokus på tillväxtkommuner i västra Sverige som bedöms ha en god tillväxtprofil och är attraktiva orter att bo, arbeta och leva i. Bolagets fastighetsportfölj har ett totalt fastighetsvärde uppgående till cirka 5,1 miljarder kronor.\n\nVinges team har bestått av Anders Strid, Wibeke Sorling, Edin Agic, Amelia Rihs, Sofia Haggren, Marcus Bergström och Oliwer Vidarsson (Kapitalmarknad och Publik M&A), Adam Loewenstein (Fastighet), Michaela Örtberg (IPR) samt Amanda Stoltz (VDR).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-fortinova-fastigheter-i-samband-med-dess-listbyte-till-nasdaq-stockholm/","date":"2025-11-19","month":11},{"year":2025,"client":"NanoTemper Technologies","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge rådgivare vid NanoTemper Technologies investering i Envue Technologies","caption":"Kapitalanskaffning · 14 november 2025","preamble":"Vinge var svensk rådgivare på uppdrag av Honert när NanoTemper Technologies GmbH förvärvade aktier i det svenska start-up-företaget Envue Technologies.","body":"NanoTemper Technologies är ett bioteknikföretag med huvudkontor i München och Envue Technologies är ett Göteborgsbaserat företag specialiserade på nanoteknik.\n\nVinges team leddes av Wibeke Sorling (partner, M&A) med senior associate Hanna Jansson som projektledare. Honert advokatbyrås team från Münchenkontoret leddes av Dr. Kai-Klemens Wehlage och Judith Kutter.","href":"https://www.vinge.se/uppdrag/vinge-radgivare-vid-nanotemper-technologies-investering-i-envue-technologies/","date":"2025-11-14","month":11},{"year":2025,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","Immaterialrätt","Corporate Commercial","Arbetsrätt"],"title":"Vinge har biträtt Lagercrantz Group vid förvärv av Sit Right och Enskede Hydraul","caption":"Förvärv · 7 november 2025","preamble":"Lagercrantz Group AB (publ) har förvärvat 70 procent av aktierna i de två svenska bolagen Sit Right AB och Enskede Hydraul AB, ledande aktörer inom produkter respektive eftermarknadsdelar för skogs- och entreprenadmaskiner i Europa.","body":"Tillsammans omsätter bolagen drygt 150 MSEK med god lönsamhet.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Michella Lina Said, Josef Groow, Hedvig Ekdahl, Alva Skott, Sara Link och Agnes Pigg.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-lagercrantz-group-vid-forvarv-av-sit-right-och-enskede-hydraul/","date":"2025-11-07","month":11},{"year":2025,"client":"Grundarna av NOOS Digital","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder grundarna av NOOS Digital i samband med samgående med Rocket Revenue och 56K Digital","caption":"Kapitalanskaffning · 4 november 2025","preamble":"Efter samgåendet mellan Rocket Revenue och 56K Digital tidigare i år, tar gruppen nästa steg genom att förena sig med NOOS Digital. Tillsammans bildar de tre bolagen en av Nordens mest heltäckande partners för digital transformation och affärsdriven tillväxt.","body":"NOOS Digital har byggt en stark position som strategisk rådgivare till flera av Nordens ledande retailbolag och etablerat sig på marknaden som en av regionens mest nytänkande och snabbväxande managementkonsulter inom digital handel. Tillsammans med Rocket Revenues och 56K:s samlade expertis inom marknadsföring, teknik, data och kreativitet formas en ny aktör som kan driva tillväxtinitiativ genom hela värdekedjan. Med närmare 100 experter inom strategi, analys, tech, performance och kreativ utveckling – baserade i Stockholm, Göteborg, Borås och Helsingborg – siktar gruppen på att sätta en ny standard för rådgivning och tillväxt inom digitala affärer.\n\nVinge, genom Viktor Ramhult, företrädde grundarna av NOOS Digital i samband med samgåendet.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-grundarna-av-noos-digital-i-samband-med-samgaende-med-rocket-revenue-och-56k-digital/","date":"2025-11-04","month":11},{"year":2025,"client":"Setra Trävaror","work":"Avyttring","disciplines":["M&A","EU‑ och konkurrensrätt","Corporate Commercial","Fastigheter och Entreprenad","Carve-Outs"],"title":"Vinge biträder Setra Trävaror vid försäljning av Malå Såg till HS Timber","caption":"Avyttring · 29 oktober 2025","preamble":"Det österrikiska företaget HS Timber Group har tecknat avtal om att förvärva 100 procent av aktierna i det svenska träförädlingsföretaget Malå Såg AB från Setra Trävaror AB, ett dotterbolag till Setra Group AB. Affären är fortfarande föremål för godkännande från berörda myndigheter.","body":"Vinges team bestod i huvudsak av Matthias Pannier, Johan Winnerblad, Philip Moré, Ellenor Eckerborn, Mathilda Persson, Siri Blomberg, Madelene Andersson och Alva Chambert.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-setra-travaror-vid-forsaljning-av-mala-sag-till-hs-timber/","date":"2025-10-29","month":10},{"year":2025,"client":"Advania","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Corporate Commercial"],"title":"Vinge har rådgett Advania i förvärvet av Visuell Teknik","caption":"Förvärv · 28 oktober 2025","preamble":"Advania har förvärvat Visuell Teknik, en svensk leverantör av audiovisuella lösningar och mötesteknik.","body":"Förvärvet stärker Advanias erbjudande inom arbetsplats- och samarbetstjänster och utökar bolagets förmåga att leverera integrerade AV-lösningar till företagskunder och offentlig sektor i hela Sverige.\n\nVisuell Teknik tillför etablerad expertis inom design, installation och support av moderna AV miljöer för kontor, mötesrum och offentliga miljöer. Genom att ansluta till Advania Group integreras Visuell Tekniks team och portfölj i Advanias bredare end to end erbjudande för den digitala arbetsplatsen, vilket ökar leveranskapaciteten och utökar täckningen av tjänster nationellt.\n\nVinges team bestod huvudsakligen av Peter Sundgren, Vilhelm Rondahl och Sara Egelberg (M&A), Emil Lindwall (Arbetsrätt), Carla Håkansson och Hanna Kövamees (Corporate Commercial) och Filippa Bergkvist (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-har-radgett-advania-i-forvarvet-av-visuell-teknik/","date":"2025-10-28","month":10},{"year":2025,"client":"Acrinova","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Acrinova i samband med frivilligt inlösenerbjudande","caption":"Övrigt · 27 oktober 2025","preamble":"Vinge har biträtt Acrinova AB (publ) i samband med dess frivilliga inlösenerbjudande. Erbjudandet omfattade cirka en tredjedel av aktierna i Acrinova och anslutningsgraden uppgick till cirka 97,34 procent, vilket motsvarar en inlösenlikvid om cirka 367,4 miljoner kronor.","body":"Acrinova är ett entreprenörsdrivet fastighetsbolag verksamt i södra Sverige och med tyngdpunkt på Öresundsregionen. Acrinovas fastighetsbestånd utvecklas genom förvärv, projektutveckling och förädling. Acrinovas aktier är noterade på Nasdaq Stockholm.\n\nVinges team har huvudsakligen bestått av Christian Lindhé och Michaela Ådén.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-acrinova-i-samband-med-frivilligt-inlosenerbjudande/","date":"2025-10-27","month":10},{"year":2025,"client":"Revivo Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Revivo Group vid förvärv av Lejon Entreprenad","caption":"Förvärv · 27 oktober 2025","preamble":"Revivo Group, en heltäckande leverantör av kvalificerade ytbehandlingstjänster, förvärvar Lejon Entreprenad, ett väletablerat specialistföretag som erbjuder kvalificerade tjänster inom ytbehandling, inklusive industrimålning, rostskyddsmålning och FROSIO-inspektioner.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Gustav Wahlberg, Ida Pettersson och Isabelle Ivarsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-revivo-group-vid-forvarv-av-lejon-entreprenad/","date":"2025-10-27","month":10},{"year":2025,"client":"Ingka Investments","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad","Tvistlösning","Företagsbeskattning"],"title":"Vinge har företrätt Ingka Investments i samband med dess största skogsmarkförvärv","caption":"Förvärv · 20 oktober 2025","preamble":"Ingka Investments, investeringsbolag inom Ingka Group (världens största IKEA-återförsäljare), har ingått avtal om att förvärva cirka 153 000 hektar mark, främst skogsmark, från Södra, Sveriges största skogsägareförening.","body":"Ingka Group är verksamt på 31 marknader och står för 87 % av IKEA:s globala försäljning. Till skillnad från vanliga företag ägs koncernen av en stiftelse med välgörenhetsändamål, vilket innebär att vinsten återinvesteras i verksamheten, vilket möjliggör självfinansierade, långsiktiga investeringar.\n\nTransaktionen omfattar Södras hela nuvarande innehav i Lettland och Estland och värderas till 720 miljoner euro, motsvarande cirka 8 miljarder kronor. Förvärvet är villkorat av godkännande från berörda myndigheter i Lettland och Estland.\n\nVinges team bestod huvudsakligen av Sofie Nordgren, Tilda Hall, Jerker Kjellander och Victor Ericsson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-ingka-investments-i-samband-med-dess-storsta-skogsmarkforvarv/","date":"2025-10-20","month":10},{"year":2025,"client":"Procuritas","work":"Förvärv","disciplines":["M&A","Bank och finans","Corporate Commercial","Fastigheter och Entreprenad","Arbetsrätt","EU‑ och konkurrensrätt"],"title":"Vinge företräder Procuritas vid förvärvet av Parkman","caption":"Förvärv · 20 oktober 2025","preamble":"Vinge har företrätt Procuritas Capital Investors VII (“Procuritas”) i samband med förvärvet av Parkman i Sverige AB (“Parkman”), ett växande svenskt teknikbaserat parkeringsföretag som tillhandahåller parkeringslösningar. I samband med transaktionen blir även Indigo Management AS minoritetsägare i bolaget.","body":"Parkman är ett svenskt företag som erbjuder kompletta parkeringslösningar med ett brett utbud av tekniska och operativa tjänster. Företaget betjänar en mångsidig portfölj av fastigheter, inklusive köpcentrum, kontor och bostadsområden.\n\nParkman omsatte 610 MSEK under 2024. Företaget har cirka 85 heltidsanställda och 50 deltidsanställda.\n\nVinges team bestod av Jonas Johansson, Desirée Hagenfeldt, Linus Adolfsson och Ian Linde (M&A), Helena Göransson, Arvid Weimers, Calle Tengwall Pagels, Ida Appelgren, William Carlberg Johansson (Bank och finans), Christoffer Nordin, Gabriel Pålsson och Filippa Eriksson (Corporate Commercial), Simon Gille-Johnson och Wilma Hellman (Fastigheter och entreprenad), William Karo Persson (Arbetsrätt), Fredrik Hellström och Hilda Ivarsson (EU- och konkurrensrätt) samt Filippa Bergkvist (Transaction Support).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-procuritas-vid-forvarvet-av-parkman/","date":"2025-10-20","month":10},{"year":2025,"client":"Eleda","work":"Förvärv","disciplines":["M&A","FDI","Bank och finans","Arbetsrätt","Fastigheter och Entreprenad","GDPR"],"title":"Vinge har företrätt Eleda i samband med förvärv av Nordic Infrastructure Group AS (“Qben Rail”)","caption":"Förvärv · 17 oktober 2025","preamble":"Qben Infra AB och ININ Group AS, som till största delen ägs av Qben Infra AB, har ingått ett aktieöverlåtelseavtal med Eleda genom Eledas dotterbolag Eleda Norge AS (”Eleda”), för att avyttra Qben Rail-plattformen till Eleda för ett totalt företagsvärde på upp till 850 miljoner NOK, inklusive en tilläggsköpeskilling på upp till 65 miljoner NOK.","body":"Slutförandet av transaktionen är föremål för sedvanliga villkor, inklusive godkännande från Inspektionen för strategiska produkter i Sverige och Konkurrensverket i Norge.\n\nKöparen, Eleda, är en ledande och snabbt växande leverantör av infrastrukturlösningar i Norden, som tillhandahåller tjänster inom utvalda nischer inom eldistribution, teknik, vatten och transport. Eleda strävar efter att skapa värde genom att identifiera och utveckla högkvalitativa, lokala, marknadsledande företag som levererar infrastrukturtjänster till samhället.\n\nQben Rail-plattformen leds av Nordic Infrastructure Group AS, ett ledande norskt infrastrukturbolag specialiserat på järnvägsinriktad byggnation, kompetens och tjänsteleverans. Plattformen har verksamhet i Norge och Sverige. Qben Rails intäkter för de senaste tolv månaderna är på cirka 1 280 miljoner NOK med ett justerat EBITA på cirka 97 miljoner NOK.\n\nVinges team bestod huvudsakligen av Christina Kokko, Johanna Wiberg, Philip Moré, Jonatan Stentorp, Anna Neubüser och Lina Björkman (M&A), Daniel Wendelsson och David Olander (FDI), Nilufer Nouri (Bank och finans), Simon Söderholm och Louisa Fagarasan (Arbetsrätt), Wilma Hellman (Fastighet), Nicklas Thorgerzon (GDPR) och Johanna Engström (Transaction Support Coordinator).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-i-samband-med-forvarv-av-nordic-infrastructure-group-as-qben-rail/","date":"2025-10-17","month":10},{"year":2025,"client":"FAM","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad","Finansiella tillståndsfrågor"],"title":"Vinge har företrätt FAM AB vid förvärv av Aktiebolaget Näckström","caption":"Förvärv · 16 oktober 2025","preamble":"Vinge har företrätt FAM AB vid förvärvet av Aktiebolaget Näckström från Vectura Fastigheter AB. Aktiebolaget Näckströms huvudsakliga tillgångar utgörs av fastigheten Stockholm Näckström 6 (Arsenalsgatan 8) och Villa Täcka udden.","body":"Det totala fastighetsvärdet uppgår till 1,4 miljarder kronor och transaktionen förväntas slutföras under fjärde kvartalet 2025.\n\nVinges team består huvudsakligen av Jonas Johansson (M&A), Niclas Winnberg, Simon Gille-Johnson, Madelene Andersson, Hanna Kövamees (Fastighet), Helena Göransson, Kamyar Najmi och Wilma Hellman (Finansiering).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-fam-ab-vid-forvarv-av-aktiebolaget-nackstrom/","date":"2025-10-16","month":10},{"year":2025,"client":"FAM","work":"Kapitalanskaffning","disciplines":["M&A","FDI"],"title":"Vinge har företrätt FAM i samband med investering i GreenIron","caption":"Kapitalanskaffning · 16 oktober 2025","preamble":"Vinge har företrätt FAM AB, som ägs av Wallenbergstiftelserna, i samband med investering i GreenIron H2 AB. Genom rundan reste GreenIron totalt 125 miljoner kronor i ytterligare finansiering från befintliga aktieägare, varvid FAM nu blir bolagets största ägare.","body":"GreenIron är ett svenskt företag fokuserat på att fossilfritt och kostnadseffektivt fullt reducera metalloxider. Bolaget är i slutskedet före kommersiell drift med driftsättning av sin första produktionsanläggning i Sandviken.\n\nVinges team har huvudsakligen bestått av Jonas Johansson, Maria Dahlin Kolvik och Alva Thörn (M&A) samt Sebastian Örndahl, Fredrik Hellström and Hampus Peterson (FDI).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-fam-i-samband-med-investering-i-greeniron-1/","date":"2025-10-16","month":10},{"year":2025,"client":"Westcomp","work":"Avyttring","disciplines":["M&A","Bolagsrätt"],"title":"Vinge har biträtt vid försäljningen av Westcomp AB till Tången Industrikapital AB","caption":"Avyttring · 15 oktober 2025","preamble":"Genom transaktionen förvärvar Tången cirka 91 procent av aktierna i Westcomp.","body":"Westcomp är leverantör av elektronikkomponenter. Säljarna är fortsatt engagerade i verksamheten och kommer fortsatt att bidra till bolagets utveckling.\n\nVinges team bestod i huvudsak av Magnus Pauli, Martin Madsen Svanberg, Emma Jansson och Fredrik Löwenclou.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-vid-forsaljningen-av-westcomp-ab-till-tangen-industrikapital-ab/","date":"2025-10-15","month":10},{"year":2025,"client":"Del av sitt innehav","work":"Avyttring","disciplines":["M&A","EU‑ och konkurrensrätt","Arbetsrätt","Bank och finans","Bolagsrätt"],"title":"Vinge har biträtt i samband med Stirling Square Capital Partners (“SSCP”) försäljning av del av sitt innehav i Infobric till KKR","caption":"Avyttring · 15 oktober 2025","preamble":"Genom transaktionen blir KKR en betydande ägare samtidigt som SSCP fortsatt kommer att vara största ägare.","body":"Infobric är ett svenskt mjukvaruföretag som utvecklar IT-lösningar för byggbranschen, särskilt känt för sina system för inpassering och närvaroregistrering. Företaget grundades 2004 i Jönköping.\n\nTransaktionen är villkorad av sedvanliga myndighetstillstånd.\n\nVinges team bestod i huvudsak av Magnus Pauli, Anna Palmérus, Petronella Hallberg, Anna Ståhlklo, Rebecka Margolin, Marcus Bergström, Filippa Berggren och Fredrik Löwenclou.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-i-samband-med-stirling-square-capital-partners-sscp-forsaljning-av-del-av-sitt-innehav-i-infobric-till-kkr/","date":"2025-10-15","month":10},{"year":2025,"client":"ABG Sundal Collier","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder ABG Sundal Collier vid Conaptos emission av ytterligare seniora säkerställda obligationer om 1 miljard kronor","caption":"Obligationsemission · 15 oktober 2025","preamble":"Vinge har biträtt ABG Sundal Collier i samband med Conapto Holding AB (publ) emission av ytterligare seniora säkerställda obligationer om 1 miljard kronor, samt parallella skriftliga förfarande för ökning av ramverket för obligationerna till 2 miljarder kronor.","body":"Obligationerna löper med rörlig ränta och har en löptid om tre år. Emissionslikviden kommer att användas för investeringar i bolagets datacenter. Conapto, ett portföljbolag till den europeiska infrastrukturfonden Marguerite, är en ledande leverantör av datacenter colocation.\n\nVinges team bestod av Mikael Ståhl, Arvid Weimers, August Ahlin och Nilufer Nouri.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-abg-sundal-collier-vid-conaptos-emission-av-ytterligare-seniora-sakerstallda-obligationer-om-1-miljard-kronor/","date":"2025-10-15","month":10},{"year":2025,"client":"Glesys","work":"Förvärv","disciplines":["M&A","IT, Telekom och Outsourcing","Carve-Outs"],"title":"Vinge biträder Glesys vid förvärv i Finland","caption":"Förvärv · 14 oktober 2025","preamble":"Glesys, en ledande nordisk leverantör av moln- och IaaS-tjänster (Infrastructure as a Service), förvärvar Vernes verksamhet inom managed private cloud i Finland, där datacenteranläggningarna i Pori och Tammerfors ingår.","body":"Genom affären tar Glesys ett avgörande steg i att bygga ut sin infrastruktur och sitt tjänsteutbud i Finland och Norden.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Mathilda Persson, Eva Fredrikson, Siri Blomberg och Linn Aho.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-glesys-vid-forvarv-i-finland/","date":"2025-10-14","month":10},{"year":2025,"client":"Sertion","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","Bank och finans","Finansiella tillståndsfrågor","Arbetsrätt","Fastigheter och Entreprenad","Miljörätt","Trade Compliance"],"title":"Vinge har företrätt Sertion i samband med förvärvet av Kiefer System Group","caption":"Förvärv · 10 oktober 2025","preamble":"Vinge har företrätt Sertion AB (”Sertion”) i samband med förvärvet av Kiefer System Group. Genom förvärvet förstärker Sertion sin position som en ledande internationell infrastruktur- och rörledningspartner inom värme- och sanitetsprojekt, teknisk infrastruktur och industriella rörledningar.","body":"Kiefer System Group, bestående av Kiefers System Svets Aktiebolag, Kiefer Systemtools AB and Uppsala Mekaniska Maskinbearbetning UMB AB, har unik expertis inom orbitalsvetsning, specialmaskiner och platsinstallationer för energi-, läkemedels- och processindustrin.\n\nVinges team bestod av Christina Kokko, Desirée Hagenfeldt, Amanda Steen och Kabbo Iftekhayer (M&A), Ludvig Montan (Commercial Agreements), William Carlberg Johansson (Banking and Finance), Daniel Wendelsson, Sebastian Örndahl och Hanna Lemne (Regulatory), William Karo Persson (Employment), Wilma Hellman (Real Estate and Environment), Hayaat Ibrahim (Compliance) samt Johanna Engström (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-sertion-i-samband-med-forvarvet-av-kiefer-system-group/","date":"2025-10-10","month":10},{"year":2025,"client":"Main Capital och Aritma","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Immaterialrätt"],"title":"Vinge företräder Main Capital och Aritma vid förvärvet av Programekonomi","caption":"Förvärv · 9 oktober 2025","preamble":"Vinge har företrätt Aritma International AS (“Aritma”), en norsk leverantör av mjukvara för bankintegration och finansiell automatisering, vid förvärvet av Programekonomi Svenska Aktiebolag.","body":"Förvärvet kompletterar och utökar Aritmas erbjudande och ligger väl i linje med bolagets expansionsstrategi på den nordiska marknaden för finansiell automatisering och ERP-anslutning, vilket bedöms stärka koncernens position i Norden.\n\nProgramekonomi Svenska Aktiebolag är ett mjukvarubolag som tillhandahåller Swebase, en tilläggsmodul för Microsoft Business Central, som möjliggör optimering av affärs- och beslutsprocesser i Microsoft Business Central genom att erbjuda företag funktioner så som hantering av bankfiler, dokumenthantering och förbättrad säkerhet. Genom förvärvet kompletterar Aritma sina lösningar för bankintegration och finansiell automatisering, samtidigt som bolaget breddar sitt erbjudande inom Microsoft Business Central med både produkt- och konsultkompetens.\n\nVinges team bestod av Filip Öhrner, Olivia Altheden, Alex Forsberg, Nora Karlsson (M&A), Alice Göransson (arbetsrätt) och Ian Jonson (IP).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-och-aritma-vid-forvarvet-av-programekonomi/","date":"2025-10-09","month":10},{"year":2025,"client":"Verisure","work":"Börsnotering","disciplines":["Kapitalmarknad och publik M&A","M&A","Bank och finans","FDI","Kommersiella avtal","Immaterialrätt","Arbetsrätt"],"title":"Vinge har företrätt Verisure i samband med dess börsnotering på Nasdaq Stockholm","caption":"Börsnotering · 8 oktober 2025","preamble":"Vinge har företrätt Verisure plc (“Verisure”) i samband med dess börsnotering på Nasdaq Stockholm. Efter att prospektet publicerades den 29 september 2025 inleddes handeln i Verisures aktier idag den 8 oktober 2025.","body":"Priset i erbjudandet uppgick till 13,25 euro per aktie, vilket motsvarar ett totalt börsvärde för Verisure om 13,7 miljarder euro (cirka 150 miljarder kronor) efter genomförandet av noteringen. Erbjudandet, som omfattade ett erbjudande till allmänheten i Sverige och ett erbjudande till institutionella investerare i Sverige och utomlands, bestod av en emission av nya aktier samt en försäljning av befintliga aktier. Det totala värdet av erbjudandet, förutsatt att övertilldelningsoptionen utnyttjas till fullo, uppgår till cirka 3,6 miljarder euro (cirka 39 miljarder kronor), vilket gör det till den största börsnoteringen i Sverige på 25 år och den största börsnoteringen i Europa på tre år.\n\nVerisure är den ledande leverantören av professionellt övervakade säkerhetstjänster i Europa och Latinamerika. Per 30 juni 2025 satte mer än 5,8 miljoner familjer och mindre företag sin tillit till Bolaget. Verisure erbjuder professionell installation, 24/7 övervakning, expertverifiering och svar, kundvård, underhåll och teknisk support som skyddar mot intrång, inbrott, brand, fysiska angrepp, stöld, livshotande nödsituationer och andra faror. Cirka 90 % av de totala intäkterna för räkenskapsåret som slutade 31 december 2024 var återkommande.\n\nVinges team bestod huvudsakligen av Jesper Schönbeck, Amanda Knutsson, David Andersson, Anna Svensson, Lorin Arabi, Filip Magnusson, Carl Lexenberg och Vilma Henricsson (Kapitalmarknad och publik M&A), Jonas Bergström, Filip Öhrner, Robin Sultani, Fredrik Eriksson Oppliger och Saga Meyer Viklund (Corporate), Albert Wållgren, Linn Adelwald, Felix Möller och Rebecka Margolin (Bank och finans), Daniel Wendelsson och Fredrik Hellström (FDI), Martin Boström, Gabriel Pålsson och Ian Jonson (Kommersiella avtal och immaterialrätt) och Sam Seddigh (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-verisure-i-samband-med-dess-borsnotering-pa-nasdaq-stockholm/","date":"2025-10-08","month":10},{"year":2025,"client":"Advania","work":"Förvärv","disciplines":["M&A","GDPR","FDI","EU‑ och konkurrensrätt"],"title":"Vinge har företrätt Advania i förvärvet av smartvokat","caption":"Förvärv · 8 oktober 2025","preamble":"smartvokat GmbH, ett tyskt konsultföretag specialiserat på digital transformation inom juridik, riskhantering och regelefterlevnad, kommer att ingå i Advanias affärsenhet Transformation & Automation.","body":"Genom förvärvet stärker Advania sitt managed services-erbjudande och sin transformationsexpertis.\n\nVinges team bestod av Peter Sundgren, Ulrich Ziche, Jonatan Stentorp, Sara Eirefors och Hanna Stamer (M&A), Nicklas Thorgerzon (GDPR), David Olander (FDI och konkurrensrätt) och Emelie Schoning (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-advania-i-forvarvet-av-smartvokat/","date":"2025-10-08","month":10},{"year":2025,"client":"Egetis Therapeutics","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Egetis Therapeutics i samband med en riktad nyemission","caption":"Kapitalanskaffning · 6 oktober 2025","preamble":"Vinge har företrätt Egetis Therapeutics AB (publ) (”Egetis Therapeutics”), noterat på Nasdaq Stockholm, i samband med en riktad nyemission varigenom Egetis Therapeutics tillfördes cirka 183 miljoner kronor före transaktionskostnader.","body":"Emissionen riktades till ett antal internationella och svenska institutionella investerare på grundval av ett accelererat bookbuilding-förfarande.\n\nVinges team bestod av Dain Hård Nevonen, Lorin Arabi och Karin Karsten.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-egetis-therapeutics-i-samband-med-en-riktad-nyemission-1/","date":"2025-10-06","month":10},{"year":2025,"client":"Agilitas","work":"Obligationsemission","disciplines":["M&A","Bank och finans","Corporate Commercial","Fastigheter och Entreprenad","FDI"],"title":"Vinge arbetade med fonder rådgivna av Agilitas vid förvärvet av Vivicta (tidigare Tietoevry Tech Services), inklusive vid emissionen av seniora säkerställda obligationer och ingåendet av en supersenior RCF","caption":"Obligationsemission · 3 oktober 2025","preamble":"Vinge, tillsammans med O’Melveny som lead counsel och Avance, har arbetat med fonder rådgivna av Agilitas Private Equity LLP (“Agilitas”), ett paneuropeiskt private equity-bolag inriktat på medelstora företag, i samband med deras förvärv av Vivicta.","body":"Förvärvet offentliggjordes den 24 mars 2025 och slutfördes den 2 september 2025.\n\nSkuldfinansieringen bestod av fullt garanterade seniora säkerställda obligationer på totalt 225 miljoner euro, tillsammans med en supersenior revolverande kreditfacilitet.\n\nVivicta betjänar kunder med en affärsmodell som främst fokuserar på outsourcing inom molntjänster, datalagring, applikationer och infrastruktur, och har över 7 000 anställda globalt. Som ett fristående företag framöver byter Tietoevry Tech Services namn till Vivicta.\n\nVinges team bestod av bland annat Christina Kokko, Per Kling, Vilhelm Rondahl, Saga Meyer Viklund och Linn Aho (M&A), Arvid Weimers, Felix Möller, Nour Makie, August Ahlin, William Carlberg Johansson och Julia Gudmundsson (Bank och finans), Martin Boström, Fredrika Hjelmberg, Carla Håkansson och Mario Saad (Corporate Commercial), Madelene Andersson (Fastigheter), Daniel Wendelsson, Fredrik Hellström och Hilda Ivarsson (FDI).","href":"https://www.vinge.se/uppdrag/vinge-arbetade-med-fonder-radgivna-av-agilitas-vid-forvarvet-av-vivicta-tidigare-tietoevry-tech-services-inklusive-vid-emissionen-av-seniora-sakerstallda-obligationer-och-ingaendet-av-en-supersenior-rcf/","date":"2025-10-03","month":10},{"year":2025,"client":"Hansa Biopharma","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har biträtt Hansa Biopharma i samband med en riktad nyemission om cirka 671,5 miljoner kronor","caption":"Kapitalanskaffning · 3 oktober 2025","preamble":"Vinge har biträtt Hansa Biopharma AB (publ) i samband med en riktad nyemission varigenom bolaget tillförs cirka 671,5 miljoner kronor före transaktionskostnader.","body":"Hansa Biopharma AB är ett biofarmabolag i kommersiell fas som utvecklar innovativa, livräddande och livsförändrande behandlingar för patienter med sällsynta immunologiska sjukdomstillstånd. Bolaget är noterat på Nasdaq Stockholm.\n\nVinges team har bestått av Dain Hård Nevonen, Joel Magnusson, Louise Nässén, Joacim Malmqvist och Rebecka Björnestedt.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-hansa-biopharma-i-samband-med-en-riktad-nyemission-om-cirka-671-5-miljoner-kronor/","date":"2025-10-03","month":10},{"year":2025,"client":"Advania","work":"Förvärv","disciplines":[],"title":"Vinge företräder Advania vid förvärvet av atNorth HPC AB","caption":"Förvärv · 3 oktober 2025","preamble":"Vinge har företrätt Advania, ett av de ledande IT-företagen i Norden, vid förvärvet av atNorth HPC AB. Förvärvet stärker Advanias satsning inom high-performance computing (HPC).","body":"atNorth HPC AB är ett bolag specialiserat på high-performance computing (HPC). Bolaget tillhandahåller lösningar för storskalig databehandling som används i avancerad forskning, datorstödda simuleringar och AI-träning. Förvärvet är en viktig del i Advanias ambition att bli Nordeuropas mest heltäckande HPC- och AI-tjänsteleverantör.\n\nVinges team bestod av Peter Sundgren, Ulrich Ziche, Robin Sultani och Hanna Stamer (M&A), Simon Söderholm och Johanna Fjellström (arbetsrätt), Nicklas Thorgerzon och Mathilda Persson (IP), Eva Fredriksson, Martin Boström och Mario Saad (Kommersiella avtal, IT och GDPR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-advania-vid-forvarvet-av-atnorth-hpc-ab/","date":"2025-10-03","month":10},{"year":2025,"client":"Hallbyggarna Jonsereds","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Hallbyggarna Jonsereds vid förvärv av Renthall","caption":"Förvärv · 2 oktober 2025","preamble":"Hallbyggarna Jonsereds AB, som ingår i NSS Group, har förvärvat Renthall i Sverige AB som omsätter 40 mSEK.","body":"Affären stärker bolagets närvaro i norra Sverige och bidrar till fortsatt tillväxt.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Anna Neubüser och Alva Chambert.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-hallbyggarna-jonsereds-vid-forvarv-av-renthall/","date":"2025-10-02","month":10},{"year":2025,"client":"Täby Air Maintenance","work":"Avyttring","disciplines":["M&A"],"title":"Vinge har biträtt i samband med försäljningen av Täby Air Maintenance AB och tre Saab 2000 flygplan","caption":"Avyttring · 2 oktober 2025","preamble":"Vinge har biträtt Erik Thun AB i samband med försäljningen av samtliga aktier i Täby Air Maintenance AB samt tre Saab 2000 flygplan till Wingefors Depå Sju AB.","body":"Täby Air Maintenance AB har sedan 1989 erbjudit avancerade underhålls- och modifieringstjänster för regionalflygplan, med särskilt fokus på Saab 340, Saab 2000 och ATR.\n\nVinges team har huvudsakligen bestått av Anders Strid och Hanna Marberg.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-i-samband-med-forsaljningen-av-taby-air-maintenance-ab-och-tre-saab-2000-flygplan/","date":"2025-10-02","month":10},{"year":2025,"client":"Tengbom","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Tengbom vid förvärv Suunnittelemo","caption":"Förvärv · 1 oktober 2025","preamble":"Tengbom Finland växer och genom förvärvet av Suunnittelemo Oy etableras verksamhet i Tammerfors.","body":"Suunnittelemos grundare Milla Lindroos tar samtidigt plats som ny vd för Tengbom Finland.\n\nVinge, genom Johan Winnerblad, biträder Tengbom i förvärvet.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-tengbom-vid-forvarv-suunnittelemo/","date":"2025-10-01","month":10},{"year":2025,"client":"Advania","work":"Förvärv","disciplines":["M&A","GDPR","IT, Telekom och Outsourcing","Kommersiella avtal","Immaterialrätt","Immaterialrättsliga avtal & transaktioner","Arbetsrätt"],"title":"Vinge företräder Advania i förvärvet av The AI Framework","caption":"Förvärv · 29 september 2025","preamble":"Vinge har företrätt Advania i förvärvet av AI-bolaget The AI Framework som bidrar med expertis inom AI-transformation för verksamheter i norra Europa.","body":"Bolaget bedriver AI-transformation inom retail, telekom, finans och andra branscher, och tillhandahåller expertis inom strategisk rådgivning och implementering av artificiell intelligens i komplexa miljöer. Genom förvärvet stärker Advania sitt erbjudande inom AI-tjänster, inklusive rådgivning kring strategi, implementering och integration av AI.\n\nVinges team bestod av Peter Sundgren, Jonatan Stentorp och Paola Lopez (M&A), Mathilda Persson och Siri Blomberg (Kommersiella avtal, IT & GDPR), Emma Gustavsson (IP), Emil Lindwall, William Karo Persson och Louisa Fagarasan (Arbetsrätt), och Caroline Löv (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-advania-i-forvarvet-av-the-ai-framework/","date":"2025-09-29","month":9},{"year":2025,"client":"Haki Safety","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder Haki Safety i samband med företrädesemission","caption":"Kapitalanskaffning · 26 september 2025","preamble":"Vinge företräder Haki Safety AB (publ) i samband med en företrädesemission om cirka 50 miljoner kronor.","body":"Vinges team består av Christian Lindhé, Michaela Ådén, Jasmine Elgh och Nathalie Wikman.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-haki-safety-i-samband-med-foretradesemission/","date":"2025-09-26","month":9},{"year":2025,"client":"Axcel och Acurum Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Axcel och Acurum Group vid förvärven av Piperep och Pipe Eksperten","caption":"Förvärv · 23 september 2025","preamble":"Vinge har företrätt Axcel VII och Acurum Group i samband med förvärven av Piperep AS och Pipe Eksperten AS.","body":"Piperep AS och Pipe Eksperten AS är entreprenörsledda, lokalt förankrade bolag med expertis inom reparation och renovering av skorstenar samt rökkanaler respektive renovering och installation av skorstenar samt eldstäder. Genom förvärvet av Piperep AS breddar Acurum Group sitt erbjudande inom skorstenar och rökkanaler, med särskilt fokus på innovativa lösningar för reparation och renovering. Pipe Eksperten AS kompletterar koncernen med ett brett erbjudande inom försäljning och installation av eldstäder, videokontroll, felsökning och ett brett sortiment av kompletterande produkter.\n\nAcurum Group består av bolag som erbjuder tjänster inom luftkvalitet, fukthantering och rörunderhåll, och har varit verksamma sedan 2024. Gruppen omfattar idag cirka 23 bolag i Sverige, Norge och Finland, med cirka 750 medarbetare och en omsättning på cirka 1,2 miljarder SEK. Varje bolag verkar under sitt eget varumärke, men utvecklas genom gemensamma initiativ, samarbete och delad kompetens inom gruppen.\n\nVinges team bestod av Christina Kokko, Elsie Nassar, Emma Lundberg och Ida Appelgren (M&A) samt Julia Ulander Kull (Projektassistent).\n\nLäs klientens pressmeddelanden här och här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-acurum-group-vid-forvarven-av-piperep-och-pipe-eksperten/","date":"2025-09-23","month":9},{"year":2025,"client":"Eleda och Craftor","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har företrätt Eleda och Craftor i samband med förvärv av LinjePartner","caption":"Förvärv · 22 september 2025","preamble":"LinjePartner är ett norskt entreprenadföretag som utför uppdrag inom telekommunikation, lågspännings- och högspänningsinstallationer.","body":"LinjePartner är baserat i Levanger, Norge och kommer att ingå i Eledas plattformsbolag Craftor.\n\nVinges team bestod huvudsakligen av Christina Kokko, Per Kling och Viktor Ejlertsson (M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-och-craftor-i-samband-med-forvarv-av-linjepartner/","date":"2025-09-22","month":9},{"year":2025,"client":"Axcel och Accru Partners","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Bank och finans","Kommersiella avtal","IT, Telekom och Outsourcing","GDPR","Fastigheter och Entreprenad","Finansiella tillståndsfrågor","Regulatoriska tvister"],"title":"Vinge företräder Axcel och Accru Partners vid förvärven av Baker Tilly Helsingborg AB, MOORE Allegretto AB och MOORE Ranby AB","caption":"Förvärv · 18 september 2025","preamble":"Vinge har företrätt Axcel VII och Accru Partners i samband med förvärven av Baker Tilly Helsingborg AB, MOORE Allegretto AB och MOORE Ranby AB.","body":"Baker Tilly Helsingborg AB, MOORE Allegretto AB och MOORE Ranby AB är entreprenörsledda, lokala företag med expertis inom redovisning, revision, skatt, och rådgivningstjänster. Efter förvärven består Accru Partners av totalt 49 självständiga byråer inom nämnda verksamhetsområden.\n\nVinges team bestod av Christina Kokko, Desirée Hagenfeldt, Egil Svensson, Michella Lina Said och Chris Bastholm (M&A), Alice Göransson och Simon Söderholm (Arbetsrätt), Sofia Haggren (Bank och finans), Mario Saad (Kommersiella avtal), Elis Allmark (IT), Nicklas Thorgerzon (GDPR), Madelene Andersson (Fastighet), Jonna Bondemark och Isabelle Asserståhl (Regulatoriska frågor), Gulestan Ali och Hayaat Ibrahim (Regelefterlevnad) samt Emelie Schoning och Jessica Öijer (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-accru-partners-vid-forvarven-av-baker-tilly-helsingborg-ab-moore-allegretto-ab-och-moore-ranby-ab/","date":"2025-09-18","month":9},{"year":2025,"client":"Workday","work":"Förvärv","disciplines":[],"title":"Vinge företräder Workday, Inc. vid förvärvet av Sana Labs för 1,1 miljarder dollar","caption":"Förvärv · 16 september 2025","preamble":"Vinge, tillsammans med Orrick Herrington & Sutcliffe, har företrätt Workday, Inc. (NASDAQ: WDAY) (”Workday”) vid förvärvet av samtliga aktier i Sana Labs AB.","body":"Sana Labs är ett svenskt ledande AI-bolag som erbjuder innovativa utbildningsverktyg, främst genom två huvudprodukter – Sana Learn och Sana Agents. Genom produkterna erbjuds en AI-driven utbildningsplattform för företag som vill kompetensutveckla sina medarbetare tillsammans med en individanpassad AI-agent. Förvärvet är strategiskt motiverat och förväntas skapa synergier mellan Workday och Sana Labs genom integrationen av Sana Labs AI-teknologi i Workdays verksamhet.\n\nWorkday är att amerikanskt bolag noterat på Nasdaq börsen och en av de största globala aktörerna för molnbaserade mjukvarulösningar för hantering av HR, ekonomi och finans.\n\nVinges team bestod bland andra av Jonas Bergström, Samra Tesser, Viktor Ramhult, Johanna Barfoed och Chris Bastholm (M&A), Eva Fredrikson, Mathilda Persson, Elis Allmark och Siri Blomberg (Corporate Commercial), Sam Seddigh, Emil Lindwall och Louisa Fagarasan (Arbetsrätt) och Malin Malm Waerme, Ian Jonson, Melinda Oldenburg (IP).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-workday-inc-vid-forvarvet-av-sana-labs-for-1-1-miljarder-dollar/","date":"2025-09-16","month":9},{"year":2025,"client":"ArmaTech","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljning av ArmaTech till Defensor Group","caption":"Avyttring · 16 september 2025","preamble":"Vinge har biträtt vid försäljningen av ArmaTech i Kungsbacka AB (“ArmaTech”) till den nybildade försvarskoncernen Defensor Group AB (“Defensor”).","body":"Genom transaktionen förvärvar Defensor cirka 70 procent av aktierna i ArmaTech. I samband med affären har Flat Capital AB (publ) gått in som största ägare i Defensor. Defensor har som ambition att bygga upp en ledande aktör inom den nordiska försvars- och säkerhetsindustrin och genomförde parallellt med förvärvet av ArmaTech också förvärv av 70% av aktierna i SAFE4U.\n\nArmaTech är en nordisk systemleverantör och partner till världsledande tillverkare av system och produkter inom försvars- och säkerhetssektorn. De tidigare ägarna har återinvesterat i både ArmaTech och Defensor Group och kommer att fortsätta vara drivande i bolagets utveckling.\n\nVinges team bestod i huvudsak av Magnus Pauli, Petronella Hallberg, Emma Jansson, och Fredrik Löwenclou.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-armatech-till-defensor-group/","date":"2025-09-16","month":9},{"year":2025,"client":"Klarnas","work":"Börsnotering","disciplines":["M&A","Kapitalmarknad och publik M&A","Finansiella tillståndsfrågor","Företagsbeskattning"],"title":"Vinge rådgivare i samband med Klarnas börsnotering på New York-börsen","caption":"Börsnotering · 15 september 2025","preamble":"Vinge, tillsammans med Latham & Watkins, agerade rådgivare åt bookrunners och managers i samband med Klarnas börsnotering på New York-börsen. Klarna är en global digital bank och leverantör av flexibla betalningslösningar.","body":"Första handelsdagen var den 10 september 2025 och Klarna satte priset för sin börsintroduktion till 40 USD per aktie, vilket värderade bolaget till cirka 15 miljarder USD.\n\nMer information om börsnoteringen finns här: https://www.klarna.com/international/press/klarna-lists-on-the-new-york-stock-exchange/\n\nVinges team bestod huvudsakligen av Johan Larsson (Corporate), Jesper Schönbeck, Amanda Knutsson och Anna Svensson (Equity Capital Markets), Emma Stuart-Beck, Henrik Schön och David Flodin (Regulatory) samt Victor Ericsson, Erik Kochbati och Marcus Svärd (Tax).","href":"https://www.vinge.se/uppdrag/vinge-radgivare-i-samband-med-klarnas-borsnotering-pa-new-york-borsen/","date":"2025-09-15","month":9},{"year":2025,"client":"Intera Partners portföljbolag Yellow Elk","work":"Förvärv","disciplines":["M&A","Immaterialrätt","Immaterialrättsliga tvister","Immaterialrättsliga avtal & transaktioner","Arbetsrätt","IT, Telekom och Outsourcing","Bank och finans","Fastigheter och Entreprenad","Regulatoriska tvister","EU‑ och konkurrensrätt"],"title":"Vinge företräder Intera Partners portföljbolag Yellow Elk i samband med dess förvärv av Bizware","caption":"Förvärv · 11 september 2025","preamble":"Vinge har företrätt det nordiska private equity-bolaget Intera Partners portföljbolag Yellow Elk i samband med dess förvärv av dataanalysföretaget Bizware AB med dess dotterbolag Bizware Lead AB och Bizware Nova AB.","body":"Bizware erbjuder expertis inom dataanalys och AI med tjänster inom data engineering, visualisering, business intelligence och projektledning. Genom förvärvet tar Yellow Elk ett steg mot visionen att bli Nordens ledande aktör inom data analytics och AI.\n\nTransaktionen är villkorad av regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Egil Svensson, Olof Löfvenberg, Josef Groow (M&A), Emma Gustavsson (Immateriella rättigheter), Viktor Lundberg (Arbetsrätt), Filippa Eriksson (IT och Kommersiella avtal), Jolinn Uhlin och Katja Häglund (Bank och finans), Wilma Hellman (Fastighet), Dagne Sabockis och Lovisa Arpi (Regulatory), och Ottilia Pettersson (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-intera-partners-portfoljbolag-yellow-elk-i-samband-med-dess-forvarv-av-bizware/","date":"2025-09-11","month":9},{"year":2025,"client":"Latham Watkins,","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Fastigheter och Entreprenad","EU‑ och konkurrensrätt","FDI"],"title":"Vinge har, tillsammans med Latham Watkins, biträtt Cadence i samband med dess förvärv av Hexagons Design & Engineering-verksamhet för cirka 2,7 miljarder euro","caption":"Förvärv · 9 september 2025","preamble":"Cadence (Nasdaq: CDNS) meddelade att bolaget har ingått ett bindande avtal om att förvärva Design & Engineering-verksamheten inom Hexagon AB, vilket inkluderar MSC Software-verksamhet – en pionjär inom ingenjörssimulering och analyslösningar.","body":"Cadence (Nasdaq: CDNS) meddelade att bolaget har ingått ett bindande avtal om att förvärva Design & Engineering-verksamheten inom Hexagon AB, vilket inkluderar MSC Software-verksamhet – en pionjär inom ingenjörssimulering och analyslösningar.\n\nVinges team bestod av Christina Kokko, Ulrich Ziche, Manon de Cooman, Lina Björkman och Anna Neubüser (M&A), Johanna Fjellström, William Karo Persson (Arbetsrätt), Niclas Winnberg (Fastigheter), David Olander, Daniel Wendelsson, Hampus Peterson och Lovisa Arpi (Konkurrensrätt och FDI).","href":"https://www.vinge.se/uppdrag/vinge-har-tillsammans-med-latham-watkins-bitratt-cadence-i-samband-med-dess-forvarv-av-hexagons-design-engineering-verksamhet-for-cirka-2-7-miljarder-euro/","date":"2025-09-09","month":9},{"year":2025,"client":"Geins","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljning av Geins till Litium","caption":"Avyttring · 8 september 2025","preamble":"Litium AB, som är noterat på First North, förvärvar SaaS-bolaget Geins Group AB. Geins utvecklar och erbjuder e-handelsplattformar. Köpeskillingen erläggs delvis i kontanter, delvis i aktier i Litium.","body":"Vinge har, genom Johan Winnerblad, biträtt aktieägarna i Geins.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-geins-till-litium/","date":"2025-09-08","month":9},{"year":2025,"client":"Helix Kapital","work":"Övrigt","disciplines":["M&A"],"title":"Vinge biträder Helix Kapital vid etablering av Revivo Group","caption":"Övrigt · 4 september 2025","preamble":"Helix Kapital ingår partnerskap med tre välrenommerade specialistbolag och etablerar Revivo Group, en ny aktör med ambitionen att bli den självklara partnern för ytbehandlingstjänster i Norden.","body":"Koncernen erbjuder ett brett utbud av tjänster för att skydda och framtidssäkra konstruktioner inom infrastruktur, industri, sjöfart samt bygg-och anläggning mot korrosion, brand och slitage. Koncernen består vid etableringen av Henry Allt i Allt, Brandskyddsmålarna i Sverige och Ahnelövs Industrimålning.\n\nVinge har genom Johan Winnerblad, Gustav Wahlberg, Agnes Pigg, Jonna Skog, Carla Håkansson, Stina Larsson, Dagne Sabockis, Filippa Eriksson, Ida Pettersson, Martin Hammarskiöld, Clara Klingspor och Isabelle Ivarsson biträtt vid de tre förvärven.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-helix-kapital-vid-etablering-av-revivo-group/","date":"2025-09-04","month":9},{"year":2025,"client":"Oncopeptides","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har företrätt Oncopeptides i samband med dess företrädesemission","caption":"Kapitalanskaffning · 28 augusti 2025","preamble":"Vinge har företrätt Oncopeptides AB (publ) i samband med en fullt garanterad företrädesemission som tillför Oncopeptides cirka 150 miljoner kronor före avdrag för transaktionskostnader.","body":"Oncopeptides är ett biotechbolag inriktat på forskning, utveckling och kommersialisering av behandlingar mot svårbehandlade hematologiska sjukdomar. Bolaget använder sin patentskyddade PDC-plattform för att utveckla peptidlänkade läkemedel som snabbt och selektivt levererar cellgifter in i cancerceller.\nVinges team har bestått av Dain Hård Nevonen, Joel Magnusson, Louise Nässén, Amanda Sandström och Vilma Henricsson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-oncopeptides-i-samband-med-dess-foretradesemission-1/","date":"2025-08-28","month":8},{"year":2025,"client":"Main Capital och Unik","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Immaterialrätt","Kommersiella avtal","GDPR"],"title":"Vinge företräder Main Capital och Unik vid förvärvet av LEB System Aktiebolag","caption":"Förvärv · 28 augusti 2025","preamble":"Vinge har företrätt Unik International ApS (“Unik”), en dansk leverantör av programvara för bostads- och fastighetsförvaltning, vid förvärvet av LEB System Aktiebolag. Det synergistiska förvärvet förväntas komplettera och utöka Uniks erbjudande och passar strategiskt väl in i Unik och ligger i linje med företagets internationaliseringsstrategi på den nordiska marknaden för fastighetsförvaltningsprogramvara.","body":"LEB System Aktiebolag är ett IT-produktbolag verksamt inom fastighetsbranschen som tillhandahåller mjukvarulösningar för ägande, administration och skötsel av fastigheter som är skräddarsydd för behoven hos offentliga och privata fastighetsägare och långsiktiga fastighetsförvaltare. Bolagets system möjliggör bland annat hantering av tillsyn, avtal, fakturor och nyckeltal, vilket möjliggör dels att kunderna erbjuds effektiva processer inom både teknisk- och administrativ förvaltning, dels att ett verksamhetsöverskridande och rollbaserat arbetssätt främjas.\n\nVinges team bestod av Filip Öhrner och Olivia Altheden (M&A), Alice Göransson (arbetsrätt), Vilma Simonius och Ian Jonson (IP), och Filippa Eriksson (Kommersiella avtal, IT och GDPR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-och-unik-vid-forvarvet-av-leb-system-aktiebolag/","date":"2025-08-28","month":8},{"year":2025,"client":"Xspray Pharma","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A","Bank och finans"],"title":"Vinge har biträtt Xspray Pharma i samband med dess företrädesemission och skuldrefinansiering","caption":"Kapitalanskaffning · 28 augusti 2025","preamble":"Vinge har biträtt Xspray Pharma AB (publ) i samband med en företrädesemission om cirka 130 miljoner kronor före transaktionskostnader med en övertilldelningsemission om cirka 20 miljoner kronor samt refinansiering av ett befintligt lån.","body":"Xspray är ett läkemedelsföretag som specialiserar sig på att använda sin patenterade HyNap-teknologi för att utveckla förbättrade versioner av befintliga protein-kinashämmare (PKI:er) för cancerbehandling.\n\nVinges team har bestått av Dain Hård Nevonen, Joel Magnusson, Louise Nässén och Amanda Sandström (Kapitalmarknad och publik M&A) samt Arvid Weimers (Bank och finans).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-xspray-pharma-i-samband-med-dess-foretradesemission-och-skuldrefinansiering/","date":"2025-08-28","month":8},{"year":2025,"client":"Bolero","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt Bolero i samband med försäljning av aktier i Ambea AB (publ)","caption":"Avyttring · 28 augusti 2025","preamble":"Vinge har biträtt Bolero Holdings S.à r.l. i samband med nedförsäljning av aktier i Ambea AB (publ) i en så kallad accelererad bookbuilding-process genomförd den 26 augusti 2025.","body":"Totalt placerades 4,3 miljoner aktier till ett pris om 126 kronor per aktie, motsvarande ett sammanlagt värde om cirka 542 miljoner kronor.\n\nVinges team bestod av Dain Hård Nevonen och Linnéa Dolk.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-bolero-i-samband-med-forsaljning-av-aktier-i-ambea-ab-publ/","date":"2025-08-28","month":8},{"year":2025,"client":"EQT IX","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt EQT IX i samband med försäljning av aktier i Beijer Ref AB (publ)","caption":"Avyttring · 27 augusti 2025","preamble":"Vinge har biträtt EQT IX (”EQT”) i samband med nedförsäljning av aktier i Beijer Ref AB (publ) i en så kallad accelererad bookbuilding-process genomförd den 26 augusti 2025.","body":"Totalt placerades 20 miljoner aktier till ett pris om 157 kronor per aktie, motsvarande ett sammanlagt värde om cirka 3,14 miljarder kronor.\n\nVinges team bestod av Sofie Bjärtun och Linnéa Dolk.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-eqt-ix-i-samband-med-forsaljning-av-aktier-i-beijer-ref-ab-publ-2/","date":"2025-08-27","month":8},{"year":2025,"client":"Intrum","work":"Övrigt","disciplines":["Rekonstruktioner och obestånd","Bank och finans","Tvistlösning","Kapitalmarknad och publik M&A","Finansiella tillståndsfrågor"],"title":"Vinge biträder Intrum i dess rekapitaliseringstransaktion om 4,48 miljarder euro","caption":"Övrigt · 25 augusti 2025","preamble":"Intrum AB och dess dotterbolag har genomfört en omfattande och strategisk rekapitaliseringstransaktion i syfte att stärka bolagets balansräkning och säkerställa dess långsiktiga finansiella stabilitet. Transaktionen innebär en omstrukturering av Intrums befintliga skuldportfölj om cirka 4,48 miljarder euro och omfattar bland annat en förlängning av låneförfall, nedskrivning av befintliga skuldinstrument, tillförande av nytt kapital från vissa av bolagets obligationsinnehavare samt en nyemission av aktier till befintliga obligationsinnehavare. Rekapitaliseringstransaktionen implementerades genom en s.k. ”pre-packaged” Chapter 11-process i USA och en svensk företagsrekonstruktion.","body":"Genom transaktionen förlängdes löptiden för Intrums revolverande kreditfacilitet om 1,1 miljarder euro, ändrades villkoren för dess tidsbestämda lånefacilitet om 90 miljoner euro, förlängdes löptid och minskades skuldsättning under dess icke-säkerställda obligationer om cirka 3,3 miljarder euro (motsvarande). Intrum tillfördes även ny finansiering om 526 miljoner euro från vissa av dess befintliga obligationsinnehavare i form nya obligationer. Därutöver genomfördes en nyemission av aktier motsvarande 10 % av aktiekapitalet till bolagets obligationsinnehavare.\n\nRekapitaliseringstransaktionen implementerades genom en s.k. pre-packaged Chapter 11-process i USA och en svensk företagsrekonstruktion för att säkerställa att effekten av rekapitaliseringstransaktionen erkändes globalt. Rekapitaliseringstransaktionen innebar även en koncernintern omstrukturering som involverade rådgivning från England, Belgien, Danmark, Finland, Frankrike, Grekland, Irland, Italien, Nederländerna, Norge, Polen, Portugal, Schweiz, Slovakien, Spanien, Tjeckien, Tyskland och Ungern.\n\nVinge har biträtt Intrum med ett team huvudsakligen bestående av Mikael Ståhl, Fabian Ekeblad och Anna Palmérus tillsammans med Jenny Sandlund, Elin Samara, Oskar Nilsson och Ida Redander.\n\nTeamet bestod också av bl.a. Malin Olsson, Kim Larsson, Alicia Olnäs, Olivia Carlsten, Oliwer Vidarsson (Rekonstruktion och obestånd), Arvid Weimers, Gabriel Chabo, August Ahlin, Rebecka Margolin, Katja Häglund (Bank och finans), Anders Öhlin, Carl Lönnqvist, Robert Wikholm, Jacqueline Fritzson (Tvistlösning), Rikard Lindahl (Kapitalmarknad och publik M&A) och Viveka Classon (Finansiella tillståndsfrågor).\n\nVinge har tillsammans med Milbank LLP biträtt Intrum i alla delar av rekapitaliseringstransaktionen.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-intrum-i-dess-rekapitaliseringstransaktion-om-4-48-miljarder-euro/","date":"2025-08-25","month":8},{"year":2025,"client":"Neptuniplan Maritime","work":"Förvärv","disciplines":[],"title":"Vinge företräder Neptuniplan Maritime vid finansiering av ANCS-förvärv","caption":"Förvärv · 25 augusti 2025","preamble":"Vinge har företrätt Neptuniplan Maritime Holding AB i samband med ingåendet av ett kreditfacilitetsavtal om drygt 133 000 000 EUR med Citibank, Danske Bank och Nordea i syfte att bl.a. finansiera förvärvet av Wärtsiläs Automation, Navigation and Control Systems (ANCS)-verksamhet. Verksamheten kommer fortsätta bedrivas under NACOS Marine, som tillhandahåller bl.a. avancerad teknik för fartygsnavigering, automatisering och kontrollsystem samt adaptiva autopiloter, och Guidance Marine, ledande inom sensorteknologi för dynamisk positionering och sjösäkerhet.","body":"Neptuniplan Maritime Holding AB ägs av det svenska investmentbolaget Solix Group AB.\n\nVinges team bestod av Henrik Ossborn, Jolinn Uhlin och William Carlberg Johansson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-neptuniplan-maritime-vid-finansiering-av-ancs-forvarv/","date":"2025-08-25","month":8},{"year":2025,"client":"HealthCap","work":"Övrigt","disciplines":[],"title":"Vinge har biträtt HealthCap vid etableringen av HealthCap IX","caption":"Övrigt · 22 augusti 2025","preamble":"HealthCap IX har hållit sin final closing och har rest kapitalåtaganden som överträffar fondens target från en diversifierad investerarbas bestående av etablerade institutioner, pensionsfonder och välrenommerade investerare inom life science-sektorn. Det starka intresset för fonden speglar fortsatt förtroende för HealthCaps strategi och firmans gedigna track record.","body":"HealthCap är ett europeiskt venture capital-bolag som investerar globalt inom life science och har sedan starten 1996 rest nio fonder. HealthCap har stöttat och byggt upp över 130 bolag, tagit fler än 45 bolag till börsen och genomfört ett flertal företagsförsäljningar. Investeringsstrategin fokuserar på sjukdomar med ett stort medicinskt behov och banbrytande behandlingar som har potential att vara transformativa, förändra klinisk praxis och förbättra livet för patienter.\n\nVinges team har huvudsakligen bestått av Mattias Schömer, Marcus Andersson, Semir Omerbasic, Jesper Ottergren, Emelie Svanberg, Erik Kochbati and Emelie Zingmark.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-healthcap-vid-etableringen-av-healthcap-ix/","date":"2025-08-22","month":8},{"year":2025,"client":"MAAG Gear","work":"Finansiering","disciplines":[],"title":"Vinge företräder MAAG Gear vid 18,5 MEUR-refinansiering","caption":"Finansiering · 21 augusti 2025","preamble":"Vinge har företrätt MAAG Gear i samband med ingåendet av ett kreditfacilitetsavtal om 18 500 000 EUR med Danske Bank A/S i syfte att bl.a. refinansiera bolagets tidigare lån. MAAG Gear är en ledande tillverkare av högprecisionsväxlar och kugghjulslösningar för cement- och gruvindustrin med ett omfattande produktsortiment och globala eftermarknadstjänster.","body":"MAAG Gear ägs av det svenska investmentbolaget Solix Group AB.\n\nVinges team bestod av Henrik Ossborn, Jolinn Uhlin, Ida Redander och Erik von Zweigbergk.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-maag-gear-vid-18-5-meur-refinansiering/","date":"2025-08-21","month":8},{"year":2025,"client":"Direktronik","work":"Förvärv","disciplines":[],"title":"Vinge har biträtt Direktronik vid förvärv av Qvintus","caption":"Förvärv · 19 augusti 2025","preamble":"Direktronik, ett dotterbolag till Lagercrantz Group, har förvärvat samtliga aktier i Qvintus.","body":"Qvintus grundades 1953, är baserat i Bandhagen och har ett brett sortiment av maskintermometrar, manometrar och ventiler, med egen tillverkning och montering av delar av sortimentet.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Sofia Sallnäs, Ellenor Eckerborn, Hedvig Ekdahl och Viktor Lundberg.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-direktronik-vid-forvarv-av-qvintus/","date":"2025-08-19","month":8},{"year":2025,"client":"Sobro","work":"Kapitalanskaffning","disciplines":["M&A","Immaterialrätt","Arbetsrätt","Kommersiella avtal","Bank och finans","Trade Compliance"],"title":"Vinge biträder Sobro vid investering i vChain","caption":"Kapitalanskaffning · 18 augusti 2025","preamble":"vTrade med dotterbolaget vChain har valt att bredda sitt ägande med Sobro som ny ägarpartner och majoritetsägare. Grundaren Carl-Henrik Lundh fortsätter som vd och betydande delägare.","body":"vChain tillhandahåller en plattformslösning för hantering och effektivisering av leverantörskedjor (s.k. supply chain management).\n\nVinges team bestod huvudsakligen av Johan Winnerblad, Josef Groow (M&A), Ian Jonson, Vilma Simonius (Immateriella rättigheter), Alice Göransson, Emil Lindwall (Arbetsrätt), Nicklas Thorgerzon, Carla Håkansson, Gabriel Pålsson (IT och Kommersiella avtal), Nilufer Nouri (Bank och finans), Gulestan Ali (Compliance) och Jessica Henning (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sobro-vid-investering-i-vchain/","date":"2025-08-18","month":8},{"year":2025,"client":"Mora Bygg","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt vid försäljningen av Mora Bygg till Pinerock Group","caption":"Avyttring · 18 augusti 2025","preamble":"Pinerock Group har förvärvat Mora Bygg AB med dotterbolagen Helob Bygg AB och Mora Golv & Kakel AB.","body":"Bolaget har kontor i Mora och Borlänge och är verksamt i stora delar av Dalarna. Företaget består av cirka 115 anställda och omsätter drygt 300 miljoner kronor. Företaget är aktivt inom ROT, byggservice och försäkringsskador. De tidigare ägarna har återinvesterat i Pinerock Group och kommer att fortsätta driva och utveckla företaget i sin region.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Alex Forsberg och Gulestan Ali.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-vid-forsaljningen-av-mora-bygg-till-pinerock-group/","date":"2025-08-18","month":8},{"year":2025,"client":"Meribel Pharma Solutions","work":"Övrigt","disciplines":["M&A","Corporate Commercial","Carve-Outs"],"title":"Vinge företräder Meribel Pharma Solutions","caption":"Övrigt · 13 augusti 2025","preamble":"Vinge företräder Meribel Pharma Solutions i samband med försäljningen av deras produktionsanläggning i Uppsala till Ofichem.","body":"Vinges team bestod av bland andra Jonas Bergström, Per Kling och Ellenor Eckerborn (M&A), och Mathilda Persson (Corporate Commercial).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-meribel-pharma-solutions-1/","date":"2025-08-13","month":8},{"year":2025,"client":"Fidelio Capital","work":"Kapitalanskaffning","disciplines":["M&A","Arbetsrätt","Trade Compliance","Fastigheter och Entreprenad","Kommersiella avtal","IT, Telekom och Outsourcing","Finansiella tillståndsfrågor","Immaterialrätt","EU‑ och konkurrensrätt","Miljörätt","Marknadskontroll"],"title":"Vinge har biträtt Fidelio Capital AB vid deras investering i Greenfood AB","caption":"Kapitalanskaffning · 11 augusti 2025","preamble":"Vinge har biträtt Fidelio Capital AB i samband med att de blir majoritetsägare i Greenfood.","body":"Fidelio, som har varit minoritetsägare i nästan 15 år, har ökat sitt ägande i Greenfood genom att förvärva Nordic Capitals andel i koncernen och Fidelio blir därmed majoritetsägare av Greenfood.\n\nVinges team bestod av bland andra Jonas Bergström, Johanna Wiberg, Amanda Steen, Edvard Gustafson, Lovisa Jonassen och Anna Neubüser (M&A), Alice Göransson och Louisa Fagarasan (Employment), Hayaat Ibrahim (Compliance), Hanna Kövamees och Wilma Hellman (Real Estate), Mario Saad och Gabriel Pålsson (Commercial Agreements), Nicklas Thorgerzon, Filippa Eriksson och Sara Link (IT), Albert Wållgren, Felix Möller, Nour Makie och Gabriel Chabo (Financial Arrangements), Melinda Oldenburg, Maja Helm och Vilma Simonius (IP), Martin Johansson och Filippa Berggren (State Aid), Stina Larsson (Environment and Permits), Sebastian Örndahl, Noelia Martinez, Hilda Ivarson, Hampus Peterson och Lovisa Arpi (Merger Control) och Ellinore Boström Andersson (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-fidelio-capital-ab-vid-deras-investering-i-greenfood-ab/","date":"2025-08-11","month":8},{"year":2025,"client":"Isofol Medical","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Isofol Medical AB (publ) i samband med dess företrädesemission av units","caption":"Kapitalanskaffning · 1 augusti 2025","preamble":"Genom företrädesemissionen av units, bestående av aktier och teckningsoptioner, och den utnyttjade övertilldelningsemissionen tillförs Isofol cirka 84 MSEK och kan komma att tillföras ytterligare maximalt cirka 110 MSEK vid utnyttjade av samtliga teckningsoptioner till högsta teckningskurs.","body":"Isofol Medical AB (publ) arbetar för att och förbättra prognosen för patienter med svåra former av cancer. Bolagets läkemedelskandidat arfolitixorin syftar till att höja effekten av första linjens standardbehandling för flera former av solida tumörer och studeras nu i kolorektalcancer, världens tredje vanligaste cancerform, där det medicinska behovet av bättre behandlingar är stort.\nVinges team har bestått av Anders Strid, Edin Agic och Sofia Haggren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-isofol-medical-ab-publ-i-samband-med-dess-foretradesemission-av-units/","date":"2025-08-01","month":8},{"year":2025,"client":"Oncorena","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Oncorena i samband med nyemission","caption":"Kapitalanskaffning · 30 juli 2025","preamble":"Vinge biträder Oncorena Holding AB i samband med en nyemission om cirka 133 miljoner kronor.","body":"Emissionslikviden kommer att användas för att slutföra den andra delen av den kliniska studien Oncorella-1, som är en fas 1/2-studie av säkerhet, tolerabilitet och antitumöreffekt vid behandling med ONC175 (Oncorenas prövningsläkemedel under utveckling) för patienter med metastaserad klarcellig eller papillär njurcellscancer, mRCC.\n\nVinges team består av Christian Lindhé, Martin Madsen Svanberg och Nathalie Wikman.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-oncorena-i-samband-med-nyemission/","date":"2025-07-30","month":7},{"year":2025,"client":"Karl Hedin och minoritetsägarna","work":"Avyttring","disciplines":[],"title":"Vinge företräder Karl Hedin och minoritetsägarna vid försäljningen av AB Karl Hedin Sågverk till Vida","caption":"Avyttring · 24 juli 2025","preamble":"Vinge har företrätt Karl Hedin och minoritetsägarna i samband med försäljningen av AB Karl Hedin Sågverk till Vida Aktiebolag (”Vida”).","body":"Vinge har företrätt Karl Hedin och minoritetsägarna i samband med försäljningen av AB Karl Hedin Sågverk till Vida Aktiebolag (”Vida”).\n\nVida är en global leverantör av förädlade produkter från svensk skog. Vida-koncernen har cirka 1 600 anställda och en omsättning på 12 miljarder kronor och bedriver verksamhet på 24 produktionsanläggningar, varav 12 sågverk. AB Karl Hedin Sågverk har tre sågverk i Sverige och en väletablerad råvaruorganisation i Bergslagen. Bolaget har cirka 220 heltidsanställda och en omsättning om 1,8 miljarder kronor. Efter förvärvet kommer AB Karl Hedin Sågverk att fortsätta verka under nuvarande namn och varumärke med Fredrik Marnefeldt som VD.\n\nTillsammans kommer Vida och AB Karl Hedin Sågverk att ha en omsättning om cirka 14 miljarder kronor, 1 800 anställda och en sågproduktion om 3,3 miljoner kubikmeter.\n\nTransaktionen är villkorad av regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Johan Winnerblad, Egil Svensson och Olof Löfvenberg.\n\nLäs mer i AB Karl Hedins pressmeddelande","href":"https://www.vinge.se/uppdrag/vinge-foretrader-karl-hedin-och-minoritetsagarna-vid-forsaljningen-av-ab-karl-hedin-sagverk-till-vida/","date":"2025-07-24","month":7},{"year":2025,"client":"OsteoCentric","work":"Övrigt","disciplines":[],"title":"Vinge biträder OsteoCentric i budet på Integrum","caption":"Övrigt · 23 juli 2025","preamble":"OsteoCentric Oncology and Bone Anchored Prostheses, LLC, ett dotterbolag till OsteoCentric Technologies, Inc., har lämnat ett offentligt uppköpserbjudande till aktieägarna i Integrum AB (publ). Erbjudandet värderar samtliga aktier i Integrum till cirka 939 miljoner kronor.","body":"Vinges team består av Erik Sjöman, Sofie Bjärtun, Linnéa Dolk och Michaela Ådén (Kapitalmarknad och publik M&A) samt Daniel Wendelsson, Fredrik Hellström och Lovisa Arpi (FDI).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-osteocentric-i-budet-pa-integrum/","date":"2025-07-23","month":7},{"year":2025,"client":"Investor","work":"Offentligt uppköpserbjudande","disciplines":["M&A","Kapitalmarknad och publik M&A","Finansiella tillståndsfrågor"],"title":"Vinge företräder Investor vid dess saminvestering i det SEK 55 miljarder offentliga uppköpserbjudandet avseende Fortnox som leds av EQT X","caption":"Offentligt uppköpserbjudande · 22 juli 2025","preamble":"Vinge företräder Investor AB (publ) (”Investor”) vid dess saminvestering i det offentliga uppköpserbjudandet avseende Fortnox AB (publ) (”Fortnox”) som leds av EQT X tillsammans med First Kraft AB (ägt av Olof Hallrup), genom Omega II AB (”Omega II”). Fortnox erbjuder kritisk mjukvarubaserad infrastruktur för svenska små och medelstora företag och har en historik av lönsam tillväxt.","body":"Den 31 mars 2025 offentliggjorde EQT X och First Kraft AB, genom Omega II, ett offentligt uppköpserbjudande till aktieägarna i Fortnox att sälja alla aktier i Fortnox till Omega II. Erbjudandet värderar Fortnox till cirka 55 miljarder kronor. Aktierna i Fortnox är noterade på Nasdaq Stockholm (Large Cap). Styrelsen i Fortnox rekommenderade enhälligt aktieägarna i Fortnox att acceptera erbjudandet.\n\nInvestors totala investering förväntas uppgå till cirka 4,5 miljarder kronor vid slutförandet av det offentliga uppköpserbjudandet, varav cirka 2,6 miljarder kronor investerades under andra kvartalet 2025.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Linus Adolfsson, Alexander Rüdén (M&A), Erik Sjöman, Sofie Bjärtun (Capital Markets), Viveka Classon och Olivia Carlsten (Financial Regulatory).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-investor-vid-dess-saminvestering-i-det-sek-55-miljarder-offentliga-uppkopserbjudandet-avseende-fortnox-som-leds-av-eqt-x/","date":"2025-07-22","month":7},{"year":2025,"client":"Cantargia","work":"Avyttring","disciplines":[],"title":"Vinge biträder Cantargia i samband med försäljning av immunologiprogrammet CAN10","caption":"Avyttring · 21 juli 2025","preamble":"Vinge biträder Cantargia AB (publ) i samband med försäljningen av IL1RAP immunologiprogrammet CAN10 i tidig klinisk fas till det japanska hälso- och läkemedelsbolaget Otsuka Pharmaceutical.","body":"Vid slutförandet av transaktionen kommer Cantargia att erhålla en initial kontant betalning om 33 miljoner USD, samt att Cantargia är berättigat till upp till ytterligare 580 miljoner USD i milstolpesbetalningar. Cantargia har även rätt till upp till tvåsiffriga tilläggsköpeskillingar, i procent av global produktförsäljning.\n\nVinges team består av Sofie Nordgren, Christian Lindhé, Martin Madsen Svanberg och Carolina Lundh.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-cantargia-i-samband-med-forsaljning-av-immunologiprogrammet-can10/","date":"2025-07-21","month":7},{"year":2025,"client":"PulPac","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt PulPac vid lånefinansiering om 20 miljoner euro från EIB","caption":"Finansiering · 18 juli 2025","preamble":"Vinge har biträtt det Göteborgsbaserade företaget PulPac, som utvecklar hållbara förpackningstekniker, i samband med att företaget erhållit en finansiering på 20 miljoner euro (cirka 220 miljoner kronor) från Europeiska investeringsbanken (EIB).","body":"Finansieringen är strukturerad som en risklånefinansiering – en form av tillväxtfinansiering skräddarsydd för innovativa företag. Lånet tillhandahålls inom ramen för InvestEU-programmet, som stöder EU:s gröna omställning och insatser för att stimulera innovation, industriell motståndskraft och hållbar ekonomisk tillväxt. EIB-finansieringen kommer att stödja utveckling och kommersialisering av en fiberbaserad teknik som utvecklats av PulPac som ett alternativ till engångsplast.\n\nVinges team bestod av Kristian Ford (ansvarig delägare), Henrik Ossborn och Agaton Lindgren (bank och finans).\n\nLäs mer här i pressmeddelande från PulPac","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-pulpac-vid-lanefinansiering-om-20-miljoner-euro-fran-eib/","date":"2025-07-18","month":7},{"year":2025,"client":"Behold Ventures","work":"Fondetablering","disciplines":[],"title":"Vinge har biträtt Behold Ventures vid fondresningen av Behold Ventures första fond","caption":"Fondetablering · 10 juli 2025","preamble":"Behold Ventures höll sin final closing den 27 juni 2025 och säkrade därmed investeringsåtaganden till sin första fond om drygt 550 miljoner kronor från en internationell investerarbas bestående av bl.a. Europeiska investeringsfonden (EIF).","body":"Behold Ventures är en svensk venture capital-investerare specialiserad på investeringar i datorspelbolag i ett tidigt skede. Behold Ventures har vid tidpunkten för final closing investerat i 18 startups inom datorspelindustrin.\n\nVinges team har huvudsakligen bestått av Mattias Schömer, Martin Cronsioe, Tobias Onegård Karlsson, Mikaela Reinhammar, Ulf Nilsson, Emelie Svanberg, Morgan Ödman, Jenny Tolander, Jonna Bondemark, Erik Kochbati, Saga Meyer Viklund, Sara Link, Marcus Svärd och Emelie Zingmark.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-behold-ventures-vid-fondresningen-av-behold-ventures-forsta-fond/","date":"2025-07-10","month":7},{"year":2025,"client":"Main Capital","work":"Avyttring","disciplines":["M&A","Bank och finans","Kommersiella avtal","IT, Telekom och Outsourcing","Arbetsrätt","Immaterialrätt"],"title":"Vinge företräder Main Capital i samband med försäljningen av Alfa eCare","caption":"Avyttring · 10 juli 2025","preamble":"Vinge har företrätt Main Capital i samband med försäljningen av Alfa eCare Holding AB samt dotterbolag (”Alfa eCare”) till SDB Groep B.V. (”SDB”)","body":"Alfa eCare är en ledande leverantör av digital programvara för hälso- och sjukvård, välfärd och barnomsorg i Norden. Alfa eCare har kontor i Finland och Danmark, och huvudkontor i Sverige. Företaget har cirka 120 anställda och över 1 300 kunder inom offentlig och privat sektor. SBD är en marknadsledande leverantör av programvara för hälso- och sjukvård och barnomsorg i Nederländerna, med tjänster inom äldreomsorg, handikappomsorg, psykisk hälsa, rehabilitering, ungdomsvård, barnomsorg och oberoende behandlingscenter (ITC).\n\nAlfa eCare och SDB går samman för att skapa en ledande aktör på den europeiska marknaden för hälso- och sjukvård.\n\nVinges team bestod huvudsakligen av Filip Öhrner, Jonatan Stentorp, Ian Linde (M&A), Felix Möller, Sofia Haggren (Bank & Finans), Martin Boström, Siri Blomberg (Kommersiella avtal samt IT & GDPR), Alice Göransson, Louisa Fagarasan (Arbetsrätt), Felizia Wiker (IP), Caroline Löv och Jasmina Skandrani (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-i-samband-med-forsaljningen-av-alfa-ecare/","date":"2025-07-10","month":7},{"year":2025,"client":"Ballista Capital","work":"Övrigt","disciplines":[],"title":"Vinge biträder vid etableringen av Ballista Capital","caption":"Övrigt · 7 juli 2025","preamble":"Ballista Capital genomförde sin finala closing den 9 juni 2025. Investerarbasen består främst av family offices och investerare med stark anknytning till norra Sverige","body":"Ballista Capital tror på möjligheten att skapa avkastning i svenska småbolag dit större kapitalflöden inte når och är främst intresserade av bolag utanför storstadsregionerna.\n\nVinges team har huvudsakligen bestått av Mattias Schömer, Marcus Andersson, Semir Omerbasic, Erik Kochbati och Emelie Zingmark.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-etableringen-av-ballista-capital/","date":"2025-07-07","month":7},{"year":2025,"client":"Sobro","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder Sobro vid investering i Shapeline","caption":"Kapitalanskaffning · 4 juli 2025","preamble":"Shapeline har valt att bredda sitt ägande med Sobro som ny ägarpartner och majoritetsägare. Samtliga befintliga ägare kvarstår som delägare. Shapeline är en ledande leverantör av beröringsfria mätlösningar för planhetsmätning av platta material som stål och aluminium. Verksamheten grundades i Linköping 1999.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Desirée Hagenfeldt, Michella Lina Said, Olivia Altheden, Hayaat Ibrahim, Hedvig Ekdahl, Melinda Oldenburg, Louisa Fagarasan och Sara Link.\n\nLäs klientens pressmeddelanden här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sobro-vid-investering-i-shapeline/","date":"2025-07-04","month":7},{"year":2025,"client":"The Qt Company Oy","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","M&A","Bank och finans","Arbetsrätt","Immaterialrätt","Kommersiella avtal","GDPR","FDI","Corporate Crime & Compliance"],"title":"Vinge biträder The Qt Company Oy i budet på I.A.R. Systems Group AB (publ)","caption":"Övrigt · 4 juli 2025","preamble":"The Qt Company Oy (”The Qt Company”), ett helägt dotterbolag till Qt Group Plc, har lämnat ett offentligt uppköpserbjudande till aktieägarna i I.A.R Systems Group AB (publ) (”IAR”) att överlåta samtliga aktier av serie B i IAR till The Qt Company mot kontant ersättning om 180 kronor per aktie.","body":"IAR tillhandahåller mjukvara och tjänster för inbyggd utveckling som används av företag världen över för att skapa säkra produkter. Med huvudkontor i Uppsala, Sverige, har IAR en global närvaro med försäljnings- och supportkontor världen över. Aktierna i IAR är upptagna till handel på Nasdaq Stockholm, Mid Cap. Erbjudandet värderar IAR till cirka 2 293 miljoner kronor.\n\nVinges team består huvudsakligen av Rikard Lindahl, Erik Sjöman, Joel Magnusson, Benjamin Vafaeian, Louise Nässén och Vilma Henricsson (Kapitalmarknad och publik M&A), Jonas Johansson (M&A), Arvid Weimers, Josefine Lanker, Nour Makie och Katja Häglund (Bank och Finans), Johanna Fjellström och Alice Göransson (Arbetsrätt), Rebecka Målquist och Melinda Oldenburg (IP), Eva Fredrikson, Martin Boström, Siri Blomberg och Filippa Eriksson (Kommersiella avtal, IT och GDPR), Fredrik Hellström och Lovisa Arpi (FDI), Gulestan Ali (Compliance) och Diana Kanold (VDR).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-the-qt-company-oy-i-budet-pa-i-a-r-systems-group-ab-publ/","date":"2025-07-04","month":7},{"year":2025,"client":"Hässelby Blommor","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Hässelby Blommor vid förvärv av Servix Plantedekor","caption":"Förvärv · 3 juli 2025","preamble":"Hässelby Blommor Holding AB har förvärvat samtliga aktier i norska Servix Plantedekor AS och ökar därmed sin närvaro på den norska marknaden.","body":"Vinge, genom Johan Winnerblad, har biträtt Hässelby Blommor Holding AB.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-hasselby-blommor-vid-forvarv-av-servix-plantedekor/","date":"2025-07-03","month":7},{"year":2025,"client":"Consolid","work":"Övrigt","disciplines":["Private Funds"],"title":"Vinge har biträtt Consolid vid etableringen av Consolid Equity III","caption":"Övrigt · 2 juli 2025","preamble":"Fonden höll sin final closing den 2 juni 2025 efter att ha rest kapital från en investerarbas bestående av bl.a. flertalet institutionella investerare från Europa och Nordamerika samt etablerade fond-i-fonder. Kapitalanskaffningen var mycket framgångsrik och fonden blev kraftigt övertecknad. Consolid Equity III har mer än dubblerat de totala kapitalåtagandena jämfört med föregångarfonden.","body":"Consolid investerar i företag med hög potential i Norden och Nordeuropa inom affärstjänster och tillhandahåller den expertis, de idéer och det kapital företagen behöver för att växa och skala upp. Genom att samarbeta nära med entreprenörer skapar Consolid möjligheter att utveckla företag som omdefinierar sina branscher.\n\nVinges team har huvudsakligen bestått av Mattias Schömer, Marcus Andersson, Ulf Nilsson, Emelie Svanberg, Anton Sjökvist, Semir Omerbasic, Rebecka Margolin, Tobias Onegård Karlsson, Marcus Svärd, Saga Meyer Viklund, Emelie Zingmark och Lovisa Lagerkvist.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-consolid-vid-etableringen-av-consolid-equity-iii/","date":"2025-07-02","month":7},{"year":2025,"client":"EQT VIII","work":"Avyttring","disciplines":["M&A","Kommersiella avtal","Fastigheter och Entreprenad","Arbetsrätt"],"title":"Vinge har företrätt EQT VIII i samband med försäljningen av Recover till Pangea AS","caption":"Avyttring · 2 juli 2025","preamble":"Recover är en ledande specialist inom fastighetssanering i Skandinavien. Sedan EQT:s förvärv 2020 har Recover investerat i digitalisering och avyttrat icke-kärnverksamheter för att stärka fokuset på vatten, brand och andra centrala tjänster inom fastighetssanering.","body":"Vinges team bestod huvudsakligen av Johanna Wiberg, Amanda Steen och Matilda Hamner (M&A), Niclas Lindblom, Martin Boström och Mario Saad (Commercial Agreements), Madelene Andersson och Sara Franson (Real Estate), Johan Cederblad och Stina Larsson (Regulatory), Louisa Fagarasan (Employment) och Jessica Öijer (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eqt-viii-i-samband-med-forsaljningen-av-recover-till-pangea-as/","date":"2025-07-02","month":7},{"year":2025,"client":"XPartners","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder XPartners vid emission av seniora säkerställda obligationer","caption":"Obligationsemission · 2 juli 2025","preamble":"Vinge biträder XPartners Samhällsbyggnad AB (”XPartners”) vid dess emission av seniora, säkerställda obligationer om SEK 3 miljarder","body":"ABG Sundal Collier AB, Danske Bank A/S, Danmark, Sverige Filial och Nykredit Bank A/S agerade joint bookrunners. Emissionslikviden från obligationen ska, enligt obligationsvillkoren, bland annat användas för att refinansiera XPartners befintliga skuld samt finansiera allmänna företagsändamål, inklusive förvärv och investeringar. Obligationerna ska enligt villkoren tas upp till handel på Nasdaq Stockholms företagsobligationslista inom 12 månader. Obligationerna har en löptid på 4 år och emitterades med en ränta på STIBOR 3m + 550 baspunkter.\n\nObligationsemissionen är den största seniora säkerställda high yield-transaktionen i SEK på den nordiska obligationsmarknaden hittills.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda och William Carlberg Johansson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-xpartners-vid-emission-av-seniora-sakerstallda-obligationer/","date":"2025-07-02","month":7},{"year":2025,"client":"Axcel och Acurum Group","work":"Förvärv","disciplines":["Bank och finans","M&A","Kommersiella avtal","IT, Telekom och Outsourcing","GDPR","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel och Acurum Group vid förvärven av H3o Vatten & Fuktskador och Testab fog & sanering","caption":"Förvärv · 2 juli 2025","preamble":"Vinge har företrätt Axcel VII och Acurum Group i samband med förvärven av H3o Vatten & Fuktskador AB och Testab fog & sanering AB","body":"H3o Vatten & Fuktskador AB och Testab fog & sanering AB är entreprenörsledda, lokalt förankrade bolag med expertis inom fukthantering respektive fukt och sanering. Genom förvärvet av H3o Vatten & Fuktskador AB breddar Acurum Group sitt erbjudande inom fukthantering, med särskilt fokus på utredning samt åtgärder av vatten- och fuktskador. Testab fog & sanering AB kompletterar koncernen med ett brett erbjudande inom sanering av asbest och PCB samt övrig byggnadsteknisk sanering.\n\nAcurum Group består av bolag som erbjuder tjänster inom luftkvalitet, fukthantering och rörunderhåll, och har varit verksamma sedan 2024. Gruppen omfattar idag 19 bolag i Sverige och Norge, med cirka 600 medarbetare och en omsättning på cirka 900 miljoner SEK. Varje bolag verkar under sitt eget varumärke, men utvecklas genom gemensamma initiativ, samarbete och delad kompetens inom gruppen.\n\nVinges team bestod av Christina Kokko, Elsie Nassar, Robin Sultani, Ida Appelgren och Emma Lundberg (M&A), Amelia Rihs (Arbetsrätt), Calle Tengwall Pagels (Bank och finans), Siri Blomberg (Kommersiella avtal, IT och GDPR), Madelene Andersson och Stina Larsson (Fastighet och Miljö) samt Julia Ulander Kull (Projektassistent).\n\nLäs klientens pressmeddelanden här och här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-acurum-group-vid-forvarven-av-h3o-vatten-fuktskador-och-testab-fog-sanering/","date":"2025-07-02","month":7},{"year":2025,"client":"EQT","work":"Avyttring","disciplines":["M&A","Regulatoriska tvister"],"title":"Vinge företräder EQT i samband med försäljningen av Eton","caption":"Avyttring · 1 juli 2025","preamble":"Vinge har företrätt EQT VII i samband med försäljningen av Eton till ett konsortium av privata investerare.","body":"Eton är ett svenskt premiumvarumärke inom herrmode grundat 1928 och med huvudkontor i Gånghester. Eton har en lång tradition av skjorttillverkning och ett växande sortiment av herrkläder som säljs i mer än 50 länder.\n\nVinges team bestod huvudsakligen av Christina Kokko, Johanna Wiberg, Egil Svensson and Alexander Rüdén (M&A), Sebastian Örndahl (Regulatory), Johanna Engström (Transaction Support Coordinator).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-eqt-i-samband-med-forsaljningen-av-eton/","date":"2025-07-01","month":7},{"year":2025,"client":"Triton","work":"Förvärv","disciplines":["M&A","Regulatoriska tvister","Bank och finans","Kommersiella avtal","Arbetsrätt","IT, Telekom och Outsourcing","GDPR","Immaterialrätt","Fastigheter och Entreprenad"],"title":"Vinge företräder Triton vid förvärvet av Prenax","caption":"Förvärv · 1 juli 2025","preamble":"Vinge har företrätt Triton Small Mid Cap Fund II i samband med förvärvet av Prenax från LBO France och vissa minoritetsägare.","body":"Prenax är en ledande leverantör av prenumerationshanteringstjänster. Företaget grundades 1993 och hanterar idag över 340 000 prenumerationer åt sina kunder. Prenax har kontor i 11 länder i UK & Benelux, Norden, Sydeuropa, USA och Australien.\n\nTransaktionen är villkorad av regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Johanna Wiberg, Egil Svensson, Michella Lina Said och Hedvig Merkel (M&A), David Olander och Lovisa Arpi (Regulatory), August Ahlin (Banking and Finance), Mario Saad och Jacob Eberil (Agreements), William Karo Persson (Employment), Carla Håkansson (IT), Siri Blomberg (GDPR), Arvid Axelryd och Melinda Oldenburg (IP), Simon Gille-Johnson (Real Estate), Hayaat Ibrahim (Compliance), Diana Kanold (Transaction Support Coordinator).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-triton-small-mid-cap-fund-ii-i-samband-med-forvarvet-av-prenax-fran-lbo-france-och-vissa-minoritetsagare/","date":"2025-07-01","month":7},{"year":2025,"client":"Impilo","work":"Övrigt","disciplines":["Private Funds"],"title":"Vinge biträder Impilo vid etableringen av Impilo Healthcare","caption":"Övrigt · 1 juli 2025","preamble":"Vinge har biträtt Impilo med regulatorisk rådgivning vid etableringen av Impilo Healthcare. Fonden kommer att ha kapitalåtaganden om 700 miljoner euro.","body":"Impilo är ett nordiskt investeringsbolag som fokuserar på investeringar i medelstora nordiska hälsovårdsföretag inom läkemedel, medicinteknik, sjukvårdstjänster och andra hälsorelaterade branscher. Impilo har en väldiversifierad portfölj av investeringar inom hälsovård och förvaltar cirka EUR 2 miljarder för ledande internationella investerare.\n\nVinges team bestod av Nils Unckel, Anton Sjökvist, Viktoria Wnuk och Isabelle Asserståhl.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-impilo-vid-etableringen-av-impilo-healthcare/","date":"2025-07-01","month":7},{"year":2025,"client":"KEYTO Group","work":"Förvärv","disciplines":["M&A","IT, Telekom och Outsourcing","GDPR","Försäkring","Arbetsrätt","Kommersiella avtal","Immaterialrätt"],"title":"Vinge företräder KEYTO Group i samband med förvärvet av Enspecta","caption":"Förvärv · 1 juli 2025","preamble":"KEYTO fortsätter dess tillväxtresa genom att stärka sitt erbjudande i Sverige genom förvärvet av Enspecta. Detta strategiska förvärv markerar KEYTO's inträde på en ny service-vertikal som fokuserar på besiktning, utvärdering och optimiering av bostäder och stärker ambitionen om att vara en ledande, teknikdriven \"one-stop-shop\" för hushållstjänster.","body":"Vinges team bestod huvudsakligen av Jonas Bergström, Gustav Wahlberg och Ian Linde (M&A), Carla Håkansson och Gabriel Pålsson (Kommersiella avtal), William Karo Persson och Ida Pettersson (Arbetsrätt), Melinda Oldenburg (IP), Nicklas Thorgenzon och Sara Link (IT och GDPR), Olivia Carlsten och Josef Jatta Kölin (Försäkring) samt Caroline Löv (Projekt Assistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-keyto-group-i-samband-med-forvarvet-av-enspecta/","date":"2025-07-01","month":7},{"year":2025,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Lagercrantz Group vid förvärv av Friggeråkers Verkstäder","caption":"Förvärv · 1 juli 2025","preamble":"Lagercrantz Group har förvärvat samtliga aktier i Friggeråkers Verkstäder, en ledande svensk tillverkare av salt- och sandspridare.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Sofia Sallnäs och Ellenor Eckerborn.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-lagercrantz-group-vid-forvarv-av-friggerakers-verkstader/","date":"2025-07-01","month":7},{"year":2025,"client":"Terranor Group","work":"Börsnotering","disciplines":["Kapitalmarknad och publik M&A","M&A","EU‑ och konkurrensrätt","Fastigheter och Entreprenad","Finansiella tillståndsfrågor","Bank och finans","IT, Telekom och Outsourcing","GDPR","Arbetsrätt","Immaterialrätt"],"title":"Vinge har företrätt Terranor Group AB i samband med dess notering på Nasdaq First North Growth Market","caption":"Börsnotering · 30 juni 2025","preamble":"Vinge har företrätt Terranor Group AB (publ) (”Terranor”) i samband med dess notering på Nasdaq First North Growth Market. Första handelsdag i Terranors aktier är idag den 30 juni 2025.","body":"Priset i erbjudandet var 20 kronor per aktie, motsvarande ett totalt marknadsvärde för samtliga aktier i Terranor om 400 miljoner kronor. Det totala värdet av erbjudandet uppgår till 115 miljoner kronor under antagandet att övertilldelningsoptionen utnyttjas till fullo.\n\nTerranor är en av de främsta aktörerna inom vägunderhåll i Norden. Bolagets affärsidé är att erbjuda ett brett utbud av kvalificerade tjänster inom drift och underhåll av vägar för att säkerställa att vägar förblir tillgängliga och funktionella året om. Verksamheten omfattar såväl vinterväghållning, med snöröjning och halkbekämpning, som sommarunderhåll, såsom reparationer och asfaltarbeten. Därtill erbjuder Terranor tjänster inom grönområdesskötsel, trafiksäkerhet och lättare infrastrukturprojekt.\n\nVinges team bestod huvudsakligen av David Andersson, Joel Magnusson, Anna Svensson, Karin Karsten, Johannes Akyol, Sara Franson och Elias Kröger (Kapitalmarknad), Jonas Bergström och Fredrik Eriksson Oppliger (M&A), Hanna Lemne och Julia Rydin (EU- och konkurrensrätt), Calle Tengwall Pagels och Katja Häglund (Finansiering), Mario Saad, Carla Håkansson, Sara Link och Filippa Eriksson (Kommersiella avtal, IT och GDPR), Niclas Lindblom (Entreprenad), Alice Göransson (Arbetsrätt), Hayaat Ibrahim (Regelefterlevnad), Hanna Kövamees (Fastighet) samt Melinda Oldenburg (Immaterialrätt).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-terranor-group-ab-i-samband-med-dess-notering-pa-nasdaq-first-north-growth-market/","date":"2025-06-30","month":6},{"year":2025,"client":"Keyto Group","work":"Förvärv","disciplines":["Bank och finans","M&A"],"title":"Vinge företräder Keyto Group i samband med förvärvet av GreenThumb","caption":"Förvärv · 30 juni 2025","preamble":"KEYTO Group expanderar till den brittiska marknaden genom förvärvet av GreenThumb. Partnerskapet innebär KEYTO:s första inträde på den brittiska marknaden och stärker ambitionerna att bli den ledande, teknikdrivna one-stop-destinationen för hemrelaterade tjänster internationellt.","body":"Vinges team bestod bland annat av Jonas Bergström, Matthias Pannier och Gustav Wahlberg (M&A) samt Linn Adelwald, Lionardo Ojeda och August Ahlin (Bank och Finans).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-keyto-group-i-samband-med-forvarvet-av-greenthumb-keyto-group-expanderar-till-den-brittiska-marknaden-genom-forvarvet-av-greenthumb/","date":"2025-06-30","month":6},{"year":2025,"client":"Hässelby Blommor","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Hässelby Blommor vid förvärv av Luwasa Greenstyling och Bellis Växtmiljö","caption":"Förvärv · 30 juni 2025","preamble":"Hässelby Blommor Holding AB har förvärvat samtliga aktier i Luwasa Greenstyling AB resp. Bellis Växtmiljö i Partille AB och skapar därmed Sveriges starkaste företagsgrupp inom växtinredning.","body":"Vinges team i bägge transaktionerna bestod i huvdsak av Johan Winnerblad och Ian Linde.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-hasselby-blommor-vid-forvarv-av-luwasa-greenstyling-och-bellis-vaxtmiljo/","date":"2025-06-30","month":6},{"year":2025,"client":"Odevo","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Odevo vid förvärvet av Portik Group","caption":"Förvärv · 27 juni 2025","preamble":"Vinge har företrätt Odevo, det internationellt ledande bolaget inom bostadsförvaltning, i samband med förvärvet av Portik Group. Genom förvärvet fortsätter Odevo med sin internationella expansion genom att etablera sig i Spanien, Italien, Portugal och Mexiko.","body":"Vinges team bestod av bland andra av Jonas Bergström, Johanna Wiberg och Gustav Wahlberg (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-odevo-vid-forvarvet-av-portik-group/","date":"2025-06-27","month":6},{"year":2025,"client":"Viking Global Investors","work":"Förvärv","disciplines":["M&A","Företagsbeskattning","IT, Telekom och Outsourcing","GDPR","Bank och finans","Corporate Crime & Compliance","Arbetsrätt","Immaterialrätt","Fastigheter och Entreprenad","FDI"],"title":"Vinge agerade svensk legal rådgivare till Viking Global Investors i ett förvärv av en betydande kontrollerande andel av aktierna i Voyado i en transaktion som värderar bolaget till cirka 3,5 miljarder kronor","caption":"Förvärv · 27 juni 2025","preamble":"Voyado är en snabbväxande och ledande plattform för kundupplevelse inom detaljhandeln och har etablerat sig som en av de mest betrodda teknikleverantörerna i Norden. Plattformen är integrerad i många detaljhandelsföretags affärskritiska infrastruktur och hjälper återförsäljare och varumärken att omvandla kund- och produktdata till lojalitet, optimera e-handelsresultat samt skapa en mer personlig köpupplevelse – både i butik och online.","body":"Viking kommer att samarbeta med Voyados grundare samt befintliga institutionella investerare, däribland NovAx, Verdane, H&M och eEquity, som samtliga kvarstår som aktieägare i bolaget.\n\nTransaktionen är föremål för sedvanliga myndighetsgodkännanden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Matthias Pannier, Edvard Gustafsson, Alex Forsberg och Ellenor Eckerborn (M&A), Victor Ericsson (Skatt), Mathilda Persson, Nicklas Thorgerzon, Elis Allmark och Siri Blomberg (Kommersiella avtal, IT och GDPR), Nour Makie och Ida Appelgren (Bank och Finans), Hayaat Ibrahim och Gulestan Ali (Compliance), Simon Söderholm och Agnes Pigg (Arbetsrätt), Arvid Axelryd, Alva Skott och Maja Helm (IP), Madelene Andersson och Wilma Hellman (Fastighet och Miljö), Daniel Wendelsson och Hampus Peterson (FDI), Julia Ulander Kull (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-agerade-svensk-legal-radgivare-till-viking-global-investors-i-ett-forvarv-av-en-betydande-kontrollerande-andel-av-aktierna-i-voyado-i-en-transaktion-som-varderar-bolaget-till-cirka-3-5-miljarder-kronor/","date":"2025-06-27","month":6},{"year":2025,"client":"Anyfin","work":"Finansiering","disciplines":["Private Funds","Finansiella tillståndsfrågor"],"title":"Vinge biträder Anyfin med ansökan om att bedriva finansieringsrörelse","caption":"Finansiering · 25 juni 2025","preamble":"Vinge har, tillsammans med PwC, biträtt Anyfin med regulatorisk rådgivning i samband med dess ansökan om att bedriva finansieringsrörelse enligt lagen (2004:297) om bank- och finansieringsrörelse. Finansinspektionen beviljade tillståndet den 17 juni 2025.","body":"Anyfin hjälper sina kunder att sänka sina räntekostnader genom att omfinansiera ursprungliga krediter och ge bättre erbjudanden på kundernas lån.\n\nVinges team har huvudsakligen bestått av Johan Larsson, Nils Unckel och Anton Sjökvist.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-anyfin-med-ansokan-om-att-bedriva-finansieringsrorelse/","date":"2025-06-25","month":6},{"year":2025,"client":"Lantmännen","work":"Avyttring","disciplines":["M&A","IT, Telekom och Outsourcing","EU‑ och konkurrensrätt","Kommersiella avtal","Carve-Outs"],"title":"Vinge företräder Lantmännen i samband med avyttringen av Swecon till Volvo Construction Equipment","caption":"Avyttring · 25 juni 2025","preamble":"Lantmännen Ek För har tecknat avtal om att avyttra Swecon till Volvo Construction Equipment (Volvo CE). Volvo CE kommer att betala 7 miljarder kronor för förvärvet. Transaktionen är villkorad av myndighetsgodkännanden och förväntas kunna slutföras under andra halvåret 2025.","body":"Transaktionen inkluderar hela Swecons affär i samtliga länder: det vill säga försäljning av produkter och tjänster, hyresverksamhet, service på eftermarknaden och kundsupport, samt kontor, verkstäder och 1 400 anställda. Avtalet inkluderar även Entrack. Swecon har varit en del av Lantmännen sedan företaget grundades för 25 år sedan, och nettoomsättningen 2024 uppgick till 10 miljarder SEK. Volvo CE ser detta som ett strategiskt drag för ökade investeringar i återförsäljarledet på ett antal nyckelmarknader – däribland Tyskland, som är Europas största marknad för anläggningsmaskiner och Sverige, som är Volvo CE:s hemmamarknad – samt Estland, Lettland och Litauen. Tillsammans med den återförsäljarverksamhet man redan äger, innebär detta förvärv att Volvo CE kommer att äga och driva majoriteten av företagets affärer i Europa, vilket innebär att återförsäljningsverksamhet blir en ny kärnaffär för Volvo CE i Europa.\n\nVinges team bestod huvudsakligen av Christina Kokko, Gustav Wahlberg, Alex Forsberg och Josef Groow (M&A), Eva Fredriksson och Elis Allmark (IT/TSA), Marcus Glader och Hampus Peterson (EU – och konkurrensrätt) Christoffer Nordin (Kommersiella avtal) samt Johanna Engström och Emy Rydén (Projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-lantmannen-i-samband-med-avyttringen-av-swecon-till-volvo-construction-equipment/","date":"2025-06-25","month":6},{"year":2025,"client":"Axcel VI och Currentum","work":"Förvärv","disciplines":["Fastigheter och Entreprenad","Arbetsrätt","EU‑ och konkurrensrätt","M&A"],"title":"Vinge företräder Axcel VI och Currentum vid förvärv av Elprojekt Skandinavien","caption":"Förvärv · 23 juni 2025","preamble":"Vinge företräder Axcel VI och Currentum-koncernen vid förvärvet av Elprojekt Skandinavien. Bolaget levererar kompletta elinstallationer i hela Sverige med fokus på nybyggnation av logistikfastigheter, produktionsanläggningar, flerbostadshus och kontorsbyggnader. Under 2024 omsatte Elprojekt Skandinavien 316 miljoner kronor.","body":"Förvärvet är villkorat av sedvanliga myndighetsgodkännanden.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Egil Svensson, Alexander Rüdén och Ian Linde (M&A), Niclas Lindblom (Entreprenadrätt), Simon Gille-Johnson och Wilma Hellman (Fastighetsrätt), Jonna Skog och Louisa Fagarasan (Arbetsrätt), David Olander och Hilda Ivarsson (EU- och konkurrensrätt) samt Emelie Schoning (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-vi-och-currentum-vid-forvarv-av-elprojekt-skandinavien/","date":"2025-06-23","month":6},{"year":2025,"client":"Meribel Pharma Solutions","work":"Övrigt","disciplines":["M&A","Corporate Commercial"],"title":"Vinge företräder Meribel Pharma Solutions","caption":"Övrigt · 23 juni 2025","preamble":"Vinge företräder Meribel Pharma Solutions i samband med försäljning av en produktionsanläggning specialiserad på tillverkning av antibiotika till Apotek Produktion & Laboratorier AB (\"APL\").","body":"Anläggningen är belägen i Strängnäs och erbjuder specialiserad expertis och omfattande tjänster som stödjer utveckling och tillverkning av orala fasta läkemedel och har specialiserad infrastruktur för produktion av betalaktamer. APL som nu förvärvar anläggningen är ett statligt helägt bolag med ett samhällsuppdrag att utveckla och tillhandahålla ett medicinskt ändamålsenligt och kvalitetssäkrat sortiment av extemporeläkemedel och lagerberedningar. Förvärvet är ett viktigt steg för svenska staten att stärka Sveriges beredskap och säkerställa tillgången till livsviktiga läkemedel i Sverige, särskilt under krissituationer.\n\nLäs mer på Regeringens hemsida här.\n\nVinges team bestod av bland andra Jonas Bergström, Per Kling och Ellenor Eckerborn (M&A), Mathilda Persson och Siri Blomberg (Corporate Commercial), samt Åsa Hellstadius och Ian Jonson (Life Science).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-meribel-pharma-solutions/","date":"2025-06-23","month":6},{"year":2025,"client":"Hansa Biopharma","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Hansa Biopharma i samband med en riktad nyemission om cirka 232 miljoner kronor och omstrukturering av skuldfinansiering","caption":"Kapitalanskaffning · 23 juni 2025","preamble":"Vinge har biträtt Hansa Biopharma AB (publ) i samband med en riktad nyemission, varigenom Hansa tillförs cirka 232 miljoner kronor före transaktionskostnader, och omstrukturering av skuldfinansiering. Som en del av sådan skuldomstrukturering har Hansa i samband med den riktade emissionen kvittat skulder motsvarande cirka 14,9 miljoner USD av sitt totala skuldbelopp.","body":"Hansa Biopharma AB är ett biofarmabolag i kommersiell fas som utvecklar innovativa, livräddande och livsförändrande behandlingar för patienter med sällsynta immunologiska sjukdomstillstånd. Bolaget är noterat på Nasdaq Stockholm.\n\nVinges team har bestått av Dain Hård Nevonen, Joel Magnusson, Annie Fällström och Amanda Sandström.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-hansa-biopharma-i-samband-med-en-riktad-nyemission-om-cirka-232-miljoner-kronor-och-omstrukturering-av-skuldfinansiering/","date":"2025-06-23","month":6},{"year":2025,"client":"Sveafastigheter","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","Företagsbeskattning","Arbetsrätt","Fastigheter och Entreprenad"],"title":"Vinge har företrätt Sveafastigheter i samband med dess listbyte till Nasdaq Stockholm","caption":"Övrigt · 18 juni 2025","preamble":"Vinge har företrätt Sveafastigheter AB (publ) i samband med dess listbyte från Nasdaq First North Premier Growth Market till Nasdaq Stockholm. Prospektet offentliggjordes den 13 juni 2025 och handeln på Nasdaq Stockholm inleddes den 18 juni 2025.","body":"Sveafastigheter är ett fastighetsbolag som äger, aktivt förvaltar och utvecklar bostadsfastigheter över hela Sverige med fokus på hyresrätter i utvalda tillväxtregioner. Fastighetsportföljen består av fastigheter i förvaltning, pågående byggnation och projektutveckling med ett totalt fastighetsvärde uppgående till cirka 28,2 miljarder kronor.\n\nVinges team har huvudsakligen bestått av Rikard Lindahl, Benjamin Vafaeian, Filip Magnusson och Carl Lexenberg (Kapitalmarknad och Publik M&A), Victor Ericsson, Emelie Svanberg, Erik Kochbati och Marcus Svärd (Företagsbeskattning), Emil Lindwall och Agnes Pigg (Arbetsrätt), Felix Möller och William Carlberg Johansson (Finansiering), Ian Jonson (IPR), Kristoffer Larson (Fastighet) samt Diana Kanold (VDR).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-sveafastigheter-i-samband-med-dess-listbyte-till-nasdaq-stockholm/","date":"2025-06-18","month":6},{"year":2025,"client":"Platzer","work":"Avyttring","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge företrädde Platzer i en försäljning av en fastighet i Södra Änggården, Göteborg","caption":"Avyttring · 17 juni 2025","preamble":"Fastigheten är en projektfastighet med en byggrätt för ett parkeringshus om 16 000 kvm. Försäljningen görs som en bolagstransaktion med en pågående entreprenad.","body":"Från Vinges sida medverkade Olof Jisland, Kristoffer Larson samt Alexandra Petersdottir.","href":"https://www.vinge.se/uppdrag/vinge-foretradde-platzer-i-en-forsaljning-av-en-fastighet-i-sodra-anggarden-goteborg/","date":"2025-06-17","month":6},{"year":2025,"client":"Bridgepoint","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","IT, Telekom och Outsourcing","GDPR","FDI","Fastigheter och Entreprenad","Arbetsrätt","Immaterialrätt"],"title":"Vinge biträder Bridgepoint i deras förvärv av Safe Life","caption":"Förvärv · 16 juni 2025","preamble":"Vinge biträder Bridgepoint i ett förvärv av en betydande kontrollerande andel av aktierna i Safe Life AB i en transaktion som värderar bolaget till cirka 500 miljoner Euro.","body":"Safe Life, med huvudkontor i Stockholm, är verksamt i Nordamerika och Europa och en marknadsledare inom distribution av automatiska externa defibrillatorer (AED) inom en mycket fragmenterad och snabbväxande sektor. Safe Life utrustar samhällen och arbetsplatser med livräddande AED:er som stöds av löpande service, inklusive HLR-utbildning, underhåll och reservdelar som dynor och batterier för att möjliggöra en snabb och effektiv respons i en nödsituation.\n\nBridgepoint kommer att samarbeta med Safe Lifes grundare och befintliga institutionella investerare, inklusive Byggmästaren, Bonnier Capital och Swedbank Robur, som alla återinvesterar väsentligt tillsammans med Bridgepoint.\n\nTransaktionen är föremål för sedvanliga myndighetsgodkännanden.\n\nVinges team bestod huvudsakligen av Daniel Rosvall, Samra Tesser, Johanna Hamrefält, Sara Hammond och Oliwer Vidarsson (M&A), Albert Wållgren, Josefine Lanker, Calle Tengwall Pagels och Gabriel Chabo (Bank och Finans), Mario Saad, Filippa Eriksson och Carla Håkansson (Kommersiella avtal, IT och GDPR), Christoffer Nordin (Regulatoriska tillstånd), Simon Söderholm och Viktor Lundberg (Arbetsrätt), Ian Jonson (IP), Hanna Kövamees och Wilma Hellman (Fastighet och Miljö), Sebastian Örndahl, Fredrik Hellström och Hilda Ivarsson (FDI), Julia Ulander Kull (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-bridgepoint-i-deras-forvarv-av-safe-life-1/","date":"2025-06-16","month":6},{"year":2025,"client":"Armada Investment AG","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A","FDI"],"title":"Vinge biträder Armada Investment AG i dess investering i Studsvik","caption":"Kapitalanskaffning · 16 juni 2025","preamble":"Armada Investment AG, ett entreprenörsdrivet investmentbolag baserat i Zürich som leds av Daniel S. Aegerter, har ökat sitt aktieinnehav i Studsvik till 29,9 % av de utestående aktierna i Studsvik. Investeringen bygger på Armadas initiala innehav om 9,9 % som förvärvades i februari 2025. Aktierna i Studsvik är upptagna till handel på Nasdaq Stockholm. Armada har i över ett decennium investerat i hela värdekedjan för kärnkraft med portföljbolag som Oklo, Commonwealth Fusion Systems, Proxima Fusion, Last Energy och Blykalla.","body":"Studsvik erbjuder en rad avancerade tekniska tjänster till den globala kärnkraftsindustrin. Studsviks fokusområden är bränsle- och materialteknik, programvara för härdövervakning och bränsleoptimering, avveckling och strålskyddstjänster samt tekniska lösningar för hantering, konditionering och volymreduktion av radioaktivt avfall. Företaget har över 75 års erfarenhet av kärnteknik och tjänster i radiologisk miljö.\n\nVinges team består av Rikard Lindahl, Joel Magnusson och Maximilian Bengtsson (Kapitalmarknad och publik M&A) samt Daniel Wendelsson, Hampus Peterson och Hilda Ivarsson (FDI).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-armada-investment-ag-i-dess-investering-i-studsvik/","date":"2025-06-16","month":6},{"year":2025,"client":"Karl Hedin och minoritetsägarna","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder Karl Hedin och minoritetsägarna vid försäljningen av Toftani Metsanduse OÜ till OÜ Metsavennaskond","caption":"Avyttring · 13 juni 2025","preamble":"Vinge har företrätt Karl Hedin och minoritetsägarna i samband med försäljningen av Toftani Metsanduse OÜ till OÜ Metsavennaskond.","body":"OÜ Metsavennaskond är en estnisk aktör med verksamhet inom skogsbruk. Verksamheten i Toftani Metsanduse OÜ omfattar totalt cirka 10 800 hektar skog och mark i Estland, med en virkesvolym om cirka 1,1 miljoner skogskubikmeter. Förvärvet omfattar samtliga aktier Toftani Metsanduse OÜ. Försäljningen är villkorad av konkurrensrättslig prövning.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Johan Winnerblad, Egil Svensson och Olof Löfvenberg (M&A) samt Jessica Öijer (Projektassistent).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-karl-hedin-och-minoritetsagarna-vid-forsaljningen-av-toftani-metsanduse-ou-till-ou-metsavennaskond/","date":"2025-06-13","month":6},{"year":2025,"client":"Fidelio Capital","work":"Kapitalanskaffning","disciplines":["Bank och finans","Corporate Commercial","Corporate Crime & Compliance","Fastigheter och Entreprenad","EU‑ och konkurrensrätt","M&A"],"title":"Vinge har biträtt Fidelio Capital AB vid deras investering i Newsec AB","caption":"Kapitalanskaffning · 9 juni 2025","preamble":"Vinge har biträtt Fidelio Capital AB vid bolagets investering i Newsec AB, ett ledande företag inom fastighetsförvaltning och rådgivning i Norden och Baltikum. Fidelio Capital AB har en vision om att expandera verksamheten genom bland annat företagsförvärv och digital utveckling inom fastighetsförvaltning.","body":"Vinges team bestod huvudsakligen av Jonas Bergström, Johanna Wiberg, Per Kling, Sofia Sallnäs, Josef Groow, Alva Thörn, Sara Eirefors (M&A), Emil Lindwall, Ida Pettersson (Arbetsrätt), Hayaat Ibrahim, Jonna Fransson (Compliance), Niclas Lindblom, Hanna Kövamees, Wilma Hellman (Fastighet), Niklas Thorgerzon, Hedvig Ekdahl, Sara Link, Filippa Eriksson (Corporate Commercial), Nour Makie, Rebecka Margolin (Bank och finans) Alva Skott (IP), Sebastian Örndahl, Hilda Ivarsson, Hanna Lemne, (Competition), Gabriella Balbo (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-fidelio-capital-ab-vid-dess-investering-i-newsec-ab/","date":"2025-06-09","month":6},{"year":2025,"client":"Brand Equity Group Sweden","work":"Förvärv","disciplines":["GDPR","Kommersiella avtal","M&A"],"title":"Vinge har företrätt Brand Equity Group Sweden AB i samband med dess förvärv av PREVOX REKLAM Aktiebolag och Jonas Anderzson of Sweden AB","caption":"Förvärv · 9 juni 2025","preamble":"Vinge har företrätt Brand Equity Group Sweden AB i samband med dess parallella förvärv av PREVOX REKLAM Aktiebolag och Jonas Anderzson of Sweden AB. De förvärvade verksamheterna bedriver produktmedieverksamhet, med huvudsaklig inriktning mot marknadsföring och produktion av produktmedia. Genom förvärven stärker Brand Equity Group Sweden AB sin position i Sverige inom produktmedia och varumärkeskommunikation.","body":"Vinges team bestod huvudsakligen av Jonas Johansson, Philip Moré och Linn Aho (M&A), Christoffer Nordin (Kommersiella avtal), Nicklas Thorgerzon (GDPR) och Jasmina Skandrani (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-brand-equity-group-sweden-ab-i-samband-med-dess-forvarv-av-prevox-reklam-aktiebolag-och-jonas-anderzson-of-sweden-ab/","date":"2025-06-09","month":6},{"year":2025,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Lagercrantz Group vid förvärv av ORAX","caption":"Förvärv · 4 juni 2025","preamble":"Lagercrantz Group har förvärvat samtliga aktier i AB ORAX, en ledande aktör av produkter för hantering och skötsel inom begravnings- och kyrkogårdssektorn.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Sofia Sallnäs och Ellenor Eckerborn.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-lagercrantz-group-vid-forvarv-av-orax/","date":"2025-06-04","month":6},{"year":2025,"client":"Eleda","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Bank och finans","Fastigheter och Entreprenad","GDPR","FDI","Immaterialrätt"],"title":"Vinge har företrätt Eleda i samband med dess förvärv av Rail Solutions Scandinavia AB, Gridtec AB, Quantity Surveying Konsult Stockholm AB, Voene AB, Vägservice centralen i Norden AB och Frästech AB.","caption":"Förvärv · 4 juni 2025","preamble":"Vinge har företrätt den ledande infrastrukturkoncernen Eleda i samband med dess parallella förvärv av Rail Solutions Scandinavia (järnvägsunderhåll), Gridtec (teknikkonsulttjänster inom elkraft), Quantity Surveying Konsult Stockholm (kostnadskontroll och projektledning), Voene (trafiksäkerhet), Vägservice centralen i Norden och Frästech (väg- och brounderhåll). De förvärvade verksamheterna hade en stark lönsamhet med en sammanlagd omsättning på cirka 200 MSEK under 2024.","body":"Samtliga bolag är nischaktörer som kompletterar de över 50 andra verksamheterna inom Eleda. Genom förvärven stärker Eleda sin ledande position inom kritisk infrastruktur i Norden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Johanna Wiberg, Carl Fredrik Wachtmeister, Philip Moré, Madelene Andersson, Nicolina Lavdas, Jonatan Stentorp, Alex Forsberg, Kabbo Iftekhayer och Lina Björkman (M&A), Simon Söderholm, Emil Lindwall, Alice Göransson och Louisa Fagarasan (Arbetsrätt), Calle Tengwall Pagels, Nilufer Nouri och Julia Gudmundsson (Bank och finans), Hanna Kövamees och Wilma Hellman (Fastighet), Niclas Lindblom (Entreprenad), Nicklas Thorgerzon och Carla Håkansson (GDPR), Daniel Wendelsson, David Olander, Alva Chambert och Hampus Peterson (Konkurrensrätt och FDI), Melinda Oldenburg (Immaterialrätt) samt Gabriella Balbo och Filippa Bergkvist (Projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-i-samband-med-dess-forvarv-av-rail-solutions-scandinavia-ab-gridtec-ab-quantity-surveying-konsult-stockholm-ab-voene-ab-vagservice-centralen-i-norden-ab-och-frastech-ab/","date":"2025-06-04","month":6},{"year":2025,"client":"Bauer Media","work":"Övrigt","disciplines":["M&A","Finansiella tillståndsfrågor"],"title":"Vinge har företrätt Bauer Media i samband med integreringen av Bauer Medias Zmarta Group i Axo","caption":"Övrigt · 4 juni 2025","preamble":"Bauer Media Group blev minoritetsägare i Axo.","body":"Vinges team bestod av Matthias Pannier, Gustav Persson, Matilda Hamner (M&A) och Caroline Krassén (Financial Regulatory).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-bauer-media-i-samband-med-integreringen-av-bauer-medias-zmarta-group-i-axo/","date":"2025-06-04","month":6},{"year":2025,"client":"Marginalen Bank","work":"Kapitalanskaffning","disciplines":["Bank och finans"],"title":"Vinge har biträtt Marginalen Bank i samband med ett byte av emittent för dess utestående kapitalbasinstrument och emission av nya kapitalbasinstrument","caption":"Kapitalanskaffning · 3 juni 2025","preamble":"Vinge har biträtt Marginalen Bank Bankaktiebolag (publ) i samband med byte av emittent för dess utestående kapitalbasinstrument, som består av supplementärkapitalinstrument (Eng. Tier 2 Notes) om totalt 560 miljoner kronor och primärkapitalinstrument (Eng. Additional Tier 1-Notes) om 200 miljoner kronor. ESCO Marginalen AB (publ) övertog samtliga förpliktelser enligt de befintliga kapitalbasinstrumenten i samband med transaktionen, medan Marginalen Bank emitterar nya kapitalbasinstrument om motsvarande belopp genom kvittning.","body":"Vinge bistod med ansökan om godkännande av emittentbytet hos Finansinspektionen, inhämtande av samtycke från obligationsinnehavarna genom skriftliga förfaranden och koordinering med Nasdaq avseende fortsatt upptagande till handel av de befintliga kapitalbasinstrumenten på Nasdaq Stockholm.\n\nABG Sundal Collier var finansiell rådgivare i transaktionen.\n\nVinges team bestod av Mikael Ståhl, Arvid Weimers, Henrik Schön, Katja Häglund och Julia Gudmundsson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-marginalen-bank-i-samband-med-ett-byte-av-emittent-for-dess-utestaende-kapitalbasinstrument-och-emission-av-nya-kapitalbasinstrument/","date":"2025-06-03","month":6},{"year":2025,"client":"Sveafastigheter","work":"Obligationsemission","disciplines":[],"title":"Vinge biträder Sveafastigheter vid dess etablering av MTN-program samt emission av gröna obligationer om totalt SEK 1 200 miljoner","caption":"Obligationsemission · 30 maj 2025","preamble":"Vinge har biträtt Sveafastigheter AB (publ) (”Sveafastigheter”) vid dess etablering av ett medium-term note-program (”MTN-program”) med ett rambelopp om SEK 8 miljarder, samt dess emission av gröna seniora icke-säkerställda obligationer om totalt SEK 1 200 miljoner","body":"Grundprospektet för MTN-programmet godkändes av Finansinspektionen den 15 maj 2025. I anslutning till programmet har Sveafastigheter etablerat ett grönt ramverk som möjliggör emission av gröna obligationer. Swedbank agerar arrangör under MTN-programmet och kommer tillsammans med Nordea och SEB att agera emissionsinstitut.\n\nDen 22 maj 2025 emitterade Sveafastigheter gröna seniora icke-säkerställda obligationer om totalt SEK 1 200 miljoner med löptider om 3 respektive 5 år under sitt MTN-program. De 3-åriga obligationerna om SEK 900 miljoner löper med en ränta om 3 månaders STIBOR plus 1,85 %, medan de 5-åriga obligationerna om SEK 300 miljoner löper med en ränta om 3 månaders STIBOR plus 2,25 %. Emissionslikviden från obligationerna kommer att användas i enlighet med Sveafastigheters gröna ramverk för obligationer.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, August Ahlin och William Carlberg Johansson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sveafastigheter-vid-dess-etablering-av-mtn-program-samt-emission-av-grona-obligationer-om-totalt-sek-1-200-miljoner/","date":"2025-05-30","month":5},{"year":2025,"client":"ABG Sundal Collier","work":"Obligationsemission","disciplines":[],"title":"Vinge biträder ABG Sundal Collier vid datacenterleverantören Conaptos första emission av seniora säkerställda obligationer om 500 miljoner kronor","caption":"Obligationsemission · 30 maj 2025","preamble":"Vinge har biträtt ABG Sundal Collier i samband med Conapto Holding AB (publ) första emission av seniora säkerställda obligationer om 500 miljoner kronor, inom ett ramverk om upp till 1 miljard kronor. Conapto, ett portföljbolag till den europeiska infrastrukturfonden Marguerite, är en ledande leverantör av datacenterlösningar.","body":"Obligationerna löper med rörlig ränta och har en löptid om tre år. Conapto avser att ansöka om notering av obligationerna på Nasdaq Transfer Market inom 60 dagar och sedan Nasdaq Stockholm inom 12 månader. Emissionslikviden kommer att användas för refinansiering av befintlig skuld samt för investeringar i bolagets fjärde datacenter.\n\nVinges team bestod av Mikael Ståhl, Arvid Weimers, August Ahlin och Nilufer Nouri.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-abg-sundal-collier-vid-datacenterleverantoren-conaptos-forsta-emission-av-seniora-sakerstallda-obligationer-om-500-miljoner-kronor/","date":"2025-05-30","month":5},{"year":2025,"client":"Vimian","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Vimian i samband med ny RCF och emission av seniora icke-säkerställda obligationer","caption":"Obligationsemission · 28 maj 2025","preamble":"Vinge biträder Vimian Group AB (publ) (“Vimian”) i samband med ett nytt revolverande kreditfacilitetsavtal om 330 miljoner EUR som kan utnyttjas i flera valutor samt dess emission av seniora icke-säkerställda obligationer om 150 miljoner EUR (inom en ram om 250 miljoner EUR)","body":"Den revolverande kreditfaciliteten och emissionslikviden från obligationerna ska bland annat användas för att refinansiera Vimians befintliga termins- och revolverande kreditfacilitetsavtal samt för att finansiera allmänna företagsändamål.\n\nKreditfaciliteten, arrangerad av Nordea Bank Abp, filial i Sverige, DNB Bank ASA, filial Sverige, och Skandinaviska Enskilda Banken AB (publ), består av en revolverande kreditfacilitet om 330 miljoner EUR som kan utnyttjas i flera valutor (med möjlighet till en icke-bindande tilläggsfacilitet om upp till 100 miljoner EUR). Avtalet löper över tre år med option till förlängning.\n\nObligationerna har en löptid om tre år och emitterades med en ränta på EURIBOR 3m plus 200 baspunkter. Obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms företagsobligationslista. DNB Carnegie Investment Bank AB (publ), Nordea Bank Abp, och Skandinaviska Enskilda Banken AB (publ) agerade joint bookrunners i samband med obligationsemissionen.\n\nVimian är ett globalt djurhälsobolag med verksamhet inom fyra områden i snabb utveckling: Specialty Pharma, MedTech, Veterinary Services och Diagnostics. Vimian har huvudkontor i Stockholm och når fler än 17 000 veterinärkliniker och laboratorier. Vimian säljer till över 80 marknader, har 1200 medarbetare och en årlig omsättning om cirka 375 miljoner EUR. Vimians aktier är noterade på Nasdaq Stockholm.\n\nVinges team bestod av Albert Wållgren, Linn Adelwald, Lionardo Ojeda och William Carlberg Johansson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vimian-i-samband-med-ny-rcf-och-emission-av-seniora-icke-sakerstallda-obligationer/","date":"2025-05-28","month":5},{"year":2025,"client":"Alrik Technologies","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Alrik Technologies i samband med ny finansieringsrunda","caption":"Kapitalanskaffning · 27 maj 2025","preamble":"Vinge har företrätt Alrik Technologies i samband med ny finansieringsrunda som leddes av People Ventures. Pi Labs, som ledde den senaste finansieringsrundan, valde att dubbla sin tidigare investering genom sitt deltagande även i denna runda.","body":"Alrik Technologies lanserades 2023 och erbjuder ett globalt operativsystem för bygglogistik som ger leverantörer, handlare och distributörer, transportörer, lastbilschaufförer och byggarbetsplatser möjlighet att samarbeta genom en sammanlänkad plattform. Företaget har redan tagit ledningen i Norden och säkrat stora kunder som Saint-Gobain, Renta, Byggmax, Sonsab, XL-Bygg och Karl Hedin, och expanderar nu över norra Europa.\n\nVinges team bestod av Jonas Johansson, Maria Dahlin Kolvik och Paola Lopez.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-alrik-technologies-i-samband-med-ny-finansieringsrunda/","date":"2025-05-27","month":5},{"year":2025,"client":"Bilia","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Miljörätt","Fastigheter och Entreprenad","Kommersiella avtal","IT, Telekom och Outsourcing","Immaterialrätt","FDI"],"title":"Vinge har företrätt Bilia AB i samband med förvärv av lastbilsverksamhet för varumärket Volvo Lastvagnar Sverige","caption":"Förvärv · 27 maj 2025","preamble":"Vinge har företrätt Bilia AB (publ) i samband med förvärvet av BRK Lastvagnar Holding AB och dotterbolagen Tage Rejmes Lastvagnar AB och Tage Rejmes i Örebro Lastvagnar AB som bedriver försäljning och service med kringliggande tjänster för lastbilar av varumärket Volvo Lastvagnar. Tillträde beräknas ske i början av juli 2025 och förvärvet är villkorat av sedvanliga myndighetsgodkännanden.","body":"Verksamheten bedrivs i nio anläggningar i mellersta Sverige och Bilia kommer fortsätta bedriva verksamhet i de berörda fastigheterna likt idag.\n\nVinges team har bestått av ansvarig delägare Magnus Pauli, Martin E Svanberg (projektledare), Hanna Marberg (M&A), Tyra Fellbom von Mentzer (Arbetsrätt och Compliance), Stina Larsson och Johan Cederblad (Miljö), Adam Loewenstein (Fastighet), Anna Drugge (Kommersiella Avtal), Michaela Örtberg (IT och IP rättigheter och dataskydd), Sofia Haggren och Marcus Bergström (Bolagsrätt och Finansiering), Victoria Gunnerek och Rebecca Edvardsson (Konkurrensrätt), Fredrik Löwenclou (FDI), Amanda Stoltz (Projektstöd).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-bilia-ab-i-samband-med-forvarv-av-lastbilsverksamhet-for-varumarket-volvo-lastvagnar-sverige/","date":"2025-05-27","month":5},{"year":2025,"client":"Trinax","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Trinax vid förvärv av Struqtur","caption":"Förvärv · 26 maj 2025","preamble":"Trinax, ett portföljbolag till Helix Kapital, har förvärvat Struqtur, ett svenskt bolag som erbjuder en heltäckande molnbaserad mjukvarulösning för tidrapportering, projekthantering och arbetsorder.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Nicolina Lavdas, Melinda Oldenburg, Carla Håkansson, William Karo Persson och Julia Gudmundsson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-trinax-vid-forvarv-av-struqtur/","date":"2025-05-26","month":5},{"year":2025,"client":"Viva Wine Group","work":"Förvärv","disciplines":["M&A","Bank och finans"],"title":"Vinge företräder Viva Wine Group i samband med förvärvet av Delta Wines","caption":"Förvärv · 26 maj 2025","preamble":"Vinge har agerat som legal rådgivare till Viva Wine Group i samband med förvärvet av Delta Wines, en ledande vindistributör i Europa. Transaktionen har genomförts på basis av ett bolagsvärde om cirka 76 miljoner EUR på en kontant- och skuldfri basis.","body":"Vinges team bestod av Anna Jonsson, Niklas Törnell och Nathalie Wikman (M&A) samt Henrik Ossborn och Agaton Lindgren (Bank och finans).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-viva-wine-group-i-samband-med-forvarvet-av-delta-wines/","date":"2025-05-26","month":5},{"year":2025,"client":"Stendörren","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Stendörren vid emission av gröna obligationer och återköpserbjudande","caption":"Obligationsemission · 23 maj 2025","preamble":"Vinge biträder Stendörren Fastigheter AB vid dess emission av seniora, icke-säkerställda gröna obligationer om SEK 500 miljoner (inom en ram om SEK 800 miljoner kronor) och i samband med bolagets parallella återköpserbjudande till investerare i dess tidigare emitterade obligationer med förfall under 2026.","body":"Swedbank AB (publ) och Danske Bank A/S, Danmark, Sverige Filial agerade joint bookrunners och dealer managers i transaktionen.\n\nEmissionslikviden från den nya obligationen ska, i enlighet med Stendörrens gröna finansieringsramverk, användas för att refinansiera Stendörrens gröna fastighetsbestånd och finansiera återköpserbjudandet. Obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms lista för gröna obligationer. Obligationerna har en ungefärlig löptid om 3,3 år och emitterades med en ränta på STIBOR 3m + 260 baspunkter.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, August Ahlin och Julia Gudmundsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-stendorren-vid-emission-av-grona-obligationer-och-aterkopserbjudande-1/","date":"2025-05-23","month":5},{"year":2025,"client":"Karl Hedin och minoritetsägarna","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder Karl Hedin och minoritetsägarna i samband med försäljningen av AS Toftan till Combiwood","caption":"Avyttring · 22 maj 2025","preamble":"Vinge har företrätt Karl Hedin och minoritetsägarna i samband med försäljningen av AS Toftan till Combiwood Grupp OÜ (”Combiwood”).","body":"Combiwood är en av Estlands ledande träkoncerner med cirka 900 anställda och en årlig omsättning om cirka 210 miljoner euro. Koncernen driver flera träförädlingsanläggningar runtom i Estland. AS Toftan är en etablerad aktör inom träindustrin och kommer att fortsätta sin verksamhet under nuvarande namn och varumärke med Martin Arula som VD. Förvärvet väntas stärka bolagens långsiktiga tillväxt samt deras fortsatta satsningar på hållbar träförädling. Tillsammans kommer de två bolagen ha en gemensam omsättning om cirka 276 miljoner euro och cirka 990 anställda. Försäljningen av AS Toftan är villkorad av konkurrensrättslig prövning.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Johan Winnerblad, Egil Svensson och Olof Löfvenberg (M&A) samt Jessica Öijer (Projektassistent).\n\nLäs klientens pressmeddelande här","href":"https://www.vinge.se/uppdrag/vinge-foretrader-karl-hedin-och-minoritetsagarna-i-samband-med-forsaljningen-av-as-toftan-till-combiwood/","date":"2025-05-22","month":5},{"year":2025,"client":"FEA-gruppen","work":"Samgående","disciplines":["M&A","Bolagsrätt"],"title":"Vinge har företrätt FEA-gruppen, med verksamheter som Freys Hyrverk och Stockholm Limousine Service, vid samgåendet med Inclusion Services International","caption":"Samgående · 21 maj 2025","preamble":"Genom samgåendet stärker den nya FEA-gruppen sin kapacitet och sitt tjänsteutbud, som erbjuder allt från övergripande reseplanering och hotellbokningar till säkerhetsklassade persontransporter och riskbedömningar. Den nybildade koncernen får, enligt ledningen, en unik position på den svenska marknaden med möjlighet att introducera nya transport- och säkerhetslösningar som hittills saknat motsvarighet i landet.","body":"Vinges team bestod huvudsakligen av Olof Jisland, Filip Öhrner, Philip Moré, Daniel Wendelsson och Fredrik Hellström.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-fea-gruppen-med-verksamheter-som-freys-hyrverk-och-stockholm-limousine-service-vid-samgaendet-med-inclusion-services-international/","date":"2025-05-21","month":5},{"year":2025,"client":"EHF Invest","work":"Övrigt","disciplines":["M&A","Kapitalmarknad och publik M&A"],"title":"Vinge biträder EHF Invest i budet på Real Fastigheter","caption":"Övrigt · 21 maj 2025","preamble":"EHF Invest AB har lämnat ett offentligt uppköpserbjudande till aktieägarna i Real Fastigheter AB (publ).","body":"Budet värderar samtliga aktier i Real Fastigheter till cirka 297 miljoner kronor.\n\nVinges team består av Erik Sjöman, Christian Lindhé och Agaton Lindgren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ehf-invest-i-budet-pa-real-fastigheter/","date":"2025-05-21","month":5},{"year":2025,"client":"Wais","work":"Avyttring","disciplines":["M&A"],"title":"Vinge har biträtt vid försäljning av Wais till Sertion","caption":"Avyttring · 19 maj 2025","preamble":"Vinge har biträtt säljarna i samband med försäljning av Wais AB till Sertion AB. Wais är verksamt inom pannservice och underhåll, rökgasrening, mekaniska arbeten samt fläktservice hos bl.a. kraftvärmeverken.","body":"Vinges team har huvudsakligen bestått av Anders Strid, Hanna Marberg och Amanda Stoltz. Censor M&A har agerat finansiell rådgivare åt säljarna.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-vid-forsaljning-av-wais-till-sertion/","date":"2025-05-19","month":5},{"year":2025,"client":"SBB","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder SBB i samband med dess förvärv av aktier i PPI mot betalning genom apportemission","caption":"Kapitalanskaffning · 16 maj 2025","preamble":"Vinge har biträtt SBB i samband med att avtal ingåtts med TRG, en norsk företagsgrupp som kontrolleras av Kjell Inge Røkke och som är huvudägare i Aker. SBB har enligt avtalet åtagit sig att genomföra en apportemission till TRG, eller såsom tillämpligt Aker Property Group.","body":"Vinges team består huvudsakligen av Jesper Schönbeck, Rikard Lindahl, Joel Magnusson och Benjamin Vafaeian.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sbb-i-samband-med-dess-forvarv-av-aktier-i-ppi-mot-betalning-genom-apportemission/","date":"2025-05-16","month":5},{"year":2025,"client":"Stendörren Fastigheter","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har biträtt Stendörren Fastigheter i samband med en riktad nyemission om cirka 300 miljoner kronor","caption":"Kapitalanskaffning · 14 maj 2025","preamble":"Vinge har biträtt fastighetsbolaget Stendörren Fastigheter AB (publ) i samband med en riktad nyemission varigenom bolaget tillförs cirka 300 miljoner kronor före transaktionskostnader.","body":"Bolaget avser att använda emissionslikviden för att finansiera tillväxt och för att kapitalisera på investeringsmöjligheter inom lager, logistik och lätt industri genom fastighetsförvärv och investeringar i projektutveckling. Stendörren Fastigheters aktie är noterad på Nasdaq Stockholm, Mid Cap.\n\nVinges team bestod av David Andersson och Maximilian Bengtsson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-stendorren-fastigheter-i-samband-med-en-riktad-nyemission-om-cirka-300-miljoner-kronor/","date":"2025-05-14","month":5},{"year":2025,"client":"EQT","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge har biträtt EQT AB i samband med dess obligationsemission till ett sammanlagt nominellt belopp om 500 000 000 USD","caption":"Obligationsemission · 13 maj 2025","preamble":"EQT AB (publ) har emitterat seniora obligationer till ett sammanlagt nominellt belopp om 500 000 000 USD med en ränta på 5,850%, som förfaller 2035, till ett pris motsvarande 99,783% av det sammanlagda nominella beloppet.","body":"Vinge företrädde tillsammans med Latham & Watkins EQT AB (publ).\n\nVinges team bestod främst av Helena Göransson, Lionardo Ojeda, Nour Makie, August Ahlin, Sofie Bjärtun, Joel Magnusson, Lorin Arabi, Victor Ericsson och Henrik Schön.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-eqt-ab-i-samband-med-dess-obligationsemission-till-ett-sammanlagt-nominellt-belopp-om-500-000-000-usd/","date":"2025-05-13","month":5},{"year":2025,"client":"Qlik","work":"Förvärv","disciplines":["IT, Telekom och Outsourcing","M&A","Immaterialrätt"],"title":"Vinge har rådgivit Qlik i samband med förvärv","caption":"Förvärv · 13 maj 2025","preamble":"Vinge har rådgivit Qlik Group i samband med dess förvärv av Qloud Cover Migration-teknologin från Stretch Qonnect. Denna automatiserade lösning, som kommer att marknadsföras som Qlik Analytics Migration Tool, eliminerar komplexiteten i att migrera från QlikView, Qlik Sense och NPrinting till Qlik Cloud – en ihållande barriär för molnadoption.","body":"Vinges team bestod av Henrik Borna (IT / M&A), Lisa Bourghardt (IP) och Niklas Törnell (M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-radgivit-qlik-i-samband-med-forvarv/","date":"2025-05-13","month":5},{"year":2025,"client":"West of England","work":"Förvärv","disciplines":[],"title":"Vinge företräder West of England vid förvärvet av Nordisk Marinförsäkring","caption":"Förvärv · 13 maj 2025","preamble":"Vinge har företrätt The West of England Ship Owners Mutual Insurance Association (Luxembourg), en ledande försäkringsleverantör till den globala sjöfartsindustrin, vid förvärvet av samtliga återstående aktier i Nordisk Marinförsäkring AB (”Nordisk Marinförsäkring”). West of England har sedan 2020 varit aktieägare i Nordisk Marinförsäkring. Det är ett strategiskt förvärv som möjliggör för West of England att diversifiera sin verksamhet och bredda de tjänster och produkter de tillhandahåller för sina medlemmar och för marinförsäkringsmarknaden som helhet.","body":"Nordisk Marinförsäkring är specialiserat på nischprodukter inom marinförsäkringsområdet och har ett gott rykte bland redare, speditörer och mäklare för sina innovativa och högkvalitativa produkter.\n\nVinges team bestod av Viveka Classon och Olivia Carlsten (Corporate Insurance), Filip Öhrner och Alex Forsberg (M&A) samt Daniel Wendelsson och Martin Hammarskiöld (FDI).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-west-of-england-vid-forvarvet-av-nordisk-marinforsakring/","date":"2025-05-13","month":5},{"year":2025,"client":"HAKI Safety","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder HAKI Safety i samband med avyttringen av Landqvist Mekaniska Verkstad till Opima","caption":"Avyttring · 7 maj 2025","preamble":"Landqvist Mekaniska Verkstad är fokuserat på skärande metallbearbetning och legotillverkning till främst svensk industri. Företaget hade en årlig försäljning om cirka 78 Mkr och ett rörelseresultat om 9 Mkr under 2024. Avyttringen är ett led i HAKI Safetys strategiomläggning, från ett konglomerat till dagens industrikoncern med fokus på säkerhetsprodukter och -lösningar för alla som arbetar i krävande miljöer. Med avyttringen består HAKI Safety nu uteslutande av verksamheter inom arbetsplatssäkerhet, systemställningar samt digitala och tekniska lösningar.","body":"Vinges team bestod av Anna Edström tillsammans med Johan Severinsson (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-haki-safety-i-samband-med-avyttringen-av-landqvist-mekaniska-verkstad-till-opima/","date":"2025-05-07","month":5},{"year":2025,"client":"Main Capital och Pointsharp","work":"Förvärv","disciplines":["M&A","Immaterialrätt","GDPR"],"title":"Vinge företräder Main Capital och Pointsharp vid förvärvet av Vemendo","caption":"Förvärv · 7 maj 2025","preamble":"Vinge har företrätt Pointsharp International AB, en mjukvaruleverantör inom identitets- och åtkomsthantering, vid förvärvet av Vemendo AB (”Vemendo”). Det strategiska förvärvet kompletterar Pointsharp väl och ligger i linje med företagets tillväxtstrategi på den europeiska marknaden för identitets- och åtkomsthantering.","body":"Vemendo tillhandahåller programvara för identitetshantering, användaradministrering och livscykelhantering vilket möjliggör att användarinformationen är uppdaterad, att användare säkert kan logga in på flera nätverk eller system samt att identitetsinformation enkelt kan spåras inom organisationen.\n\nVinges team bestod av Filip Öhrner och Alex Forsberg (M&A), Arvid Axelryd (IP) och Martin Boström (GDPR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-och-pointsharp-vid-forvarvet-av-vemendo/","date":"2025-05-07","month":5},{"year":2025,"client":"Karl Hedin och minoritetsägarna","work":"Avyttring","disciplines":["M&A","EU‑ och konkurrensrätt","Kommersiella avtal","Fastigheter och Entreprenad","Immaterialrätt","Carve-Outs"],"title":"Vinge företräder Karl Hedin och minoritetsägarna i samband med försäljningen av AB Karl Hedin Emballage till DTE","caption":"Avyttring · 7 maj 2025","preamble":"Vinge har företrätt Karl Hedin och minoritetsägarna i samband med försäljningen av AB Karl Hedin Emballage till Dansk Træemballage A/S (”DTE”).","body":"DTE är Nordens största tillverkare av träemballage och har cirka 625 anställda med en omsättning om 1,9 miljarder kronor. DTE har åtta produktionsanläggningar i Danmark, nio produktionsanläggningar i Norge, två produktionsanläggningar i Sverige och ett tradingbolag i Tyskland. AB Karl Hedin Emballage har tio produktionsanläggningar i Sverige och en i Estland och cirka 275 heltidsanställda. Tillsammans kommer de två bolagen ha en omsättning om cirka 2,5 miljarder kronor och cirka 900 anställda. AB Karl Hedin Emballage kommer fortsatt att verka under nuvarande namn och varumärke.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Johan Winnerblad, Egil Svensson och Olof Löfvenberg (M&A), David Olander och Dagne Sabockis (EU- och konkurrensrätt), Eva Fredrikson och Siri Blomberg (Kommersiella avtal), Niclas Winnberg och Simon Gille-Johnson (Fastighetsrätt), Alva Skott (Immaterialrätt) och Jessica Öijer (Projektassistent).\n\nLäs klientens pressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-karl-hedin-och-minoritetsagarna-i-samband-med-forsaljningen-av-ab-karl-hedin-emballage-till-dte/","date":"2025-05-07","month":5},{"year":2025,"client":"Schibsted Tillväxtmedier","work":"Avyttring","disciplines":["M&A","Arbetsrätt","GDPR","Immaterialrätt","Kommersiella avtal"],"title":"Vinge företräder Schibsted Tillväxtmedier i samband med deras försäljning av Prisjakt","caption":"Avyttring · 6 maj 2025","preamble":"Schibsted Tillväxtmedier har ingått avtal avseende försäljning av Prisjakt till eEquity. Köpeskillingen förväntas uppgå till omkring 500 miljoner kronor. Schibsted har ägt Prisjakt i ca 20 år och försäljning genomförs som en del av Schibsteds pågående streamlining av organisationen och portföljen.","body":"Transaktionen förväntas genomföras i juni 2025 och är villkorad av godkännande från Konkurrensverket.\n\nVinges team bestod huvudsakligen av Johan Larsson, Johan Winnerblad och Gustav Wahlberg (M&A), Nicklas Thorgerzon (GDPR), Eva Fredrikson, Christoffer Nordin, Siri Blomberg och Carl Lexenberg (Kommersiella avtal), Alice Göransson (Arbetsrätt) samt Johan Gavelin (IP).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-schibsted-tillvaxtmedier-i-samband-med-deras-forsaljning-av-prisjakt/","date":"2025-05-06","month":5},{"year":2025,"client":"Studentbostäder","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Studentbostäder i Norden AB i samband med dess företrädesemission","caption":"Kapitalanskaffning · 25 april 2025","preamble":"Vinge har företrätt Studentbostäder i Norden AB (publ), ett fastighetsbolag vars aktier är noterade på Nasdaq First North Premier Growth Market, i samband med en övertecknad företrädesemission varigenom Studentbostäder i Norden AB (publ) tillförs cirka 145 miljoner kronor före avdrag för emissionskostnader.","body":"De nya aktierna som emitteras inom ramen för företrädesemissionen beräknas bli föremål för handel på Nasdaq First North Premier Growth Market omkring den 7 maj 2025.\n\nStudentbostäder i Norden AB (publ) äger, förvaltar och utvecklar studentbostäder i långsiktiga partnerskap med kommuner, regioner och högskolor. Bolagets aktier är noterade i Sverige på Nasdaq First North Premier Growth Market med kortnamnet STUDBO.\n\nVinges team har bestått av Jesper Schönbeck, Joel Wahlberg, Benjamin Vafaeian, Johannes Akyol och Elias Kröger.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-studentbostader-i-norden-ab-i-samband-med-dess-foretradesemission/","date":"2025-04-25","month":4},{"year":2025,"client":"Axcel och Accru Partners","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Bank och finans","Kommersiella avtal","IT, Telekom och Outsourcing","GDPR","Fastigheter och Entreprenad","Regulatoriska tvister"],"title":"Vinge företräder Axcel och Accru Partners vid förvärven av Carlstedt & Lindh AB och Brahe Revisionsbyrå AB","caption":"Förvärv · 24 april 2025","preamble":"Vinge har företrätt Axcel VII och Accru Partners i samband med förvärven av Carlstedt & Lindh AB och Brahe Revisionsbyrå AB","body":"Carlstedt & Lindh AB och Brahe Revisionsbyrå AB är entreprenörsledda, lokala företag med expertis inom redovisning, revision, skatt, och rådgivningstjänster. Efter förvärven består Accru Partners av totalt 32 självständiga byråer inom nämnda verksamhetsområden.\n\nVinges team bestod av Christina Kokko, Egil Svensson, Michella Lina Said och Chris Bastholm (M&A), Linn Aho och Simon Söderholm (Arbetsrätt), Sofia Haggren (Bank och finans), Mario Saad (Kommersiella avtal), Elis Allmark (IT), Nicklas Thorgerzon (GDPR), Madelene Andersson (Fastighet), Jonna Bondemark (Regulatoriska frågor), Gulestan Ali och Hayaat Ibrahim (Regelefterlevnad) samt Jessica Öijer (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-accru-partners-vid-forvarven-av-carlstedt-lindh-ab-och-brahe-revisionsbyra-ab/","date":"2025-04-24","month":4},{"year":2025,"client":"Platzer Fastigheter","work":"Övrigt","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge har företrätt Platzer Fastigheter","caption":"Övrigt · 22 april 2025","preamble":"Platzer Fastigheter har sålt bostadsbyggrätter i området Södra Änggården i Göteborg till PEAB Bostad. Södra Änggården skall utvecklas av Platzer Fastigheter i samverkan med ett antal aktörer.","body":"Från Vinges sida medverkade Olof Jisland och Kristoffer Larson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-platzer-fastigheter/","date":"2025-04-22","month":4},{"year":2025,"client":"Biotage","work":"Offentligt uppköpserbjudande","disciplines":["M&A"],"title":"Vinge biträder Biotage i samband med RWK Bidcos offentliga uppköpserbjudande","caption":"Offentligt uppköpserbjudande · 22 april 2025","preamble":"Den 22 april 2025 offentliggjorde RWK Bidco AB, ett nybildat bolag som indirekt är helägt av KKR-Fonder, ett offentligt uppköpserbjudande till aktieägarna i Biotage AB att överlåta samtliga stamaktier i Biotage till RWK Bidco för 145 kronor kontant per stamaktie.","body":"Biotage är en global leverantör och partner till ett brett spektrum av kunder inom läkemedelsindustrin och analytisk testning. Biotage har sitt huvudkontor i Sverige och är verksamt globalt i över 80 länder. Bolaget är noterat på Nasdaq Stockholm. Erbjudandet värderar Biotage till cirka 11 607 miljoner kronor baserat på det totala antalet stamaktier i Biotage.\n\nVinges team består huvudsakligen av Dain Hård Nevonen, Joel Magnusson, Benjamin Vafaeian, Lovisa Jonassen, Vilma Henricsson, David Olander och Emelie Schoning.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-biotage-i-samband-med-rwk-bidcos-offentliga-uppkopserbjudande/","date":"2025-04-22","month":4},{"year":2025,"client":"Baseload Capital","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Baseload Capital i samband med investering från Google","caption":"Kapitalanskaffning · 16 april 2025","preamble":"Vinge har biträtt Baseload Capital Holding AB i samband med att Google genomför en investering i bolaget.","body":"Baseload Capital är en ledande investeringsenhet som arbetar för att främja utbyggnaden av geotermisk energi globalt. Genom att etablera operativa bolag på olika platser i världen samarbetar Baseload Capital med lokala samhällen och energileverantörer för att ta i drift, upphandla tillstånd och bygga geotermiska kraftverk som finansieras av Baseload Capital. Baseload Capital och dess dotterbolag Baseload Power är verksamma på mogna geotermiska marknader som Island, USA och Japan, samt på tillväxtmarknader som Taiwan.\n\nI samband med Googles investering i Baseload har Google och Baseload ingått ett CPPA-avtal (Corporate Power Purchase Agreement) för koldioxidfri geotermisk energi i Taiwan. Samarbetets inledande projekt kommer att tillföra 10MW ren energi till elnätet, vilket innebär en fördubbling av den nuvarande geotermiska kapaciteten i kommersiell drift i Taiwan. När projekten har driftsatts under 2029 kommer de att leverera kapacitet till lokala datacenter och kontor.\n\nVinges team bestod av Maria Dahlin Kolvik och Gustav Wahlberg.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-baseload-capital-i-samband-med-investering-fran-google/","date":"2025-04-16","month":4},{"year":2025,"client":"Acrinova","work":"Avyttring","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Acrinova i samband med avyttring av fastigheter","caption":"Avyttring · 15 april 2025","preamble":"Vinge biträder Acrinova AB (publ) i samband med dess avyttring av fastigheter med ett underliggande fastighetsvärde om 1,4 miljarder kronor.","body":"Vinges team består av Christian Lindhé, Martin Madsen Svanberg, Johan Åhman och Nathalie Wikman.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-acrinova-i-samband-med-avyttring-av-fastigheter/","date":"2025-04-15","month":4},{"year":2025,"client":"Visa","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har biträtt Visa i samband med deras investering i Mynt AB","caption":"Kapitalanskaffning · 14 april 2025","preamble":"Vinge har biträtt Visa i samband med deras investering i det svenska fintechbolaget Mynt AB (\"Mynt\"). Investeringen, som är en del av Mynts meddelade serie B-finansieringsrunda, understryker Visas engagemang för att stödja innovativa fintech-lösningar och förbättra betalningsupplevelser för företag i hela Europa.","body":"Mynt är ett svenskt SaaS-fintechbolag specialiserat på lösningar inom utgiftshantering och levererar tjänster som hjälper företagare att förenkla sin administration och bokföring genom att erbjuda ett företagskort som via Mynts plattform integreras med kundernas bokföringssystem. Partnerskapet kommer att göra det möjligt för Visa att bättre tillgodose sina kunders behov och den underförsörjda marknaden för små och medelstora företag (SMB) samtidigt som det möjliggör för Mynt att möta den växande efterfrågan på effektiv utgiftshantering bland små och medelstora företag.\n\nVinges team bestod av Johan Larsson och Helena Liljenberg.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-visa-i-samband-med-deras-investering-i-mynt-ab/","date":"2025-04-14","month":4},{"year":2025,"client":"Scania","work":"Förvärv","disciplines":["M&A","Rekonstruktioner och obestånd","EU‑ och konkurrensrätt","Immaterialrätt","Corporate Commercial","Fastigheter och Entreprenad","Arbetsrätt","Carve-Outs"],"title":"Vinge företräder Scania vid förvärvet av Northvolts Systems Industrial-verksamhet","caption":"Förvärv · 11 april 2025","preamble":"Vinge företräder Scania vid förvärvet av Northvolts Systems Industrial-verksamhet. Verksamheten inkluderar produktion- och utvecklingsverksamhet samt ett team om cirka 260 anställda. Verksamheten är baserad på två platser: en produktionsanläggning i Gdańsk, Polen, och en R&D-anläggning i Tomteboda, Stockholm.","body":"Northvolts Systems Industrial-verksamhet utvecklar och tillverkar batterisystem för tung industri och off-highway marknadssegment, och erbjuder en portfölj av batterimoduler och batterisystem som används inom bland annat materialhantering, anläggningsmaskiner och gruvdrift. Den förvärvade verksamheten kommer att vara ett komplement till Scania Power Solutions och verka som ett fristående företag inom Scania Ventures and New Business, i linje med Scanias strategi att utveckla kompletterande och transformerande verksamheter som stärker Scanias långsiktiga konkurrenskraft.\n\nMed över ett sekel av innovation inom drivlinor har Scania Power Solutions byggt upp ett starkt rykte för att leverera tillförlitliga och effektiva motorer som uppfyller de tuffaste kraven inom industri-, marin- och kraftgenereringssegmenten. Med detta förvärv kommer Scania att stärka sitt erbjudande inom elektrifiering för off-road applikationer.\n\nVinges team bestod av jurister från Vinges samtliga kontor i Stockholm, Göteborg, Malmö och Bryssel. Teamet leddes av Jonas Johansson och Linus Adolfsson (M&A) och bestod därutöver huvudsakligen av Henrik Borna, Desirée Hagenfeldt, Jonatan Karlsson, Sara Hammond (Corporate och M&A), Morgan Hallén, Petronella Hallberg, Malin Olsson (Restructuring and Insolvency), Sebastian Örndahl, Martin Johansson, Dagne Sabockis, Hilda Ivarsson (EU, Competition and Regulatory), Malin Malm Waerme, Arvid Axelryd, (Intellectual Property), Eva Fredrikson, Anna Jonsson, Nicklas Thorgezon (Corporate Commercial), Simon Söderholm (Employment), Niclas Winnberg, Anna Edström och Simon Gille-Johnson (Real Estate).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-scania-vid-forvarvet-av-northvolts-systems-industrial-verksamhet/","date":"2025-04-11","month":4},{"year":2025,"client":"Trianon","work":"Avyttring","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Trianon i samband med avyttring av fastigheter","caption":"Avyttring · 10 april 2025","preamble":"Vinge biträder Fastighets Aktiebolaget Trianon (publ) i samband med dess avyttring av fastigheter med ett sammanlagt överenskommet fastighetsvärde om 1 062 miljoner kronor.","body":"Vinges team består av Christian Lindhé, Martin Madsen Svanberg, Agaton Lindgren och Johan Severinsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-trianon-i-samband-med-avyttring-av-fastigheter/","date":"2025-04-10","month":4},{"year":2025,"client":"Sacpro","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Sacpro vid förvärv av UVRelining","caption":"Förvärv · 9 april 2025","preamble":"Sacpro, ett portföljbolag till Helix Kapital och ledande producent och leverantör av material samt utrustning för relining i fastigheter, har förvärvar UVRelining, en framträdande aktör inom UV-härdningsteknik. UVRelinings ledning kommer fortsätta att driva verksamheten och ansluter som delägare i Sacpro-koncernen.","body":"Vinge, genom framförallt Johan Winnerblad och Alex Forsberg, har biträtt Sacpro.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-sacpro-vid-forvarv-av-uvrelining/","date":"2025-04-09","month":4},{"year":2025,"client":"Eleda","work":"Förvärv","disciplines":["Arbetsrätt","M&A","Fastigheter och Entreprenad","Bank och finans","FDI","GDPR"],"title":"Vinge har företrätt Eleda i samband med förvärv av Signalbolaget i Sverige AB","caption":"Förvärv · 7 april 2025","preamble":"Signalbolaget är med och utvecklar samt underhåller det svenska järnvägsnätet, med fokus på tjänster inom signalteknik. Signalbolaget är baserat i Borlänge, omsätter cirka 80 miljoner kronor och har 50 anställda.","body":"Transaktionen är föremål för sedvanligt myndighetsgodkännande.\n\nVinges team bestod huvudsakligen av Christina Kokko, Ellen Flygt och Philip Moré (M&A), Daniel Wendelsson och David Olander (FDI), Emil Lindwall och Louisa Fagarasan (Arbetsrätt), Calle Tengwall Pagels och Ida Appelgren (Bank och finans), Hanna Kövamees och Wilma Hellman (Fastigheter), Nicklas Thorgerzon (GDPR) samt Johanna Engström (Transaction Support Senior Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-i-samband-med-forvarv-av-signalbolaget-i-sverige-ab/","date":"2025-04-07","month":4},{"year":2025,"client":"Morrow Banks","work":"Tillstånd","disciplines":["Bank och finans","Finansiella tillståndsfrågor","Kapitalmarknad och publik M&A"],"title":"Morrow Banks svenska dotterbolag har fått banktillstånd","caption":"Tillstånd · 2 april 2025","preamble":"Vinge har biträtt Morrow Bank ASA i samband med att dess dotterbolag Morgon Finans AB (under namnändring till Morrow Bank AB) beviljats svenskt tillstånd att bedriva bankrörelse av Finansinspektionen.","body":"Morrow Bank är en nischbank med ambitionen att skapa långsiktigt värde genom att erbjuda olika finansieringslösningar främst till konsumenter på den nordiska marknaden. Morrow Banks strategi bygger på en digital, skalbar, och effektiv verksamhetsmodell i kombination med ett stort fokus på riskkontroll. På en alltmer digital marknad fokuserar Morrow Bank på att skapa kundvärde genom flexibla lösningar och effektiva och användarvänliga processer. Produktportföljen omfattar konsumentlån, kreditkort, sparkonto samt olika försäkringsprodukter.\n\nMorrow Bank avser att genomföra en redomilicering till Sverige genom en gränsöverskridande fusion mellan Morrow Bank ASA och Morrow Bank AB, med Morrow Bank AB som det övertagande bolaget. Morrow Bank ASA är noterat på Oslo Børs och efter fusionen är avsikten att det övertagande bolaget ska noteras på Nasdaq Stockholm.\n\nAtt kunna hjälpa Morrow Bank att erhålla svenskt banktillstånd är en betydande prestation som understryker vår strävan och förmåga att kunna leverera exceptionella juridiska tjänster som är skräddarsydda för våra klienters unika behov. Ansökan godkändes på mindre än fem månader, vilket är ett bevis på det mycket goda samarbetet med Morrow Bank och kvaliteten på den ansökan som lämnades in. Denna milstolpe är ett resultat av vårt teams hårda arbete och engagemang. Vi är glada över att ha bidragit till Morrow Banks strategiska expansion på den nordiska marknaden och ser fram emot att se den positiva påverkan detta kommer att ha på deras verksamhet och kunderbjudande”, säger Emma Stuart-Beck, ansvarig delägare.\n\nVinges team bestod huvudsakligen av Emma Stuart-Beck, Henrik Schön, Caroline Krassén, Elias Bohlin (projektledare), David Flodin, Sara Hedgren och Ebba Gäbel (Financial Services) samt Joel Wahlberg och Oskar Nilsson (Capital Markets).\n\nMorrow Banks pressmeddelande finns här.","href":"https://www.vinge.se/uppdrag/morrow-banks-svenska-dotterbolag-har-fatt-banktillstand/","date":"2025-04-02","month":4},{"year":2025,"client":"VARO Energy Marketing AG","work":"Förvärv","disciplines":["M&A","Miljörätt","Corporate Commercial","Fastigheter och Entreprenad","IT, Telekom och Outsourcing","EU‑ och konkurrensrätt","Immaterialrätt","Corporate Crime & Compliance"],"title":"Vinge har företrätt VARO Energy Marketing AG i samband med dess förvärv av Corral Petroleum Holdings AB, moderbolaget i Preemkoncernen","caption":"Förvärv · 31 mars 2025","preamble":"Preem driver omkring 500 tankställen i Sverige, samt raffinaderier i Lysekil och Göteborg som sammanlagt står för över 40 % av Sveriges transportenergiförsörjning samt 80 % av dess raffineringskapacitet. Preem och Varo kommer tillsammans att bli Europas näst största producent av förnybara bränslen och stå för nästan 10 % av bränsleförsörjningen till Europas väg- och vattentransporter.","body":"Transaktionen är föremål för sedvanliga myndighetsgodkännanden.\n\nVinges team bestod huvudsakligen av Samra Tesser, Peter Sundgren, Vilhelm Rondahl, Gustav Persson, Alexander Rüdén, Ian Linde och Matilda Hamner (M&A), Albert Wållgren, Linn Adelwald, Calle Tengwall Pagels och Karl-Gustaw Tobola (Bank & Finans), Johan Cederblad (Miljö), Martin Boström och Mario Saad (Corporate Commercial), Hanna Kövamees (Fastighet), Emil Lindwall och Agnes Pigg (Arbetsrätt), Daniel Wendelsson, Lovisa Lewin, Dagne Sabockis och Sara Hammond (Competition & Regulatory), Rebecka Målquist (IP), Carla Håkansson (IT), Gulestan Ali (Compliance) samt Caroline Löv och Ellinore Boström Andersson (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-varo-energy-marketing-ag-i-samband-med-dess-forvarv-av-corral-petroleum-holdings-ab-moderbolaget-i-preemkoncernen/","date":"2025-03-31","month":3},{"year":2025,"client":"Geveko","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Geveko vid dess första emission av seniora säkerställda obligationer om EUR 170 miljoner och ingående av super senior RCF","caption":"Obligationsemission · 31 mars 2025","preamble":"Vinge har biträtt Geveko Holding AB (publ) i samband med dess första emission av seniora säkerställda obligationer med rörlig ränta om EUR 170 miljoner (inom ett rambelopp om EUR 325 miljoner) samt vid ingåendet av en super senior revolverande kreditfacilitet med en nordisk bank.","body":"Obligationerna och kreditfaciliteten omfattas av ett gemensamt säkerhetspaket enligt ett borgenärsavtal (intercreditor agreement) och ett vattenfallsarrangemang.\n\nPareto Securities AB agerade sole bookrunner i transaktionen.\n\nVinges team bestod av Henrik Ossborn, Arvid Weimers och Agaton Lindgren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-geveko-vid-dess-forsta-emission-av-seniora-sakerstallda-obligationer-om-eur-170-miljoner-och-ingaende-av-super-senior-rcf/","date":"2025-03-31","month":3},{"year":2025,"client":"Vimian Group","work":"Övrigt","disciplines":["Företagsbeskattning","Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Vimian Group AB i samband med dess listbyte till Nasdaq Stockholm","caption":"Övrigt · 28 mars 2025","preamble":"Vinge har företrätt Vimian Group AB (publ) i samband med dess listbyte från Nasdaq First North Growth Market till Nasdaq Stockholm, Large cap. Prospektet offentliggjordes den 21 mars 2025 och handeln på Nasdaq Stockholm inleddes den 28 mars 2025.","body":"Vimian är ett globalt djurhälsobolag med verksamhet inom fyra områden i snabb utveckling: Specialty Pharma, MedTech, Veterinary Services och Diagnostics. Vimian har huvudkontor i Stockholm och når fler än 17 000 veterinärkliniker och laboratorier. Vimian säljer till över 80 marknader, har 1200 medarbetare och en årlig omsättning om cirka 375 miljoner euro.\n\nVinges team har huvudsakligen bestått av Dain Hård Nevonen, Linnéa Sellström, Anna Svensson och Michaela Ådén (Kapitalmarknad och Publik M&A) samt Victor Ericsson, Emelie Svanberg och Erik Kochbati (Företagsbeskattning).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-vimian-group-ab-i-samband-med-dess-listbyte-till-nasdaq-stockholm/","date":"2025-03-28","month":3},{"year":2025,"client":"Bergman & Beving","work":"Avyttring","disciplines":["M&A","EU‑ och konkurrensrätt"],"title":"Vinge biträder Bergman & Beving vid försäljning av Skyddas nordiska verksamheter","caption":"Avyttring · 27 mars 2025","preamble":"Bergman & Beving har ingått avtal om att avyttra dotterbolagen Skydda Sverige, Skydda Finland och Skydda Norge, vilket utgör huvuddelen av Skydda Group, till Ahlsell. Skydda har en sammanlagd nettoomsättning på cirka 550 MSEK och ett underliggande EBITA-resultat på cirka 45 MSEK för de senaste tolv månaderna. De avyttrade verksamheterna värderas till 300 MSEK, exklusive en eventuell tilläggsköpeskilling uppgående till maximalt 80 MSEK.","body":"Transaktionen är föremål för konkurrensgodkännanden.\n\nVinge, genom Johan Winnerblad, Alex Forsberg, Marcus Glader, Fredrik Hellström, Eva Fredrikson, Elis Allmark och Siri Blomberg, har företrätt Bergman & Beving.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-bergman-beving-vid-forsaljning-av-skyddas-nordiska-verksamheter/","date":"2025-03-27","month":3},{"year":2025,"client":"Tribune Therapeutics","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Tribune Therapeutics vid finansieringsrunda","caption":"Kapitalanskaffning · 26 mars 2025","preamble":"Vinge biträder Tribune Therapeutics, ett svenskt bioteknikföretag med fokus på att ta fram terapier för fibrotiska sjukdomar, att ta in 23 MEUR. I finansieringsrundan deltar de tidigare investerarna HealthCap, Novo Holding och Innovestor samt de nya investerarna LifeArc Ventures, Industrifonden och Investinor.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Gustav Wahlberg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-tribune-therapeutics-vid-finansieringsrunda/","date":"2025-03-26","month":3},{"year":2025,"client":"Dignitana","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Dignitana i budet från Paxman","caption":"Övrigt · 24 mars 2025","preamble":"Paxman AB (publ) har lämnat ett uppköpserbjudande till aktieägarna i Dignitana AB. Erbjudandet värderar samtliga aktier i Dignitana till cirka 153 miljoner kronor.","body":"Vinges team består av Christian Lindhé, Martin Madsen Svanberg och Nathalie Wikman.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-dignitana-i-budet-fran-paxman/","date":"2025-03-24","month":3},{"year":2025,"client":"Boliden","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Boliden i samband med en riktad nyemission om cirka 3,75 miljarder kronor","caption":"Kapitalanskaffning · 21 mars 2025","preamble":"Vinge har biträtt Boliden AB i samband med en riktad nyemission varigenom bolaget tillförs cirka 3,75 miljarder kronor före transaktionskostnader.","body":"Bolaget avser använda emissionslikviden för att finansiera förvärvet av Neves-Corvo-gruvan i Portugal och Zinkgruvan i Sverige. Bolidens aktie är noterad på Nasdaq Stockholm.\n\nVinges team bestod av Jesper Schönbeck, Amanda Knutsson, Joel Magnusson, Adrian Filipovic, Filip Magnusson och Sara Franson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-boliden-i-samband-med-en-riktad-nyemission-om-cirka-3-75-miljarder-kronor/","date":"2025-03-21","month":3},{"year":2025,"client":"EQT","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder EQT i samband med dess EUR 890 miljoner försäljning av Dellner Couplers till Wabtec","caption":"Avyttring · 19 mars 2025","preamble":"Vinge företräder tillsammans med Milbank EQT VIII-fonden (”EQT”) vid dess försäljning av Dellner Couplers (”Dellner”), en ledande leverantör av tåganslutningssystem för passagerartåg, till Wabtec Corporation (ett Fortune 500-bolag noterat på New York Stock Exchange, NYSE: WAB). Transaktionen värderar Dellner till cirka 890 miljoner euro. Transaktionen är föremål för sedvanliga villkor och myndighetsgodkännanden.","body":"Dellner Couplers är en global ledare inom tåganslutningssystem och tillhandahåller säkerhetskritiska komponenter och tjänster till järnvägstillverkare och operatörer över hela världen. Bolaget grundades 1941 i Vika, Sverige, och har vuxit från ett familjeägt företag till en av de mest betrodda partnerna inom den globala järnvägsindustrin med en stark närvaro i Europa, Nordamerika och Asien. Den avancerade produktportföljen omfattar kopplingar, tåggångar, dämpare och eftermarknadstjänster som bidrar till tillförlitliga och effektiva järnvägstransporter. Dellner har 17 dotterbolag runt om i världen och mer än 1 200 anställda globalt.\n\nEQT rådgavs av J.P. Morgan Securities Plc, Milbank, Vinge och EY.\n\nVinges team bestod huvudsakligen av Christina Kokko, Samra Tesser, Linus Adolfsson och Ian Linde.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-eqt-i-samband-med-dess-eur-890-miljoner-forsaljning-av-dellner-couplers-till-wabtec/","date":"2025-03-19","month":3},{"year":2025,"client":"Ambea","work":"Förvärv","disciplines":["M&A","Kapitalmarknad och publik M&A","Kommersiella avtal","Bank och finans","EU‑ och konkurrensrätt"],"title":"Vinge företräder Ambea vid förvärvet av Validia","caption":"Förvärv · 12 mars 2025","preamble":"Vinge har varit rådgivare åt Ambea AB (publ) tillsammans med finska advokatbyrån Krogerus i samband med förvärvet av Validia Oy från Invalidiliitto, det finska invalidförbundet, en ledande omsorgsaktör i Finland. Genom förvärvet etablerar sig Ambea på den finska marknaden och stärker sin position som den enda omsorgsaktören med närvaro i de fyra största nordiska länderna. Köpeskillingen uppgår till totalt 1 382 miljoner kronor.","body":"Vinges team bestod av Christina Kokko, Gustav Persson (M&A), Eva Fredrikson, Siri Blomberg (Commercial agreements), Sofie Bjärtun, Joel Magnusson (Kapitalmarknad och publik M&A), Albert Wållgren, Josefine Lanker (Bank och finans), Marcus Glader och Sebastian Örndahl (EU‑ och konkurrensrätt)","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ambea-vid-forvarvet-av-validia/","date":"2025-03-12","month":3},{"year":2025,"client":"Road Rental","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträdde vid försäljning av Road Rental","caption":"Avyttring · 12 mars 2025","preamble":"Vinge har biträtt Sobro och övriga aktieägare vid försäljning av Road Rental till BUKO Group, en ledande europeisk aktör inom tillfälliga trafikanordningar. Med denna strategiska partner får Road Rental tillgång till ett brett internationellt nätverk, starka resurser och expertis som möjliggör en fortsatt expansion i såväl Sverige som övriga Skandinavien","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Per Kling och Jonatan Stentorp.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-vid-forsaljning-av-road-rental/","date":"2025-03-12","month":3},{"year":2025,"client":"Röko","work":"Börsnotering","disciplines":["Kapitalmarknad och publik M&A","Företagsbeskattning","Bank och finans","IT, Telekom och Outsourcing","GDPR","Immaterialrätt","Arbetsrätt"],"title":"Vinge har företrätt Röko i samband med dess notering på Nasdaq Stockholm","caption":"Börsnotering · 11 mars 2025","preamble":"Vinge har företrätt Röko AB (publ) (”Röko”) i samband med dess notering på Nasdaq Stockholm. Prospektet offentliggjordes den 4 mars 2025 och första handelsdag är den 11 mars 2025.","body":"Priset i erbjudandet var 2 048 kronor per B-aktie, motsvarande ett totalt marknadsvärde för samtliga aktier i Röko om cirka 29,95 miljarder kronor. Det totala värdet av erbjudandet uppgår till cirka 5 284 miljoner kronor.\n\nRöko är en Sverigebaserad serieförvärvare som genomfört 28 plattformsförvärv i en mängd olika branscher över hela Europa. Bolagets ambition är att vara den eviga ägaren av små och medelstora bolag. Historiskt har Röko framförallt förvärvat små och medelstora bolag med huvudkontor i Norden och norra Europa. Rökos organisation har mer än 100 års kombinerad erfarenhet från att arbeta med grundar- och entreprenörsledda bolag inom ett brett spektrum av branscher och personerna i ledande befattning har arbetat på bolaget sedan dess första verksamhetsår.\n\nVinges team bestod huvudsakligen av Linnéa Sellström, Jesper Schönbeck, Erik Sjöman, Lorin Arabi, Annie Fällström, Michaela Ådén, Karin Karsten, Louise Nässén och Lovisa Jonassen (Kapitalmarknad och publik M&A), Victor Ericsson, Emelie Svanberg, Erik Kochbati, Marcus Svärd och Ellenor Eckerborn (Företagsbeskattning), Helena Göransson, Nour Makie och William Carlberg Johansson (Finansiering), Nicklas Thorgerzon, Martin Boström och Elis Allmark (Kommersiella avtal, IT och GDPR) Johan Gavelin (Immaterialrätt), Gulestan Ali (Regelefterlevnad) samt Louisa Fagarasan (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-roko-i-samband-med-dess-notering-pa-nasdaq-stockholm/","date":"2025-03-11","month":3},{"year":2025,"client":"Ingrid Capacity","work":"Partnerskap","disciplines":["M&A"],"title":"Vinge har företrätt Ingrid Capacity i nytt samarbete med Locus Energy, ett av SEB Nordic Energys portföljbolag","caption":"Partnerskap · 7 mars 2025","preamble":"Vinge har företrätt Ingrid Capacity i samband med ett nytt projekt tillsammans med Locus Energy, ett ledande nordiskt energiinfrastrukturbolag som ägs av SEB Asset Managements fond SEB Nordic Energy, för att skapa Finlands största och ett av Nordens största batterilagringssystem.","body":"Parterna ingick under fjolåret ett strategiskt partnerskap för att öka kapaciteten av det nationella elnätet och har nu gjort en ny gemensam investering i Finlands största batterilagringssystem, belägen i Nivala, Finland. Anläggningen, som planeras tas i drift 2026, har en kapacitet på 70MW/140MWh och kommer att hanteras av Ingrid Capacitys egenutvecklade och helautomatiska handels- och optimeringsplattform, en avancerad AI-driven programvara som är utformad för att fatta beslut i realtid. Nivalaprojektet är partnerskapets andra i ordningen, och en del i Ingrid Capacitys långsiktiga vision om att möjliggöra ett motståndskraftigt, kostnadseffektivt och hållbart elnät.\n\nVinge's team bestod huvudsakligen av Carl Sander, Vilhelm Rondahl, och Ellenor Eckerborn (M&A).\n\nFör mer information vänligen läs här.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-ingrid-capacity-i-nytt-samarbete-med-locus-energy-ett-av-seb-nordic-energys-portfoljbolag/","date":"2025-03-07","month":3},{"year":2025,"client":"Great Security och Garda Group","work":"Förvärv","disciplines":["M&A","Arbetsrätt","IT, Telekom och Outsourcing","Kommersiella avtal","Immaterialrätt","Offentlig upphandling","FDI"],"title":"Vinge har företrätt Great Security och Garda Group i samband med förvärvet av Comdate Norrlarm","caption":"Förvärv · 6 mars 2025","preamble":"Vinge har företrätt Great Security, ett av Sveriges största säkerhetsföretag, i samband med förvärvet av Comdate Norrlarm, norra Sveriges största oberoende larm- och säkerhetsföretag. Genom förvärvet får Great Security en starkare närvaro i regionen samt direkt tillgång till denna geografiska marknad.","body":"Comdate Norrlarm är en ledande aktör inom larm- och säkerhetsbranschen och erbjuder avancerade säkerhetslösningar inom områdena inbrottslarm, brandlarm, kameraövervakning och passagesystem.\n\nGreat Security ingår sedan tidigare i Garda Group-koncernen som är en av norra Europas största leverantör av fysisk säkerhet. Garda Group består av säkerhetsbolag i Sverige, Danmark, Norge, Finland och Tyskland. Tillsammans har bolagen ca 2 100 anställda och med en årlig omsättning på över 5 miljarder SEK.\n\nVinges team bestod främst av Carl Sander, Linus Adolfsson och Sara Hammond (M&A), Simon Söderholm och Gulestan Ali (Arbetsrätt), Carla Håkansson, Elis Allmark och Nicklas Thorgerzon (Kommersiella avtal, IT och GDPR), Johan Gavelin och Siri Blomberg (IP), Kristoffer Sällfors (Offentlig upphandling), Dagne Sabockis och Martin Hammarskiöld (FDI) samt Cecilia Loctander (Transaktionssupport).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-great-security-och-garda-group-i-samband-med-forvarvet-av-comdate-norrlarm/","date":"2025-03-06","month":3},{"year":2025,"client":"SpareBank 1 Markets","work":"Partnerskap","disciplines":["M&A","Finansiella tillståndsfrågor"],"title":"Vinge företräder SpareBank 1 Markets i samband med dess partnerskap med Swedbank","caption":"Partnerskap · 4 mars 2025","preamble":"Partnerskapet mellan SpareBank 1 Markets och Swedbank syftar till att skapa en ledande nordisk investmentbank. Som en del av affären tar SpareBank 1 Markets emot Swedbanks Corporate Finance- och High-Yield Debt Capital Markets (DCM) i Sverige och etablerar en filial i Stockholm varigenom de kommer att bedriva verksamheten.","body":"Genom partnerskapet blir Swedbank delägare i SpareBank 1 Markets med en ägarandel på 20 %, vilket stärker båda bankernas position på den nordiska marknaden och skapar nya möjligheter för expansion inom investment banking.\n\nTransaktionen är föremål för regulatoriska godkännanden och sedvanliga tillträdesvillkor.\n\nVinges team består huvudsakligen av Samra Tesser, Nils Unckel, Anton Sjökvist och Gustav Wahlberg.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-sparebank-1-markets-i-samband-med-dess-partnerskap-med-swedbank/","date":"2025-03-04","month":3},{"year":2025,"client":"Adelis Equity Partners","work":"Övrigt","disciplines":["Private Funds"],"title":"Vinge biträder Adelis Equity Partners vid etableringen av Adelis Equity Partners Fund IV","caption":"Övrigt · 3 mars 2025","preamble":"Vinge har biträtt Adelis Equity Partners vid etableringen av Adelis fjärde flagship fund: Adelis Equity Partners Fund IV.","body":"Fonden, som var kraftigt övertecknad, höll sin final closing den 28 februari 2025 efter att ha rest 1,6 miljarder euro i kapital från en investerarbas bestående av bl.a. ledande pensionsfonder, fond-i-fonder och stiftelser från Europa och Nordamerika, samt från Adelis-teamet själva. Fondens storlek ökar därmed med över 50 % jämfört med föregångsfonden Adelis Equity Partners Fund III. Adelis investerar sedan starten 2013 i välpositionerade bolag i Norden och DACH-regionen, och har fram till idag genomfört 45 plattformsinvesteringar och över 260 tilläggsförvärv.\n\nVinges team har huvudsakligen bestått av Mattias Schömer, Nils Unckel, Martin Cronsioe, Ulf Nilsson, Mikaela Reinhammar, Anton Sjökvist, Emelie Svanberg, Tobias Onegård Karlsson, Viktoria Wnuk, Rebecka Margolin, Saga Meyer Viklund och Emelie Zingmark.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-adelis-equity-partners-vid-etableringen-av-adelis-equity-partners-fund-iv/","date":"2025-03-03","month":3},{"year":2025,"client":"Sveriges Olympiska Kommitté (SOK)","work":"Tvist","disciplines":["Tvistlösning"],"title":"Vinge har biträtt Sveriges Olympiska Kommitté (SOK) vid uppmärksammat principavgörande i idrottens skiljedomstol, CAS","caption":"Tvist · 28 februari 2025","preamble":"Vinge företrädde SOK i medialt uppmärksammat och principiellt mycket viktigt skiljeförfarande gällande uttagningarna till OS i Paris. I målet fastslog CAS att SOK:s uttagningsregler för de olympiska spelen är fullt tillåtna.","body":"Dagarna före invigningen av de olympiska spelen i Paris avgjordes ett brådskande skiljeförfarande i idrottens skiljedomstol, CAS, där ett antal idrottare överklagade Sveriges Olympiska Kommittés (SOK) beslut att inte ta ut dem till OS i Paris.\n\nEfter ett mycket snabbt skiljeförfarande dömde CAS till SOK:s fördel den 26 juli 2024, samma dag som OS-invigningen, men utan att redovisa några skäl för sitt beslut.\n\nNu har CAS meddelat sina domskäl. I ett vägledande principavgörande för den internationella idrottsrörelsen slår CAS nu fast att nationella olympiska kommittéer får tillämpa egna, striktare uttagningskriterier än de internationella kvalgränser och kvalificeringsregler som internationella idrottsförbund (t.ex. World Aquatics, World Athletics, osv.) satt upp, vilket var målets huvudfråga.\n\nCAS bekräftar därmed att de uttagningsregler som SOK tillämpade inför spelen i Paris är förenliga med The Olympic Charter, det högst stående regelverket för den olympiska rörelsen. SOK har publicerat följande pressmeddelande.\n\nCAS är ett internationellt organ med säte i Schweiz som hanterar tvister inom idrotten, däribland frågor om spelarövergångar, sponsorkontrakt, doping och andra disciplinfrågor.\n\nVinge har samarbetat med SOK sedan 2016 och inledde 2020 ett långsiktigt partnerskap med Sveriges Paralympiska Kommitté (SPK) som officiell affärsjuridisk rådgivare, läs mer här.\n\nVinges team i tvisten i CAS bestod av James Hope, Nils Ivars och Sebastian Saadieh.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-sveriges-olympiska-kommitte-sok-vid-uppmarksammat-principavgorande-i-idrottens-skiljedomstol-cas/","date":"2025-02-28","month":2},{"year":2025,"client":"Briban Invest","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","Företagsbeskattning","FDI"],"title":"Vinge biträder Briban Invest i budet på Sydsvenska Hem","caption":"Övrigt · 28 februari 2025","preamble":"Briban Invest AB har lämnat ett offentligt uppköpserbjudande till aktieägarna i Sydsvenska Hem AB (publ).","body":"Erbjudandet värderar samtliga aktier i Sydsvenska Hem till cirka 784 miljoner kronor, baserat på kontantalternativet i budet.\n\nVinges team består av Erik Sjöman, Amanda Knutsson, Joel Magnusson, Anna Svensson och Vilma Henricsson (Kapitalmarknad och publik M&A), Victor Ericsson, Erik Kochbati och Axel Åshuvud (Skatt) samt Sofie Nordgren och Jasmine Elgh (FDI).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-briban-invest-i-budet-pa-sydsvenska-hem/","date":"2025-02-28","month":2},{"year":2025,"client":"Sobro","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder Sobro vid försäljning av Mercur till Accel-KKR","caption":"Avyttring · 27 februari 2025","preamble":"Vinge har biträtt Sobro och övriga aktieägare vid försäljningen av Mercur till Accel-KKRs portföljbolag Aico. Mercur är en ledande leverantör av lösningar för verksamhetsstyrning och beslutsstöd för medelstora och stora företag och Aico erbjuder en avancerad plattform för automatisering av bokslutsprocesser för medelstora och stora företag.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Per Kling och Alex Forsberg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sobro-vid-forsaljning-av-mercur-till-accel-kkr/","date":"2025-02-27","month":2},{"year":2025,"client":"Schibsted Media","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","Immaterialrätt","GDPR","Arbetsrätt","Fastigheter och Entreprenad","FDI","EU‑ och konkurrensrätt","Corporate Crime & Compliance","Carve-Outs"],"title":"Vinge företräder Schibsted Media i samband med deras förvärv av TV4 och MTV Finland","caption":"Förvärv · 25 februari 2025","preamble":"Schibsted Media har ingått avtal avseende förvärv av Telia Companys TV & Media-verksamhet, vilket inkluderar TV4 i Sverige och MTV Finland. Transaktionen görs på basis av ett bolagsvärde om SEK 6,55 miljarder på en kontant- och skuldfri basis och den förväntas stänga under Q3 2025, villkorat av att sedvanliga regulatoriska godkännanden har erhållits.","body":"Vinges team bestod huvudsakligen av Johan Larsson, Johan Winnerblad, Jesper Ottergren, Per Kling, Nathalie Wikman (M&A), Eva Fredrikson, Martin Boström, Elis Allmark, Mario Saad(Kommersiella avtal), Malin Malm Waerme, Arvid Axelryd, Ian Jonson, Alva Skott, Melinda Oldenburg (Immaterialrätt), Nicklas Thorgerzon (GDPR), Sam Seddigh, Emil Lindwall, Agnes Pigg (Arbetsrätt), Kristoffer Larson, Sara Franson (Fastighetsrätt), Marcus Glader, Fredrik Hellström, Jakob Jeanrond, Martin Bergqvist, Martin Hammarskiöld (Konkurrensrätt och FDI), Martin Johansson, Carl Johan af Petersens, Hampus Peterson (Compliance och regulatoriska frågor).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-schibsted-media-i-samband-med-deras-forvarv-av-tv4-och-mtv-finland/","date":"2025-02-25","month":2},{"year":2025,"client":"Oral Care","work":"Förvärv","disciplines":["Bank och finans","Arbetsrätt","M&A","Immaterialrätt","Kommersiella avtal"],"title":"Vinge företräder Oral Care i samband med förvärvet av den nederländska tandvårdsleverantören De Tandartsengroep (DTG)","caption":"Förvärv · 19 februari 2025","preamble":"DTG driver 31 kliniker och 8 tandtekniska laboratorier i Nederländerna. Oral Care är ett portföljbolag till Axcel VI och driver ett nätverk av tandvårdskliniker i Sverige, Norge och Nederländerna. För att stödja denna expansion går Axcel VII in som aktieägare i Oral Care tillsammans med Axcel VI.","body":"Transaktionen är föremål för sedvanligt godkännande från den nederländska vårdmyndigheten (Dutch Health Care Authority) och den nederländska myndigheten för konsumenter och marknader (ACM).\n\nVinges team bestod av Christina Kokko, Manon de Cooman, Gustav Wahlberg, Helena Liljenberg, Josef Groow (M&A), Alice Göransson (Arbetsrätt), Avid Axelryd (Immaterialrätt), Calle Tengwall Pagels, August Ahlin, Sara Jansson (Bank och Finans), Carla Håkansson, Katja Hägglund (Kommersiella avtal), Frida Lansfjord, Jacob Guve, Alma Rotsman, Augus Olding (Assistenter).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-oral-care-i-samband-med-forvarvet-av-den-nederlandska-tandvardsleverantoren-de-tandartsengroep-dtg/","date":"2025-02-19","month":2},{"year":2025,"client":"Pyrotek Global Holdings","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företrädde Pyrotek Global Holdings vid förvärv","caption":"Förvärv · 19 februari 2025","preamble":"Vinge företrädde Pyrotek Global Holdings Inc vid deras förvärv av SFX controllers Sweden AB, Unique Pyrotechnic ApS, Unique Pyrotechnic AS, Laserteknikk AS, Fyrverkeri Experterna Per Hultgren AB och Unique Pyrotechnic AB.","body":"Vinges team leddes av Wibeke Sorling (Partner, M&A) och bestod vidare av Amelia Rihs (M&A), Anna Högsten (Employment, IT and data protection), Aleksandar Bajic (Commercial Agreements), Fredrik Löwenclou (Compliance) och Carl-Johan Lerjefors (Real estate).","href":"https://www.vinge.se/uppdrag/vinge-foretradde-pyrotek-global-holdings-vid-forvarv/","date":"2025-02-19","month":2},{"year":2025,"client":"Gotlandsbolaget","work":"Avtal","disciplines":["Kommersiella avtal","M&A"],"title":"Vinge biträder Gotlandsbolaget i samband med off-take avtal avseende biogas","caption":"Avtal · 17 februari 2025","preamble":"Vinge har företrätt Rederiaktiebolaget Gotland (Gotlandsbolaget) i samband med ingåendet av ett strategiskt off-take avtal, som säkerställer långsiktig biogasförsörjning för Gotlandstrafiken.","body":"Gotlandsbolaget har som mål att erbjuda klimatneutrala överfarter mellan Gotland och fastlandet senast 2045. För att göra detta, krävs stora volymer av fossilfria bränslen. Vinge har biträtt Gotlandsbolaget i en investering i en byggnation av en biogasanläggning utanför Eskilstuna för produktion av högkvalitativ biogas samt förhandling och ingående av ett 10 årigt off-take avtal avseende köp och leverans av den tillverkade biogasen. Genom transaktionen har Gotlandsbolaget tagit viktiga steg för att nå sitt mål om klimatneutrala överfarter mellan Gotland och fastlandet. Anläggningen väntas tas i bruk 2026.\n\nVinges team bestod huvudsakligen av Malin Ohlin och Mario Saad.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-gotlandsbolaget-i-samband-med-off-take-avtal-avseende-biogas/","date":"2025-02-17","month":2},{"year":2025,"client":"HAKI Safety","work":"Förvärv","disciplines":["Arbetsrätt","Immaterialrätt","M&A","FDI","Kommersiella avtal"],"title":"Vinge företräder HAKI Safety AB i samband med förvärvet av Trimtec","caption":"Förvärv · 14 februari 2025","preamble":"Trimtec är en svensk återförsäljare av högteknologiska precisionsinstrument.","body":"Trimtec erbjuder köp och uthyrning av precisionsinstrument för bland annat lantmäteri och kartläggning. I erbjudandet ingår också serviceavtal för underhåll och utbildningsuppdrag. Huvudkontoret ligger i Stockholm och bolaget har säljkontor i ytterligare fem svenska städer. Merparten av bolagets produktsortiment tillverkas av Trimble, en ledande tillverkare av mätinstrument för lantmäteri och kartläggning.\n\nVinges team bestod av Anna Edström, Nicolas Ek och Emil Sandgrim (M&A), Johanne Örnfeldt Svensson och Agnes Tell (kommersiella avtal), Tove Hallbäck (arbetsrätt), Lisa Bourghardt (IP) samt Sofie Nordgren och Nathalie Wikman (FDI).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-haki-safety-ab-i-samband-med-forvarvet-av-trimtec/","date":"2025-02-14","month":2},{"year":2025,"client":"Gotlandsbolaget","work":"Övrigt","disciplines":["Sjö‑ och transporträtt"],"title":"Vinge bistår Gotlandsbolaget i satsningen på framtidens sjöfart","caption":"Övrigt · 14 februari 2025","preamble":"Gotlandsbolaget har tagit ett viktigt steg mot en mer hållbar framtid genom att beställa den snabbgående katamaranen Gotland Horizon X, som kommer att drivas av fossilfria bränslen. För Vinge har det varit ett privilegium att bistå Gotlandsbolaget med rådgivning under processen.","body":"Fartyget, som byggs av det australiensiska varvet Austal, blir ett banbrytande exempel på framtidens hållbara färjetrafik. Rådgivningen har omfattat såväl upprättande och förhandling av skeppsbyggnadskontrakt som immaterialrättsliga frågor. Med vårt stöd har Gotlandsbolaget, Sveriges äldsta passagerarrederi, kunnat fokusera på att utveckla en lösning som inte bara gynnar Gotlandstrafiken, utan också bidrar till sjöfartens omställning mot en klimatneutral framtid.\n\nEn hållbar lösning för Gotlandstrafiken\n\nGotland Horizon X kommer att vara en snabbgående katamaran med plats för 1500 passagerare och 400 personbilar, som kan drivas med flera typer av fossilfria drivmedel. Fartyget kommer att kunna gå i 29 knop, vilket ger en överfartstid mellan Gotland och fastlandet på drygt 3 timmar.\n\nVi på Vinge ser fram emot att följa utvecklingen och är stolta över att ha varit en del av Gotlandsbolagets viktiga satsning på hållbarhet och innovation.\n\nVinges team har bestått av Paula Bäckdén, Alexander Lindeberg och Imola Szanto Francsics.","href":"https://www.vinge.se/uppdrag/vinge-bistar-gotlandsbolaget-i-satsningen-pa-framtidens-sjofart/","date":"2025-02-14","month":2},{"year":2025,"client":"Industrifonden","work":"Kapitalanskaffning","disciplines":["M&A","Arbetsrätt","Immaterialrättsliga tvister"],"title":"Vinge företräder Industrifonden i samband med deras investering i Agteria Biotech","caption":"Kapitalanskaffning · 13 februari 2025","preamble":"Vinge företräder Industrifonden i samband med deras deltagande i Agteria Biotech AB’s seed-finansiering. Rundan leddes av Industrifonden och AgriZeroNZ.","body":"Agteria Biotech AB är ett svenskt start-up-företag vars målsättning är att minska de globala utsläppen av växthusgaser med 1% genom deras patentsökta molekyl som avsevärt minskar metanutsläppen från nötkreatur. Den nya finansieringen kommer att göra det möjligt för bolaget att gå vidare med regulatoriskt godkännande för molekylen, med fokus på säkerhetsstudier för djur, konsumenter samt miljö. Vinges team bestod huvudsakligen av Johan Larsson, Maria Dahlin Kolvik, Ian Linde (M&A), Åsa Hellstadius, Rebecka Målquist (IP), Simon Söderholm och Agnes Pigg (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-industrifonden-i-samband-med-deras-investering-i-agteria-biotech/","date":"2025-02-13","month":2},{"year":2025,"client":"Axcel och Accru Partners","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Bank och finans","Kommersiella avtal","IT, Telekom och Outsourcing","Immaterialrätt","GDPR","Fastigheter och Entreprenad","Finansiella tillståndsfrågor"],"title":"Vinge företräder Axcel och Accru Partners vid förvärvet av Sporrong & Eriksson Revisionsbyrå AB","caption":"Förvärv · 12 februari 2025","preamble":"Vinge har företrätt Axcel VII och Accru Partners i samband med förvärvet av Sporrong & Eriksson Revisionsbyrå AB.","body":"Sporrong & Eriksson Revisionsbyrå AB är ett entreprenörslett, lokalt företag med expertis inom redovisning, revision, skatt, företagsöverlåtelser och rådgivningstjänster. Efter förvärvet består Accru Partners av totalt 28 självständiga byråer inom nämnda verksamhetsområden.\n\nVinges team bestod av Christina Kokko, Egil Svensson, Michella Lina Said och Chris Bastholm (M&A), Narin Melazade och Simon Söderholm (Arbetsrätt), Sofia Haggren (Bank och finans), Mario Saad (Kommersiella avtal), Elis Allmark (IT), Rebecka Målquist (Immaterialrätt), Nicklas Thorgerzon (GDPR), Madelene Andersson (Fastighet), Jonna Bondemark (Regulatoriska frågor), Gulestan Ali och Jonna Fransson (Regelefterlevnad) samt Jessica Öijer (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-accru-partners-vid-forvarvet-av-sporrong-eriksson-revisionsbyra-ab/","date":"2025-02-12","month":2},{"year":2025,"client":"American Industrial Partners (AIP)","work":"Övrigt","disciplines":["M&A","Företagsbeskattning","Arbetsrätt"],"title":"Vinge har biträtt American Industrial Partners (AIP)","caption":"Övrigt · 12 februari 2025","preamble":"Vinge har biträtt American Industrial Partners (AIP) samband med förvärvet av Munters FoodTechs verksamhet för utrustning till livsmedelsindustrin (FoodTech Equipment).","body":"Munters FoodTech är ett av tre affärsområden inom Munters AB, en global ledare inom lösningar för klimatkontroll. FoodTech Equipment är specialiserat på lösningar för kritisk luftkvalitet, rörelse och temperaturkontroll inom slutmarknaderna för djuruppfödning och växthus. Transaktionen förväntas slutföras under Q2 2025, med förbehåll för sedvanliga villkor.\n\nVinge biträdde AIP, tillsammans med Sidley Austin, med ett team lett av delägare Sofie Nordgren (M&A) och inkluderande delägare Victor Ericsson (skatt) samt biträdande juristerna Jonatan Karlsson (M&A) och Karin Hultgren (arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-american-industrial-partners-aip/","date":"2025-02-12","month":2},{"year":2025,"client":"Gränges","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt Gränges i samband med refinansieringen av dess hållbarhetslänkade kreditfacilitet","caption":"Finansiering · 10 februari 2025","preamble":"Vinge har företrätt Gränges AB (publ) (”Gränges”), en global ledare inom valsning och återvinning av aluminium för utvalda nischer, i samband med refinansieringen av bolagets hållbarhetslänkade kreditfacilitet, som stödjer Gränges hållbarhetsmål.","body":"Kreditfaciliteten, som arrangerats av Danske Bank, Nordea, SEB och Citibank, består av en revolverande kreditfacilitet om 3 000 MSEK (med möjlighet till utökning till 3 500 MSEK) samt en tidsbegränsad facilitet om 70 MUSD. Avtalet löper över tre år, med möjlighet till förlängning i ytterligare två år.\n\nFinansieringen är kopplad till utfallen av två hållbarhetsnyckeltal (KPI:er) relaterade till Gränges klimatmål, vilka även återspeglas i bolagets ramverk för hållbarhetslänkad finansiering. Det nya avtalet förväntas bidra med minskade finansieringskostnader och ytterligare stärka Gränges hållbarhetsprofil. I samband med refinansieringen har kreditfaciliteten från 2022 återbetalats.\n\nVinges team bestod av Helena Göransson och Karl-Gustaw Tobola.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-granges-i-samband-med-refinansieringen-av-dess-hallbarhetslankade-kreditfacilitet/","date":"2025-02-10","month":2},{"year":2025,"client":"Priveq Fund VII","work":"Finansiering","disciplines":["Bank och finans","Private Funds"],"title":"Vinge har företrätt Priveq Fund VII i samband med en hållbarhetslänkad kreditfacilitet","caption":"Finansiering · 10 februari 2025","preamble":"Priveq Fund VII har ingått ett kreditfacilitetsavtal med Swedbank AB (publ) vilket främst kommer att användas för att finansiera fondens investeringsverksamhet. Kreditfaciliteten är kopplad till vissa av Priveqs hållbarhetsmål, vilket innebär att räntesatsen på kreditfaciliteten kommer att justeras upp eller ned baserat på Priveq Fund VII:s portföljbolags prestationer.","body":"Vinges team bestod huvudsakligen av Helena Göransson, Nour Makie, Sara Jansson, Marcus Andersson och Tobias Onegård Karlsson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-priveq-fund-vii-i-samband-med-en-hallbarhetslankad-kreditfacilitet/","date":"2025-02-10","month":2},{"year":2025,"client":"ReCarber","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har biträtt ReCarber i samband med kapitalanskaffning","caption":"Kapitalanskaffning · 10 februari 2025","preamble":"Vinge har biträtt ReCarber AB i samband med kapitalanskaffning om 60 miljoner kronor. Kapitalet investeras av Luminar Ventures, Spintop Ventures och Course Corrected.","body":"ReCarber startades hösten 2023 med syfte att finansiera och leda projekt som fångar och lagrar biogen koldioxid, som sedan lagras in permanent i berggrunden.\n\nVinges Johan Larsson biträdde ReCarber.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-recarber-i-samband-med-kapitalanskaffning/","date":"2025-02-10","month":2},{"year":2025,"client":"Lagercrantz Group","work":"Förvärv","disciplines":[],"title":"Vinge biträder Lagercrantz Group AB vid förvärv av PPV Plast & Plåt Vägmärken AB","caption":"Förvärv · 7 februari 2025","preamble":"Vinge har biträtt Lagercrantz Group vid förvärv av samtliga aktier i PPV Plast & Plåt Vägmärken AB, en ledande aktör inom permanent och tillfällig vägmärkning.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Ida Appelgren och Katja Häglund.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-ab-vid-forvarv-av-ppv-plast-plat-vagmarken-ab/","date":"2025-02-07","month":2},{"year":2025,"client":"Main Capital och Björn Lundén","work":"Förvärv","disciplines":[],"title":"Vinge företräder Main Capital och Björn Lundén vid förvärvet av Aprello","caption":"Förvärv · 30 januari 2025","preamble":"Vinge har företrätt Björn Lundén, en leverantör av mjukvarulösningar för redovisning och finansiell administration, i samband med förvärvet av Aprello AB (”Aprello”). Det strategiska förvärvet kompletterar Björn Lundéns tillväxtstrategi på den europeiska marknaden för mjukvara för finansiell administration.","body":"Aprello, grundat 2017, är specialiserat på att utveckla mjukvarulösningar för årsredovisning och skattedeklarationer och vänder sig till såväl skatte- och redovisningsbyråer som små och medelstora företag i Sverige. Aprello fokuserar på användarvänliga lösningar och erbjuder funktioner som smarta mallar, digitala förvaltningsberättelser, e-signering och steg-för-steg-vägledning.\n\nVinges team bestod av Filip Öhrner, Maria Dahlin Kolvik, Alexander Rüdén (M&A), Martin Boström (GDPR) och Felizia Wiker (IP).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-och-bjorn-lunden-vid-forvarvet-av-aprello/","date":"2025-01-30","month":1},{"year":2025,"client":"ABGSC","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder ABGSC i samband med EQL Pharmas första obligationsemission","caption":"Obligationsemission · 24 januari 2025","preamble":"Vinge biträder ABG Sundal Collier i samband med EQL Pharma AB (publ) (”EQL”) första emission av seniora säkerställda obligationer om 350 000 000 SEK inom ett ramverk om upp till 700 000 000 SEK.","body":"Obligationerna löper med en rörlig ränta om STIBOR 3m + 4,00% och har en löptid om tre år. EQL avser att ansöka om upptagande till handel av obligationerna på Nasdaq Transfer Market och Nasdaqs Stockholms lista för företagsobligationer. Emissionslikviden kommer att användas för att finansiera inkråmsförvärvet av en produktportfölj bestående av originalläkemedel, återbetalning av existerande skuld samt för allmänna företagsändamål.\n\nVinges team bestod av Mikael Ståhl, Arvid Weimers, August Ahlin och Sara Jansson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-abgsc-i-samband-med-eql-pharma-s-forsta-obligationsemission/","date":"2025-01-24","month":1},{"year":2025,"client":"Majoritetsaktieägarna Altor","work":"Avyttring","disciplines":["M&A","Kapitalmarknad och publik M&A","Bank och finans","Immaterialrätt","Kommersiella avtal","IT, Telekom och Outsourcing","Arbetsrätt","Corporate Crime & Compliance","Fastigheter och Entreprenad","EU‑ och konkurrensrätt"],"title":"Vinge företräder majoritetsaktieägarna Altor, Telia Company, Time For Growth och Zenith VC i försäljningen av aktier i Marshall Group","caption":"Avyttring · 24 januari 2025","preamble":"Vinge företräder majoritetsaktieägarna Altor, Telia Company, Time For Growth och Zenith VC i samband med försäljningen av aktier i Marshall Group AB (publ) (”Marshall Group”) till HongShan Group, tidigare känt som Sequoia China. Marshall-familjen kommer fortsatt att vara ägare i Marshall Group.","body":"Marshall Group är ledande inom ljud, teknik och design och för samman musiker och musikälskare genom genrebrytande innovation. Marshall, bolagets huvudvarumärke, är unikt positionerat med över 60 års rock'n'roll-attityd på scen, hemma och på språng, på över 90 marknader. Marshall Group omsätter över 400 miljoner euro och sammanför cirka 800 talangfulla medarbetare på åtta platser i världen.\n\nTransaktionen är föremål för tillämpliga konkurrensrättsliga godkännanden.\n\nVinges team bestod av Christina Kokko, Johanna Wiberg, Elsie Nassar, Ellinor Wargenbrant och Emma Lundberg (M&A), David Andersson och Joel Magnusson (Kapitalmarknad & publik M&A), Albert Wållgren, Karl-Gustaw Tobola och William Carlberg Johansson (Bank och finans), Rebecka Målquist (Immaterialrätt), Martin Boström och Mario Saad (Kommersiella avtal), Carla Håkansson och Siri Blomberg (IT och GDPR), Emil Lindwall (Arbetsrätt), Hayaat Ibrahim och Gulestan Ali (Compliance), Hanna Kövamees (Fastighet och miljö), Marcus Glader, Sebastian Örndahl, Lovisa Lewin och Alva Chambert (EU- och konkurrensrätt), Ellinore Boström Andersson, Cecilia Loctander, Emelie Schoning och Gabriella Balbo (Projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-majoritetsaktieagarna-altor-telia-company-time-och-zenith-i-forsaljningen-av-aktier-i-marshall-group/","date":"2025-01-24","month":1},{"year":2025,"client":"Sedana Medical","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Sedana Medical AB vid förvärvet av Innovatif Cekal","caption":"Förvärv · 22 januari 2025","preamble":"Vinge har företrätt Sedana Medical AB (publ) i samband med förvärvet av Innovatif Cekal. Innovatif Cekal, med säte i Klang nära Kuala Lumpur i Malaysia, är en tillverkare av medicintekniska produkter. Genom detta förvärv stärker Sedana Medical sin kontroll över leverantörskedjan och förbättrar sin lönsamhet genom minskade varukostnader.","body":"Vinges team bestod av Matthias Pannier, Dain Hård Nevonen, Gustav Persson och Chris Bastholm.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-sedana-medical-ab-publ-vid-forvarvet-av-innovatif-cekal/","date":"2025-01-22","month":1},{"year":2025,"client":"Infranity","work":"Förvärv","disciplines":["Arbetsrätt","M&A","GDPR","FDI","Immaterialrätt","Företagsbeskattning","Bank och finans"],"title":"Vinge företräder Infranity i samband med förvärvet av Nordic Re-Finance AB","caption":"Förvärv · 20 januari 2025","preamble":"Vinge har företrätt Infranity, ett private equity-bolag specialiserat på investeringar inom infrastruktur, i samband med deras majoritetsförvärv av Nordic Re-Finance AB, en skandinavisk uthyrare av lokomotiv. Förvärvet innebär ambitiösa utvecklingsplaner för Nordic Re-Finance AB, inklusive expansion till nya geografiska områden.","body":"Transaktionen är villkorad av regulatoriska godkännanden och förväntas slutföras under Q1 2025.\n\nVinges team bestod huvudsakligen av Matthias Pannier, Ulrich Ziche, Robin Sultani och Sara Hammond (M&A), Calle Tengwall Pagels och Julia Gudmundsson (Bank och Finans), Jolene Reimerson, Christoffer Nordin, Katja Häglund och Nicklas Thorgerzon (Kommersiella avtal, IT och GDPR), Victor Ericsson, Erik Kochbati, Tobias Fleischer, Ellenor Eckerborn och Marcus Svärd (Skatt), Alice Göransson och Gulestan Ali (Arbetsrätt), Tobias Kempas och Rebecka Målquist (IP), Daniel Wendelsson, Alva Chambert och Martin Hammarskiöld (FDI) samt Julia Ulander Kull (Transaktionssupport).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-infranity-i-samband-med-forvarvet-av-nordic-re-finance-ab/","date":"2025-01-20","month":1},{"year":2025,"client":"Platzer","work":"Avyttring","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge företräder Platzer vid försäljning av skolfastighet i Göteborg","caption":"Avyttring · 17 januari 2025","preamble":"Vinge har bistått Platzer Fastigheter AB vid försäljningen av en skolfastighet i Södra Änggården, Göteborg. Fastigheten, som såldes genom en bolagsaffär, har ett värde om 552 miljoner kronor. Försäljningen är en del av Platzers strategi att utveckla och optimera sitt fastighetsbestånd.","body":"Vinges team bestod huvudsakligen av advokaterna Robert Deli och Adam Loewenstein.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-platzer-vid-forsaljning-av-skolfastighet-i-goteborg/","date":"2025-01-17","month":1},{"year":2025,"client":"Qben Infra","work":"Obligationsemission","disciplines":[],"title":"Vinge biträder Qben Infra vid emission av seniora, icke-säkerställda obligationer och förtida återinlösen","caption":"Obligationsemission · 16 januari 2025","preamble":"Vinge har biträtt Qben Infra AB vid dess emission av seniora, icke-säkerställda obligationer om SEK 500 000 000 (inom en ram om SEK 600 000 000) och i samband med dess dotterbolag ININ Group AS parallella förtida återinlösen av dess tidigare emitterade seniora, säkerställda obligationer med förfall under 2027.","body":"De nya obligationerna löper med en rörlig ränta om STIBOR 3M + 800 baspunkter och har en löptid om tre år. Emissionslikviden ska användas för att refinansiera ININ Group’s tidigare obligationer, viss bankskuld inom Qben-koncernen samt för allmänna företagsändamål. Bolaget avser att ansöka om upptagande till handel av obligationerna på Nasdaq Transfer Market och Nasdaq Stockholms lista för företagsobligationer.\n\nDNB Bank ASA, filial Sverige, har agerat Sole Bookrunner.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda, Felix Möller, Calle Tengwall Pagels och August Ahlin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-qben-infra-vid-emission-av-seniora-icke-sakerstallda-obligationer-och-fortida-aterinlosen/","date":"2025-01-16","month":1},{"year":2025,"client":"Ellevio","work":"Förvärv","disciplines":["M&A","Miljörätt","Fastigheter och Entreprenad","IT, Telekom och Outsourcing","GDPR","Kommersiella avtal","FDI","Offentlig upphandling","Arbetsrätt","Corporate Crime & Compliance"],"title":"Vinge företräder Ellevio vid förvärv av Markbygden Net Väst AB","caption":"Förvärv · 16 januari 2025","preamble":"Vinge företräder Ellevio vid förvärvet av Markbygden Net Väst AB, ett nätbolag som ansluter till stamnätet via Svenska kraftnäts station i Trolltjärn utanför Arvidsjaur, från Enercon.","body":"Ellevio är ett av Sveriges största elnätsföretag och genom förvärvet stärker Ellevio sin roll som en ledande aktör i den svenska energiomställningen och vägen mot nettonollutsläpp 2045.\n\nVinges team bestod av ansvarige delägaren Peter Sundgren (Energi/M&A) tillsammans med Gustav Persson och Ida Appelgren (M&A), Johan Cederblad och Lina Österberg (Tillstånd och Miljörätt), Kristoffer Larson och Hanna Kövamees (Fastighetsrätt), Fredrika Hjelmberg och Siri Blomberg (IT och GDPR), Mario Saad och Jolene Reimerson (Kommersiella avtal), Daniel Wendelsson, Dagne Sabockis, Alva Chambert och Isabell Åkerblom (FDI), Kristoffer Sällfors (Offentlig upphandling), Carl Johan af Petersens och Andrea Rökaas (Regulatoriska frågor), Niclas Lindblom (Entreprenadrätt), Ian Jonson (IP), Amelia Rihs (Arbetsrätt), August Ahlin (Bank och finans), Gulestan Ali och Jonna Fransson (Compliance), Caroline Löv (Transaktionssupport).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ellevio-vid-forvarv-av-markbygden-net-vast-ab/","date":"2025-01-16","month":1},{"year":2025,"client":"Intera Partners","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Intera Partners i samband med investeringen i Yellow Elk","caption":"Kapitalanskaffning · 15 januari 2025","preamble":"Vinge har företrätt det nordiska private equity-bolaget Intera Partners vid investeringen i AI- och dataanalysföretaget Yellow Elk.","body":"Yellow Elk erbjuder expertis inom dataanalys och AI, med tjänster som sträcker sig från data engineering till maskininlärning, visualisering, analys och andra rådgivningstjänster, inklusive företags- och dataarkitektur samt datadriven utveckling. Yellow Elk grundades 2018 och har en omsättning på 150 miljoner kronor samt sysselsätter runt 90 experter inom dataanalys i Sverige. Yellow Elk har mottagit Dagens Industris Gasell-utmärkelse för snabbväxande företag de tre senaste åren.\n\nTransaktionen är villkorad av regulatoriska godkännanden.\n\nVinges team bestod av Jonas Johansson, Egil Svensson och Helena Liljenberg (M&A), Helena Göransson och Karl-Gustaw Tobola (Banking and Finance), Mario Saad och Jacob Eberil (Commercial Agreements), Simon Söderholm och Agnes Pigg (Employment), Johan Gavelin (IP), Katja Häglund (IT and GDPR), Madelene Andersson och Sara Franson (Real Estate), Daniel Wendelsson, Martin Hammarskiöld och Lovisa Arpi (Regulatory).\n\nLäs klientens pressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-intera-partners-i-samband-med-investeringen-i-yellow-elk/","date":"2025-01-15","month":1},{"year":2025,"client":"Inflexion","work":"Förvärv","disciplines":["M&A","Företagsbeskattning","Bank och finans","Immaterialrätt","Arbetsrätt","Kommersiella avtal","Corporate Crime & Compliance","GDPR","FDI"],"title":"Vinge har företrätt Inflexion i samband med förvärvet av Mecenat","caption":"Förvärv · 14 januari 2025","preamble":"Vinge har företrätt Inflexion i samband med förvärvet av Mecenatgruppen från IK. Förvärvet av Mecenat är den första investeringen som görs genom Inflexions nya Enterprise Fund VI, och Inflexions första förvärv i Sverige.","body":"Mecenat är en digital marknadsplats som kopplar samman studenter, alumner, unga yrkesverksamma och seniorer med välkända varumärken genom att erbjuda tillgång till exklusiva erbjudanden, karriärtjänster och relevanta evenemang. Mecenatgruppen verkar inom både Sverige och Finland, har drygt tre miljoner medlemmar och samarbetar med fler än 700 lokala och globala varumärken. Mecenats plattform sträcker sig över olika branscher, däribland teknik, mode, resor och underhållning.\n\nVinges team bestod huvudsakligen av Christina Kokko, Maria Dahlin Kolvik, Eléonore Friberg, Carl Fredrik Wachtmeister, Madelene Andersson och Chris Bastholm (M&A), Victor Ericsson (Skatt), Helena Göransson, Karl-Gustaw Tobola, August Ahlin och Matilda Hamner (Bank och finans), Ian Jonsson och Siri Blomberg (IP), Simon Söderholm och Linn Aho (Arbetsrätt), Carla Håkansson och Hanna Kövamees (Kommersiella avtal), Katja Häglund (GDPR), Hayaat Ibrahim (Compliance), Nils Unckel och Anton Sjökvist (AIFMD), Lovisa Lewin och Alva Chambert (Konkurrensrätt och FDI) och Caroline Löv (Projektassistent).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-inflexion-i-samband-med-forvarvet-av-mecenat/","date":"2025-01-14","month":1},{"year":2025,"client":"Säljarna","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt säljarna vid försäljningen av Färskvaruhuset i Göteborg AB","caption":"Avyttring · 13 januari 2025","preamble":"Färskvaruhuset i Göteborg AB är en svensk rikstäckande leverantör till detaljhandeln av kött och fågel samt chark- och delikatessvaror. Förvärvaren var det internationella livsmedelshandelsföretaget BPI A/S med huvudkontor i Danmark.","body":"Vinges team bestod av Magnus Pauli, Johanna Hamrefält (projektledare), Amelia Rihs, Fredrik Löwenclou, Tyra Fellbom von Mentzer och Amanda Stoltz.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-saljarna-vid-forsaljningen-av-farskvaruhuset-i-goteborg-ab/","date":"2025-01-13","month":1},{"year":2025,"client":"Säljaren","work":"Avyttring","disciplines":["M&A"],"title":"Vinge har biträtt säljaren vid försäljningen av Lundby Plåt Aktiebolag","caption":"Avyttring · 13 januari 2025","preamble":"Lundby Plåt Aktiebolag tillhandahåller tjänster inom plåtslageri. Förvärvaren var det Göteborgsbaserade entreprenad- och byggserviceföretaget Göfast Gruppen AB.","body":"Vinges team bestod av Magnus Pauli, Johanna Hamrefält (projektledare), Amelia Rihs, Fredrik Löwenclou och Tyra Fellbom von Mentzer.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-saljaren-vid-forsaljningen-av-lundby-plat-aktiebolag/","date":"2025-01-13","month":1},{"year":2025,"client":"Bergs Timber","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder Bergs Timber vid försäljningen av Vika Woods till HS Timber group","caption":"Avyttring · 10 januari 2025","preamble":"Vinge har biträtt Bergs Timber AB vid försäljningen av det lettiska träförädlingsföretaget Vika Wood SIA till den österrikiska HS Timber group.","body":"Transaktionen är fortfarande föremål för godkännande av konkurrensmyndigheten och förväntas slutföras under det första kvartalet 2025. För detaljer hänvisas till Bergs Timbers pressmeddelande.\n\nVinges team bestod i huvudsak av Ulrich Ziche, Niclas Suni (M&A) och Emelie Schoning (Transaktionssupport).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-bergs-timber-vid-forsaljningen-av-vika-woods-till-hs-timber-group/","date":"2025-01-10","month":1},{"year":2025,"client":"TUI-koncernen","work":"Finansiering","disciplines":[],"title":"Vinge rådgivare till TUI-koncernen i samband med hållbarhetslänkad kreditfacilitet","caption":"Finansiering · 1 januari 1970","preamble":"Vinge har agerat lokal rådgivare åt TUI-koncernen, världens ledande integrerade resekoncern, i samband med ingåendet av avtal om en revolverande kreditfacilitet om 1,89 miljarder euro.","body":null,"href":"https://www.vinge.se/uppdrag/vinge-raadgivare-till-tui-koncernen-i-samband-med-haallbarhetslaenkad-kreditfacilitet/","date":null},{"year":2024,"client":"Stenhus Fastigheter","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","Företagsbeskattning","Bank och finans","Corporate Crime & Compliance","Arbetsrätt","Miljörätt","IT, Telekom och Outsourcing","Fastigheter och Entreprenad"],"title":"Vinge har företrätt Stenhus Fastigheter i Norden AB i samband med deras listbyte till Nasdaq Stockholm","caption":"Övrigt · 20 december 2024","preamble":"Vinge har företrätt Stenhus Fastigheter i Norden AB (publ) (”Stenhus Fastigheter” eller ”Bolaget”) i samband med Bolagets listbyte till Nasdaq Stockholm. Första handelsdag på Nasdaq Stockholm var den 18 december 2024.","body":"Stenhus Fastigheter är ett fastighetsbolag som äger och förvaltar offentliga fastigheter och kommersiella fastigheter med tydligt geografiskt fokus på storstadsområden samt tillväxtorter. Stenhus Fastigheter arbetar även aktivt med befintliga och potentiella byggrätter inom det nuvarande beståndet.\n\nVinges team bestod i huvudsak av Rikard Lindahl, Joel Magnusson och Michaela Ådén (Kapitalmarknad och Publik M&A), Diana Kanold (VDR), Victor Ericsson, Emelie Svanberg, Marcus Svärd och Ellenor Eckerborn (Skatt), Nicklas Thorgerzon och Siri Blomberg (IT och GDPR), Ebba Svenburg och Jonna Skog (Arbetsrätt), Kristoffer Larson, Madelene Andersson och Sara Franson (Fastighet), Lina Österberg (Miljö), Ida Redander, August Ahlin och William Carlberg Johansson (Bank- och finans) samt Hayaat Ibrahim och Jonna Fransson (Compliance).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-stenhus-fastigheter-i-norden-ab-publ-i-samband-med-deras-listbyte-till-nasdaq-stockholm/","date":"2024-12-20","month":12},{"year":2024,"client":"Platzer","work":"Avyttring","disciplines":[],"title":"Vinge biträdde Platzer vid dess försäljning av byggrätter i Södra Änggården till bostadsutvecklaren Bonava","caption":"Avyttring · 20 december 2024","preamble":"Affären sker genom ett bolagsförvärv till ett underliggande fastighetsvärde om 186 miljoner kronor.","body":"Från Vinges sida medverkade främst Olof Jisland och Kristoffer Larson.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-platzer-vid-dess-forsaljning-av-byggratter-i-sodra-anggarden-till-bostadsutvecklaren-bonava/","date":"2024-12-20","month":12},{"year":2024,"client":"Inter IKEA","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Inter IKEA i samband med förvärv av skog och mark i Lettland","caption":"Förvärv · 16 december 2024","preamble":"Vinge biträder IKEA Forestry Investment AB (ett bolag inom Inter IKEA-koncernen) vid förvärv av 100% av aktierna i de två lettiska bolagen SIA \"Latvijas Mežu Aģentūra\" och SIA \"Vadakstes Meži\" (”Bolagen”) från Skogsfond Baltikum AB (publ). Bolagen äger totalt 8.080 hektar skog och mark i Lettland.","body":"Vinges team bestod av Björn Mullaart, Niklas Törnell och Jonatan Karlsson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-inter-ikea-i-samband-med-forvarv-av-skog-och-mark-i-lettland/","date":"2024-12-16","month":12},{"year":2024,"client":"Enterstore","work":"Förvärv","disciplines":["M&A","EU‑ och konkurrensrätt","Försäkring","GDPR","Kommersiella avtal","Bank och finans"],"title":"Vinge biträder enterstore i samband med förvärvet av Miss Mary of Sweden","caption":"Förvärv · 16 december 2024","preamble":"Enterstore a.s., ägt av Hartenberg Holding, har ingått avtal med Scope Growth III L.P. om förvärv av Swedish Bra Holding AB, Miss Mary of Sweden. Miss Mary är verksamt med design, tillverkning och försäljning av damunderkläder med ca 90 procent av omsättningen inom e-handel. Enterstore är en e-handelskoncern bestående av portföljbolag med ledande varumärken inom nischbranscher.","body":"Vinges team utgörs huvudsakligen av Anders Strid, Petronella Hallberg (projektledare), Amelia Rihs (M&A), Anna Palmérus (konkurrensrätt), Anders Leissner (sanktioner och försäkring), Michaela Örtberg (GDPR och IT), Aleksandar Bajic (kommersiella avtal), Sofia Haggren (finansiering) och Amanda Stoltz (projektassistens och VDR). Walless OÛ har biträtt med legal rådgivning avseende estnisk rätt.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-enterstore-i-samband-med-forvarvet-av-miss-mary-of-sweden/","date":"2024-12-16","month":12},{"year":2024,"client":"Abliva","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Abliva i budet från Pharming","caption":"Övrigt · 16 december 2024","preamble":"Pharming Technologies B.V., ett helägt dotterbolag till Pharming Group N.V., har lämnat ett uppköpserbjudande till aktieägarna i Abliva AB (publ). Erbjudandet värderar samtliga aktier i Abliva till cirka 725 miljoner kronor.","body":"Vinges team består av Christian Lindhé, Erik Sjöman, Martin Madsen Svanberg och Agaton Lindgren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-abliva-i-budet-fran-pharming/","date":"2024-12-16","month":12},{"year":2024,"client":"Umia Sweden och övriga ägare","work":"Avyttring","disciplines":["M&A","FDI","EU‑ och konkurrensrätt","Tvistlösning","Corporate Commercial","Arbetsrätt"],"title":"Vinge företräder Umia Sweden och övriga ägare vid försäljningen av Umia Stockholm till Sandbäckens","caption":"Avyttring · 11 december 2024","preamble":"Umia Stockholm AB grundades 2016 av Jonas Hedlund, Rolf Danielsson, Ronnie Ketola och Göran Karlsson och har idag cirka 60 anställda samt omsätter 190 miljoner kronor (2023). Bolaget är specialiserat på el, som står för 70 % av verksamheten, och ventilation. Som en del av förvärvet kommer Umia Stockholm AB att integreras i Sandbäckens varumärke inom snar framtid.","body":"Vinges team bestod huvudsakligen av Johan Larsson, Per Kling, Philip Moré och Niklas Suni (M&A), Daniel Wendelsson (FDI), Sebastian Örndahl (EU- och konkurrensrätt), Malin Olsson (Tvistlösning), Martin Boström (Corporate Commercial), Agnes Pigg (Arbetsrätt) samt Emy Rydén (Transaction Support Senior Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-umia-sweden-och-ovriga-agare-vid-forsaljningen-av-umia-stockholm-till-sandbackens/","date":"2024-12-11","month":12},{"year":2024,"client":"Pricer","work":"Obligationsemission","disciplines":["Bank och finans","M&A","Kapitalmarknad och publik M&A"],"title":"Vinge biträder Pricer AB vid emission av seniora icke-säkerställda obligationer och förtida inlösen","caption":"Obligationsemission · 10 december 2024","preamble":"Vinge biträder Pricer AB (publ) vid dess emission av seniora icke-säkerställda obligationer med rörlig ränta om SEK 300 miljoner inom en ram om SEK 500 miljoner och förtida inlösen av existerande obligationer.","body":"Emissionslikviden ska användas för att refinansiera Pricers existerande obligationer om SEK 250 miljoner och för att finansiera allmänna företagsändamål, och obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms företagsobligationslista. Obligationerna har en löptid om tre år och emitterades med en ränta om STIBOR 3m + 400 baspunkter. I samband med emissionen utnyttjade Pricer sin rätt till förtida inlösen av sina existerande obligationer.\n\nNordea Bank Abp agerade sole bookrunner i transaktionen.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda, Calle Tengwall Pagels, William Carlberg Johansson, Nilufer Nouri (Bank och Finans), Dain Hård Nevonen och Benjamin Vafaeian (Kapitalmarknad och publik M&A).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-pricer-ab-publ-vid-emission-av-seniora-icke-sakerstallda-obligationer-och-fortida-inlosen/","date":"2024-12-10","month":12},{"year":2024,"client":"Boliden","work":"Förvärv","disciplines":["M&A","Miljörätt","Fastigheter och Entreprenad","Arbetsrätt","Kommersiella avtal"],"title":"Vinge har biträtt Boliden vid förvärv av gruvorna Neves-Corvo och Zinkgruvan från Lundin Mining","caption":"Förvärv · 10 december 2024","preamble":"Boliden har ingått ett slutgiltigt avtal med Lundin Mining om att förvärva Neves-Corvo-gruvan i Portugal och Zinkgruvan i Sverige. Köpeskillingen som ska erläggas kontant för enheterna uppgår till 1 300 MUSD plus villkorade tilläggsköpeskillingar som kan uppgå till 150 MUSD, på en kassa- och skuldfri basis. Transaktionen, som avsevärt stärker Bolidens gruvproduktion samt interna försörjning av zink- och kopparkoncentrat, är föremål för sedvanliga godkännanden, inklusive myndighetsgodkännanden.","body":"Vinges M&A-team leddes av Ulrich Ziche och bestod av Maria Dahlin Kolvik, Egil Svensson och Helena Liljenberg (M&A), Johan Cederblad (Miljö), Niclas Winnberg (Fastigheter), Emil Lindwall och Louisa Fagarasan (Arbetsrätt), Victor Ericsson (Skatt), Mario Saad (Kommersiella Avtal) och Johanna Engström (Transaktionsstöd), medan Aktiemarknadsteamet leddes av Jesper Schönbeck och bestod av Amanda Knutsson, Joel Wahlberg, Joel Magnusson och Adrian Filipovic.\n\nFör detaljer om transaktionen hänvisas till Bolidens pressmeddelande, läs mer här.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-boliden-vid-forvarv-av-gruvorna-neves-corvo-och-zinkgruvan-fran-lundin-mining/","date":"2024-12-10","month":12},{"year":2024,"client":"Carasent","work":"Börsnotering","disciplines":["M&A"],"title":"Vinge företräder Carasent i samband med notering på Nasdaq Stockholm","caption":"Börsnotering · 9 december 2024","preamble":"Vinge företräder Carasent AB (publ) i samband med noteringen på Nasdaq Stockholm. Noteringen genomförs genom en omvänd gränsöverskridande fusion, varvid Carasent AB övertar Carasent ASA, tidigare noterat på Oslo Börs.","body":"Vinges team består av Christian Lindhé, Erik Sjöman, Agaton Lindgren, Jasmine Elgh och Nathalie Wikman.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-carasent-i-samband-med-notering-pa-nasdaq-stockholm/","date":"2024-12-09","month":12},{"year":2024,"client":"Apotea","work":"Börsnotering","disciplines":["Kapitalmarknad och publik M&A","Företagsbeskattning","Arbetsrätt","IT, Telekom och Outsourcing","Immaterialrätt","Bank och finans"],"title":"Vinge har företrätt Apotea i samband med dess notering på Nasdaq Stockholm","caption":"Börsnotering · 6 december 2024","preamble":"Vinge har företrätt Apotea AB (publ) (”Apotea”) i samband med dess notering på Nasdaq Stockholm. Prospektet offentliggjordes den 26 november 2024 och första handelsdag är den 6 december 2024.","body":"Priset i erbjudandet var 58 kronor per stamaktie, motsvarande ett totalt marknadsvärde för samtliga stamaktier i Apotea om cirka 6 miljarder kronor. Det totala värdet av erbjudandet uppgår till cirka 1 880 miljoner kronor under antagandet att övertilldelningsoptionen utnyttjas till fullo.\n\nApotea är Sveriges ledande nätapotek baserat på marknadsandel med målet att bli det största apoteket i Sverige och därmed även i Norden. Med marknadens bredaste sortiment, låga priser och snabba leveranser underlättar bolaget vardagen för sina tre miljoner aktiva kunder.\n\nVinges team bestod huvudsakligen av Jesper Schönbeck, Amanda Knutsson, Anna Svensson, Lorin Arabi, Karin Karsten och Elias Kröger (Kapitalmarknad och publik M&A), Victor Ericsson, Emelie Svanberg, Ellenor Eckerborn och Marcus Svärd (Företagsbeskattning), Sam Seddigh och Emil Lindwall (Arbetsrätt), Helena Rosén Andersson och Hilda Ivarsson (Tillstånd), Fredrika Hjelmberg, Mario Saad och Siri Blomberg (Kommersiella avtal, IT och GDPR), Ian Jonson (Immaterialrätt) och Sofia Haggren (Finansiering).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-apotea-i-samband-med-dess-notering-pa-nasdaq-stockholm/","date":"2024-12-06","month":12},{"year":2024,"client":"Dafo Vehicle","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljningen av Dafo Vehicle","caption":"Avyttring · 5 december 2024","preamble":"Vinge har biträtt Sobro och övriga ägare vid försäljningen av Dafo Vehicle till amerikanska United Safety & Survivability Corporation. Dafo Vehicle är en ledande leverantör av branddetekterings- och släcksystem för fordon och genom förvärvet skapas en global ledare inom fordonssäkerhetssystem.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Manon De Cooman, Eléonore Friberg, Philip Moré och Saga Meyer Viklund (M&A), Johan Cederblad (Miljö), Jolene Reimerson och Jacob Eberil (Kommersiella avtal), Ian Jonson (Immaterialrätt), Jessica Öijer, Johanna Engström och Christoffer Widström (Transaktionssupport).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljningen-av-dafo-vehicle/","date":"2024-12-05","month":12},{"year":2024,"client":"Platzer","work":"Förvärv","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge biträdde Platzer vid förvärvet av kontorsfastighet i Mölndal","caption":"Förvärv · 5 december 2024","preamble":"Vinge biträdde Platzer vid förvärvet av fastigheten MIMO i Mölndal med en total bruttoarea om cirka 40 000 kvm. Säljare är NCC AB och tillträde sker den 18 december 2024.","body":"Vinges team bestod av Olof Jisland och Kristoffer Larson.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-platzer-vid-forvarvet-av-kontorsfastighet-i-molndal/","date":"2024-12-05","month":12},{"year":2024,"client":"Babcock & Wilcox","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt Babcock & Wilcox i samband med försäljningen av dess italienska och svenska verksamheter","caption":"Avyttring · 4 december 2024","preamble":"Vinge har tillsammans med bland andra Dentons biträtt Babcock & Wilcox Enterprises, Inc. (NYSE: BW), en USA-baserad leverantör av energi- och miljörelaterade produkter och tjänster, vid försäljningen av dess italienska dotterbolagsgrupp SPIG S.p.A. och dess svenska dotterbolag Babcock & Wilcox Vølund AB (tid. Götaverken Miljö AB) till AUCTUS Capital Partners AG, en tysk-italiensk Private Equity firma.","body":"Vinges team bestod huvudsakligen av Kristian Ford, Niklas Törnell, Sofie Nordgren (FDI) och Lisa Bourghardt (IP).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-babcock-wilcox-i-samband-med-forsaljningen-av-dess-italienska-och-svenska-verksamheter/","date":"2024-12-04","month":12},{"year":2024,"client":"Xspray Pharma","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Xspray Pharma i samband med dess företrädesemission","caption":"Kapitalanskaffning · 3 december 2024","preamble":"Vinge har företrätt Xspray Pharma AB (publ) i samband med en företrädesemission av aktier varigenom Xspray tillförs cirka 135 miljoner kronor före avdrag för emissionskostnader.","body":"Xspray är ett läkemedelsföretag som specialiserar sig på att använda sin patenterade HyNap-teknologi för att utveckla förbättrade versioner av befintliga protein-kinashämmare (PKI:er) för cancerbehandling. Företagets mål är att bli en ledande aktör inom utveckling av förbättrade PKI:er för cancerbehandling. Xsprays aktier är noterade på Nasdaq Stockholm.\n\nVinges team har huvudsakligen bestått av Dain Hård Nevonen, Joel Magnusson, Adrian Filipovic och Elias Kröger.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-xspray-pharma-i-samband-med-dess-foretradesemission/","date":"2024-12-03","month":12},{"year":2024,"client":"Eleda","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad","Kommersiella avtal","GDPR","Bank och finans","Arbetsrätt","Corporate Crime & Compliance","FDI"],"title":"Vinge har företrätt Eleda i samband med förvärven av Marbit Aktiebolag, FlexiRail AB och Hanell Entreprenad i Gävle AB","caption":"Förvärv · 2 december 2024","preamble":"Vinge har företrätt den ledande infrastrukturkoncernen Eleda i samband med förvärven av Marbit Aktiebolag, FlexiRail AB och Hanell Entreprenad i Gävle AB från Vestum. Bolagen bedriver entreprenadverksamhet inom anläggning. Den totala köpeskillingen för aktierna uppgår till 747 MSEK. Samtliga ledande befattningshavare i bolagen blir delägare i Eleda.","body":"Hanell Entreprenad i Gävle AB och FlexiRail AB har båda lång erfarenhet av underhåll inom järnväg och Eleda stärker också sin ledande position inom markanläggning i Stockholm genom förvärvet av Marbit Aktiebolag.\n\nTransaktionen är villkorad av regulatoriska godkännanden och tillträde förväntas ske under första kvartalet 2025.\n\nVinges team bestod huvudsakligen av Christina Kokko, Johanna Wiberg, Eléonore Friberg, Madelene Andersson och Chris Bastholm (M&A), Niclas Lindblom (Entreprenad), Sara Franson (Fastighet), Hanna Kövamees (Kommersiella avtal), Siri Bromberg (GDPR), Calle Tengwall Pagels och William Carlberg Johansson (Bank och finans), Simon Söderholm och Jessica Jacob (Arbetsrätt), Hayaat Ibrahim och Gulestan Ali (Compliance), Marcus Glader, Daniel Wendelsson, Dagne Sabockis, Lovisa Lewin och Lovisa Arpi (Konkurrensrätt och FDI) och Jasmina Skandrani (Projektassistent).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-i-samband-med-forvarven-av-marbit-aktiebolag-flexirail-ab-och-hanell-entreprenad-i-gavle-ab/","date":"2024-12-02","month":12},{"year":2024,"client":"Fortum","work":"Avyttring","disciplines":["Miljörätt","M&A","Corporate Commercial","Arbetsrätt","Bank och finans","Fastigheter och Entreprenad","Regulatoriska tvister"],"title":"Vinge har biträtt Fortum i samband med försäljningen av återvinnings- och avfallsverksamheten","caption":"Avyttring · 2 december 2024","preamble":"Vinge har tillsammans med bland andra Castrén & Snellman biträtt Fortum i samband med försäljningen av dess återvinnings- och avfallsverksamhet till Summa Equity genom dess portföljbolag NG Group. Köpeskillingen uppgår till cirka 800 miljoner euro på skuldfri basis.","body":"Återvinnings- och avfallsverksamheten som är föremål för försäljning inbegriper kommunal och industriell avfallsbehandling samt återvinningstjänster för hantering och återvinning av plast, metaller, aska, slagg och farligt avfall. Verksamheterna finns i Finland, Sverige, Danmark och Norge och har för närvarande cirka 900 medarbetare.\n\nVinges team bestod huvudsakligen av Peter Sundgren och Gustav Wahlberg (M&A), Johan Cederblad och Lina Österberg (Miljö), Martin Boström och Elis Allmark (Corporate Commercial), Sam Seddigh och Agnes Pigg (Arbetsrätt), Linn Adelwald och Karl-Gustaw Tobola (Bank & Finans), Frida Ställborn (Fastighet) samt Daniel Wendelsson, David Olander, Dagne Sabockis och Lovisa Lewin (Regulatory)","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-fortum-i-samband-med-forsaljningen-av-atervinnings-och-avfallsverksamheten/","date":"2024-12-02","month":12},{"year":2024,"client":"Active Biotech","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Active Biotech i samband med företrädesemission","caption":"Kapitalanskaffning · 29 november 2024","preamble":"Vinge företräder Active Biotech AB (publ) i samband med en företrädesemission om cirka 43 miljoner kronor.","body":"Vinges team består av Christian Lindhé, Erik Sjöman, Agaton Lindgren och Jasmine Elgh.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-active-biotech-i-samband-med-foretradesemission/","date":"2024-11-29","month":11},{"year":2024,"client":"ABGSC och SEB","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder ABGSC och SEB i samband med Europis första emission av gröna obligationer","caption":"Obligationsemission · 29 november 2024","preamble":"Vinge biträder arrangörerna i samband med Europi Property Group AB (publ):s (”Bolaget”) första emission av seniora icke-säkerställda gröna obligationer om 50 miljoner euro inom ett ramverk om upp till 100 miljoner euro.","body":"Obligationerna löper med en rörlig ränta om EURIBOR 3M + 5,00% och har en löptid på tre år. Bolaget avser att ansöka om upptagande till handel av obligationerna på Nasdaq Transfer Market och Nasdaq Stockholms lista för gröna och hållbara obligationer. ABG Sundal Collier AB och Skandinaviska Enskilda Banken AB (publ) har agerat Joint Bookrunners.\n\nVinges team bestod av Albert Wållgren, Arvid Weimers och August Ahlin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-abgsc-och-seb-i-samband-med-europis-forsta-emission-av-grona-obligationer/","date":"2024-11-29","month":11},{"year":2024,"client":"Rieber & Søn","work":"Förvärv","disciplines":[],"title":"Vinge företräder Rieber & Søn i samband med dess förvärv av Accept Försäkringsaktiebolag (publ)","caption":"Förvärv · 21 november 2024","preamble":"Accept, med huvudkontor i Stockholm, har varit en innovatör på den svenska försäkringsmarknaden sedan starten 1998. Bolaget var först med att erbjuda inkomstbortfallsförsäkring och har sedan dess erbjudit produkter som kompletterar det allmänna försäkringsutbudet. Idag levererar Accept webbaserade försäkringslösningar anpassade för dess erbjudande.","body":"Vinges team bestod huvudsakligen av Jonas Bergström, Kristoffer Larsson och Gustav Wahlberg.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-rieber-son-i-samband-med-dess-forvarv-av-accept-forsakringsaktiebolag-publ/","date":"2024-11-21","month":11},{"year":2024,"client":"Symrise","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","FDI"],"title":"Vinge biträder Symrise i budet på Probi","caption":"Övrigt · 20 november 2024","preamble":"Symrise AG har lämnat ett kontanterbjudande till aktieägarna i Probi AB (publ) (”Probi”). Erbjudandet värderar Probi till cirka 3 988 miljoner kronor. Aktierna i Probi är upptagna till handel på Nasdaq Stockholm, Mid Cap.","body":"Probi är ett globalt företag inom biotiska lösningar med fokus på forskning, tillverkning och leverans av biotika för kosttillskott och funktionella livsmedel.\n\nVinges team består huvudsakligen av Jesper Schönbeck, Erik Sjöman, Linnéa Sellström, Benjamin Vafaeian och Hannah Mark (Kapitalmarknad och publik M&A) samt Daniel Wendelsson och Noelia Martinez (FDI).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-symrise-i-budet-pa-probi/","date":"2024-11-20","month":11},{"year":2024,"client":"Oxx","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder Oxx vid investering i Kodiak Hub","caption":"Kapitalanskaffning · 20 november 2024","preamble":"Kodiak Hub, ett svenskt SaaS-bolag som erbjuder inköpare en AI-baserad mjukvaruplattform, har genomfört en kapitalanskaffning om 6 miljoner euro. VC-fonden Oxx, som investerar i SaaS-bolag, är största investerare.","body":"Vinge, genom Johan Winnerblad, Michella Lina Said, Arvid Axelryd och Martin Boström, har biträtt Oxx.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-oxx-vid-investering-i-kodiak-hub/","date":"2024-11-20","month":11},{"year":2024,"client":"HAKI Safety","work":"Förvärv","disciplines":["M&A","Immaterialrätt","Arbetsrätt"],"title":"Vinge företräder HAKI Safety AB (publ) i samband med förvärvet av Semmco Group Limited","caption":"Förvärv · 19 november 2024","preamble":"Semmco Group är en brittisk marknadsledande tillverkare och leverantör av underhållsplattformar och trappor till flygplan och tåg.","body":"Semmco Group utvecklar och tillverkar produkter som möjliggör säkert och effektivt underhåll av flygplan, helikoptrar och tåg. I sortimentet ingår bland annat specialutvecklade arbetsplattformar, trappor och dockningssystem. Kunderna är i huvudsak internationella flyg- och tågbolag. Semmcos huvudkontor och huvudsakliga tillverkning finns i Woking, Surrey, England. Tillverkning och försäljning sker också i Arlington, Texas, USA. Marknaderna i Mellanöstern och Asien bearbetas via ett säljkontor i Dubai, Förenade Arabemiraten.\n\nVinges team bestod av Anna Edström, Niklas Törnell, Johan Severinsson (M&A) samt Lisa Bourghardt (IP) och Karin Hultgren (arbetsrätt/persondata).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-haki-safety-ab-publ-i-samband-med-forvarvet-av-semmco-group-limited/","date":"2024-11-19","month":11},{"year":2024,"client":"Impilo","work":"Övrigt","disciplines":[],"title":"Vinge biträder Impilo vid etableringen av en continuation fund","caption":"Övrigt · 15 november 2024","preamble":"Vinge har biträtt Impilo med regulatorisk rådgivning vid etableringen av Impilo Orphan Drugs, en s.k. continuation fund. Fonden kommer att ha kapitalåtaganden om 320 miljoner euro och investera i Immedica där KKR nyligen har gått in som ägare vid sidan av Impilo.","body":"Impilo är ett nordiskt investmentbolag som specialiserar sig på investeringar i företag inom läkemedel, medicinteknik, sjukvårdstjänster och andra hälsorelaterade sektorer. Impilo har en väldiversifierad portfölj av investeringar inom hälso- och sjukvårdssektorn, och förvaltar cirka 1 miljard euro i kapital från ledande nordiska och internationella investerare.\n\nVinges team bestod av Nils Unckel, Anton Sjökvist och Viktoria Wnuk.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-impilo-vid-etableringen-av-en-continuation-fund/","date":"2024-11-15","month":11},{"year":2024,"client":"Österlens Kraft ekonomisk förening","work":"Avyttring","disciplines":[],"title":"Vinge företräder Österlens Kraft ekonomisk förening vid försäljningen av samtliga aktier i Österlens Kraft Fjärrvärme AB till Adven Sverige AB","caption":"Avyttring · 14 november 2024","preamble":"Österlens Kraft Fjärrvärme AB producerar, distribuerar och säljer fjärrvärme till bolagets kunder i Simrishamn.","body":"Vinges team bestod huvudsakligen av Peter Abrahamsson och Annika Tingström (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-osterlens-kraft-ekonomisk-forening-vid-forsaljningen-av-samtliga-aktier-i-osterlens-kraft-fjarrvarme-ab-till-adven-sverige-ab/","date":"2024-11-14","month":11},{"year":2024,"client":"Abacus Bidco Oy (som är moderbolag till Accountor Software","work":"Förvärv","disciplines":["M&A","Kapitalmarknad och publik M&A","Carve-Outs"],"title":"Vinge företräder Abacus Bidco Oy (som är moderbolag till Accountor Software som förvärvades av KKR tidigare i år) vid förvärv av vissa dotterbolag samt tillgångar av 24SevenOffice Group AB (”24SevenOffice”)","caption":"Förvärv · 13 november 2024","preamble":"24SevenOffice är ett noterat bolag (First North Stockholm) som tillhandahåller moduluppbyggd programvara för redovisning, ERP och affärstjänster som automatiserar processer med hjälp av AI.","body":"Transaktionen avser främst ERP-relaterade dotterbolag och tillgångar, inklusive bland annat 24SevenOffice Norway AS, 24SevenOffice Scandinavian Systems och 24SevenOffice Sweden AB. Efter transaktionens slutförande kommer förvärvade tillgångar och dotterbolag att integreras med Accountor Software.\n\nKöpeskillingen för de ERP-relaterade dotterbolagen och tillgångarna motsvarar ett företagsvärde om cirka 2,4 miljarder kronor.\n\nTransaktionen är villkorad av godkännande från aktieägarna i 24SevenOffice samt regulatoriskt godkännande.\n\nVinges team bestod huvudsakligen av Christina Kokko, Matthias Pannier, Gustav Persson och Ian Linde (M&A), Sofie Bjärtun och Joel Magnusson (Kapitalmarknad och Publik M&A), Johan Gavelin (IP), Alice Göransson (Arbetsrätt), Madelene Andersson (Fastighet), Daniel Wendelsson (FDI), Christoffer Nordin och Katja Häglund (Kommersiella avtal), Nicklas Thorgerzon (IT och GDPR), Calle Tengwall Pagels och William Carlberg Johansson (Bank och Finans), Caroline Krassén (Financial Services), Caroline Löv och Filippa Bergkvist (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-abacus-bidco-oy-som-ar-moderbolag-till-accountor-software-som-forvarvades-av-kkr-tidigare-i-ar-vid-forvarv-av-vissa-dotterbolag-samt-tillgangar-av-24sevenoffice-group-ab-24sevenoffice/","date":"2024-11-13","month":11},{"year":2024,"client":"Cantargia","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Cantargia i samband med företrädesemission","caption":"Kapitalanskaffning · 13 november 2024","preamble":"Vinge företräder Cantargia AB (publ) i samband med en företrädesemission om cirka 170 miljoner kronor.","body":"Vinges team består av Christian Lindhé, Erik Sjöman, Martin Madsen Svanberg, Johan Åhman och Nathalie Wikman.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-cantargia-i-samband-med-foretradesemission-1/","date":"2024-11-13","month":11},{"year":2024,"client":"Axcel och Accru Partners","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Bank och finans","Kommersiella avtal","Immaterialrätt","Fastigheter och Entreprenad","GDPR","Corporate Crime & Compliance"],"title":"Vinge företräder Axcel och Accru Partners vid förvärven av Ekonomernas Hus, Revisorernas Hus, RevisionsPartner och Censio","caption":"Förvärv · 12 november 2024","preamble":"Vinge har företrätt Axcel VII och Accru Partners i samband med de parallella förvärven av Ekonomernas hus i Sverige AB, Ekonomernas Hus Örebro AB, Revisorernas Hus Sverige AB, RevisionsPartner Skaraborg AB och Censio Tax AB.","body":"Samtliga byråer är entreprenörsledda, lokala företag med expertis inom redovisning, skatt, revision och rådgivningstjänster. Efter förvärven består Accru Partners av totalt 26 självständiga byråer inom nämnda verksamhetsområden.\n\nVinges team bestod av Christina Kokko, Desirée Hagenfeldt, Egil Svensson, Michella Lina Said, Madelene Andersson och Alexander Rüdén (M&A), Simon Söderholm och Narin Melazade (Arbetsrätt), Kamyar Najmi och Sofia Haggren (Bank och finans), Mario Saad (Kommersiella avtal), Elis Allmark (IT), Rebecka Målquist (Immaterialrätt), Nicklas Thorgerzon (GDPR), Agnes Pigg och Hanna Kövamees (Fastighet), Jonna Bondemark och David Gavatin (Regulatoriska frågor), Mia Falk och Gulestan Ali (Regelefterlevnad) samt Jessica Öijer (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-accru-partners-vid-forvarven-av-ekonomernas-hus-revisorernas-hus-revisionspartner-och-censio/","date":"2024-11-12","month":11},{"year":2024,"client":"Retune Group","work":"Avyttring","disciplines":[],"title":"Vinge biträder vid försäljningen av Retune Group till Co-native","caption":"Avyttring · 12 november 2024","preamble":"Sobro och övriga aktieägare i Retune Group har träffat avtal om sälja bolaget till Co-native.","body":"Retune Group är ett Stockholmsbaserat molnspecialistföretag inom Microsoft 365 och moderna, säkra IT-arbetsplatser, med 45 anställda och en omsättning på över 100 miljoner kronor. Sobro och vissa nyckelpersoner återinvesterar samtidigt i Co-native.\n\nVinges team bestod bl.a. av Johan Winnerblad, Chris Bastholm och Lovisa Arpi.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljningen-av-retune-group-till-co-native/","date":"2024-11-12","month":11},{"year":2024,"client":"Our Legacy och grundarna","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Our Legacy och grundarna vid försäljningen av en minoritetsandel i Our Legacy till LVMH","caption":"Kapitalanskaffning · 8 november 2024","preamble":"Vinge har företrätt Our Legacy och grundarna i samband med försäljningen av en minoritetsandel i Our Legacy till LVMH genom dess investeringsfond LVMH Luxury Ventures.","body":"Our Legacy är ett svenskt modevarumärke baserat i Stockholm, Sverige och grundat 2005. Bolaget har en omsättning på cirka 400 miljoner kronor med sina största marknader i Sydkorea, USA, England, Japan och Italien. Investeringen i Our Legacy är LVMH:s första investering i ett svenskt modevarumärke på 25 år.\n\nVinges team bestod av Jonas Bergström, Samra Tesser, Egil Svensson och Michella Lina Said (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-our-legacy-och-grundarna-vid-forsaljningen-av-en-minoritetsandel-i-our-legacy-till-lvmh/","date":"2024-11-08","month":11},{"year":2024,"client":"Intera Partners","work":"Förvärv","disciplines":["M&A","Corporate Commercial","Arbetsrätt","Immaterialrätt","Bank och finans"],"title":"Vinge företräder Intera Partners i samband med förvärvet av Halon Security","caption":"Förvärv · 5 november 2024","preamble":"Vinge har företrätt Intera Equity Partners IV Oy (”Intera Partners”) vid förvärvet av Halon Security AB (”Halon”).","body":"Halon är en global ledare inom mjukvara för e-postinfrastruktur baserad i Sverige med kunder i över 30 länder och en omsättning på cirka 49 miljoner kronor.\n\nHalon är en betrodd partner för verksamhetskritiska e-posttjänster och tjänsteleverantörer och företag som kräver hög säkerhet, skalbarhet och hantering av stora volymer e-post förlitar sig på Halons programvara. Intera Partners investering kommer att bidra till Halons fortsatta marknadsexpansion och utveckling av lösningar som möter kunders skiftande behov och föränderliga affärs, teknik och säkerhetskrav.\n\nVinges team bestod av bland andra Jonas Bergström, Carl Sander, Eléonore Friberg, Klara Fäldt och Emma Lundberg (M&A), Helena Göransson, Karl-Gustaw Tobola och Matilda Hamner (Bank och Finans), Jolene Reimerson och Carla Håkansson (Corporate Commercial & IT), Victor Björkheim (Arbetsrätt), Emma Gustavsson (IP) och Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-intera-partners-i-samband-med-forvarvet-av-halon-security/","date":"2024-11-05","month":11},{"year":2024,"client":"EQT X","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","M&A","Bank och finans","Kommersiella avtal","Arbetsrätt","Fastigheter och Entreprenad","Immaterialrätt"],"title":"Vinge biträder EQT X i budet på OEM International","caption":"Övrigt · 5 november 2024","preamble":"EQT X, genom dess indirekt ägda dotterbolag Oak BidCo S.à r.l., har säkrat ett ägande om 72,5% av rösterna i OEM International Aktiebolag (publ) och har lämnat ett kontanterbjudande till samtliga aktieägare. Aktierna i OEM International är upptagna till handel på Nasdaq Stockholm, Mid Cap. Erbjudandets värde uppgår till cirka 15,2 miljarder kronor.","body":"OEM International är ett av Europas ledande teknikhandelsföretag och består av 34 rörelsedrivande enheter i 15 länder. Koncernen verkar inom handel med komponenter och system från ledande leverantörer på utvalda marknader i Europa. Genom en väl utvecklad lokal marknadsorganisation och effektiv logistik utgör OEM ett bättre alternativ än att leverantörerna etablerar egna säljbolag.\n\nVinges team består huvudsakligen av Sofie Bjärtun, Erik Sjöman, Joel Magnusson, Maximilian Bengtsson och Lovisa Jonassen (Kapitalmarknad och publik M&A), Christina Kokko och Eléonore Friberg (M&A), Sebastian Örndahl, Noelia Martinez, Julia Rydin och Martin Hammarskiöld (Regulatory), Josefine Lanker (Bank och finans), Christoffer Nordin och Elis Allmark (Kommersiella avtal), Niclas Winnberg (Fastighet), Ebba Svenburg (Arbetsrätt), Arvid Axelryd (Immaterialrätt), Eva Fredriksson (IT), Hayaat Ibrahim (Compliance), Nicklas Thorgerzon (GDPR) och Julia Ulander Kull (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-eqt-x-i-budet-pa-oem-international/","date":"2024-11-05","month":11},{"year":2024,"client":"Readily Diagnostics","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder Readily Diagnostics vid kapitalanskaffning","caption":"Kapitalanskaffning · 30 oktober 2024","preamble":"Readily Diagnostics, ett Uppsalabaserat bolag som specialiserar sig på att utveckla snabba och noggranna diagnostiska tester, har genomfört en kapitalanskaffning om 1,6 miljoner euro.","body":"Bl.a. Beijerstiftelsen och Länsförsäkringar Uppsala har tillkommit som nya aktieägare och flera befintliga aktieägare såsom Almi Invest, Ulf Landegren och Uppsala Universitet Invest har också deltagit.\n\nVinge, genom Johan Winnerblad, har biträtt Readily.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-readily-diagnostics-vid-kapitalanskaffning/","date":"2024-10-30","month":10},{"year":2024,"client":"Spring Media","work":"Avyttring","disciplines":["M&A","Företagsbeskattning"],"title":"Vinge biträder vid försäljningen av Spring Media till Two Circles","caption":"Avyttring · 28 oktober 2024","preamble":"Aktieägarna i Spring Media har ingått avtal om att sälja aktierna i Spring Media till Two Circles. Spring Media är en internationell sportagentur verksamma med bland annat produktion, paketering, digitala strategier och rättighetsförhandling inom området för sporträttigheter.","body":"Slutförandet av transaktionen är föremål för sedvanliga tillträdesvillkor.\n\nVinge, genom Johan Winnerblad, Manon De Cooman och Ida Appelgren (M&A), Maria Schultzberg och Victor Ericsson (Skatt), och Fanny Askelöf, Christoffer Widström, Carl Bruneheim (Transaktionssupport), har biträtt säljarna.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljningen-av-spring-media-till-two-circles/","date":"2024-10-28","month":10},{"year":2024,"client":"Stendörren Fastigheter","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har biträtt Stendörren Fastigheter i samband med en riktad nyemission om cirka 505 miljoner kronor","caption":"Kapitalanskaffning · 25 oktober 2024","preamble":"Vinge har biträtt fastighetsbolaget Stendörren Fastigheter AB (publ) i samband med en riktad nyemission varigenom bolaget tillförs cirka 505 miljoner kronor före transaktionskostnader.","body":"Bolaget avser att använda emissionslikviden för att finansiera tillväxt och för att kapitalisera på investeringsmöjligheter inom lager, logistik och lätt industri genom fastighetsförvärv och investeringar i projektutveckling. Stendörren Fastigheters aktie är noterad på Nasdaq Stockholm Mid Cap.\n\nVinges team bestod av Jesper Schönbeck, David Andersson, Joel Magnusson, Adrian Filipovic och Louise Nässén.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-stendorren-fastigheter-i-samband-med-en-riktad-nyemission-om-cirka-505-miljoner-kronor/","date":"2024-10-25","month":10},{"year":2024,"client":"Main Capital och Aunetic","work":"Förvärv","disciplines":["Arbetsrätt","M&A","GDPR","Immaterialrätt","Kommersiella avtal"],"title":"Vinge företräder Main Capital och Aunetic i samband med förvärvet av Qnister","caption":"Förvärv · 25 oktober 2024","preamble":"Vinge har företrätt Aunetic, en ledande specialist inom mjukvara för bolagsstyrning, i samband med förvärvet av Qnister AB (”Qnister”). Det strategiska förvärvet breddar Aunetics produktportfölj och stärker bolagets närvaro på den svenska marknaden.","body":"Qnister, grundat 2017, är ett SaaS-företag som specialiserar sig på mjukvarulösningar för regelefterlevnad. Qnister tillhandahåller GDPR- och visselblåsarlösningar samt tjänster inom sanktionsscreening och avtalshantering till små och medelstora företag inom den privata sektorn såväl som till kunder inom den offentliga sektorn.\n\nFörvärvet ligger i linje med Aunetics mål att utöka sitt mjukvaruerbjudande för regelefterlevnad och sin marknadsräckvidd, för att positionera Aunetic som en ledande aktör inom mjukvara för bolagsstyrning i Europa.\n\nVinges team bestod huvudsakligen av Filip Öhrner, Linus Adolfsson, Jonatan Stentorp (M&A), Emil Lindwall, Gulestan Ali (Arbetsrätt), Carla Håkansson (Avtal och GDPR), Ian Jonson (IP) och Gabriella Balbo (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-och-aunetic-i-samband-med-forvarvet-av-qnister/","date":"2024-10-25","month":10},{"year":2024,"client":"Vicore Pharma Holding","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har företrätt Vicore Pharma Holding AB (publ) i samband med dess företrädesemission","caption":"Kapitalanskaffning · 22 oktober 2024","preamble":"Vinge har företrätt Vicore Pharma Holding AB (publ) i samband med en övertecknad företrädesemission av aktier varigenom Vicore tillförs cirka 782 miljoner kronor före avdrag för emissionskostnader.","body":"De nya aktierna som emitteras i företrädesemissionen beräknas bli föremål för handel på Nasdaq Stockholm omkring den 22 oktober 2024. Vicore är ett läkemedelsbolag i klinisk fas med fokus på att utveckla en ny klass av läkemedel med sjukdomsmodifierande potential. Bolaget utvecklar en läkemedelsportfölj inom lung- och fibrotiska sjukdomar, inkluderande idiopatisk lungfibros (IPF). Bolagets aktier är noterade på Nasdaq Stockholm.\n\nVinges team bestod i huvudsak av Rikard Lindahl, Joel Magnusson, Annie Fällström och Carl Lexenberg.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-vicore-pharma-holding-ab-publ-i-samband-med-dess-foretradesemission/","date":"2024-10-22","month":10},{"year":2024,"client":"Vicore Pharma Holding","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har företrätt Vicore Pharma Holding AB (publ) i samband med dess riktade nyemission","caption":"Kapitalanskaffning · 22 oktober 2024","preamble":"Vinge har företrätt Vicore Pharma Holding AB (publ) i samband med en riktad nyemission, varigenom Vicore tillförs cirka 100 miljoner kronor före avdrag för transaktionskostnader.","body":"De deltagande investerarna var den befintliga investeraren Invus, samt en eller flera fonder under förvaltning av Capital Group, en ny investerare i Vicore.\nVicore är ett läkemedelsbolag i klinisk fas med fokus på att utveckla en ny klass av läkemedel med sjukdomsmodifierande potential. Bolaget utvecklar en läkemedelsportfölj inom lung- och fibrotiska sjukdomar, inkluderande idiopatisk lungfibros (IPF). Bolagets aktier är noterade på Nasdaq Stockholm.\n\nVinges team har bestått av Rikard Lindahl, Joel Magnusson och Annie Fällström.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-vicore-pharma-holding-ab-publ-i-samband-med-dess-riktade-nyemission/","date":"2024-10-22","month":10},{"year":2024,"client":"Svenska staten","work":"Rekonstruktion","disciplines":["EU‑ och konkurrensrätt","Rekonstruktioner och obestånd"],"title":"Vinge har biträtt svenska staten i samband med rekonstruktionsförfarandena i SAS","caption":"Rekonstruktion · 21 oktober 2024","preamble":"Vinge har biträtt svenska staten i samband med rekonstruktionsförfarandena i SAS. Förfarandena, med överväganden rörande statligt stöd som godkänts av EU-kommissionen, har bland annat inneburit omstrukturering och nedskrivning av skulder och att ett budgivarkonsortium med Castlelake, Air France-KLM, Lind Invest och danska staten har investerat totalt cirka 1,2 miljarder USD i SAS, fördelat på 475 miljoner USD i onoterade aktier och 725 miljoner USD i konvertibla skuldebrev.","body":"SAS aktier har avnoterats och svenska staten upphör att vara aktieägare i SAS i anslutning till att förfarandena har avslutats.\n\nVinges team har huvudsakligen bestått av Erik Sjöman och Amanda Knutsson (aktiemarknadsrätt), Morgan Hallén och Jenny Sandlund (insolvensrätt) samt Martin Johansson, Hedvig Josefson och Victoria Gunnerek (EU-rätt).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-svenska-staten-i-samband-med-rekonstruktionsforfarandena-i-sas/","date":"2024-10-21","month":10},{"year":2024,"client":"Elektroskandia","work":"Avyttring","disciplines":["Carve-Outs"],"title":"Vinge har företrätt Elektroskandia i samband med omstruktureringen och försäljningen av Cylinda","caption":"Avyttring · 21 oktober 2024","preamble":"Vinge har företrätt Elektroskandia AB (ett Sonepar-bolag) i samband med omstruktureringen och försäljningen av Cylinda-verksamheten till Vestel (genom dotterbolaget Vestel Holland B.V.).","body":"Cylinda är verksamt inom vitvarusektorn, har huvudkontor i Rotebro och har cirka 100 anställda.\n\nVinges team bestod av Matthias Pannier, Mathilda Persson, Desirée Hagenfeldt, Filip Magnusson, Victor Ericsson, Sebastian Örndahl och Alva Chambert.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-elektroskandia-i-samband-med-omstruktureringen-och-forsaljningen-av-cylinda/","date":"2024-10-21","month":10},{"year":2024,"client":"Sveafastigheter","work":"Börsnotering","disciplines":["Bank och finans","Kapitalmarknad och publik M&A","Fastigheter och Entreprenad"],"title":"Vinge har företrätt Sveafastigheter i samband med dess notering på Nasdaq First North Premier Growth Market","caption":"Börsnotering · 18 oktober 2024","preamble":"Vinge har företrätt Sveafastigheter AB (publ) (”Sveafastigheter”) i samband med dess notering på Nasdaq First North Premier Growth Market. Prospektet offentliggjordes den 7 oktober 2024 och första handelsdag är den 18 oktober 2024.","body":"Priset i erbjudandet var 39,50 kronor per aktie, motsvarande ett marknadsvärde på Sveafastigheter om cirka 7,9 miljarder kronor. Erbjudandet omfattar upp till 88 000 000 befintliga aktier, motsvarande ett totalt värde om cirka 3,5 miljarder kronor under antagandet att övertilldelningsoptionen utnyttjas i sin helhet.\n\nSveafastigheter är ett fastighetsbolag som äger, aktivt förvaltar och utvecklar bostadsfastigheter över hela Sverige med fokus på hyresrätter i utvalda tillväxtregioner. Fastighetsportföljen består av fastigheter i förvaltning, pågående byggnation och projektutveckling med ett totalt fastighetsvärde uppgående till cirka 27,5 miljarder kronor.\n\nVinges team bestod huvudsakligen av Jesper Schönbeck, Rikard Lindahl, Joel Magnusson, Benjamin Vafaeian, Johannes Akyol, Louise Nässén och Filip Magnusson (Kapitalmarknad och Publik M&A), Kristoffer Larson och Agnes Pigg (Fastighet), Victor Ericsson, Emelie Svanberg, Ellenor Eckerborn och Marcus Svärd (Företagsbeskattning), Mikael Ståhl, Kamyar Najmi och William Carlberg Johansson (Bank och finans).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-sveafastigheter-i-samband-med-dess-notering-pa-nasdaq-first-north-premier-growth-market/","date":"2024-10-18","month":10},{"year":2024,"client":"PEQ Invest","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad","Bank och finans","Arbetsrätt","Corporate Commercial","GDPR"],"title":"Vinge företräder PEQ Invest i samband med förvärv av Cookin Food Sweden AB (”Cookin”)","caption":"Förvärv · 15 oktober 2024","preamble":"Cookin grundades 2011 av erfarna kockar, bagare och restaurangägare och har en stark närvaro inom flyg- och detaljhandeln och erbjuder högkvalitativa färdiglagade måltider som skräddarsys efter kundernas behov.","body":"Vinges team bestod huvudsakligen av Jonas Johansson, Philip Moré och Alex Forsberg (M&A), Kristoffer Larson (Fastigheter), Arvid Weimers och August Ahlin (Bank och finans), Emil Lindwall och Agnes Källström (Arbetsrätt), Mario Saad och Ian Linde (Corporate Commercial), Jolene Reimerson och Sara Hedgren (GDPR) samt Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-peq-invest-i-samband-med-forvarv-av-cookin-food-sweden-ab-cookin/","date":"2024-10-15","month":10},{"year":2024,"client":"Mark Bric","work":"Avyttring","disciplines":["M&A"],"title":"Vinge har biträtt i samband med försäljningen av Mark Bric till Sareq","caption":"Avyttring · 15 oktober 2024","preamble":"Vinge har biträtt säljarna i samband med försäljningen av samtliga aktier i Mark Bric AB till Sareq AB. Mark Bric tillverkar och säljer högkvalitativa storleksmarkörer till den globala detaljhandeln.","body":"Vinges team har huvudsakligen utgjorts av Anders Strid, Anna Ståhlklo (projektledare), Amelia Rihs (M&A), Hannah Mark (M&A), Anders Leissner (regulatoriskt) samt Amanda Stoltz (VDR). Censor M&A har agerat finansiell rådgivare åt säljaren.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-i-samband-med-forsaljningen-av-mark-bric-till-sareq/","date":"2024-10-15","month":10},{"year":2024,"client":"Nordic Paper","work":"Offentligt uppköpserbjudande","disciplines":[],"title":"Vinge biträder Nordic Paper i samband med Strategic Value Partners offentliga uppköpserbjudande","caption":"Offentligt uppköpserbjudande · 14 oktober 2024","preamble":"Den 11 oktober 2024 offentliggjorde Strategic Value Partners, genom Coniferous Bidco AB, ett offentligt uppköpserbjudande till aktieägare i Nordic Paper Holding AB (”Nordic Paper” eller ”Bolaget”) att förvärva samtliga aktier i Nordic Paper.","body":"Nordic Paper är en ledande specialpappersproducent med basen i Skandinavien, som har levererat högkvalitativa kraftpapper och naturligt fettresistenta livsmedelspapper sedan 1800-talet. Aktien är noterad på Nasdaq Stockholm. Det totala värdet av erbjudandet uppgår till cirka 3 345 miljoner kronor, baserat på det totala antalet aktier i Nordic Paper. Erbjudandet föregicks av en process som styrelsen i Nordic Paper initierade för att undersöka det potentiella intresset från tredje parter att förvärva samtliga aktier i Bolaget, mot bakgrund av att Bolagets nuvarande huvudägare, Shanying International Holding Co., Ltd, hade offentliggjort sin avsikt att sälja hela eller en del av sitt innehav i Nordic Paper. Vinge biträder Nordic Paper.\n\nVinges team har huvudsakligen bestått av David Andersson, Erik Sjöman, Anna Svensson och Michaela Ådén (Kapitalmarknad och publik M&A), Albert Wållgren och Kamyar Najmi (Bank och finans), Sebastian Örndahl och Martin Hammarskiöld (Konkurrensrätt), Daniel Wendelsson, Dagne Sabockis och Lovisa Lewin (FDI) samt Diana Kanold (Transaktionssupport).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-nordic-paper-i-samband-med-strategic-value-partners-offentliga-uppkopserbjudande/","date":"2024-10-14","month":10},{"year":2024,"client":"Chieftain Capital","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Chieftain Capital vid investering i Koenigsegg Automotive","caption":"Kapitalanskaffning · 8 oktober 2024","preamble":"Vinge har biträtt New York-baserade Chieftain Capital Management, Inc. (\"Chieftain\") i sin investering i svenska biltillverkaren Koenigsegg Automotive AB (\"Koenigsegg\").","body":"Investeringen, som sammanföll med Koenigseggs 30-årsjubileum, genomfördes i form av en riktad nyemission. Investeringen ska stödja nästa kapitel för Koenigsegg och ytterligare stärka företagets position som en global ledare inom segmentet för superbilar. Majoritetsägaren Christian von Koenigsegg, deltog också i emissionen genom sitt familjeföretag.\n\nVinges team bestod av Magnus Pauli, Petronella Hallberg, Jenny Sandlund, Amelia Rihs, Adam Loewenstein, Michael Montner, Fredrik Löwenclou, Hanna Jansson och Anna Högsten.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-chieftain-capital-vid-investering-i-koenigsegg-automotive/","date":"2024-10-08","month":10},{"year":2024,"client":"IBinder Group","work":"Förvärv","disciplines":["M&A","Immaterialrätt","Corporate Commercial","Arbetsrätt","Företagsbeskattning","IT, Telekom och Outsourcing"],"title":"Vinge har företrätt iBinder Group i samband med förvärvet av Avima AB","caption":"Förvärv · 7 oktober 2024","preamble":"Avima AB är en svensk specialist inom projekt- och informationshantering, med expertis inom komplexa projekt inom bygg, fastighet och infrastruktur.","body":"iBinder Group erbjuder digitala informationshanteringstjänster för bygg- och fastighetsbranschen. Företaget grundades 2005 och hjälper kunder att öka produktivitet, minska miljöpåverkan och att följa lagar och förordningar inom byggprojekt och fastighetsförvaltning.\n\nVinges team bestod huvudsakligen av Johanna Wiberg, Johanna Hamrefält (Projektledare), Johan Gavelin (IP), Elis Allmark (Commercial/IT), Emelie Svanberg och Victor Ericsson (Skatt), Jonna Skog (Arbetsrätt) och Amelia Rihs (M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-ibinder-group-i-samband-med-forvarvet-av-avima-ab/","date":"2024-10-07","month":10},{"year":2024,"client":"Axcel","work":"Övrigt","disciplines":[],"title":"Vinge företräder Axcel i samband med etableringen av Accru Partners, en ny koncern inom redovisning, skatt, revision och rådgivningstjänster","caption":"Övrigt · 4 oktober 2024","preamble":"Vinge har företrätt det nordiska riskkapitalbolaget Axcel i samband med etableringen av Accru Partners, en ny koncern beståendes av 22 självständiga byråer i Sverige som erbjuder tjänster inom redovisning, skatt, revision och andra rådgivningstjänster.","body":"Samtliga byråer i gruppen är entreprenörsledda, lokala företag med expertis inom redovisning, skatt, revision och rådgivningstjänster. Totalt sysselsätter den nya gruppen omkring 500 personer med över 30 kontor i Sverige.\n\nVinges team bestod av Christina Kokko, Desirée Hagenfeldt, Egil Svensson, Robin Fagerström, Michella Lina Said, Madelene Andersson, Niklas Suni och Alexander Rüdén (M&A), Simon Söderholm, Narin Melazade, Jonatan Stentorp och Melinda Oldenburg (Arbetsrätt), Kamyar Najmi, Ida Redander och Sofia Haggren (Bank och finans), Mario Saad, Jolene Reimerson och Carl Lexenberg (Kommersiella avtal), Mathilda Persson och Elis Allmark (IT), Rebecka Målquist (Immaterialrätt), Nicklas Thorgerzon (GDPR), Agnes Pigg och Hanna Kövamees (Fastighet), Kristoffer Sällfors (Offentlig upphandling), David Olander (EU- och konkurrensrätt), Jonna Bondemark och David Gavatin (Regulatoriska frågor), Mia Falk, Gulestan Ali och Maja Höglund (Regelefterlevnad) samt Jessica Öijer (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-i-samband-med-etableringen-av-accru-partners-en-ny-koncern-inom-redovisning-skatt-revision-och-radgivningstjanster/","date":"2024-10-04","month":10},{"year":2024,"client":"Irisity","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder Irisity vid emission av units","caption":"Kapitalanskaffning · 3 oktober 2024","preamble":"Vinge biträder Irisity AB (publ) i samband med dess företrädesemission av units bestående av aktier och teckningsoptioner. Emissionen är garanterad till 80 procent genom teckningsåtaganden och externa garanter.","body":"Vid full teckning av företrädesemissionen och aktier som kan tecknas med stöd av teckningsoptionerna kommer Irisity att tillföras cirka 83 MSEK före emissionskostnader.\n\nVinges team har huvudsakligen bestått av Anders Strid, Edin Agic (projektledare) och Sofia Haggren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-irisity-vid-emission-av-units/","date":"2024-10-03","month":10},{"year":2024,"client":"Varbergs kommun","work":"Övrigt","disciplines":[],"title":"Vinge har biträtt Varbergs kommun i samband med att detaljplan för nytt bostadsområde vunnit laga kraft","caption":"Övrigt · 3 oktober 2024","preamble":"Detaljplanen för ca 50 nya bostäder i Trönningenäs, norr om Varbergs stad, antogs av kommunen den 23 februari 2023. Den överklagades därefter i flera steg. Genom beslut från Mark- och miljööverdomstolen vann detaljplanen laga kraft den 2 oktober 2024.","body":"Bildtext: Illustration av planområdet\n\nPlanområdet är beläget i området Lindhov, på halvön Trönningenäs, ca 5 km norr om Varbergs stad. Området utgörs idag i huvudsak av jordbruksmark. Den omgivande bebyggelsen är bl.a. ett fåtal äldre gårdar. Väster om planområdet växer ett villaområde med cirka 60 bostäder fram. Detaljplanen möjliggör i sig för cirka 50 nya bostäder i form av radhus, parhus och villor. Inom planområdet möjliggörs även två grönområden.\n\nDetaljplanen överklagades till Mark- och miljödomstolen av ett större antal motparter. Invändningarna bestod bl.a. i att detaljplanen skulle innebära olovligt ianspråktagande av jordbruksmark, att den skulle leda till påtaglig skada på riksintressen och att den inte tog skälig hänsyn till befintlig bebyggelse, att dagvattenhanteringen inte var säkerställd samt att trafikförhållandena inte var tillräckligt bra. Även markinlösenfrågor aktualiserades.\n\nKommunen fick dock rätt i Mark- och miljödomstolen. Detaljplanen upphävdes således inte. Detaljplanen överklagades därefter på nytt, till Mark- och miljööverdomstolen. Mark- och miljööverdomstolen meddelade den 2 oktober 2024 att domstolen bedömer att det saknas skäl för att ta upp målet till prövning. Detaljplanen vann därmed laga kraft.\n\nVinge har varit legal rådgivare till Varbergs kommun under domstolsprocessen.\n\nVinges team bestod i huvudsak av advokat Hampus Wahlberg och biträdande jurist Sophie Romedahl.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-varbergs-kommun-i-samband-med-att-detaljplan-for-nytt-bostadsomrade-vunnit-laga-kraft/","date":"2024-10-03","month":10},{"year":2024,"client":"Egetis Therapeutics","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har företrätt Egetis Therapeutics i samband med riktade nyemissioner","caption":"Kapitalanskaffning · 3 oktober 2024","preamble":"Vinge har företrätt Egetis Therapeutics AB (publ) (”Egetis Therapeutics”), noterat på Nasdaq Stockholm, i samband med riktade nyemissioner varigenom Egetis Therapeutics tillförs 300 miljoner kronor före transaktionskostnader.","body":"Emissionerna riktades till ett antal internationella och svenska institutionella investerare på grundval av ett accelererat bookbuilding-förfarande. En av emissionerna förutsätter extra bolagsstämmas godkännande samt godkännande och offentliggörande av prospekt.\n\nVinges team bestod av Dain Hård Nevonen, Lorin Arabi och Karin Karsten.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-egetis-therapeutics-i-samband-med-riktade-nyemissioner/","date":"2024-10-03","month":10},{"year":2024,"client":"Orlando Capital V","work":"Förvärv","disciplines":["Arbetsrätt","Bank och finans","M&A"],"title":"Vinge företräder Orlando Capital V i samband med förvärvet av Swedpaper AB","caption":"Förvärv · 30 september 2024","preamble":"Vinge har agerat som legal rådgivare till Orlando Capital V i samband med förvärvet av Swedpaper AB, en ledande europeisk tillverkare av säck- och kraftpapper som används i olika förpackningslösningar för detaljhandel, livsmedel och byggindustrin. Swedpaper AB:s omsättning för räkenskapsåret 2023 uppgick till över EUR 68 miljoner.","body":"Vinges team bestod bland andra av Magnus Hedsund, Oskar Larsson och Nicolas Ek (M&A), Henrik Ossborn och Agaton Lindgren (bank och finans) samt Emelie Svensäter Jerntorp, Karin Hultgren och Sophia Reutercrona (Employment).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-orlando-capital-v-i-samband-med-forvarvet-av-swedpaper-ab/","date":"2024-09-30","month":9},{"year":2024,"client":"Global Auto Holdings Limited","work":"Förvärv","disciplines":[],"title":"Global Auto Holdings Limited förvärvar K.W. Bruuns import- och digitalverksamhet","caption":"Förvärv · 30 september 2024","preamble":"Vinge har biträtt Global Auto Holdings Limited vid förvärvet av den danska fordonskoncernen K.W. Bruuns import- och digitalverksamhet. I samarbete med Paul, Weiss, Rifkind, Wharton & Garrison LLP (lead counsel) och Bruun & Hjejle (dansk counsel) har vi biträtt Global Auto Holdings Limited, en ledande global bilåterförsäljare, vid förvärvet av K.W. Bruun Import A/S och K.W. Bruun NxT A/S inklusive förvärvsfinansieringen härav.","body":"K.W. Bruun Import har i mer än 70 år varit en av Nordens största bilimportörer och distributörer av både nya fordon och reservdelar av OEM-märken för Peugeot, Citroën, DS, Opel och Mitsubishi i Danmark och Sverige, samt Fiat, Alfa Romeo, Jeep, Hongqi och Voyah i Danmark.\n\nGlobal Auto Holdings Limited är en internationell bilkoncern som driver cirka 150 bilåterförsäljare som representerar ett brett utbud av bilmärken. Global Auto Holdings Limited driver 164 franchiseåterförsäljare som representerar mer än 40 av världens ledande bilmärken i USA, Kanada, Storbritannien och Irland.\n\nMålet med förvärvet är att Global Auto Holdings Limited ska bli en global ledare inom bilhandel och relaterade tjänster, med ett starkt fokus på digitalisering, och positionera bolaget som en framstående bilimportör i Europa.\n\nTransaktionen förväntas slutföras i december 2024, med förbehåll för myndighetsgodkännanden.\n\nVinges team bestod av Christina Kokko, Ulrich Ziche, Sara Passandideh, Ellinor Wargenbrant, Johan Cederblad, Niclas Winnberg, Kristoffer Larson, Karolina Cohrs, Jolene Reimerson, Carla Zachariasson, Gulestan Ali, Jonna Fransson, Jonna Skog, Alva Chambert, Carl Bruneheim och Julia Ulander Kull.\n\nLäs Global Auto Holdings Limiteds pressmeddelande här.","href":"https://www.vinge.se/uppdrag/global-auto-holdings-limited-forvarvar-k-w-bruuns-import-och-digitalverksamhet/","date":"2024-09-30","month":9},{"year":2024,"client":"ITAB","work":"Förvärv","disciplines":[],"title":"Vinge biträder ITAB vid förvärv av HMY","caption":"Förvärv · 26 september 2024","preamble":"ITAB Shop Concept AB (publ) har träffat avtal avsett att leda till förvärv av Financière HMY för 320 miljoner euro. Transaktionen finansieras med en ny långfristig kreditfacilitet om 255 miljoner euro samt en riktad nyemission om cirka 867 miljoner kronor genomförd genom ett accelererat bookbuildingförfarande.","body":"Vinges team består huvudsakligen av Erik Sjöman, Christian Lindhé, Jesper Ottergren, Henrik Borna, Henrik Ossborn, Martin Madsen Svanberg, Fredrik Christiansson och Johan Åhman.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-itab-vid-forvarv-av-hmy/","date":"2024-09-26","month":9},{"year":2024,"client":"Santander Consumer Finance","work":"Avyttring","disciplines":["M&A","Bank och finans","GDPR","IT, Telekom och Outsourcing","Kommersiella avtal","Immaterialrätt","Carve-Outs"],"title":"Vinge företräder Santander Consumer Finance i samband med avyttring av den svenska och norska kreditkorts- och säljfinansieringsverksamheten","caption":"Avyttring · 19 september 2024","preamble":"Vinge har biträtt Santander Consumer Bank AS i samband med försäljningen av dess svenska och norska kreditkortsverksamhet samt den säljfinansieringsverksamhet som Santander idag driver i samarbete med Elkjøp i Norge och Elgiganten i Sverige till Avida Finans AB (publ).","body":"Verksamheten omfattar cirka 450 000 privatkunder med en total utestående balans av icke-förfallna lån på cirka 4 miljarder kronor. Transaktionen förväntas slutföras den 31 december 2024 och är fortfarande föremål för tillämpliga myndighetsgodkännanden.\n\nVinges team bestod av Christina Kokko, Matthias Pannier, Manon de Cooman, Isabelle Wållgren, Erik Kochbati (M&A), Eva Fredrikson, Jolene Reimerson, Mathilda Persson, Elis Allmark, Nicklas Thorgerzon (Commercial Agreements, IT and GDPR), Viveka Classon, Caroline Krassén, Sara Hedgren (Financial Services), Malin Malm Waerme (IP), Albert Wållgren (Banking and Finance), Victor Ericsson (Tax), Sam Seddigh, Emil Lindwall, Jonatan Stentorp (Employment) samt Carl Bruneheim och Cecilia Loctander (Transaction Support).\n\nLäs Avidas pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-santander-consumer-finance-i-samband-med-avyttring-av-den-svenska-och-norska-kreditkorts-och-saljfinansieringsverksamheten/","date":"2024-09-19","month":9},{"year":2024,"client":"Flower","work":"Förvärv","disciplines":["Fastigheter och Entreprenad","M&A","Kommersiella avtal","Miljörätt","FDI"],"title":"Vinge företräder Flower i samband med förvärvet av batteriprojektet Pajkölen","caption":"Förvärv · 19 september 2024","preamble":"Vinge har företrätt energi-techbolaget Flower Technologies AB (”Flower”) i förvärvet av ett av Sveriges största batteriprojekt, Pajkölen, från Arise AB (publ) (”Arise”). Projektet, som är en Ready-to-Build-anläggning för energilagring med en kapacitet på 40 MW / 80 MWh (BESS), är beläget i vindkraftparken Kölvallen i Ljusdals kommun. Affären omfattar samtliga aktier i Pajkölen BESS AB som äger rättigheterna till projektet.","body":"Tillträdet är villkorat av bl.a. erhållandet av vissa myndighetsgodkännanden och förväntas ske under fjärde kvartalet 2024. Nätanslutningen förväntas vara färdigställd under första halvåret 2025.\n\nGenom förvärvet stärker Flower sin position som landets ledande aktör inom optimering av batterier. När projektet är i drift kommer Flower att ha fullständig kontroll över hela batterivärdekedjan, vilket öppnar upp viktiga intäktsströmmar för aktörer inom förnybar energi, såsom nätoperatörer eller ägare av förnybara kraftslag.\n\nVinges team bestod huvudsakligen av Peter Sundgren, Niklas Suni och Gustav Wahlberg (M&A), Kristoffer Larson (Fastigheter och Entreprenad), Lina Österberg (Miljö), Carla Zachariasson och Ian Linde (Kommersiella avtal) samt Daniel Wendelsson, Dagne Sabockis och Alva Chambert (FDI).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-flower-i-samband-med-forvarvet-av-batteriprojektet-pajkolen/","date":"2024-09-19","month":9},{"year":2024,"client":"EQT IX","work":"Avyttring","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt EQT IX i samband med försäljning av aktier i Beijer Ref AB (publ)","caption":"Avyttring · 18 september 2024","preamble":"Vinge har biträtt EQT IX (”EQT”) i samband med nedförsäljning av aktier i Beijer Ref AB (publ) i en så kallad accelererad bookbuilding-process genomförd den 17 september 2024.","body":"Totalt placerades 20 miljoner aktier till ett pris om 165 kronor per aktie, motsvarande ett sammanlagt värde om 3,3 miljarder kronor.\n\nVinges team bestod av Sofie Bjärtun och Linnéa Sellström.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-eqt-ix-i-samband-med-forsaljning-av-aktier-i-beijer-ref-ab-publ-1/","date":"2024-09-18","month":9},{"year":2024,"client":"Axcel","work":"Övrigt","disciplines":["M&A","Bank och finans","IT, Telekom och Outsourcing","Kommersiella avtal","Immaterialrätt","Offentlig upphandling","Fastigheter och Entreprenad","EU‑ och konkurrensrätt"],"title":"Vinge företräder Axcel i samband med lanseringen av en nordisk koncern inom fastighetsservice","caption":"Övrigt · 18 september 2024","preamble":"Vinge har företrätt det nordiska riskkapitalbolaget Axcel i samband med etableringen av en ny grupp inom fastighetsservice genom att skapa en plattform med 15 bolag i Sverige och Norge. Gruppen erbjuder tjänster inom besiktning, underhåll och incidenthantering för fastigheter med fokus på luftkvalitet, fukt och rör.","body":"Samtliga bolag i gruppen är entreprenörsledda, lokala företag med långvariga kundrelationer och hög kompetens inom områden som luftkvalitet, fuktkontroll eller rör, och erbjuder sina tjänster direkt till fastighetsägare samt genom fastighetsförvaltare och försäkringsbolag. Totalt sysselsätter den nya gruppen närmare 500 personer och genererar intäkter på över 800 miljoner kronor.\n\nVinges team bestod av Christina Kokko, Samra Tesser, Elsie Nassar, Robin Sultani, Nina Fathjalali, Erik Kochbati, Ida Appelgren, Alex Forsberg och Gabriel Chabo (M&A), Hanna Marberg och Amelia Rihs (Arbetsrätt), Kamyar Najmi, Calle Tengwall Pagels och William Carlberg Johansson (Bank och finans), Fredrika Hjelmberg och Siri Blomberg (Kommersiella avtal, IT och GDPR), Arvid Axelryd och Johan Gavelin (Immaterialrätt), Hanna Kövamees och Lina Österberg (Fastighet och miljö), Kristoffer Sällfors (Offentlig upphandling), David Olander och Alva Chambert (EU- och konkurrensrätt), Gulestan Ali (Regelefterlevnad) samt Fanny Askelöf och Julia Ulander Kull (Projektassistenter).\n\nTransaktionen är villkorad av tillämpliga konkurrensmyndigheters godkännanden.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-i-samband-med-lanseringen-av-en-nordisk-plattform-inom-fastighetsservice/","date":"2024-09-18","month":9},{"year":2024,"client":"Pandox","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har biträtt Pandox i samband med en riktad nyemission om 2 miljarder kronor","caption":"Kapitalanskaffning · 18 september 2024","preamble":"Vinge har biträtt hotellfastighetsbolaget Pandox Aktiebolag (publ) i samband med en riktad nyemission varigenom bolaget tillförs cirka 2 miljarder kronor före transaktionskostnader.","body":"Bolaget avser att använda emissionslikviden för att bibehålla bolagets starka finansiella ställning efter förvärv av hotell i London och Edinburgh samt för att öka bolagets finansiella flexibilitet för ytterligare fastighetsförvärv och investeringar i befintliga fastigheter. Pandox aktie är noterad på Nasdaq Stockholm.\n\nVinges team bestod av Jesper Schönbeck, Joel Magnusson, Adrian Filipovic och Maximilian Bengtsson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-pandox-i-samband-med-en-riktad-nyemission-om-2-miljarder-kronor/","date":"2024-09-18","month":9},{"year":2024,"client":"Stendörren","work":"Obligationsemission","disciplines":[],"title":"Vinge biträder Stendörren vid emission av gröna obligationer och återköperbjudande","caption":"Obligationsemission · 13 september 2024","preamble":"Vinge biträder Stendörren Fastigheter AB vid dess emission av seniora, icke-säkerställda gröna obligationer om SEK 800 miljoner (inom en ram om SEK 1200 miljoner kronor) och i samband med bolagets parallella återköpserbjudande till investerare i dess tidigare emitterade obligationer med förfall under 2025.","body":"Ett belopp motsvarande emissionslikviden från de nya obligationerna kommer att användas i enlighet med Stendörrens sedan tidigare etablerade gröna finansieringsramverk och för att återköpa delar av Stendörrens utestående seniora icke-säkerställda obligationer. Obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms lista för hållbara obligationer. Obligationerna har en löptid om 3,25 år och emitterades med en ränta på STIBOR 3m + 290 baspunkter.\n\nNordea Bank Abp, Skandinaviska Enskilda Banken AB (publ) och Swedbank AB (publ) agerade joint bookrunners och dealer managers i transaktionen.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, August Ahlin och Rebecka Margolin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-stendorren-vid-emission-av-grona-obligationer-och-aterkoperbjudande/","date":"2024-09-13","month":9},{"year":2024,"client":"Lagercrantz Group","work":"Förvärv","disciplines":[],"title":"Vinge biträder Lagercrantz Group vid förvärv av Mastsystem Int'l","caption":"Förvärv · 13 september 2024","preamble":"Lagercrantz Group har ingått avtal om att förvärva finska Mastsystem Int'l från Transdigm. Mastsystem Int'l är leverantör av högpresenterande teleskopmaster, som utgör en integrerad del av ledande luftvärnssystem. Bolaget har en årlig omsättning på ca 15 MEUR med EBITA på ca 6 MEUR. Förvärvet görs med en EV/EBITA-multipel på ca 7x.","body":"Slutförandet av transaktionen är föremål för sedvanliga tillträdesvillkor.\n\nVinge, genom Johan Winnerblad, har biträtt Lagercrantz Group.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-vid-forvarv-av-mastsystem-int-l/","date":"2024-09-13","month":9},{"year":2024,"client":"Consolid Equity","work":"Övrigt","disciplines":["M&A","Kommersiella avtal","Bank och finans","Arbetsrätt","Fastigheter och Entreprenad"],"title":"Vinge företräder Consolid Equity i samband med etableringen av Road Mobility Services Group","caption":"Övrigt · 13 september 2024","preamble":"Vinge har företrätt Consolid Equity Investment AB (\"Consolid Equity\") i samband med etableringen av Road Mobility Services Group genom en konsolidering av 28 däck- och bärgningsföretag.","body":"Genom att kombinera expertis och resurser från 28 lokalt ledande däck- och bärgningsbolag skapar Road Mobility Services Group en ny ledande nordisk servicepartner för såväl yrkestrafiken som för privatkunder. Consolid Equity fungerar som en strategisk samarbetspartner i den nya gruppen.\n\nVinges team bestod huvudsakligen av ansvariga delägare Christina Kokko och Johanna Wiberg tillsammans med Viktor Lennartsson, Per Kling, Ellen Flygt, Olof Löfvenberg, Madelene Andersson och Matilda Hamner (M&A); Martin Boström och Elis Allmark (Kommersiella avtal); Calle Tengwall och Josef Groow (Bank och finans); Hanna Marberg och Tyra von Mentzer (Arbetsrätt); Agnes Pigg och Hanna Kövamees (Fastighetsrätt) samt Ellinore Boström Andersson och Diana Kanold (Transaktionssupport).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-consolid-equity-i-samband-med-etableringen-av-road-mobility-services-group/","date":"2024-09-13","month":9},{"year":2024,"client":"Got Your Back","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Got Your Back vid förvärvet av Nordic Depository Services verksamhet inom förvaringsinstituttjänster för alternativa investeringsfonder","caption":"Kapitalanskaffning · 10 september 2024","preamble":"Nordic Depository Services tillhandahåller förvaringsinstituttjänster för alternativa investeringsfonder med fokus på fastigheter och förnybar energi.","body":"Got Your Back tillhandahåller administration av alternativa investeringsfonder, förvaringsinstitutstjänster och fullserviceadministration av svenska aktiebolag. Got Your Back administrerar vidare stiftelser och bistår med andra typer av avancerade administrationsuppdrag som kräver kombinerad kompetens inom juridik och redovisning.\n\nGenom förvärvet stärker och expanderar Got Your Back sin verksamhet inom förvaringsinstituttjänster för alternativa investeringsfonder.\n\nVinges team bestod av Carl Sander och Linus Adolfsson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-got-your-back-vid-forvarvet-av-nordic-depository-services-verksamhet-inom-forvaringsinstituttjanster-for-alternativa-investeringsfonder/","date":"2024-09-10","month":9},{"year":2024,"client":"Säljarna","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt säljarna vid försäljningen av Keeros AB","caption":"Avyttring · 10 september 2024","preamble":"Keeros AB är ett fintech-bolag som erbjuder heltäckande lösningar för fakturering, utlåning och leasing. Förvärvaren var Marathon Software AB som är ett investmentbolag nischade mot mjukvarubolag.","body":"Vinges team bestod av Magnus Pauli, Johanna Hamrefält (Projektledare), Anna Drugge och Amanda Stoltz.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-saljarna-vid-forsaljningen-av-keeros-ab/","date":"2024-09-10","month":9},{"year":2024,"client":"Säljarna","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt säljarna vid försäljningen av Konsert Strategy & IP AB","caption":"Avyttring · 10 september 2024","preamble":"Konsert Strategy & IP är ett svenskt managementkonsultbolag som erbjuder tjänster inom affärsstrategi och immateriella rättigheter. Förvärvaren var Rouse International som är en ledande internationell aktör inom immaterialrättstjänster.","body":"Vinges team bestod av Magnus Pauli, Johanna Hamrefält (Projektledare), Amelia Rihs, Anna Drugge och Amanda Stoltz.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-saljarna-vid-forsaljningen-av-konsert-strategy-ip-ab/","date":"2024-09-10","month":9},{"year":2024,"client":"Zellis Group","work":"Förvärv","disciplines":["M&A","Bank och finans","Kommersiella avtal","Arbetsrätt"],"title":"Vinge företräder Zellis Group, ett portföljbolag till Apax Partners, vid dess förvärv av Benify","caption":"Förvärv · 9 september 2024","preamble":"Vinge har, tillsammans med Kirkland & Ellis, företrätt Zellis Group, en ledande mjukvaruleverantör inom HR-tech, lönehantering och förmånsadministration och ett portföljbolag till fonder som rådgivs av Apax Partner LLP (\"Apax\"), i samband med förvärvet av Benify från bland andra Vitruvian Partners.","body":"Som en del av förvärvet kombineras Benify med Zellis Groups mjukvaruverksamhet för förmånsadministration och medarbetarengagemang, Benefex, för att tillsammans skapa en ledande plattform för globala förmåner, kompensation och medarbetarengagemang, med ett utökat produktutbud till kunder världen över. Slutförandet av transaktionen är föremål för sedvanliga tillträdesvillkor.\n\nVinges team bestod bland andra av Jonas Bergström, Anna Jonsson, Nicolas Ek, Johan Severinsson och Gustav Bergengren (M&A), Nils Unckel och Anton Sjökvist (Financial Regulatory), Albert Wållgren och Arvid Weimers (Banking and Finance), Oskar Larsson (Commercial Contracts) samt Emelie Svensäter Jerntorp och Carolina Lundh (Employment).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-zellis-group-ett-portfoljbolag-till-apax-partners-vid-dess-forvarv-av-benify/","date":"2024-09-09","month":9},{"year":2024,"client":"Baseload Capital","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Baseload Capital i samband med dess Serie B runda på 53 MEUR","caption":"Kapitalanskaffning · 4 september 2024","preamble":"Vinge har biträtt Baseload Capital Holding AB i samband med dess Serie B finansieringsrunda om 53 MEUR. Rundan leddes av infrastrukturfonden ENGF. Huvudinvesteraren bakom ENGF är Ingka Investments, investeringsgrenen inom Ingka Group. Andra aktieägare som deltar i denna runda inkluderar energiteknikföretaget Baker Hughes (vars investering tillkännagavs 2023), NEFCO, Breakthrough Energy Ventures och Gullspång Invest.","body":"Baseload Capital är en ledande investeringsenhet som arbetar för att främja utbyggnaden av geotermisk energi globalt. Genom att etablera operativa bolag på olika platser i världen samarbetar Baseload Capital med lokala samhällen och energileverantörer för att ta i drift, upphandla tillstånd och bygga geotermiska kraftverk som finansieras av Baseload Capital. Baseload Capital och dess dotterbolag Baseload Power är verksamma på mogna geotermiska marknader som Island, USA och Japan, samt på tillväxtmarknader som Taiwan. Som en av de första europeiska investeringarna av Breakthrough Energy Ventures (BEV) har Baseload Capital också en viss kvalitetsstämpel eftersom BEV endast investerar i företag som kan minska utsläppen med minst en halv gigaton växthusgaser.\n\nVinges team bestod huvudsakligen av Maria Dahlin Kolvik, Gustav Wahlberg och Måns Håkansson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-baseload-capital-i-samband-med-dess-serie-b-runda-pa-53-meur/","date":"2024-09-04","month":9},{"year":2024,"client":"Blue Wolf Capital Partners","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad","Arbetsrätt","Kommersiella avtal","FDI","Carve-Outs"],"title":"Vinge företräder Blue Wolf Capital Partners i samband med förvärv av sju tillverknings- och utvecklingsanläggningar från Recipharm","caption":"Förvärv · 3 september 2024","preamble":"Vinge har, tillsammans med Kirkland & Ellis, företrätt Blue Wolf Capital Partners LLC (”Blue Wolf”), ett middle market private equity-bolag specialiserat på hälsovårds- och industrisektorerna, i samband med förvärvet av sju tillverknings- och utvecklingsanläggningar i Sverige, Frankrike och Spanien från Recipharm Group, en organisation verksam inom kontraktsutveckling och kontraktstillverkning (”CDMO”) med huvudkontor i Stockholm.","body":"De sju anläggningarna har varit en del av Recipharm i över ett decennium och har fokuserat på tillverkning och utveckling av orala fasta, halvfasta och flytande läkemedelsprodukter i dosform. Anläggningarna levererar till över 120 kunder runt om i världen och har en stark historik av kvalitet och regelefterlevnad. Tillsammans kommer dessa anläggningar att bilda en ny, oberoende CDMO-plattform med fortsatt fokus på läkemedelstillverkning under ett nytt företagsnamn, vilket kommer att tillkännages efter transaktionens slutförande.\n\nVinges team bestod huvudsakligen av Jonas Bergström, Matthias Pannier, Carl Sander, Per Kling och Alexander Rüdén (M&A), Sam Seddigh, Emil Lindwall och Agnes Pigg (Employment), Johan Cederblad, Lina Österberg och Madelene Andersson (Real Estate and Environment), Stojan Arnerstål (Life Science and Regulatory), Mathilda Persson, Fredrika Hjelmberg, Christoffer Nordin, Carla Zachariasson och Elis Allmark (Commercial Contracts and Separation), Daniel Wendelsson, David Olander, Hilda Ivarsson och Hanna Lemne (FDI) samt Anna Ekdahl Roos (Transaction Support).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-blue-wolf-capital-partners-i-samband-med-forvarv-av-sju-tillverknings-och-utvecklingsanlaggningar-fran-recipharm/","date":"2024-09-03","month":9},{"year":2024,"client":"Märta Måås-Fjetterströms verksamhet","work":"Avyttring","disciplines":[],"title":"Vinge biträder vid försäljningen av Märta Måås-Fjetterströms verksamhet","caption":"Avyttring · 3 september 2024","preamble":"Vinge har biträtt familjen Swedrup vid försäljningen av Märta Måås-Fjetterström, Verkstaden för svenska mattor och vävnader Aktiebolag. Bolaget tillverkar mattor och vävnader i Båstad efter ritningar av såväl Märta Måås-Fjetterström själv som hennes efterföljare såsom Barbro Nilsson, Marianne Richter, Ann-Mari Forsberg med flera. Köpare är familjen Hult.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Philip Moré, Olof Jisland, Emma Stuart-Beck och Fanny Askelöf.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljningen-av-marta-maas-fjetterstroms-verksamhet/","date":"2024-09-03","month":9},{"year":2024,"client":"Ingrid Capacity","work":"Partnerskap","disciplines":["M&A","Bank och finans"],"title":"Vinge företräder Ingrid Capacity vid ingåendet av partnerskap med Locus Energy, ett av SEB Nordic Energys portföljbolag","caption":"Partnerskap · 3 september 2024","preamble":"Vinge har företrätt Ingrid Capacity i samband med ingåendet av ett strategiskt partnerskap med Locus Energy, ett ledande nordiskt energiinfrastrukturbolag som ägs av SEB Asset Managements fond SEB Nordic Energy.","body":"Genom det nya partnerskapet kommer 13 storskaliga batterienergilagringssystem att byggas i södra Sverige, vilket ger ytterligare 196 MW flexibel kapacitet till det nationella elnätet i elprisområdena SE3 och SE4. Det är den näst största investeringen av sitt slag i Sverige och Norden.\n\nIngrid Capacity har som affärsidé att bygga storskaliga batterier för energilagring i Europa. I Sverige ska batterierna bland annat användas för att hjälpa statliga Svenska Kraftnät och regionala och lokala elnätsbolag att klara elförsörjningen. Ingrid Capacity grundandes 2022, omsatte år 2023 ca 117 mkr, och har 50 anställda.\n\nTransaktionen är villkorad av tillämpliga regulatoriska godkännanden.\n\nVinge's team bestod huvudsakligen av Carl Sander, Jonas Bergström, Vilhelm Rondahl, och Matilda Hamner (M&A), Christoffer Thalin och Jonatan Karlsson (Energy), samt Helena Göransson och Jolinn Uhlin (Banking & Finance).\n\nFör mer information vänligen läs här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ingrid-capacity-vid-ingaendet-av-partnerskap-med-locus-energy-ett-av-seb-nordic-energys-portfoljbolag/","date":"2024-09-03","month":9},{"year":2024,"client":"Fidelio Capital","work":"Avyttring","disciplines":["M&A","Immaterialrätt","EU‑ och konkurrensrätt","Finansiella tillståndsfrågor","IT, Telekom och Outsourcing","Kommersiella avtal"],"title":"Vinge företräder Fidelio Capital vid försäljningen av en minoritetsandel i Odevo till CVC Capital Partners","caption":"Avyttring · 28 augusti 2024","preamble":"Vinge har företrätt Fidelio Capital (”Fidelio”) och övriga aktieägare i Odevo Group (”Odevo”) i samband med försäljningen av en minoritetsandel till fonder kontrollerade av CVC Capital Partners (”CVC”). Fidelio, den befintliga ledningen och andra minoritetsägare i Odevo kommer att behålla en majoritetsandel i bolaget.","body":"Odevo har byggt en organisation som, med stöd av en egenutvecklad tech-plattform, hjälper bostadsägare att hantera alla aspekter av sina fastigheter, från redovisning, administration, fakturering och fastighetsservice till renoveringar. Bolaget grundades i Sverige 2018 av investmentbolaget Fidelio och den nuvarande ledningen. Genom organisk tillväxt och samarbete med över 50 framgångsrika entreprenörer i Europa och USA har Odevo expanderat sin verksamhet mer än 50 gånger och förvaltar idag 1,4 miljoner bostäder med över 7 000 anställda och en årlig omsättning på 650 miljoner EUR. Genom att välkomna CVC till gruppen av investerare tar Odevo nu ytterligare steg på sin internationella tillväxtresa.\n\nTransaktionen är villkorad av tillämpliga regulatoriska och konkurrensmyndigheters godkännanden.\n\nVinges team bestod av Jonas Bergström, Johanna Wiberg, Anna Jonsson, Elsie Nassar, Amanda Steen, Philip Moré, Lovisa Jonassen och Matilda Hamner (M&A), Nils Unckel och Anton Sjökvist (Financial Regulatory), Sebastian Örndahl och Alva Chambert (EU‑ och konkurrensrätt), Mathilda Persson, Jolene Reimerson och Siri Blomberg (Kommersiella avtal, IT och GDPR), Rebecka Målquist (Immaterialrätt), Mia Falk och Gulestan Ali (Regelefterlevnad), Emelie Schoning, Emy Rydén, Gabriella Balbo och Ottilia Pettersson (Projektassistenter).\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-fidelio-capital-vid-forsaljningen-av-en-minoritetsandel-i-odevo-till-cvc-capital-partners/","date":"2024-08-28","month":8},{"year":2024,"client":"Evroc","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder evroc i finansieringsrunda","caption":"Kapitalanskaffning · 22 augusti 2024","preamble":"Vinge har biträtt svenska evroc, som planerar att bygga flera stora datacenter i Europa och bli en ledande leverantör av molntjänster, att ta in ca. 500 milj kronor. I finansieringsrundan deltar bl.a. de tidigare investerarna EQT Ventures och Norrsken VC samt den nye investeraren Blisce, ett franskt riskkapitalbolag.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Matilda Hamner.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-evroc-i-finansieringsrunda/","date":"2024-08-22","month":8},{"year":2024,"client":"Lunar Bank","work":"Avyttring","disciplines":["Bank och finans"],"title":"Vinge rådger Lunar Bank vid försäljningen av dess svenska konsumentlåneportfölj till Morrow Bank","caption":"Avyttring · 20 augusti 2024","preamble":"Vinge har rådgett Lunar Bank A/S vid försäljningen av dess svenska konsumentlåneportfölj om ca 1,6 miljarder kr till Morrow Bank ASA.","body":"Transaktionen omfattar hela Lunar Banks svenska konsumentlåneportfölj och kommer slutföras så snart danska Finanstilsynet har godkänt transaktionen. Samtidigt som Lunar Bank fortsätter att växa på den svenska marknaden genom att utöka sin produktportfölj och tjänster, följer transaktionen det strategiska beslutet att kreditförmedlad långivning inte är kärnverksamhet för Lunar Bank och säkerställer att låneportföljen övertas av en specialist på utlåning i Morrow Bank.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda och Jolinn Uhlin.","href":"https://www.vinge.se/uppdrag/vinge-radger-lunar-bank-vid-forsaljningen-av-dess-svenska-konsumentlaneportfolj-till-morrow-bank/","date":"2024-08-20","month":8},{"year":2024,"client":"IK Partners","work":"Avyttring","disciplines":["Bank och finans","M&A","Finansiella tillståndsfrågor","Fastigheter och Entreprenad","Arbetsrätt","Immaterialrätt","Kommersiella avtal"],"title":"Vinge biträder IK Partners vid försäljningen av Carspect till TÜV SÜD","caption":"Avyttring · 19 augusti 2024","preamble":"Vinge har företrätt IK Partners och övriga ägare vid försäljningen av Carspect Group Holding AB till TÜV SÜD Aktiengesellschaft. Carspect är en ledande aktör inom bilbesiktning i Sverige, Estland och Lettland, med totalt omkring 150 stationer och över 500 anställda.","body":"Vinges team har framförallt bestått av Jonas Bergström, Johanna Wiberg, Vilhelm Rondahl och Ida Appelgren (M&A), Lionardo Ojeda, Rebecka Margolin, Sofia Haggren och Nour Makie (Bank och finans), Johan Cederblad (Tillstånd & Ackreditering), Kristoffer Larsson (Fastighet och miljö), Ebba Svenburg och Emil Lindwall (Arbetsrätt), Martin Boström (Kommersiella avtal / IT), Felizia Wiker (IP) och Anna Ekdahl Roos, Ellinore Boström Andersson och Gabriella Balbo (Transaktionssupport).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ik-partners-vid-forsaljningen-av-carspect-till-tuv-sud/","date":"2024-08-19","month":8},{"year":2024,"client":"Embracer Group","work":"Finansiering","disciplines":[],"title":"Vinge har biträtt Embracer Group i samband med ingående av ett 500 miljoner kronors låneavtal med Aktiebolaget Svensk Exportkredit (publ)","caption":"Finansiering · 15 augusti 2024","preamble":"Vinge har biträtt Embracer Group AB (publ) (“Embracer”) i samband med ingåendet av ett låneavtal om 500 miljoner kronor med Aktiebolaget Svensk Exportkredit (publ). Embracer är en global koncern med entreprenörsdrivna företag inom spel- och underhållningsindustrin och den nya lånefaciliteten ska användas för finansiering av allmänna företagsändamål inom koncernen.","body":"Vinges team bestod av Albert Wållgren, Felix Möller, Ida Redander och Josef Groow.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-embracer-group-i-samband-med-ingaende-av-ett-500-miljoner-kronors-laneavtal-med-aktiebolaget-svensk-exportkredit-publ/","date":"2024-08-15","month":8},{"year":2024,"client":"Vitamin Well","work":"Avyttring","disciplines":["M&A","Arbetsrätt","Bank och finans","Immaterialrätt","Fastigheter och Entreprenad","GDPR","Kommersiella avtal","IT, Telekom och Outsourcing","EU‑ och konkurrensrätt","Corporate Crime & Compliance"],"title":"Vinge rådgivare vid försäljning i Vitamin Well","caption":"Avyttring · 6 augusti 2024","preamble":"Vinge företräder Bridgepoint Development Capital III och Bridgepoint Europe VI (”Bridgepoint”), grundare och övriga ägare i samband med att Cinven, ett internationellt riskkapitalbolag, förvärvar en betydande andel i Vitamin Well Group (”Vitamin Well”) och därmed blir ny huvudinvesterare, samtidigt som Bridgepoint, grundare och övriga ägare kommer att behålla betydande minoritetsandelar efter transaktionen.","body":"Vitamin Well, som grundades 2008 och har sitt huvudkontor i Stockholm, är en snabbväxande koncern inom functional foods och drycker som erbjuder premiumprodukter för hälsomedvetna och aktiva konsumenter. Idag har koncernen cirka 500 anställda och en bred produktportfölj med flera varumärken, inklusive kärnvarumärkena Vitamin Well (vitamin- och mineralberikade drycker), NOCCO (energidrycker) och Barebells (proteinbars och shakes), som säljs internationellt på mer än 40 marknader.\n\nTransaktionen är villkorad av regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Daniel Rosvall, Samra Tesser, Carl Fredrik Wachtmeister, Robin Fagerström, Sara Passandideh och Lovisa Jonassen (M&A), Albert Wållgren, Karl-Gustaw Tobola och Josef Groow (Banking and Finance), Ebba Svenburg och Jonna Skog (Employment), Arvid Axelryd (Intellectual Property), Karolina Cohrs (Real Estate), Christoffer Nordin, Martin Boström, Carla Zachariasson och Arthur Kinski (Commercial Agreements, IT and GDPR) David Olander, Lovisa Lewin och Hampus Peterson (EU and FDI Regulatory) Anders Leissner, Tyra von Mentzer och Gulestan Ali (Compliance), Jessica Öijer, Cecilia Loctander och Christoffer Widström (Transaction Support Coordinators).","href":"https://www.vinge.se/uppdrag/vinge-radgivare-vid-forsaljning-i-vitamin-well/","date":"2024-08-06","month":8},{"year":2024,"client":"EQT","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har företrätt EQT AB i samband med refinansieringen av EQTs hållbarhetslänkade revolverande kreditfacilitet om 1.500.000.000 EUR","caption":"Finansiering · 23 juli 2024","preamble":"Den hållbarhetslänkade krediten har en löptid på 5 år med två 1-åriga förlängningsoptioner.","body":"Krediten arrangerades av bland annat Nordea och långivargruppen bestod av 20 globala finansiella institutioner.\n\nVinges team bestod huvudsakligen av Helena Göransson, Josefine Lanker, Kamyar Najmi, Nour Makie och Rebecka Margolin.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eqt-ab-i-samband-med-refinansieringen-av-eqts-hallbarhetslankade-revolverande-kreditfacilitet-om-1-500-000-000-eur/","date":"2024-07-23","month":7},{"year":2024,"client":"Embracer Group","work":"Finansiering","disciplines":["M&A"],"title":"Vinge har biträtt Embracer Group i samband med ingående av ett 600 miljoner euro revolverande kreditfacilitetsavtal","caption":"Finansiering · 19 juli 2024","preamble":"Vinge har biträtt Embracer Group i samband med ingående av ett 600 miljoner euro revolverande kreditfacilitetsavtal med BNP Paribas, Citibank Europe, DNB, JP Morgan, Nordea, SEB och Swedbank.","body":"Vinge har biträtt Embracer Group AB (publ) (“Embracer”) i samband med ingåendet av ett revolverande kreditfacilitetsavtal om 600 miljoner euro med BNP Paribas, Citibank Europe, DNB, JP Morgan, Nordea, SEB och Swedbank. Embracer är en global koncern med entreprenörsdrivna företag inom spel- och underhållningsindustrin.\n\nDen nya faciliteten om 600 miljoner euro används för att refinansiera Embracers befintliga revolverande kreditfaciliteter på 4,8 miljarder kronor. Villkoren för den nya faciliteten har förbättrats, inklusive en noterbart lägre kreditmarginal för utnyttjad skuld, vilket kommer att minska räntekostnaderna genom både förbättrade villkor och en minskad skuldsättning.\n\nVinges team bestod av Albert Wållgren, Felix Möller, Ida Redander och Josef Groow.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-embracer-group-i-samband-med-ingaende-av-ett-600-miljoner-euro-revolverande-kreditfacilitetsavtal/","date":"2024-07-19","month":7},{"year":2024,"client":"SBB och Sveafastigheter","work":"Övrigt","disciplines":["Bank och finans"],"title":"Vinge har företrätt SBB och Sveafastigheter i samband utbyteserbjudande","caption":"Övrigt · 9 juli 2024","preamble":"Vinge har företrätt Samhällsbyggnadsbolaget i Norden AB (SBB) och Sveafastigheter AB i samband med ett utbyteserbjudande riktat till investerare i SBBs utestående obligationer, genom vilket investerare utbytt seniora och hybridobligationer i SBB mot nya seniora obligationer emitterade i Sveafastigheter AB. De existerande obligationerna var delvis emitterade under SBBs EMTN-program, delvis på standalone basis, och investerarna flyttas efter transaktionen in under svenska obligationsvillkor på standalone basis.","body":"Genom transaktionen har i SBB utestående obligationer om EUR 275 000 000, SEK 721 000 000 och NOK 40 000 000 utbytts mot nya obligationer i Sveafastigheter till belopp om EUR 110 900 000 (under ett ramverk om EUR 183 500 000) samt SEK 412 500 000. I tillägg till det rena instrumentutbyten erbjöd SBB även, under vissa förutsättningar, en kontantkomponent som kompensation för utbytet.\n\nDanske Bank A/S, DNB Markets, en del av DNB Bank ASA, filial Sverige och Skandinaviska Enskilda Banken AB (publ) agerade dealer managers i samband utbyteserbjudandet.\n\nVinges team bestod av Mikael Ståhl, Rikard Lindahl, Lionardo Ojeda, William Kåge, Benjamin Vafaeian, August Ahlin och Filip Magnusson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-sbb-och-sveafastigheter-i-samband-utbyteserbjudande/","date":"2024-07-09","month":7},{"year":2024,"client":"SmartCella Holding","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har biträtt SmartCella Holding AB i samband med kapitalanskaffning","caption":"Kapitalanskaffning · 8 juli 2024","preamble":"Vinge har biträtt SmartCella Holding AB i samband med kapitalanskaffning om EUR 50 miljoner. Kapitalet investerades av bl a AstraZeneca, Fjärde AP-fonden, AMF Pension, SEB-Stiftelsen, Handelsbanken Fonder and RoosGruppen AB. SmartCella är ett världsledande bioteknikföretag som banar väg för framtiden för riktade terapier genom att kombinera förstklassiga leveransplattformar med banbrytande cell- och genterapier.","body":"Vinges team bestod av Jesper Ottergren, Sofie Bjärtun, Erik Sjöman, Stojan Arnerstål, Martin Madsen Svanberg, Annie Fällström, Joel Magnusson, Johan Severinsson och Nathalie Wikman.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-smartcella-holding-ab-i-samband-med-kapitalanskaffning/","date":"2024-07-08","month":7},{"year":2024,"client":"Polar Structure","work":"Obligationsemission","disciplines":["Fastigheter och Entreprenad","Bank och finans"],"title":"Vinge har biträtt Polar Structure AB vid en emission av seniora säkerställda obligationer om 81 miljoner euro genom ett majoritetsägt dotterbolag","caption":"Obligationsemission · 4 juli 2024","preamble":"Vinge har biträtt Polar Structure AB, en ledande utvecklare och ägare av infrastruktur, vid bolagets emission av seniora säkerställda obligationer om 81 miljoner euro genom ett majoritetsägt dotterbolag. Emissionen syftar till att finansiera byggnationen av en järnvägstillgång utanför Boden som ska förbinda Malmbanan med H2 Green Steels nya anläggning för storskalig produktion av grönt stål vid Boden Industrial Park.","body":"Obligationerna har en löptid på 6,5 år, löper med fast ränta och är säkerställda med panter i bland annat järnvägstillgångarna.\n\nVinges team bestod huvudsakligen av Niclas Winnberg och Kristoffer Larson (Fastighet), Helena Göransson, Karl-Gustaw Tobola och Josef Groow (Bank och finans) samt Filippa Bergkvist (Transaktionsstöd).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-polar-structure-ab-vid-en-emission-av-seniora-sakerstallda-obligationer-om-81-miljoner-euro-genom-ett-majoritetsagt-dotterbolag/","date":"2024-07-04","month":7},{"year":2024,"client":"KKR","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder KKR vid investering i Söderberg & Partners","caption":"Kapitalanskaffning · 3 juli 2024","preamble":"KKR och TA Associates, vilka är befintliga minoritetsägare i Söderberg & Partners, har åtagit sig att vid nyemissioner av aktier tillföra Söderberg & Partners totalt cirka tre miljarder kronor. Vinge företräder KKR.","body":"Vinges team bestod av Christina Kokko och Samra Tesser.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-kkr-i-investering-i-soderberg-partners/","date":"2024-07-03","month":7},{"year":2024,"client":"Bergs Timber AB och Bitus","work":"Övrigt","disciplines":["Miljörätt","Fastigheter och Entreprenad","M&A","Arbetsrätt","EU‑ och konkurrensrätt"],"title":"Vinge företräder Bergs Timber AB (publ) och Bitus AB","caption":"Övrigt · 3 juli 2024","preamble":"Vinge företräder Bergs Timber AB (publ) och Bitus AB vid avyttring av Fågelfors pelletsverksamhet till J. Rettenmeier & Söhne. Fågelfors pelletsverksamhet bedrivs i Fågelfors i Högsby. Förvärvet är villkorat av sedvanliga myndighetsgodkännanden.","body":"Vinges team bestod av ansvarig counsel Ulrich Ziche tillsammans med Niklas Suni (M&A), Johan Cederblad (Miljörätt), Niclas Winnberg och Frida Ställborn (Fastighetsrätt), Simon Söderholm (Arbetsrätt), Daniel Wendelsson (Regulatory) samt Emelie Schoning (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-bergs-timber-ab-publ-och-bitus-ab/","date":"2024-07-03","month":7},{"year":2024,"client":"EQT och Recover","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder EQT och Recover i dess försäljning av Serwant","caption":"Avyttring · 3 juli 2024","preamble":"Vinge företräder EQT backade Recover Group i dess försäljning av Serwant till Norverstor. Serwent är en leverantör av underhållstjänster för infrastruktur ovan och under jord.","body":"Vinges team bestod av bland andra Samra Tesser, Nina Fathjalali och Alex Forsberg.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-eqt-och-recover-i-dess-forsaljning-av-serwant/","date":"2024-07-03","month":7},{"year":2024,"client":"Borgo","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har biträtt Borgo i samband med kapitalanskaffning","caption":"Kapitalanskaffning · 1 juli 2024","preamble":"Vinge har biträtt Borgo i samband med kapitalanskaffning om 357 miljoner kronor. Kapitalet investeras av existerande ägare och Lån & Spar Bank A/S.","body":"Borgo AB (publ) Borgo är ett svenskt hypoteksbolag som samägs av ICA Banken, Ikano Bank, Söderberg & Partners, Sparbanken Syd, Ålandsbanken och Lån & Spar samt Persson Invest, Proventus, Real Alliance Invest och Neptunia Invest och ytterligare investerare. Borgo drivs fristående och fokuserar på att finansiera och erbjuda bostadskrediter.\n\nVinges team bestod främst av Johan Larsson, Samra Tesser, Rikard Lindahl, Joel Magnusson och Michaela Ådén.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-borgo-i-samband-med-kapitalanskaffning/","date":"2024-07-01","month":7},{"year":2024,"client":"VIA equity","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder VIA equity vid investering i Crediflow","caption":"Kapitalanskaffning · 28 juni 2024","preamble":"Vinge har biträtt danska VIA equity fond V när de blir majoritetsägare i OptoSweden AB med dotterbolaget Crediflow AB. Dagens aktiva aktieägare kommer återinvestera för att bli minoritetsaktieägare. Crediflows tjänster används idag i flertalet ekonomi- och affärssystem på den svenska och europeiska marknaden för att digitalisera och automatisera inkommande och utgående flöden av fakturor och elektroniska dokument.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Per Kling, Tim Axell, Fredrika Hjelmberg, Mario Saad, Ian Linde, Arthur Kinski, Felizia Wiker, Emil Lindwall, Lava Mustafa och Julia Ulander Kull.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-via-equity-vid-investering-i-crediflow/","date":"2024-06-28","month":6},{"year":2024,"client":"Tele2","work":"Finansiering","disciplines":[],"title":"Vinge biträder Tele2 i samband med 5G-finansiering från EIB","caption":"Finansiering · 28 juni 2024","preamble":"Vinge biträder Tele2 AB (publ) i samband med ingåendet av ett låneavtal om EUR 140 miljoner från Europeiska investeringsbanken (EIB), vilket tas upp i syfte att stödja utbyggnaden av 5G-nätet och uppgraderingen av 4G-nätet i Sverige.","body":"EIB är Europeiska unionens bank. Det är den enda banken som ägs av och företräder Europeiska unionens medlemsstaters intressen. Banken finansierar och specialiserar sig på sunda och hållbara investeringsprojekt som bidrar till att främja EU:s politiska mål.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, Karl-Gustaw Tobola och Adrian Filipovic.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-tele2-i-samband-med-5g-finansiering-fran-eib/","date":"2024-06-28","month":6},{"year":2024,"client":"Trinax","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Trinax vid förvärv av Jiricom","caption":"Förvärv · 27 juni 2024","preamble":"Vinge har biträtt Trinax, ett portföljbolag till Helix Kapital, vid förvärv av Jiricom. Trinax, ett ledande mjukvarubolag inom tid- och projekthantering för hantverkare och fältservicebolag, stärker sin marknadsposition inom fleet management genom förvärvet av Jiricom.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Gustav Wahlberg, Jonatan Stentorp och Siri Blomberg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-trinax-vid-forvarv-av-jiricom/","date":"2024-06-27","month":6},{"year":2024,"client":"Funnel","work":"Förvärv","disciplines":[],"title":"Vinge biträder Funnel vid förvärv av AdTriba","caption":"Förvärv · 26 juni 2024","preamble":"Vinge har biträtt det svenska SaaS-bolaget Funnel vid förvärv av tyska AdTriba, som sysslar med marknadsföringsmätningar. Förvärvet utökar och förbättrar Funnels produkterbjudande.","body":"Vinges team bestod av Johan Winnerblad, Matthias Pannier, Joel Wahlberg, Adrian Filipovic och Filip Magnusson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-funnel-vid-forvarv-av-adtriba/","date":"2024-06-26","month":6},{"year":2024,"client":"KMC Properties","work":"Samgående","disciplines":[],"title":"Vinge har biträtt KMC Properties i dess samgående med Logistea","caption":"Samgående · 24 juni 2024","preamble":"Den 14 juni 2024 offentliggjorde KMC Properties ASA, noterat på Oslo Børs, att bolaget går samman med Logistea AB (publ), noterat på Nasdaq Stockholm.","body":"Samgåendet genomförs genom att Logistea förvärvar samtliga aktier i KMC Properties HoldCo AS (”KMC HoldCo”), ett helägt dotterbolag till KMC Properties, och därmed förvärvar all verksamhet i KMC Properties-koncernen, med betalning genom nyemitterade aktier i Logistea. Transaktionen värderar KMC HoldCo till 3 259 miljoner kronor.\n\nVinges team bestod huvudsakligen av Jesper Schönbeck, Niclas Winnberg, Ulrich Ziche, Joel Wahlberg, Karolina Cohrs, Frida Ställborn, Adrian Filipovic, Agnes Pigg och Hanna Kövamees.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-kmc-properties-i-dess-samgaende-med-logistea/","date":"2024-06-24","month":6},{"year":2024,"client":"Cinclus Pharma","work":"Börsnotering","disciplines":["Immaterialrätt","Kapitalmarknad och publik M&A","Företagsbeskattning","Arbetsrätt","IT, Telekom och Outsourcing","Bank och finans"],"title":"Vinge företräder Cinclus Pharma i samband med notering på Nasdaq Stockholm","caption":"Börsnotering · 20 juni 2024","preamble":"Vinge företräder Cinclus Pharma Holding AB (publ) (”Cinclus Pharma”) i samband med ett erbjudande av nyemitterade stamaktier och notering på Nasdaq Stockholm. Första dag för handel är den 20 juni 2024.","body":"Erbjudandet kommer att tillföra Cinclus Pharma cirka 787 miljoner SEK före avdrag för emissionskostnader och under förutsättning att övertilldelningsoptionen utnyttjas fullt ut. I samband med erbjudandet genomför Cinclus Pharma även en kvittningsemission till erbjudandepriset i syfte att konvertera utestående brygglån.\n\nCinclus Pharma är ett läkemedelsbolag i klinisk fas som fokuserar på utveckling av läkemedelskandidaten linaprazan glurate, en patentskyddad ”prodrug” av molekylen linaprazan. Linaprazan glurate representerar en ny och innovativ verkningsmekanism för behandling av erosiv GERD.\n\nVinges team består huvudsakligen av Dain Hård Nevonen, Amanda Knutsson, Anna Svensson, Michaela Ådén och Filip Magnusson (Kapitalmarknad och Publik M&A), Stojan Arnestål (IP/Life science), Maria Schultzberg (Företagsbeskattning), Mathilda Persson (Kommersiella avtal), Gulestan Ali (Compliance), Nicklas Thorgerzon (IT/GDPR), Jonatan Stentorp (Arbetsrätt) samt Sofia Haggren (Finansiering).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-cinclus-pharma-i-samband-med-notering-pa-nasdaq-stockholm/","date":"2024-06-20","month":6},{"year":2024,"client":"Axcel VI och Currentum","work":"Förvärv","disciplines":["M&A","Bank och finans","Fastigheter och Entreprenad","Arbetsrätt"],"title":"Vinge företräder Axcel VI och Currentum vid förvärv av Elektro-Emanuel","caption":"Förvärv · 19 juni 2024","preamble":"Vinge företräder Axcel VI och Currentum-koncernen vid förvärvet av Elektro-Emanuel AB. Bolaget utför elinstallationer åt såväl företag som privatpersoner och har kontor i fyra städer i Västsverige.","body":"Förvärvet är villkorat av sedvanliga myndighetsgodkännanden.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Carl Fredrik Wachtmeister och Alexander Rüdén (M&A), Calle Tengwall Pagels och Frithiof Hallgren Wallin (Bank och finans), Niclas Lindblom (Entreprenadrätt), Hanna Kövamees (Fastighetsrätt), Narin Melazade och Jonatan Stentorp (Arbetsrätt), Daniel Wendelsson, David Olander och Hilda Ivarsson (Regulatory) samt Johanna Engström (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-vi-och-currentum-vid-forvarv-av-elektro-emanuel/","date":"2024-06-19","month":6},{"year":2024,"client":"ARCH Venture Partners","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har biträtt ARCH Venture Partners som lead investor i Moleculents $26 miljoner Serie A runda","caption":"Kapitalanskaffning · 19 juni 2024","preamble":"Moleculent AB, ett bolag med banbrytande teknologi för studier av kommunikation mellan celler i mänsklig vävnad, har stängt sin övertecknade $26 miljoner Serie A runda. Rundan leddes ARCH Venture Partners tillsammans med Eir Ventures och med deltagande från befintliga investerare.","body":"ARCH Venture Partners skapar och investerar i nyskapande life science och teknologi bolag. Firman är en erkänd ledare inom kommersialisering av teknologier som skapats inom akademiska institutioner, företags forskningsgrupper och nationella laboratorier.\n\nVinges team bestod främst av Johan Larsson, Maria Dahlin Kolvik, Stojan Arnerstål, David Olander, Johan Gavelin, Olof Löfvenberg och Alice Göransson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-arch-venture-partners-som-lead-investor-i-moleculents-26-miljoner-serie-a-runda/","date":"2024-06-19","month":6},{"year":2024,"client":"Eleda","work":"Förvärv","disciplines":["M&A","EU‑ och konkurrensrätt"],"title":"Vinge har företrätt Eleda i samband med förvärvet av Sartor & Drange AS","caption":"Förvärv · 17 juni 2024","preamble":"Vinge företrädde tillsammans med Thommessen infrastrukturkoncernen Eleda vid förvärvet av Sartor & Drange AS, en marknadsledande anläggningsentreprenör i Bergenregionen. Sartor & Drange AS erbjuder tjänster inom bland annat väg-, VA- och grundläggningsarbeten på Vestlandet. Sartor & Drange AS har cirka 200 medarbetare och omsätter i storleksordning 1 100 MNOK.","body":"Vinges team bestod av Christina Kokko, Johanna Wiberg, Carl Fredrik Wachtmeister (M&A) och David Olander (konkurrensrätt).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-i-samband-med-forvarvet-av-sartor-drange-as/","date":"2024-06-17","month":6},{"year":2024,"client":"Svea Bank","work":"Kapitalanskaffning","disciplines":["Bank och finans"],"title":"Vinge har biträtt Svea Bank AB i samband med dess emission av sekundärkapital (T2) om 300 miljoner SEK","caption":"Kapitalanskaffning · 14 juni 2024","preamble":"Vinge har biträtt Svea Bank AB vid dess emission av T2-obligationer om 300 miljoner SEK med en rörlig kupong om 3-månaders STIBOR + 6.75%. Emissionsdagen är satt till den 7 juni 2024 och obligationerna har en löptid på 10,25 år med första möjliga inlösendag efter 5 år. Instrumenten kommer att noteras på Nasdaq Stockholm.","body":"Vinges team bestod av Mikael Ståhl, Felix Möller och Sofia Haggren.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-svea-bank-ab-i-samband-med-dess-emission-av-sekundarkapital-t2-om-300-miljoner-sek/","date":"2024-06-14","month":6},{"year":2024,"client":"Axcel och XPartners","work":"Förvärv","disciplines":[],"title":"Vinge företräder Axcel och XPartners vid förvärv av HTJ","caption":"Förvärv · 13 juni 2024","preamble":"Vinge har företrätt Axcel VII (”Axcel”) och XPartners Samhällsbyggnad (”XPartners”) vid förvärvet av HTJ Holding OY och dess dotterbolag Rakennuttajatoimisto HTJ Oy (”HTJ”).","body":"HTJ är en av de ledande byggkonsultfirmorna i Finland, med över 200 anställda och en omsättning på cirka 26 miljoner euro. HTJ erbjuder experttjänster inom byggledning, energi- och miljörådgivning samt projektledning och har sitt huvudkontor i Vanda utanför Helsingfors. Genom förvärvet tar XPartners steget in på den finländska marknaden.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Carl Fredrik Wachtmeister, Alexander Rüdén och David Olander.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-xpartners-vid-forvarv-av-htj/","date":"2024-06-13","month":6},{"year":2024,"client":"Flower Infrastructure Technologies","work":"Förvärv","disciplines":["M&A","Bank och finans","Miljörätt","Kommersiella avtal","Fastigheter och Entreprenad","FDI"],"title":"Vinge har företrätt Flower Infrastructure Technologies AB i samband med förvärvet av energilagringsanläggningen Bredhälla","caption":"Förvärv · 11 juni 2024","preamble":"Energilagringsanläggningen Bredhälla består av batterier med litium-jonteknik med en total kapacitet på 42,5MW/42,5MWh fördelat på 20 containrar vilket gör den till Sveriges största batteripark. Bredhälla kommer att tillhandahålla stödtjänster till Svenska Kraftnät för att säkerställa stabiliteten i elnätet samt arbitragetjänster på elmarknaden.","body":"Förvärvet stärker Flowers position som Sveriges ledande batterioptimerare.\n\nVinges team bestod huvudsakligen av Peter Sundgren och Gustav Wahlberg (M&A), Albert Wållgren och Jolinn Uhlin (Finansiering), Johan Cederblad och Lina Österberg (Miljö), Jolene Reimersson och Carl Lexenberg (Kommersiella avtal), Daniel Prawitz och Clara Klingspor (Entreprenadrätt) samt Daniel Wendelsson, Felizia Wiker, Dagne Sabockis och Alva Chambert (FDI).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-flower-infrastructure-technologies-ab-i-samband-med-forvarvet-av-energilagringsanlaggningen-bredhalla/","date":"2024-06-11","month":6},{"year":2024,"client":"Doconomy","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Doconomy i samband med dess Serie B runda på 34 MEUR","caption":"Kapitalanskaffning · 5 juni 2024","preamble":"Vinge har biträtt Doconomy AB, en fintech start-up som ger banker resurser för att främja finansiell hälsa och klimatåtgärder, i samband med dess Serie B finansieringsrunda om 34 MEUR. Rundan leddes av UBS Next, som är UBS VC- och innovationsgren, samt befintliga investeraren CommerzVentures som agerade co-lead. Andra aktieägare som deltog i rundan inkluderar Motive Ventures, PostFinance och Tenity.","body":"Finansieringen kommer att stödja Doconomys produktutbud och expansion i Nordamerika, vilket främjar en bredare användning av och engagemang för verktygen som Doconomy tillhandahåller.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Maria Dahlin Kolvik, Måns Håkansson och Ida Appelgren.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-doconomy-i-samband-med-dess-serie-b-runda-pa-34-meur/","date":"2024-06-05","month":6},{"year":2024,"client":"Priveq","work":"Övrigt","disciplines":["Private Funds"],"title":"Vinge har biträtt Priveq vid etableringen av Priveq Investment VII","caption":"Övrigt · 4 juni 2024","preamble":"Priveq, en ledande investerare på den nordiska marknaden för små- och medelstora bolag har stängt sin sjunde fond, Priveq Investment VII, med investeringsåtaganden om 3 miljarder kr. Fondens första och sista stängning var betydligt övertecknad med stort intresse från existerande investerare och nytillkomna institutionella investerare.","body":"Fondens investerarkollektiv består av en diversifierad grupp av nordiska, europeiska och amerikanska investerare och inkluderar bland annat statliga och privata pensionsfonder, försäkringsbolag, välgörenhetsstiftelser, family offices och fond-i-fonder.\n\nVinge har biträtt Priveq som svenskt juridiskt ombud i samband med fondetableringen.\n\nVinges team har bestått av Mattias Schömer, Marcus Andersson, Nils Unckel, Anton Sjökvist, Emelie Svanberg, Tobias Onegård Karlsson, Semir Omerbasic, Emelie Zingmark, Helena Göransson, Nour Makie och Elias Kröger.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-priveq-vid-etableringen-av-priveq-investment-vii/","date":"2024-06-04","month":6},{"year":2024,"client":"Vinci Concessions SAS och dotterbolaget SunMind SAS","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Miljörätt","Fastigheter och Entreprenad","Kommersiella avtal","Corporate Crime & Compliance","EU‑ och konkurrensrätt"],"title":"Vinge företräder Vinci Concessions SAS och dotterbolaget SunMind SAS i samband med förvärvet av Helios Nordic Energy AB","caption":"Förvärv · 30 maj 2024","preamble":"Helios Nordic Energy är specialiserade inom utveckling av storskaliga solcellsparker och batteriparker fram till ready-to-build status i Norden och Baltikum.","body":"Förvärvet kommer att möjliggöra för Vinci att ytterligare utöka sin portfölj och expertis inom förnybar solenergi och andra typer av förnybar energi.\n\nDe nuvarande aktieägarna i Helios kommer erhålla en initial köpeskilling om ca 73 MEUR såväl som en substantiell tilläggsköpeskillingskomponent kopplad till Helios osålda portfölj av projekt vilken sträcker sig över fem år från tillträde.\n\nFörvärvet är villkorat av sedvanliga myndighetsgodkännanden.\n\nVinges team bestod bland annat av ansvarig delägare Peter Sundgren, Martin E Svanberg (projektledare), Hanna Jansson och Fredrik Löwenclou (M&A), Amelia Rihs (Arbetsrätt & M&A), Johan Cederblad och Lina Österberg (Miljö), Kristoffer Larsson (Fastighet), Jasdeep Singh (Entreprenadrätt), Jolene Reimersson och Mario Saad (Kommersiella Avtal), Mia Falk (Compliance), David Olander och Lovisa Lewin (Regulatory), Cecilia Loctander och Caroline Löv (Transaction Support Coordinators).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-vinci-concessions-sas-och-dotterbolaget-sunmind-sas-i-samband-med-forvarvet-av-helios-nordic-energy-ab-fran-magnora-asa-management-och-tidiga-investerare/","date":"2024-05-30","month":5},{"year":2024,"client":"Samhällsbyggnadsbolaget","work":"Partnerskap","disciplines":[],"title":"Vinge har företrätt Samhällsbyggnadsbolaget i Norden AB i samband med att SBB etablerar ett nytt joint venture-bolag tillsammans med Castlelake, LP","caption":"Partnerskap · 28 maj 2024","preamble":"Vinge har företrätt Samhällsbyggnadsbolaget i Norden AB (publ) (”SBB”) i samband med att SBB etablerar ett nytt joint venture-bolag tillsammans med Castlelake, LP (\"Castlelake\").","body":"SBB har ingått avtal om att bilda ett joint venture-bolag, SBB Social Facilities AB, tillsammans med fonder som förvaltas av den globala alternativa förvaltaren Castlelake och med stöd från ATLAS SP Partners (tillsammans ”Långivarna”). I samband med etableringen av joint venture-bolaget frigörs likvida medel till SBB genom ett låneavtal mellan SBB Social Facilities och Långivarna om cirka 5,7 miljarder kronor. Fullföljande av transaktionen kommer att ske så snart som alla fullföljandevillkor har uppfyllts, vilket väntas ske i juni 2024.\n\nVinges team bestod huvudsakligen av Mikael Ståhl, Helena Göransson, Rikard Lindahl, Ulrich Ziche, William Kåge, Kamyar Najmi, Ida Redander och Rebecka Margolin.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-samhallsbyggnadsbolaget-i-norden-ab-publ-sbb-i-samband-med-att-sbb-etablerar-ett-nytt-joint-venture-bolag-tillsammans-med-castlelake-lp-castlelake/","date":"2024-05-28","month":5},{"year":2024,"client":"Calliditas Therapeutics","work":"Offentligt uppköpserbjudande","disciplines":["Kapitalmarknad och publik M&A","FDI"],"title":"Vinge biträder Calliditas Therapeutics i samband med Asahi Kasei Corporations offentliga uppköpserbjudande","caption":"Offentligt uppköpserbjudande · 28 maj 2024","preamble":"Den 28 maj 2024 offentliggjorde Asahi Kasei Corporation ett offentligt uppköpserbjudande till aktieägare och innehavare av amerikanska depåbevis i Calliditas Therapeutics AB (publ) (”Calliditas Therapeutics”) att förvärva samtliga aktier respektive amerikanska depåbevis (som vardera representerar två aktier) i Calliditas Therapeutics.","body":"Calliditas Therapeutics är ett kommersiellt biofarmabolag noterat på Nasdaq Stockholm och Nasdaq Global Select Market i USA som fokuserar på identifiering, utveckling och kommersialisering av nya behandlingar för sällsynta sjukdomar med betydande medicinska behov som inte tillgodosetts. Det totala värdet av erbjudandet uppgår till cirka 11 164 miljoner kronor baserat på totalt antal utestående aktier i Calliditas Therapeutics. Vinge biträder Calliditas Therapeutics.\n\nVinges team har huvudsakligen bestått av Dain Hård Nevonen, Linnéa Sellström, William Kåge och Benjamin Vafaeian (Kapitalmarknad och publik M&A) samt Daniel Wendelsson (FDI).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-calliditas-therapeutics-i-samband-med-asahi-kasei-corporations-offentliga-uppkopserbjudande/","date":"2024-05-28","month":5},{"year":2024,"client":"Alder","work":"Fondetablering","disciplines":["Private Funds"],"title":"Vinge har biträtt Alder vid fondetableringen av Alder III","caption":"Fondetablering · 27 maj 2024","preamble":"Vinge har biträtt Alder vid etableringen av Alders tredje och största fond någonsin, Alder III.","body":"Alder har under en framgångsrik fondresning erhållit ca 3,1 miljarder kronor i investeringsåtaganden från en internationell investerarbas och dubblerar därmed de totala investeraråtagandena jämfört med föregångsfonden Alder II.\n\nAlder stängde sin första fond 2010 och fokuserar på investeringar i hållbara teknikbolag med lönsam tillväxt och en omsättning på mellan 100 och 750 miljoner kronor. Alder investerar primärt som majoritetsägare i bolag som är etablerade i Norden men kan även investera selektivt i övriga Europa. Alders fonder – inkluderat Alder III – är klassade som s.k. artikel 9-fonder under SFDR.\n\nVinges team har huvudsakligen bestått av Johan Larsson, Mattias Schömer, Martin Cronsioe, Viveka Classon, Nils Unckel, Ulf Nilsson, Emelie Svanberg, Anton Sjökvist, Semir Omerbasic, Tobias Onegård Karlsson, Marcus Andersson, Viktoria Wnuk, Emelie Zingmark, Helena Göransson, Kamyar Najmi och Nour Makie.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-alder-vid-fondetableringen-av-alder-iii/","date":"2024-05-27","month":5},{"year":2024,"client":"Triton","work":"Avyttring","disciplines":["M&A","Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Triton i samband med försäljning av aktier i Ambea AB (publ)","caption":"Avyttring · 27 maj 2024","preamble":"Totalt placerades 7,6 miljoner aktier till ett pris om 64 kronor per aktie, motsvarande ett sammanlagt värde om cirka 489 miljoner kronor.","body":"Vinges team bestod av Sofie Bjärtun och Joel Magnusson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-triton-i-samband-med-forsaljning-av-aktier-i-ambea-ab-publ-2/","date":"2024-05-27","month":5},{"year":2024,"client":"J2 Sourcing","work":"Övrigt","disciplines":["Arbetsrätt","Fastigheter och Entreprenad","M&A"],"title":"Vinge biträder J2 Sourcing AB","caption":"Övrigt · 23 maj 2024","preamble":"Vinge har biträtt J2 Sourcing AB i samband med dess förvärv av AAAAA Nordic AB, en svensk återförsäljare av elektronikkomponenter.","body":"Vinges team bestod av Magnus Hedsund, Nicolas Ek (M&A), Tove Hallbäck (Arbetsrätt) och Simona Mullai (Fastighet).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-j2-sourcing-ab/","date":"2024-05-23","month":5},{"year":2024,"client":"Axcel","work":"Avyttring","disciplines":["M&A","Bank och finans","IT, Telekom och Outsourcing","Arbetsrätt","Fastigheter och Entreprenad","Immaterialrätt","GDPR","Corporate Crime & Compliance"],"title":"Vinge företräder Axcel i samband med försäljningen av Loopia Group till team.blue","caption":"Avyttring · 23 maj 2024","preamble":"Vinge företräder Axcel V i samband med försäljningen av Loopia Group till team.blue, Europas ledande digitala tjänsteleverantör för entreprenörer och små och medelstora företag och som stöds av Hg, en ledande investerare i Europeiska och transatlantiska mjukvaru- och tjänsteföretag.","body":"Med huvudkontor i Stockholm och med över 320 medarbetare är Loopia Group en ledande europeisk leverantör av webb- och hostingtjänster, med fokus på hållbarhet och grön hosting. Loopia Group har över 650 000 kunder i huvudsakligen Sverige, Finland, Slovakien, Tjeckien, Ungern och Serbien och en portfölj av lokala varumärken som bland annat innefattar Loopia, Websupport, Hostingpalvelu, Domainhotelli och Active24.\n\nTransaktionen är villkorad av regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Carl Sander, Egil Svensson och Alexander Rüdén (M&A), Marcus Glader, Sebastian Örndahl och Alva Chambert (Regulatory), Jolinn Uhlin, Ida Redander och Josef Groow (Banking and Finance), Mathilda Persson och Elis Allmark (Agreements and IT), Sam Seddigh, Narin Melazade och Jonatan Stentorp (Employment), Agnes Pigg (Real Estate), Axel Lennartsson (IP), Nicklas Thorgerzon och Siri Blomberg (GDPR), Mia Falk och Gulestan Ali (Compliance), Emy Rydén och Johanna Engström (Transaction Support Coordinators).\n\nLäs klientens pressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-i-samband-med-forsaljningen-av-loopia-group-till-team-blue/","date":"2024-05-23","month":5},{"year":2024,"client":"InArea Group","work":"Förvärv","disciplines":[],"title":"Vinge företräder InArea Group i samband med förvärv","caption":"Förvärv · 17 maj 2024","preamble":"Vinge företräder InArea Group AB i samband med förvärvet av Heikkinen och LTU Group. InArea Group är ett av Europas ledande och Sveriges största entreprenadföretag specialiserat på golvläggning, plattsättning samt golvavjämning.","body":"Förvärvet av Heikkinen och LTU Group innebär ett strategiskt viktigt steg in på den finländska marknaden. Efter förvärven uppgår koncernens samlade omsättning till cirka 3 miljarder SEK, med 1 400 medarbetare.\n\nVinges team bestod av Christian Lindhé, Anna Edström, Agaton Lindgren och Jonatan Karlsson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-inarea-group-i-samband-med-forvarv/","date":"2024-05-17","month":5},{"year":2024,"client":"Humana","work":"Förvärv","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Humana i dess förvärv av Team Olivia Norge AS","caption":"Förvärv · 17 maj 2024","preamble":"Humana-koncernen (”Humana”) stärker sitt erbjudande av kvalitativa omsorgstjänster i Norge genom att Human Care Holding AS (”Humana Norge”) har ingått avtal om att förvärva Team Olivia Norge AS för en köpeskilling om 341 miljoner svenska kronor på en kassa- och skuldfri basis.","body":"Förvärvet finansieras delvis genom en apportemission om 4 miljoner aktier till säljarna. Förvärvet förväntas bidra till en lägre operationell risk genom en mer diversifierad kundbas och bredare geografisk exponering.\n\nTransaktionen är föremål för godkännande av norska konkurrensmyndigheten och beräknas slutföras under andra kvartalet 2024. Humanas aktier är upptagna till handel på Nasdaq Stockholm, Mid Cap.\n\nVinges team består huvudsakligen av Linnéa Sellström, Anna Svensson och Maximilian Bengtsson (Kapitalmarknad och publik M&A).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-humana-i-dess-forvarv-av-team-olivia-norge-as/","date":"2024-05-17","month":5},{"year":2024,"client":"Stendörren","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Stendörren vid emission av gröna hybridobligationer och återköpserbjudande","caption":"Obligationsemission · 17 maj 2024","preamble":"Vinge biträder Stendörren Fastigheter AB vid dess emission av gröna efterställda hybridobligationer med evig löptid om SEK 300 miljoner (inom en ram om SEK 400 miljoner) och i samband med bolagets parallella återköpserbjudande till investerare i dess tidigare emitterade hybridobligationer.","body":"Hybridobligationerna emitterades med en ränta om STIBOR 3m + 550 baspunkter fram till första ordinarie inlösendag och de avses upptas till handel på Nasdaq Stockholms lista för gröna obligationer. Ett belopp motsvarande emissionslikviden ska användas i enlighet med Stendörrens gröna finansieringsramverk och för att återköpa utestående hybridobligationer. Stendörren har mottagit återköpsinstruktioner om ett totalt belopp om SEK 132 500 000 och avser att acceptera alla återköpsinstruktioner som har mottagits.\n\nSkandinaviska Enskilda Banken AB (publ) och Swedbank AB (publ) agerade arrangörer och joint bookrunners i samband med emissionen av de gröna hybridobligationerna och dealer managers i samband med återköpserbjudandet.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda och Calle Tengwall Pagels.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-stendorren-vid-emission-av-grona-hybridobligationer-och-aterkopserbjudande/","date":"2024-05-17","month":5},{"year":2024,"client":"Ebie","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Ebie vid kapitalanskaffning","caption":"Kapitalanskaffning · 17 maj 2024","preamble":"Vinge har företrätt proptech-bolaget Ebie (Rentfair AB) i samband med en kapitalanskaffning om 8 miljoner kronor i syfte att fortsätta expansionen av verksamheten.","body":"Ebie förmedlar en försäkringslösning i form av en hyresgaranti som frigör kapital åt företag som hyr lokaler som annars hade varit tvungna att låsa upp pengarna i en deposition eller bankgaranti. Bolaget grundades av Ville Löthén, Edvin Lindhout, Erik Larsson och André Brogärd och har haft en stark tillväxt under de senaste åren.\n\nI kapitalrundan som leddes av det belgiska proptech-fonden AMAVI Capital deltog även ett flertal nya och befintliga investerare, däribland SSE Ventures.\n\nVinges team bestod av Filip Öhrner och Tim Axell.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ebie-vid-kapitalanskaffning/","date":"2024-05-17","month":5},{"year":2024,"client":"Stockholm Exergi","work":"Avtal","disciplines":[],"title":"Vinge har biträtt Stockholm Exergi AB i samband med dess ingående av världens hittills största avtal om permanenta minusutsläpp, med Microsoft","caption":"Avtal · 16 maj 2024","preamble":"Vinge har biträtt Stockholm Exergi i samband med dess ingående av avtal med Microsoft om 3,33 miljoner ton permanenta minusutsläpp från Stockholm Exergis planerade bio-CCS-anläggning vid Värtan i Stockholm. Det är världens hittills största avtal om permanenta minusutsläpp.","body":"När Stockholm Exergis bio-CCS-anläggning är i drift kommer den att permanent avlägsna upp till 800 000 ton koldioxid från atmosfären varje år. Avtalet med Microsoft anses vara en viktig milstolpe för arbetet mot klimatförändringarna. Genom att åta sig ambitiösa och frivilliga klimatmål hoppas Microsoft och Stockholm Exergi att kunna bidra till branschens tillväxt för att göra det möjligt för företag att uppnå sina netto-nollmål och för länder att uppfylla målen i Parisavtalet. Läs mer här.\n\nVinges team bestod huvudsakligen av Michele Fara och Josua Fridh.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-stockholm-exergi-ab-i-samband-med-dess-ingaende-av-varldens-hittills-storsta-avtal-om-permanenta-minusutslapp-med-microsoft/","date":"2024-05-16","month":5},{"year":2024,"client":"Axcel och XPartners","work":"Förvärv","disciplines":["Bank och finans","M&A","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel och XPartners vid förvärv av Theta","caption":"Förvärv · 15 maj 2024","preamble":"Vinge har företrätt Axcel VII (”Axcel”) och XPartners Samhällsbyggnad (”XPartners”) vid förvärvet av THETA Engineering AB (”Theta”).","body":"Theta är ett konsultbolag med kompetens inom projektledning, berg och anläggning, projektstyrning, planering, kalkyl och kostnadsstyrning samt teknik.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Carl Fredrik Wachtmeister, Gustav Persson och Alexander Rüdén (M&A), August Ahlin (bank och finans), Clara Klingspor (Entreprenadrätt) samt Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-xpartners-vid-forvarv-av-theta/","date":"2024-05-15","month":5},{"year":2024,"client":"Axcel och XPartners","work":"Förvärv","disciplines":["Bank och finans","M&A","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel och XPartners vid förvärv av Projektkompaniet","caption":"Förvärv · 15 maj 2024","preamble":"Vinge har företrätt Axcel VII (”Axcel”) och XPartners Samhällsbyggnad (”XPartners”) vid förvärvet av Projektkompaniet i Motala AB (”Projektkompaniet”).","body":"Projektkompaniet är ett byggkonsultföretag med inriktning mot projekt- och byggledning, arkitektprojektering, storköksprojektering och konstruktion. Bolaget profilerar sig mot investeringsprojekt och erbjuder tjänster i alla skeden i byggprocessen där huvudsegmenten är inom offentliga och kommersiella projekt.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Carl Fredrik Wachtmeister, Gustav Persson och Alexander Rüdén (M&A), August Ahlin (bank och finans), Clara Klingspor (Entreprenadrätt) samt Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-xpartners-vid-forvarv-av-projektkompaniet/","date":"2024-05-15","month":5},{"year":2024,"client":"EQT Infrastructure VI","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","M&A","EU‑ och konkurrensrätt","Bank och finans","Fastigheter och Entreprenad","Arbetsrätt","GDPR","Corporate Crime & Compliance"],"title":"Vinge biträder EQT Infrastructure VI i budet på OX2","caption":"Övrigt · 13 maj 2024","preamble":"EQT Infrastructure VI, genom dess indirekt ägda dotterbolag Otello BidCo AB, lämnar ett rekommenderat uppköpserbjudande till aktieägarna i OX2 AB (publ) (”OX2”). Aktierna är upptagna till handel på Nasdaq Stockholm, Large Cap.","body":"OX2 grundades 2004 och är en ledande aktör inom förnybar energi med en stor och diversifierad projektportfölj inom alla etablerade tekniker inom förnybar energi (land- och havsbaserad vindkraft, solenergi och lagring) och är idag en av de största utvecklarna av landbaserad vindkraft i Europa.\n\nErbjudandets värde uppgår till cirka 16,4 miljarder kronor.\n\nVinges team består huvudsakligen av Sofie Bjärtun, Erik Sjöman, Linnéa Sellström, Joel Magnusson, Lorin Arabi och Maximilian Bengtsson (Kapitalmarknad och publik M&A), Christoffer Thalin, Peter Sundgren, Filip Öhrner, Daniel Daun, Niklas Törnell och Jonatan Karlsson (Energi, M&A), Sebastian Örndahl, Hampus Peterson, Lovisa Lewin och Ebba Ehrling Sjögren (Regulatory), Kamyar Najmi (Bank och finans), Lina Österberg, Tilda Hall och Agnes Pigg (Miljö och fastighet) Sam Seddigh och Alice Göransson (Arbetsrätt), Fredrika Hjelmberg och Ian Linde (IT/GDPR), Gulestan Ali (Compliance) och Julia Ulander Kull (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-eqt-infrastructure-vi-i-budet-pa-ox2/","date":"2024-05-13","month":5},{"year":2024,"client":"Fidelio Capital och Heart BidCo","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Fidelio Capital och Heart BidCo AB i samband med obligationsemission","caption":"Obligationsemission · 9 maj 2024","preamble":"Vinge biträder Fidelio Capital och Heart BidCo AB i samband med en emission om SEK 900 000 000 seniora säkerställda obligationer av Heart BidCo AB, moderbolaget i en koncern bestående av bland annat Hemfrid, Servly och andra ledande spelare inom hemtjänstsektorn i Sverige. Pareto Securities AB agerade sole bookrunner och issuing agent i transaktionen.","body":"Obligationerna ska enligt villkoren upptas till handel på Frankfurt Stock Exchange Open Market och Nasdaq Stockholms lista för företagsobligationer. Obligationerna har en löptid om 5 år och emitterades med en ränta på STIBOR 3m + 525 baspunkter.\n\nVinges team bestod av Albert Wållgren, Linn Adelwald, Lionardo Ojeda och August Ahlin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-fidelio-capital-och-heart-bidco-ab-i-samband-med-obligationsemission/","date":"2024-05-09","month":5},{"year":2024,"client":"Rite Ventures","work":"Offentligt uppköpserbjudande","disciplines":["Kapitalmarknad och publik M&A","Bank och finans"],"title":"Vinge biträder Rite Ventures i budpliktsbudet på Nelly","caption":"Offentligt uppköpserbjudande · 8 maj 2024","preamble":"Rite Internet Ventures Holding AB har, genom det helägda dotterbolaget Rite Ventures SPV AB, lämnat ett offentligt uppköpserbjudande till aktieägarna i Nelly Group AB (publ) enligt reglerna om budplikt. Budet värderar samtliga aktier i Nelly till cirka 500 miljoner kronor. Vinge företräder Rite Ventures.","body":"Vinges team bestod i huvudsak av David Andersson och Oskar Nilsson (Kapitalmarknad och publik M&A) samt Helena Göransson och Nour Makie (Bank och finans).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-rite-ventures-i-budpliktsbudet-pa-nelly/","date":"2024-05-08","month":5},{"year":2024,"client":"PropTech Energy","work":"Förvärv","disciplines":["M&A","GDPR","Arbetsrätt","IT, Telekom och Outsourcing"],"title":"Vinge företräder PropTech Energy i samband med dess förvärv av P2 Energi AB","caption":"Förvärv · 6 maj 2024","preamble":"PropTech Energy består av bolagen Ömangruppen och Axcell Fastighetspartner. Genom förvärvet av P2 Energi AB, ett energikonsultbolag inom värme-, ventilations- och kylteknik, stärker PropTech Energy sitt fokus på energieffektivitet.","body":"Vinges team bestod huvudsakligen av Jonas Johansson och Filip Magnusson (M&A), Carla Zachariasson (Avtal), Fredrika Hjelmberg (IT/GDPR) samt Narin Melazade (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-proptech-energy-i-samband-med-dess-forvarv-av-p2-energi-ab/","date":"2024-05-06","month":5},{"year":2024,"client":"Jernhusen","work":"Övrigt","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge har biträtt Jernhusen i samband med att detaljplan för omfattande stadsutveckling norr om Göteborgs Centralstation vunnit laga kraft","caption":"Övrigt · 2 maj 2024","preamble":"Detaljplanen för området norr om Centralstationen antogs av kommunfullmäktige i Göteborg den 22 april 2021 och har därefter överklagats i flera steg. Mark- och miljööverdomstolen meddelade, som sista instans, dom den 30 april 2024. Domstolen fastställer detaljplanen och nu kan planerna för Göteborgsregionens nya city intill Centralstationen börja ta form.","body":"Planområdet ligger mitt i regionens kärna och i ett av Göteborgs mest spännande utvecklingsområden; mellan Göteborgs Centralstation och uppgångarna till Västlänken (f.n. under byggnation). Detaljplanen medger en tät och hög bebyggelse som utöver stationsfunktioner kan användas för handel, kontor, service, hotell, bostäder, utbildning och vård. Detaljplanen omfattar byggnader i upp till 36 våningar, vilka bildar en grupp av högre byggnader med stark visuell effekt – en symbol för den växande staden och regionen.\n\nPlanområdet är helt integrerat i stationsområdet och målet är att bidra med innehåll för en blandad stad i den del av regionen där flest människor rör sig.\n\nPlanerad bruttoarea för byggnationen i området är cirka 140 000 kvm. Exploatör är Jernhusen AB.\n\nVinge har varit legal rådgivare till Jernhusen under projektets gång samt varit ombud i processen i Mark- och miljööverdomstolen. Vinges team bestod i huvudsak av advokaterna Robert Deli och Hampus Wahlberg.\n\nLäs mer om detaljplanen här: Pressmeddelande Jernhusen, Pressmeddelande Domstol.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-jernhusen-i-samband-med-att-detaljplan-for-omfattande-stadsutveckling-norr-om-goteborgs-centralstation-vunnit-laga-kraft/","date":"2024-05-02","month":5},{"year":2024,"client":"Aspo","work":"Förvärv","disciplines":["M&A","Bank och finans","Corporate Commercial","Arbetsrätt","Miljörätt","GDPR","IT, Telekom och Outsourcing","Fastigheter och Entreprenad","EU‑ och konkurrensrätt"],"title":"Vinge företräder Aspo vid förvärvet av Swed Handling","caption":"Förvärv · 30 april 2024","preamble":"Vinge företräder Aspo, noterat på Nasdaq Helsinki, i transaktionen där Aspos dotterbolag Telko expanderar sin kemiverksamhet i Sverige genom att förvärva Swed Handling, en ledande svensk kemidistributör, från TeRa Invest. Som en del av transaktionen expanderar Aspos dotterbolag Leipurin sin verksamhet inom livsmedelsindustrin i Sverige genom förvärvet av Kebelco, en distributör av tekniska livsmedelsingredienser, som är ett dotterbolag till Swed Handling. Slutförandet av transaktionen är föremål för sedvanliga godkännanden från myndigheter.","body":"Företagsvärdet i transaktionen uppgår till 500 MSEK, med möjlighet till en tilläggsköpeskilling om upp till 130 MSEK. Upp till 100 MSEK av köpeskillingen kan betalas med aktier i Aspo.\n\nAspo är ett finskt konglomerat som är specialiserat på krävande B-to-B-kunder. Aspo skapar värde genom att äga och utveckla affärsverksamheter på ett hållbart och långsiktigt sätt. Aspo har verksamhet i 16 olika länder och sysselsätter totalt cirka 700 medarbetare.\n\nLäs klientens pressmeddelande här.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Linus Adolfsson, Tim Axell (M&A), Karl-Gustaw Tobola (Banking and Finance), Mario Saad (Corporate Commercial), Ebba Svenburg, Jonna Skog (Employment) Johan Cederblad, Lina Österberg (Environment), Elis Allmark, Carla Zachariasson (IT & GDPR), Karolina Cohrs (Real Estate), Daniel Wendelsson, Sebastian Örndahl, Dagne Sabockis, Hilda Ivarsson (FDI, EU, Competition and Regulatory) och Emma Emsjö (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-aspo-vid-forvarvet-av-swed-handling/","date":"2024-04-30","month":4},{"year":2024,"client":"Vinnergi Holding","work":"Avyttring","disciplines":[],"title":"Vinge biträder vid försäljning av Vinnergi Holding AB","caption":"Avyttring · 30 april 2024","preamble":"Vinge har biträtt Sobro och övriga aktieägare vid försäljningen av Vinnergi Holding AB till Polaris, ett nordiskt riskkapitalbolag. I samband med transaktionen återinvesterar ledning och medarbetare en betydande del för att utveckla bolaget vidare. Vinnergi-koncernen är verksamt inom teknikkonsulttjänster och utveckling av mjukvara i Sverige, med särskilt fokus på telekom, energi och fastighet.","body":"Transaktionen är föremål för tillämpliga regulatoriska godkännanden.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Desirée Hagenfeldt, Michella Lina Said, Fanny Askelöf och Christoffer Widström.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-vinnergi-holding-ab/","date":"2024-04-30","month":4},{"year":2024,"client":"Pareto Securities","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har företrätt Pareto Securities i samband med en företrädesemission i Episurf Medical","caption":"Kapitalanskaffning · 24 april 2024","preamble":"Vinge har företrätt Pareto Securities i samband med en delvis garanterad företrädesemission av units om högst cirka 120 miljoner SEK i Episurf Medical.","body":"Episurf Medical är ett svenskt ortopediföretag i kommersiell fas och har en bred portfölj av produkter baserade på proprietär teknologi som adresserar ledskador. Episurf Medicals B-aktie är noterad på Nasdaq Stockholm.\n\nVinges team bestod av Dain Hård Nevonen, Anna Svensson och Pernilla Björklund.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-pareto-securities-i-samband-med-en-foretradesemission-i-episurf-medical/","date":"2024-04-24","month":4},{"year":2024,"client":"Ikano Bank","work":"Förvärv","disciplines":["Bank och finans","Arbetsrätt","M&A","Finansiella tillståndsfrågor","EU‑ och konkurrensrätt","Företagsbeskattning","Försäkring"],"title":"Vinge företräder Ikano Bank AB (publ) i samband med förvärv av en konsumentkreditportfolio från Nordnet Bank AB","caption":"Förvärv · 22 april 2024","preamble":"Vinge har företrätt Ikano Bank AB (publ) i samband med förvärv av en konsumentkreditportfolio från Nordnet Bank AB. Det slutgiltiga vederlaget kommer att baseras på utlånad volym i portfolion per tillträdesdagen. Per mars 2024 uppgick den utlånade volymen i portfolion till cirka 3,8 miljarder kronor. Förvärvet är villkorat av sedvanliga myndighetsgodkännanden.","body":"Vinges team bestod av Henrik Ossborn (bank och finans), Magnus Hedsund, Nicolas Ek, Irma Softic och Agaton Lindgren (M&A), Emelie Svensäter Jernstorp and Karin Hultgren (Arbetsrätt), Henrik Schön och David Flodin (Financial Services), Sofie Nordgren och Nathalie Wikman (FDI), David Olander (Konkurrens), Viveka Classon och David Gavatin (Corporate Insurance) och Ulf Nilsson (skatt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ikano-bank-ab-publ-i-samband-med-forvarv-av-en-konsumentkreditportfolio-fran-nordnet-bank-ab/","date":"2024-04-22","month":4},{"year":2024,"client":"Embracer Group","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt Embracer Group i samband med ingående av ett 900 miljoner euro bryggfinansieringsavtal med JP Morgan, BNP Paribas, SEB, Société Générale och Swedbank","caption":"Finansiering · 22 april 2024","preamble":"Vinge har biträtt Embracer Group AB (publ) (“Embracer”) och dess dotterbolag inom Asmodee i samband med ingåendet av ett bryggfinansieringsavtal om 900 miljoner euro med JP Morgan, BNP Paribas, SEB, Société Générale och Swedbank och sammanhängande förtida återbetalning av existerande skuld i Embracer.","body":"Embracer är en global koncern med entreprenörsdrivna företag inom spel- och underhållningsindustrin, där Asmodee är en fransk utvecklare av brädspel, kortspel och rollspel. Finansieringen är ett viktigt steg i Embracers refinansiering och omstruktureringsprogram och kommer att användas för att refinansiera Embracers befintliga lån på 8 miljarder kronor med förfall i februari 2025, samt för att minska de revolverande kreditfaciliteterna med 1 miljard kronor till 8 miljarder kronor.\n\nVinges team bestod av Louise Brorsson Salomon, Albert Wållgren, Felix Möller, Ida Redander och Josef Groow.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-embracer-group-i-samband-med-ingaende-av-ett-900-miljoner-euro-bryggfinansieringsavtal-med-jp-morgan-bnp-paribas-seb-societe-generale-och-swedbank/","date":"2024-04-22","month":4},{"year":2024,"client":"Trianon","work":"Obligationsemission","disciplines":["Kapitalmarknad och publik M&A","Bank och finans"],"title":"Vinge biträder Trianon i samband med riktad nyemission och återköpserbjudande av efterställda hållbara hybridobligationer","caption":"Obligationsemission · 19 april 2024","preamble":"Vinge biträder Fastighets Aktiebolaget Trianon (publ) i samband med en riktad nyemission om 184 miljoner kronor samt ett frivilligt återköpserbjudande avseende utestående efterställda hållbara hybridobligationer.","body":"Totalt återköptes hybridobligationer till ett sammanlagt nominellt belopp om 76 miljoner kronor. Betalning för återköpta hybridobligationer skedde genom kvittning mot nya B-aktier i bolaget. Teckningskursen i nyemissionerna fastställdes genom ett accelererat bookbuilding-förfarande.\n\nVinges team består av Christian Lindhé, Martin Madsen Svanberg, Agaton Lindgren, Jasmine Elgh och Johan Severinsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-trianon-i-samband-med-riktad-nyemission-och-aterkopserbjudande-av-efterstallda-hallbara-hybridobligationer/","date":"2024-04-19","month":4},{"year":2024,"client":"Blackstone","work":"Kapitalanskaffning","disciplines":["M&A","Arbetsrätt"],"title":"Vinge företräder Blackstone i samband med investering i Winthrop Technologies","caption":"Kapitalanskaffning · 17 april 2024","preamble":"Vinge, har biträtt Blackstone Tactical Opportunities och närstående fonder (\"Blackstone\") i samband med ett strategiskt partnerskap med Winthrop Technologies Limited (\"Winthrop Technologies \").","body":"Winthrop Technologies är Europas ledande leverantör av nyckelfärdiga datacenter.\n\nVinges team bestod av Jonas Bergström, Ulrich Ziche (M&A), Emil Lindwall, Melinda Oldenburg (Employment & Benefits) och Emelie Schoning (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-blackstone-i-samband-med-investering-i-winthrop-technologies/","date":"2024-04-17","month":4},{"year":2024,"client":"Hansa Biopharma","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har biträtt Hansa Biopharma i samband med en riktad nyemission om 372 miljoner kronor","caption":"Kapitalanskaffning · 16 april 2024","preamble":"Vinge har biträtt Hansa Biopharma AB (publ) i samband med en riktad nyemission varigenom bolaget tillförs 372 miljoner kronor före transaktionskostnader. Hansa Biopharma är ett biofarmabolag i kommersiell fas och en pionjär inom utveckling och kommersialisering av innovativa, livsavgörande och livsförändrande behandlingar för patienter med sällsynta immunologiska sjukdomstillstånd. Hansa Biopharmas stamaktie är noterad på Nasdaq Stockholm.","body":"Vinges team har bestått av Dain Hård Nevonen, Linnéa Sellström, Joel Magnusson, Adrian Filipovic och Karin Karsten.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-hansa-biopharma-i-samband-med-en-riktad-nyemission-om-372-miljoner-kronor/","date":"2024-04-16","month":4},{"year":2024,"client":"Triton","work":"Avyttring","disciplines":["M&A","Bank och finans","Rekonstruktioner och obestånd"],"title":"Vinge företräder Triton i samband med försäljningen av Norstat till Nalka Invest","caption":"Avyttring · 12 april 2024","preamble":"Vinge företräder Triton Smaller Mid-Cap Fund I (”Triton”) i samband med försäljningen av Norstat, ett ledande företag inom datainsamling för marknadsundersökningar, till Nalka Invest.","body":"Norstat är en av de ledande datainsamlarna för marknadsundersökningar i Europa. Norstat bistår mer än 2 000 marknadsundersökningsföretag, privata och offentliga slutkunder, mediebyråer, förlag och konsultföretag över olika branscher. Bolaget grundades i Norge 1997 och har sedan dess utökat sin geografiska närvaro till att omfatta Danmark, Sverige, Finland, Estland, Lettland, Litauen, Polen, Tyskland, Storbritannien, Frankrike, Schweiz, Nederländerna, Österrike och Italien.\n\nTransaktionen är föremål för tillämpliga regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Johanna Wiberg, Amanda Steen, Robin Fagerström, Filip Magnusson och Saga Meyer Viklund (M&A), Helena Göransson (Banking and Finance), Daniel Wendelsson, David Olander och Alva Chambert (Regulatory) och Ellinore Boström Andersson, Gabriella Balbo och Fanny Askelöf (Transaction Support Specialists).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-triton-i-samband-med-forsaljningen-av-norstat-till-nalka-invest/","date":"2024-04-12","month":4},{"year":2024,"client":"Sobro","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder Sobro vid investering i Clinton Marine Survey","caption":"Kapitalanskaffning · 9 april 2024","preamble":"Clinton Marine Survey har valt att bredda sitt ägande med Sobro som ny ägarpartner och majoritetsägare. Samtliga befintliga ägare kvarstår som betydande delägare. Clinton Marine Survey erbjuder högkvalitativa hydrografiska och geologiska undersökningar för navigering, muddringsoperationer, kartläggning, marint byggande med mera.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Gustav Persson, Madelene Andersson, Paula Bäckdén, Olivia Onwuta, Martin Boström, August Ahlin, Hilda Ivarson och Alva Chambert.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sobro-vid-investering-i-clinton-marine-survey/","date":"2024-04-09","month":4},{"year":2024,"client":"Helix Kapital","work":"Fondetablering","disciplines":["Private Funds","Företagsbeskattning"],"title":"Vinge har biträtt Helix Kapital vid fondetableringen av Helix Kapital Fund III","caption":"Fondetablering · 5 april 2024","preamble":"Vinge har biträtt Helix Kapital vid etableringen av Helix Kapitals tredje fond – Helix Kapital Fund III – som har stängts framgångsrikt med investeraråtaganden om drygt 1,5 miljarder kronor från en internationell investerarbas bestående av ett antal ledande finansiella institutioner. Investerarintresset i fondresningen var mycket starkt och fonden kraftigt övertecknad.","body":"Fonden kommer att investera i teknikdrivna nordiska small cap-bolag som specialiserar sig på modernisering av traditionella industrier genom att främja industriell innovation, hållbara framsteg och digital omvandling.\n\nVinges team bestod främst av Mattias Schömer, Martin Cronsioe, Emelie Svanberg, Semir Omerbasic, Viktoria Wnuk och Emelie Zingmark.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-helix-kapital-vid-fondetableringen-av-helix-kapital-fund-iii/","date":"2024-04-05","month":4},{"year":2024,"client":"Alrik Technologies","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Alrik Technologies i samband med seed investering från Pi Labs","caption":"Kapitalanskaffning · 3 april 2024","preamble":"Vinge har företrätt Alrik Technologies i samband med seed-finansiering från den globala VC investeraren Pi Labs.","body":"Alrik Technologies lanserades 2023 och erbjuder en SaaS-plattform för byggsektorn, som gör det möjligt för fastighetsutvecklare och byggare att mäta utsläppsmål samtidigt som logistiknätverket digitaliseras för att minska projektförseningar, leveranstider och kostnader. Alrik arbetar direkt med distributörer för att övervaka och optimera utsläpp från byggleveranser genom en enda enhetlig plattform, och har redan över 100 kunder.\n\nVinges team bestod av Jonas Johansson, Maria Dahlin Kolvik och Gustav Persson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-alrik-technologies-i-samband-med-seed-investering-fran-pi-labs/","date":"2024-04-03","month":4},{"year":2024,"client":"Tobii","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Tobii AB (publ) i samband med dess företrädesemission","caption":"Kapitalanskaffning · 3 april 2024","preamble":"Vinge har företrätt Tobii AB (publ) i samband med en fullt garanterad företrädesemission av stamaktier som tillför Tobii cirka 301 miljoner kronor före avdrag för transaktionskostnader.","body":"De nya stamaktierna som emitteras i företrädesemissionen beräknas bli föremål för handel på Nasdaq Stockholm omkring den 15 april 2024. Tobii utvecklar teknologi inom eyetracking och attention computing som förstår mänskligt beteende och intention. Tobiis eyetracking-lösningar används av tusentals företag, universitet och forskningsinstitutioner runt om i världen. Bolagets stamaktier är noterade på Nasdaq Stockholm.\n\nVinges team bestod i huvudsak av Jesper Schönbeck, Rikard Lindahl, Amanda Knutsson, Joel Magnusson, Oskar Nilsson, Lorin Arabi, Elias Kröger, Lovisa Jonassen och William Carlberg Johansson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-tobii-ab-publ-i-samband-med-dess-foretradesemission/","date":"2024-04-03","month":4},{"year":2024,"client":"Ellevio","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","M&A"],"title":"Vinge biträder Ellevio i budet på Dala Energi","caption":"Övrigt · 2 april 2024","preamble":"Elleviokoncernen, genom Ellevio Holding 1 AB, har lämnat ett offentligt uppköpserbjudande till aktieägarna i Dala Energi AB (publ). Budet värderar samtliga aktier i Dala Energi till cirka 2 229 miljoner kronor.","body":"Ellevio är ett av Sveriges största energibolag med cirka en miljon kunder. Ellevio ägs av OMERS Infrastructure, Tredje AP-fonden, Folksam och AMF.\n\nVinges team består av Peter Sundgren, Måns Håkanson och Filip Magnusson (M&A) samt David Andersson, Lorin Arabi och Maximilian Bengtsson (Kapitalmarknad och Publik M&A).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ellevio-i-budet-pa-dala-energi/","date":"2024-04-02","month":4},{"year":2024,"client":"Bilia","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge biträder Bilia vid refinansiering","caption":"Finansiering · 27 mars 2024","preamble":"Vinge biträder Bilia AB (publ) vid dess refinansiering av revolverande lån- och kreditfaciliteter på 2,3 miljarder kronor.","body":"Den nya kreditfaciliteten uppgår till 2 300 Mkr, varav 1 700 Mkr i revolverande lån och 600 Mkr i checkräkningskredit. De revolverande lånen har en löptid om tre år med möjlighet till förlängning (ett plus ett år) efter kreditgivarnas godkännande. DNB och Nordea är långivare under den nya kreditfaciliteten.\n\nLåneavtalet utgör tillsammans med utestående icke-säkerställda obligationer om 1 300 Mkr, i förhållande till vilka Vinge också biträtt Bilia, en väsentlig del av Bilias långsiktiga grundfinansiering.\n\nVinges team bestod av Anders Strid, Lionardo Ojeda, Sofia Haggren och Frithiof Hallgren Wallin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-bilia-vid-refinansiering/","date":"2024-03-27","month":3},{"year":2024,"client":"Energiteknikbolaget Flower","work":"Finansiering","disciplines":[],"title":"Vinge biträder energiteknikbolaget Flower i samband med kreditfaciliteter från Norion Bank","caption":"Finansiering · 27 mars 2024","preamble":"Vinge biträder det expansiva energiteknikbolaget Flower i samband med ingåendet av kreditfaciliteter med Norion Bank. Flower grundades 2020 och har på kort tid blivit Sveriges ledande aktör inom batterilagring och s.k. BESS (Battery Energy Storage Systems). Med sikte på snabb expansion mot utvalda europeiska marknader definieras Flowers resa av att kombinera banbrytande teknik med flexibla tillgångar, vilket möjliggör för samhällen drivna av hållbar energi.","body":"Medlen från kreditfaciliteterna ska användas till att, bland annat, finansiera Flowers framtida investeringar och expansion. Flower har siktet på en fortsatt expansion globalt, även om det aktuella tillskottet ska gå till att stärka positionen på den svenska marknaden.\n\nVinges team bestod av Albert Wållgren och Jolinn Uhlin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-energiteknikbolaget-flower-i-samband-med-kreditfaciliteter-fran-norion-bank/","date":"2024-03-27","month":3},{"year":2024,"client":"Arrangörer","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder arrangörer i samband med Sehlhall Fastigheters emission av hållbara obligationer och refinansiering","caption":"Obligationsemission · 26 mars 2024","preamble":"Vinge biträder arrangörerna i samband med Sehlhall Fastigheter AB:s (”Bolaget”) emission av seniora, säkerställda och hållbara obligationer om SEK 200 miljoner och i samband med ett parallellt förtida återinlösen av existerande obligationer emitterade i dess dotterbolag, Sehlhall Holding AB (”Dotterbolaget”).","body":"De nya obligationerna löper med en rörlig ränta om STIBOR 3M + 8.00% och förfaller i mars 2027. Bolaget avser att ansöka om upptagande till handel av de nya obligationerna på Nasdaq Stockholms lista för hållbara obligationer.\n\nEmissionen av de nya obligationerna tecknades genom återköp av utestående obligationer i Dotterbolaget samt mot kontant vederlag. Bolagets återköp skedde delvis genom att existerande obligationsinnehavare i Dotterbolaget betalat för nya obligationer med deras existerande obligationsinnehav och delvis mot utställande av efterställda reverser.\n\nSkandinaviska Enskilda Banken AB (publ) och Swedbank AB (publ) har agerat Joint Bookrunners. Swedbank AB (publ) har även agerat Sole Structuring Advisor för Bolagets hållbara ramverk.\n\nVinges team bestod av Albert Wållgren, Arvid Weimers, Lionardo Ojeda, Felix Möller, August Ahlin och Rebecka Margolin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-arrangorer-i-samband-med-sehlhall-fastigheters-emission-av-hallbara-obligationer-och-refinansiering/","date":"2024-03-26","month":3},{"year":2024,"client":"Amer Sports","work":"Börsnotering","disciplines":[],"title":"Vinge har företrätt Amer Sports, Inc. i samband med notering på NYSE med kreditfaciliteter och utgivande av obligationer","caption":"Börsnotering · 26 mars 2024","preamble":"Vinge har företrätt Amer Sports, Inc. i samband med noteringen av bolaget på New York Stock Exchange till ett värde av 1,37 miljarder dollar varvid Vinge bistått Amer Sports, Inc. och deras dotterbolag i regulatoriska frågor samt upptagandet av kreditfaciliteter om 500 miljoner dollar respektive 700 miljoner euro samt med utgivandet av seniora säkerställda obligationer om 800 miljoner dollar där de svenska dotterbolagen har ställt vissa säkerheter.","body":"Amer Sports är en global grupp av ikoniska sport- och friluftsvarumärken, inklusive Arc'teryx, Salomon, Wilson, Peak Performance och Atomic. Amer Sports har över 10.800 anställda och bedriver verksamhet i 41 länder.\n\nVinges team bestod av Fredrik Wilkens, Henrik Schön, David Flodin, Linn Adelwald, Arvid Weimers och Jolinn Uhlin.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-amer-sports-inc-i-samband-med-notering-pa-nyse-med-kreditfaciliteter-och-utgivande-av-obligationer/","date":"2024-03-26","month":3},{"year":2024,"client":"Smart Eye","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har biträtt Smart Eye i samband med kapitalanskaffning om 150 MSEK","caption":"Kapitalanskaffning · 22 mars 2024","preamble":"Vinge har biträtt Smart Eye Aktiebolag i samband med en riktad nyemission av aktier till svenska och internationella investerare som tillförde Smart Eye 150 MSEK. Teckningskursen uppgick till 91 SEK vilken fastställdes genom ett accelererat bookbuildingförfarande arrangerat av Carnegie.","body":"Vinges team bestod huvudsakligen av Anders Strid, Edin Agic och Hannah Mark.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-smart-eye-i-samband-med-kapitalanskaffning-om-150-msek/","date":"2024-03-22","month":3},{"year":2024,"client":"Triton","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt Triton i samband med försäljning av aktier i Ambea AB (publ)","caption":"Avyttring · 20 mars 2024","preamble":"Totalt placerades 7,7 miljoner aktier till ett pris om 57,50 kronor per aktie, motsvarande ett sammanlagt värde om cirka 443 miljoner kronor.","body":"Vinges team bestod av Sofie Bjärtun, Joel Magnusson och Karin Karsten.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-triton-i-samband-med-forsaljning-av-aktier-i-ambea-ab-publ-1/","date":"2024-03-20","month":3},{"year":2024,"client":"Hearst och CAMP","work":"Förvärv","disciplines":["GDPR","M&A","Företagsbeskattning","Arbetsrätt"],"title":"Vinge företräder Hearst och CAMP vid förvärvet av Avinode Group och mjukvaruprodukter för Aviation FBO","caption":"Förvärv · 18 mars 2024","preamble":"Läs klientens pressmeddelande.\n\nVinges team bestod huvudsakligen av Daniel Rosvall, Gustav Wahlberg, Linus Adolfsson, Klara Fäldt (M&A), Victor Ericsson, Emelie Svanberg, Erik Kochbati, Isabell Bitar (skatt), Sam Seddigh, Emil Lindwall (arbetsrätt) och Jolene Reimerson (GDPR).","body":null,"href":"https://www.vinge.se/uppdrag/vinge-foretrader-hearst-och-camp-vid-forvarvet-av-avinode-group-och-mjukvaruprodukter-for-aviation-fbo/","date":"2024-03-18","month":3},{"year":2024,"client":"Oncopeptides","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har företrätt Oncopeptides i samband med dess företrädesemission","caption":"Kapitalanskaffning · 14 mars 2024","preamble":"Vinge har företrätt Oncopeptides AB (publ) i samband med en fullt garanterad företrädesemission som tillför Oncopeptides cirka 300 miljoner kronor före avdrag för transaktionskostnader.","body":"Oncopeptides är ett biotechbolag inriktat på forskning, utveckling och kommersialisering av behandlingar mot svårbehandlade hematologiska sjukdomar. Bolaget använder sin patentskyddade PDC-plattform för att utveckla peptidlänkade läkemedel som snabbt och selektivt levererar cellgifter in i cancerceller.\n\nVinges team bestod av Dain Hård Nevonen, William Kåge, Joel Magnusson, Annie Fällström och Maximilian Bengtsson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-oncopeptides-i-samband-med-dess-foretradesemission/","date":"2024-03-14","month":3},{"year":2024,"client":"Vimian Group","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har företrätt Vimian Group i samband med dess företrädesemission","caption":"Kapitalanskaffning · 12 mars 2024","preamble":"Vinge har företrätt Vimian Group AB (publ) i samband med en delvis garanterad företrädesemission som tillför Vimian 1,633 miljarder kronor före avdrag för transaktionskostnader.","body":"Vimian är ett globalt djurhälsoföretag verksamt inom fyra snabbväxande segment: Specialty Pharma, MedTech, Veterinary Services och Diagnostics. Vimian anser att varje djur förtjänar den bästa tillgängliga vården. Därför sammanför Vimian framstående företag för att göra marknadens mest innovativa produkter och tjänster tillgängliga för fler veterinärer och djurägare.\n\nVinges team bestod av Dain Hård Nevonen, Linnéa Sellström, Anna Svensson, Michaela Ådén och Alexander Rüdén.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-vimian-group-i-samband-med-dess-foretradesemission/","date":"2024-03-12","month":3},{"year":2024,"client":"Bona","work":"Förvärv","disciplines":[],"title":"Vinge har företrätt Bona vid förvärv av Ezi Floor Products","caption":"Förvärv · 8 mars 2024","preamble":"Vinge har företrätt Bona AB i samband med förvärvet av dess distributör Ezi Floor Products (VIC) Pty Ltd i Australien.","body":"Bona är ett familjeägt företag som sedan 1919 levererar produkter och system för att installera, renovera och underhålla golv. Bona har fler än 600 anställda och fem fabriker runtom i världen. Genom 17 dotterbolag och distributörer finns Bona representerat i fler än 90 länder. Bonas huvudkontor ligger i Malmö och omsättningen 2022 uppgick till 3,6 miljarder kronor.\n\nVinge, genom Kristian Ford, har biträtt Bona.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-bona-vid-forvarv-av-ezi-floor-products/","date":"2024-03-08","month":3},{"year":2024,"client":"Annehem Fastigheter","work":"Kapitalanskaffning","disciplines":["M&A","Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Annehem Fastigheter AB (publ) i samband med dess företrädesemission","caption":"Kapitalanskaffning · 8 mars 2024","preamble":"Vinge har företrätt Annehem Fastigheter AB (publ) i samband med dess företrädesemission av A- och B-aktier, vilken tillför Annehem cirka 300 miljoner kronor före avdrag för transaktionskostnader.","body":"De nya B-aktierna som emitteras i företrädesemissionen beräknas bli föremål för handel på Nasdaq Stockholm omkring den 13 mars 2024. Annehem Fastigheter är ett tillväxtdrivet fastighetsbolag inriktat på kommersiella-, samhälls- och bostadsfastigheter i de nordiska tillväxtregionerna Stockholm, Skåne, Göteborg och Helsingfors. Fastighetsbeståndet i Annehem Fastigheter består av 26 förvaltningsfastigheter med ett värde om 4 412,7 Mkr och en uthyrbar yta om 202 tkvm per 31 december 2023. Bolagets B-aktier är noterade på Nasdaq Stockholm.\n\nVinges team bestod i huvudsak av Rikard Lindahl, Joel Magnusson, Oskar Nilsson, Michaela Ådén och Lovisa Jonassen.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-annehem-fastigheter-ab-publ-i-samband-med-dess-foretradesemission/","date":"2024-03-08","month":3},{"year":2024,"client":"BHG Group","work":"Förvärv","disciplines":["M&A","EU‑ och konkurrensrätt"],"title":"Vinge företräder BHG Group i samband med konsolidering av Hemfint Kristianstad och Arc E-Commerce samt förvärv av Trendrum","caption":"Förvärv · 7 mars 2024","preamble":"Två av BHG Group AB:s befintliga verksamheter, Hemfint Kristianstad AB med siten hemfint.se och Arc E-Commerce AB med siten Outl1.se, konsolideras. Samtidigt förvärvas Trendrum AB med siten trendrum.se. Tillsammans bildar de Hemfint Group vars omsättning 2023 uppgick proforma till cirka 800 Mkr.","body":"Trendrum förvärvas från dess grundare, som även är grundare till Hemfint, och BHG Group erlägger inget kontant vederlag för förvärvet. BHG Group förvärvar 67,5 procent av Trendrum mot en köpeskilling om 32,5 procent av koncernens innehav i Arc E-Commerce samt 16,3 procent av innehavet i Hemfint Kristianstad. Ägandet av dessa bolag kommer att ligga under det nybildade gemensamt ägda Hemfint Group som kommer att ägas till 67,5 procent av BHG Group och till 32,5 procent av ett av bl.a. grundarna till Trendrum och Hemfint gemensamt ägt bolag. Enligt avtalet mellan BHG och minoritetsägarna ska BHG förvärva minoritetens samtliga aktier uppdelat i trancher under perioden april 2025 till april 2028, till köpeskillingar som baseras på Hemfint Groups EBIT.\n\nTill följd av att Hemfint och Trendrum bland annat delägs av till verkställande direktören i Hemfint närstående bolag är transaktionen villkorad av godkännande från en extra bolagsstämma i BHG Group AB.\n\nVinges team bestod huvudsakligen av Kristian Ford, Niklas Törnell, Sophia Reutercrona, Jasmine Elgh och Markus Hedbys samt Pär Remnelid (konkurrensrätt).\n\nPressmeddelandet finns att läsa här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-bhg-group-i-samband-med-konsolidering-av-hemfint-kristianstad-och-arc-e-commerce-samt-forvarv-av-trendrum/","date":"2024-03-07","month":3},{"year":2024,"client":"Dr. Schär","work":"Övrigt","disciplines":["M&A","EU‑ och konkurrensrätt","Carve-Outs"],"title":"Vinge företräder Dr. Schär","caption":"Övrigt · 29 februari 2024","preamble":"Vinge företräder Dr. Schär i förvärvet av Semper AB:s glutenfria verksamhet. Det italienska företaget Dr. Schär producerar och utvecklar produkter för specialkost.","body":"Vinge företrädde Dr. Schär i förvärvet av Semper AB:s nordiska glutenfria verksamhet.\n\nVinge's team leddes av Wibeke Sorling (Partner, M&A), och bestod vidare av ett team som leddes av Anna Palmérus (Partner, EU & Konkurrensrätt), Jenny Sandlund (Senior Associate, M&A) samt Victoria Gunnerek (Senior Associate, EU & Konkurrensrätt)","href":"https://www.vinge.se/uppdrag/vinge-foretrader-dr-schar/","date":"2024-02-29","month":2},{"year":2024,"client":"Irisity","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A","M&A"],"title":"Vinge företräder Irisity AB i samband med förvärvet av Ultinous och en riktad nyemission","caption":"Kapitalanskaffning · 29 februari 2024","preamble":"Vinge företräder Irisity AB i samband med förvärvet av Ultinous och en riktad nyemission.","body":"Vinge företräder Irisity AB (publ) i samband med förvärvet av Ultinous Zrt, en svensk-ungersk AI-innovatör. Köpeskillingen, på kassa- och skuldfri basis och med antagande om normaliserat rörelsekapital, uppgår till 45 miljoner kronor kommer att betalas genom en apportemission om 9 000 000 nya aktier i Irisity till en teckningskurs om 5,00 kronor per aktie. I samband med förvärvet kommer Stockhorn Capital AB (grundat av Gustav Andersson och Inna Kaushan) att investera 45 miljoner kronor i Irisity genom en riktad nyemission på samma villkor som i apportemissionen, det vill säga 5,00 kronor per aktie. Transaktionen kommer att vara föremål för FDI-godkännande från svenska och ungerska myndigheter samt att Iristys extra bolagsstämma beslutar att bemyndiga styrelsen att besluta om nyemissionerna. Som en del av förvärvet och den riktade nyemissionen kommer Irisity och Stockhorn Capital även att ingå ett låneavtal enligt vilket Stockhorn Capital kommer att låna Irisity ett belopp om 15 miljoner kronor.\n\nVinges team består av Anders Strid, Edin Agic och Fredrik Löwenclou.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-irisity-ab-i-samband-med-forvarvet-av-ultinous-och-en-riktad-nyemission/","date":"2024-02-29","month":2},{"year":2024,"client":"Samhällsbyggnadsbolaget","work":"Partnerskap","disciplines":["Kapitalmarknad och publik M&A","Bank och finans","IT, Telekom och Outsourcing","GDPR","Fastigheter och Entreprenad"],"title":"Vinge har företrätt Samhällsbyggnadsbolaget i Norden AB (publ) (”SBB”) i samband med att SBB etablerar ett joint venture-bolag för samhällsfastigheter tillsammans med Castlelake, LP (\"Castlelake\").","caption":"Partnerskap · 29 februari 2024","preamble":"Vinge har företrätt Samhällsbyggnadsbolaget i Norden AB (publ) (”SBB”) i samband med att SBB etablerar ett joint venture-bolag för samhällsfastigheter tillsammans med Castlelake, LP (\"Castlelake\").","body":"SBB har ingått avtal om att bilda ett joint venture-bolag, SBB Infrastructure AB (”SBB Infrastucture”), tillsammans med fonder som förvaltas av den globala alternativa förvaltaren Castlelake. I samband med etableringen av joint venture-bolaget har SBB Infrastructure ingått ett låneavtal med Castlelake, om cirka 5,2 miljarder kronor. Fullföljande av transaktionen kommer att ske så snart som alla fullföljandevillkor har uppfyllts, vilket väntas ske i mars 2024.\n\nVinges team bestod huvudsakligen av Mikael Ståhl, Albert Wållgren, Helena Göransson, Rikard Lindahl, Ulrich Ziche, William Kåge, Kamyar Najmi, Jolinn Uhlin, Nour Makie, Ida Redander och Rebecka Margolin.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-samhallsbyggnadsbolaget-i-norden-ab-publ-sbb-i-samband-med-att-sbb-etablerar-ett-joint-venture-bolag-for-samhallsfastigheter-tillsammans-med-castlelake-lp-castlelake/","date":"2024-02-29","month":2},{"year":2024,"client":"Lantmännen","work":"Avyttring","disciplines":["M&A","Miljörätt","Kommersiella avtal"],"title":"Vinge företräder Lantmännen i samband med avyttringen av Gooh färdigrätter","caption":"Avyttring · 23 februari 2024","preamble":"Lantmännen Cerealia har tecknat ett avtal om att avyttra färdigmatsverksamheten under varumärket Gooh till Atria Sweden. Affären omfattar hela verksamheten, samt varumärket Gooh. All personal som idag arbetar i affärsområdet får erbjudande att följa med i överlåtelsen. Genom avyttringen fokuserar Lantmännen Cerealia verksamheten på spannmålsvärdekedjan.","body":"Gooh är ett välrenommerat varumärke med höga marknadsandelar i en kategori som sett en spännande utveckling under åren. Verksamheten började småskaligt i början av 2000-talet, men har utvecklats enormt och serverar idag ca 5 miljoner rätter årligen via försäljningsställen i hela Sverige. Sortimentet består av en blandning av traditionell svensk husmanskost och smaker från andra länder, såsom italienska pastarätter. Sortimentet har utvecklats kontinuerligt, men grunden i kock-lagade måltider med noggrant utvalda råvaror består. Tillverkningen sker i ett storkök i Järna i Södermanland.\n\nTransaktionen planeras genomföras genom att verksamheten överlåts till ett nybildat bolag, till vilket Atria Sweden blir ägare av samtliga aktier. Affären ska godkännas av berörda myndigheter och förväntas kunna slutföras senare under våren.\n\nVinges team bestod av Christina Kokko, Ulrich Ziche, Carl Sander och Clara Sohlberg (M&A), Johan Cederblad (Miljö) and Eva Fredrikson (Kommersiella avtal).\n\nLäs klientens pressmeddelande här","href":"https://www.vinge.se/uppdrag/vinge-foretrader-lantmannen-i-samband-med-avyttringen-av-gooh-fardigratter/","date":"2024-02-23","month":2},{"year":2024,"client":"Adelis Equity Partners","work":"Övrigt","disciplines":["Private Funds","Företagsbeskattning"],"title":"Vinge biträder Adelis Equity Partners vid etableringen av en continuation fund","caption":"Övrigt · 21 februari 2024","preamble":"Vinge har biträtt Adelis Equity Partners vid etableringen av en continuation fund till Adelis Equity Partners Fund II.","body":"Continuation-fonden är ett s.k. dual-asset vehicle som kommer att investera i Presto och HVD Group (Hantverksdata) – bägge befintliga portföljbolag i Adelis Equity Partners Fund II. Continuation-fonden, i vilken HarbourVest Partners blir den största investeraren, kommer att ha 430 miljoner euro i kapitalåtaganden och investera parallellt i portföljbolagen tillsammans med Adelis Equity Partners Fund III och Adelis team.\n\nVinges team har huvudsakligen bestått av Mattias Schömer, Nils Unckel, Martin Cronsioe, Emelie Svanberg, Anton Sjökvist och Viktoria Wnuk.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-adelis-equity-partners-vid-etableringen-av-en-continuation-fund/","date":"2024-02-21","month":2},{"year":2024,"client":"Axcel och XPartners","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel och XPartners vid förvärvet av Wavecon","caption":"Förvärv · 14 februari 2024","preamble":"Vinge har företrätt Axcel VII (”Axcel”) och XPartners Samhällsbyggnad (”XPartners”) vid förvärvet av Wavecon AB (”Wavecon”).","body":"Wavecon är ett konsultbolag som erbjuder kvalificerade projekt- och konsulttjänster inom två områden. Det ena området är omgivningskontroller vid byggprojekt, där Wavecon upprättar riskanalyser och hanterar kontrollprogram som efterföljs innan, under och efter vibrations- och bulleralstrande byggprojekt. Det andra området omfattar utförandet av mättekniska tjänster inom diverse byggprojekt, såsom projekteringsmätning, bygg- och anläggningsmätning, mängdberäkningar och mätning av spår/järnväg.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Karl Klackenberg, Carl Fredrik Wachtmeister, Gustav Persson, Egil Svensson, Sara Passandideh och Alexander Rüdén (M&A) och Clara Klingspor (Entreprenadrätt) samt Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-xpartners-vid-forvarvet-av-wavecon/","date":"2024-02-14","month":2},{"year":2024,"client":"Axcel och XPartners","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel och XPartners vid förvärvet av Projektstaben","caption":"Förvärv · 14 februari 2024","preamble":"Vinge har företrätt Axcel VII (”Axcel”) och XPartners Samhällsbyggnad (”XPartners”) vid förvärvet av Projektstaben i Sverige AB (”Projektstaben”).","body":"Projektstaben är verksamt inom projektledning och erbjuder projektledningsstöd i samhällsbyggnadsprojekt. Tjänster erbjuds inom byggarbetsmiljö, byggherrestöd, projektriskhantering, kostnads- och tidsriskanalyser, kravställning och ledning inom bygg- och anläggningstekniskt brandskydd, miljöskydd inom bygg- och anläggning, kvalitetsledning och krav-hantering samt inom hållbarhet.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Karl Klackenberg, Carl Fredrik Wachtmeister, Gustav Persson, Egil Svensson, Sara Passandideh, Filip Magnusson och Alexander Rüdén (M&A) och Clara Klingspor (Entreprenadrätt) samt Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-xpartners-vid-forvarvet-av-projektstaben/","date":"2024-02-14","month":2},{"year":2024,"client":"Axcel och XPartners","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel och XPartners vid förvärvet av P O Andersson","caption":"Förvärv · 14 februari 2024","preamble":"Vinge har företrätt Axcel VII (”Axcel”) och XPartners Samhällsbyggnad (”XPartners”) vid förvärvet av P O Andersson Konstruktionsbyrå Aktiebolag AB (”P O Andersson”).","body":"P O Andersson sysselsätter ett 20-tal civil-, högskole- och gymnasieingenjörer och är verksamma som konsulterande ingenjörer. Uppdragen omfattar i huvudsak projektering av anläggningar för olika system såsom luftbehandling, kyla, värme, vatten och avlopp, samt ramhandlingar för styr- och övervakning samt sprinkel. P O Andersson etablerades för över 40 år sedan och har omfattande erfarenheter av planering och projektering av olika typer av byggnadsprojekt och arbetar med kommersiella och offentliga lokaler, industrier, energicentraler och bostadsbyggande.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Karl Klackenberg, Carl Fredrik Wachtmeister, Gustav Persson, Egil Svensson, Sara Passandideh, Filip Magnusson och Alexander Rüdén (M&A) och Clara Klingspor (Entreprenadrätt) samt Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-xpartners-vid-forvarvet-av-p-o-andersson/","date":"2024-02-14","month":2},{"year":2024,"client":"Axcel och XPartners","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel och XPartners vid förvärvet av NXTLEV","caption":"Förvärv · 14 februari 2024","preamble":"Vinge har företrätt Axcel VII (”Axcel”) och XPartners Samhällsbyggnad (”XPartners”) vid förvärvet av NXTLEV Holding AB och dess dotterbolag (”NXTLEV”).","body":"NXTLEV specialiserar sig på bygg- och anläggningsbranschen och erbjuder kvalificerade tjänster inom projektledning, projekteringsledning, byggledning, m.m. NXTLEV är involverade i flera större projekt, däribland kapacitetsökning av Saltsjöbanan, Spårväg Syd, Förbifart Stockholm, Södertälje Sluss och Kanal.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Karl Klackenberg, Carl Fredrik Wachtmeister, Gustav Persson, Egil Svensson, Sara Passandideh, Filip Magnusson och Alexander Rüdén (M&A) och Clara Klingspor (Entreprenadrätt) samt Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-xpartners-vid-forvarvet-av-nxtlev/","date":"2024-02-14","month":2},{"year":2024,"client":"Axcel och XPartners","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel och XPartners vid förvärvet av Vibroakustik","caption":"Förvärv · 13 februari 2024","preamble":"Vinge har företrätt Axcel VII (”Axcel”) och XPartners Samhällsbyggnad (”XPartners”) vid förvärvet av Vibroakustik Sverige AB (”Vibroakustik”).","body":"Vibroakustik är ett konsultbolag specialiserat på att minska omgivningspåverkan och förbättra arbetsmiljön genom avancerade mät- och analystjänster. Inom omgivningspåverkan tar Vibroakustik ett helhetsgrepp om miljöutmaningar, med en betoning på riskanalyser, besiktningar samt mätning och analys av buller och vibrationer i syfte att säkerställa att större bygg- och infrastrukturprojekt efterlever miljökrav och att de negativa påverkningarna på omgivningen minimeras.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Karl Klackenberg, Carl Fredrik Wachtmeister, Gustav Persson, Sara Passandideh och Alexander Rüdén (M&A) och Clara Klingspor (Entreprenadrätt) samt Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-xpartners-vid-forvarvet-av-vibroakustik/","date":"2024-02-13","month":2},{"year":2024,"client":"Expedition Growth Capital","work":"Kapitalanskaffning","disciplines":["Arbetsrätt","Immaterialrätt","M&A"],"title":"Vinge företräder Expedition Growth Capital i samband med investering i Xensam","caption":"Kapitalanskaffning · 9 februari 2024","preamble":"Expedition Growth Capital har idag offentliggjort en investering om 40 miljoner dollar i det svenska SaaS-bolaget Xensam. Vinge rådgav Expedition Growth Capital i samband med investeringen.","body":"Xensam är en leverantör av en AI-driven Software Assessment Management-plattform (SAM). Plattformen möjliggör för dess kunder att förstå hur användare interagerar med applikationer, oavsett om de är SaaS eller on-premise, över hela deras digitala infrastruktur för att erbjuda en organisatorisk översikt över hybridmiljöer.\n\nExpedition Growth Capital är en Londonbaserad growth-fond med fokus på investeringar i snabbväxande företag.\n\nVinges team har bestått av Karl Klackenberg, Clara Sohlberg och Johan Gavelin (M&A), Rebecka Målquist (IP), Olivia Onwuta (Arbetsrätt) och Anna Ekdahl Roos (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-expedition-growth-capital-i-samband-med-investering-i-xensam/","date":"2024-02-09","month":2},{"year":2024,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["Arbetsrätt","Kapitalmarknad och publik M&A","IT, Telekom och Outsourcing","Immaterialrätt","GDPR","Fastigheter och Entreprenad","EU‑ och konkurrensrätt"],"title":"Vinge företräder Lagercrantz Group AB i samband med dess förvärv av Prido AB","caption":"Förvärv · 7 februari 2024","preamble":"Vinge företräder Lagercrantz Group AB i samband med dess förvärv av 96 % av aktierna i Prido AB. Prido AB grundandes 1973 och är idag en av Europas största tillverkare av högkvalitativa industriportar av vikportstyp, med en omsättning om cirka 300 miljoner SEK. Transaktionen är föremål för godkännande av relevanta myndigheter och förväntas slutföras under mars 2024.","body":"Vinges team bestod av Johan Winnerblad, Clara Sohlberg och Filip Magnusson (M&A), Victor Björkheim (Arbetsrätt), Ellis Allmark (Avtal), Sofia Bergenståhle (IPR), Johan Cederblad, Karolina Cohrs och Madelene Andersson (Fastighet och miljö), Ida Redander (Finansiering), Alva Chambert (Konkurrens) samt Arthur Kinski (IT/GDPR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-lagercrantz-group-ab-i-samband-med-dess-forvarv-av-prido-ab/","date":"2024-02-07","month":2},{"year":2024,"client":"1Vision Biogas","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","M&A","FDI","EU‑ och konkurrensrätt"],"title":"Vinge biträder 1Vision Biogas i samband med budet på Biokraft","caption":"Övrigt · 5 februari 2024","preamble":"1Vision Biogas AB, ett bolag kontrollerat av Aneo, HitecVision och St1, har lämnat ett offentligt erbjudande till aktieägarna i Biokraft International AB enligt reglerna om budplikt. Erbjudandet värderar aktierna i Biokraft till cirka 900 miljoner kronor. Vinge biträder 1Vision Biogas.","body":"Vinges team består av Christian Lindhé, Erik Sjöman, Martin Madsen Svanberg, Johan Åhman och Johan Severinsson (Kapitalmarknad och publik M&A), Jesper Ottergren (M&A) samt Sofie Nordgren, Pär Remnelid, Rikard Azelius och Jasmine Elgh (FDI/EU- och konkurrensrätt).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-1vision-biogas-i-samband-med-budet-pa-biokraft/","date":"2024-02-05","month":2},{"year":2024,"client":"Modular Finance","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Modular Finance i samband med förvärvet av BörsData Sverige","caption":"Förvärv · 5 februari 2024","preamble":"Vinge har företrätt Modular Finance, ett SaaS-företag som erbjuder ett utbud av nischprodukter riktade mot finansbranschen med fokus på unika datamängder och användarvänlighet, i samband med ingående av avtal om förvärv av aktierna i BörsData Sverige. BörsData Sverige är ett av Nordens största fristående analysverktyg för aktieinvesteringar.","body":"Genom förvärvet stärker Modular Finance sin position som en av Sveriges främsta SaaS-plattformar med inriktning mot finansbranschen.\n\nVinges team bestod av Christina Kokko, Karl Klackenberg, Viktor Lennartsson och Johan Gavelin.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-modular-finance-i-samband-med-forvarvet-av-borsdata-sverige/","date":"2024-02-05","month":2},{"year":2024,"client":"Zengun","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Zengun vid emission av hållbarhetslänkade obligationer och återköpserbjudande","caption":"Obligationsemission · 5 februari 2024","preamble":"Vinge biträder Zengun Group AB (publ) vid dess emission av seniora, säkerställda och hållbarhetslänkade obligationer om SEK 400 miljoner (inom en ram om SEK 600 miljoner) och i samband med bolagets parallella återköpserbjudande till investerare i dess tidigare emitterade obligationer med förfall under 2024. Obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms lista för hållbara obligationer. Obligationerna har en löptid om fyra år och emitterades med en ränta om STIBOR 3m + 635 baspunkter.","body":"Carnegie Investment Bank AB (publ) agerade som global coordinator, joint bookrunner och dealer manager, och Nordea Bank Abp agerade joint bookrunner och dealer manager i transaktionen.\n\nVinges team bestod av Magnus Pauli, Lionardo Ojeda, Arvid Weimers och Malin Waldén.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-zengun-vid-emission-av-hallbarhetslankade-obligationer-och-aterkopserbjudande/","date":"2024-02-05","month":2},{"year":2024,"client":"1","work":"Övrigt","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge har biträtt i samband med att detaljplan för etapp 1 av stadsdelen Västerport i Varberg vunnit laga kraft","caption":"Övrigt · 1 februari 2024","preamble":"Den 31 januari 2024 vann detaljplanen för etapp 1 av stadsdelen Västerport i Varberg laga kraft. Mark- och miljööverdomstolen ändrar mark- och miljödomstolens dom och fastställer Varbergs kommuns beslut att anta detaljplanen. Domen får inte överklagas.","body":"Planområdet ligger i centrala Varberg, cirka 300 meter nordväst om Varbergs torg. Varberg planerar för att utveckla en ny, attraktiv stadsdel som kopplar samman den nuvarande staden med havet. Planområdet har tidigare varit hamn. Genom flytt av färjehamn och industrihamn tillsammans med den nya järnvägslösningen i Varberg skapas ett stort utrymme för stadsutveckling i ett centralt läge. Denna detaljplan utgör den första etappen av den nya stadsdelen Västerport.\n\nDetaljplanen möjliggör uppförande av nya kvarter för bostäder och centrumfunktioner. Sammantaget ges möjligheten att uppföra cirka 500 nya bostäder med en genomsnittlig höjd av 5 våningar, lokaler för centrumändamål, förskola, parkeringshus samt en besöksanläggning på piren. Därutöver möjliggörs ett hotell med cirka 250 rum, som högst i 14 våningar.\n\nMark- och miljödomstolen upphävde detaljplanen av både formella och materiella skäl, bl.a. att detaljplanen skulle medföra s.k. påtaglig skada på riksintresset för kulturmiljövården Varberg. Efter skriftväxling och syn i målet meddelade Mark- och miljööverdomstolen sin dom, som alltså ändrar mark- och miljödomstolens dom och fastställer detaljplanen. Mark- och miljööverdomstolen anser inte att detaljplanen leder till s.k. påtaglig skada på riksintresset. Detaljplanen har därmed vunnit laga kraft.\n\nVinge biträdde Varbergs kommun i Mark- och miljööverdomstolen.\n\nVinges team bestod i huvudsak av advokaterna Robert Deli och Hampus Wahlberg.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-i-samband-med-att-detaljplan-for-etapp-1-av-stadsdelen-vasterport-i-varberg-vunnit-laga-kraft/","date":"2024-02-01","month":2},{"year":2024,"client":"Nordic Nest","work":"Förvärv","disciplines":["Arbetsrätt","Kapitalmarknad och publik M&A"],"title":"Vinge företräder Nordic Nest i samband med förvärv av KitchenTime","caption":"Förvärv · 24 januari 2024","preamble":"Vinge har företrätt Nordic Nest Group AB, ett bolag inom BHG Group, i samband med inkråmsförvärv av KitchenTimes varumärke och varulager till en total köpeskilling om upp till 65 MSEK. Tillträde beräknas ske den 1 april 2024.","body":"Nordic Nest är idag Nordens ledande aktör inom premiumsegmentet som helhet genom varumärkena Nordic Nest och Svenssons. KitchenTime är en av marknadsledarna i Norden inom matlagnings-, serverings- och köksprodukter, vilka är marknader och produktkategorier där Nordic Nest redan har en ledande position.\n\nVinges team bestod huvudsakligen av Kristian Ford och Niklas Törnell (M&A) samt Emelie Svensäter Jerntorp (arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-nordic-nest-i-samband-med-forvarv-av-kitchentime/","date":"2024-01-24","month":1},{"year":2024,"client":"HAKI Safety","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder HAKI Safety i samband med avyttringen av FAS Converting Machinery till CMD","caption":"Avyttring · 24 januari 2024","preamble":"FAS Converting Machinery är en global verksamhet som utvecklar, producerar och säljer maskinutrustning för konvertering av plastfilmsmaterial till produkter på rulle.","body":"Med maskinutrustningen tillverkar kunder exempelvis avfallspåsar och engångsförkläden i polyetenplast och industrifilm. Avyttringen är ett led i HAKI Safetys strategiomläggning, från ett konglomerat till dagens industrikoncern med fokus på säkerhetsprodukter och -lösningar på tillfälliga arbetsplatser.\n\nVinges team bestod av Anna Edström tillsammans med Jasmine Elgh (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-haki-safety-i-samband-med-avyttringen-av-fas-converting-machinery-till-cmd/","date":"2024-01-24","month":1},{"year":2024,"client":"La Française des Jeux SA","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","Bank och finans"],"title":"Vinge biträder La Française des Jeux SA i budet på Kindred Group plc","caption":"Övrigt · 22 januari 2024","preamble":"La Française des Jeux SA, Frankrikes nationella lotteri och ledande betting- och speloperatör, har lämnat ett rekommenderat uppköpserbjudande till aktieägarna i Kindred Group plc avseende de depåbevis i Kindred Group plc som är upptagna till handel på Nasdaq Stockholm. Genom transaktionen stärker La Française des Jeux SA sin position i Europa inom spel och betting.","body":"Med sin portfölj av välkända varumärken erbjuder Kindred Group plc underhållning i en säker, trygg och hållbar miljö för 1,6 miljoner aktiva kunder. Genom transaktionen bildas en ledande europeisk spelaktör med ökad skalbarhet, tekniska möjligheter och större diversifiering. Transaktionen är också förenlig med klassledande hållbarhet och ansvarsfullt spelande.\n\nErbjudandets värde uppgår till cirka 28 miljarder kronor. Vinge biträder La Française des Jeux SA.\n\nVinges team består av David Andersson, Erik Sjöman, William Kåge, Gabriel Chabo och Isabell Bitar (Kapitalmarknad och publik M&A) samt av Louise Brorsson Salomon och Helena Göransson (Bank och finans).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-la-francaise-des-jeux-sa-i-budet-pa-kindred-group-plc/","date":"2024-01-22","month":1},{"year":2024,"client":"PSG Equity","work":"Kapitalanskaffning","disciplines":["M&A","Immaterialrätt","Arbetsrätt","Kommersiella avtal","IT, Telekom och Outsourcing","GDPR","Företagsbeskattning","Bank och finans","Fastigheter och Entreprenad"],"title":"Vinge företräder PSG Equity vid investering i Visit Group International AB","caption":"Kapitalanskaffning · 22 januari 2024","preamble":"Vinge har företrätt den internationella private equity-firman PSG Equity i samband med dess investering i Visit Group International AB (\"Visit Group\").","body":"Visit Group, med huvudkontor i Göteborg, är marknadsledande i Norden inom hotell- och reseteknik och tillhandahåller programvara för kollaborativ handel till leverantörer av destinationsupplevelser inklusive logi, dagsturer och attraktioner, bergsresorter, färjerederier, nöjesparker och aktivitetsleverantörer. Per augusti 2023 leverare bolaget till fler än 2 200 kunder i över 25 länder. Visit Groups olika mjukvarulösningar skapar ett unikt ekosystem som hjälper hotell- och reseleverantörer att paketera, sälja, distribuera och leverera gästupplevelser.\n\nPSG är ett private equity-bolag inom tillväxt som samarbetar med mjukvaru- och teknikbaserade tjänsteföretag för att hjälpa dem att navigera i transformativ tillväxt, kapitalisera på strategiska möjligheter och bygga starka team. PSG har stöttat mer än 130 företag och hanterat över 470 tilläggsförvärv och bidrar med omfattande investeringserfarenhet, djup expertis inom programvara och teknik samt ett åtagande att samarbeta med ledningsgrupper.\n\nMed PSG:s stöd kommer Visit Group att investera för att påskynda både organisk och icke-organisk tillväxt i regionen genom att bredda utbudet och omfattningen av lösningarna som erbjuds till dess kunder. Transaktionen är PSG:s första plattformsinvestering i Sverige och Norge.\n\nVinges team bestod huvudsakligen av Christina Kokko, Samra Tesser, Gustav Wahlberg och Jonatan Stentorp (M&A), Axel Lennartsson (IP), Gulestan Ali (Arbetsrätt), Martin Boström (Avtal), Carla Zachariasson (IT), Arthur Kinski (GDPR), Maja Höglund (Compliance), Karl-Gustaw Tobola och August Ahlin (Finansiering), Frida Ställborn (Fastighet) samt Emma Emsjö och Johanna Engström (Transaction Support Coordinators).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-psg-equity-vid-investering-i-visit-group-international-ab/","date":"2024-01-22","month":1},{"year":2024,"client":"Attendo","work":"Förvärv","disciplines":["M&A","IT, Telekom och Outsourcing","Fastigheter och Entreprenad","Arbetsrätt","GDPR","Corporate Crime & Compliance","EU‑ och konkurrensrätt","Bank och finans","Immaterialrätt","Finansiella tillståndsfrågor","Offentlig upphandling","Carve-Outs"],"title":"Vinge företräder Attendo i samband med förvärvet av Team Olivias omsorgsverksamhet","caption":"Förvärv · 17 januari 2024","preamble":"Vinge har företrätt Attendo, Nordens största omsorgsföretag, i samband med ingående av avtal för förvärv av Team Olivias svenska omsorgsverksamhet (exklusive personlig assistans). Attendo stärker därmed positionen inom omsorg för personer med funktionsnedsättningar (LSS), Individ-och familjeomsorg (IOF) samt hemtjänst i Sverige.","body":"Förvärvet innebär att cirka 120 omsorgsverksamheter med omkring 3 200 kunder och nära 3 000 medarbetare blir en del av Attendo-koncernen. Team Olivia bedriver en högspecialiserad verksamhet för personer med komplexa omsorgsbehov inom LSS och IOF, vilket kompletterar Attendos befintliga verksamheter inom dessa områden väl. Affären beräknas ge tydliga skalfördelar vilket innebär ökade resurser till kvalitetsutveckling, digitalisering och förbättring av arbetssätt i det omsorgsnära arbetet. Den förvärvade verksamheten har en årsomsättning på cirka 1,350 miljoner kronor med ett leasejusterat rörelseresultat på cirka 130 miljoner kronor.\n\nKöpeskillingen uppgår på kassa och skuldfri basis till 950 miljoner kronor.\n\nVinges team bestod huvudsakligen av Jonas Bergström, Joacim Rydergård, Carl Sander, Isabelle Wållgren, Gustav Wahlberg och Sara Passandideh (M&A), Mathilda Persson och Elis Allmark (IT), Christoffer Nordin (Tillstånd), Frida Ställborn och Madelene Andersson (Fastighet), Simon Söderholm och Olivia Onwuta (Arbetsrätt), Nicklas Thorgenzon (GDPR), Karl-Gustaw Tobola och Sofia Haggren (Finansiering), Sofia Bergenstråhle (IP), Julia Löfqvist och Maja Höglund (Compliance), Sebastian Öhrndahl, Daniel Wendelson, Lovisa Lewin, Dagne Sabockis och Hilda Ivarsson (Regulatory), Kristoffer Sällfors (Offentlig upphandling) samt Emy Rydén och Christoffer Widström (Transaction Support Coordinators).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-attendo-i-samband-med-forvarvet-av-team-olivias-omsorgsverksamhet/","date":"2024-01-17","month":1},{"year":2024,"client":"Viva Media","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Viva Media vid förvärv av ID Kommunikation","caption":"Förvärv · 12 januari 2024","preamble":"Vinge har biträtt marknadsföringsbyrån Viva Media vid förvärvet av den Malmöbaserade kommunikationsbyrån ID Kommunikation. Efter förvärvet har Viva Media kontor i Uppsala, Kalmar, Malmö och Oslo med totalt över 100 medarbetare.","body":"Vinges team bestod av Johan Winnerblad, Tim Axell och Olivia Onwuta.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-viva-media-vid-forvarv-av-id-kommunikation/","date":"2024-01-12","month":1},{"year":2024,"client":"Santander Consumer Finance","work":"Förvärv","disciplines":["M&A","Kommersiella avtal","GDPR","Bank och finans","Fastigheter och Entreprenad","Finansiella tillståndsfrågor","Försäkring","Immaterialrätt","Arbetsrätt"],"title":"Vinge företräder Santander Consumer Finance vid förvärv av Athlon Sweden AB","caption":"Förvärv · 9 januari 2024","preamble":"Vinge företräder Santander Consumer Finance vid förvärv av samtliga aktier i Athlon Sweden AB, en del av Mercedes-Benz Mobility.","body":"Athlon Sweden AB, verksamt inom billeasing och fleet management, har sitt huvudkontor i Malmö och bedriver försäljning även i Stockholm. Företaget har under de senaste fem åren visat betydande tillväxt och hanterar för närvarande en portfölj med 5 200 person- och transportbilar. De utgör den nionde största aktören på den svenska marknaden.\n\nTransaktionens genomförande är villkorat av sedvanliga regulatoriska godkännanden.\n\nVinges team bestod av Christina Kokko tillsammans med Isabelle Wållgren, Robin Fagerström (M&A), Christoffer Nordin, Sam Fakhraie Ardekani (Commercial Agreements), Lisa Hörnqvist (GDPR/IT), Emma-Stuart Beck, Caroline Krassén, Elias Bohlin (Financial Services), David Flodin (Banking and Finance), Jonna Bondemark (Insurance Regulatory), Axel Lennartsson (IPR), Madelene Andersson (Real Estate), Gulestan Ali (Employment), Fanny Askelöf (Transaction Support Specialist), och Emma Emsjö (Project Assistant).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-santander-consumer-finance-vid-forvarv-av-athlon-sweden-ab/","date":"2024-01-09","month":1},{"year":2024,"client":"EQT Healthcare Growth","work":"Förvärv","disciplines":["IT, Telekom och Outsourcing","GDPR","Arbetsrätt","Fastigheter och Entreprenad","Immaterialrätt","Bank och finans","Kommersiella avtal","Företagsbeskattning","EU‑ och konkurrensrätt"],"title":"Vinge företräder EQT Healthcare Growth i samband med dess förvärv av Mabtech","caption":"Förvärv · 9 januari 2024","preamble":"Vinge företräder EQT Healthcare Growth, en ny dedikerad förvärvsstrategi inom hälso- och sjukvårdssektorn introducerad av EQT, i samband med dess första investering – förvärvet av bioteknikföretaget Mabtech, från IK Small Cap II Fund och flertalet minoritetssäljare.","body":"EQT Healthcare Growth är en ny förvärvsstrategi som bygger på EQT:s 30-åriga erfarenhet inom hälso- och sjukvårdssektorn, med fokus på att skala upp innovativa, snabbväxande hälso- och sjukvårdsföretag för att bidra till positiva resultat över hela värdekedjan. Genom att hjälpa företag att stärka sina kommersiella muskler och expandera global räckvidd syftar strategin till att möjliggöra utvecklingen av medicinsk forskning, diagnostik, verktyg och behandlingar för att leverera mer effektiv och tillgänglig vård.\n\nMabtech är en ledande leverantör av tester och kit för studier av immunförsvar, främst inom vaccin, infektionssjukdomar och onkologisk forskning. Företaget är baserat i Sverige och har över 900 kunder i fler än 60 länder. EQT Healthcare Growth kommer att stödja Mabtech i dess strävan att expandera sin tillväxt och räckvidd.\n\nTransaktionen är föremål för sedvanliga villkor och godkännanden och förväntas slutföras under Q1 2024.\n\nVinges team bestod av Christina Kokko, Johanna Wiberg, Viktor Lennartsson, Robin Sultani och Filip Magnusson (M&A), Stojan Arnerstål och Rebecka Målquist (IPR), Louise Brorsson Salomon, Helena Göransson, Kamyar Najmi och August Ahlin (Finansiering), Christoffer Nordin och Rebecka Danelius Gedin (Avtal och Tillstånd), Mika Jordan och Elis Allmark (IT), Nicklas Thorgerzon och Lisa Hörnqvist (GDPR), Gulestan Ali (Arbetsrätt), Kristoffer Larson (Fastigheter), Mia Falk, Sam Fakhraie Ardekani och Maja Höglund (Compliance och Sanktioner), Sebastian Örndahl, Daniel Wendelsson, Dagne Sabockis, Lovisa Lewin och Hilda Ivarson (Regulatory) och Gabriella Balbo (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-eqt-healthcare-growth-i-samband-med-dess-forvarv-av-mabtech/","date":"2024-01-09","month":1},{"year":2024,"client":"Byggfakta","work":"Övrigt","disciplines":["EU‑ och konkurrensrätt","Bank och finans"],"title":"Vinge biträder Byggfakta i samband med budet från Giant BidCo","caption":"Övrigt · 5 januari 2024","preamble":"Vinge biträder Byggfakta Group Nordic HoldCo AB (publ) i samband med att Stirling Square, TA Associates och Macquarie Capital, genom Giant BidCo, har lämnat ett uppköpserbjudande till aktieägarna i Byggfakta. Erbjudandet motsvarar 46 kronor per aktie och värderar Byggfakta till cirka 10,1 miljarder kronor.","body":"Vinges team består huvudsakligen av Anders Strid och Edin Agic samt Anna Palmérus (EU & Antitrust) och Albert Wållgren (Banking & Finance).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-byggfakta-i-samband-med-budet-fran-giant-bidco/","date":"2024-01-05","month":1},{"year":2023,"client":"Lantmännen","work":"Förvärv","disciplines":["M&A","Miljörätt","Fastigheter och Entreprenad","EU‑ och konkurrensrätt","GDPR","Kommersiella avtal","Arbetsrätt","Immaterialrätt","Corporate Crime & Compliance","Carve-Outs"],"title":"Vinge företräder Lantmännen i samband med förvärvet av HKScans svenska verksamhet","caption":"Förvärv · 30 december 2023","preamble":"Lantmännen har tecknat avtal om att förvärva HKScan Corporations svenska verksamhet, HKScan Sweden AB. Förvärvet omfattar all verksamhet i Sverige samt varumärkena Scan, Pärsons och Bullens. Förvärvet innebär att Lantmännen breddar och stärker sin affärsportfölj från jord till bord - och att de långsiktiga förutsättningarna för svenskt lantbruk stärks.","body":"HKScans svenska verksamhet erbjuder kött- och växtbaserade livsmedel från svenska gårdar, sysselsätter cirka 1 800 personer och hade 2022 en nettoomsättning på cirka 8 miljarder SEK. Den svenska verksamheten har produktionsanläggningar i Kristianstad, Skara, Linköping och Halmstad - och har sitt svenska huvudkontor i Stockholm.\n\nI samband med förvärvet överlåter Lantmännen även samtliga sina befintliga aktier i HKScan Corporation till HKScan Corporation. Transaktionen är föremål för godkännande av relevanta myndigheter och förväntas slutföras under första halvåret 2024.\n\nVinges team bestod av Christina Kokko, Karl Klackenberg, Clara Sohlberg och Robin Sultani (M&A), Johan Cederblad (Miljö), Kristoffer Larsson och Alexandra Tamm (Fastighet), Trine Osen Bergqvist och Jesper Ekman (Konkurrensrätt), Malin Malm Waerme och Johan Gavelin (IP), Lisa Hörnqvist (GDPR), Eva Fredriksson, Jolene Reimerson och Carla Zachariasson (IT och kommersiella avtal), Mia Falk och Julia Löfquist (Regulatory), Agnes Pigg (Arbetsrätt) och Emy Rydén (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-lantmannen-i-samband-med-forvarvet-av-hkscans-svenska-verksamhet/","date":"2023-12-30","month":12},{"year":2023,"client":"Nordic Road Safety","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljning av Nordic Road Safety","caption":"Avyttring · 22 december 2023","preamble":"Vinge har biträtt ägaren av Nordic Road Safety AB vid försäljning av 85% av aktierna till Lagercrantz Group AB. Nordic Road Safety är en ledande leverantör inom utveckling, konsultation, försäljning, projektledning och installation av permanent vägsäkerhet i form av vägräckessystem och bullerskydd och omsätter ca. 350 MSEK med ett rörelseresultat om ca 50 MSEK.","body":"Förvärvet är villkorat av myndigheters godkännande.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Eléonore Friberg och Narin Melazade.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-nordic-road-safety/","date":"2023-12-22","month":12},{"year":2023,"client":"Active Biotechs","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder i Active Biotechs företrädesemission","caption":"Kapitalanskaffning · 21 december 2023","preamble":"Active Biotech AB (publ) (Nasdaq Stockholm) har genomfört en nyemission med företrädesrätt för aktieägarna om cirka 51 MSEK.","body":"Vinge biträder Active Biotech. Vinges team består av Erik Sjöman, Christian Lindhé, Agaton Lindgren och Jasmine Elgh.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-i-active-biotechs-foretradesemission-1/","date":"2023-12-21","month":12},{"year":2023,"client":"Trianon","work":"Obligationsemission","disciplines":["Kapitalmarknad och publik M&A","Bank och finans"],"title":"Vinge biträder Trianon i samband med återköpserbjudande avseende efterställda hållbara hybridobligationer","caption":"Obligationsemission · 21 december 2023","preamble":"Vinge biträder Fastighets Aktiebolaget Trianon (publ) i samband med dess frivilliga partiella återköpserbjudande avseende befintliga efterställda hållbara hybridobligationer. Totalt återköptes hybridobligationer till ett sammanlagt nominellt belopp om 370 miljoner kronor. Betalning för återköpta hybridobligationer skedde genom kvittning mot nya B-aktier i bolaget.","body":"Vinges team består av Christian Lindhé, Martin Madsen Svanberg, Arvid Weimers och Johan Severinsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-trianon-i-samband-med-aterkopserbjudande-avseende-efterstallda-hallbara-hybridobligationer/","date":"2023-12-21","month":12},{"year":2023,"client":"Svea Bank","work":"Kapitalanskaffning","disciplines":["Bank och finans"],"title":"Vinge har biträtt Svea Bank AB i samband med dess emission av primärkapitaltillskott (AT1) om 300 miljoner SEK för att optimera sin kapitalstruktur.","caption":"Kapitalanskaffning · 20 december 2023","preamble":"Vinge har biträtt Svea Bank AB (“Bolaget”) vid dess emission av AT1-obligationer om 300 miljoner SEK med en rörlig kupong om 3-månaders STIBOR + 7.50%.","body":"Emissionsdagen är satt till den 20 december 2023 och obligationerna har en evig löptid med första möjliga inlösendag efter 5 år. Emissionen sker i form av skuldinstrument med automatisk nedskrivning av dess nominella belopp om Bolagets kärnprimärkapitalkvot faller under en viss nivå. Instrumenten kommer att noteras på Nasdaq Stockholm.\n\nVinges team bestod av Mikael Ståhl, Arvid Weimers och Sofia Haggren.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-svea-bank-ab-i-samband-med-dess-emission-av-primarkapitaltillskott-at1-om-300-miljoner-sek-for-att-optimera-sin-kapitalstruktur/","date":"2023-12-20","month":12},{"year":2023,"client":"EQT X","work":"Kapitalanskaffning","disciplines":["M&A","Bank och finans","Arbetsrätt","Kommersiella avtal","Immaterialrätt","EU‑ och konkurrensrätt"],"title":"Vinge företräder EQT X i samband med dess investering i HVD Group och Next One Technology","caption":"Kapitalanskaffning · 20 december 2023","preamble":"Vinges företräder EQT X (\"EQT Private Equity\") i samband med dess investering i de nordiska mjukvarubolagen HVD Group (Hantverksdata) och Next (Next One Technology). Båda bolagen är verksamma inom hantverks- och byggbranschen, där HVD Group är inriktat på installations- och serviceyrken, såsom elektriker, rörmokare, värme- och ventilationsföretag, medan Next är inriktat på byggentreprenörer. HVD Groups plattform kompletterar Next, och investeringen banar väg för ett förstärkt produktutbud på basis av båda bolagens starka kundnöjdhet.","body":"EQT Private Equity kommer att investera i HVD Group och Next tillsammans med den befintliga aktieägaren i HVD Group, Adelis, som kommer att utöka sin investering i det nya kombinerade bolaget.\n\nBåda transaktionerna förväntas slutföras i februari 2024.\n\nVinges team bestod av Christina Kokko, Karl Klackenberg, Elsie Nassar, Amanda Steen, Maximilian Bengtsson och Jonatan Stentorp (M&A), Louise Brorsson Salomon och Jolinn Uhlin (Bank och Finans), Marcus Glader, Daniel Wendelsson, Sebastian Örndahl, David Olander och Adam Löfquist (Regulatory), Axel Lennartsson (IP), Mathilda Persson, Jolene Reimerson, Lisa Hörnqvist och Mario Saad (IT och GDPR), Christoffer Nordin, Carl Lexenberg och Arthur Kinski (Kommersiella avtal), Emil Lindwall och Victor Björkheim (Arbetsrätt) och Emelie Schoning (Transaction Support Coordinator).\n\nLäs klientens pressmeddelande","href":"https://www.vinge.se/uppdrag/vinge-foretrader-eqt-x-i-samband-med-dess-investering-i-hvd-group-och-next-one-technology/","date":"2023-12-20","month":12},{"year":2023,"client":"Annehem Fastigheter","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Annehem Fastigheter vid förvärv av fastighet","caption":"Förvärv · 19 december 2023","preamble":"Vinge har biträtt Annehem Fastigheter AB (publ) vid förvärvet av fastigheten The Corner, en nyproducerad kontorsfastighet i Malmö. Fastighetsvärdet uppgår till 420 miljoner kronor.","body":"Annehem Fastigheter är ett tillväxtdrivet fastighetsbolag inriktat på kommersiella-, samhälls- och bostadsfastigheter i de nordiska tillväxtregionerna Stockholm, Skåne, Göteborg samt Helsingfors och Oslo. Fastighetsbeståndet i Annehem Fastigheter består av 26 förvaltningsfastigheter med ett värde om 4 237,8 miljoner kronor och en uthyrbar yta om 198 tkvm per 30 september 2023. Bolaget är sedan december 2020 noterat på Nasdaq Stockholm och ingår sedan maj 2022 i Nasdaq Green Designation.\n\nVinges team bestod av Rikard Lindahl, Victor Ericsson, Kristoffer Larson, Joel Magnusson, Madelene Andersson, Michaela Ådén, Erik Kochbati och Lovisa Jonassen.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-annehem-fastigheter-vid-forvarv-av-fastighet/","date":"2023-12-19","month":12},{"year":2023,"client":"Norvestor","work":"Övrigt","disciplines":["M&A"],"title":"Vinge biträder Norvestor i samband med budet på Permascand","caption":"Övrigt · 19 december 2023","preamble":"Vinge har biträtt huvudägaren Norvestor VI L.P i samband med att Altor PC AB lämnat ett offentligt erbjudande till aktieägarna i Permascand Top Holding AB (publ). Norvestor äger cirka 44,45 procent av aktierna i Permascand och har åtagit sig att acceptera erbjudandet. Erbjudandet värderar samtliga aktier i Permascand till cirka 1 008 miljoner kronor.","body":"Vinges team består av Jesper Schönbeck och Linnéa Sellström.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-norvestor-i-samband-med-budet-pa-permascand/","date":"2023-12-19","month":12},{"year":2023,"client":"Helix Kapital","work":"Kapitalanskaffning","disciplines":["M&A","Corporate Commercial"],"title":"Vinge biträder Helix Kapital vid investering i Sacpro","caption":"Kapitalanskaffning · 19 december 2023","preamble":"Vinge har biträtt Helix Kapital när de blir strategisk ägarpartner till Sacpro AB, en ledande leverantör och producent av verktyg och material för rörinfordring (”relining”) i fastigheter. Sacpros grundare och ledning kommer tillsammans med Helix Kapital att accelerera bolagets tillväxt med fokus på norra Europa och USA.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Robin Sultani, Martin Boström och Emma Gustavsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-helix-kapital-vid-investering-i-sacpro/","date":"2023-12-19","month":12},{"year":2023,"client":"Precio Fishbone","work":"Avyttring","disciplines":["M&A","Corporate Commercial","Immaterialrätt","Kapitalmarknad och publik M&A","Carve-Outs"],"title":"Vinge företräder Precio Fishbone i samband med försäljningen av aktier i dotterbolag","caption":"Avyttring · 15 december 2023","preamble":"Vinge företräder Precio Fishbone AB (publ) (”Precio Fishbone”) i samband med försäljningen av cirka 80,1 procent av aktierna i dotterbolaget Precio Fishbone Systems AB (”Omnia”), inklusive produkten Omnia Digital Workplace, till Monterro.","body":"Omnia Digital Workplace har prisbelönats i flera olika internationella sammanhang och har under sex år i rad rankats som marknadens bästa SaaS-produkt för att skapa en modern digital arbetsplats.\n\nMonterro förvärvar en majoritetsandel om cirka 80,1 procent i Omnia från Precio Fishbone medan Precio Fishbone bibehåller en minoritetsandel om cirka 19,9 procent. Omnia har skapats genom en omstrukturering innebärandes att all verksamhet och anställda hänförliga till produkten Omnia Digital Workplace överförts från Precio Fishbone till det tidigare helägda dotterbolaget Omnia. Samtliga aktier i Omnia överlåts till ett bolag som indirekt kommer ägas av Monterro och Precio Fishbone. Köpeskillingen för de cirka 80,1 procent av aktierna i Omnia som indirekt överlåts till Monterro uppgår till 168 miljoner kronor. Omnia äger även Omnia Systems Ltd (Vietnam), Precio Fishbone Canada Inc, Precio Fishbone Danmark ApS och har en filial i Tyskland.\n\nVinges team bestod av Matthias Pannier, Gustav Persson, Maximilian Bengtsson (M&A), Dain Hård Nevonen, William Kåge (Capital Markets), Mathilda Persson (Corporate Commercial), Rebecka Målquist (Intellectual Property) och Fanny Askelöf (Transaction Support Specialist).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-precio-fishbone-i-samband-med-forsaljningen-av-aktier-i-dotterbolag/","date":"2023-12-15","month":12},{"year":2023,"client":"American Industrial Partners","work":"Förvärv","disciplines":["M&A","EU‑ och konkurrensrätt","Arbetsrätt"],"title":"Vinge företräder American Industrial Partners vid ingåendet av ett avtal om att förvärva Veoneers Restraint Control Systems-verksamhet från SSW Partners","caption":"Förvärv · 15 december 2023","preamble":"Veoneer är världsledande inom elektroniska styrsystem för fasthållningsanordningar i bilar och har sålt mer än 1 miljard elektroniska styrenheter och krocksensorer. Veoneers skalbara, förstklassiga kontrollsystem för fasthållningsanordningar räddar liv genom att mildra effekterna av bilolyckor. Under 2023 kommer bolagets produkter att ingå i mer än 40 planerade fordonslanseringar. Företaget har cirka 2.700 anställda i 11 länder.","body":"AIP är ett middle market private equity-företag med fokus på industriföretag. Företaget förvaltar över 16 miljarder dollar på uppdrag av sina limited partners och investerar i flyg och försvar, fordon, byggprodukter, kapitalvaror, kemikalier, industriella tjänster, industriell teknik, logistik, metaller och gruvdrift, transport och andra sektorer.\n\nVinges team bestod av Ulrich Ziche (M&A), Daniel Wendelson, Hilda Ivarsson, Alva Chambert (EU, Competition and Regulatory), Simon Söderholm (Employment & Benefits) och Marcus Eklund (Investigations & International Disputes).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-american-industrial-partners-vid-ingaendet-av-ett-avtal-om-att-forvarva-veoneers-restraint-control-systems-verksamhet-fran-ssw-partners/","date":"2023-12-15","month":12},{"year":2023,"client":"Region Uppsala","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Region Uppsala vid emission av innovativ hälsoobligation","caption":"Obligationsemission · 14 december 2023","preamble":"Vinge biträder Region Uppsala i samband med dess emission av en s.k. hälsoobligation till ett belopp om SEK 80 miljoner och med en löptid om fem år. Hälsoobligationen är den andra i världen av sitt slag och kommer efter Region Stockholms obligation som var kopplad tillförebyggande insatser mot typ 2-diabetes. Skandia var ensam investerare och SEB agerade finansiell rådgivare och emissionsinstitut.","body":"Hälsobligationen är en skräddarsydd produkt som syftar till finansiera en preventiv insats för att upptäcka och erbjuda potentiellt livräddande behandling till personer med odiagnostiserat högt blodtryck och andra relaterade riskfaktorer. Den preventiva insatsen förväntas förhindra upp till 650 allvarliga kardiovaskulära händelser och medföra kostnadsbesparingar om cirka SEK 160 miljoner över tio år.\n\nEn utmärkande och unik funktion i hälsoobligationen är avkastningsmodellen, vilken är utfallsbaserad och innebär en riskdelning mellan Regionen och investeraren. Om Regionens initiativ uppnår de förväntade resultaten kommer investeraren att få en högre avkastning på sin investering, men om Regionen inte uppnår förväntade resultat blir avkastningen lägre eller negativ (dvs. investeraren får tillbaka mindre än sitt investerade belopp).\n\nFör mer information, se gärna https://regionuppsala.se/politik-och-paverkan/pressrum/2023/december/satsar-stort-mot-hogt-blodtryck-genom-att-ge-ut-halsoobligation/.\n\nVinges team bestod av Albert Wållgren, Lionardo Ojeda och Sofia Haggren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-region-uppsala-vid-emission-av-innovativ-halsoobligation/","date":"2023-12-14","month":12},{"year":2023,"client":"Altor","work":"Kapitalanskaffning","disciplines":["M&A","Bank och finans","EU‑ och konkurrensrätt"],"title":"Vinge företräder Altor, grundarna och övriga säljare i samband med dess försäljning av en majoritetsandel i Eleda till Bain Capital","caption":"Kapitalanskaffning · 13 december 2023","preamble":"Vinge företräder Altor Funds (”Altor”), grundarna och övriga säljare i samband med att Bain Capital Private Equity (”Bain Capital”), ett ledande globalt privat investeringsföretag, förvärvar en kontrollerande andel i Eleda från Altor, som kommer att återinvestera en minoritetsandel. Eledas grundare, Johan Halvardsson och Peter Condrup, samt ledande befattningshavare inom Eleda, kommer också att göra betydande återinvesteringar. Genom transaktionen etablerar Altor, Eleda och Bain Capital ett partnerskap för framtida tillväxt.","body":"Med huvudkontor i Stockholm och cirka 3 000 medarbetare är Eleda en ledande nordisk leverantör inom infrastrukturtjänster. Koncernen är marknadsledare inom flera segment, och många av dem tillgodoser behovet av den gröna omställningen, såsom vatten och avlopp, eldistribution, fjärrvärme, vägar, järnvägar, datacenter och laddstationer för elfordon. Eledas decentraliserade verksamhetsmodell skapar förutsättningar för bolagen inom koncernen att leverera högsta kvalitet till sina kunder med den optimala mixen av lokal närvaro och resurserna i en större organisation.\n\nTransaktionen är villkorad av regulatoriska godkännanden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Johanna Wiberg, Carl Fredrik Wachtmeister, Ellen Flygt, Philip Moré, Jonatan Stentorp, Jonas Johansson, Nina Gransäter och Johan Gavelin (M&A), Louise Brorsson Salomon och Jolinn Uhlin (Banking and Finance), Martin Johansson och Hedvig Josefson (EU Regulatory), Emy Rydén, Emelie Schoning, Gabriella Balbo, Emma Emsjö, Christoffer Widström och Fanny Askelöf (Transaction Support Coordinators).\n\nLäs klientens pressmeddelande","href":"https://www.vinge.se/uppdrag/vinge-foretrader-altor-grundarna-och-ovriga-saljare-i-samband-med-dess-forsaljning-av-en-majoritetsandel-i-eleda-till-bain-capital/","date":"2023-12-13","month":12},{"year":2023,"client":"Lagercrantz","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad","Miljörätt"],"title":"Vinge biträder Lagercrantz vid förvärv av Material Handling Modules","caption":"Förvärv · 13 december 2023","preamble":"Vinge har biträtt Lagercrantz Group vid förvärv av 97% av aktierna i Material Handling Modules Europe AB, en ledande nordisk leverantör av modulariserade rullbane- och pallhanteringssystem till integratörer inom automationsindustrin.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Klara Fäldt, Karolina Cohrs, Olivia Onwuta och Lina Österberg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-vid-forvarv-av-material-handling-modules/","date":"2023-12-13","month":12},{"year":2023,"client":"Tobii","work":"Förvärv","disciplines":["Kapitalmarknad och publik M&A","M&A"],"title":"Vinge biträder Tobii i samband med förvärvet av AutoSense från Xperi","caption":"Förvärv · 13 december 2023","preamble":"Vinge har biträtt Tobii AB vid förvärvet av AutoSense-verksamheten från Xperi Inc. Transaktionen accelererar Tobiis resa mot en ledande position på marknaden för Automotive Interior Sensing genom att kombinera Tobiis och AutoSenses förmågor.","body":"Transaktionen förväntas vara slutförd inom 30 dagar och är föremål för sedvanliga slutförandevillkor.\nVinges team bestod i huvudsak av Jesper Schönbeck, Amanda Knutsson, Joel Magnusson, Louise Brorsson Salomon och Karl-Gustaw Tobola.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-tobii-i-samband-med-forvarvet-av-autosense-fran-xperi/","date":"2023-12-13","month":12},{"year":2023,"client":"Stena Sessan","work":"Övrigt","disciplines":["M&A"],"title":"Vinge biträder Stena Sessan i budet på Concordia Maritime","caption":"Övrigt · 12 december 2023","preamble":"Stena Sessan AB har lämnat ett rekommenderat uppköpserbjudande till aktieägarna i Concordia Maritime Aktiebolag (publ). Budet värderar samtliga aktier i Concordia Maritime till cirka 468 miljoner kronor.","body":"Vinges team består av Johan Winnerblad, Jesper Schönbeck, David Andersson, Paula Bäckdén, Anna Svensson och Agnes Pigg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-stena-sessan-i-budet-pa-concordia-maritime/","date":"2023-12-12","month":12},{"year":2023,"client":"Main Capital och Björn Lundén","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Bank och finans","GDPR","Immaterialrätt"],"title":"Vinge företräder Main Capital och Björn Lundén vid förvärvet av Due Compliance AB","caption":"Förvärv · 12 december 2023","preamble":"Due Compliance möjliggör för organisationer att efterleva kraven som ställs enligt penningtvättslagen genom att tillhandahålla digitala verktyg för penningtvättskontroller, KYC och riskbedömningar.","body":"Björn Lundén, som är en stark aktör inom programvara för bl.a. bokföring, fakturering och lönehantering, ser förvärvet av Due Compliance som ett viktigt steg i att utöka sitt erbjudande av digitala verktyg på den regulatoriska marknaden. Förvärvet kommer stärka koncernens marknadsposition med målet att bli en ledande aktör inom Europa som erbjuder en heltäckande uppsättning molnbaserade redovisnings-, ERP och RegTech-lösningar.\n\nVinges team bestod av Filip Öhrner, Josef Groow (M&A), Arvid Weimers, Karl-Gustaw Tobola, August Ahlin (Bank och Finans), Lisa Hörnqvist (IT och GDPR), Axel Lennartsson (IP), Victor Björkheim (arbetsrätt) och Jessica Öijer (Transaction Support Senior Specialist).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-och-bjorn-lunden-vid-forvarvet-av-due-compliance-ab/","date":"2023-12-12","month":12},{"year":2023,"client":"L5 Navigation","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder L5 Navigation vid förvärv av ROCKMA System","caption":"Förvärv · 8 december 2023","preamble":"Vinge har biträtt L5 Navigation, ett portföljbolag till Helix Kapital, vid förvärv av ROCKMA System AB. ROCKMA utvecklar och levererar maskinstyrningsmjukvara för borriggar, borrövervakningssystem och realtids- berganalyssystem.","body":"Vinges team bestod av Johan Winnerblad, Linus Adolfsson och Nando Basic.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-l5-navigation-vid-forvarv-av-rockma-system/","date":"2023-12-08","month":12},{"year":2023,"client":"Grundarna av Modular Finance","work":"Kapitalanskaffning","disciplines":["M&A","Rekonstruktioner och obestånd","Företagsbeskattning"],"title":"Vinge företräder grundarna av Modular Finance i samband med försäljning till Sprints","caption":"Kapitalanskaffning · 8 december 2023","preamble":"Vinge företräder grundarna av Modular Finance i samband med en försäljning av 40% av aktierna i bolaget till Sprints.","body":"Modular Finance är ett SaaS-företag som fokuserar på finansmarknaderna i Norden och Storbritannien. Genom två affärsområden, Banking & Finance samt Investor Relations, erbjuds ett utbud av nischprodukter med fokus på unika datamängder och användarvänlighet.\n\nSprints har ett team grundat och lett av svenskar men med huvudkontor i Storbritannien och är en fokuserad teknikinvesterare med ett tidigare ägande i Hemnet och nuvarande ägande i bolag som Teamtailor, Planhat, Vinted och Revolut.\n\nFöretagets grundare Måns Flodberg, Rasmus Holm och Petter Hedborg kommer att behålla majoriteten av sina aktier och förbli fullt engagerade under de kommande åren. Rite Ventures som varit delägare sedan 2014 kommer också att behålla majoriteten av sina aktier.\n\nVinges team bestod av Christina Kokko, Karl Klackenberg, Viktor Lennartsson, Egil Svensson och Gustav Persson (M&A), Victor Ericsson och Morgan Ödman (Tax), samt Daniel Wendelsson (Regulatory).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-grundarna-av-modular-finance-i-samband-med-forsaljning-till-sprints/","date":"2023-12-08","month":12},{"year":2023,"client":"Oxx","work":"Fondetablering","disciplines":["Private Funds"],"title":"Vinge har biträtt Oxx i samband med fondresningen av Oxx II","caption":"Fondetablering · 7 december 2023","preamble":"Oxx stänger sin andra generations fond med 190 miljoner USD i investeringsåtaganden från en internationell investerarbas, och ökar därmed sin fondstorlek med 40 % jämfört med den senaste generationen.","body":"Oxx grundades 2017 och investerar huvudsakligen i europeiska bolag inom B2B SaaS scale-up-segmentet.\nVinges team har huvudsakligen bestått av Mattias Schömer, Jesper Ottergren, Viveka Classon, Martin Cronsioe, Semir Omerbasic och Viktoria Wnuk.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-oxx-i-samband-med-fondresningen-av-oxx-ii/","date":"2023-12-07","month":12},{"year":2023,"client":"Cell Impact","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har företrätt Cell Impact i samband med dess företrädesemission","caption":"Kapitalanskaffning · 6 december 2023","preamble":"Vinge har företrätt Cell Impact AB (publ) i samband med en delvis garanterad företrädesemission som tillför Cell Impact 129 miljoner kronor före avdrag för transaktionskostnader","body":"Cell Impact är en global leverantör av avancerade flödesplattor till tillverkare av bränsleceller och elektrolysörer. Företaget har utvecklat och patenterat en unik metod för höghastighetsformning, Cell Impact Forming™, som gör det möjligt att tillverka flödesplattor mer skalbart och kostnadseffektivt, jämfört med konventionella formningsmetoder.\n\nVinges team bestod av Johan Larsson, Dain Hård Nevonen, Rikard Lindahl, Stina Bengtsson, Anna Svensson och Elias Kröger.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-cell-impact-i-samband-med-dess-foretradesemission/","date":"2023-12-06","month":12},{"year":2023,"client":"Helix Kapital","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Helix Kapital vid investering i Xamera","caption":"Kapitalanskaffning · 3 december 2023","preamble":"Vinge har biträtt Helix Kapital när de blir strategisk ägarpartner till Xamera AB, en ledande aktör inom långsiktig och teknikfokuserad kompetensförsörjning till den svenska industri- och techsektorn.","body":"Xameras grundare och delägare kommer tillsammans med Helix Kapital att accelerera bolagets tillväxt i Sverige och Norden.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Per Kling, Eskil Nyström, Emil Lindwall och Gulestan Ali.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-helix-kapital-vid-investering-i-xamera/","date":"2023-12-03","month":12},{"year":2023,"client":"Triton","work":"Avyttring","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Triton i samband med försäljning av aktier i Ambea AB (publ)","caption":"Avyttring · 29 november 2023","preamble":"Totalt placerades 8,4 miljoner aktier till ett pris om 43,50 kronor per aktie, motsvarande ett sammanlagt värde om cirka 365 miljoner kronor.","body":"Vinges team bestod av Sofie Bjärtun och Joel Magnusson.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-triton-i-samband-med-forsaljning-av-aktier-i-ambea-ab-publ/","date":"2023-11-29","month":11},{"year":2023,"client":"Lassie","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Lassie AB vid kapitalanskaffning om 260 miljoner kronor","caption":"Kapitalanskaffning · 29 november 2023","preamble":"Vinge har företrätt djurförsäkringsförmedlingsbolaget Lassie AB i samband med en kapitalanskaffning om 260 miljoner kronor i syfte att fortsätta expansionen av verksamheten.","body":"Lassie AB, vars affärsmodell bygger på att användarna sänker sina försäkringskostnader genom att samla poäng genom preventiv djurvård, grundades av Hedda Båverud Olsson, Johan Jönsson och Sophie Wilkinson och bolaget har vuxit snabbt sedan den första kapitalrundan för drygt två år sedan.\n\nI kapitalrundan som leddes av det brittiska venture capital-bolaget Balderton Capital deltog även ett flertal befintliga investerare, däribland de institutionella investerarna Felix Capital, Inventure och Passion Capital.\n\nVinges team bestod av Filip Öhrner och Tim Axell.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-lassie-ab-vid-kapitalanskaffning-om-260-miljoner-kronor/","date":"2023-11-29","month":11},{"year":2023,"client":"Expedition Growth Capital","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har rådgivit Expedition Growth Capital i samband med dess investering i Factbird","caption":"Kapitalanskaffning · 27 november 2023","preamble":"Expedition Growth Capital har, tillsammans med Danmarks Eksport- og Investeringsfond (EIFO), genomfört en investering i det danska tech-bolaget Factbird. Vinge rådgav Expedition Growth Capital i samband med investering.","body":"Factbird, ett bolag i kraftig tillväxt sedan 2021, tillhandahåller 250+ kunder med intelligent, molnbaserad teknologi för optimering av tillverkares produktionslinjer. Expedition Growth Capital är en London-baserad tillväxtfond som fokuserar på investeringar i snabbväxande bolag som fortsatt är i dess startup-fas.\n\nVinges team bestod av Karl Klackenberg och Per Kling.","href":"https://www.vinge.se/uppdrag/vinge-har-radgivit-expedition-growth-capital-i-samband-med-dess-investering-i-factbird/","date":"2023-11-27","month":11},{"year":2023,"client":"The Weir Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har rådgivit The Weir Group i samband med dess förvärv av Sentiantechnologies AB (\"Sentian\")","caption":"Förvärv · 23 november 2023","preamble":"The Weir Group, ett globalt och världsledande företag inom gruvteknologi, har förvärvat 100% av aktierna i Sentian, en Sverigebaserad utvecklare av AI-lösningar som optimerar processer rörande mineralbearbetning.","body":"Vinges team bestod huvudsakligen av Jonas Bergström, Per Kling, Sara Passandideh, Filip Magnusson, Jolene Reimerson, Carl Lexenberg, Gulestan Ali och Gabriella Balbo.","href":"https://www.vinge.se/uppdrag/vinge-har-radgivit-the-weir-group-i-samband-med-dess-forvarv-av-sentiantechnologies-ab-sentian/","date":"2023-11-23","month":11},{"year":2023,"client":"CDPQ","work":"Kapitalanskaffning","disciplines":["Arbetsrätt","M&A","Immaterialrätt","EU‑ och konkurrensrätt"],"title":"Vinge har biträtt CDPQ i samband med en investering i Northvolt","caption":"Kapitalanskaffning · 21 november 2023","preamble":"Caisse de dépôt et placement du Québec (CDPQ) har investerat 150 miljoner USD i Northvolt genom ett konvertibelt lån. Investeringen kommer användas för att finansiera byggandet av den nya batterifabriken Northvolt Six i Québec. När fabriken är färdigställd kommer den ha en årlig produktionskapacitet på upp till 60 GWh.","body":"Vinges team bestod främst av Christina Kokko, Maria Dahlin Kolvik, Desirée Hagenfeldt, Stina Bengtsson, Eskil Nyström, Jolene Reimerson, Malin Malm Waerme, Arvid Axelryd, Helena Göransson, Kamyar Najmi, Sam Fakhraie Ardekani och Julia Löfqvist.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-cdpq-i-samband-med-en-investering-i-northvolt/","date":"2023-11-21","month":11},{"year":2023,"client":"Scandic","work":"Övrigt","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Scandic i samband med dess återköp av konvertibler","caption":"Övrigt · 20 november 2023","preamble":"Vinge har biträtt Scandic Hotels Group AB (publ) (”Scandic”) i samband med dess återköp av konvertibler.","body":"Totalt återköptes konvertibler till ett sammanlagt nominellt belopp om 590,2 miljoner kronor via ett modifierat ”Dutch auction”-förfarande.\n\nScandic är det största hotellföretaget i Norden med ett nätverk av omkring 280 hotell och 58 000 hotellrum i drift och under utveckling på över 130 destinationer. Scandic är noterat på Nasdaq Stockholm.\n\nVinges team har bestått av Jesper Schönbeck, Amanda Knutsson, William Kåge, Lovisa Jonassen (Kapitalmarknad och publik M&A), Louise Brorsson Salomon och Arvid Weimers (Bank och finans).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-scandic-i-samband-med-dess-aterkop-av-konvertibler/","date":"2023-11-20","month":11},{"year":2023,"client":"Sobro","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Sobro vid investering i EFFSO Group","caption":"Kapitalanskaffning · 17 november 2023","preamble":"EFFSO Group har valt att bredda sitt ägande med Sobro som ny ägarpartner och majoritetsägare. EFFSO Group är en marknadsledande koncern av svenska inköpstjänsteföretag. Verksamheten grundades 2007 och har en total omsättning på ca 170 mkr.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Eléonore Friberg, Eskil Nyström, Elis Allmark, Olivia Onwuta, Madelene Andersson, Mika Jordan och Emma Gustavsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sobro-vid-investering-i-effso-group/","date":"2023-11-17","month":11},{"year":2023,"client":"EHF","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder EHF i budet på Götenehus","caption":"Övrigt · 16 november 2023","preamble":"EHF AB har lämnat ett offentligt uppköpserbjudande till aktieägarna i Götenehus Group AB (publ).","body":"Budet värderar samtliga aktier i Götenehus till cirka 398 miljoner kronor.\n\nVinges team består huvudsakligen av Erik Sjöman och Agaton Lindgren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ehf-i-budet-pa-gotenehus/","date":"2023-11-16","month":11},{"year":2023,"client":"Axcel och XPartners","work":"Förvärv","disciplines":["Fastigheter och Entreprenad","M&A"],"title":"Vinge företräder Axcel och XPartners vid förvärv av B&B Bro & Betong","caption":"Förvärv · 16 november 2023","preamble":"Vinge har företrätt Axcel VII (”Axcel”) och XPartners Samhällsbyggnad (”XPartners”) vid förvärvet av B&B Bro & Betong Projektledning AB (”B&B Bro & Betong”).","body":"B&B Bro & Betong är ett konsultbolag som erbjuder kvalificerade projekt- och byggledningstjänster inom infrastruktur och stadsutveckling. Tjänsterna omfattar flera av byggprocessens skeden såsom förstudie, utredning, systemhandling, bygghandling, produktion och överlämnande, och bolaget jobbar aktivt med ständiga förbättringar och följer ISO-kraven för kvalitets- och miljöstyrning. B&B Bro & Betong medverkar i många av Mälardalens stora samhällsviktiga infrastrukturprojekt och beställare är bland annat Stockholms stad, Stockholms Hamnar, Trafikverket och nya tunnelbanan.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Karl Klackenberg, Carl Fredrik Wachtmeister, Egil Svensson, Sara Passandideh och Alexander Rüdén (M&A) och Clara Klingspor (Entreprenadrätt) samt Cecilia Loctander (Transaction Support Coordinator).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-och-xpartners-vid-forvarv-av-b-b-bro-betong/","date":"2023-11-16","month":11},{"year":2023,"client":"Swire Renewable Energy","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Swire Renewable Energy i samband med förvärvet av WPS Sweden AB","caption":"Förvärv · 13 november 2023","preamble":"Vinge har företrätt Swire Renewable Energy i samband med dess förvärv av WPS Sweden AB (\"WPS\").","body":"WPS är ett företag som arbetar med inspektion, reparation och underhåll av turbiner för vindkraftverk och som verkar över hela Sverige, Norge och Finland. Med förvärvet kommer Swire Renewable Energy att accelerera sitt erbjudande av professionella tjänster för inspektion, reparation och underhåll av vindturbiner till kunder och intressenter samt utvidga sin geografiska täckning i norra Europa, särskilt i Norden.\n\nVinges team bestod av bland andra av Jonas Bergström, Johanna Wiberg och Egil Svensson (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-swire-renewable-energy-i-samband-med-forvarvet-av-wps-sweden-ab/","date":"2023-11-13","month":11},{"year":2023,"client":"Epta S.p.A.","work":"Partnerskap","disciplines":["M&A"],"title":"Vinge har biträtt Epta S.p.A. i ett joint venture med Viessmann Refrigeration Solutions","caption":"Partnerskap · 9 november 2023","preamble":"Vinge har biträtt Epta S.p.A. i ett joint venture med Viessmann Refrigeration Solutions, varigenom det samägda bolaget Epta Central North Europe B.V. bildades. Epta Central North Europe B.V. förväntas ha en omsättning överstigande 400 miljoner Euro med mer än 400 anställda.","body":"Vinges team bestod i huvudsak av av Henrik Borna, Jonatan Karlsson och Tove Hallbäck.\n\nLäs klientens press-release.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-epta-s-p-a-i-ett-joint-venture-med-viessmann-refrigeration-solutions/","date":"2023-11-09","month":11},{"year":2023,"client":"Fast Travel Games","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har företrätt Fast Travel Games vid kapitalanskaffning","caption":"Kapitalanskaffning · 7 november 2023","preamble":"Vinge har företrätt den Stockholmsbaserade VR-spelstudion Fast Travel Games vid en kapitalanskaffning om 4 MUSD.","body":"Finansieringen kommer att ytterligare stärka Fast Travel Games’ möjlighet att kapitalisera på den växande VR-spelmarknaden. Medverkade i kapitalanskaffningsrundan gjorde bland annat Handelsbanken Fonder, Industrifonden, Brightly Ventures, Creades och Inbox Capital.\n\nVinges team bestod av Johan Larsson, Ellinor Wargenbrant och Robin Fagerström.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-fast-travel-games-vid-kapitalanskaffning-1/","date":"2023-11-07","month":11},{"year":2023,"client":"Cantargia","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Cantargia i samband med riktad nyemission","caption":"Kapitalanskaffning · 1 november 2023","preamble":"Vinge biträder Cantargia AB (publ) i samband med en riktad nyemission om cirka 59 miljoner kronor till ett antal svenska och internationella investerare.","body":"Vinges team består av Christian Lindhé, Erik Sjöman, Martin Madsen Svanberg och Johan Åhman.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-cantargia-i-samband-med-riktad-nyemission/","date":"2023-11-01","month":11},{"year":2023,"client":"Bergs Timber","work":"Offentligt uppköpserbjudande","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Bergs Timber i samband med Norviks offentliga uppköpserbjudande","caption":"Offentligt uppköpserbjudande · 30 oktober 2023","preamble":"Den 27 oktober 2023 offentliggjorde Norvik hf, genom det helägda dotterbolaget Kivron AB, ett offentligt uppköpserbjudande till aktieägarna i Bergs Timber AB (publ) att förvärva samtliga aktier i Bergs Timber.","body":"Det totala värdet av erbjudandet uppgår till cirka 1,54 miljarder kronor baserat på totalt antal utestående aktier i Bergs Timber.\n\nVinges team består av Jesper Schönbeck, Joel Wahlberg, Johannes Akyol (Kapitalmarknad och publik M&A), Ulrich Ziche (M&A) och David Olander (EU och konkurrensrätt).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-bergs-timber-i-samband-med-norviks-offentliga-uppkopserbjudande/","date":"2023-10-30","month":10},{"year":2023,"client":"Carnegie","work":"Förvärv","disciplines":["Arbetsrätt","Private Funds","Immaterialrätt","M&A","Bank och finans"],"title":"Vinge företräder Carnegie i samband med förvärvet av Erik Penser Banks värdepappersrörelse","caption":"Förvärv · 25 oktober 2023","preamble":"Vinge företräder Carnegie Investment Bank AB i samband med förvärvet av verksamhetsområdena Erik Penser Wealth Management och Erik Penser Corporate Finance samt analystjänsterna Penser Access och Penser Future från Erik Penser Bank AB. Vederlaget för genomfört förvärv utgörs av aktier i Carnegie och förvärvet är villkorat av sedvanliga myndighetsgodkännanden.","body":"Carnegie Group är idag en av Nordens ledande finansiella rådgivare och kapitalförvaltare med 800 medarbetare i sex länder. Erik Penser Bank erbjuder en omfattande portfölj av finansiella tjänster och grundades genom etableringen av Erik Penser Fondkommission 1994 av Erik Penser.\n\nVinges team bestod huvudsakligen av Kristian Ford (ansvarig delägare), Sofie Nordgren, Anna Edström, Henrik Borna och Agaton Lindgren (M&A), Nils Unckel, Anton Sjökvist and Viktoria Wnuk (regulatory), Pär Remnelid (konkurrensrätt), Emelie Svensäter Jerntorp (arbetsrätt), Lisa Bourghardt (IP), Fredrik Christiansson (bank och finans) och Ulf Nilsson (skatt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-carnegie-i-samband-med-forvarvet-av-erik-penser-banks-vardepappersrorelse/","date":"2023-10-25","month":10},{"year":2023,"client":"Sileon","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har företrätt Sileon i samband med dess företrädesemission","caption":"Kapitalanskaffning · 23 oktober 2023","preamble":"Vinge har företrätt Sileon AB (publ) i samband med dess företrädesemission, varigenom bolaget tillförs cirka 33,8 miljoner kronor före emissionskostnader.","body":"Företrädesemissionen avser främst finansiering av fortsatta kommersialiseringsaktiviteter och produktutveckling samt allmänt rörelsekapital. Sileon är ett globalt fintech-bolag som erbjuder en innovativ kortbaserad Buy Now Pay Later (BNPL) SaaS-funktionalitet till banker, kortutgivare och fintechs. Sileon är noterat på Nasdaq First North Growth Market.\n\nVinges team bestod av Anders Strid, Edin Agic och Adrian Filipovic.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-sileon-i-samband-med-dess-foretradesemission/","date":"2023-10-23","month":10},{"year":2023,"client":"Equip Capital och Remagruppen","work":"Förvärv","disciplines":["Arbetsrätt","M&A","Fastigheter och Entreprenad"],"title":"Vinge företräder Equip Capital och Remagruppen vid förvärv av Beredningsbart Syd","caption":"Förvärv · 23 oktober 2023","preamble":"Vinge företräder den norska private equity-firman Equip Capital och dess portföljbolag Remagruppen vid förvärvet av Beredningsbart Syd AB (”BNB Syd”).","body":"BNB Syd tillhandahåller kvalitativa tjänster inom sanering, rivning, håltagning och avfallshantering och är verksamt i södra Sverige. Remagruppen förvärvar och utvecklar välskötta, stabila och entreprenörsledda bolag inom hållbart fastighetsunderhåll.\n\nVinges team bestod huvudsakligen av Karl Klackenberg, Carl Fredrik Wachtmeister och Maximilian Bengtsson (M&A), Clara Klingspor (Entreprenadrätt), Olivia Onwuta (Arbetsrätt), och Emma Emsjö (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-equip-capital-och-remagruppen-vid-forvarv-av-beredningsbart-syd/","date":"2023-10-23","month":10},{"year":2023,"client":"Fairpoint Capital och eEquity","work":"Kapitalanskaffning","disciplines":["Arbetsrätt","Corporate Commercial","M&A"],"title":"Vinge biträder Fairpoint Capital och eEquity i samband med investering i Mediatool","caption":"Kapitalanskaffning · 20 oktober 2023","preamble":"Vinge biträder Fairpoint Capital och eEquity i samband med deras deltagande i en investeringsrunda om 90 MSEK i Mediatool, ett bolag som erbjuder en digital plattform för mediehantering för varumärken och mediebyråer.","body":"Vinges team har bestått av Johan Larsson och Nando Basic (M&A), Mathilda Persson (kommersiella avtal) och Victor Björkheim (arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-fairpoint-capital-och-eequity-i-samband-med-investering-i-mediatool/","date":"2023-10-20","month":10},{"year":2023,"client":"Thermo Fisher","work":"Förvärv","disciplines":["M&A","Immaterialrätt","Offentlig upphandling","Tvistlösning","Kapitalmarknad och publik M&A","Företagsbeskattning","Arbetsrätt"],"title":"Vinge företräder Thermo Fisher i samband med förvärvet av Olink","caption":"Förvärv · 18 oktober 2023","preamble":"Vinge har företrätt Thermo Fisher Scientific Inc., (”Thermo Fisher”), världsledaren inom teknik till vetenskap och forskning, med en årlig omsättning om över 40 miljarder USD, i samband med dess förvärv av Olink Holding AB (publ) (”Olink”).","body":"Thermo Fisher kommer att lansera ett uppköpserbjudande att förvärva samtliga utestående stamaktier och amerikanska depåaktier i Olink för 26,00 USD per stamaktie i kontanter, vilket motsvarar 26,00 USD per depåaktie. Transaktionen värderar Olink till cirka 3,1 miljarder dollar, vilket inkluderar en nettokassa på cirka 143 miljoner dollar.\n\nOlink är ett bolag vars syfte är att möjliggöra och påskynda området proteomik tillsammans med akademin, över flera sjukdomsområden för att möjliggöra nya upptäckter och förbättra patienters liv. Olink tillhandahåller en plattform av produkter och tjänster som distribueras till stora biofarmaceutiska företag och ledande kliniska och akademiska institutioner för att fördjupa förståelsen för mänsklig biologi i realtid och driva nuvarande hälsovård genom handlingsbar och effektiv vetenskap. Bolaget grundades 2016 och är väletablerat i Europa, Nordamerika och Asien. Olink har sitt huvudkontor i Uppsala och bolagets aktier är sedan 2021 noterade på Nasdaq Global Market.\n\nVinges team bestod huvudsakligen av Jonas Bergström, Erik Sjöman, Samra Tesser, Linnéa Sellström och Anna Svensson (M&A och aktiemarknad), Cecilia Möller Norstedt (tvistelösning), Mattias Schömer och Emelie Svanberg (skatt), Sam Seddigh, (arbetsrätt), Daniel Wendelsson, Victoria Fredén och Hampus Peterson (FDI) samt Malin Malm Waerme (IP).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-thermo-fisher-i-samband-med-forvarvet-av-olink/","date":"2023-10-18","month":10},{"year":2023,"client":"AtNorth","work":"Övrigt","disciplines":["M&A","GDPR","Bank och finans"],"title":"Vinge har biträtt atNorth AB","caption":"Övrigt · 16 oktober 2023","preamble":"Vinge har biträtt atNorth AB, ett ledande nordiskt datacenterföretag som erbjuder ansvarsfulla, energieffektiva, kostnadsoptimerade datacenterhotell och högpresterande databehandlingstjänster, i samband med dess förvärv av Gompute och dess spanska dotterbolag.","body":"Gompute är en ledande leverantör av HPC-tjänster (High Performance Computing) och datacentertjänster. Företaget har sitt huvudkontor i Göteborg.\n\nFörvärvet av Gompute kommer ytterligare att stärka atNorths position på den snabbt växande HPC-marknaden.\n\nVinges team bestod huvudsakligen av Peter Sundgren, Ulrich Ziche, Isabelle Wållgren, Elis Allmark, Elsa Strandberg, Tove Hallbäck, Sophia Reutercrona, Clara Klingspor, Nicklas Thorgerzon, Karolina Cohrs, Alexandra Tamm, Anna Ekdahl Roos och Cecilia Loctander.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-atnorth-ab/","date":"2023-10-16","month":10},{"year":2023,"client":"Ernströmgruppen","work":"Förvärv","disciplines":["Arbetsrätt","M&A","Finansiella tillståndsfrågor","Kommersiella avtal"],"title":"Vinge har företrätt Ernströmgruppen i samband med förvärv","caption":"Förvärv · 16 oktober 2023","preamble":"Vinge har företrätt Ernströmgruppen i samband med dess förvärv av en majoritetsandel av aktierna i Tubman AB, en ledande distributör av segjärnsrörsystem till den svenska VA-marknaden. Tubman kompletterar Ernströmgruppens affärsområde \"Water & Energy\" och dess tidigare ägare kvarstår som delägare.","body":"Vinges team bestod huvudsakligen av Magnus Pauli, Jenny Sandlund (Projektledare), Hannah Mark (Kommersiella avtal), Hanna Marberg (Arbetsrätt) och Adam Loewenstein (Hyresavtal).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-ernstromgruppen-i-samband-med-forvarv/","date":"2023-10-16","month":10},{"year":2023,"client":"Axel Johnson","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Axel Johnson i Dustins nyemission","caption":"Kapitalanskaffning · 16 oktober 2023","preamble":"Dustin AB (publ) genomför en av Axel Johnson fullt garanterad företrädesemission om cirka 1 750 miljoner kronor.","body":"Vinge, genom Erik Sjöman, biträder Axel Johnson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-axel-johnson-i-dustins-nyemission/","date":"2023-10-16","month":10},{"year":2023,"client":"Studentbostäder","work":"Obligationsemission","disciplines":["Kapitalmarknad och publik M&A","Bank och finans"],"title":"Vinge företräder Studentbostäder i Norden AB (publ) i samband med dess företrädesemission och omförhandling av obligationsvillkor","caption":"Obligationsemission · 13 oktober 2023","preamble":"Vinge företräder Studentbostäder i Norden AB (publ), ett fastighetsbolag vars aktier är noterade på Nasdaq First North Premier Growth Market, i samband med en fullt garanterad företrädesemission omfattande sammanlagt 331 miljoner kronor före avdrag för emissionskostnader och omförhandling av obligationsvillkoren för bolagets utestående gröna 2021/2024 obligationer med ISIN SE0015960802 (”Obligationerna”) genom ett skriftligt förfarande.","body":"De nya aktierna som emitteras inom ramen för företrädesemissionen beräknas bli föremål för handel på Nasdaq First North Premier Growth Market under vecka 45 2023.\n\nOmförhandling av obligationsvillkoren medförde, bland annat, en förlängning av den ursprungliga slutförfallodagen till den 15 november 2026, en ändring av räntekomponenten till en fast PIK-ränta och ett nytt åtagande för bolaget att delvis amortera på Obligationerna.\n\nStudentbostäder i Norden AB (publ) äger, förvaltar och utvecklar studentbostäder i långsiktiga partnerskap med kommuner, regioner och högskolor. Bolagets aktier är noterade i Sverige på Nasdaq First North Premier Growth Market med kortnamnet STUDBO.\n\nVinges team består av Jesper Schönbeck, Joel Wahlberg, Benjamin Vafaeian, Gabriel Chabo och Alexander Rüdén (Kapitalmarknad och publik M&A), Mikael Ståhl, Lionardo Ojeda, Felix Möller och August Ahlin (Bank och Finans).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-studentbostader-i-norden-ab-publ-i-samband-med-dess-foretradesemission-och-omforhandling-av-obligationsvillkor/","date":"2023-10-13","month":10},{"year":2023,"client":"Egetis Therapeutics","work":"Kapitalanskaffning","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Egetis Therapeutics i samband med en kombinerad finansiering bestående av en riktad nyemission och en skuldfinansiering","caption":"Kapitalanskaffning · 13 oktober 2023","preamble":"Vinge har företrätt Egetis Therapeutics AB (publ) (”Egetis Therapeutics”), ett innovativt och integrerat läkemedelsbolag fokuserat på projekt i sen klinisk utvecklingsfas för kommersialisering inom särläkemedelsområdet för behandling av allvarliga och sällsynta sjukdomar med betydande medicinska behov, noterat på Nasdaq Stockholm, i samband med en kombinerad finansiering bestående av en riktad nyemission om 172 miljoner kronor och en skuldfinansiering om 290 miljoner kronor.","body":"Vinges team bestod av Dain Hård Nevonen, Amanda Knutsson, Lorin Arabi och Isabell Bitar (Kapitalmarknad och publik M&A) samt av Albert Wållgren, Arvid Weimers och Ida Redander (Bank och finans).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-egetis-therapeutics-i-samband-med-en-kombinerad-finansiering-bestaende-av-en-riktad-nyemission-och-en-skuldfinansiering/","date":"2023-10-13","month":10},{"year":2023,"client":"Advania","work":"Förvärv","disciplines":["Kommersiella avtal","GDPR","IT, Telekom och Outsourcing","M&A","Corporate Crime & Compliance","Fastigheter och Entreprenad","Offentlig upphandling","EU‑ och konkurrensrätt"],"title":"Vinge legal rådgivare åt Advania i dess förvärv av RTS","caption":"Förvärv · 12 oktober 2023","preamble":"Vinge agerar som legal rådgivare åt Advania i samband med förvärvet av RTS Group AB (\"RTS\").","body":"RTS är en helhetsleverantör inom IT-lösningar för bland annat managerade tjänster, datacenter och IT-infrastruktur. Förvärvet ligger i linje med Advanias mål att bli den mest attraktiva IT-tjänsteleverantören i norra Europa. Transaktionen är villkorat av sedvanliga myndighetsgodkännanden och förväntas slutföras under fjärde kvartalet 2023.\n\nVinges team bestod av Peter Sundgren, Linus Adolfsson, Gustav Persson och Michella Lina Said (M&A), August Ahlin (Bank och Finans), Carla Zachariasson, Christoffer Nordin och Carl Lexenberg (Kommersiella avtal), Henrik Borna och Jolene Reimerson (IT), Nicklas Thorgerzon (GDPR), Mia Falk och Julia Löfqvist (Compliance), Axel Lennartsson och Rebecka Målquist (IP), Gulestan Ali (Arbetsrätt), Kristoffer Larson (Fastighetsrätt), David Olander och Hampus Peterson (EU och konkurrensrätt), Daniel Wendelsson (Säkerhetsskydd och FDI), Kristoffer Sällfors (Offentlig upphandling) och Cecilia Loctander (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-legal-radgivare-at-advania-i-dess-forvarv-av-rts/","date":"2023-10-12","month":10},{"year":2023,"client":"Devant","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Devant vid kapitalanskaffning","caption":"Kapitalanskaffning · 12 oktober 2023","preamble":"Norrköpingsbaserade Devant, som erbjuder datagenererad data till kamerabaserade maskininlärningssystem, har nyligen slutfört en kapitalanskaffning riktad bl.a. till det teknikfokuserade, svenska investeringsbolaget Seven District.","body":"Vinge, genom Johan Winnerblad, har biträtt Devant.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-devant-vid-kapitalanskaffning/","date":"2023-10-12","month":10},{"year":2023,"client":"Eleda","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har företrätt Eleda i samband med förvärv av Mark & Bygg Resursen AB (”MBR”)","caption":"Förvärv · 9 oktober 2023","preamble":"MBR är baserat i Stockholm och bolagets huvudsakliga verksamhet är att bedriva alla typer av markarbeten, med specialisering mot reparation och nyanläggning av fjärrvärmeledningar. Bolaget har 15 medarbetare och omsätter cirka 60 miljoner kronor om året.","body":"Vinges team bestod huvudsakligen av Christina Kokko, Johanna Wiberg, Ellen Flygt och Philip Moré (M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-i-samband-med-forvarv-av-mark-bygg-resursen-ab-mbr/","date":"2023-10-09","month":10},{"year":2023,"client":"Norberg & Partner","work":"Offentligt uppköpserbjudande","disciplines":["M&A"],"title":"Vinge biträder Norberg & Partner vid budpliktsbudet på Aino Health","caption":"Offentligt uppköpserbjudande · 4 oktober 2023","preamble":"Norberg & Partner Sustainable Group AB har lämnat ett offentligt uppköpserbjudande till aktieägarna i Aino Health AB (publ) enligt reglerna om budplikt.","body":"Vinges team består av Anders Strid, Edin Agic och Amelia Rihs.\n\nLäs klients pressmeddelande","href":"https://www.vinge.se/uppdrag/vinge-bitrader-norberg-partner-vid-budpliktsbudet-pa-aino-health/","date":"2023-10-04","month":10},{"year":2023,"client":"Spetses Investments och Bacara Holdings","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Spetses Investments och Bacara Holdings i budet på IRRAS","caption":"Övrigt · 3 oktober 2023","preamble":"Ett budkonsortium har genom IR Holding Bidco Inc. lämnat och fullföljt ett offentligt uppköpserbjudande till aktieägarna i IRRAS AB (publ). Konsortiet bestod bland annat av IRRAS två största aktieägare, Spetses Investments Ltd och Bacara Holdings Limited, vilka har biträtts av Vinge.","body":"Vinges team består av David Andersson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-spetses-investments-och-bacara-holdings-i-budet-pa-irras/","date":"2023-10-03","month":10},{"year":2023,"client":"SAGA Diagnostics","work":"Finansiering","disciplines":[],"title":"Vinge rådgivare till SAGA Diagnostics AB i samband med konvertibelfinansiering","caption":"Finansiering · 28 september 2023","preamble":"SAGA Diagnostics AB, ett bolag verksamt inom cancerdiagnostik, har genomfört en konvertibelfinansiering om cirka 144 miljoner kronor. Vinge företrädde SAGA Diagnostics i samband med transaktionen.","body":"Vinges team bestod av Christian Lindhé, Sofie Nordgren och Agaton Lindgren.","href":"https://www.vinge.se/uppdrag/vinge-radgivare-till-saga-diagnostics-ab-i-samband-med-konvertibelfinansiering/","date":"2023-09-28","month":9},{"year":2023,"client":"Repligen Corporation","work":"Förvärv","disciplines":["M&A","Arbetsrätt","EU‑ och konkurrensrätt","Immaterialrätt","IT, Telekom och Outsourcing","GDPR","Fastigheter och Entreprenad","Corporate Crime & Compliance"],"title":"Vinge företräder Repligen Corporation i samband med förvärvet av Metenova","caption":"Förvärv · 27 september 2023","preamble":"Vinge har företrätt Repligen Corporation med dotterbolag (”Repligen”), en multinationell koncern inom life science som utvecklar och kommersialiserar höginnovativa bioprocessteknologier och system som möjliggör effektiviseringar i processen för tillverkning av biologiska läkemedel, i samband med dess förvärv av Metenova Holding AB med dotterbolag (”Metenova”).","body":"Metenova är en ledande innovatör och tillverkare av magnetiska mixrar för farmaceutisk och bioteknisk användning. Bolaget har sitt huvudsakliga säte i Mölndal, Göteborg.\nGenom förvärvet av Metenova förstärks Repligens portfölj för vätskehantering, med en produktlinje som bygger vidare på framgångarna för Repligens system- och vätskehanteringslösningar.\n\nVinges team bestod huvudsakligen av Jonas Bergström, Johanna Wiberg, Viktor Lennartsson, Robin Sultani (M&A), Sam Seddigh, Hanna Marberg (arbetsrätt), David Olander (konkurrensrätt), Mathilda Persson, Mika Jordan, Arthur Kinski, Mario Saad (kommersiella avtal), Christoffer Nordin (Life Science/Regulatory), Lisa Hörnqvist (IT och GDPR), Stojan Arnerstål, Axel Lennartsson, Johan Gavelin (IP), Kristoffer Larson (fastighet), Mia Falk (compliance), Anders Leissner (sanktioner/exportkontroll) och Cecilia Loctander (projektassistent)","href":"https://www.vinge.se/uppdrag/vinge-foretrader-repligen-corporation-i-samband-med-forvarvet-av-metenova/","date":"2023-09-27","month":9},{"year":2023,"client":"Heda Security","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljning av Heda Security","caption":"Avyttring · 25 september 2023","preamble":"Helix Kapital och övriga aktieägare har avyttrat sina aktier i ADEH Intressenter AB, moderbolag till Heda Security, till EMK Capital.","body":"Under Helix ägarperiod sedan 2018 har koncernen framgångsrikt påvisat stark lönsam tillväxt drivet både av organiska satsningar och en omfattande förvärvsresa, vilket har positionerat koncernen som marknadsledande i Sverige inom områdessäkerhet.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Eléonore Friberg, Maximilian Bengtsson, Per Kling, Christoffer Widström, Emelie Schoning och Emy Rydén.\n\nKlients pressrelease läses här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-heda-security/","date":"2023-09-25","month":9},{"year":2023,"client":"Stirling Square Capital Partners","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Stirling Square Capital Partners i samband med förvärv","caption":"Förvärv · 22 september 2023","preamble":"Vinge har biträtt Stirling Square Capital Partners i samband med dess förvärv av en majoritetsandel i Infobric, en ledande leverantör av mjukvarulösningar för byggbranschen, från Summa Equity.","body":"Summa återinvesterade tillsammans med Stirling Square och Infobrics managementsom en minoritetsinvesterare. Infobric, med huvudkontor i Sverige och verksamhet i Norden och Storbritannien, tillhandahåller end-to-end mjukvaruprodukter som stödjer digitaliseringen av byggbranschen.\n\nVinges team bestod huvudsakligen av Magnus Pauli, Wibeke Sorling och Sofie Nordgren.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-stirling-square-capital-partners-i-samband-med-forvarv/","date":"2023-09-22","month":9},{"year":2023,"client":"Stendörren","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Stendörren vid emission av gröna obligationer och återköpserbjudande","caption":"Obligationsemission · 21 september 2023","preamble":"Vinge biträder Stendörren Fastigheter AB vid dess emission av seniora, icke-säkerställda gröna obligationer om SEK 500 miljoner (inom en ram om SEK 600 miljoner kronor) och i samband med bolagets parallella återköpserbjudande till investerare i dess tidigare emitterade obligationer med förfall under 2024.","body":"Nordea Bank Abp, Swedbank AB (publ) och Danske Bank A/S, Danmark, Sverige Filial agerade joint bookrunners och dealer managers i transaktionen.\n\nEmissionslikviden från den nya obligationen ska, i enlighet med Stendörrens gröna finansieringsramverk, användas för att refinansiera Stendörrens gröna fastighetsbestånd och finansiera återköpserbjudandet. Obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms lista för gröna obligationer. Obligationerna har en löptid om 3,25 år och emitterades med en ränta på STIBOR 3m + 525 baspunkter.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, Felix Möller och August Ahlin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-stendorren-vid-emission-av-grona-obligationer-och-aterkopserbjudande/","date":"2023-09-21","month":9},{"year":2023,"client":"Elektroskandia","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har företrätt Elektroskandia i samband med dess majoritetsinvestering i Aprilice","caption":"Kapitalanskaffning · 20 september 2023","preamble":"Vinge har företrätt Elektroskandia (ett Soneparägt bolag) i samband med dess förvärv av 70 % av aktierna i Aprilice, en av de ledande solenergiplattformarna i Nordeuropa.","body":"Aprilice grundades 2012 och har sedan starten fokuserat på den svenska solcellsmarknaden, med ett komplett produktsortiment i kombination med hög teknisk kompetens. Företaget med, huvudkontor i Stockholm samt filialer i Göteborg, Jönköping, Kalmar och Landskrona, har idag cirka 160 anställda och med en kundbas om cirka 1300 kunder. 2022 omsatte Aprilice strax över 1,1 miljarder kronor. Företagets tre grundare kommer att förbli minoritetsägare och fortsätta arbeta i företaget.\n\nVinges team bestod av Matthias Pannier, Stina Bengtsson, Sophie Böje, David Flodin, Amelia Rihs, Mario Saad, Mika Jordan, Alexandra Tamm, Sebastian Örndahl, Victoria Fredén, Alva Chambert och Cecilia Loctander.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-elektroskandia-i-samband-med-dess-majoritetsinvestering-i-aprilice/","date":"2023-09-20","month":9},{"year":2023,"client":"Ellevio","work":"Förvärv","disciplines":["Arbetsrätt","M&A","Immaterialrätt","Kommersiella avtal","Corporate Crime & Compliance","Fastigheter och Entreprenad","Offentlig upphandling","FDI"],"title":"Vinge företräder Ellevio vid deras förvärv av Markbygden Net AB","caption":"Förvärv · 20 september 2023","preamble":"Vinge företräder Ellevio vid deras förvärv av Markbygden Net AB, ett modernt transmissionsnät som ansluter betydande delar av Europas största vindkraftspark Markbygden 1101 utanför Piteå i norra Sverige, från Svevind och Enercon.","body":"Ellevio är ett av Sveriges största elnätsföretag och genom förvärvet etablerar sig Ellevio för första gången i norra Sverige och stärker sin roll som en ledande aktör i den svenska energiomställningen och vägen mot nettonollutsläpp 2045. Ellevio tillträder Markbygden Net AB den 20 september 2023.\n\nVinges team bestod av ansvarige delägaren Peter Sundgren (Energi/M&A) tillsammans med Desirée Hagenfeldt, Robin Sultani och Eskil Nyström (M&A), Johan Cederblad och Madelene Andersson (Miljörätt), Karolina Cohrs (Fastighetsrätt), Mathilda Persson och Alva Skott (Kommersiella avtal och IT), Mario Saad och Carl Lexenberg (Kommersiella avtal), Daniel Wendelsson (Offentlig upphandling och FDI), Carl Johan af Petersens och Andrea Rökaas (Regulatoriska frågor), Daniel Prawitz (Entreprenadrätt), Arvid Axelryd (IP), Amelia Rihs (Arbetsrätt), David Flodin (Finansiella arrangemang), Julia Löfqvist (Compliance) Gabriella Balbo och Jessica Henning (VDR).\n\nPressmeddelande från klient läses här.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ellevio-vid-deras-forvarv-av-markbygden-net-ab/","date":"2023-09-20","month":9},{"year":2023,"client":"Borgo","work":"Förvärv","disciplines":["Bank och finans","M&A"],"title":"Vinge biträder Borgo i samband med förvärv av bolåneportfölj","caption":"Förvärv · 19 september 2023","preamble":"Vinge har biträtt Borgo i samband med dess förvärv av en bolåneportfölj om ca 5,8 miljarder kronor från Ålandsbanken.","body":"Vinges team bestod huvudsakligen av Johan Larsson, Joacim Rydergård, Mikael Ståhl samt Caroline Krassén.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-borgo-i-samband-med-forvarv-av-bolaneportfolj/","date":"2023-09-19","month":9},{"year":2023,"client":"CAREL Industries S.p.A","work":"Förvärv","disciplines":["Arbetsrätt","M&A","IT, Telekom och Outsourcing"],"title":"Vinge har biträtt CAREL Industries S.p.A i samband med förvärv","caption":"Förvärv · 18 september 2023","preamble":"CAREL Industries S.p.A har ingått ett bindande avtal om att förvärva 82,4% av aktierna i Kiona Holding AS, en ledande norsk Software as a Service (\"SaaS\") leverantör av prop-tech lösningar för optimering av energiförbrukning och digitalisering av byggnader inom detaljhandel och industriell kylning, offentliga, kommersiella och flerbostadsfastigheter. Förvärvspriset för 100% av aktierna baserar sig på ett enterprise value om 2.350.000.000 NOK (ca 2,428,255,000 SEK).","body":"Vinge agerade ombud åt CAREL i de svenska frågorna i samband med transaktionen. Vinge biträdde CAREL tillsammans med Thommessen.\n\nCAREL, baserat i Italien och noterat på börsen i Milano, är en global ledare inom design, produktion och marknadsföring av tekniskt avancerade komponenter och lösningar för utmärkt energieffektivitet vid kontroll av värme, ventilation och luftkonditionering (HVAC) och kylutrustning och system.\n\nVinges team bestod huvudsakligen av Henrik Borna (M&A/IT), Niklas Törnell (M&A), Jonatan Karlsson (M&A) och Sophia Reutercrona (Arbetsrätt)","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-carel-industries-s-p-a-i-samband-med-forvarv/","date":"2023-09-18","month":9},{"year":2023,"client":"Alder","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Alder, Umia och grundarna vid försäljningen av Umia Innovation till TSG","caption":"Kapitalanskaffning · 15 september 2023","preamble":"Vinge företräder Alder, Umia och grundarna vid försäljningen av Umia Innovation till The Specialist Group (TSG), ett portföljbolag till Oaktree Capital Management.","body":"Umia Innovation, med kontor i Umeå, Skellefteå och Örnsköldsvik, erbjuder kunskapsbaserade konsulttjänster inom process, teknik och ledarskap. Bolaget har kunder inom bland annat gruvindustrin, skog, medicinsk teknik, fordonsindustrin och energisektorn. I samband med transaktionen byter Umia Innovation namn till Altio.\n\nVinges team bestod huvudsakligen av Johan Larsson, Karl Klackenberg, Ellinor Wargenbrant, Carl Fredrik Wachtmeister, Robin Fagerström (M&A), samt Jessica Henning och Emy Rydén (projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-alder-umia-och-grundarna-vid-forsaljningen-av-umia-innovation-till-tsg/","date":"2023-09-15","month":9},{"year":2023,"client":"Altor","work":"Förvärv","disciplines":["M&A","EU‑ och konkurrensrätt","Företagsbeskattning"],"title":"Vinge företräder Altor i samband med dess förvärv av en betydande minoritetspost i Marshall Group AB (publ)","caption":"Förvärv · 15 september 2023","preamble":"Vinge företräder Altor Funds (”Altor”) i samband med dess förvärv av en betydande minoritetspost i Marshall Group AB (publ) (”Marshall”) från Varenne AB, Varenne Invest I AB, Zenith Venture Capital I AB, Zenith Venture Capital III AB samt ett stort antal mindre investerare.","body":"Marshall är verksamt inom ljud, teknik och design, på fler än 90 marknader, med cirka fyra miljarder kronor i omsättning och cirka 800 anställda på åtta platser runtom i världen.\n\nVinges team bestod huvudsakligen av Christina Kokko, Johanna Wiberg och Viktor Lennartsson (M&A), David Olander (Konkurrenrätt), Victor Ericsson och Emelie Svanberg (Skatt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-altor-i-samband-med-dess-forvarv-av-en-betydande-minoritetspost-i-marshall-group-ab-publ/","date":"2023-09-15","month":9},{"year":2023,"client":"Det finska börsnoterade bolaget Fiskars Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt det finska börsnoterade bolaget Fiskars Group i samband med dess förvärv","caption":"Förvärv · 15 september 2023","preamble":"Vinge har biträtt det finska börsnoterade bolaget Fiskars Group i samband med dess förvärv av det kända danska designföretaget Georg Jensen för 151,5 miljoner euro från private equity-bolaget Investcorp. Transaktionen förväntas slutföras i början av Q4 2023, med förbehåll för sedvanliga tillträdesvillkor.","body":"Georg Jensen är ett ikoniskt danskt designföretag som grundades 1904 och är globalt erkänt för sitt banbrytande hantverk och sin tidlösa design inom smycken, klockor, silvervaror, hushållsartiklar med mera. Fiskars, Finlands äldsta företag, är känt för sin tillverkning av köksutrustning och trädgårdsprodukter. Fiskars har också ett antal designvarumärken i sin portfölj, inklusive det danska porslinsföretaget Royal Copenhagen. Förvärvet av Georg Jensen är avsett att stärka Fiskars portfölj av lyxvarumärken och stödja Fiskars globala tillväxtstrategi. Vinge biträdde Fiskars tillsammans med Accura i samband med transaktionen.\n\nVinges team bestod huvudsakligen av Magnus Hedsund, Sofie Nordgren och Niklas Törnell.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-det-finska-borsnoterade-bolaget-fiskars-group-i-samband-med-dess-forvarv/","date":"2023-09-15","month":9},{"year":2023,"client":"XVIVO","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har biträtt XVIVO i samband med dess riktad emission om 440 MSEK","caption":"Kapitalanskaffning · 14 september 2023","preamble":"Vinge har biträtt XVIVO Perfusion AB i samband med dess riktade nyemission till en teckningskurs om 275 kronor per aktie som motsvarade XVIVO-aktiens stängningskurs på Nasdaq Stockholm dagen för emission.","body":"XVIVO tillfördes 440 MSEK före emissionskostnader. Teckningskursen bestämdes genom ett accelererat bookbuildingförfarande arrangerat av Carnegie och DNB Markets. Investerare i den riktade emissionen var såväl befintliga som nya aktieägare, såsom Bure Equity AB, Fjärde AP-fonden, Swedbank Robur Fonder, Eccenovo, Handelsbanken Fonder, Tredje AP-fonden samt en Tier-1 global internationell investerare.\n\nVinges team bestod huvudsakligen av Anders Strid och projektledaren Edin Agic.\n\nLäs klientens pressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-xvivo-i-samband-med-dess-riktad-emission-om-440-msek/","date":"2023-09-14","month":9},{"year":2023,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Lagercrantz Group vid förvärv av Letti","caption":"Förvärv · 12 september 2023","preamble":"Lagercrantz Group har förvärvat samtliga aktier i norska Letti AS. Letti är ledande tillverkare av installations- och fästmaterial för kablar och kabelrör.","body":"Vinge, genom Johan Winnerblad, och den norska advokatbyrån Wiersholm har biträtt Lagercrantz Group vid förvärvet.\n\nLäs klientens pressmeddelande här.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-vid-forvarv-av-letti/","date":"2023-09-12","month":9},{"year":2023,"client":"Altor","work":"Kapitalanskaffning","disciplines":["M&A","Miljörätt","Offentlig upphandling","Corporate Crime & Compliance","Bank och finans","Fastigheter och Entreprenad","Kommersiella avtal","EU‑ och konkurrensrätt","Immaterialrätt"],"title":"Vinge företräder Altor i samband med investering i H2 Green Steel","caption":"Kapitalanskaffning · 8 september 2023","preamble":"Vinge företräder Altor i samband med dess investering i H2 Green Steel. Investeringen har genomförts i samband med investeringsrunda i H2 Green Steel om totalt ca 1,5 miljarder euro. Deltagande investerare var, utöver Altor, bland andra AMF, GIC, Hitachi Energy, Kinnevik, Schaeffler, Andra AP-fonden, FAM, Hy24 och Just Climate.","body":"H2 Green Steel grundades 2020 med ambitionen att påskynda utfasningen av fossila bränslen i tunga industrier. Företaget börjar med stål, som är en av världens största koldioxidutsläppare, och bygger ett stålverk i Boden, norra Sverige. Anläggningen kommer att producera grönt stål och minska koldioxidutsläppen med upp till 95 procent jämfört med traditionell ståltillverkning. Markarbeten har pågått i Boden sedan sommaren 2022, och med denna transaktion tar H2 Green Steel ett betydande steg närmare att inleda verksamheten i slutet av 2025.\n\nVinges team bestod huvudsakligen av Johan Larsson, Isabelle Wållgren, Robin Fagerström (M&A), Christoffer Nordin, Jolene Reimerson, Elis Allmark (Commercial Agreements), Johan Cederblad, Lina Österberg (Environment), Kristoffer Larson (Real Estate), Mathilda Persson (IT), Mia Falk, Julia Löfqvist, (Compliance), Louise Brorsson Salomon, Helena Göransson, Kamyar Najmi (Banking and Finance), Axel Lennartsson (IP), Johan Wahlbom (Competition law), Daniel Wendelsson (Regulatory), Emy Rydén och Ottilia Pettersson (projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-altor-i-samband-med-investering-i-h2-green-steel-1/","date":"2023-09-08","month":9},{"year":2023,"client":"Flat Capital","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Flat Capital i samband med dess företrädesemission","caption":"Kapitalanskaffning · 7 september 2023","preamble":"Vinge har företrätt Flat Capital i samband med dess företrädesemission, varigenom bolaget tillförs cirka 153 miljoner kronor före emissionskostnader.","body":"Flat Capital är ett investeringsbolag som grundades 2013 och som fokuserar på bolag med framstående entreprenörer i ledande ställning. Portföljen består av 21 bolag varav de största innehaven inkluderar Instabee, Getir, OpenAI, Truecaller och Klarna.\n\nFlat Capital är noterat på Nasdaq First North Growth Market.\n\nVinges team bestod av Jesper Schönbeck, Joel Wahlberg, Adrian Filipovic och Johannes Akyol.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-flat-capital-i-samband-med-dess-foretradesemission-1/","date":"2023-09-07","month":9},{"year":2023,"client":"Sobro","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Sobro vid investering i Prefabsystem Syd","caption":"Kapitalanskaffning · 5 september 2023","preamble":"Prefabsystem Syd har valt att bredda sitt ägande med Sobro som ny ägarpartner. Grundaren Hans Lindfors kvarstår i sin operativa roll och som betydande ägare samtidigt som fler medarbetare kommer in som nya delägare. Prefabsystem Syd är specialister på komplexa, prefabricerade stomsystem.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Per Kling, Philip Moré, Hanna Marberg, Agnes Pigg, David Olander, Hampus Peterson och Clara Klingspor.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sobro-vid-investering-i-prefabsystem-syd/","date":"2023-09-05","month":9},{"year":2023,"client":"Helix Kapital","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Helix Kapital vid investering i Trinax","caption":"Kapitalanskaffning · 4 september 2023","preamble":"Vinge har biträtt Helix Kapital när fonden ingått partnerskap med Trinax AB:s grundare och ledning för accelererad tillväxt.","body":"Trinax är ett ledande mjukvarubolag inom tidrapportering och projekthantering.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Gustav Wahlberg, Fredrika Hjelmberg, Rebecka Målquist och Johan Gavelin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-helix-kapital-vid-investering-i-trinax/","date":"2023-09-04","month":9},{"year":2023,"client":"Main Capital","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder Main Capital vid försäljningen av Assessio","caption":"Avyttring · 1 september 2023","preamble":"Vinge företräder Main Capital V (”Main Capital”) vid försäljningen av Assessio International Holding 2 AB med dotterbolag (”Assessio”)","body":"Assessio är ett SaaS-bolag specialiserade inom strategisk HR och utvecklar tester och verktyg inom arbetspsykologi. Deras verktyg kan bland annat hjälpa organisationer att förutsäga vem som har bäst potential att lyckas i en roll, hitta framtidens ledare i organisationen och definiera sin organisationskultur och matcha den med individers värderingar.\n\nMain Capital förvärvade Assessio 2019 och Assessio har sedan dess fördubblat sin omsättning och är idag den ledande aktören inom talangutvärderingar i både Norden och Benelux, med över 1 800 kunder inom ett brett spektrum av branscher.\n\nVinges bestod huvudsakligen av Jonas Johansson, Filip Öhrner, Maria Dahlin Kolvik, Per Kling, Stina Bengtsson, Gustav Persson, Johan Gavelin, Sophie Böje, Alexander Rüdén och Anna Ekdahl Roos.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-vid-forsaljningen-av-assessio/","date":"2023-09-01","month":9},{"year":2023,"client":"Bridgepoint","work":"Förvärv","disciplines":[],"title":"Vinge företräder Bridgepoint vid förvärvet av Ports Group","caption":"Förvärv · 31 augusti 2023","preamble":"Vinge företräder Bridgepoint Development Capital (\"Bridgepoint\") i samband med förvärvet av House of Ports Holding AB (\"Ports Group\").","body":"Ports Group är en snabbväxande och lönsam plattformsbaserad leverantör av IP- och domäntjänster. Ports Group har en unik position på marknaden med 25 års erfarenhet av digitalisering som ICANN-ackrediterad registrar och ett heltäckande Brand Protection-paket inklusive mjukvara och tjänster inom Domain Management, Trademark Management och Web Security. Proaktivt skydd genom Ports Groups övervakningstjänster säkrar kundens immateriella rättigheter och exklusiva rättigheter. Centralt för vad Ports erbjuder är mjukvaruplattformen Ports Management, som sammanför portföljen av innehav, vilket ger en optimal överblick och automatiserad hantering. Plattformen hanterar domäner, varumärkesinnehav och webbsäkerhetsprodukter.\n\nVinges team bestod av Daniel Rosvall, Samra Tesser, Ellen Flygt, Michella Lina Said och Elis Allmark (M&A), Louise Brorsson Salomon, Josefine Lanker, Jolinn Uhlin, David Flodin, Nour Makie (Bank och Finans), Mathilda Persson, Mika Jordan och Jolene Reimerson (IT och GDPR), Mario Saad (Commercial), Julia Löfqvist (Compliance), Alexandra Tamm (Fastighet), David Olander (EU och konkurrensrätt), samt Cecilia Loctander (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-bridgepoint-vid-forvarvet-av-ports-group/","date":"2023-08-31","month":8},{"year":2023,"client":"TA Associates tillsammans","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder TA Associates tillsammans med Goodwin Procter i samband med förvärv","caption":"Förvärv · 23 augusti 2023","preamble":"De ledande globala private equity-bolagen TA Associates och Warburg Pincus LLC har ingått avtal om att förvärva en majoritetsandel i Epassi Group från majoritetsägaren Bregal Milestone. Vinge biträdde TA Associates med avseende på svenska frågor i transaktionen. Vinge biträdde TA Associates tillsammans med Goodwin Procter.","body":"TA är ett ledande globalt private equity-bolag med fokus på tillväxt i lönsamma företag. Warburg Pincus är en ledande global tillväxtinvesterare och en erfaren partner till ledningsgrupper som strävar efter att bygga hållbara företag med hållbart värde. Epassi Group är Europas ledande digitala lösning för personalförmåner med en räckvidd på nästan 13 miljoner användare, över 13 500 arbetsgivare och mer än 59 000 tjänsteleverantörer. Epassi är marknadsledande inom digitala personalförmåner i Norden, Italien och Storbritannien och har utsetts av Financial Times till ett av de snabbast växande företagen i Europa under 2022 och 2023.\n\nVinges team bestod huvudsakligen av Sofie Nordgren, Niklas Törnell och Emil Sandgrim.\n\nLäs pressrelease här","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ta-associates-tillsammans-med-goodwin-procter-i-samband-med-forvarv/","date":"2023-08-23","month":8},{"year":2023,"client":"Polar Structure","work":"Obligationsemission","disciplines":[],"title":"Vinge har biträtt Polar Structure AB vid dess emission av seniora säkerställda obligationer om 835 miljoner kronor","caption":"Obligationsemission · 18 augusti 2023","preamble":"Vinge har biträtt Polar Structure AB, en utvecklare och ägare av infrastruktur, vid bolagets emission av seniora säkerställda obligationer om 835 miljoner kronor genom ett helägt dotterbolag.","body":"Obligationerna löper med en fast ränta och en löptid om 15 år. Lånet är säkerställt med pant i fem järnvägsrelaterade tillgångar belägna i tre strategiska järnvägsknutpunkter i Sverige. Transaktionen möjliggör en långsiktig finansiering av tillgångarna och kommer att ytterligare diversifiera bolagets kapitalstruktur.\n\nVinges team bestod primärt av Niclas Winnberg, Helena Göransson, Arvid Weimers, Kristoffer Larson, Kamyar Najmi, Felix Möller, Karl-Gustaw Tobola, Nour Makie och August Ahlin.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-polar-structure-ab-vid-dess-emission-av-seniora-sakerstallda-obligationer-om-835-miljoner-kronor/","date":"2023-08-18","month":8},{"year":2023,"client":"Säljarna","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder säljarna i samband med försäljningen av von Euler & Partners AB","caption":"Avyttring · 15 augusti 2023","preamble":"Vinge företräder säljarna i samband med försäljningen av von Euler & Partners AB till Säkra AB.","body":"von Euler & Partners AB bildades 2002 och har en lång erfarenhet inom family office, förmögenhetsförvaltning och investeringsrådgivning och ska stärka Säkras erbjudande för finansiella rådgivningstjänster.\n\nVinges team bestod av Jonas Bergström, Joacim Rydergård, Gustav Wahlberg och Josef Groow (M&A) och Ellinore Boström samt Ottilia Pettersson (Projektassistenter)","href":"https://www.vinge.se/uppdrag/vinge-foretrader-saljarna-i-samband-med-forsaljningen-av-von-euler-partners-ab/","date":"2023-08-15","month":8},{"year":2023,"client":"Köparna","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträdde köparna i samband med förvärvet av Mechanum","caption":"Förvärv · 15 augusti 2023","preamble":"Vinge biträdde MGN Holding, bestående primärt av grundare och ledning av bolaget, vid dess förvärv av Mechanum från bland annat Navigo Invest.","body":"Mechanum är en renodlad auktoriserad flermärkesverkstad som utför service, reparationer och garantiarbeten på personbilar och transportbilar. Mechanum omsatte cirka 488 miljoner kronor under verksamhetsåret 2022 och har totalt över 300 anställda vid sina sju anläggningar i Göteborg, Stockholm och Malmö.\n\nVinges team bestod av främst av Carl Sander, Linus Adolfsson och Alexander Rüdén.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-koparna-i-samband-med-forvarvet-av-mechanum/","date":"2023-08-15","month":8},{"year":2023,"client":"Main Capital och Pointsharp","work":"Övrigt","disciplines":["M&A","Företagsbeskattning"],"title":"Vinge har biträtt Main Capital och Pointsharp vid dess strategiska sammangående med SIVIS","caption":"Övrigt · 10 augusti 2023","preamble":"Pointsharp möjliggör för organisationer att säkra IT-miljöer med en hög nivå av kontroll för IT-avdelningar i kombination med en intuitiv mobil användarupplevelse.","body":"Pointsharp har en bred produktportfölj inom identitets- och åtkomsthantering som kan användas med multifaktorautentisering, säkerhetsgateway, användarbehörighet och lösenordshantering. SIVIS, som grundades 1999 och är baserat i Tyskland och Danmark, fokuserar bland annat på identitets- och åtkomsthantering och riskhantering.\n\nTillägget av SIVIS starka erbjudande inom identitets- och åtkomsthantering förväntas stärka den sammanslagna koncernens position på marknaden.\n\nVinges team bestod av Filip Öhrner, Linus Adolfsson och Josef Groow.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-main-capital-och-pointsharp-vid-dess-strategiska-sammangaende-med-sivis/","date":"2023-08-10","month":8},{"year":2023,"client":"FishBrain","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder FishBrain i finansieringsrunda","caption":"Kapitalanskaffning · 7 augusti 2023","preamble":"FishBrain AB (publ), den ledande sportfiskeappen, har tagit in cirka 6 miljoner dollar i en nyemission.","body":"Kapitalanskaffningen leddes av den svenska riskkapitalfonden Industrifonden och tillsammans med det New York-baserade investmentbolaget Lucerne Capital Management.\n\nVinges team bestod av Johan Larsson, Clara Sohlberg och Oskar Nilsson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-fishbrain-i-finansieringsrunda/","date":"2023-08-07","month":8},{"year":2023,"client":"Damen Shipyards Group","work":"Partnerskap","disciplines":["M&A"],"title":"Vinge har företrätt Damen Shipyards Group vid dess strategiska partnerskap med Lazarus Industriförvaltning avseende Oskarhamnsvarvet i syfte att stärka sin position på den svenska marknaden","caption":"Partnerskap · 7 augusti 2023","preamble":"Vinges team har huvudsakligen bestått av Jonas Bergström och Stina Bengtsson.","body":null,"href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-damen-shipyards-group-vid-dess-strategiska-partnerskap-med-lazarus-industriforvaltning-avseende-oskarhamnsvarvet-i-syfte-att-starka-sin-position-pa-den-svenska-marknaden/","date":"2023-08-07","month":8},{"year":2023,"client":"Samhällsbyggnadsbolaget","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A","Arbetsrätt","Bank och finans","IT, Telekom och Outsourcing","GDPR"],"title":"Vinge har företrätt Samhällsbyggnadsbolaget i Norden AB (publ) (”SBB”) i samband med att dess nybildade dotterbolag SBB Residential Property AB ingått ett avtal om kapitalanskaffning med en investeringsfond som förvaltas av Morgan Stanley Real Estate Investing (”MSREI”).","caption":"Kapitalanskaffning · 25 juli 2023","preamble":"Enligt avtalet kommer SBB Residential Property AB emittera preferensaktier om 2,36 miljarder SEK till MSREI. Preferensaktierna kommer att emitteras av en entitet med namnet SBB Residential Property AB som bildar en ny underkoncern inom SBB.","body":"Efter transaktionen kommer MSREI inneha en minoritetsandel i SBB Residential Property AB. Transaktionen är föremål för sedvanliga fullföljandevillkor men inte konkurrensgodkännande. Fullföljande av transaktionen kommer att ske så snart som alla fullföljandevillkor har uppfyllts, vilket väntas ske omkring mitten av augusti 2023.\n\nVinges team bestod huvudsakligen av Mikael Ståhl, Jesper Schönbeck, Rikard Lindahl, Niclas Winnberg, Helena Göransson, Ulrich Ziche, Maria Dahlin Kolvik, Kristoffer Larsson, Frida Ställborn, Joel Magnusson, Kamyar Najmi, Nour Makie, Ida Redander och Filip Magnusson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-samhallsbyggnadsbolaget-i-norden-ab-publ-sbb-i-samband-med-att-dess-nybildade-dotterbolag-sbb-residential-property-ab-ingatt-ett-avtal-om-kapitalanskaffning-med-en-investeringsfond-som-forvaltas-av-morgan-stanley-real-es/","date":"2023-07-25","month":7},{"year":2023,"client":"Axel Johnson","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","EU‑ och konkurrensrätt"],"title":"Vinge biträder Axel Johnson i budet på Dustin","caption":"Övrigt · 2 juli 2023","preamble":"Axel Johnson AB, genom det helägda dotterbolaget AxMedia AB, har lämnat ett offentligt uppköpserbjudande till aktieägarna i Dustin Group AB (publ) enligt reglerna om budplikt. Budet värderar samtliga aktier i Dustin till cirka 3,2 miljarder kronor.","body":"Vinges team består av Erik Sjöman, Agaton Lindgren, Trine Osen Bergqvist och Victoria Fredén.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-axel-johnson-i-budet-pa-dustin/","date":"2023-07-02","month":7},{"year":2023,"client":"Re:NewCell","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Re:NewCell i samband med en riktad nyemission","caption":"Kapitalanskaffning · 30 juni 2023","preamble":"Vinge har företrätt Re:NewCell, ett textilåtervinningsbolag noterat på Nasdaq First North Premier Growth Market, i samband med en riktad nyemission varigenom bolaget tillfördes cirka 240 miljoner kronor före emissionskostnader.","body":"Emissionen riktades till ett antal utvalda svenska och internationella institutionella investerare på grundval av en accelererad bookbuilding process.\n\nRe:NewCell AB (publ) grundades 2012 av forskare vid KTH i Stockholm. Det är ett flerfaldigt prisbelönt sustaintechbolag baserat i Sverige. Renewcells vision är att göra modeindustrin cirkulär.\n\nVinges team bestod av Dain Hård Nevonen, William Kåge och Annie Fällström.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-re-newcell-i-samband-med-en-riktad-nyemission-2/","date":"2023-06-30","month":6},{"year":2023,"client":"Bergs Timber","work":"Förvärv","disciplines":["M&A","Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge företräder Bergs Timber AB (publ) i förvärv av Hedlunda Holding AB","caption":"Förvärv · 30 juni 2023","preamble":"Hedlunda är en högmodern tillverkare av trämöbler och komponenter med produktionsanläggningar i Sverige (Lycksele) och i Polen (Skoczów). Förvärvet stärker Bergs erbjudande inom träförädling och innebär även en breddning av verksamheten mot möbelsektorn. Hedlunda kommer tillsammans med Bergs befintliga affär inom komponentförsäljning till industrikunder bilda ett nytt produktområde, Furniture & Components.","body":"Vinges team bestod av Ulrich Ziche, Gustav Persson (M&A), Louise Brorsson Salomon, Nour Makie (bank och finans), Joel Wahlberg (public M&A), Ulf Nilsson, Maria Schultzberg (skatt) och Ellinore Boström Andersson (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-bergs-timber-ab-publ-i-forvarv-av-hedlunda-holding-ab/","date":"2023-06-30","month":6},{"year":2023,"client":"Ägaren till Compilator","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder ägaren till Compilator AB i samband med försäljning av bolaget till Kerridge Commercial Systems Ltd (”KCS”).","caption":"Avyttring · 29 juni 2023","preamble":"Compilator AB utvecklar ERP-system till däckbranschen. KCS är en marknadsledande leverantör av ERP- och affärssystem med över 35.000 kunder över hela världen, med fokus på fordons-, distributions-, detaljhandels- och maskinuthyrningsmarknaderna.","body":"Förvärvet har strategisk betydelse för KCS, då det breddar koncernens produktutbud mot däckbranschen och dessutom ger koncernen en närvaro på den skandinaviska marknaden.\n\nVinges team bestod i huvudsak av Jesper Ottergren, Jonatan Karlsson (M&A) och Annika Tingström (projektassistent).\n\nPressmeddelande.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-agaren-till-compilator-ab-i-samband-med-forsaljning-av-bolaget-till-kerridge-commercial-systems-ltd-kcs/","date":"2023-06-29","month":6},{"year":2023,"client":"Skandia","work":"Kapitalanskaffning","disciplines":["Bank och finans","M&A"],"title":"Vinge företräder Skandia vid dess investering i Lumera","caption":"Kapitalanskaffning · 27 juni 2023","preamble":"Vinge företräder Skandia vid dess förvärv av en minoritetspost i Lumera från Monterro. I samband därmed förvärvar även AMF en minoritetspost från Monterro, samt att Monterro återinvesterar i Lumera genom sin fond M4, vilket innebar att Monterro kvarstår som majoritetsägare genom dess fonder M2 och M4.","body":"Lumera är ett mjukvarubolag som utvecklar affärssystem för liv- och pensionsförsäkringsbranschen, bl.a. genom ett molnbaserat system som administrerar försäkringspolicyn.\n\nVinges team bestod av Viveka Classon, Samra Tesser, Jonna Bondemark och Philip Moré.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-skandia-vid-dess-investering-i-lumera/","date":"2023-06-27","month":6},{"year":2023,"client":"KKR","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder KKR vid ytterligare investering i Söderberg & Partners","caption":"Kapitalanskaffning · 27 juni 2023","preamble":"Söderberg & Partners tar in nytt kapital till fortsatt internationell expansion. Nuvarande minoritetsägaren KKR investerar ytterligare 2,3 miljarder SEK genom en nyemission. KKR kvarstår som en betydande minoritetsägare i Söderberg & Partners efter emissionen tillsammans med TA Associates. Kontrollen över bolaget ligger dock fortsatt hos dess grundare och styrelseordförande.","body":"Vinges team bestod av Christina Kokko, Samra Tesser och Maximilian Bengtsson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-kkr-vid-ytterligare-investering-i-soderberg-partners/","date":"2023-06-27","month":6},{"year":2023,"client":"Baseload Capital","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Baseload Capital i samband med investering från Baker Hughes","caption":"Kapitalanskaffning · 22 juni 2023","preamble":"Vinge har biträtt Baseload Capital Holding AB i samband med att Baker Hughes genomför en andra, strategisk investering i bolaget.","body":"Baseload Capital är en ledande investeringsenhet som arbetar för att främja utbyggnaden av geotermisk energi globalt. Genom att etablera operativa bolag på olika platser i världen samarbetar Baseload Capital med lokala samhällen och energileverantörer för att ta i drift, upphandla tillstånd och bygga geotermiska kraftverk som finansieras av Baseload Capital. Baseload Capital och dess dotterbolag Baseload Power är verksamma på mogna geotermiska marknader som Island, USA och Japan, samt på tillväxtmarknader som Taiwan.\n\nVinges team bestod huvudsakligen av Maria Dahlin Kolvik, Clara Sohlberg och Måns Håkansson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-baseload-capital-i-samband-med-investering-fran-baker-hughes/","date":"2023-06-22","month":6},{"year":2023,"client":"EQT IX","work":"Avyttring","disciplines":["M&A"],"title":"Vinge har biträtt EQT IX i samband med försäljning av aktier i Beijer Ref AB (publ)","caption":"Avyttring · 22 juni 2023","preamble":"Vinge har biträtt EQT IX (”EQT”) i samband med nedförsäljning av aktier i Beijer Ref AB (publ) i en så kallad accelererad bookbuilding-process genomförd den 20 juni 2023.","body":"Totalt placerades 40 miljoner aktier till ett pris om 140 kronor per aktie, motsvarande ett sammanlagt värde om 5,6 miljarder kronor.\n\nVinges team bestod av Sofie Bjärtun och Linnéa Sellström.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-eqt-ix-i-samband-med-forsaljning-av-aktier-i-beijer-ref-ab-publ/","date":"2023-06-22","month":6},{"year":2023,"client":"SEB Kort Bank","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder SEB Kort Bank AB i samband med förvärvet av Lufthansa AirPlus Servicekarten GmbH","caption":"Förvärv · 21 juni 2023","preamble":"SEB Kort Bank AB (”SEB Kort”), ett helägt dotterbolag inom SEB-koncernen, har ingått avtal med Lufthansa Group om att förvärva samtliga aktier i Lufthansa AirPlus Servicekarten GmbH (”AirPlus”).","body":"Tillsammans blir SEB Kort och AirPlus en ledande europeisk aktör inom företagsbetalningar. För en kontant köpeskilling på 450 miljoner euro kommer transaktionen att ge SEB Kort ytterligare skala, en stark position för ytterligare tillväxt i Europa samt en modern IT-plattform. Dessutom förväntas transaktionen resultera i synergier och kompletterar även SEB:s bredare ambitioner inom företagsaffären i DACH-regionen (Tyskland, Österrike och Schweiz) och norra Europa.\n\nVinge har i samband med transaktionen agerat lokalt ombud för SEB Kort och biträtt i svenska bolagsrättsliga och regulatoriska frågor.\n\nTransaktionen är bland annat villkorad av myndighetsgodkännanden.\n\nVinges team bestod av Daniel Rosvall och Viktor Lennartsson (M&A) samt Caroline Krassén (Financial Services).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-seb-kort-bank-ab-i-samband-med-forvarvet-av-lufthansa-airplus-servicekarten-gmbh/","date":"2023-06-21","month":6},{"year":2023,"client":"Bilia","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Bilia vid obligationsemission och återköpserbjudande","caption":"Obligationsemission · 19 juni 2023","preamble":"Vinge biträder Bilia AB vid dess emission av seniora, icke-säkerställda obligationer om SEK 800 miljoner (inom en ram om SEK 1500 miljoner) och i samband med bolagets parallella återköpserbjudande till investerare i dess tidigare emitterade obligationer med förfall under 2023.","body":"DNB Markets, en del av DNB Bank ASA, filial Sverige och Nordea Bank Abp agerade joint bookrunners och dealer managers i transaktionen.\n\nEmissionslikviden från den nya obligationen används för att finansiera återköpserbjudandet och för allmänna företagsändamål, och obligationerna ska enligt villkoren upptas till handel på Nasdaq Stockholms lista för företagsobligationer. Obligationerna har en löptid om fem år och emitterades med en ränta på STIBOR 3m + 275 baspunkter.\n\nVinges team bestod av Anders Strid, Lionardo Ojeda och August Ahlin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-bilia-vid-obligationsemission-och-aterkopserbjudande/","date":"2023-06-19","month":6},{"year":2023,"client":"Sergel Group","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge har biträtt Sergel Group vid dess emission av seniora säkerställda obligationer om 325 miljoner kronor","caption":"Obligationsemission · 16 juni 2023","preamble":"Vinge har biträtt Legres AB (publ) (del av Sergel Group) i samband med bolagets emission av seniora säkerställda obligationer om 325 miljoner kronor samt ändring av obligationsvillkoren för bolagets befintliga, efterställda obligationer.","body":"ABG Sundal Collier agerade ensam arrangör och emissionsinstitut. Likviden från emissionen ska användas för att refinansiera bolagets befintliga seniora obligationer.\n\nObligationerna har en löptid om 2,5 år och en rörlig ränta om 3 månaders STIBOR + 900 baspunkter. Bolaget kommer ansöka om upptagande till handel av obligationerna på Nasdaq Stockholm.\n\nVinges team bestod av Mikael Ståhl, Arvid Weimers, Felix Möller och August Ahlin.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-sergel-group-vid-dess-emission-av-seniora-sakerstallda-obligationer-om-325-miljoner-kronor/","date":"2023-06-16","month":6},{"year":2023,"client":"Axcel","work":"Förvärv","disciplines":["M&A","EU‑ och konkurrensrätt","Kommersiella avtal","Arbetsrätt","Bank och finans","Immaterialrätt","IT, Telekom och Outsourcing","GDPR"],"title":"Vinge företräder Axcel vid förvärv av Progrits, ett ledande programvaruföretag inom vertikal mjukvara och informationstjänster","caption":"Förvärv · 14 juni 2023","preamble":"Progrits består av tio verksamheter som utvecklar och levererar verksamhetskritisk programvara och informationstjänster inom transport och logistik, fordonshandel och integrerad e-handel. Det B2B-fokuserade programvaruföretaget förenklar och automatiserar hanteringen av kundinformation och arbetsflöden för sina cirka 5 000 nordiska och internationella kunder.","body":"Transaktionen är villkorad av tillämplig konkurrensmyndighets godkännande.\n\nVinges team bestod av Christina Kokko, Johanna Wiberg, Viktor Lennartsson, Nando Basic och Josef Groow (M&A), Mathilda Persson och Alva Skott (Kommersiella avtal), August Ahlin (Bank och finans), Madelene Andersson (Fastighetsrätt), Julia Löfqvist (Regelefterlevnad), Tove Hallbäck (Arbetsrätt), Lisa Hörnqvist (IT och GDPR), Arvid Axelryd och Felizia Wiker (Immaterialrätt), Sebastian Örndahl, Victoria Fredén och Hampus Peterson (Konkurrensanmälan) och Ellinore Boström Andersson (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-vid-forvarv-av-progrits-ett-ledande-programvaruforetag-inom-vertikal-mjukvara-och-informationstjanster/","date":"2023-06-14","month":6},{"year":2023,"client":"Svenska","work":"Kapitalanskaffning","disciplines":[],"title":"Svenska klimatteknikbolaget ClimateView tar in ca 14 miljoner euro i sin serie A+ runda","caption":"Kapitalanskaffning · 14 juni 2023","preamble":"Investeringsrundan har letts av 2050, en investerare med tydligt fokus på investeringar i gröna och hållbara bolag. I tillägg så backas rundan bland annat av de tidigare investerarna CommerzVentures och NordicNinja samt av de nya investerarna Polar Structure, Sandwater och La Banque Postale.","body":"ClimateView har utvecklat en unik teknikplattform (ClimateOS) som hjälper städer att skapa och implementera strategier för att möta sina klimatmål.\n\nVinges team har huvudsakligen bestått av Johan Larsson och Per Kling.","href":"https://www.vinge.se/uppdrag/svenska-klimatteknikbolaget-climateview-tar-in-ca-14-miljoner-euro-i-sin-serie-a-runda/","date":"2023-06-14","month":6},{"year":2023,"client":"Vicore Pharma Holding","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Vicore Pharma Holding AB (publ) i samband med riktade nyemissioner","caption":"Kapitalanskaffning · 12 juni 2023","preamble":"Vinge har företrätt Vicore Pharma Holding AB (publ) i samband med riktade nyemissioner, varigenom Vicore Pharma tillförs 500 miljoner kronor före transaktionskostnader.","body":"Emissionerna riktades till ett antal svenska och internationella institutionella investerare på grundval av ett accelererat bookbuilding-förfarande. En av emissionerna är villkorad av extra bolagsstämmas godkännande samt att ett prospekt publiceras. Vicore Pharma är ett svenskt läkemedelsbolag i klinisk fas med fokus på att utveckla en ny klass av läkemedel för att stoppa sjukdomsprogress och återställa funktion. Bolaget utvecklar en läkemedelsportfölj inom ovanliga lungsjukdomar, inkluderande idiopatisk lungfibros (IPF) och pulmonell hypertension (PH).\n\nVinges team har bestått av Rikard Lindahl, Joel Magnusson och Annie Fällström.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-vicore-pharma-holding-ab-publ-i-samband-med-riktade-nyemissioner/","date":"2023-06-12","month":6},{"year":2023,"client":"Fidelio Capital","work":"Fondetablering","disciplines":["Arbetsrätt","Bank och finans","Företagsbeskattning","Private Funds","M&A"],"title":"Vinge har biträtt Fidelio Capital vid etableringen av dess största fond hittills","caption":"Fondetablering · 8 juni 2023","preamble":"Fonden – som är Fidelio Capitals tredje – har erhållit över 1 miljard euro i investeringsåtaganden från en internationell investerarbas, och tredubblar därmed de totala investeraråtagandena från tidigare investeringsmandat.","body":"Fidelio Capital grundades av Gabriel Fitzgerald 2010 och fokuserar på investeringar i bolag utan förutbestämda exithorisonter eller geografiska begränsningar, i vilka man kan vara en aktiv huvudägare. Genom sin investeringsstrategi har man genererat en marknadsledande avkastning motsvarande en genomsnittlig gross IRR om 80 % sedan start.\n\nVinges team har huvudsakligen bestått av Mattias Schömer, Jonas Bergström, Jesper Ottergren, Martin Cronsioe, Viveka Classon, Malin Malm Waerme, Fredrik Dahl, Anton Sjökvist, Emelie Svanberg, Semir Omerbasic och Viktoria Wnuk.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-fidelio-capital-vid-etableringen-av-dess-storsta-fond-hittills/","date":"2023-06-08","month":6},{"year":2023,"client":"Symrise","work":"Offentligt uppköpserbjudande","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Symrise i budpliktsbudet på Swedencare","caption":"Offentligt uppköpserbjudande · 7 juni 2023","preamble":"Symrise AG har lämnat ett offentligt uppköpserbjudande till aktieägarna i Swedencare AB (publ) enligt reglerna om budplikt.","body":"Budet värderar samtliga aktier i Swedencare till cirka 5,96 miljarder kronor.\n\nVinges team består av Jesper Schönbeck, Linnéa Sellström, Benjamin Vafaeian och Isabell Anstrin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-symrise-i-budpliktsbudet-pa-swedencare/","date":"2023-06-07","month":6},{"year":2023,"client":"Evroc","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder evroc i pre-seed finansieringsrunda","caption":"Kapitalanskaffning · 6 juni 2023","preamble":"Svenska evroc planerar att bygga flera stora datacenter i Europa. Satsningen på molntjänster kan skapa tusentals nya jobb. Målet är att ta in drygt 30 miljarder kronor. Bland de första investerarna finns EQT Ventures och Norrsken VC.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Stina Bengtsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-evroc-i-pre-seed-finansieringsrunda/","date":"2023-06-06","month":6},{"year":2023,"client":"Stride.VC","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Stride.VC i samband med investering i Anotherblock","caption":"Kapitalanskaffning · 25 maj 2023","preamble":"Anotherblock lanserade 2022 en blockkedjebaserad marknadsplats för musikrättigheter. Bolaget har via sin plattform gett fans tillgång till streamingrättigheter för låtar av flera kända artister. Investeringsrundan leds av Stride.VC.","body":"Vinges team har huvudsakligen bestått av Filip Öhrner, Ellinor Wargenbrant, Sofia Bergenstråhle och Narin Melazade.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-stride-vc-i-samband-med-investering-i-anotherblock/","date":"2023-05-25","month":5},{"year":2023,"client":"M42","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder M42 i samband med förvärvet av Diaverum från Bridgepoint","caption":"Förvärv · 22 maj 2023","preamble":"Vinge företräder M42, ett Abu Dhabi-baserat teknikbaserat hälsovårdsföretag, i samband med dess förvärv av Diaverum AB. M42 är ett globalt ledande företag inom hälso- och sjukvård.","body":"Diaverum är för närvarande världens tredje största leverantör av dialystjänster, verksamt i 23 länder, med 440 kliniker och över 13 000 anställda. Förvärvet av Diaverum innebär en betydande utvidgning av M42:s globala geografiska närvaro, vilket gör det möjligt för företaget att introducera relevanta hälsovårdstjänster och hälsotekniska lösningar på nya marknader samtidigt som det ytterligare förbättrar sitt njurvårdserbjudande i GCC. Transaktionen som är föremål för sedvanliga fullföljandevillkor förväntas slutföras senare under 2023.\n\nVinges team bestod av Matthias Pannier, Stina Bengtsson, Christoffer Nordin, Josefin Lanker och Josef Groow.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-m42-i-samband-med-forvarvet-av-diaverum-fran-bridgepoint/","date":"2023-05-22","month":5},{"year":2023,"client":"Tele2","work":"Obligationsemission","disciplines":["Bank och finans","Företagsbeskattning"],"title":"Vinge biträder Tele2 vid obligationsemission och återköpserbjudande","caption":"Obligationsemission · 22 maj 2023","preamble":"Vinge biträder Tele2 AB (publ) vid dess emission av seniora, icke-säkerställda fastränteobligationer om EUR 500 miljoner och i samband med bolagets parallella återköpserbjudande till investerare i dess tidigare emitterade obligationer med förfall under 2024.","body":"Emissionslikviden från den nya obligationen, vilken emitterats under Tele2:s EMTN-program med en ram om EUR 5 miljarder, används för att finansiera återköpserbjudandet och för allmänna företagsändamål, och obligationerna ska enligt villkoren upptas till handel på Luxembourg Stock Exchange. Obligationerna har en löptid om sex och ett halvt år och emitterades med en ränta på 3.75%.\n\nVinges team bestod av Louise Brorsson Salomon, Lionardo Ojeda, Ida Redander (Bank och Finans), Victor Ericsson och Emelie Svanberg (Skatt)","href":"https://www.vinge.se/uppdrag/vinge-bitrader-tele2-vid-obligationsemission-och-aterkopserbjudande/","date":"2023-05-22","month":5},{"year":2023,"client":"IBT","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder IBT i samband med företrädesemission","caption":"Kapitalanskaffning · 19 maj 2023","preamble":"Vinge företräder Infant Bacterial Therapeutics AB (publ) i samband med en företrädesemission om cirka 100 miljoner kronor.","body":"Vinges team består av Erik Sjöman, Christian Lindhé, Martin Svanberg och Jasmine Elgh.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ibt-i-samband-med-foretradesemission/","date":"2023-05-19","month":5},{"year":2023,"client":"Continental","work":"Övrigt","disciplines":["M&A"],"title":"Vinge företräder Continental","caption":"Övrigt · 15 maj 2023","preamble":"Vinge företräder Continental i samband med förvärvet av Printing Solutions Holding AB från Trelleborg AB. Tillträde ägde rum den 2 maj 2023,","body":"Vinges team bestod av Ulrich Ziche, Nina Fathjalali and Josef Groow.\n\nPressmeddelande Continental >>>\n\nPressmeddelande Trelleborg >>>","href":"https://www.vinge.se/uppdrag/vinge-foretrader-continental/","date":"2023-05-15","month":5},{"year":2023,"client":"Procuritas","work":"Förvärv","disciplines":["Arbetsrätt","Corporate Crime & Compliance","EU‑ och konkurrensrätt","IT, Telekom och Outsourcing","M&A","Offentlig upphandling","Bank och finans","Miljörätt","Fastigheter och Entreprenad","GDPR"],"title":"Vinge företräder Procuritas vid förvärvet av PropTech Sweden","caption":"Förvärv · 15 maj 2023","preamble":"Vinge företräder Procuritas Capital Investor (VII) (”Procuritas”) i samband med förvärvet av PropTech Sweden AB (\"PropTech Sweden\") med dotterbolagen Axcell Fastighetspartner AB (”Axcell Fastighetspartner”) och Ömangruppen Svenska AB (”Ömangruppen”).","body":"PropTech Sweden är moderbolag till Ömangruppen och Axcell Fastighetspartner, två ledande bolag verksamma inom inomhusklimat, energieffektivitet och fastighetsförvaltning. Med över 300 anställda och 30 kontor i södra Sverige, Luleå och Örnsköldsvik har företagen nära samarbeten med fastighetsägare som önskar förbättra energieffektiviteten eller på annat sätt optimera driften av sina fastigheter. Procuritas grundades 1986 och har sedan dess genomfört över 50 investeringar och hundratals add-on förvärv i Norden. Fastigheter står idag för 40 % av Sveriges totala energiförbrukning, varför Procuritas ser PropTech Sweden och dess dotterbolag som en viktig aktör i klimatomställningen, särskilt i ljuset av kommande EU-regler om krav på minskade utsläpp. Slutförande av transaktionen är föremål för sedvanligt godkännande från Konkurrensverket.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Maria Dahlin Kolvik, Clara Sohlberg, Eskil Nyström (M&A), Karl-Gustaw Tobola (Banking and Finance), Mario Saad, Clara Klingspor, Daniel Prawitz (Corporate Commercial), Julia Löfqvist (Compliance), Petronella Hallberg, Amelia Rihs (Employment) Lina Österberg (Environment), Mathilda Persson, Alva Skott (IT & GDPR), Alexandra Tamm (Real Estate), Kristoffer Sällfors (Public Procurement) och Johan Walhbom (EU‑ och konkurrensrätt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-procuritas-vid-forvarvet-av-proptech-sweden/","date":"2023-05-15","month":5},{"year":2023,"client":"Säljarna","work":"Avyttring","disciplines":["Bank och finans","M&A"],"title":"Vinge företräder säljarna i samband med försäljningen av Johan i Hallen & Bergfalk","caption":"Avyttring · 4 maj 2023","preamble":"Vinge företräder säljarna, representerade av Litorina V Fund, i samband med försäljningen av JOHBECO AB (inklusive dess svenska och finska dotterbolag Johan i Hallen & Bergfalk) till METRO FSD Holding GmbH, ett indirekt dotterbolag till den internationella grossisten METRO AG.","body":"Johan i Hallen & Bergfalk är verksam på svenska och finska marknaden och är en av Sveriges ledande specialistleverantörer av högkvalitativa färskvaror med fokus på kött, fisk och skaldjur till restauranger, hotell och caféer.\n\nVinges team bestod av Jonas Johansson, Carl Sander, Desirée Hagenfeldt och Robin Sultani (M&A) och Karl-Gustaw Tobola (Bank & Finans) samt Julia Hagelberg, Emy Rydén och Anna Ekdahl Roos (projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-saljarna-i-samband-med-forsaljningen-av-johan-i-hallen-bergfalk/","date":"2023-05-04","month":5},{"year":2023,"client":"Xspray Pharma","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Xspray Pharma i samband med dess företrädesemission av units","caption":"Kapitalanskaffning · 4 maj 2023","preamble":"Genom företrädesemission av units förväntas Xspray tillföras cirka 300 MSEK, med två teckningsoptionsserier som tillsammans uppgår till ytterligare cirka 300 MSEK vid full teckning.","body":"Xspray Pharma AB (publ) är ett läkemedelsföretag som specialiserar sig på att använda sin patenterade HyNap-teknologi för att utveckla förbättrade versioner av befintliga protein-kinashämmare (PKI:er) för cancerbehandling. Företagets mål är att bli en ledande aktör inom utveckling av förbättrade PKI:er för cancerbehandling. Xsprays aktier är noterade på Nasdaq Stockholm.\n\nVinges team har huvudsakligen bestått av Dain Hård Nevonen, Linnéa Sellström och Adrian Filipovic.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-xspray-pharma-i-samband-med-dess-foretradesemission-av-units/","date":"2023-05-04","month":5},{"year":2023,"client":"Platzer Fastigheter","work":"Förvärv","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge biträdde Platzer Fastigheter vid förvärvet av tre fastigheter i Sörred Logistikpark.","caption":"Förvärv · 3 maj 2023","preamble":"Förvärven skedde genom bolkag och till ett underliggande fastighetsvärde om 1 478 MSEK. Fastigheterna uppgår till 90 000 kvm som är fullt uthyrda till Volvo Cars, Volvo Lastvagnar, Schenker Logistics och Sportshopen.","body":"Från Vinges sida medverkade framförallt Olof Jisland och Kristoffer Larsson.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-platzer-fastigheter-vid-forvarvet-av-tre-fastigheter-i-sorred-logistikpark/","date":"2023-05-03","month":5},{"year":2023,"client":"Axcel","work":"Kapitalanskaffning","disciplines":["M&A","Fastigheter och Entreprenad","GDPR","Corporate Crime & Compliance","Arbetsrätt","EU‑ och konkurrensrätt"],"title":"Vinge företräder Axcel i samband med investering i XPartners","caption":"Kapitalanskaffning · 3 maj 2023","preamble":"Vinge har företrätt Axcel i samband med dess investering i XPartners Samhällsbyggnad (”XPartners”), en hållbarhetsorienterad teknikkonsultkoncern specialiserad inom infrastruktur, offentliga och kommersiella byggnader samt miljötjänster.","body":"Efter Axcels investering består XPartners-koncernen av nio affärsenheter med cirka 400 anställda fördelade över 30 kontor runtom i Sverige, med en total omsättning om cirka 600 miljoner kronor. XPartners är den första investeringen för Axcel VII.\n\nFör mer information om transaktionen, se klientens pressmeddelande.\n\nVinges team bestod huvudsakligen av Christina Kokko, Karl Klackenberg, Carl Fredrik Wachtmeister, Egil Svensson och Elsa Strandberg (M&A), Daniel Prawitz (Entreprenadrätt), Daniel Melander Björner och Tove Halläck (Arbetsrätt), Mikael Ståhl, Seyran Sahin, Karl-Gustaw Tobola och Ida Redander (Finansiering), Alexandra Tamm (Fastighetsrätt), Tove Tullberg och Julia Löfqvist (Compliance), Lisa Hörnqvist (GDPR), Trine Osen Bergqvist, Victoria Fredén och Alva Chambert (Konkurrensrätt) samt Emy Rydén (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-i-samband-med-investering-i-xpartners/","date":"2023-05-03","month":5},{"year":2023,"client":"Sustainable Transmission Soluitions Group AB (STS Group)","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företrädde Sustainable Transmission Soluitions Group AB (”STS Group”) vid försäljning av samtliga aktier i VSV AB med dotterbolag","caption":"Avyttring · 2 maj 2023","preamble":"VSV AB med dotterbolagen Scandinavian Transmission Service AB, LBM Autoparts AB och Vaihteistokeskus Oy (”Bolagen”) bedriver verksamhet i form av handel och renovering av transmissionsdelar och drivlinekomponenter för fordon.","body":"Vinges team bestod av Wibeke Sorling (Partner, M&A), Jenny Sandlund (Senior Associate, M&A) och Amanda Stoltz.","href":"https://www.vinge.se/uppdrag/vinge-foretradde-sustainable-transmission-soluitions-group-ab-sts-group-vid-forsaljning-av-samtliga-aktier-i-vsv-ab-med-dotterbolag/","date":"2023-05-02","month":5},{"year":2023,"client":"Yubico","work":"Samgående","disciplines":["Kapitalmarknad och publik M&A","M&A"],"title":"Vinge biträder Yubico i fusionen med ACQ Bure","caption":"Samgående · 20 april 2023","preamble":"ACQ Bure AB, ett svenskt förvärvsbolag (s.k. SPAC) noterat på Nasdaq Stockholm och Yubico AB har ingått ett fusionsavtal och antagit en gemensam fusionsplan avseende ett samgående mellan ACQ och Yubico.","body":"Yubico är ett ledande cybersäkerhetsbolag inom multifaktorautentisering. Yubicos hårdvarubaserade säkerhetsnyckel, YubiKey, är en ledande lösning för att skydda användare mot ”phishing”-attacker och fungerar med hundratals konsument- och företagsapplikationer och tjänster. Yubicos teknologi möjliggör säker autentisering, kryptering och kodsignering och används av många av världens största organisationer och miljontals användare i mer än 160 länder.\n\nTransaktionen värderar Yubicos aktier till 800 MUSD och förväntas slutföras under det tredje kvartalet 2023, villkorat av, bland annat, godkännande vid extra bolagsstämma i ACQ respektive Yubico.\n\nVinges team har bestått av Jonas Johansson, Maria Dahlin Kolvik och Gustav Wahlberg (M&A) samt Linnea Sällström (Public M&A).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-yubico-i-fusionen-med-acq-bure/","date":"2023-04-20","month":4},{"year":2023,"client":"Lunar","work":"Övrigt","disciplines":["Finansiella tillståndsfrågor","M&A"],"title":"Vinge företräder Lunar vid överlåtelse av samtliga kundrelationer inom ramen för dess P2P-verksamhet till SaveLend","caption":"Övrigt · 11 april 2023","preamble":"Vinge företräder Lunar Bank A/S vid överlåtelsen av samtliga kundrelationer med investerare och låntagare inom ramen för dess P2P-verksamhet med tillhörande varumärke och domäner till SaveLend Group ABs dotterbolag SBL Finans AB (publ).","body":"Överlåtelsen omfattar cirka 17 000 aktiva investerare, 7 000 aktiva låntagare och ett investerat kapital om cirka 450 Mkr. Lunar har drivit sin P2P-verksamhet sedan 2021. I syfte att renodla verksamheten har Lunar aktivt letat efter ett nytt hem för sina P2P-kunder, såväl investerare som låntagare. Genom transaktionen övertas samtliga kundrelationer och hanteras från och med tillträdet genom SaveLend Groups egenutvecklade plattform och kundserviceteam.\n\nTransaktionens genomförande är villkorad av danska Finanstilsynets godkännande.\n\nVinges team bestod huvudsakligen av Filip Öhrner, Robin Fagerström (M&A) och Caroline Krassén (Financial Services).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-lunar-vid-overlatelse-av-samtliga-kundrelationer-inom-ramen-for-dess-p2p-verksamhet-till-savelend/","date":"2023-04-11","month":4},{"year":2023,"client":"Procuritas","work":"Fondetablering","disciplines":["Bank och finans","Företagsbeskattning","Private Funds"],"title":"Vinge har biträtt Procuritas vid etableringen av deras största fond hittills","caption":"Fondetablering · 11 april 2023","preamble":"Fonden har erhållit 407 miljoner euro i investeringsåtaganden. Procuritas är en riskkapitalförvaltare som fokuserar på nordiska buyout-investeringar i små till mellanstora bolag inom exempelvis programvaruutveckling och nischade industribolag.","body":"Vinges team har bestått av Mattias Schömer, Jesper Ottergren, Marcus Andersson, Martin Svanberg, Viveka Classon, Emelie Svanberg, Ludvig Berke, Nour Makie och Moa Frändestam.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-procuritas-vid-etableringen-av-deras-storsta-fond-hittills/","date":"2023-04-11","month":4},{"year":2023,"client":"CTEK","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A","M&A"],"title":"Vinge har företrätt CTEK i samband med dess företrädesemission","caption":"Kapitalanskaffning · 29 mars 2023","preamble":"Vinge har företrätt CTEK AB (publ) i samband med en fullt garanterad företrädesemission, vilken tillför CTEK cirka 350 miljoner kronor före avdrag för transaktionskostnader.","body":"De nya aktierna som emitteras inom ramen för företrädesemissionen beräknas bli föremål för handel på Nasdaq Stockholm omkring den 4 april 2023.\n\nCTEK är en av de ledande globala leverantörerna av batteriladdare för olika fordon inom premiumsegmentet och en av Sveriges största leverantörer av laddare och tillbehör för elfordonsladdning. Bolaget präglas av en stark innovationskultur och arbetar ständigt med att förbättra och utveckla nya produkter anpassade efter kundernas behov. CTEK grundades 1997 i Vikmanshyttan och har numera försäljning i över 70 länder. Med en historia av innovation och teknikledarskap möter bolaget proaktivt nya kundbehov genom att utveckla produkterbjudandet och verksamheten kontinuerligt. CTEK har genom sitt teknikledarskap etablerat starka och långvariga kundrelationer med bland annat över 50 av världens mest prestigefyllda fordonstillverkare. Utöver fordonstillverkare erbjuder CTEK produkter till bland annat fordonsverkstäder, distributörer, återförsäljare, laddpunktsoperatörer samt fastighetsägare.\n\nVinges team bestod i huvudsak av David Andersson, William Kåge, Oskar Nilsson, Lorin Arabi och Gabriel Chabo (Kapitalmarknad och Publik M&A), Eléonore Friberg och Ebba Nyberg (M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-ctek-i-samband-med-dess-foretradesemission/","date":"2023-03-29","month":3},{"year":2023,"client":"VNV Global","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt VNV Global i samband en företrädesemission","caption":"Kapitalanskaffning · 29 mars 2023","preamble":"Vinge har företrätt VNV Global i samband med en fullt säkerställd företrädesemission om cirka 328 miljoner kronor.","body":"Vinges team bestod i huvudsak av Jesper Schönbeck, Joel Wahlberg, Emma Brolund, Annie Fällström och Michaela Ådén.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-vnv-global-i-samband-en-foretradesemission/","date":"2023-03-29","month":3},{"year":2023,"client":"Ramirent","work":"Förvärv","disciplines":["Bank och finans","M&A","Corporate Commercial","IT, Telekom och Outsourcing","Immaterialrätt","Fastigheter och Entreprenad"],"title":"Vinge företräder Ramirent i samband med förvärvet av JIAB","caption":"Förvärv · 21 mars 2023","preamble":"Vinge företräder Ramirent AB i samband med förvärvet av JIAB Hyrcenter (bestående av bolagen JIAB Hyrcenter AB och JIAB Boden AB). Genom förvärvet förstärker Ramirent ytterligare sin position i Norrbotten och som det största maskinuthyrningsföretaget i Sverige.","body":"Vinges team bestod huvudsakligen av Jonas Johansson, Per Kling, Elsie Nassar och Nando Basic (M&A), Arvid Axelryd och Emma Gustavsson (IP), Seyran Sahin och Ida Redander (Bank och finans), Anna Ståhlklo, Anna Högsten och Maja Eliasson (Arbetsrätt), Martin Boström och Mario Saad (Corporate commercial), Karolina Fuhrman och Elis Allmark (IT & GDPR), Tove Tullberg och Julia Löfqvist (compliance), Rebecka Maltenius (fastighet) samt Emy Rydén och Ellinore Boström Andersson (projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-ramirent-i-samband-med-forvarvet-av-jiab/","date":"2023-03-21","month":3},{"year":2023,"client":"GleSYS","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljning av GleSYS","caption":"Avyttring · 21 mars 2023","preamble":"Vinge har biträtt huvudägarna VIA equity och VD Glenn Johansson samt övriga mindre aktieägare vid försäljning av GleSYS till den Luxemburgbaserade infrastrukturfonden Cube Infrastructure Managers.","body":"GleSYS äger datacenter i Falkenberg, Stockholm och Oulu (Finland) och samarbetar med marknadsledande aktörer i Europa. GleSYS' datacenter använder 100 procent förnybar energi och spillvärmen återvinns för att värma bostäder.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Per Kling, Nando Basic, Olivia Belding, Emelie Schoning och Christoffer Widström.\n\nLäs mer här","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-glesys/","date":"2023-03-21","month":3},{"year":2023,"client":"Svea Bank","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Svea Bank AB med emission av AT1-obligationer om 300 miljoner SEK","caption":"Obligationsemission · 14 mars 2023","preamble":"Vinge har biträtt Svea Bank AB (”Bolaget”) i samband med dess emission av primärkapitaltillskott (AT1) om 300 miljoner SEK för att optimera sin kapitalstruktur.","body":"Emissionen sker i form av skuldinstrument med automatisk nedskrivning av dess nominella belopp om Bolagets kärnprimärkapitalkvot faller under en viss nivå. Instrumenten kommer att noteras på Nasdaq Stockholm. I samband med emissionen ska Bolagets utestående AT1-obligation, ursprungligen emitterad 3 april 2018, återlösas, vilket sker den 3 april 2023.\n\nVinges team bestod av Mikael Ståhl, Arvid Weimers och Calle Tengwall Pagels.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-svea-bank-ab-med-emission-av-at1-obligationer-om-300-miljoner-sek/","date":"2023-03-14","month":3},{"year":2023,"client":"Anglo American","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder Anglo American i samband med investering i Dannemoragruvan","caption":"Kapitalanskaffning · 14 mars 2023","preamble":"Vinge har tillsammans med Norton Rose Fulbright biträtt Anglo American Limited i samband med ingående av royalty-avtal om USD 10 miljoner samt ett bindande term sheet för ett offtake-avtal med Dannemora Iron AB. Vinge har även biträtt med därtill relaterad due diligence. Dannemora Iron AB är ett helägt dotterbolag till Grängesberg Exploration Holding AB (publ).","body":"Vinges team består av Christoffer Thalin, Henrik Ossborn, Johan Cederblad, Tilda Hall, Agaton Lindgren och Lina Österberg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-anglo-american-i-samband-med-investering-i-dannemoragruvan/","date":"2023-03-14","month":3},{"year":2023,"client":"Transtema","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Transtema i samband med riktad nyemission","caption":"Kapitalanskaffning · 10 mars 2023","preamble":"Vinge har biträtt Trantema Group AB (Nasdaq Stockholm) i samband med en riktad nyemission om ca 63 MSEK.","body":"Teckningskursen fastställdes genom ett accelererat bookbuildingförfarande och aktierna tilldelades ett antal svenska och internationella institutionella investerare.\n\nVinges team bestod av Anders Strid och Edin Agic.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-transtema-i-samband-med-riktad-nyemission/","date":"2023-03-10","month":3},{"year":2023,"client":"Zington","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Zington vid förvärv av Pia Relations","caption":"Förvärv · 6 mars 2023","preamble":"Vinge har biträtt Zington, som är del av det globala IT-konsultbolaget VASS, att förvärva Pia Relations. Pia Relations är en etablerad Salesforce-partner med bas i Stockholm.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Ellinor Wargenbrant.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-zington-vid-forvarv-av-pia-relations/","date":"2023-03-06","month":3},{"year":2023,"client":"Dreams","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder Dreams i samband med försäljningen av Dreams Technology","caption":"Avyttring · 27 februari 2023","preamble":"Vinge företräder Dreams AB i samband med försäljningen av den ledande engagemangsbankplattformen Dreams Technology till Doconomy vilket utökar uppsättningen klimatåtgärdsverktyg och ger banker möjlighet att bättre engagera sina kunder.","body":"Dreams Technology är ett Stockholmsbaserat fintech-bolag med en ledande engagemangsbankplattform som bygger på beteendevetenskap och som hjälper finansbranschen att skapa starka kundrelationer, attrahera nästa generation och samtidigt ta itu med ekonomiskt välbefinnande och hållbarhet. Doconomy är en ledande startup för klimatteknologi som hjälper banker, företag och konsumenter att bättre förstå och minska sin miljöpåverkan.\n\nGenom transaktionen blir Doconomy den första leverantören som erbjuder en helhetslösning som driver meningsfull klimatpåverkan för finansbranschen.\n\nVinges team bestod av Jonas Johansson, Eléonore Friberg och Stojan Arnerstål.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-dreams-i-samband-med-forsaljningen-av-dreams-technology/","date":"2023-02-27","month":2},{"year":2023,"client":"Scandic","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge biträder Scandic i samband med kreditfaciliteter om 3,45 miljarder kronor","caption":"Finansiering · 22 februari 2023","preamble":"Vinge har företrätt Scandic Hotels Group AB (publ) i samband med ingåendet av ett kreditfacilitetsavtal om 3 450 000 000 kronor.","body":"Kreditfaciliteten löper till den 31 december 2025 och möjliggör för Scandic att, förutsatt att vissa villkor är uppfyllda, refinansiera hela eller delar av dess utestående konvertibellån.\n\nScandic är det största hotellföretaget i Norden med omkring 58 000 hotellrum fördelade på cirka 280 hotell i drift och under utveckling. Scandic är noterat på Nasdaq Stockholm.\n\nVinges team bestod av Louise Brorsson Salomon, Arvid Weimers och Calle Tengwall Pagels.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-scandic-i-samband-med-kreditfaciliteter-om-3-45-miljarder-kronor/","date":"2023-02-22","month":2},{"year":2023,"client":"CapMan Buyout","work":"Avyttring","disciplines":["Miljörätt","M&A"],"title":"Vinge företräder CapMan Buyout i samband med försäljningen av Malte Månson","caption":"Avyttring · 21 februari 2023","preamble":"Vinge företräder fonder förvaltade av CapMan och övriga aktieägare i Malte Månson-koncernen i samband med försäljningen till Accent Equity.","body":"Malte Månson grundades 1918 och är den ledande oberoende verkstadskedjan för kommersiella fordon i Sverige. Företaget har 17 verkstäder runt om i landet och betjänar alla typer av kommersiella fordon, inklusive auktorisation för MAN, DAF, Iveco och Mercedes. År 2022 hade Malte Månson ca 180 anställda med en omsättning om 360 MSEK.\n\nTransaktionen är villkorad av tillämpliga konkurrensmyndigheters godkännande.\n\nVinges team bestod av Jonas Johansson, Elsie Nassar och Linus Adolfsson (M&A), Johan Cederblad (Miljö) och Julia Hagelberg (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-capman-buyout-i-samband-med-forsaljningen-av-malte-manson/","date":"2023-02-21","month":2},{"year":2023,"client":"Heda Security","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Heda Security vid förvärv av Tuna Stängsel","caption":"Förvärv · 21 februari 2023","preamble":"Vinge har biträtt Heda Security i förvärvet av aktierna i Tuna Stängsel. Heda Security-koncernen är Nordens ledande företagsgrupp inom installation och service av områdessäkerhet och omsätter efter det senaste förvärvet över 650 miljoner kronor och har fler än 200 anställda.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Nando Basic.\n\nLäs mer om uppdraget här","href":"https://www.vinge.se/uppdrag/vinge-bitrader-heda-security-vid-forvarv-av-tuna-stangsel/","date":"2023-02-21","month":2},{"year":2023,"client":"Immunovia","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Immunovia i samband med dess företrädesemission om högst 202 miljoner kronor","caption":"Kapitalanskaffning · 20 februari 2023","preamble":"Immunovia AB (publ) är ett diagnostikföretag med visionen att revolutionera den blodbaserade diagnostiken och öka överlevnadsfrekvensen för patienter med cancer. Immunovias aktier är noterade på Nasdaq Stockholm.","body":"Vinges team har huvudsakligen bestått av Dain Hård Nevonen, Amanda Knutsson, Anders Sundin Lundberg och Adrian Filipovic.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-immunovia-i-samband-med-dess-foretradesemission-om-hogst-202-miljoner-kronor/","date":"2023-02-20","month":2},{"year":2023,"client":"Smart Eye","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Smart Eye i deras företrädesemission om 324 MSEK","caption":"Kapitalanskaffning · 20 februari 2023","preamble":"Vinge har agerat rådgivare åt Smart Eye Aktiebolag (First North Growth Market) i samband med dess fullt ut säkerställda företrädesemission som tillförde Smart Eye 324 MSEK före transaktionskostnader. Emissionen var fulltecknad och inga garantiåtaganden behövde utnyttjas.","body":"Vinges team har huvudsakligen bestått av Anders Strid, Oscar Lunde (projektledare), Amelia Rihs, Fredrik Löwenclou samt bolagsassistenten Daniela Maniscalchi. Carnegie agerade finansiell råsgivare åt Smart Eye.\n\nLäs mer här","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-smart-eye-i-deras-foretradesemission-om-324-msek/","date":"2023-02-20","month":2},{"year":2023,"client":"Fyndiq","work":"Samgående","disciplines":["M&A"],"title":"Vinge företräder Fyndiq vid sammanslagning med CDON","caption":"Samgående · 16 februari 2023","preamble":"Fyndiq lanserades 2010 och driver en marknadsplats som erbjuder ett brett utbud av fyndprodukter från svenska och internationella handlare.","body":"Fyndiq och CDON slår nu ihop sina krafter för att skapa Nordens ledande e-handelsplattform. Det sammanslagna bolaget, som går under namnet CDON, kommer fortsatt att driva två separata konsumenterbjudanden under varumärkena CDON och Fyndiq.\n\nSammanslagningen är villkorad av godkännande från CDONs aktieägare på en extra bolagsstämma som ska hållas den 28 mars 2023.\n\nVinges team bestod av Jonas Bergström, David Andersson, Samra Tesser, Ellinor Wargenbrant och Philip Moré (M&A) och Ellinore Boström Andersson (Projekt- och VDR-assistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-fyndiq-vid-sammanslagning-med-cdon/","date":"2023-02-16","month":2},{"year":2023,"client":"Danske Bank","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt Danske Bank i samband med en kreditfacilitet för Svenska Retursystem om 750 miljoner kronor","caption":"Finansiering · 16 februari 2023","preamble":"Vinge har biträtt Danske Bank A/S, Danmark, Sverige Filial i samband med Svenska Retursystem Aktiebolags ingående av en ny kreditfacilitet om 750 miljoner kronor.","body":"Kreditfaciliteten har en löptid om tre år med möjlighet till förlängning och parterna avser fastställa vissa KPI:er varpå räntesatsen i kreditfaciliteten kommer villkoras av hur bolaget lever upp till vissa uppsatta hållbarhetsmål. Medlen ska användas till att, bland annat, refinansiera existerande skuld samt för allmänna företags- och rörelsekapitalsändamål.\n\nSvenska Retursystems cirkulära system möjliggör att livsmedelsproducenter, grossister, butiker och restauranger kan arbeta tillsammans för att optimera livsmedelsbranschens varuflöden.\n\nVinges team bestod av Albert Wållgren, Arvid Weimers och Karl-Gustaw Tobola.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-danske-bank-i-samband-med-en-kreditfacilitet-for-svenska-retursystem-om-750-miljoner-kronor/","date":"2023-02-16","month":2},{"year":2023,"client":"Biotage","work":"Förvärv","disciplines":["M&A","Kapitalmarknad och publik M&A","EU‑ och konkurrensrätt"],"title":"Vinge företräder Biotage i samband med förvärvet av Astrea från KKRs life science-plattform Gamma","caption":"Förvärv · 15 februari 2023","preamble":"Vinge företräder Biotage AB (publ) (”Biotage”) i samband med förvärvet av Astrea Bioseparations (”Astrea”), en snabbväxande leverantör av kromatografilösningar, från Gamma Biosciences (”Gamma”), en plattform för life science-verktyg skapad och kontrollerad av KKR.","body":"Förvärvet ökar Biotages exponering mot kromatografiverksamhet till det mer snabbväxande och större segmentet för bioprocesser, samtidigt som det ökar exponeringen mot kunder inom biologiska läkemedel och avancerade terapier. Köpeskillingen kommer att betalas i form av nyutgivna stamaktier i Biotage, vilket medför att det KKR-kontrollerade Gamma förväntas bli den största aktieägaren i Biotage, med ett innehav motsvarande cirka 17 procent av Biotage.\n\nTransaktionen är villkorad av godkännande från aktieägarna på bolagsstämma i Biotage, samt föremål för sedvanliga fullföljandevillkor, inklusive godkännande från brittiska myndigheter.\n\nVinges team bestod av Matthias Pannier, Karl Klackenberg, Linus Adolfsson, Sebastian Saadieh, Elis Allmark (M&A), Dain Hård Nevonen, William Kåge, Joel Magnusson, Anna Svensson, Gabriel Chabo (Capital Markets), Sebastian Örndahl (Konkurrensrätt), Sara Dahlros Sköld and Julia Hagelberg (VDR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-biotage-i-samband-med-forvarvet-av-astrea-fran-kkrs-life-science-plattform-gamma/","date":"2023-02-15","month":2},{"year":2023,"client":"Byggfakta","work":"Förvärv","disciplines":["Arbetsrätt","Immaterialrätt","M&A"],"title":"Vinge biträder Byggfakta i samband med förvärvet av 4CastGroup AS","caption":"Förvärv · 14 februari 2023","preamble":"Vinge biträder Byggfakta Group (Nasdaq Stockholm) i samband med förvärvet av ca 73 procent av aktierna i 4CastGroup AS med dotterbolagen Prognosesenteret AS i Norge och Prognoscentret AB i Sverige vilka är ledande i Norden på marknadsanalyser och prognoser för bygg- och anläggningsmarknaden.","body":"Vinges team bestod huvudsakligen av Anders Strid, Petronella Hallberg (projektledare), Anna Ståhlklo (arbetsrätt), Alexander Lindeberg och Anna Högsten (IP/IT), Hanna Jansson och Rebecca Edvardsson samt bolagsassistenten Daniela Maniscalchi. Advokatfirmaet Thommessen agerade lokalt ombud i Norge.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-byggfakta-i-samband-med-forvarvet-av-4castgroup-as/","date":"2023-02-14","month":2},{"year":2023,"client":"Neobo Fastigheter","work":"Börsnotering","disciplines":["Kapitalmarknad och publik M&A","Företagsbeskattning"],"title":"Vinge har företrätt Neobo Fastigheter i samband noteringen av Neobos Fastigheters aktier på Nasdaq First North Premier","caption":"Börsnotering · 10 februari 2023","preamble":"Vinge har företrätt Neobo Fastigheter AB (publ) (”Neobo”) i samband noteringen av Neobos aktier på Nasdaq First North Premier. Bolagsbeskrivningen offentliggjordes den 6 februari 2023 och första handelsdag på Nasdaq First North Premier var den 10 februari 2023.","body":"Neobo är ett fastighetsbolag som långsiktigt förvaltar och förädlar hyresfastigheter över hela Sverige. Fastighetsbeståndet består av 8 381 lägenheter fördelat över 268 fastigheter, med ett totalt fastighetsvärde om 15,3 mdkr per 31 december 2022. Bolagets affärsidé går ut på att förvalta och förädla bostäder i kommuner med befolkningstillväxt, god sysselsättningsgrad och en stabil hyresmarknad.\n\nVinges team bestod av Jesper Schönbeck, Rikard Lindahl, Joel Magnusson, Johannes Akyol, Gabriel Chabo, Clara Sohlberg, Kristoffer Larson, Victor Ericsson och Maria Schultzberg.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-neobo-fastigheter-i-samband-noteringen-av-neobos-fastigheters-aktier-pa-nasdaq-first-north-premier/","date":"2023-02-10","month":2},{"year":2023,"client":"AmSpec","work":"Förvärv","disciplines":["Arbetsrätt","Immaterialrätt","M&A","Fastigheter och Entreprenad","IT, Telekom och Outsourcing","GDPR","Kommersiella avtal"],"title":"Vinge företräder AmSpec i samband med förvärvet av IIS","caption":"Förvärv · 6 februari 2023","preamble":"AmSpec Group, Inc. med dotterbolag (”AmSpec”) är en multinationell koncern inom inspektion, analys och testning av produkter inom energi- och jordbruksindustrin.","body":"IIS Independent Inspection Services AB (”IIS”) utför tester, inspektioner och en rad olika supporttjänster inom energi- och jordbrukssektorerna på den nordiska marknaden. Bolaget har sitt huvudsakliga laboratorium i Göteborg.\n\nGenom förvärvet av IIS förstärks AmSpecs närvaro på den europeiska marknaden i allmänhet, och på den nordiska marknaden i synnerhet.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Viktor Lennartsson, Robin Sultani (M&A), Karin Gynnerstedt (arbetsrätt), Christoffer Nordin (kommersiella avtal), Karolina Fuhrman (IT och GDPR), Arvid Axelryd (IP), Markus Bernander (fastighetsrätt), Ottilia Pettersson och Ellinore Boström Andersson (projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-amspec-i-samband-med-forvarvet-av-iis/","date":"2023-02-06","month":2},{"year":2023,"client":"Veeco Instruments Inc.","work":"Förvärv","disciplines":["M&A","IT, Telekom och Outsourcing","GDPR","Immaterialrätt","Företagsbeskattning","Arbetsrätt"],"title":"Vinge bistår Veeco Instruments Inc. i samband med dess förvärv av Epiluvac AB","caption":"Förvärv · 1 februari 2023","preamble":"Vinge har bistått Veeco Instruments Inc. (”Veeco”), ett amerikanskt bolag listat på NASDAQ, i samband med dess förvärv av Epiluvac AB, en tillverkare av system för produktion av avancerade halvledarmaterial baserade på kiselkarbid som används inom elbilsmarknaden.","body":"Epiluvac är baserat i Lund och grundades 2013 av ett team med omfattande erfarenhet av kiselkarbid. Epiluvacs teknologiska plattform tillsammans med Veecos go-to market erfarenhet och förmåga förväntas utgöra en väsentlig tillväxtdrivare för Veeco. Epiluvac är ett uppstartsbolag med 11 anställda. Köpeskillingen för transaktionen utgörs av en kontantbetalning om 30 miljoner USD som erlades vid tillträdet och en prestationsbaserad tilläggsköpeskilling om upp till 35 miljoner USD.\n\nVinges team bestod av bl a Jonas Bergström, Carl Sander, Stina Bengtsson och Robin Sultani (M&A), Sofia Bergenstråhle och Arvid Axelryd (IP), Anna Ståhlklo och Jonna Skog (Arbetsrätt), Victor Ericsson och Emelie Svanberg (Skatt), Nicklas Thorgerzon (IT & GDPR) och Jasmina Skandrani (Projekt Assistent).","href":"https://www.vinge.se/uppdrag/vinge-bistar-veeco-instruments-inc-i-samband-med-dess-forvarv-av-epiluvac-ab/","date":"2023-02-01","month":2},{"year":2023,"client":"Main Capital och Optimizers","work":"Förvärv","disciplines":["Arbetsrätt","Kommersiella avtal","Immaterialrätt","M&A","IT, Telekom och Outsourcing","GDPR"],"title":"Vinge biträder Main Capital och Optimizers vid förvärvet av Vendre","caption":"Förvärv · 30 januari 2023","preamble":"Vendre är en leverantör av en innovativ modulbaserad e-handelsplattform som riktar sig till kunder inom både B2B- och B2C-marknader","body":"Vendre AB grundades 2007 och tillhandahåller en innovativ e-handelsplattform med en rad olika och unika funktionaliteter till sina över hundra kunder. Genom förvärvet stärker Main Capitals portföljbolag Optimizers sitt produktutbud och sin position på den nordiska marknaden och växer därigenom mot 25 miljoner euro i omsättning samt 170 anställda.\n\nVinges team bestod huvudsakligen av Filip Öhrner, Olivia Belding, Nando Basic (M&A), Ebba Svenburg (arbetsrätt), Martin Boström (kommersiella avtal) Lisa Hörnqvist (IT och GDPR), Rebecka Målquist, Johan Gavelin (IP) och Ellinore Boström Andersson (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-main-capital-och-optimizers-vid-forvarvet-av-vendre/","date":"2023-01-30","month":1},{"year":2023,"client":"Egetis Therapeutics","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Egetis Therapeutics i samband med en riktad nyemission","caption":"Kapitalanskaffning · 27 januari 2023","preamble":"Vinge har företrätt Egetis Therapeutics AB (publ) (”Egetis Therapeutics”), ett innovativt och integrerat läkemedelsbolag fokuserat på projekt i sen klinisk utvecklingsfas för kommersialisering inom särläkemedelsområdet för behandling av allvarliga och sällsynta sjukdomar med betydande medicinska behov, noterat på Nasdaq Stockholm, i samband med en riktad nyemission varigenom bolaget tillfördes 210 miljoner kronor före emissionskostnader.","body":"Emissionen riktades till ett antal utvalda svenska och internationella institutionella investerare på grundval av en accelererad bookbuilding-process.\n\nVinges team bestod av Dain Hård Nevonen, Amanda Knutsson och Lorin Arabi.\n\n**","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-egetis-therapeutics-i-samband-med-en-riktad-nyemission/","date":"2023-01-27","month":1},{"year":2023,"client":"SBB","work":"Övrigt","disciplines":["Bank och finans","Kapitalmarknad och publik M&A","Företagsbeskattning"],"title":"Vinge har företrätt SBB i samband med utdelningen av aktierna i Neobo Fastigheter","caption":"Övrigt · 24 januari 2023","preamble":"Vinge har företrätt Samhällsbyggnadsbolaget i Norden AB (publ) (”SBB”) i samband med utdelningen av aktierna i Neobo Fastigheter AB (publ) (”Neobo”) till A- och B-aktieägarna i SBB. Beslutet om utdelningen fattades på extra bolagsstämma i SBB den 21 december 2022 och utdelningen genomfördes den 30 december 2022.","body":"Neobo är ett fastighetsbolag med huvudkontor i Stockholm som långsiktigt förvaltar och förädlar hyresfastigheter över hela Sverige. Fastighetsbeståndet är diversifierat över 40 kommuner med ett totalt fastighetsvärde om 15,8 mdkr. Bostadsfastigheter står för 97 procent av fastighetsbeståndets marknadsvärde och resterande marknadsvärde utgörs av övriga fastigheter.\n\nVinges team bestod av Jesper Schönbeck, Rikard Lindahl, Joel Magnusson, Johannes Akyol, Gabriel Chabo, Clara Sohlberg, Kristoffer Larson, Albert Wållgren, Kamyar Najmi, Victor Ericsson och Maria Schultzberg.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-sbb-i-samband-med-utdelningen-av-aktierna-i-neobo-fastigheter/","date":"2023-01-24","month":1},{"year":2023,"client":"Leos Lekland","work":"Samgående","disciplines":["M&A"],"title":"Vinge biträder Leos Lekland vid samgående med finska HopLop","caption":"Samgående · 23 januari 2023","preamble":"Vinge har biträtt Litorinas portföljbolag Leos Lekland vid samgående med finska HopLop, med CapMan Special Situations I som huvudägare. Den nya gruppen kommer vara ledande i Europa och inledningsvis driva 68 lekland i Sverige, Finland, Norge, Danmark och Tyskland.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Vilhelm Rondahl och Robin Sultani.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-leos-lekland-vid-samgaende-med-finska-hoplop/","date":"2023-01-23","month":1},{"year":2023,"client":"Sandvik","work":"Kapitalanskaffning","disciplines":["Bank och finans"],"title":"Vinge har biträtt Sandvik i samband med lån om 500 miljoner euro från Europeiska investeringsbanken (EIB)","caption":"Kapitalanskaffning · 20 januari 2023","preamble":"Vinge har biträtt Sandvik AB (publ) och Sandvik Treasury AB (publ) i samband med ingående av ett låneavtal om 500 miljoner euro med Europeiska investeringsbanken (EIB). Lånet kommer att stödja Sandviks investeringar i forskning och utveckling, vilket inkluderar avancerade lösningar för komponenttillverkning och lösningar inom elektrifiering och automation för gruv-och infrastruktursegmenten.","body":"Lånet har en löptid på sju år, och kommer att stödja Sandviks investeringsplaner inom forskning och utveckling fram till och med 2025.\n\nSandvik är en global, högteknologisk industrikoncern som tillhandahåller lösningar som förbättrar produktivitet, lönsamhet och hållbarhet inom tillverknings-, gruv- och infrastrukturindustrierna\n\nVinges team bestod av Albert Wållgren, Arvid Weimers och Karl-Gustaw Tobola.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-sandvik-i-samband-med-lan-om-500-miljoner-euro-fran-europeiska-investeringsbanken-eib/","date":"2023-01-20","month":1},{"year":2023,"client":"Anyfin","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Anyfin i kapitalanskaffning om drygt 320 miljoner kronor","caption":"Kapitalanskaffning · 18 januari 2023","preamble":"Den nya finansieringen ska användas för att ytterligare stärka Anyfins produktsvit på befintliga marknader i Europa, att accelerera utvecklingen av ny teknik för att hjälpa konsumenter att spara pengar och förbättra det ekonomiska välbefinnandet bland hundratusentals européer.","body":"Anyfin hjälper sina kunder att sänka sina räntekostnader genom att omfinansiera ursprungliga krediter och ge bättre erbjudanden på kundernas lån.\n\nVinges team har huvudsakligen bestått av Johan Larsson, Ellinor Wargenbrant och Nando Basic.\n\nLäs mer här>>>","href":"https://www.vinge.se/uppdrag/vinge-foretrader-anyfin-i-kapitalanskaffning-om-drygt-320-miljoner-kronor/","date":"2023-01-18","month":1},{"year":2023,"client":"François-Charles Oberthur","work":"Övrigt","disciplines":["M&A","Kapitalmarknad och publik M&A"],"title":"Vinge biträder François-Charles Oberthur i budet på Rolling Optics","caption":"Övrigt · 18 januari 2023","preamble":"François-Charles Oberthur har lämnat ett offentligt erbjudande till aktieägarna och innehavare av noterade teckningsoptioner i Rolling Optics Holding AB (publ).","body":"Vinges team består av Jesper Schönbeck, Erik Sjöman, Linnéa Sellström, William Kåge och Philip Moré (Kapitalmarknad och publik M&A), Jonas Bergström och Ulrich Ziche (M&A).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-francois-charles-oberthur-i-budet-pa-rolling-optics/","date":"2023-01-18","month":1},{"year":2023,"client":"MySafety Group","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljning av mySafety Group","caption":"Avyttring · 16 januari 2023","preamble":"Vinge har biträtt Litorina och övriga aktieägare i mySafety Group AB vid försäljning av aktierna i bolaget till ett konsortie bestående av Empir Group AB och ett antal nuvarande och tidigare ledande befattningshavare i mySafety-koncernen.","body":"mySafety uppfann ID-skyddsförsäkringen 2008 och har sedan dess varit nordisk marknadsledare och innovatör inom området bedrägeri- och ID-skyddsförsäkringar. År 2021 omsatte mySafety ca 352 MSEK med ett EBITDA om ca 38 MSEK.\n\nVinges team bestod i huvudsak Johan Winnerblad, Per Kling, Gunilla Nyman och Ellinore Boström Andersson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-mysafety-group/","date":"2023-01-16","month":1},{"year":2023,"client":"Svenska Handelsbanken","work":"Övrigt","disciplines":["Bank och finans"],"title":"Vinge biträder Svenska Handelsbanken i samband med hållbarhetslänkad kredit till Byggmax Group","caption":"Övrigt · 13 januari 2023","preamble":"Vinge biträder Svenska Handelsbanken i samband med en revolverande kreditfacilitet om 500 miljoner SEK med Byggmax Group AB (publ) som låntagare.","body":"Kreditfaciliteten är länkad till Byggmax hållbarhetsmål; CO2e-utsläpp från egen verksamhet ska minska med 90 procent till år 2027 jämfört med år 2020 och CO2e-utsläpp per transporterat ton gods ska minska med 70 procent till år 2030 jämfört med år 2010. Facilitetens KPIs är satta i linje med dessa mål och räntemarginalen för faciliteten påverkas i positiv eller negativ riktning beroende på om dessa nivåer möts.\n\nVinges team bestod av Louise Brorsson Salomon, Helena Göransson och Karl-Gustaw Tobola","href":"https://www.vinge.se/uppdrag/vinge-bitrader-svenska-handelsbanken-i-samband-med-hallbarhetslankad-kredit-till-byggmax-group/","date":"2023-01-13","month":1},{"year":2023,"client":"Blugiallo","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder Blugiallo vid kapitalanskaffning","caption":"Kapitalanskaffning · 12 januari 2023","preamble":"Vinge har företrätt Blugiallo och dess grundare i samband med en kapitalanskaffning i syfte att expandera verksamheten inom befintliga såväl som nya marknader.","body":"Blugiallo är ett svenskt herrmodeföretag, grundat 2015 av Alexander Moström och Daniel Apler. Genom att ifrågasätta systematiska problem inom modeindustrin, så som överproduktion och returfrekvens, fokuserar Blugiallo uteslutande på att producera varor ”on demand”, och samtliga produkter är anpassade efter varje enskild kund.\n\nFinansieringsrundan inkluderade befintliga och nya investerare.\n\nVinges team bestod av Karl Klackenberg och Viktor Lennartsson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-blugiallo-vid-kapitalanskaffning/","date":"2023-01-12","month":1},{"year":2023,"client":"Sobro","work":"Kapitalanskaffning","disciplines":["Fastigheter och Entreprenad","M&A","IT, Telekom och Outsourcing","Bank och finans","Arbetsrätt","Kommersiella avtal","GDPR"],"title":"Vinge företräder Sobro vid investering i NSS Group","caption":"Kapitalanskaffning · 12 januari 2023","preamble":"Vinge företräder Sobro vid investering i NSS Group, en ledande nordisk leverantör av tälthallar och presenningar.","body":"I NSS Group ingår Hallbyggarna Jonsereds (Sverige), Lainapeite (Finland) samt IPS Hal & Presenning (Danmark). Företagsgruppen omsätter cirka 300 mkr och har 35 anställda. NSS Group, med rötter i 1950-talet, har ett modernt och flexibelt utbud av produkter som är utformade för det krävande nordiska klimatet. Företagets kunder finns framför allt inom industri- och byggsektorn.\n\nVinges team bestod av Johan Winnerblad, Elsie Nassar, Ellinor Wargenbrant och August Ahlin (M&A), Christoffer Nordin och Axel Lennartsson (Kommersiella avtal), Karl-Gustaw Tobola (Bank- och finans), Kristoffer Larson (Fastighetsrätt och Miljö), Sara Passandideh (Arbetsrätt), Nicklas Thorgerzon (IT och GDPR), Ian Jonsson (Immaterialrätt) och Emelie Schoning (Projekt- och VDR-assistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-sobro-vid-investering-i-nss-group/","date":"2023-01-12","month":1},{"year":2023,"client":"Main Capital och Alfa eCare","work":"Förvärv","disciplines":["Arbetsrätt","Corporate Commercial","M&A","IT, Telekom och Outsourcing","Immaterialrätt"],"title":"Vinge biträder Main Capital och Alfa eCare i samband med förvärvet av Selfpoint","caption":"Förvärv · 2 januari 2023","preamble":"Alfa eCare-koncernen är en erkänd och snabbt växande mjukvaruleverantör inom e-hälsobranschen som tillhandahåller lösningar åt både privata och offentliga vårdgivare i Norden.","body":"Selfpoint Sverige AB grundades 2015 och tillhandahåller en s.k. ”low-code” plattform för arbetsflödes- och processhanteringslösningar för den svenska välfärdsmarknaden. Bolaget har över 40 kunder med en stark närvaro inom den offentliga sektorn. Den flexibla plattformen gör det möjligt för kunder att digitalisera arbetsflöden och processer i hela värdekedjan mot medborgare och vårdgivare. Selfpoint är Alfa eCares sjunde tilläggsförvärv sedan 2020 då Main Capital blev majoritetsägare av gruppen.\n\nVinges team bestod huvudsakligen av Filip Öhrner, Per Kling, Robin Fagerström (M&A), Sara Passandideh (arbetsrätt), Martin Boström (kommersiella avtal) Lisa Hörnqvist (IT och GDPR), Rebecka Målquist, Johan Gavelin (IP) och Emelie Schoning (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-main-capital-och-alfa-ecare-i-samband-med-forvarvet-av-selfpoint/","date":"2023-01-02","month":1},{"year":2023,"client":"Main Capital och Alfa eCare","work":"Förvärv","disciplines":["Arbetsrätt","IT, Telekom och Outsourcing","Immaterialrätt","M&A"],"title":"Vinge biträder Main Capital och Alfa eCare i samband med förvärvet av 2BRA","caption":"Förvärv · 2 januari 2023","preamble":"Alfa eCare-koncernen är en erkänd och snabbt växande mjukvaruleverantör inom e-hälsobranschen som tillhandahåller lösningar åt både privata och offentliga vårdgivare i Norden.","body":"2BRA System AB grundades 2008 och utvecklar verksamhetssystem för arbetsmarknadsrelaterade åtgärder och insatser. Bolagets tjänster erbjuds både till företag som stöttar människors etablering på arbetsmarknaden och till kommuner, där bolagets system idag används i över 100 kommunala verksamheter. 2BRA är Alfa eCares sjätte tilläggsförvärv sedan 2020 då Main Capital blev majoritetsägare av gruppen.\n\nVinges team bestod huvudsakligen av Filip Öhrner, Linus Adolfsson, Jonna Skog (M&A), Elin Broman (arbetsrätt), Lisa Hörnqvist (IT och GDPR), Rebecka Målquist, Johan Gavelin (IP) och Ottilia Pettersson (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-main-capital-och-alfa-ecare-i-samband-med-forvarvet-av-2bra/","date":"2023-01-02","month":1},{"year":2022,"client":"Lagercrantz Group","work":"Förvärv","disciplines":[],"title":"Vinge biträder Lagercrantz Group vid förvärv av Tykoflex","caption":"Förvärv · 21 december 2022","preamble":"Vinge har biträtt Lagercrantz Group vid förvärv av samtliga aktier i Tykoflex, som är en ledande tillverkare av högkvalitativa kapslingar för skarvning och terminering av fiberkablar i luft, mark och hav, samt kopplingselement för rörsystem.","body":"Tykoflex är baserat i Tyresö och beräknas för 2022 omsätta omkring 140 milj kr med ett rörelseresultat (EBITA) om 22-24 milj kr.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Gustav Wahlberg och Christoffer Nordin.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-vid-forvarv-av-tykoflex/","date":"2022-12-21","month":12},{"year":2022,"client":"People Ventures","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder People Ventures vid investering i Leia Health","caption":"Kapitalanskaffning · 21 december 2022","preamble":"Vinge har biträtt danska VC-fonden People Ventures vid investering i Leia Health, som utvecklat en app för att kartlägga fysisk och psykisk hälsa för kvinnor efter förlossning.","body":"Leia Health har tagit in 14 milj kr i sin senaste investeringsrunda och huvudinvesterare är, förutom People Ventures, Norrsken och Unconventional Ventures.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Eléonore Friberg, Jonna Skog, Ebba Nyberg och Karolina Fuhrman.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-people-ventures-vid-investering-i-leia-health/","date":"2022-12-21","month":12},{"year":2022,"client":"FAM","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge har företrätt FAM i samband med investering i Novare","caption":"Kapitalanskaffning · 21 december 2022","preamble":"Vinge har företrätt FAM AB, som ägs av Wallenbergstiftelserna, i samband med investering i Novaregruppen.","body":"Novare är en svensk koncern som erbjuder specialistkompetens inom området Human Capital.\n\nVinges team har huvudsakligen bestått av Jonas Johansson, Olivia Belding, Martin Boström, Narin Melazade, Ebba Svenburg, Nicklas Thorgerzon och Ellinore Boström Andersson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-fam-i-samband-med-investering-i-novare/","date":"2022-12-21","month":12},{"year":2022,"client":"Platzer","work":"Förvärv","disciplines":[],"title":"Vinge biträdde Platzer vid förvärvet av NCCs andel i Kineum","caption":"Förvärv · 21 december 2022","preamble":"Vinge biträdde Platzer vid förvärvet av NCCs andel i Kineum; en 27 våningar hög destination i Gårda, Göteborg. Projektet, som påbörjades 2018, har genomförts av Platzer och NCC i ett gemensamt ägt bolag.","body":"Genom affären blir Platzer ensam ägare av Kineum. Från Vinges sida har främst Olof Jisland och Kristoffer Larson medverkat.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-platzer-vid-forvarvet-av-nccs-andel-i-kineum/","date":"2022-12-21","month":12},{"year":2022,"client":"Tele2","work":"Finansiering","disciplines":[],"title":"Vinge biträder Tele2 i samband med hållbarhetslänkad kreditfacilitet","caption":"Finansiering · 20 december 2022","preamble":"Vinge biträder Tele2 AB (publ) i samband med ingåendet av dess första hållbarhetslänkade kreditfacilitet till ett belopp om EUR 700 miljoner, vilken kommer att nyttjas för allmänna företagsändmål och rörelsekapitalbehov.","body":"Räntesatsen i bolagets nya kreditfacilitet villkoras av hur bolaget lever upp till uppsatta mål inom klimat och jämställdhet, och kreditfaciliteten har en löptid om fem år med möjlighet till förlängning.\n\nVinges team bestod av Louise Brorsson Salomon, Lionardo Ojeda och Ida Redander.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-tele2-i-samband-med-hallbarhetslankad-kreditfacilitet/","date":"2022-12-20","month":12},{"year":2022,"client":"SiB Solutions","work":"Övrigt","disciplines":[],"title":"Vinge biträder SiB Solutions","caption":"Övrigt · 19 december 2022","preamble":"Vinge biträder SiB Solutions i samband med en investering från Scania Growth Capital (SGC).","body":"Vinges team består av Christian Lindhé, Niklas Törnell och Jasmine Elgh.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sib-solutions/","date":"2022-12-19","month":12},{"year":2022,"client":"Roima Intelligence Oy","work":"Övrigt","disciplines":["M&A"],"title":"Vinge företräder Roima Intelligence Oy","caption":"Övrigt · 19 december 2022","preamble":"Vinge företräder Roima Intelligence Oy, ett portföljbolag till Intera Partners, vid förvärv av Part Trap AB.","body":"Roima accelererar sin tillväxt med tillägget av Part Trap AB, en snabbväxande mjukvaruleverantör av ett B2B e-handelssystem för tillverkande och distribuerande bolag, känt som Parttrap ONE. Parttrap ONE erbjuder allt ett B2B-företag behöver för e-handel genom att snabbt möjliggöra digital försäljning av komplexa produkter och deras reservdelar. Part Trap är baserat i Göteborg, Sverige, och kommer att utöka Roimas svenska närvaro ytterligare.\n\nVinges team bestod av Jonas Bergström, Elsie Nassar och Robin Sultani (M&A), Axel Lennartsson (IP), Lisa Hörnqvist (Kommersiella avtal, IT och GDPR), Jonna Skog (Arbetsrätt) samt Anna Ekdahl Roos (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-roima-intelligence-oy/","date":"2022-12-19","month":12},{"year":2022,"client":"Velvet Cichlid","work":"Övrigt","disciplines":[],"title":"Vinge biträder Velvet Cichlid i budet på Sleep Cycle","caption":"Övrigt · 19 december 2022","preamble":"Velvet Cichlid har lämnat ett offentligt erbjudande till aktieägarna i Sleep Cycle AB (publ). Erbjudandet värderar aktierna i Sleep Cycle till cirka 862 miljoner kronor.","body":"Vinges team består av Jesper Schönbeck, Erik Sjöman, Linnéa Sellström, William Kåge, Emma Brolund, Philip Moré och Petter Hellgren (Kapitalmarknad och publik M&A), Louise Brorsson Salomon och Seyran Sahin (Bank och finans).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-velvet-cichlid-i-budet-pa-sleep-cycle/","date":"2022-12-19","month":12},{"year":2022,"client":"Intrum","work":"Obligationsemission","disciplines":["Bank och finans","Företagsbeskattning"],"title":"Vinge biträder Intrum vid obligationsemission om EUR 450m","caption":"Obligationsemission · 16 december 2022","preamble":"Vinge biträder Intrum AB (publ) vid dess emission av seniora, säkerställda fastränteobligationer om EUR 450 miljoner.","body":"Emissionslikviden ska delvis användas för att refinansiera Intrums existerande obligationer med förfall under 2024, och obligationerna ska enligt villkoren upptas till handel på Securities Official List på Luxembourg Stock Exchange. Obligationerna har en löptid om fem år och emitterades med en ränta på 9.25% och till ett pris om 97.020% av nominellt belopp.\n\nVinges team bestod av Louise Brorsson Salomon, Lionardo Ojeda, Jolinn Uhlin, Calle Tengwall Pagels (Bank och Finans), Victor Ericsson och Maja Prahl (Skatt)","href":"https://www.vinge.se/uppdrag/vinge-bitrader-intrum-vid-obligationsemission-om-eur-450m/","date":"2022-12-16","month":12},{"year":2022,"client":"Acrinova","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","Företagsbeskattning"],"title":"Vinge företräder Acrinova AB (publ) i samband med listbyte till Nasdaq Stockholm","caption":"Övrigt · 16 december 2022","preamble":"Vinge företräder Acrinova AB (publ) (”Acrinova” eller ”Bolaget”) i samband med Bolagets listbyte till Nasdaq Stockholm. Prospektet offentliggjordes den 9 december 2022 och första handelsdag på Nasdaq Stockholm var den 16 december 2022.","body":"Acrinova är en fastighetskoncern med fokus på södra Sverige och på kommersiella fastigheter. Bolaget erbjuder helhetstjänster som ägare, förvaltare och utvecklare inom fastigheter. Acrinova har sitt huvudkontor i Malmö. Bolaget byter lista från Nasdaq First North Premier Growth Market där Bolagets aktier varit noterade sedan 2019.\n\nVinges team bestod i huvudsak av Linnéa Sellström, Emma Brolund, Lorin Arabi och Michaela Ådén (Kapitalmarknad och Publik M&A), samt Victor Ericsson, Emelie Svanberg och Maja Prahl (företagsbeskattning).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-acrinova-ab-publ-i-samband-med-listbyte-till-nasdaq-stockholm/","date":"2022-12-16","month":12},{"year":2022,"client":"Nijhuis Saur Industries","work":"Förvärv","disciplines":[],"title":"Vinge företräder Nijhuis Saur Industries som svensk ombud i förvärv av Veolias mobile water solutions verksamhet.","caption":"Förvärv · 16 december 2022","preamble":"The transaction closed on 30 November 2022.","body":"Vinges team bestod av Ulrich Ziche, Sophie Böje, Vilhelm Rondahl (M&A) Jonna Skog (HR), Mario Saad (commercial contracts), Maria Schultzberg, Ulf Nilsson (båda skatt), Arvid Weimers (bank & finans) and Julia Hagelberg (paralegal).\n\nLäs mer här","href":"https://www.vinge.se/uppdrag/vinge-foretrader-nijhuis-saur-industries-som-svensk-ombud-i-forvarv-av-veolias-mobile-water-solutions-verksamhet/","date":"2022-12-16","month":12},{"year":2022,"client":"Hansa Biopharma","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Hansa Biopharma i samband med en riktad nyemission om 415,9 miljoner kronor","caption":"Kapitalanskaffning · 15 december 2022","preamble":"Vinge har biträtt Hansa Biopharma i samband med en riktad nyemission varigenom bolaget tillförs 415,9 miljoner kronor före transaktionskostnader.","body":"Hansa Biopharma är ett biofarmabolag i kommersiell fas som utvecklar innovativa, livräddande och livsförändrande behandlingar för patienter med sällsynta immunologiska sjukdomstillstånd. Hansa Biopharmas stamaktie är noterad på Nasdaq Stockholm.\n\nVinges team har bestått av Dain Hård Nevonen, Amanda Knutsson, Anders Sundin Lundberg och Petter Hellgren.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-hansa-biopharma-i-samband-med-en-riktad-nyemission-om-415-9-miljoner-kronor/","date":"2022-12-15","month":12},{"year":2022,"client":"Vicore Pharma Holding","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Vicore Pharma Holding AB (publ) i samband med en riktad nyemission","caption":"Kapitalanskaffning · 12 december 2022","preamble":"Vinge har företrätt Vicore Pharma Holding AB (publ) i samband med en riktad nyemission, varigenom Vicore Pharma tillförs 200 miljoner kronor före transaktionskostnader.","body":"Emissionen riktades till ett antal svenska och internationella institutionella investerare på grundval av ett accelererat bookbuilding-förfarande. Vicore Pharma avser bland annat att använda emissionslikviden till att finansiera förberedelser inför bolagets kliniska fas IIb-studie inom idiopatisk lungfibros (IPF), däribland uppskalning och tillverkning, parallellt med slutförandet av IPF AIR-studien.\n\nVinges team har bestått av Rikard Lindahl, Joel Magnusson och Annie Fällström.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-vicore-pharma-holding-ab-publ-i-samband-med-en-riktad-nyemission-1/","date":"2022-12-12","month":12},{"year":2022,"client":"BHG","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder BHG i samband med riktad nyemission","caption":"Kapitalanskaffning · 9 december 2022","preamble":"Vinge biträder BHG Group AB (publ) i samband med en riktad nyemission om 800 miljoner kronor genom ett accelererat bookbuilding-förfarande.","body":"Vinges team består av Christian Lindhé, Martin Svanberg, Astrid Isberg, Johanne Örnfeldt Svensson och Jasmine Elgh. Kristian Ford är klientansvarig partner.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-bhg-i-samband-med-riktad-nyemission/","date":"2022-12-09","month":12},{"year":2022,"client":"BICO","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträdde BICO vid en riktad emission om 487 MSEK till Sartorius","caption":"Kapitalanskaffning · 9 december 2022","preamble":"Vinge har birätt BICO Group AB i samband med en riktad nyemission till Sartorius AG som tillför BICO 487 MSEK. Teckningskursen, 76 SEK motsvarade en premie om 2,7 procent jämfört 3-dags VWAP. I samband med emissionen har BICO och Sartorius träffat en överenskommelse om att ingå ett omfattande teknik-, försäljnings- och marknadssamarbete.","body":"Vinges team bestod av Anders Strid, Edin Agic och bolagsassistenten Daniela Maniscalchi.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-bico-vid-en-riktad-emission-om-487-msek-till-sartorius/","date":"2022-12-09","month":12},{"year":2022,"client":"Eleda Koncernen (Eleda)","work":"Övrigt","disciplines":["M&A"],"title":"Vinge har företrätt Eleda Koncernen (\"Eleda\")","caption":"Övrigt · 9 december 2022","preamble":"Vinge har företrätt Eleda i samband med förvärv av finska Enerims Smart Metering verksamhet. Verksamheten levererar smart metering tjänster, insamling och analys, till kunder över hela Finland.","body":"Vinges team bestod huvudsakligen av Christina Kokko och Samra Tesser.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-koncernen-eleda/","date":"2022-12-09","month":12},{"year":2022,"client":"LumenRadio","work":"Börsnotering","disciplines":["Kapitalmarknad och publik M&A","Arbetsrätt"],"title":"Vinge företrädde LumenRadio AB (publ) i samband med noteringen på Nasdaq First North Growth Market","caption":"Börsnotering · 8 december 2022","preamble":"Vinge företrädde LumenRadio AB (publ) (”LumenRadio”) i samband med dess notering på Nasdaq First North Growth Market. Prospektet offentliggjordes den 28 november 2022 och första dagen för handel inträffade den 8 december 2022.","body":"Erbjudandet i samband med noteringen genomfördes till ett fast pris om 48 kronor per aktie, motsvarande ett marknadsvärde för LumenRadio aktier om cirka 544 miljoner kronor före erbjudandet och cirka 594 miljoner kronor efter genomförandet av erbjudandet.\n\nLumenRadio är ett Göteborgsbaserat teknikbolag som utvecklar och säljer tillförlitliga trådlösa produkt-till-produkt-uppkopplingar för verksamhetskritiska applikationer inom Internet of Things (”IoT”). LumenRadio erbjuder skalbara lösningar som bygger på en egenutvecklad och patenterad teknik för tillförlitlig trådlös dataöverföring på de öppna frekvensbanden, vilket ersätter traditionella kablar för styrning och automation. LumenRadio har cirka 60 anställda och huvudkontor i Göteborg, samt försäljningskontor i Frankfurt och Boston.\n\nVinges team bestod huvudsakligen av Magnus Pauli, Edin Agic (Projektledare), Petronella Hallberg, Adrian Filipovic, Amelia Rihs, Hanna Jansson (Kapitalmarknad och Publik M&A), Anna Högsten, Victoria Gunnerek (Arbetsrätt och Sanktioner) och Amanda Stoltz (VDR).","href":"https://www.vinge.se/uppdrag/vinge-foretradde-lumenradio-ab-publ-i-samband-med-noteringen-pa-nasdaq-first-north-growth-market/","date":"2022-12-08","month":12},{"year":2022,"client":"Eleda Infra Services Group (Eleda)","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har företrätt Eleda Infra Services Group (”Eleda”) i samband med förvärv av Gjermundshaug Anlegg AS och Anlegg Øst Entreprenør AS (”Gjermundshaug Gruppen”)","caption":"Förvärv · 5 december 2022","preamble":"Gjermundshaug Gruppen utför anläggningsuppdrag inom väg, järnväg och annan infrastruktur. Per 2021 hade koncernen en total omsättning på cirka 1,3 miljarder NOK och ett rörelseresultat på 140 miljoner NOK. Genom förvärvet etablerar sig Eleda i Norge och påbörjar sin internationella satsning.","body":"Förvärvet är villkorat av godkännande av Konkurransetilsynet.\n\nVinges team bestod huvudsakligen av Christina Kokko, Per Kling och Ellen Flygt (M&A) och David Olander (ECR) samt Advokatfirman Thommessen avseende norsk rätt.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-infra-services-group-eleda-i-samband-med-forvarv-av-gjermundshaug-anlegg-as-och-anlegg-ost-entreprenor-as-gjermundshaug-gruppen/","date":"2022-12-05","month":12},{"year":2022,"client":"Viva Media","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Viva Media vid förvärv av Kalmar Kreation","caption":"Förvärv · 5 december 2022","preamble":"Vinge har biträtt marknadsföringsbyrån Viva Media vid förvärv av reklambyrån Kalmar Kreation.","body":"Kreation innefattar dotterbolaget och filmbyrån Wedomotion. Viva Media har totalt drygt 100 anställda efter transaktionen.\n\nVinges team bestod i huvudsak av Johan Winnerblad och Nina Fathjalali.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-viva-media-vid-forvarv-av-kalmar-kreation/","date":"2022-12-05","month":12},{"year":2022,"client":"Cafeyn","work":"Offentligt uppköpserbjudande","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Cafeyn i samband med Bonnier News bud på Readly","caption":"Offentligt uppköpserbjudande · 5 december 2022","preamble":"Tidnings AB Marieberg, en del av Bonnier News, har offentliggjort ett uppköpserbjudande om 455 miljoner kronor avseende aktierna i Readly International AB (publ).","body":"Cafeyn Group och Bonnier News har i samband med detta träffat avtal med avsikten att Cafeyn blir ägare av Readlys icke-nordiska verksamheter, villkorat av att uppköpserbjudandet fullföljs. Vinge biträder Cafyen.\n\nVinges team består huvudsakligen av Erik Sjöman, Henrik Borna, Daniel Daun, Lisa Bourghardt och Martin Svanberg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-cafeyn-i-samband-med-bonnier-news-bud-pa-readly/","date":"2022-12-05","month":12},{"year":2022,"client":"SBB","work":"Avyttring","disciplines":["Kapitalmarknad och publik M&A","EU‑ och konkurrensrätt","Fastigheter och Entreprenad","Bank och finans","M&A","Tvistlösning"],"title":"Vinge företräder SBB i samband med dess försäljning till Brookfield","caption":"Avyttring · 2 december 2022","preamble":"Vinge företräder Samhällsbyggnadsbolaget i Norden (publ) AB (\"SBB\") i samband med dess försäljning av en andel av sin portfölj inom social infrastruktur för utbildning till Brookfield för 9,2 miljarder kronor. Transaktionen innefattar även tilläggsköpeskillingar om upp till 1,2 miljarder kronor.","body":"SBB säljer sin portfölj inom social infrastruktur för utbildning, om 44,9 miljarder kronor, till ett nybildat dotterbolag till SBB, EduCo AB (”EduCo”). Brookfield, en av världens största investerare inom infrastruktur, förvärvar genom sin open-ended, core infrastrukturfond (Brookfield Super-core Infrastructure Partners) en andel om 49 % av EduCo från SBB mot en ersättning bestående av cirka 9,2 miljarder kronor genom kontant betalning, samt cirka 1,2 miljarder kronor kontant genom tilläggsköpeskillingar. EduCo kommer att drivas och förvaltas av SBB under ett förvaltningsavtal som avser hela EduCos portfölj.\n\nVinges team bestod av Jesper Schönbeck, Rikard Lindahl och Joel Wahlberg (Kapitalmarknad och public M&A), Niclas Winnberg, Karolina Cohrs, Frida Ställborn, Kristoffer Larsson och Anette Kahn (Fastighet och social infrastruktur), Albert Wållgren, Linn Adelwald och Axel Jansson (Finansiering), Maria Dahlin Kolvik och Sebastian Saadieh (M&A), Marcus Glader och Trine Osen Bergqvist (Konkurrensrätt) samt Robert Wikholm (Rekonstruktioner och obestånd).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-sbb-i-samband-med-dess-forsaljning-till-brookfield/","date":"2022-12-02","month":12},{"year":2022,"client":"Oncopeptides","work":"Kapitalanskaffning","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Oncopeptides i samband med ingående av förnyat avtal om lånefacilitet om upp till 30 miljoner euro från den Europeiska investeringsbanken","caption":"Kapitalanskaffning · 1 december 2022","preamble":"Låneavtalet med den Europeiska investeringsbanken (EIB) ger Oncopeptides tillgång till en icke-säkerställd lånefacilitet om upp till 30 miljoner euro. Låneavtalet är indelat i tre trancher som vardera har en löptid om fem år och kommer att bli tillgängliga om bolaget, bland annat, uppfyller vissa milstolpar kopplade till den pågående kommersialiseringen av Pepaxti® i Europa och en möjlig re-lansering av Pepaxto® i USA. I samband med låneavtalet har Oncopeptides ingått ett förnyat teckningsoptionsavtal med EIB som ger EIB rätt till teckningsoptioner i bolaget om bolaget nyttjar lånefaciliteten.","body":"Oncopeptides är ett biotechbolag inriktat på utvecklingen av riktade terapier för svårbehandlade hematologiska sjukdomar. Bolagets ledande produkt är godkänd på flera marknader för behandling av vuxna patienter med multipelt myelom. Bolagets aktie är upptagen till handel på Nasdaq Stockholm.\n\nVinges team har bestått av Louise Brorsson Salomon, Arvid Weimers och Kamyar Najmi (finansiering) samt Dain Hård Nevonen och Linnéa Sellström (kapitalmarknad).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-oncopeptides-i-samband-med-ingaende-av-fornyat-avtal-om-lanefacilitet-om-upp-till-30-miljoner-euro-fran-den-europeiska-investeringsbanken/","date":"2022-12-01","month":12},{"year":2022,"client":"Gotlandsbolaget","work":"Avyttring","disciplines":["Sjö‑ och transporträtt","M&A"],"title":"Vinge har rådgivit Gotlandsbolaget i samband med fartygsförsäljningar","caption":"Avyttring · 30 november 2022","preamble":"Gotlandsbolaget och dess dotterbolag Gotland Tankers, har genomfört fyra lyckade försäljningar av tankfartygen M/T Gotland Carolina, M/T Gotland Sofia, M/T Gotland Aliya respektive M/T Gotland Marieann.","body":"Fartygen är byggda mellan 2006 och 2008 i den egna serien Gotland Class. Vinge har rådgivit Gotlandsbolaget genom affärerna och bistått vid kontraktsförhandlingar, leverans av fartygen samt avregistrering från Bahamas fartygsregister.\n\nVinges team har bestått av Paula Bäckdén och Hanna Marberg med stöttning av Amelia Rihs och, i bolagsrättsliga frågor, Petronella Hallberg. Försäljningarna innebär att alla fartyg i Gotland Class har sålts och är enligt Gotlandsbolaget ett led i bolagets strategi att fokusera än mer på industriell sjöfart och infrastruktur.","href":"https://www.vinge.se/uppdrag/vinge-har-radgivit-gotlandsbolaget-i-samband-med-fartygsforsaljningar/","date":"2022-11-30","month":11},{"year":2022,"client":"Polhem Infra","work":"Avtal","disciplines":["M&A"],"title":"Vinge företräder Polhem Infra vid tecknande av ramavtal med Solkompaniet gällande solkraftsparker","caption":"Avtal · 28 november 2022","preamble":"Vinge har hjälpt Polhem Infra när det tecknat ett ramavtal med Solkompaniet avseende projektering, utveckling och byggnation av storskaliga solkraftsparker i Sverige.","body":"Avtalet möjliggör utveckling och byggnation av solkraftsparker med en uppskattad sammanlagd kapacitet upp till 600MW. I avtalet ingår från start två projekt under utveckling av Solkompaniet med en uppskattad kapacitet om 100MW.\n\nVinges team bestod av Henrik Ossborn, Christoffer Thalin och Carl Trolle Olson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-polhem-infra-vid-tecknande-av-ramavtal-med-solkompaniet-gallande-solkraftsparker/","date":"2022-11-28","month":11},{"year":2022,"client":"IO Group","work":"Förvärv","disciplines":["IT, Telekom och Outsourcing","Immaterialrätt","M&A"],"title":"Vinge har företrätt iO Group i samband med förvärvet av den digitala webbyrån Triggerfish","caption":"Förvärv · 28 november 2022","preamble":"Triggerfish är en digital webbyrå baserad i Stockholm som erbjuder tjänster inom WordPress, analys, strategi, design och varumärkesutveckling.","body":"Triggerfish grundades 1999 och har idag 44 anställda.\n\niO Group är en innovativ digital servicekoncern i Benelux och Norden, som tillhandahåller tjänster för kommunikation och digital transformation.\n\nVinges team bestod huvudsakligen av Magnus Pauli, Johanna Hamrefält (Projektledare), Fredrik Löwenclou (M&A), Rebecka Hansson (Arbetsrätt), Oscar Jansson (IP/IT) and Alexander Lindeberg (IP/IT).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-io-group-i-samband-med-forvarvet-av-den-digitala-webbyran-triggerfish/","date":"2022-11-28","month":11},{"year":2022,"client":"Aneo","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Aneo i budet på Scandinavian Biogas","caption":"Övrigt · 24 november 2022","preamble":"Aneo Renewables Holding AS har lämnat ett offentligt erbjudande till aktieägarna i Scandinavian Biogas Fuels International AB enligt reglerna om budplikt. Erbjudandet värderar aktierna i Scandinavian Biogas till cirka 670 miljoner kronor. Vinge biträder Aneo.","body":"Vinges team består huvudsakligen av Erik Sjöman, Christian Lindhé, Martin Svanberg och Johan Åhman.\n\n--","href":"https://www.vinge.se/uppdrag/vinge-bitrader-aneo-i-budet-pa-scandinavian-biogas/","date":"2022-11-24","month":11},{"year":2022,"client":"Aneo","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträdde Aneo i samband med riktad nyemission i Scandinavian Biogas","caption":"Kapitalanskaffning · 24 november 2022","preamble":"Scandinavian Biogas Fuels International AB har genomfört en riktad nyemission om 326 miljoner kronor. Vinge biträdde Aneo Renewables Holding AS, som är Scandinavian Biogas största aktieägare.","body":"Vinges team bestod huvudsakligen av Christian Lindhé, Erik Sjöman och Martin Svanberg.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-aneo-i-samband-med-riktad-nyemission-i-scandinavian-biogas/","date":"2022-11-24","month":11},{"year":2022,"client":"Grundaren av Hub Planner","work":"Kapitalanskaffning","disciplines":["Arbetsrätt","M&A"],"title":"Vinge företräder grundaren av Hub Planner vid försäljning till Monterro","caption":"Kapitalanskaffning · 24 november 2022","preamble":"Vinge företräder grundaren Stephen Martin vid försäljningen av en majoritet av aktierna i Hub Planner och dess mjukvaruplattform för resursplanering till riskkapitalbolaget Monterro.","body":"Hub Planner grundades 2013 i Stockholm av irländaren Stephen Martin. Bolagets mjukvaruplattform tillhandahålls som en SaaS-lösning och möjliggör enklare hantering av personalfrågor såsom resursplanering, schemaläggning och tidrapportering. Bland Hub Planners nuvarande kunder återfinns bolag såsom Mercedes, Havas och Pfizer, men den största kundgruppen består annars i konsultbolag som med hjälp av platformen bl a kan bemanna projekt och rapportera in arbetade timmar.\n\nVinges team har bestått av Jonas Johansson och Carl Sander (M&A) samt Sara Strandberg (arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-grundaren-av-hub-planner-vid-forsaljning-till-monterro/","date":"2022-11-24","month":11},{"year":2022,"client":"Igneo Infrastructure Partners","work":"Avyttring","disciplines":[],"title":"Vinge har biträtt Igneo Infrastructure Partners i samband med försäljningen av ForSea AB","caption":"Avyttring · 24 november 2022","preamble":"Vinge har biträtt Igneo Infrastructure Partners under försäljningsprocessen av ForSea-koncernen till Seabridge BidCo AB, ett helägt dotterbolag till Molslinjen A/S, vilket ytterst ägs av EQT. ForSea AB med dotterbolag driver trafiken på färjelinjen mellan Helsingborg och Helsingør och är den enda operatören av ”roll-on/roll-off-färjor” på denna rutt med över 6 miljoner passagerare årligen.","body":"Vinges team har bestått av bl.a. Christoffer Thalin, Henrik Borna, Anna Jonsson, Rikard Azelius, Martin Johansson, Emelie Svensäter Jerntorp, Fredrik Christiansson, Lisa Bourghardt, Niklas Törnell, Lotta Knapp Lönroth, Paula Bäckdén, Victoria Fredén, Agaton Lindgren, Johanne Örnfeldt Svensson, Emil Sandgrim och Clara Klingspor.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-igneo-infrastructure-partners-i-samband-med-forsaljningen-av-forsea-ab/","date":"2022-11-24","month":11},{"year":2022,"client":"Axcel VI och Currentum","work":"Förvärv","disciplines":["M&A","Bank och finans","Fastigheter och Entreprenad","Arbetsrätt"],"title":"Vinge företräder Axcel VI och Currentum vid förvärv av Holmströms Rör","caption":"Förvärv · 22 november 2022","preamble":"Vinge företräder Axcel VI och Currentum-koncernen vid förvärven av Holmströms Rör AB, Holmströms Rör i Ängelholm AB samt Holmströms Rör Syd Väst AB.","body":"Bolagen tillhandahåller tjänster inom installation och service av värme och sanitet och är verksamma i Skåne. Tillsammans omsätter bolagen årligen cirka 192 miljoner kronor och har drygt 70 medarbetare.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Karl Klackenberg, Carl Fredrik Wachtmeister och Egil Svensson (M&A), Daniel Prawitz (Entreprenadrätt), Elin Broman (Arbetsrätt), Calle Tengwall Pagels (Finansiering), Frida Ställborn (Fastighetsrätt) och Anna Ekdahl Roos (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-vi-och-currentum-vid-forvarv-av-holmstroms-ror/","date":"2022-11-22","month":11},{"year":2022,"client":"PulPac","work":"Kapitalanskaffning","disciplines":["Arbetsrätt","Immaterialrätt","M&A"],"title":"Vinge biträder vid investering i PulPac","caption":"Kapitalanskaffning · 18 november 2022","preamble":"Vinge har biträtt PulPac AB i samband med en investering om totalt MEUR 31 från strategiska partners Aliaxis, Stora Enso, Amcor Ventures och Teseo Capital. Befintliga ägare inklusive den störste ägaren WPP har också deltagit i finansieringsrundan.","body":"PulPac har utvecklat ett sätt att tillverka plastliknande material och produkter, bl.a. förpackningar, med papper som råvara istället för plast, s k Dry Molded Fiber, i en process som kräver betydligt mindre vatten än tidigare metoder. Bolaget grundades 2018, har ca 70 anställda och är baserat i Göteborg.\n\nVinges team bestod huvudsakligen av Kristian Ford, Sofie Nordgren, Carl Trolle Olsson, Lisa Bourghardt och Karin Gynnerstedt.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-investering-i-pulpac/","date":"2022-11-18","month":11},{"year":2022,"client":"Midagon Group Oy","work":"Övrigt","disciplines":["Arbetsrätt","Corporate Crime & Compliance","M&A"],"title":"Vinge har företrätt Midagon Group Oy","caption":"Övrigt · 16 november 2022","preamble":"Vinge har företrätt Midagon Group Oy, ett portföljbolag till Intera Partners, vid dess förvärv av Kontract AB.","body":"Kontract är ett oberoende IT-konsultbolag med ca 70 anställda. Genom förvärvet, vilket kommer att slutföras i slutet av 2022, strävar Midagon och Kontract efter att bli en nordisk ledare inom oberoende affärs – och IT konsultverksamhet med ett team om ca 170 experter i Finland och Sverige.\n\nVinges team har bestått av bland andra Jonas Bergström och Gustav Wahlberg (M&A), Sara Strandberg och Sara Passandideh (Arbetsrätt) samt Tove Tullberg (Compliance).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-midagon-group-oy/","date":"2022-11-16","month":11},{"year":2022,"client":"Heda Security","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Heda Security vid förvärv av M&M Stängsel Service","caption":"Förvärv · 11 november 2022","preamble":"Vinge har biträtt Heda Security i förvärvet av aktierna i M&M Stängsel. Heda Security-koncernen är Nordens ledande företagsgrupp inom installation och service av områdessäkerhet och omsätter efter det senaste förvärvet ca 600 miljoner kronor och har 200 anställda.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Nando Basic.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-heda-security-vid-forvarv-av-m-m-stangsel-service/","date":"2022-11-11","month":11},{"year":2022,"client":"LKAB","work":"Kapitalanskaffning","disciplines":["Bank och finans"],"title":"Vinge företräder LKAB i samband med dess investering i den hållbara producenten av sällsynta jordartsmetaller, REEtec.","caption":"Kapitalanskaffning · 8 november 2022","preamble":"Vinge har biträtt Luossavaara-Kiirunavaara AB (publ) (“LKAB”) i samband med dess investering i REEtec Holding AS (“REEtec”). LKAB investerar i finansieringsrundan, som totalt uppgår till 1,2 miljarder NOK, för att bli den största aktieägaren i REEtec.","body":"REEtec har utvecklat en innovativ och hållbar teknik för separering av sällsynta jordartsmetaller och den nya finansieringen kommer användas för att finansiera byggnationen av dess första separationsanläggning som kommer vara belägen i Herøya, Norge. REEtecs process kombinerar hög effektivitet med upp till 90 procent lägre koldioxidutsläpp.\n\nEfterfrågan av sällsynta jordartsmetaller, vilken drivs av bland annat produktionen av elbilar och vindkraftverk, förväntas femdubblas fram till år 2030. Eftersom Europa är beroende av import av dessa kritiska mineraler ligger LKABs investering i REEtec väl i linje med Europeiska unionens strategi för att öka Europas självförsörjning. Den nya separationsanläggningen i Herøya kommer att ha en produktion om 720 ton av jordartsmetallerna Neodym och Praseodym, motsvarande fem procent av Europas behov. Majoriteten av produktionen kommer att säljas till bilindustrin. En andra anläggning är planerad att byggas i Herøya år 2026, som även kommer att processa material från LKABs utvinning av sällsynta jordartsmetaller från gruvavfall, som processas i industriparken i Luleå som är planerad för produktion år 2027.\n\nWiersholm biträdde LKAB som legal rådgivare avseende norsk rätt och PwC agerade finansiell rådgivare till LKAB.\n\nVinges team bestod av Olof Jisland, Albert Wållgren och Arvid Weimers.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-lkab-i-samband-med-dess-investering-i-den-hallbara-producenten-av-sallsynta-jordartsmetaller-reetec/","date":"2022-11-08","month":11},{"year":2022,"client":"STARK Group","work":"Förvärv","disciplines":["Bank och finans","EU‑ och konkurrensrätt","Arbetsrätt","Kommersiella avtal","M&A","Fastigheter och Entreprenad"],"title":"Vinge företrädde STARK Group i förvärvet av FagFlis Group","caption":"Förvärv · 7 november 2022","preamble":"Vinge företrädde STARK Group i samband med förvärvet av den nordiska kakelaktören FagFlis Group med den svenska verksamheten FF Kakel AB. Koncernen har varit verksamt sedan 1981 och innefattar, utöver de svenska butikerna, ca 30 anläggningar i Norge med en omsättning på totalt ca 750 miljoner NOK.","body":"Transaktionen beräknas slutföras runt årsskiftet 2022/2023 efter godkännande av norska konkurrensverket.\n\nVinges team bestod av bland andra Jonas Bergström, Joacim Rydergård, Ellinor Wargenbrant och Tobias Onegård Karlsson (M&A), Frida Ställborn (Fastighet), Hedvig Ekdahl (Kommersiella avtal), Ebba Svenburg (Arbetsrätt), Karl-Gustaw Tobola (Bank och finans), Sebastian Örndahl och Adam Löfquist (Konkurrensrätt) och Anna Ekdahl Roos (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretradde-stark-group-i-forvarvet-av-fagflis-group/","date":"2022-11-07","month":11},{"year":2022,"client":"Midway Holding","work":"Förvärv","disciplines":[],"title":"Vinge företräder Midway Holding AB (publ) vid förvärv av EKRO Bausystem GmbH","caption":"Förvärv · 5 november 2022","preamble":"EKRO Bausystem GmbH tillverkar och säljer produkter för arbete på temporära arbetsplatser med Österrike som största marknad.","body":"Vinges team bestod av Anna Edström, Daniel Melander Björner och Oskar Larsson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-midway-holding-ab-publ-vid-forvarv-av-ekro-bausystem-gmbh/","date":"2022-11-05","month":11},{"year":2022,"client":"Helix Kapital","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Helix Kapital vid investering i Competence Factory","caption":"Kapitalanskaffning · 4 november 2022","preamble":"Vinge har biträtt Helix Kapital vid etableringen av Wellness Education & Technology AS och dess förvärv av Competence Factory AB, som bl.a. erbjuder utbildning inom träning, hälsa och kost.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Nando Basic.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-helix-kapital-vid-investering-i-competence-factory/","date":"2022-11-04","month":11},{"year":2022,"client":"Helix Kapital","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Helix Kapital vid investering i Akademiet For Personlig Trening","caption":"Kapitalanskaffning · 4 november 2022","preamble":"Vinge har biträtt Helix Kapital vid etableringen av Wellness Education & Technology AS och dess förvärv av norska Akademiet For Personlig Trening AS, som sedan 2005 erbjuder utbildning inom träning, hälsa och kost.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Nando Basic.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-helix-kapital-vid-investering-i-akademiet-for-personlig-trening/","date":"2022-11-04","month":11},{"year":2022,"client":"Ambea","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt Ambea AB (publ) i samband med dess refinansiering","caption":"Finansiering · 4 november 2022","preamble":"Vinge har biträtt Ambea AB (publ), Skandinaviens ledande omsorgsföretag, i samband med refinansiering till ett sammanlagt belopp om SEK 5.000.000.000.","body":"Ambea AB (publ) ingick den 31 oktober 2022 ett nytt revolverande låneavtal med ett banksyndikat bestående av tre nordiska banker. Det nya låneavtalet har en löptid på tre år med en förlängningsmöjlighet på 1 år och består av en bekräftad kreditram på SEK 4.000.000.000 med en möjlighet att utöka kreditramen med ytterligare SEK 1.000.000.000.\n\nSyftet med refinansieringen är att refinansiera utestående skuld under tidigare låneavtal om totalt SEK 4.500.000.000 samt att öka Ambea koncernens finansiella flexibilitet.\n\nVinges team bestod av delägare Albert Wållgren tillsammans med Josefine Lanker och Sofia Haggren.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-ambea-ab-publ-i-samband-med-dess-refinansiering-om-msek-5-000/","date":"2022-11-04","month":11},{"year":2022,"client":"Tritons portföljbolag Sunweb","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Tritons portföljbolag Sunweb vid förvärv av Airtours","caption":"Förvärv · 2 november 2022","preamble":"Vinge företräder Tritons portföljbolag Sunweb Group, ett ledande holländskt resebolag, i samband med dess förvärv av Airtours – Sveriges fjärde största researrangör.","body":"Genom förvärvet förstärker Sunweb sin nuvarande verksamhet i Sverige, och blir en av de ledande aktörerna i Norden.\n\nVinges team bestod av bland andra Christina Kokko, Johanna Wiberg, Ulrich Ziche, Nando Basic och August Ahlin (M&A), Nour Makie (Bank och finans), Michael Montner (IP), Lisa Hörnqvist och Sam Fakhraie Ardekani (Kommersiella avtal), Emil Lindwall (Arbetsrätt) och Jasmina Skandrani (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-tritons-portfoljbolag-sunweb-vid-forvarv-av-airtours/","date":"2022-11-02","month":11},{"year":2022,"client":"Re:NewCell","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Re:NewCell i samband med en riktad nyemission","caption":"Kapitalanskaffning · 31 oktober 2022","preamble":"Vinge har företrätt Re:NewCell, ett textilåtervinningsbolag noterat på Nasdaq First North Premier Growth Market, i samband med en riktad nyemission varigenom bolaget tillfördes cirka 158 miljoner kronor före emissionskostnader.","body":"Emissionen riktades till ett antal utvalda svenska och internationella institutionella investerare på grundval av en accelererad bookbuilding process.\n\nRe:NewCell AB (publ) grundades 2012 av forskare vid KTH i Stockholm. Det är ett flerfaldigt prisbelönt sustaintechbolag baserat i Sverige. Renewcells vision är att göra modeindustrin cirkulär.\n\nVinges team bestod av Dain Hård Nevonen, William Kåge och Johannes Akyol. Henrik Ossborn och Agaton Lindgren biträdde avseende finansieringsfrågor.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-re-newcell-i-samband-med-en-riktad-nyemission-1/","date":"2022-10-31","month":10},{"year":2022,"client":"Azelio","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Azelio i samband med dess företrädesemission","caption":"Kapitalanskaffning · 26 oktober 2022","preamble":"Vinge har företrätt Azelio AB (publ) i samband med en fullt garanterad företrädesemission, vilken tillför Azelio cirka 300 miljoner kronor före avdrag för transaktionskostnader.","body":"De nya aktierna och teckningsoptionerna som emitteras inom ramen för företrädesemissionen beräknas bli föremål för handel på Nasdaq First North Growth Market omkring den 31 oktober 2022.\n\nAzelio är ett publikt svenskt bolag och specialiserar sig på lagring av energi med produktion av el och värme. Azelios system (”TES.POD”) för förnybar, Stirlingbaserad el- och värmeproduktion baserad på termisk energilagring bygger på löpande teknisk utveckling och förädling. Teknologin gör energin styrbar, vilket möjliggör att förnybar energi kan göras tillgänglig dygnet runt.\n\nAzelios aktier är noterade på Nasdaq First North Growth Market.\n\nVinges team bestod i huvudsak av David Andersson, William Kåge, Joel Magnusson, Benjamin Vafaeian och Joacim Malmqvist.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-azelio-i-samband-med-dess-foretradesemission/","date":"2022-10-26","month":10},{"year":2022,"client":"Newen Studios SAS","work":"Förvärv","disciplines":["Arbetsrätt","Immaterialrätt","M&A","Kommersiella avtal"],"title":"Vinge har biträtt Newen Studios SAS vid förvärvet av majoritetsägandet i Anagram koncernen","caption":"Förvärv · 26 oktober 2022","preamble":"Newen Studios är en ledande aktör inom audiovisuell produktion och distribution i Europa.","body":"Anagram grundades 2002 av komikerna Anders Jansson och Johan Wester och är ett av de ledande oberoende produktionsbolagen i Skandinavien.\n\nVinges team bestod av ansvarig delägare Wibeke Sorling, Johanna Hamrefält (M&A), Anna Högsten (IP & Arbetsrätt), Amelia Rihs (Bolagsrätt), Adrian Filipovic (M&A) och Amanda Stoltz.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-newen-studios-sas-vid-forvarvet-av-majoritetsagandet-i-anagram-koncernen/","date":"2022-10-26","month":10},{"year":2022,"client":"Baseload Capital","work":"Finansiering","disciplines":["Bank och finans","M&A"],"title":"Vinge företräder Baseload Capital i samband med bolagets nya finansiering om ca 500 miljoner SEK","caption":"Finansiering · 25 oktober 2022","preamble":"Vinge har biträtt Baseload Capital Holding AB i samband med upptagande av ny finansiering om ca 500 miljoner SEK. Finansieringen består av (i) ett konvertibellån om 24 miljoner USD från befintliga och nya investerare, och (ii) en kreditfacilitet med konvertibelvillkor om 25 miljoner EUR från Sustainable Development Capital (SDCL) för att finansiera utveckling av befintliga och nya geotermiska energianläggningar.","body":"De nuvarande aktieägarna som deltog i finansieringsrundan består av Gullspång Invest, Chevron Technology Ventures – investeringsarmen för Chevron, ett av världens största energibolag – och Breakthrough Energy Ventures – ett bolag grundat av Bill Gates med syfte att investera i teknologier för att nå netto-noll utsläpp till år 2050. De nya investerarna består av det teknikfokuserade energibolaget Baker Hughes samt Nordic Environment Finance Corporation (Nefco) – den nordiska gröna banken.\n\nBaseload Capital är verksamt inom finansiering, projektering och byggnation av internationella projekt för förnyelsebar energi, främst inom geotermisk energi, d.v.s. värme som lagras i jordens inre. Geotermisk energi fungerar självständigt utan påverkan av väder eller dagliga fluktuationer, varför den är välanpassad för att användas som baskraft i stora energisystem. I tillägg till att användas som baskraft kan geotermiskt vatten användas för utvinning av mineraler såsom litium, vilket skapar ett ekosystem av ytterligare fördelar för planeten.\n\nVinges team bestod huvudsakligen av Maria Dahlin Kolvik och Måns Håkanson (M&A) samt Louise Brorsson Salomon, Arvid Weimers och Jolinn Uhlin (Finansiering).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-baseload-capital-i-samband-med-bolagets-nya-finansiering-om-ca-500-miljoner-sek/","date":"2022-10-25","month":10},{"year":2022,"client":"Spring Media","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Spring Media vid förvärv av Athletic Sports Group","caption":"Förvärv · 20 oktober 2022","preamble":"Vinge har biträtt Spring Media vid förvärv av den hollandsbaserade sportmediabyrån Athletic Sports Group med dotterbolaget Fight Globe.","body":"Genom förvärvet får Spring Media en marknadsledande position avseende mediarättigheter till kampsport.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Clara Sohlberg, Robin Sultani och Kamyar Najmi.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-spring-media-vid-forvarv-av-athletic-sports-group/","date":"2022-10-20","month":10},{"year":2022,"client":"NatWest Markets N.V.","work":"Övrigt","disciplines":[],"title":"Vinge har biträtt NatWest Markets N.V. med utökning av värdepapperisering","caption":"Övrigt · 19 oktober 2022","preamble":"Vinge har biträtt NatWest Markets N.V. som senior långivare i samband med ändring av ett existerande finansieringsavtal för DBT Capital AB och dess dotterbolag (”DBT”). Ändringen innebar, bland annat, en ökning av det totala facilitetsbeloppet till upp till SEK 3.100.000.000 och inkluderandet av en entitet kontrollerad av globala investmentbolaget Värde Partners som mezzanine-långivare. Finansieringen är del av en värdepapperisering av säkerställda lån till små- och medelstora företag (SME) utgivna av DBT.","body":"DBT är en svensk privat långivare som är registrerat som finansiellt institut hos Finansinspektionen och som erbjuder företagsfinansiering och företagslån för SME i Sverige.\n\nTransaktionen utförs och rapporteras i enlighet med värdepapperiseringsförordningen från EU (Europaparlamentets och Rådets förordning (EU) 2017/2402 av den 12 december 2017).\n\nVinges team bestod huvudsakligen av ansvarig delägare Albert Wållgren tillsammans med biträdande juristerna Seyran Sahin, Axel Jansson, Ulf Pyk och Calle Tengwall Pagels.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-natwest-markets-n-v-med-utokning-av-vardepapperisering/","date":"2022-10-19","month":10},{"year":2022,"client":"Night Train Media","work":"Förvärv","disciplines":["Företagsbeskattning","M&A"],"title":"Vinge har biträtt Night Train Media i samband med dess förvärv av Eccho Rights","caption":"Förvärv · 19 oktober 2022","preamble":"Vinge har biträtt tyska Night Train Media GmbH, som ingår i Serafin Group, i samband med dess förvärv av Eccho Rights AB från den koreanska mediegruppen CJ ENM Co., Ltd.","body":"Eccho Rights, med huvudkontor i Stockholm, är en global innehavare och distributör av licenser för TV-serier med kontor även i Istanbul, London, Madrid och Seoul.\n\nVinges team bestod huvudsakligen av Kristian Ford, Sofie Nordgren, Carl Trolle Olson, Clara Klingspor, Hanna Jansson och Karin Gynnerstedt samt på skatt, Maria Schultzberg och Emelie Svanberg.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-night-train-media-i-samband-med-dess-forvarv-av-eccho-rights/","date":"2022-10-19","month":10},{"year":2022,"client":"Xspray Pharma","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Xspray Pharma i samband med nyemission","caption":"Kapitalanskaffning · 18 oktober 2022","preamble":"Vinge har biträtt Xspray Pharma, ett läkemedelsbolag med ett antal produktkandidater under klinisk utveckling noterat på Nasdaq Stockholm, i samband med en nyemission varigenom bolaget tillförs 100 miljoner kronor.","body":"Vinges team bestod av Dain Hård Nevonen, Joel Magnusson och Gabriel Chabo.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-xspray-pharma-i-samband-med-nyemission_/","date":"2022-10-18","month":10},{"year":2022,"client":"Cameco","work":"Förvärv","disciplines":["Arbetsrätt","EU‑ och konkurrensrätt","Corporate Commercial","Corporate Crime & Compliance","M&A","Miljörätt","Internationell handel"],"title":"Vinge har biträtt Cameco i samband med förvärvet av Westinghouse Electric Company","caption":"Förvärv · 18 oktober 2022","preamble":"Vinge har, tillsammans med Covington & Burling LLP, biträtt Cameco Corporation i samband med deras förvärv av Westinghouse Electric Company i en affär värderad till 7,875 miljarder dollar. Cameco, tillsammans med Brookfield Renewable Partners, förvärvar samtliga aktier i Westinghouse Electric Company. Vid avslutad affär kommer Camecos ägarandel uppgå till 49 procent medan Brookfield Renewables, tillsammans sina institutionella partners, ägarandel kommer att uppgå 51 procent.","body":"Westinghouse har verkat i energiindustrin i över 100 år och är idag branschledande inom tillhandahållandet av verksamhetskritiska och specialiserade tekniska lösningar, produkter och tjänster för kärnkraftssektorn. I Sverige är Westinghouse främst verksamt genom Westinghouse Electric Sweden AB och har runt 800 anställda i Sverige och en årlig svensk omsättning uppgående till över 3 miljarder kronor.\n\nCameco är en av de största globala leverantörerna av kärnbränsle, med omfattande drift av uranbrytnings- och malningsverksamhet, raffinerings- och omvandlingsanläggningar samt CANDU-bränsletillverkning för tungvattenreaktorer.\n\nBrookfield Renewable driver en av de största börsnoterade, plattformarna för förnybar energi och är en av världens största investerare inom ren energi med en sammanlagd drifts- och utvecklingskapacitet uppgående till ca 125,000 MW världen över.\n\nTransaktionens genomförande är villkorat av sedvanliga regulatoriska godkännanden.\n\nVinges team, lett av Peter Sundgren (M&A) och Johan Cederblad (Miljö och kärnkraftsreglering), inkluderade Per Kling, Gustav Wahlberg och Robin Fagerström (M&A), Sara Strandberg (Arbetsrätt), Stojan Arnerstål, Rebecka Målquist och Arvid Axelryd (IP), Hedvig Ekdahl och Mario Saad (Corporate Commercial), Anders Leissner och Victoria Gunnerek (Internationell handel) och Tove Tullberg (Compliance). Därtill bistår Daniel Wendelsson, Sebastian Örndahl och Victoria Fredén i samband med konkurrens- och FDI-anmälan.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-cameco-i-samband-med-forvarvet-av-westinghouse-electric-company/","date":"2022-10-18","month":10},{"year":2022,"client":"EQT Infrastructure","work":"Avyttring","disciplines":["Arbetsrätt","Bank och finans","Fastigheter och Entreprenad","Immaterialrätt","M&A","Corporate Crime & Compliance","Kommersiella avtal"],"title":"Vinge företräder EQT Infrastructure i samband med försäljningen av en minoritetsandel i GlobalConnect till Mubadala","caption":"Avyttring · 14 oktober 2022","preamble":"Vinge företräder EQT Infrastructure III och IV (“EQT Infrastructure”) i samband med försäljningen av en minoritetsandel i GlobalConnect (“GlobalConnect”) till Mubadala Investment Company (“Mubadala”). EQT Infrastructure har varit involverad i GlobalConnect sedan 2017 och kommer att kvarstå som största aktieägare efter transaktionens avslutande.","body":"GlobalConnect tillhandahåller fiberbaserade datakommunikations- och datacentertjänster till företag, offentliga organ och konsumenter i norra Europa. GlobalConnects infrastruktur hanterar mer än 50 procent av all genererad internettrafik i Norden via bolagets nätverk av 150 000 km fiberinfrastruktur och 35 000 m2 datacenterutrymme. GlobalConnect har cirka 1 800 anställda i regionen.\n\nGenom att välkomna Mubadala som en minoritetsinvesterare i GlobalConnect avser EQT Infrastructure att bredda GlobalConnects långsiktiga aktieägarbas och dra fördel av Mubadalas tidigare investeringserfarenhet inom datacenter- och fiber-till-hemmet-tillgångar på flera olika marknader.\n\nTransaktionen är föremål för sedvanliga villkor och godkännanden och förväntas att vara avslutad under Q1 2023.\n\nVinges team bestod av Daniel Rosvall, Maria Dahlin Kolvik, Karl Klackenberg, Desirée Hagenfeldt, Viktor Lennartsson, Nina Gransäter, Amanda Steen och Sebastian Saadieh (M&A), Lisa Hörnqvist och Mathilda Persson (Commercial Agreements), Daniel Wendelsson och Victoria Fredén (FDI), Sebastian Örndahl (Antitrust och Telecom Regulatory), Tove Tullberg (Compliance), Axel Jansson och Ida Redander (Banking and Finance), Axel Lennartsson (IP), Kristoffer Larson (Real Estate), Sara Strandberg (Employment) och Sara Dahlros Sköld, Emy Rydén, Julia Hagelberg och Christoffer Widström (VDR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-eqt-infrastructure-i-samband-med-forsaljningen-av-en-minoritetsandel-i-globalconnect-till-mubadala/","date":"2022-10-14","month":10},{"year":2022,"client":"Spring Media","work":"Samgående","disciplines":["M&A"],"title":"Vinge biträder Spring Media vid samgående med Hogmore","caption":"Samgående · 11 oktober 2022","preamble":"Vinge har biträtt Spring Media när bolaget går samman med Hogmore.","body":"Spring Media och Hogmore är bl.a. verksamma med produktion, paketering, digitala strategier och rättighetsförhandling inom området för sporträttigheter. Hogmore är verksamt Lichtenstein och Österrike och bolagets grundare kommer bli en del av Spring Medias group management.\n\nVinges team bestod av Johan Winnerblad, Clara Sohlberg och Philip Moré (M&A) och Linn Adelwald och Karl-Gustaw Tobola (Finansiering).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-spring-media-vid-samgaende-med-hogmore/","date":"2022-10-11","month":10},{"year":2022,"client":"Helix Kapital","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Helix Kapital vid investering i L5 Navigation Systems","caption":"Kapitalanskaffning · 10 oktober 2022","preamble":"Vinge har biträtt Helix Kapital i samband med att L5 Navigation Systems tar in Helix Kapital som ägarpartner för fortsatt internationell expansion. L5 Navigation Systems är ett ledande bolag inom positioneringsteknik för maskinstyrning och GNSS-mätning.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Nando Basic, Ida Redander, Robin Sultani, Emil Lindwall, Ian Jonson och Julia Löfqvist.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-helix-kapital-vid-investering-i-l5-navigation-systems/","date":"2022-10-10","month":10},{"year":2022,"client":"Sequoia","work":"Kapitalanskaffning","disciplines":["Bank och finans","M&A"],"title":"Vinge biträder Sequoia i investeringsrunda i Klarna","caption":"Kapitalanskaffning · 29 september 2022","preamble":"Vinge har biträtt Sequoia Capital Operations, LLC i en finansieringsrunda omfattande $800m i Klarna Holding AB, som efter rundan värderas till $6,7mdr.","body":"Rundan leddes av Sequoia och inkluderade bland annat befintliga investerare såsom grundarna, Bestseller, Silver Lake och Commonwealth Bank of Australia, samt de nya investerarna Mubadala Investment Company och Canada Pension Plan Investment Board.\n\nVinges team bestod av Christina Kokko, Joacim Rydergård och Vilhelm Rondahl (M&A) och Emma Stuart-Beck och Henrik Schön (Financial Services).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sequoia-i-investeringsrunda-i-klarna/","date":"2022-09-29","month":9},{"year":2022,"client":"Semcon","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Semcon i samband med budet från Ratos","caption":"Övrigt · 26 september 2022","preamble":"Vinge biträder Semcon AB (publ) med anledning av att Ratos AB har lämnat ett konkurrerande uppköpserbjudande till aktieägarna i Semcon.","body":"Erbjudandet är 157 SEK per aktie och värderar Semcon till cirka 2 844 miljoner SEK.\n\nVinges team består huvudsakligen av Anders Strid, Erik Sjöman och Edin Agic samt Anna Palmérus som biträder Semcon med konkurrensrättsliga frågor.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-semcon-i-samband-med-budet-fran-ratos/","date":"2022-09-26","month":9},{"year":2022,"client":"Nordea","work":"Offentligt uppköpserbjudande","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträdde Nordea i samband med Karo Intressenters bud på Karo Pharma","caption":"Offentligt uppköpserbjudande · 19 september 2022","preamble":"Vinge har biträtt Nordea Bank Abp, filial i Sverige, Corporate Finance i samband med uppdraget att avge en så kallad fairness opinion avseende Karo Intressenter AB:s uppköpserbjudande till aktieägarna i Karo Pharma AB.","body":"Vinges team bestod av Erik Sjöman.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-nordea-i-samband-med-karo-intressenters-bud-pa-karo-pharma/","date":"2022-09-19","month":9},{"year":2022,"client":"Vimian","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder Vimian i samband med en riktad nyemission om cirka 1 500 MSEK","caption":"Kapitalanskaffning · 16 september 2022","preamble":"Vinge företräder Vimian i samband med en riktad nyemission, varigenom bolaget tillförs cirka 1 500 MSEK före transaktionskostnader.","body":"Emissionen genomförs dels med stöd av bemyndigande, dels efter beslut från extra bolagsstämma. Bolagets aktie är upptagen till handel på Nasdaq First North Growth Market.\n\nVinges team har bestått av Dain Hård Nevonen, Linnéa Sellström, Anders Sundin Lundberg och Anna Svensson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-vimian-i-samband-med-en-riktad-nyemission-om-cirka-1-500-msek/","date":"2022-09-16","month":9},{"year":2022,"client":"Säljarna","work":"Avyttring","disciplines":["M&A"],"title":"Vinge har biträtt säljarna vid försäljningen av Conmore Ingenjörsbyrå AB","caption":"Avyttring · 15 september 2022","preamble":"Conmore Ingenjörsbyrå AB är ett teknikkonsultbolag som i mer än 30 år uppfyllt förväntningarna från stora industrikoncerner genom att tillhandahålla sin expertis inom mekanik, inbyggda system och elektronik inom fordons-, järnvägs- och energisektorerna. Förvärvaren var Astek Group.","body":"Vinges team bestod av Magnus Pauli, Johanna Hamrefält (Projektledare), Anna Palmérus och Amelia Rihs.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-saljarna-vid-forsaljningen-av-conmore-ingenjorsbyra-ab/","date":"2022-09-15","month":9},{"year":2022,"client":"Latour","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har biträtt Latour i samband vid förvärv av MAXAGV","caption":"Förvärv · 14 september 2022","preamble":"Investment AB Latour har, genom sitt helägda dotterbolag Latour Industries AB, förvärvat de två bolagen Soft Design RTS AB och atab autmationsteknik AB (gemensamt MAXAGV) från grundarna och ledningen.","body":"MAXAGV är en ledande leverantör av system med mobila robotar och mjukvara för godshantering med huvudkontor i Mölndal. Omsättningen uppgår till cirka 160 Mkr varav majoriteten är exportförsäljning.\n\nInvestment AB Latour är ett blandat investmentbolag bestående av en helägd industrirörelse samt en portfölj av börsnoterade innehav där Latour är huvudägare eller en av huvudägarna.\n\nVinges team bestod av Magnus Pauli, Petronella Hallberg, Beatrice Randow, Adrian Filipovic och Hanna Marberg.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-latour-i-samband-vid-forvarv-av-maxagv/","date":"2022-09-14","month":9},{"year":2022,"client":"Nividas","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har företrätt Nividas i en investeringsrunda","caption":"Kapitalanskaffning · 14 september 2022","preamble":"Vinge har företrätt Nividas AB när bolaget tar in kapital från Aggregate Media.","body":"Även en del befintliga investerare deltog i investeringsrundan. Nividas är ett svenskt glasögonmärke grundat 2014 med målet att sälja prisvärda, snygga glasögon i bästa möjliga kvalité.\n\nVinges team bestod av Matthias Pannier och Ellinor Wargenbrant.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-nividas-i-en-investeringsrunda/","date":"2022-09-14","month":9},{"year":2022,"client":"GeneraLife","work":"Förvärv","disciplines":["EU‑ och konkurrensrätt","M&A","Arbetsrätt","IT, Telekom och Outsourcing","Fastigheter och Entreprenad","Bank och finans","Rekonstruktioner och obestånd"],"title":"Vinge har företrätt GeneraLife i samband med dess förvärv av Liviokoncernen","caption":"Förvärv · 13 september 2022","preamble":"Vinge har företrätt GeneraLife, en av Europas största fertilitetskliniker som ägs av KKR i samband med dess förvärv av Liviokoncernen.","body":"Livio är en av de största fertilitetskliniker i Norden och har för närvarande 9 kliniker i Sverige, Norge och Island. Förvärvet omfattar även Livios egen ägg- och spermiebank, Livio Egg and Spermbank, med försäljningscenter i Danmark.\n\nVinges team har bestått av ansvarig delägare Matthias Pannier och biträdande jurister Samra Baytar, Stina Bengtsson, Olivia Belding, Elias Bohlin (M&A), Trine Osen Bergqvist, Johan Wahlbom, Jakob Jeanrond, Victoria Fredén, Alva Chambert (Konkurrens), Christoffer Nordin, Mika Jordan (Tillstånd & Avtal), Rebecka Målquist (IP), Frida Ställborn, Karolina Cohrs (Fastighet), Calle Tengwall Pagels (Bank & Finans), Gustav Lindgren (Arbetsrätt), Karolina Fuhrman (IT & GDPR) and Jessica Henning (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-generalife-i-samband-med-dess-forvarv-av-liviokoncernen/","date":"2022-09-13","month":9},{"year":2022,"client":"Swegon","work":"Förvärv","disciplines":["M&A","Fastigheter och Entreprenad"],"title":"Vinge har biträtt Swegon vid förvärv av ABC Ventilationsprodukter AB","caption":"Förvärv · 13 september 2022","preamble":"Vinge har biträtt Swegon vid förvärv av ABC Ventilationsprodukter AB, en svensk ledande aktör inom takhuvar, ventilationsgaller, spjäll och brandskyddsprodukter.","body":"ABC Ventilationsprodukter grundades 1976, har 90 anställda med huvudkontor och produktion i Borås. Nettoförsäljningen uppgick 2021 till 138 MSEK.\n\nVinges team bestod av ansvarig delägare Magnus Pauli, Johanna Hamrefält (M&A), Adam Lowenstein (Fastighet) och Fredrik Löwenclou (M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-swegon-vid-forvarv-av-abc-ventilationsprodukter-ab/","date":"2022-09-13","month":9},{"year":2022,"client":"Stanley Black & Decker","work":"Övrigt","disciplines":["Arbetsrätt","M&A","Offentlig upphandling"],"title":"Vinge har biträtt Stanley Black & Decker","caption":"Övrigt · 13 september 2022","preamble":"Vinge har biträtt Stanley Black & Decker i samband med försäljningen av dess verksamheter avseende elektroniska säkerhetslösningar (Stanley Security) till Securitas AB.","body":"Vinges team bestod av Matthias Pannier och Sofie Nordgren (M&A), Daniel Wendelsson och Victoria Fredén (Regulatory) och Daniel Melander Björner (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-stanley-black-decker/","date":"2022-09-13","month":9},{"year":2022,"client":"Axcel VI och Currentum","work":"Förvärv","disciplines":["Arbetsrätt","M&A","Bank och finans","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel VI och Currentum vid förvärv av Gullikssons El, Elkalkyl och Elprojektering samt Reglerab","caption":"Förvärv · 13 september 2022","preamble":"Vinge företräder Axcel VI och Currentum-koncernen vid förvärven av J. Gullikssons El Aktiebolag, Elkalkyl och Elprojektering i Sverige AB samt Reglerab AB.","body":"Bolagen tillhandahåller tjänster bland annat inom projektering, installation och service inom el- och byggsektorn och är verksamma i Stockholm och Mälardalen. Tillsammans omsätter bolagen årligen cirka 155 miljoner kronor och har drygt 100 medarbetare. Genom förvärven förväntas Currentum omsätta cirka 3 miljarder kronor och sysselsätta drygt 1 000 medarbetare.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Carl Fredrik Wachtmeister, Linnea Petersson och Philip Moré (M&A), Isak Willborg (Entreprenadrätt), Sara Strandberg (Arbetsrätt), Calle Tengwall Pagels (Finansiering), Frida Ställborn (Fastighetsrätt) och Anna Ekdahl Roos (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-vi-och-currentum-vid-forvarv-av-gullikssons-el-elkalkyl-och-elprojektering-samt-reglerab/","date":"2022-09-13","month":9},{"year":2022,"client":"Main Capital och Alfa eCare","work":"Förvärv","disciplines":["Arbetsrätt","M&A","Fastigheter och Entreprenad","IT, Telekom och Outsourcing"],"title":"Vinge biträder Main Capital och Alfa eCare i samband med förvärvet av Avancit AB","caption":"Förvärv · 8 september 2022","preamble":"Alfa eCare-koncernen är en erkänd och snabbt växande mjukvaruleverantör inom e-hälsobranschen som tillhandahåller lösningar åt både privata och offentliga vårdgivare i Norden.","body":"Avancit AB är en marknadsledande aktör i Sverige inom affärsutvecklande mjukvarulösningar för vårdgivare inom personlig assistans. Bolaget erbjuder tjänster till både mindre och större företag inom flertalet kompetensområden - däribland systemutveckling, implementering, support, utbildning och infrastruktur. Avancit är Alfa eCares femte tilläggsförvärv sedan 2020 då Main Capital blev majoritetsägare av gruppen.\n\nVinges team bestod av Jonas Johansson, Filip Öhrner, Per Kling, Linus Adolfsson, Sophie Böje, Jonna Skog, Sara Strandberg, Hedvig Ekdahl, Nicklas Thorgerzon och Rebecka Målquist.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-main-capital-och-alfa-ecare-i-samband-med-forvarvet-av-avancit-ab/","date":"2022-09-08","month":9},{"year":2022,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Lagercrantz Group vid förvärv av Water Proof Diving International","caption":"Förvärv · 8 september 2022","preamble":"Vinge har biträtt Lagercrantz Group vid förvärv av 93% av aktierna i Water Proof Diving International.","body":"Bolaget är en ledande leverantör av avancerade torr- och våtdräkter till professionella dykare med kunder bl.a. inom militär- och räddningstjänst.\n\nBolaget är baserat i Partille och omsätter ca. 90 MSEK med god lönsamhet.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Iiris Ikkelä, Sophie Böje, Emil Lindwall, Sam Fakhraie Ardekani samt Axel Lennartsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-vid-forvarv-av-water-proof-diving-international/","date":"2022-09-08","month":9},{"year":2022,"client":"Cinven","work":"Förvärv","disciplines":["Arbetsrätt","Bank och finans","M&A","Immaterialrätt","IT, Telekom och Outsourcing","Kommersiella avtal","EU‑ och konkurrensrätt","Försäkring"],"title":"Vinge företräder Cinven vid förvärv av Säkra","caption":"Förvärv · 6 september 2022","preamble":"Vinge har företrätt den internationella private equity-firman Cinven i samband med dess förvärv av Säkrakoncernen (”Säkra”).","body":"Säkra, med drygt 350 medarbetare på ett 60-tal orter runt om i Sverige, erbjuder skräddarsydda försäkringslösningar, tjänstepensionsupplägg samt rådgivartjänster och är en av Sveriges ledande försäkringsförmedlare. Förvärvet av Säkra är den fjärde investeringen som Cinvens första Strategic Financial Fund (”SFF”) genomför.\n\nSFF har sin grund i Cinvens ledande investeringsplattform för finansiella tjänster i Europa med en investeringsstrategi som fokuserar på områden där Cinven har utvecklat en betydande investeringsexpertis, såsom liv- och skadeförsäkring och återförsäkring, specialfinansiering med underliggande tillgångar, förmögenhetsförvaltning, försäkringsdistributörer och andra icke-kapitaltunga teknikbaserade förmedlare av finansiella tjänster.\n\nFörvärvet är villkorat av godkännanden av Finansinspektionen och Konkurrensverket.\n\nVinges team bestod huvudsakligen av Christina Kokko, Samra Baytar, Carl Fredrik Wachtmeister och Robin Fagerström (M&A), Viveka Classon och Fabian Ekeblad (Corporate Insurance), Emma Stuart-Beck, Caroline Krassén, Henrik Schön och David Flodin (Financial Services), Hedvig Ekdahl (Commercial Agreements), Kristoffer Larsson (Real Estate), Louise Brorsson Salomon, Kamyar Najmi och Ellen Flygt (Banking and Finance), Rebecka Målquist (IP), Nicklas Thorgerzon (IT och GDPR) Sara Strandberg (Employment), David Olander och Victoria Fredén (ECR) samt Emy Rydén (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-cinven-vid-forvarv-av-sakra/","date":"2022-09-06","month":9},{"year":2022,"client":"Swisscom Ventures","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder Swisscom Ventures i samband med investering i Billogram AB","caption":"Kapitalanskaffning · 2 september 2022","preamble":"Vinge biträder Swisscom Ventures i samband med deras MEUR 10 investering i Billogram AB, den svenska fakturerings- och betalningsplattform.","body":"Vinges team består av Ulrich Ziche, Johan Larsson, Ebba Svenburg och Karolina Fuhrman.\n\nLäs bolagets pressrelease>>","href":"https://www.vinge.se/uppdrag/vinge-bitrader-swisscom-ventures-i-samband-med-investering-i-billogram-ab/","date":"2022-09-02","month":9},{"year":2022,"client":"Lantmännen","work":"Avyttring","disciplines":["Arbetsrätt","Kommersiella avtal","M&A"],"title":"Vinge har företrätt Lantmännen i samband med försäljningen av Lantmännen Agrovärme","caption":"Avyttring · 2 september 2022","preamble":"Vinge har företrätt Lantmännen i samband med försäljningen av Lantmännen Agrovärme AB till Solör Bioenergi.","body":"Lantmännen Agrovärme producerar, distribuerar och säljer fjärrvärme till cirka 1100 kunder från 19 anläggningar i södra och mellersta Sverige. Lantmännen Agrovärme har som strategi att bidra till en cirkulär ekonomi. Cirka 95 procent av fjärrvärmen från Lantmännen Agrovärme kommer i huvudsak från förbränning av lokalt framtagna biobränslen, såsom flis, energiskog, träpellets och spill från jordbruket.\n\nVinges team bestod av bland andra Christina Kokko, Peter Sundgren, Ellinor Wargenbrant och Elsie Nassar (M&A), Eva Fredriksson (Kommersiella avtal), Sara Strandberg (Arbetsrätt) och Julia Hagelberg (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-lantmannen-i-samband-med-forsaljningen-av-lantmannen-agrovarme/","date":"2022-09-02","month":9},{"year":2022,"client":"Xintela","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Xintela","caption":"Övrigt · 1 september 2022","preamble":"Vinge biträder Xintela AB (publ) i samband med budpliktsbudet från Flerie Invest AB.","body":"Vinges team består av Christian Lindhé, Erik Sjöman och Astrid Isberg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-xintela/","date":"2022-09-01","month":9},{"year":2022,"client":"Altor","work":"Kapitalanskaffning","disciplines":["Kommersiella avtal","Bank och finans","Corporate Crime & Compliance","M&A","Arbetsrätt","Immaterialrätt","Miljörätt","Fastigheter och Entreprenad"],"title":"Vinge företräder Altor i samband med investering i H2 Green Steel","caption":"Kapitalanskaffning · 30 augusti 2022","preamble":"Vinge företräder Altor Fund V i samband med dess investering i H2 Green Steel. Investeringen har genomförts i samband med H2 Green Steels serie B-runda om totalt ca 190 miljoner euro. Deltagande investerare var, utöver Altor, bland andra AMF, GIC, Swedbank Robur Alternative Equity, FAM och IMAS Foundation.","body":"H2 Green Steel grundades 2020 med ambitionen att påskynda utfasningen av fossila bränslen inom stålindustrin med hjälp av miljövänligt producerad vätgas. Stål, som är en av världens största utsläppare av koldioxid, är företagets första affärsområde. H2 Green Steel har sitt huvudkontor i Stockholm och företaget utvecklar sitt första gröna stålverk i Boden.\n\nVinges team bestod huvudsakligen av Christina Kokko, Johan Larsson, Carl Fredrik Wachtmeister, Linus Adolfsson (M&A), Lisa Hörnqvist, Elis Allmark (Commercial Agreements), Johan Cederblad (Environment), Kristoffer Larsson (Real Estate), Julia Löfqvist (Compliance), Kamyar Najmi (Banking and Finance), Axel Lennartsson (IP), Ebba Svenburg (Employment), Sara Dahlros Sköld och Julia Hagelberg (projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-altor-i-samband-med-investering-i-h2-green-steel/","date":"2022-08-30","month":8},{"year":2022,"client":"Semcon","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Semcon i samband med budet från Etteplan","caption":"Övrigt · 23 augusti 2022","preamble":"Vinge biträder Semcon AB (publ) med anledning av att Etteplan Oyj har lämnat ett uppköpserbjudande till aktieägarna i Semcon. Erbjudandet är 149 SEK per aktie och värderar Semcon AB till cirka 2 699 miljoner SEK.","body":"Vinges team består huvudsakligen av Anders Strid, Erik Sjöman och Edin Agic samt Anna Palmérus som biträder Semcon med konkurrensrättsliga frågor.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-semcon-i-samband-med-budet-fran-etteplan/","date":"2022-08-23","month":8},{"year":2022,"client":"Zington","work":"Avyttring","disciplines":[],"title":"Vinge biträder vid försäljning av Zington","caption":"Avyttring · 8 augusti 2022","preamble":"Vinge har biträtt Sobro och övriga aktieägare vid försäljning av Zington till VASS Group, en ledande aktör inom digital transformation med huvudkontor i Spanien.","body":"Med bas i Stockholm levererar Zington affärskritiska digitala lösningar och expertkunskap till flera av Sveriges största företag. Zington omsätter cirka 370 MSEK och har 230 medarbetare.\n\nTransaktionen är villkorad av berörda konkurrensmyndigheters godkännande.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Carl Sander, Elsie Nassar och Ellinor Wargenbrant.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-zington/","date":"2022-08-08","month":8},{"year":2022,"client":"Active Biotechs","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge biträder i Active Biotechs företrädesemission","caption":"Kapitalanskaffning · 5 augusti 2022","preamble":"Active Biotech AB (publ) (Nasdaq Stockholm) genomför en nyemission med företrädesrätt för aktieägarna om cirka 55 MSEK.","body":"Vinge biträder Active Biotech. Vinges team består i huvudsak av Christian Lindhé, Erik Sjöman, Astrid Isberg och Johanne Örnfeldt Svensson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-i-active-biotechs-foretradesemission/","date":"2022-08-05","month":8},{"year":2022,"client":"Vimian Group","work":"Övrigt","disciplines":["M&A"],"title":"Vinge acted as advisor to Vimian Group (including VetFamily) on the acquisition of Heiland GmbH","caption":"Övrigt · 2 augusti 2022","preamble":"Heiland.com is a leading online ordering platform offering veterinary pharmaceuticals, consumables, nutrition and more to veterinary clinics across Germany.","body":"The Vinge team advising Vimian Group includes Counsel Ulrich Ziche, Senior Associate Sebastian Örndahl and paralegal Julia Hagelberg. Local counsel advice was provided by Möhrle Happ Luther, Hamburg.\n\nMore information on the transaction","href":"https://www.vinge.se/uppdrag/vinge-acted-as-advisor-to-vimian-group-including-vetfamily-on-the-acquisition-of-heiland-gmbh/","date":"2022-08-02","month":8},{"year":2022,"client":"Grundarna av Future Media Group","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder grundarna av Future Media Group vid försäljning till Caybon","caption":"Kapitalanskaffning · 22 juli 2022","preamble":"Vinge företräder grundarna Rikard Virta, Linus Wennerström och Johan Oscarsson samt övriga ägare vid försäljningen av Future Media Group AB till Caybon.","body":"Future Media Group är specialister på att hjälpa medieägare och tillväxtbolag att driva nya intäkter genom affärsutveckling, produktutveckling och försäljning. I nära samarbete med sina partners utvecklar man nya annonsformat, medielösningar och marknadsföringskoncept, och tar ut lösningarna till rätt målgrupp via sina olika säljorganisationer, specialiserade på olika typer av produkter och kundsegment.\n\nBland Future Media Groups nuvarande partners finns dels större mediehus såsom Bonnier och Stampen, samt nischade aktörer såsom Preglife (Nordens ledande gravid-app) och den digitala veterinär-tjänsten Firstvet. Bolaget har kontor i Stockholm och Oslo och har drygt 100 medarbetare.\n\nVinges team har främst bestått av Jonas Johansson, Carl Sander, Ellinor Wargenbrant och Linus Adolfsson (M&A), samt Sara Dahlros Sköld och Ellinore Boström Andersson (VDR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-grundarna-av-future-media-group-vid-forsaljning-till-caybon/","date":"2022-07-22","month":7},{"year":2022,"client":"Oncopeptides","work":"Kapitalanskaffning","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge företräder Oncopeptides i samband med riktad nyemission","caption":"Kapitalanskaffning · 15 juli 2022","preamble":"Styrelsen för Oncopeptides har beslutat att genomföra en riktad nyemission, varigenom Oncopeptides tillförs cirka 435,6 MSEK före transaktionskostnader. Priset per aktie i emissionen motsvarar stängningskursen på Nasdaq Stockholm per dagen för emissionen.","body":"Emissionen riktades till ett antal utvalda internationella och svenska institutionella investerare samt investerare som är specialiserade på life science.\n\nOncopeptides är ett biotechbolag inriktat på forskning och utveckling av läkemedel för svårbehandlade hematologiska sjukdomar. Bolaget använder sin patentskyddade PDC-plattform för att utveckla peptidlänkade läkemedel som snabbt och selektivt levererar cellgifter in i cancerceller. Bolagets aktie är upptagen till handel på Nasdaq Stockholm.\n\nVinges team har bestått av Dain Hård Nevonen och Linnéa Sellström (aktiemarknad), och Louise Brorsson Salomon, Arvid Weimers och Kamyar Najmi (finansiering).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-oncopeptides-i-samband-med-riktad-nyemission-4/","date":"2022-07-15","month":7},{"year":2022,"client":"Retune och Tillmobil","work":"Samgående","disciplines":["M&A"],"title":"Vinge biträder vid samgående mellan Retune och Tillmobil","caption":"Samgående · 15 juli 2022","preamble":"Vinge har biträtt Sobro och grundarna av Retune vid etablering av en ny bolagsgrupp som kombinerar Retunes tjänsteutbud inom molnbaserad infrastruktur, säkerhet och konsulttjänster med Tillmobils tjänster inom telefoni, växeltjänster och hårdvara.","body":"Gruppen innefattar även bolaget Reswitch, som driver en modern molnbaserad växellösning. Omsättningen innevarande år beräknas till ca 170 MSEK med strax över 100 medarbetare.\n\nVinges team bestod i huvudsak av Johan Winnerblad, Eléonore Friberg, Michella Lina Said, Lisa Hörnqvist, Elin Broman, Michael Montner och Ian Jonson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-samgaende-mellan-retune-och-tillmobil/","date":"2022-07-15","month":7},{"year":2022,"client":"CityGlas","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljning av CityGlas","caption":"Avyttring · 14 juli 2022","preamble":"Corteco har förvärvat CityGlas, som erbjuder glas- och fönsterentreprenader. Celero Capital har etablerat Corteco i syfte att konsolidera den nordiska marknaden för renovering och underhåll av fastighetens yttre skal.","body":"Vinge, genom Johan Winnerblad, biträder ägarna i CityGlas.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-cityglas/","date":"2022-07-14","month":7},{"year":2022,"client":"Axcel","work":"Förvärv","disciplines":["Arbetsrätt","Kommersiella avtal","EU‑ och konkurrensrätt","IT, Telekom och Outsourcing","M&A","Corporate Crime & Compliance","Fastigheter och Entreprenad"],"title":"Vinge företräder Axcel vid förvärv av Oral Care","caption":"Förvärv · 14 juli 2022","preamble":"Vinge företräder Axcel vid förvärv av Oral Care, en ledande vårdgivare inom tandvård i Sverige och Norge.","body":"Oral Care grundades 1989 i Stockholm, Sverige och var en pionjär i svensk mobil tandvård, som omfattar behandling av äldre och funktionshindrade patienter i deras egna hem, typiskt sett vårdhem och äldreboenden. Under 2015 utnyttjade Oral Care sin ledande mobila verksamhet för att etablera kliniker i Sverige. Sedan dess har företaget utökat sin kliniknärvaro genom att förvärva och integrera välpresterande kliniker i Sverige och Norge. Oral Care driver idag 12 kliniker i Sverige och två i Norge. Vidare är Oral Care Sveriges största privata leverantör av mobil tandvård, verksam i sju regioner i mellersta och södra Sverige.\n\nTransaktionen är villkorad av tillämplig konkurrensmyndighets godkännande.\n\nVinges team bestod av Christina Kokko, Johanna Wiberg, Elsie Nassar, Nando Basic och Ida Redander (M&A), Christoffer Nordin (Kommersiella avtal och Tillstånd), Mikael Ståhl, Linn Adelwald och Ellen Flygt (Bank- och finans), Frida Ställborn (Fastighetsrätt och Miljö), Julia Löfqvist (Regelefterlevnad), Lina André (Arbetsrätt), Nicklas Thorgerzon (IT och GDPR), Michael Montner och Ian Jonsson (Immaterialrätt), Johan Wahlbom och Victoria Fredén (Konkurrensanmälan) och Jessica Henning (Projekt- och VDR-assistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-vid-forvarv-av-oral-care/","date":"2022-07-14","month":7},{"year":2022,"client":"Marcegaglia Steel Group","work":"Förvärv","disciplines":["Arbetsrätt","EU‑ och konkurrensrätt","M&A"],"title":"Vinge företräder Marcegaglia Steel Group i samband med förvärv","caption":"Förvärv · 13 juli 2022","preamble":"Vinge företräder Marcegaglia Steel Group, en ledare inom stålbearbetningssektorn, i samband med förvärv av majoriteten av Outokumpus Long Products-verksamhet för 228 million euros.","body":"Transaktionen är villkorad berörda konkurrensmyndigheters godkännande och kräver intern omstrukturering innan tillträdet.\n\nVinges team bestod huvudsakligen av Sofie Nordgren och Lena Westberg (M&A), Pär Remnelid (Konkurrensrätt) och Johan Cederblad (Miljörätt).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-marcegaglia-steel-group-i-samband-med-forvarv/","date":"2022-07-13","month":7},{"year":2022,"client":"Odevo","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har företrätt Odevo, ett ledande mjukvaru- och serviceföretag som riktar sig till fastighetsmarknaden, i samband med dess förvärv av Trinity Property Group.","caption":"Förvärv · 13 juli 2022","preamble":"Vinge har varit svenskt ombud och tillsammans med Herbert Smith Freehills biträtt Odevo i samband med förvärvet.","body":"Vinges team bestod av bland andra av Jonas Bergström, Johanna Wiberg och Linnea Petersson (M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-odevo-ett-ledande-mjukvaru-och-serviceforetag-som-riktar-sig-till-fastighetsmarknaden-i-samband-med-dess-forvarv-av-trinity-property-group/","date":"2022-07-13","month":7},{"year":2022,"client":"Studentbostäder","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Studentbostäder i Norden AB (publ) i samband med en riktad nyemission","caption":"Kapitalanskaffning · 13 juli 2022","preamble":"Vinge har biträtt Studentbostäder i Norden i samband med en riktad nyemission varigenom bolaget tillförs 125 miljoner kronor före emissionskostnader.","body":"Vinges team bestod av Jesper Schönbeck, Joel Wahlberg och Johannes Akyol.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-studentbostader-i-norden-ab-publ-i-samband-med-en-riktad-nyemission-1/","date":"2022-07-13","month":7},{"year":2022,"client":"Brunswick Real Estate Capital","work":"Finansiering","disciplines":["Bank och finans"],"title":"Vinge har biträtt Brunswick Real Estate Capital i samband med fastighetsfinansiering av Nyfosa om cirka 1,7 miljarder kronor","caption":"Finansiering · 12 juli 2022","preamble":"Vinge har biträtt Brunswick Real Estate Capital i samband med ingåendet av ett låneavtal om cirka 1,7 miljarder kronor, i syfte att refinansiera Nyfosas fastighetsportfölj ”Svea Real”. Fastighetsportföljen består av 36 fastigheter runt om i Sverige.","body":"Vinges team bestod av Mikael Ståhl, Arvid Weimers, Jolinn Uhlin och Ellen Flygt.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-brunswick-real-estate-capital-i-samband-med-fastighetsfinansiering-av-nyfosa-om-cirka-1-7-miljarder-kronor/","date":"2022-07-12","month":7},{"year":2022,"client":"Moank","work":"Kapitalanskaffning","disciplines":["Bank och finans"],"title":"Vinge har biträtt Moank i samband med emission av primärkapitaltillskott om 150 miljoner SEK","caption":"Kapitalanskaffning · 12 juli 2022","preamble":"Vinge har biträtt fintech-bolaget Credit Opportunity One AB (publ) (u.n.ä.t. Moank Fintech Group AB (publ)) (”Bolaget”) i samband med dess emission av primärkapitaltillskott (AT1) om 150 miljoner SEK för att optimera sin kapitalstruktur.","body":"Emissionen sker i form av skuldinstrument med automatisk nedskrivning av dess nominella belopp om Bolagets kärnprimärkapitalkvot faller under en viss nivå. Instrumenten kommer att noteras på Nasdaq First North Bond Market.\n\nVinges team bestod av Albert Wållgren, Arvid Weimers och Felix Möller.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-moank-i-samband-med-emission-av-primarkapitaltillskott-om-150-miljoner-sek/","date":"2022-07-12","month":7},{"year":2022,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Lagercrantz Group vid förvärv av Stegborgs EL-evator","caption":"Förvärv · 5 juli 2022","preamble":"Lagercrantz Group AB har förvärvat Stegborgs EL-evator AB, som erbjuder produkter och lösningar för renovering och ombyggnation av hissar.","body":"Vinge, genom Johan Winnerblad, biträder Lagercrantz Group.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-vid-forvarv-av-stegborgs-el-evator/","date":"2022-07-05","month":7},{"year":2022,"client":"Bostadsbyggrätt","work":"Avyttring","disciplines":["Fastigheter och Entreprenad"],"title":"Platzers försäljning av bostadsbyggrätt i Gamlestadens Fabriker till JM","caption":"Avyttring · 5 juli 2022","preamble":"Vinge biträdde Platzer när försäljningen av en bostadsbyggrätt i Gamlestadens fabriker till JM genomfördes. Affären omfattar 5 000 kvm markareal med möjlig byggrätt på 26 300 kvm.","body":"Försäljningen skedde till ett överenskommer fastighetsvärde om 158 mkr. På området avser JM utveckla cirka 330 bostäder. Affären är ett led i utvecklingen av området Gamlestaden i Göteborg.\n\nFrån Vinges sida medverkade främst Olof Jisland och Kristoffer Larsson.","href":"https://www.vinge.se/uppdrag/platzers-forsaljning-av-bostadsbyggratt-i-gamlestadens-fabriker-till-jm/","date":"2022-07-05","month":7},{"year":2022,"client":"Ikano Bostad","work":"Övrigt","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge biträder Ikano Bostad i fastighetsaffärer med Wallenstam","caption":"Övrigt · 1 juli 2022","preamble":"Wallenstam köper ett stadsnära projekt i Årstaberg, Stockholm, av Ikano Bostad för 750 miljoner kronor. I samband med affären säljer Wallenstam också en portfölj med 28 bostadsfastigheter i Göteborg och Partille till Ikano Bostad för 1.360 miljoner kronor.","body":"Vinge har bistått Ikano Bostad i båda affärerna genom Niclas Winnberg, Assur Badur, Frida Ställborn och Karolina Cohrs.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ikano-bostad-i-fastighetsaffarer-med-wallenstam/","date":"2022-07-01","month":7},{"year":2022,"client":"Komatsu","work":"Förvärv","disciplines":["Arbetsrätt","Corporate Crime & Compliance","Immaterialrätt","M&A","Fastigheter och Entreprenad","Bank och finans"],"title":"Vinge företräder Komatsu i samband med förvärv av Bracke Forest AB","caption":"Förvärv · 1 juli 2022","preamble":"Vinge företräder Komatsu Ltd. och dess dotterbolag Komatsu Forest AB i samband med förvärv av Bracke Forest AB, ett bolag som utvecklar och tillverkar markberedningsutrustning och produkter för mekaniserad skogsplantering.","body":"Vinges team bestod huvudsakligen av Jonas Johansson, Carl Fredrik Wachtmeister och Philip Moré (M&A), Johan Cederblad (Environment), Ulf Pyk (Real Estate och Banking & Finance), Isabell Nielsen, Lisa Hörnqvist och Karolina Fuhrman (Commercial Agreements, IT och GDPR), Michael Montner och Ian Jonson (IP), Ebba Svenburg (Employment), Tove Tullberg (Compliance) samt Emy Rydén (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-komatsu-i-samband-med-forvarv-av-bracke-forest-ab/","date":"2022-07-01","month":7},{"year":2022,"client":"Lagercrantz Group","work":"Förvärv","disciplines":["Kapitalmarknad och publik M&A","M&A","Miljörätt"],"title":"Vinge biträder Lagercrantz Group vid förvärv av PcP Corporation","caption":"Förvärv · 30 juni 2022","preamble":"Vinge har biträtt Lagercrantz Group vid förvärv av 95% av aktierna i den danska koncernen PcP Corporation A/S, ett ledande produktbolag med innovativa, högkvalitativa och kundanpassade säkerhetslösningar. Förvärvet genomfördes till ett totalt rörelsevärde (enterprise value) om ca 500 milj kr.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Jesper Schönbeck, Amanda Knutsson och Johan Cederblad.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lagercrantz-group-vid-forvarv-av-pcp-corporation/","date":"2022-06-30","month":6},{"year":2022,"client":"SBC Sveriges BostadsrättsCentrum","work":"Förvärv","disciplines":["Arbetsrätt","Företagsbeskattning","M&A","Corporate Commercial"],"title":"Vinge har företrätt SBC Sveriges BostadsrättsCentrum i dess förvärv av Mediator AB","caption":"Förvärv · 30 juni 2022","preamble":"Vinge har företrätt SBC Sveriges BostadsrättsCentrum, en helhetsleverantör inom bostadsrätts- och fastighetsförvaltning, i samband med dess förvärv av fastighetsförvaltningsbolaget Mediator AB.","body":"Vinges team bestod av bland andra Jonas Bergström, Johanna Wiberg, Olivia Belding, Victor Ericsson och Emelie Svanberg (Skatt), Emil Lindwall (Arbetsrätt), Mika Jordan (Corporate Commercial) samt Emy Rydén (VDR).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-sbc-sveriges-bostadsrattscentrum-i-dess-forvarv-av-mediator-ab/","date":"2022-06-30","month":6},{"year":2022,"client":"Cantargia","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder Cantargia i samband med företrädesemission","caption":"Kapitalanskaffning · 30 juni 2022","preamble":"Vinge företräder Cantargia AB (publ) i samband med en fullt garanterad företrädesemission om cirka 250 miljoner kronor.","body":"Vinges team består av Christian Lindhé, Erik Sjöman, Martin Svanberg och Alice Clarin.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-cantargia-i-samband-med-foretradesemission/","date":"2022-06-30","month":6},{"year":2022,"client":"Mentimeter","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","M&A"],"title":"Vinge företräder Mentimeter i samband med en private placement","caption":"Övrigt · 23 juni 2022","preamble":"Vinge har företrätt Mentimeter AB (publ) i samband med en private placement om cirka 432 miljoner kronor till ett antal nya investerare och befintliga ägare.","body":"Vinges team bestod huvudsakligen av David Andersson, Jonas Bergström, Maria Dahlin Kolvik, William Kåge, Amanda M Johansson och Annie Fällström.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-mentimeter-i-samband-med-en-private-placement/","date":"2022-06-23","month":6},{"year":2022,"client":"Goldman Sachs","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder Goldman Sachs, J.P. Morgan, Nordea, Morgan Stanley och DNB Markets i samband med Millicoms företrädesemission","caption":"Kapitalanskaffning · 23 juni 2022","preamble":"Vinge företräder Goldman Sachs International, J.P. Morgan Securities plc, Nordea Bank Abp, filial i Sverige (Joint Global Coordinators och Joint Bookrunners), DNB Markets, en del av DNB Bank ASA, filial Sverige och Morgan Stanley & Co. International plc (Joint Bookrunners) i samband med Millicom International Cellular S.A.s företrädesemission om cirka 7,5 miljarder kronor före emissionskostnader.","body":"Millicoms aktier är, genom depåbevis, noterade på Nasdaq Stockholm. Millicoms aktier är direktnoterade på Nasdaq Stock Market’s Global Select Market i USA.\n\nVinges team består i huvudsak av David Andersson, William Kåge, Michaela Ådén och Erik Sjöman.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-goldman-sachs-j-p-morgan-nordea-morgan-stanley-och-dnb-markets-i-samband-med-millicoms-foretradesemission/","date":"2022-06-23","month":6},{"year":2022,"client":"SEB","work":"Kapitalanskaffning","disciplines":["IT, Telekom och Outsourcing","M&A"],"title":"Vinge biträder SEB vid samarbete med och investering i Leneo","caption":"Kapitalanskaffning · 20 juni 2022","preamble":"Vinge har biträtt SEB när man inleder strategiskt samarbete med och genom SEB Venture Capital går in som delägare i det danska techbolaget Leneo. Leneo har utvecklat en plattform, som hjälper företag att gå över till nya affärsmodeller, där de i stället för att sälja produkter säljer en tjänst, där produkten är inkluderad tillsammans med kompletterande tjänster.","body":"Vinges team bestod i huvudsak av Eva Fredrikson, Johan Winnerblad, Lisa Hörnqvist, Trine Osen Bergqvist och Carl Fredrik Wachtmeister.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-seb-vid-samarbete-med-och-investering-i-leneo/","date":"2022-06-20","month":6},{"year":2022,"client":"Ernström Ventures och Nicklas Storåkers","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Ernström Ventures och Nicklas Storåkers i samband med investering i Lysa","caption":"Kapitalanskaffning · 16 juni 2022","preamble":"Vinge har biträtt Ernström Ventures och Nicklas Storåkers i samband med att Lysa genomför en nyemission om 350 miljoner kronor. Lysa är en automatisk sparrobottjänst och det nya kapitalet ska användas för fortsatt internationell expansion.","body":"Vinges team bestod av Johan Larsson.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ernstrom-ventures-och-nicklas-storakers-i-samband-med-investering-i-lysa/","date":"2022-06-16","month":6},{"year":2022,"client":"FCG","work":"Övrigt","disciplines":["EU‑ och konkurrensrätt","M&A","Kapitalmarknad och publik M&A"],"title":"Vinge biträder FCG i budet på Transcendent Group","caption":"Övrigt · 15 juni 2022","preamble":"FCG Holding Sverige AB har lämnat ett rekommenderat kontant uppköpserbjudande till aktieägarna i Transcendent Group AB (publ). Erbjudandets värde uppgår till cirka 240 miljoner kronor. Vinge biträder FCG.","body":"Vinges team består av Jesper Schönbeck, Sofie Bjärtun, Anders Sundin Lundberg (Kapitalmarknad och publik M&A), Jonas Bergström, Johanna Wiberg, Amanda Steen (M&A) och Johan Wahlbom (Konkurrensrätt).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-fcg-i-budet-pa-transcendent-group/","date":"2022-06-15","month":6},{"year":2022,"client":"King","work":"Förvärv","disciplines":["Arbetsrätt","M&A","Företagsbeskattning","Bank och finans","IT, Telekom och Outsourcing","Kommersiella avtal"],"title":"Vinge har företrätt King i samband med förvärv av Peltarion AB","caption":"Förvärv · 15 juni 2022","preamble":"Vinge har företrätt King i samband med förvärv av leverantören av operationella AI-plattformar, Peltarion AB.","body":"Vinges team bestod av bland andra Ulrich Ziche, Isabelle Wållgren och Robin Fagerström (M&A), Åsa Gotthardsson, Ebba Svenburg och Emil Lindwall (Employment), Alexander Lindberg (IP/IT/GDPR), Isabell Nielsen och Mario Saad (Commercial Agreements), Axel Jansson och Nour Makie (Banking and Finance), Maria Schultzberg (Tax) samt Julia Hagelberg and Sara Dahlros Sköld (projekt assistenter).\n\nFör mer information om transaktionen se klientens pressmeddelande","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-king-i-samband-med-forvarv-av-peltarion-ab/","date":"2022-06-15","month":6},{"year":2022,"client":"Klaravik","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Klaravik vid förvärvet av Dansk Aktions Service ApS och Nordisk Logistik Partner ApS från NLP Group Holding ApS.","caption":"Förvärv · 13 juni 2022","preamble":"Klaravik är en ledande marknadsplats för begagnade maskiner inom entreprenad, lantbruk, tunga fordon och bygg och har ca 190 anställda med huvudkontor i Karlstad.","body":"Vinges team bestod huvudsakligen av Jonas Bergström, Joacim Rydergård, Per Kling och Olivia Belding (M&A).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-klaravik-vid-forvarvet-av-dansk-aktions-service-aps-och-nordisk-logistik-partner-aps-fran-nlp-group-holding-aps/","date":"2022-06-13","month":6},{"year":2022,"client":"Trill Impact och ID North","work":"Förvärv","disciplines":["Arbetsrätt","Kommersiella avtal","IT, Telekom och Outsourcing","M&A","Fastigheter och Entreprenad"],"title":"Vinge företräder Trill Impact och ID North i samband med förvärv av Pulsen Integrations IAM-verksamhet","caption":"Förvärv · 10 juni 2022","preamble":"Vinge företräder Trill Impact och dess portföljbolag ID North i samband med förvärvet av Pulsen Integrations verksamhet inom identitets- och behörighetshantering (IAM).","body":"Totalt handlar det om 35 medarbetare från Pulsen Integration i Sverige och Finland som blir en del av ID North, som är verksamt inom IAM och cybersäkerhet, och tillhandahåller konsulttjänster samt återförsäljer och utvecklar IT-produkter med bas i Stockholm. Samtidigt går Pulsen Group in som delägare i moderbolaget European ID Security, där ID North och Arctic Group ingår. Efter transaktionen består ID North av 65 medarbetare i Sverige och Finland.\n\nVinges team bestod huvudsakligen av Christina Kokko, Matthias Pannier, Samra Baytar, Nina Gransäter, Linus Adolfsson (M&A), Isabell Nielsen, Jolene Reimerson, Lisa Hörnqvist, Karolina Fuhrman (Commercial Agreements, IT & GDPR), Åsa Gotthardsson, Emil Lindwall (Employment), Arvid Axelryd (IP), Frida Ställborn (Real Property), Ulf Pyk (Banking and Finance), Ellinore Boström Andersson och Ellinor Gyllenhammar (projektassistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-trill-impact-och-id-north-i-samband-med-forvarv-av-pulsen-integrations-iam-verksamhet/","date":"2022-06-10","month":6},{"year":2022,"client":"Procuritas","work":"Förvärv","disciplines":["Immaterialrätt","M&A","Bank och finans","Arbetsrätt","Offentlig upphandling","IT, Telekom och Outsourcing"],"title":"Vinge företräder Procuritas vid förvärvet av We Select","caption":"Förvärv · 9 juni 2022","preamble":"Vinge företräder Procuritas Capital Investors i samband med förvärvet av en majoritetsandel i The We Select Company AB (\"We Select\"), en snabbväxande digital rekryteringsplattform. Nyckelpersoner inom bolagets ledning kommer att behålla en betydande ägarandel efter transaktionen.","body":"We Select grundades 2011 som ett traditionellt rekryteringsföretag. Efter att ha lanserat sin digitala rekryteringsplattform 2016 förändrade företaget snabbt sin affärsmodell och fokuserade helt på det snabbt växande rekryteringssegmentet - sociala medier. We Select hjälper företag att attrahera och anställa topptalanger genom att kombinera strategisk Employer Branding, datadriven jobbannonsering och automatisk kandidathantering i en smart plattform.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Carl Sander, Linus Adolfsson (M&A), Seyran Sahin, Karl-Gustaw Tobola (bank och finans), Elin Broman (arbetsrätt), Arvid Axelryd, Anna Högsten (IP), Lisa Hörnqvist (IT & GDPR), Kristoffer Sällfors (offentlig upphandling) och Anna Ekdahl Roos (projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-procuritas-vid-forvarvet-av-we-select/","date":"2022-06-09","month":6},{"year":2022,"client":"Del av Arendal","work":"Avyttring","disciplines":["Fastigheter och Entreprenad"],"title":"Platzers försäljning av del av Arendal till Göteborgs Hamn","caption":"Avyttring · 9 juni 2022","preamble":"Vinge biträdde Platzer när försäljningen av en del av området Arendal (108 000 kvm mark och 69 000 kvm vattenareal) till Göteborgs Hamn genomfördes.","body":"Fastighetsvärdet var 475 mkr. Affären möjliggör flytten av färjerederiet Stena Lines Tysklands- och Danmarksterminaler från centrala Göteborg till Arendal på Hisingssidan. Kommunen planerar att på den frigjorda delen av älvstranden i centrala Göteborg utveckla en tät blandstad.\n\nFrån Vinge medverkade Olof Jisland och Kristoffer Larsson.","href":"https://www.vinge.se/uppdrag/platzers-forsaljning-av-del-av-arendal-till-goteborgs-hamn/","date":"2022-06-09","month":6},{"year":2022,"client":"Klaravik","work":"Avyttring","disciplines":["IT, Telekom och Outsourcing","M&A","EU‑ och konkurrensrätt"],"title":"Vinge biträder vid försäljningen av Klaravik","caption":"Avyttring · 8 juni 2022","preamble":"Vinge biträder säljaren vid försäljningen av Klaravik till TBAuctions.","body":"Klaravik är en ledande marknadsplats för begagnade maskiner inom entreprenad, lantbruk, tunga fordon och bygg och har ca 190 anställda med huvudkontor i Karlstad.\n\nTBAuctions är en ledande auktionsplattform och marknadsplats för begagnade och andrahandsvaror, verksamma genom varumärkena: Troostwijk Auctions, BVA Auctions, Vavato, British Medical Auctions, Auksjonen och PS Auctions.\n\nVinges team bestod huvudsakligen av Jonas Bergström, Joacim Rydergård, Per Kling och Olivia Belding (M&A), Marcus Glader (Konkurrensrätt), Malin Malm Waerme och Mathilda Persson (IP och IT) samt Anna Ekdahl Roos och Christoffer Widström (VDR).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljningen-av-klaravik/","date":"2022-06-08","month":6},{"year":2022,"client":"SAF-HOLLAND","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder SAF-HOLLAND i budet på Haldex","caption":"Övrigt · 8 juni 2022","preamble":"SAF-HOLLAND SE har lämnat ett rekommenderat kontanterbjudande till aktieägarna i Haldex AB (publ). Erbjudandet värderar samtliga utestående aktier i Haldex till cirka 3,2 miljarder kronor. Vinge biträder SAF-HOLLAND.","body":"Vinges team består av Erik Sjöman,Martin Svanberg och Linn Adelwald.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-saf-holland-i-budet-pa-haldex_/","date":"2022-06-08","month":6},{"year":2022,"client":"Cinven och Novo Holdings","work":"Avyttring","disciplines":["Arbetsrätt","Bank och finans","Corporate Commercial","M&A","IT, Telekom och Outsourcing","EU‑ och konkurrensrätt","Kommersiella avtal"],"title":"Vinge företräder Cinven och Novo Holdings vid försäljningen av Envirotainer","caption":"Avyttring · 7 juni 2022","preamble":"Vinge har företrätt den internationella private equity-firman Cinven och det danska life science investmentbolaget Novo Holdings vid försäljningen av Envirotainer Holding AB till EQT X Fund och Mubadala Investment Company, till en värdering på ca 2,8 miljarder euro. Vinge samarbetade med Clifford Chance.","body":"Envirotainer utvecklar, tillverkar och leasar temperaturkontrollerade kylcontainrar för flygtransport av mediciner och andra biofarmaprodukter. Bolaget grundades 1985 i Stockholm och idag är utveckling, tillverkning och högkvarter belägna i Stockholmsområdet. Med en global närvaro med ca 375 anställda i 20 länder och en flotta på ca 6 700 containrar är Envirotainer marknadsledande inom flygtransport av temperaturkänsliga läkemedel.\n\nVingeteamet bestod huvudsakligen av Christina Kokko, Samra Baytar, Vilhelm Rondahl, Gustav Persson och Ida Redander (M&A), Trine Osen Bergqvist och Ebba Thoms (EU, Competition & Regulatory), Victoria Gunnerek (Customs), Linn Adelwald (Bank & finans), Isabell Nielsen och Sam Fakhraie Ardekani (Corporate Commercial), Sara Strandberg, Veronika Garemark, Emil Lindvall och Tove Tullberg (Employment & Corporate Crime), Kristoffer Larson (Fastighet), Axel Lennartsson och Rebecca Målquist (IP), Nicklas Thorgerzon (GDPR), Martin Boström (IT), Johan Cederblad och Lina Österberg (Permits & Environment), Viktoria Owetz Leyva, Sara Dahlros Sköld, Christoffer Widström och Ellinor Gyllenhammar (VDR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-cinven-och-novo-holdings-vid-forsaljningen-av-envirotainer/","date":"2022-06-07","month":6},{"year":2022,"client":"Paynova","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Paynova vid kapitalanskaffning och listbyte","caption":"Kapitalanskaffning · 7 juni 2022","preamble":"Vinge biträder Paynova AB, under namnändring till Sileon AB, i samband med en fulltecknad företrädesemission om ca 70 MSEK.","body":"I samband med emissionen har Paynova även offentliggjort avsikten att genomföra ett listbyte från NGM Regulated till Nasdaq First North Growth Market.\n\nVinges team har bl.a. bestått av Anders Strid, Edin Agic (projektledare), Adrian Filipovic och Amelia Rihs.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-paynova-vid-kapitalanskaffning-och-listbyte/","date":"2022-06-07","month":6},{"year":2022,"client":"Convini Intressenter","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder Convini Intressenter AB","caption":"Övrigt · 7 juni 2022","preamble":"Vinge med stöd av Heuking Kühn Lüer Wojtek, företräder Convini Intressenter AB i förvärv av HelloFreshGo i Tyskland.","body":"Vinges team bestod av Ulrich Ziche tillsammans med bland andra biträdande juristerna Laura Kylmänen och Sophie Böje.\n\nLänk till Convinis pressmeddelande","href":"https://www.vinge.se/uppdrag/vinge-foretrader-convini-intressenter-ab/","date":"2022-06-07","month":6},{"year":2022,"client":"SEB","work":"Kapitalanskaffning","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt SEB i samband med emission av primärkapitaltillskott om 500 miljoner USD","caption":"Kapitalanskaffning · 7 juni 2022","preamble":"Vinge har biträtt Skandinaviska Enskilda Banken AB (publ) avseende svensk rätt i samband med emission av primärkapitaltillskott (AT1) om 500 miljoner USD för att optimera kapitalstrukturen.","body":"Emissionen sker i form av skuldinstrument med automatisk konvertering till A-aktier om bankens kärnprimärkapitalkvot faller under en viss nivå. Instrumenten kommer att noteras på Euronext Dublin.\n\nVinges team bestod av Albert Wållgren, David Andersson och Arvid Weimers.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-seb-i-samband-med-emission-av-primarkapitaltillskott-om-500-miljoner-usd/","date":"2022-06-07","month":6},{"year":2022,"client":"VEF","work":"Börsnotering","disciplines":["Kapitalmarknad och publik M&A","Företagsbeskattning"],"title":"Vinge har företrätt VEF AB (publ) i samband med notering av bolagets stamaktier på Nasdaq Stockholms huvudlista","caption":"Börsnotering · 3 juni 2022","preamble":"Vinge har företrätt VEF AB (publ) i samband med dess listbyte från Nasdaq First North Growth Market till Nasdaq Stockholms huvudlista. Prospektet offentliggjordes den 30 maj 2022 och handeln på Nasdaq Stockholm inleddes den 1 juni 2022.","body":"VEF är ett investmentbolag vars syfte är att investera i bolag i ett tidigt skede som erbjuder moderna finansiella tjänster i tillväxtmarknader. VEF fokuserar på stora tillväxtmarknader och investerar över hela spektrat av finansiella tjänster inklusive betalningar, kreditgivning, mobila lösningar och förmögenhetsförvaltning.\n\nVinges team har huvudsakligen bestått av Jesper Schönbeck, Joel Wahlberg, Emma Brolund, Anna Svensson och Johannes Akyol (Kapitalmarknad och Publik M&A) och Victor Ericsson och Emelie Svanberg (Företagsbeskattning).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-vef-ab-publ-i-samband-med-notering-av-bolagets-stamaktier-pa-nasdaq-stockholms-huvudlista/","date":"2022-06-03","month":6},{"year":2022,"client":"Öhlin Holding","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Öhlin Holding i budet på myFC","caption":"Övrigt · 1 juni 2022","preamble":"K Öhlin Holding AB har lämnat ett rekommenderat kontanterbjudande till aktieägarna i myFC Holding AB (publ).","body":"Vinges team består av Erik Sjöman och Agaton Lindgren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ohlin-holding-i-budet-pa-myfc/","date":"2022-06-01","month":6},{"year":2022,"client":"Axcel","work":"Samgående","disciplines":["M&A"],"title":"Vinge företräder Axcel i samband med sammanslagningen av itm8 och dess nuvarande portföljbolag AddPro","caption":"Samgående · 30 maj 2022","preamble":"Axcel, tillsammans med Chr. Augustinus Fabrikker, har kommit överens om att förvärva den danska digitala transformationspartnern, itm8, i syfte att tillsammans med Axcel-ägda AddPro skapa en nordeuropeisk koncern inom end-to-end IT-tjänster.","body":"Itm8 och AddPro har genom åren var för sig byggt upp starka varumärken och målet är att tillsammans utöka utbudet av IT-tjänster på den nordeuropeiska marknaden. Vinge var juridisk rådgivare till Axcel i transaktionen avseende försäljningen av AddPro samt i relation till sammanslagningens svenskrättsliga aspekter.\n\nTransaktionen är villkorad av sedvanliga myndighetsgodkännanden och förväntas vara avslutad under Q3 2022.\n\nVinges team bestod av Christina Kokko, Johanna Wiberg, Viktor Lennartsson och Nina Fathjalali (M&A) samt Viktoria Owetz Leyva, Sara Dahlros Sköld, Christoffer Widström, Julia Hagelberg and Klara Lundquist (VDR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-i-samband-med-sammanslagningen-av-itm8-och-dess-nuvarande-portfoljbolag-addpro/","date":"2022-05-30","month":5},{"year":2022,"client":"Main Capital Partners","work":"Förvärv","disciplines":["Bank och finans","M&A"],"title":"Vinge företräder Main Capital Partners vid förvärvet och förvärvsfinansieringen av King Software","caption":"Förvärv · 27 maj 2022","preamble":"Vinge har biträtt Main Capital Partners och dess portföljbolag Björn Lundén med dess förvärv och förvärvsfinansiering av King Software och dess dotterbolag. King Software är en holländsk mjukvaru-koncern primärt verksamma inom innovativa SaaS-lösningar.","body":"Finansieringen bestod av ett kreditfacilitetsavtal, inklusive både förvärvs- och revolverande faciliteter, med Skandinaviska Enskilda Banken AB (publ) som långivare.\n\nVinges team bestod av Mikael Ståhl, Arvid Weimers, Axel Jansson och Calle Tengwall Pagels (Banking and finance) samt Jonas Johansson, Per Kling och Elias Bohlin (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-partners-vid-forvarvet-och-forvarvsfinansieringen-av-king-software/","date":"2022-05-27","month":5},{"year":2022,"client":"Grundarna","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge företräder grundarna i samband med Altors investering i Audiowell","caption":"Kapitalanskaffning · 25 maj 2022","preamble":"Vinge företräder grundarna i samband med Altor Fund V:s investering i den svenskgrundade internationella musikkoncernen Audiowell. Grundarna kommer att förbli ägare och fortsätta i sina nuvarande roller i utvecklingen av koncernen. I samband med transaktionen har Audiowell och Altor ingått partnerskap med den ledande musikproducenten Martin Sandberg (även känd som Max Martin). Altor och Max Martin kommer att stödja grundarna och koncernen på dess fortsatta tillväxtresa.","body":"Grundarna - Andreas Romdhane och Josef Svedlund - lanserade Audiowell med målsättningen att öka kvaliteten på livsstilsmusik genom att dedikera tid, resurser och samarbeta med begåvade kreatörer. Båda grundarna har arbetat i mer än 20 år som musikproducenter och låtskrivare, legat bakom flera toppsinglar i Storbritannien och arbetat med artister som Westlife, Kelly Clarkson, Diana Ross och Il Divo för att nämna några. Koncernen har ett musikstudiokomplex i Stockholm varifrån den stödjer över 100 musikskapare spridda från USA till Hongkong och Sydamerika och fokuserar på ett brett utbud av genrer som jazz, avkoppling, akustisk, dans, rock och klassisk.\n\nVinges team bestod huvudsakligen av Jonas Johansson, Maria Dahlin Kolvik, Carl Fredrik Wachtmeister och Linnea Petersson (M&A) samt Viktoria Owetz Leyva och Ellinor Gyllenhammar (VDR-specialister).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-grundarna-i-samband-med-altors-investering-i-audiowell/","date":"2022-05-25","month":5},{"year":2022,"client":"Lassie","work":"Kapitalanskaffning","disciplines":[],"title":"Vinge företräder Lassie AB vid kapitalanskaffning om 115 miljoner kronor","caption":"Kapitalanskaffning · 24 maj 2022","preamble":"Vinge har företrätt djurförsäkringsbolaget Lassie AB i samband med en kapitalanskaffning om 115 miljoner kronor i syfte att expandera verksamheten internationellt samt utveckla företagets app.","body":"Lassie AB, vars affärsmodell bygger på att användarna sänker sina försäkringskostnader genom att samla poäng genom preventiv djurvård, grundades av Hedda Båverud Olsson, Johan Jönsson och Sophie Wilkinson och bolaget har vuxit snabbt sedan den första kapitalrundan för knappt ett år sedan.\n\nI kapitalrundan som leddes av det brittiska venture capital-bolaget Felix Capital deltog även ett flertal befintliga investerare, däribland de institutionella investerarna Inventure och Passion Capital samt H&M:s styrelseordförande Karl-Johan Persson och Vois grundare respektive marknadschef Fredrik och Caroline Hjelm.\n\nVinges team bestod av Filip Öhrner, Maria Dahlin Kolvik och Viktor Lennartsson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-lassie-ab-vid-kapitalanskaffning-om-115-miljoner-kronor/","date":"2022-05-24","month":5},{"year":2022,"client":"FSN Capital och Seriline","work":"Förvärv","disciplines":["Arbetsrätt","IT, Telekom och Outsourcing","M&A","Immaterialrätt"],"title":"Vinge företräder FSN Capital och Seriline i samband med tilläggsförvärv av Areff Systems","caption":"Förvärv · 24 maj 2022","preamble":"Vinge har företrätt FSN Capital och Seriline i samband med förvärvet av Areff Systems AB från dess grundare. Grundarna blir kvar i det sammanslagna bolaget och återinvesterar en betydande andel av köpeskillingen i gruppen.","body":"I slutet av februari 2022 förvärvade riskkapitalbolaget FSN Capital en majoritetsandel i Seriline med ambitionen att konsolidera marknaden för fysisk och digital identitets- och accesskontroll. Förvärvet av Seriline följs nu upp med förvärvet av Areff Systems där FSN Capital står för en majoritet av finansieringen. Areff Systems arbetar med säkerhets- och identifieringslösningar och har i dag 18 anställda. Förvärvet av Areff Systems ökar Serilines omsättning med närmare 50 procent till omkring 150 miljoner kronor för 2022.\n\nVinges team bestod huvudsakligen av Johan Winnerblad, Maria Dahlin Kolvik, Eléonore Friberg och Ebba Nyberg (M&A), Mathilda Persson (IT), Sara Strandberg (Arbetsrätt) och Axel Lennartsson (IP).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-fsn-capital-och-seriline-i-samband-med-tillaggsforvarv-av-areff-systems/","date":"2022-05-24","month":5},{"year":2022,"client":"Odevo","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Odevo i samband med förvärvet av Monu","caption":"Förvärv · 23 maj 2022","preamble":"Vinge företräder Odevo i samband med förvärvet av fintech-bolaget Monu.","body":"Vinges team bestod av bland andra Jonas Bergström, Johanna Wiberg och Amanda Steen.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-odevo-i-samband-med-forvarvet-av-monu/","date":"2022-05-23","month":5},{"year":2022,"client":"Re:NewCell","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Re:NewCell i samband med en riktad nyemission","caption":"Kapitalanskaffning · 20 maj 2022","preamble":"Vinge har företrätt Re:NewCell, ett textilåtervinningsbolag noterat på Nasdaq First North Premier Growth Market, i samband med en riktad nyemission varigenom bolaget tillfördes cirka 324 miljoner kronor före emissionskostnader.","body":"Emissionen riktades till ett antal utvalda svenska och internationella institutionella investerare på grundval av en accelererad bookbuilding process.\n\nRe:NewCell AB grundades 2012 av forskare vid KTH i Stockholm. Det är ett flerfaldigt prisbelönt sustaintechbolag baserat i Sverige. Re:NewCells vision är att inspirera en Industriell Evolution till en hållbar värld genom att producera material av hög kvalitet från återvunnen textil.\n\nVinges team bestod av Dain Hård Nevonen, William Kåge, Benjamin Vafaeian och Gabriel Chabo. Henrik Ossborn biträdde avseende finansieringsfrågor.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-re-newcell-i-samband-med-en-riktad-nyemission/","date":"2022-05-20","month":5},{"year":2022,"client":"Heda Security","work":"Förvärv","disciplines":["Arbetsrätt","M&A"],"title":"Vinge biträder Heda Security vid förvärv av MSS Nordic","caption":"Förvärv · 19 maj 2022","preamble":"Vinge har biträtt Helix Kapitals portföljbolag Heda Security vid förvärv av MSS Nordic, som är specialister på alla typer av automatiserade grindar, trafikbommar och tillhörande system på den nordiska marknaden.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Amanda Steen, Christoffer Nordin och Veronika Garemark.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-heda-security-vid-forvarv-av-mss-nordic/","date":"2022-05-19","month":5},{"year":2022,"client":"Wpd","work":"Avyttring","disciplines":["Bank och finans","M&A"],"title":"Vinge företräder wpd i samband med försäljningen av vindkraftsparken Aldermyrberget","caption":"Avyttring · 16 maj 2022","preamble":"Vinge företräder wpd Europe GmbH, som utvecklar och driver vind- och solkraftsparker till land och till havs, i samband med försäljningen av vindkraftsparken Aldermyrberget till EB Renewable Energy Fund Europe och LHI Green Infrastructure Invest II.","body":"Vindkraftsparken Aldermyrberget består av 17 stycken vindkraftverk tillverkade av Vestas. Med en beräknad energiproduktion om ca 275 GWh och en årlig CO2-minskning om 1 308 ton bidrar projektet aktivt till en hållbar energiförsörjning i Sverige.\n\nVinges team bestod huvudsakligen av Peter Sundgren, Linus Adolfsson (M&A) och Linn Adelwald (Banking and Finance).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-wpd-i-samband-med-forsaljningen-av-vindkraftsparken-aldermyrberget/","date":"2022-05-16","month":5},{"year":2022,"client":"Studentbostäder","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Studentbostäder i Norden AB (publ) i samband med en riktad nyemission","caption":"Kapitalanskaffning · 10 maj 2022","preamble":"Vinge har biträtt Studentbostäder i Norden AB (publ), ett fastighetsbolag vars stamaktier är noterade på Nasdaq First North, i samband med en riktad nyemission varigenom bolaget tillförs 50 miljoner kronor före emissionskostnader.","body":"Studentbostäder i Nordens strategi är i huvudsak utveckling och förvärv av kostnadseffektiva studentbostäder i svenska universitets- och högskolestäder. Bolagets aktier är noterade i Sverige på Nasdaq First North Growth Market med kortnamnet STUDBO.\n\nVinges team bestod av Jesper Schönbeck, Joel Wahlberg och Johannes Akyol.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-studentbostader-i-norden-ab-publ-i-samband-med-en-riktad-nyemission/","date":"2022-05-10","month":5},{"year":2022,"client":"Atairos","work":"Offentligt uppköpserbjudande","disciplines":["M&A"],"title":"Vinge företräder Atairos i samband med ett rekommenderat uppköpserbjudande till aktieägarna i Ocean Outdoor. Erbjudandets värde uppgår till cirka 5 805 miljoner kronor.","caption":"Offentligt uppköpserbjudande · 6 maj 2022","preamble":"Transaktionen kommer genomföras via en s.k. statutory merger enligt Brittiska Jungfruöarnas bolagsrätt, och är beroende av svenska Konkurrensverket godkännande och andra sedvanliga tillträdesvillkor. Transaktionen förväntas genomföras under juni 2022.","body":"Atairos är en investeringsfond med omkring USD 6,5 miljarder in kapital och kontor i New York, London och Philadelphia. Ocean Outdoor är en ledande aktör i digital ’out-of-home’ reklam i Storbritanninen och Europa. Oceans aktier är noterade på London Stock Exchange.\n\nVinges team bestod av Sofie Nordgren (M&A), Pär Remnelid (EU / Competition) and Carl Trolle Olson (M&A).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-atairos-i-samband-med-ett-rekommenderat-uppkopserbjudande-till-aktieagarna-i-ocean-outdoor-erbjudandets-varde-uppgar-till-cirka-5-805-miljoner-kronor/","date":"2022-05-06","month":5},{"year":2022,"client":"BHG Group","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder BHG Group i samband med riktad nyemission","caption":"Kapitalanskaffning · 5 maj 2022","preamble":"Vinge biträder BHG Group AB (publ) i samband med en riktad nyemission om 1,0 miljard kronor genom ett accelererat bookbuilding-förfarande.","body":"Vinges team består av Christian Lindhé, Martin Svanberg, Johanne Örnfeldt Svensson och Emil Sandgrim. Kristian Ford är klientansvarig partner.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-bhg-group-i-samband-med-riktad-nyemission-1/","date":"2022-05-05","month":5},{"year":2022,"client":"A3P Biomedical","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder A3P Biomedical vid riktad emission","caption":"Kapitalanskaffning · 5 maj 2022","preamble":"Vinge har biträtt A3P Biomedical i samband med en emission om 400 miljoner kr riktad till Stena Sessan AB, TomEqt Private AB, Flerie Invest AB, Östersjöstiftelsen och Inbox Capital. A3P Biomedical specialiserar sig på avancerad diagnostik av prostatacancer.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Rikard Lindahl, William Kåge, Lorin Arabi, Gabriel Chabo, Stojan Arnerstål, Arvid Axelryd och Olivia Belding.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-a3p-biomedical-vid-riktad-emission/","date":"2022-05-05","month":5},{"year":2022,"client":"Aleris","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Aleris i förvärv av Art Clinic AB","caption":"Förvärv · 3 maj 2022","preamble":"Vinge företräder Aleris Sjukvård AB i samband med förvärvet av Art Clinic AB. Art Clinic AB bedriver fyra specialistvårdskliniker med fem satellitmottagningar i sex regioner i Sverige.","body":"Aleris är en av Skandinaviens ledande vårdgivare med två miljoner patientbesök om året och bedriver specialistsjukvård på över 130 platser i Sverige, Norge och Danmark. Genom förvärvet förstärker Aleris sin specialistsjukvård inom ortopedi, ryggkirurgi samt estetisk och rekonstruktiv plastikkirurgi i Sverige.\n\nKlientens förvärv är beroende av berörda konkurrensmyndigheters godkännande och andra sedvanliga tillträdesvillkor.\n\nVinges team bestod av Christina Kokko, Samra Baytar, Olivia Belding och Elias Bohlin (M&A), Johan Wahlbom (Competition), Christoffer Nordin, Sam Fakhraie Ardekani och Max Hetta (Agreements), Emil Lindwall (Employment), Nour Makie (Banking and Finance), Karolina Fuhrman (IT/GDPR), Frida Ställborn (Real Estate) samt Jessica Henning (VDR specialist).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-aleris-i-forvarv-av-art-clinic-ab/","date":"2022-05-03","month":5},{"year":2022,"client":"Embracer","work":"Förvärv","disciplines":["Bank och finans"],"title":"Vinge biträder Embracer i samband med förvärvsfinansiering om 4 miljarder kronor","caption":"Förvärv · 3 maj 2022","preamble":"Embracer Group AB (publ) har ingått avtal om att förvärva spelutvecklings-studios Crystal Dynamics, Eidos Montreal och Square Enix Montreal, och en varumärkeskatalog som inkluderar Tomb Raider, Deux Ex, Thief, Legacy of Kain och mer än 50 katalogspel.","body":"Förvärvet inkluderar cirka 1 100 anställda fördelat på tre studios och åtta olika platser. Den totala köpeskillingen uppgår till 300 MUSD på en kassa- och skuldfri basis, och betalas i sin helhet vid slutförande av transaktionen. Transaktionen är villkorad av vissa regulatoriska och andra externa godkännanden och väntas slutföras under andra kvartalet i Embracers räkenskapsår 22/23\n\nVinge har biträtt Embracer i samband med ingåendet av ett nytt kreditfacilitetsavtal med SEB, Nordea och Swedbank till ett värde av 4 miljarder kronor i syfte att användas b.la. för att finansiera förvärvet, samt en förlängning av existerande brygglån om 6 miljarder kronor.\n\nVinges team bestod av Louise Brorsson Salomon, Lionardo Ojeda och Felix Möller.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-embracer-i-samband-med-forvarvsfinansiering-om-4-miljarder-kronor/","date":"2022-05-03","month":5},{"year":2022,"client":"Swecon","work":"Förvärv","disciplines":["Arbetsrätt","Corporate Commercial","M&A","EU‑ och konkurrensrätt"],"title":"Vinge har företrätt Swecon i samband med förvärv av Kewab Rental","caption":"Förvärv · 3 maj 2022","preamble":"Vinge har företrätt Swecon Anläggningsmaskiner AB (”Swecon”) vid förvärv av KEWAB Rental AB (”Kewab Rental”). Kewab Rental, med huvudkontor i Karlstad, är ett av Sveriges största uthyrningsföretag av stora entreprenadmaskiner utan förare.","body":"Vinges team bestod av bland andra Christina Kokko, Ellinor Wargenbrant och Nina Fathjalali (M&A), Christoffer Nordin (Kommersiella avtal), Johan Wahlbom (Konkurrensrätt), Karl-Gustaw Tobola (Bank och finans), Elin Broman (Arbetsrätt) och Ellinore Boström Andersson (Projektassistent).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-swecon-i-samband-med-forvarv-av-kewab-rental/","date":"2022-05-03","month":5},{"year":2022,"client":"Astrego Diagnostics","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljning av Astrego Diagnostics till Sysmex","caption":"Avyttring · 2 maj 2022","preamble":"Vinge har biträtt huvudägarna i Astrego Diagnostics AB vid försäljning av aktierna till den japanska minoritetsägaren Sysmex Corporation.","body":"Astrego har utvecklat en diagnostisk test för bestämning av förekomsten av bakterier i patientprover och fastställande av resistens mot olika antibiotika (sk ”Antibiotic Susceptibility Test, AST”).\n\nVinges team bestod av Johan Winnerblad, Eléonore Friberg, Viktoria Owetz Leyva och Gunilla Nyman.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-astrego-diagnostics-till-sysmex/","date":"2022-05-02","month":5},{"year":2022,"client":"MGM","work":"Övrigt","disciplines":["Arbetsrätt","EU‑ och konkurrensrätt","Kapitalmarknad och publik M&A"],"title":"Vinge biträder MGM i budet på LeoVegas","caption":"Övrigt · 2 maj 2022","preamble":"MGM Casino Next Lion, LLC har lämnat ett rekommenderat uppköpserbjudande till aktieägarna i LeoVegas AB (publ). Erbjudandets värde uppgår till cirka 5 957 miljoner kronor. Vinge biträder MGM.","body":"Vinges team består av Erik Sjöman, Linnéa Sellström, William Kåge, Anna Svensson, Michaela Ådén, Emma Johansson, Johan Wahlbom, Mattias Schömer, Victor Ericsson och Sara Strandberg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-mgm-i-budet-pa-leovegas/","date":"2022-05-02","month":5},{"year":2022,"client":"Promimic","work":"Börsnotering","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt Promimic AB (publ) i samband med dess notering på Nasdaq First North Growth Market","caption":"Börsnotering · 29 april 2022","preamble":"Vinge har biträtt Promimic AB (publ) i samband med dess notering på Nasdaq First North Growth Market. Första handelsdag är den 29 april 2022. I samband med noteringen genomfördes ett erbjudande att teckna aktier till en teckningskurs om 16 kronor.","body":"Promimic AB är ett biomaterialföretag som tillverkar och marknadsför HAnano Surface, en unik beläggning för medicinska implantat som stärker dess förankring i benvävnad. Promimic fokuserar på marknaden för dentala och ortopediska implantat.\n\nVinges team har huvudsakligen bestått av Anders Strid, Johanna Hamrefält (projektledare), Adrian Filipovic, Rebecka Hansson, Anna Högsten och Fredrik Löwenclou.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-promimic-ab-publ-i-samband-med-dess-notering-pa-nasdaq-first-north-growth-market/","date":"2022-04-29","month":4},{"year":2022,"client":"Beijer Byggmaterial","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företrädde Beijer Byggmaterial i förvärvet av 100 Procent Proffs","caption":"Förvärv · 21 april 2022","preamble":"Vinge företrädde Beijer Byggmaterial AB i samband med förvärvet av 100 Procent Proffs. Anläggningarna som ligger i Bandhagen och i Rotebro har ca 50 medarbetare och riktar sig enbart mot proffskunder i Stockholmsområdet.","body":"Vinges team bestod av bland andra Jonas Bergström, Joacim Rydergård och Ellinor Wargenbrant, Arvid Axelryd, Kristoffer Larson, Karolina Fuhrman, Elin Broman samt Jessica Henning.","href":"https://www.vinge.se/uppdrag/vinge-foretradde-beijer-byggmaterial-i-forvarvet-av-100-procent-proffs/","date":"2022-04-21","month":4},{"year":2022,"client":"PDL Group och dess huvudägare","work":"Samgående","disciplines":["Bank och finans","M&A"],"title":"Vinge har företrätt PDL Group och dess huvudägare i samband med samgåendet med Padel United","caption":"Samgående · 20 april 2022","preamble":"Vinge har företrätt PDL Group och dess huvudägare i samband med samgåendet med Padel United. Genom transaktionen blir PDL Group en del av Padel United, som därmed blir världens största padelaktör med sammanlagt 118 anläggningar och med ytterligare 30 anläggningar som kommer öppna inom en snar framtid.","body":"Vinges team bestod av bland andra Jonas Bergström, Johanna Wiberg och Måns Håkansson (M&A) samt Albert Wållgren, Linn Adelwald, Kamyar Najmi och Ulf Pyk (Banking and finance).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-pdl-group-och-dess-huvudagare-i-samband-med-samgaendet-med-padel-united/","date":"2022-04-20","month":4},{"year":2022,"client":"Odevo","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Odevo i samband med förvärvet av OBOS ägarandel i SBC och Obos investering i Odevo","caption":"Kapitalanskaffning · 13 april 2022","preamble":"Vinge företräder Odevo i samband med förvärvet av OBOS ägarandel i och försäljning av sin minoritetsandel om cirka 40 procent i SBC Intressenter HoldCo AB (\"SBC\") och OBOS investering i Odevo.","body":"OBOS har sedan 2019 varit delägare i SBC genom sin minoritetsandel om cirka 40 procent i SBC Intressenter HoldCo AB. Genom försäljningen av sina aktier till Odevo blir SBC helägt av Odevo som har cirka 1 300 anställda och en omsättning på drygt 1,5 MDSEK.\n\nVinges team bestod av bland andra Jonas Bergström, Joacim Rydergård och Clara Sohlberg.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-odevo-i-samband-med-forvarvet-av-obos-agarandel-i-sbc-och-obos-investering-i-odevo/","date":"2022-04-13","month":4},{"year":2022,"client":"Sobro","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Sobro vid investering i Viva Media","caption":"Kapitalanskaffning · 13 april 2022","preamble":"Vinge biträder Sobro när Sobro går in som ny huvudägare i Viva Media där de tillsammans med grundarna Arash Gilan och Henrik Zobal, som kvarstår som ägare, satsar på att göra Viva Media till Nordens bästa marknadsföringsbyrå.","body":"Vinges team bestod bl.a. av Johan Winnerblad, Per Kling, Emil Lindwall, Mario Saad, Karolina Fuhrman, Philip Moré och Lotten Hellström.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sobro-vid-investering-i-viva-media/","date":"2022-04-13","month":4},{"year":2022,"client":"ABG Sundal Collier och Carnegie","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt ABG Sundal Collier och Carnegie i samband med kapitalanskaffning i Xshore","caption":"Kapitalanskaffning · 12 april 2022","preamble":"Vinge har företrätt ABG Sundal Collier och Carnegie i samband med en kapitalanskaffning om 500 miljoner kronor i elbåtsbolaget Xshore genom en riktad nyemission till ett antal nya investerare och befintliga ägare.","body":"Xshore grundades 2016 av Konrad Bergström med avsikten att tillhandahålla kunder en överlägsen och hållbar användarupplevelse samt därigenom att driva branschen till att agera mer hållbart. Xshore har en ledande marknadsposition och nominerades till Årets Powerboat 2022 i konkurrens med icke-elektriska båtar.\n\nVinges team bestod av Dain Hård Nevonen och Linnéa Sellström.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-abg-sundal-collier-och-carnegie-i-samband-med-kapitalanskaffning-i-xshore/","date":"2022-04-12","month":4},{"year":2022,"client":"Flat Capital","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge har företrätt Flat Capital i samband med dess företrädesemission","caption":"Kapitalanskaffning · 11 april 2022","preamble":"Vinge har företrätt Flat Capital AB (publ) (”Flat Capital”) i samband med dess företrädesemission, vilken tillförde Flat Capital cirka 77 miljoner kronor.","body":"Flat Capital är ett investeringsbolag som grundades 2013 och som fokuserar på bolag med framstående entreprenörer i ledande ställning. Flat Capital är noterat på Nasdaq First North Growth Market.\n\nVinges team bestod av Jesper Schönbeck, Joel Wahlberg och Johannes Akyol.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-flat-capital-i-samband-med-dess-foretradesemission/","date":"2022-04-11","month":4},{"year":2022,"client":"Mayr-Melnhof Group","work":"Förvärv","disciplines":["Bank och finans","Kommersiella avtal","Immaterialrätt","M&A","Corporate Crime & Compliance","IT, Telekom och Outsourcing","Fastigheter och Entreprenad","Miljörätt"],"title":"Vinge har biträtt Mayr-Melnhof Group vid dess förvärv av Eson Pac","caption":"Förvärv · 11 april 2022","preamble":"Eson Pac är en förpackningleverantör specialiserad på läkemedelsförpackningar. Mayr-Melnhof Group (“MM”) har förvärvat 100 % av aktierna i Eson Pac från majoritetsägaren Nalka Invest AB samt grundarfamiljen och minoritetsägare från bolagsledningen. MM är en av Europas ledande producenter av kartong och vikkartonger samt erbjudanden inom papper och finpapper.","body":"Vinges team bestod av Matthias Pannier, Ulrich Ziche, Måns Håkanson och Elias Bohlin (M&A), Felix Möller och Ellen Flygt (Bank och Finans), Elin Broman och Emil Lindwall (Arbetsrätt), Michael Montner (IP), Mario Saad (Kommersiella Avtal), Mika Jordan (IT), Tove Tullberg (Regelefterlevnad), Frida Ställborn (Fastighetsrätt), Johan Cederblad and Lina Österberg (Miljörätt).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-mayr-melnhof-group-vid-dess-forvarv-av-eson-pac/","date":"2022-04-11","month":4},{"year":2022,"client":"Platzer fastigheter","work":"Övrigt","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge har biträtt Platzer fastigheter i samband med att detaljplan för Södra Änggården vunnit laga kraft.","caption":"Övrigt · 8 april 2022","preamble":"Den 6 april 2022 vann detaljplanen för Södra Änggården laga kraft. Mark- och miljööverdomstolen har avslagit överklagan av detaljplanen för omvandlingen av Högsbo industriområde till blandstaden Södra Änggården. Domen får inte överklagas.","body":"Detaljplanen möjliggör för bl.a. ca 1900 bostäder samt verksamhetslokaler, skolor och parker. Platzer är idag den största fastighetsägaren i området. Den totala intäkten för Platzer bedöms uppgå till 1,8 mdkr.\n\nVinges roll i ärendet har bl.a. varit att driva Platzers talan i Mark- och miljööverdomstolen.\n\nVinges team bestod i huvudsak av Robert Deli och Hampus Wahlberg.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-platzer-fastigheter-i-samband-med-att-detaljplan-for-sodra-anggarden-vunnit-laga-kraft/","date":"2022-04-08","month":4},{"year":2022,"client":"Swedbank","work":"Förvärv","disciplines":["Bank och finans"],"title":"Vinge har biträtt Swedbank i samband med Regios förvärvsfinansiering om cirka 1,5 miljarder kronor","caption":"Förvärv · 7 april 2022","preamble":"Vinge har biträtt Swedbank AB (publ) i samband med en kreditfacilitetsavtal om cirka 1,5 miljarder kronor i syfte att finansiera Fastighets AB Regios förvärv av en fastighetsportfölj till ett sammanlagt överenskommet fastighetsvärde om cirka 2,4 miljarder kronor.","body":"De förvärvade fastigheterna är centralt belägna i Gävle och den primära användningen är kontor. Genom förvärvet blir Regio en av de större fastighetsägarna i Gävle.\n\nVinges team bestod av Louise Brorsson Salomon, Arvid Weimers och Ellen Flygt.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-swedbank-i-samband-med-regios-forvarvsfinansiering-om-cirka-1-5-miljarder-kronor/","date":"2022-04-07","month":4},{"year":2022,"client":"Heda Security","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Heda Security vid förvärv av Teknoinfra","caption":"Förvärv · 7 april 2022","preamble":"Vinge har biträtt Heda Security vid förvärv av finska Teknoinfra Oy. Förvärvet stärker ytterligare positionen som Nordens ledande företag inom områdessäkerhet. Koncernen omsätter nu drygt 440 miljoner kr och har 170 anställda.","body":"Vinges team bestod av Johan Winnerblad","href":"https://www.vinge.se/uppdrag/vinge-bitrader-heda-security-vid-forvarv-av-teknoinfra/","date":"2022-04-07","month":4},{"year":2022,"client":"EQT","work":"Obligationsemission","disciplines":["Bank och finans","Kapitalmarknad och publik M&A"],"title":"Vinge har biträtt EQT AB (publ) i samband med dess obligationsemissioner om totalt 1 500 MEUR","caption":"Obligationsemission · 6 april 2022","preamble":"EQT AB (publ) har emitterat hållbarhetslänkade obligationer (s.k. sustainability-linked bonds) om 750 000 000 euro som förfaller 2028 och om 750 000 000 euro som förfaller 2032. Obligationernas kupongränta är föremål för ökning vid överstigandet av särskilda tröskelvärden som kopplar till vissa hållbarhetsmål.","body":"Vinge företräder tillsammans med Latham & Watkins EQT AB.\n\nVinges team bestod främst av Louise Brorsson Salomon, Ludvig Wettergren, Jolinn Uhlin, Sofie Bjärtun, Linnéa Sellström och Henrik Schön.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-eqt-ab-publ-i-samband-med-dess-obligationsemissioner-om-totalt-1-500-meur/","date":"2022-04-06","month":4},{"year":2022,"client":"Main Capital","work":"Förvärv","disciplines":["Arbetsrätt","M&A","Immaterialrätt","IT, Telekom och Outsourcing","Kommersiella avtal"],"title":"Vinge har biträtt Main Capital vid dess förvärv av Blika Solutions AB","caption":"Förvärv · 6 april 2022","preamble":"Blika tillhandahåller ett modulärt, best-of-breed SaaS-system som möjliggör för företag att bevaka legala strukturer för att säkerställa adekvat styrning och regelefterlevnad. Plattformen hjälper företag med regelefterlevnad avseende bland annat skatte- och internprissättningsregler såsom DAC6 och IFRIC 23 samt andra regelverk.","body":"Blika, med huvudkontor i Stockholm och ytterligare kontor i Kalmar och Oskarshamn, har en stor kundbas bestående av europeiska och globala multinationella företag inklusive Fortune 500-företag.\n\nVinges team bestod av Filip Öhrner, Manne Bergström, Egil Svensson (M&A), Veronika Garemark, Elin Broman (Arbetsrätt), Rebecka Målquist (IP), Lisa Hörnqvist, Karolina Fuhrman (Commercial Agreements, IT & GDPR) och Jessica Henning (VDR-assistent).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-main-capital-vid-dess-forvarv-av-blika-solutions-ab/","date":"2022-04-06","month":4},{"year":2022,"client":"Yokohama Rubber Company Ltd.","work":"Förvärv","disciplines":["Corporate Crime & Compliance","M&A","Immaterialrätt","Arbetsrätt"],"title":"Vinge företräder Yokohama Rubber Company Ltd. i förvärv av Trelleborg Wheel Systems AB","caption":"Förvärv · 5 april 2022","preamble":"Klientens förvärv är beroende av berörda konkurrensmyndigheters godkännande och andra sedvanliga tillträdesvillkor.","body":"Vinges team bestod av Christina Kokko, Ulrich Ziche, Tove Tullberg, Karolina Cohrs, Veronika Garemark, Tobias Kempas och Gustav Persson.\n\nPressrelease från klient: https://www.y-yokohama.com/release/?id=3774&lang=en","href":"https://www.vinge.se/uppdrag/vinge-foretrader-yokohama-rubber-company-ltd-i-forvarv-av-trelleborg-wheel-systems-ab/","date":"2022-04-05","month":4},{"year":2022,"client":"Capio","work":"Förvärv","disciplines":["Arbetsrätt","IT, Telekom och Outsourcing","EU‑ och konkurrensrätt","M&A","Offentlig upphandling"],"title":"Vinge biträder Capio vid förvärvet av PR Vård","caption":"Förvärv · 31 mars 2022","preamble":"Vinge biträder Capio i samband med förvärvet av samtliga aktier i PR Vård Hemsjukvård AB och PR Vård Mottagning AB.","body":"PR Vård bedriver hemsjukvård i fem av åtta primärvårdsområden i Stockholm samt driver en BUM och en VC på Södermalm. PR Vård har 600 anställda och utför närmare 1 miljon hemsjukvårdbesök om året. Tillträdet är villkorat av Konkurrensverkets godkännande.\n\nVinges team har bestått av ansvarig delägare Anders Strid samt Jenny Sandlund (projekledare), Victoria Gunnerek (offentlig upphandling), Adam Löwenstein (hyresrätt), Alexander Lindeberg (IT/GDPR), Anna Ståhlklo (arbetsrätt), Fredrik Löwenklou (M&A) samt Anna Palmérus (konkurrensrätt).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-capio-vid-forvarvet-av-pr-vard/","date":"2022-03-31","month":3},{"year":2022,"client":"Altor Fund III","work":"Avyttring","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträdde Altor Fund III i samband med försäljningen av aktier i CTEK AB (publ)","caption":"Avyttring · 31 mars 2022","preamble":"Vinge biträdde Altor Fund III GP Limited (”Altor”) i samband med en försäljning av aktier i CTEK AB (publ) (”CTEK”) i en så kallad accelererad bookbuilding-process. Altor sålde aktier till ett värde om 621 miljoner kronor och äger efter försäljningen cirka 10 procent av aktierna i CTEK.","body":"Vinges team bestod av David Andersson och Isabell Anstrin.","href":"https://www.vinge.se/uppdrag/vinge-bitradde-altor-fund-iii-i-samband-med-forsaljningen-av-aktier-i-ctek-ab-publ-vinge-bitradde-altor-fund-iii-i-samband-med-forsaljningen-av-aktier-i-ctek-ab-publ/","date":"2022-03-31","month":3},{"year":2022,"client":"Sobro","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Sobro vid investering i Hässelby Blommor AB","caption":"Kapitalanskaffning · 28 mars 2022","preamble":"Vinge har biträtt Sobro i samband med att Hässelby Blommor tar in Sobro som ny ägarpartner för fortsatt expansion. Hässelby Blommor är ett av Sveriges största förädlande blomsterföretag inriktat mot företagskunder, med en ledande ställning när det gäller design, kvalitet och service.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Ellinor Wargenbrant, Frida Ställborn och Emil Lindwall.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-sobro-vid-investering-i-hasselby-blommor-ab/","date":"2022-03-28","month":3},{"year":2022,"client":"Capillar","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A","M&A","Företagsbeskattning"],"title":"Vinge rådgivare till Capillar i samband med Sveriges första de-SPAC-transaktion","caption":"Övrigt · 22 mars 2022","preamble":"Capillar och minoritetsaktieägarna har ingått ett avtal om att sälja samtliga aktier i Spolargruppen Sverige AB, en svensk ledande aktör inom rörinfodring (så kallad relining) och rörspolning, till tbd30 AB (publ), en så kallad SPAC (Special Purpose Acquisition Company).","body":"I samband med den föreslagna transaktionen initieras en process (så kallad ”de-SPAC” eller bolagskombination) som bland annat innefattar att Nasdaq Stockholm AB granskar det tilltänkta förvärvet, ansökan om notering och listbyte till Nasdaq First North Growth Market inom ramen för Nasdaqs Stockholms regelverk för förvärvsbolag.\n\nSom en del av den fortsatta finansieringen har ett antal institutionella och andra investerare, däribland Lannebo Fonder och Carnegie Fonder, åtagit sig att teckna 1 500 000 nya A-aktier i tbd30 i en riktad nyemission som utges till 100 kronor per aktie.\n\nVinges team består huvudsakligen av Christina Kokko, Joacim Rydergård, Hannah Kajlinger och Philip Moré (M&A), Linnéa Sellström (Equity Capital Markets) samt Matthias Schömer och Henrik Wastenson (Skatt).","href":"https://www.vinge.se/uppdrag/vinge-radgivare-till-capillar-i-samband-med-sveriges-forsta-de-spac-transaktion/","date":"2022-03-22","month":3},{"year":2022,"client":"Advent International","work":"Förvärv","disciplines":["Arbetsrätt","Bank och finans","M&A","Kommersiella avtal","Immaterialrätt"],"title":"Vinge har företrätt Advent International vid förvärv av minoritetsandel i Medius","caption":"Förvärv · 17 mars 2022","preamble":"Medius är ledande global aktör inom AP-automatisering och fakturahantering. Bolagets erbjudande består av produkter och tjänster som förenklar och automatiserar hela processen, från att ta emot och godkänna fakturor till betalning och hantering av leverantörer.","body":"Vinges team bestod av Christina Kokko, Ulrich Ziche, Isabelle Wållgren, Eléonore Friberg och Elias Bohlin (M&A), Josefine Lanker (Bank & Finans), Mika Jordan (Kommersiella avtal), Fredrika Hjelmberg och Karolina Fuhrman (IT/GDPR), Michael Montner (IP), and Veronika Garemark (Arbetsrätt).\n\nMer information om transaktionen finner ni här: https://www.adventinternational.com/advent-international-to-acquire-minority-stake-in-spend-management-leader-medius/","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-advent-international-vid-forvarv-av-minoritetsandel-i-medius/","date":"2022-03-17","month":3},{"year":2022,"client":"EQT","work":"Samgående","disciplines":["Kapitalmarknad och publik M&A","EU‑ och konkurrensrätt"],"title":"Vinge företräder EQT i samband med sammanslagningen med Baring Private Equity Asia","caption":"Samgående · 16 mars 2022","preamble":"Vinge företräder EQT i samband med sammanslagningen med Baring Private Equity Asia, en ledande privat investeringsfirma i Asien med 17,7 miljarder euro i förvaltat kapital. Den totala köpeskillingen uppgår till 6,8 miljarder euro.","body":"Genom transaktionen kommer EQT att förvärva 100 procent av aktierna i förvaltningsbolaget BPEA, BPEA general partners som kontrollerar BPEA fonderna, och rätten till carried interest i utvalda befintliga fonder. Den totala köpeskillingen uppgår till 6,8 miljarder euro, varav cirka 5,3 miljarder euro kommer att utgöras av 191,2 miljoner nyemitterade aktier i EQT (motsvarande en utspädning om cirka 16 procent), plus 1,5 miljarder euro i kontant vederlag. Transaktionen är villkorad av sedvanliga fullföljandevillkor och fullföljandet förväntas ske under det fjärde kvartalet 2022.\n\nVinges team består huvudsakligen av Sofie Bjärtun, Erik Sjöman, Linnéa Sellström, Joel Magnusson, Lorin Arabi, Pernilla Björklund, Marcus Glader, Emma Johansson, Sebastian Örndahl, Jesper Ekman och Adam Löfquist.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-eqt-i-samband-med-sammanslagningen-med-baring-private-equity-asia/","date":"2022-03-16","month":3},{"year":2022,"client":"Säljarna av InnovDr","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder säljarna av InnovDr vid försäljning till Doktor.se","caption":"Avyttring · 15 mars 2022","preamble":"InnovDr är en digital vårdgivare inom hälsa- och sjukvård. Inom verksamheten, som startads 2016, bedrivs urinkollen.se, aknekollen.se, borreliakollen.se, menskollen.se, ögonkollen.se och herpeskollen.se under paraplyet Kollarna.se.","body":"Ägarna till InnovDr säljer bolaget till Doktor.se, som är en av Sveriges största aktörer inom digifysisk vård.\n\nVinges team bestod av Wibeke Sorling, Jenny Sandlund, Hanna Jansson och Amanda Stoltz.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-saljarna-av-innovdr-vid-forsaljning-till-doktor-se/","date":"2022-03-15","month":3},{"year":2022,"client":"Load Services","work":"Avyttring","disciplines":["M&A"],"title":"Vinge biträder vid försäljning av Load Services AB","caption":"Avyttring · 11 mars 2022","preamble":"Vinge har biträtt aktieägarna vid försäljning av Load Services till engelska ExcelRedstone. Load Services är ett av Sveriges ledande företag inom datacenter och kabelnätstjänster.","body":"Vinges team bestod av Johan Winnerblad.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-vid-forsaljning-av-load-services-ab/","date":"2022-03-11","month":3},{"year":2022,"client":"Lantmännen","work":"Förvärv","disciplines":["Arbetsrätt","Corporate Commercial","EU‑ och konkurrensrätt","M&A","Fastigheter och Entreprenad","Miljörätt"],"title":"Vinge har företrätt Lantmännen vid förvärv av del i KG:s Ägg","caption":"Förvärv · 10 mars 2022","preamble":"Vinge har företrätt Lantmännen vid förvärv av en minoritetsandel i KG:s Ägg, som är ett av Sveriges ledande äggpackeriföretag. Tillträde planeras äga rum den 1 april 2022.","body":"Vinges team bestod av bland andra Christina Kokko och Jenny Sandlund (M&A), Isabell Nielsen (Kommersiella avtal), Frida Ställborn och Ulf Pyk (Fastighet), Johan Wahlbom (Konkurrensrätt), Lina Österberg (Miljörätt och regelefterlevnad) och Gustav Lindgren (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-lantmannen-vid-forvarv-av-del-i-kg-s-agg/","date":"2022-03-10","month":3},{"year":2022,"client":"Ägaren av By Malina","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder ägaren av By Malina i samband med Stella Capitals majoritetsinvestering i bolaget","caption":"Kapitalanskaffning · 10 mars 2022","preamble":"Vinge företräder grundaren och ägaren av By Malina AB i samband med Stella Capital AB:s majoritetsinvestering i bolaget.","body":"By Malina AB grundades 2010 och är verksamt inom försäljning av kläder under varumärket By Malina. Grundaren kommer fortsatt vara verksam i sin nuvarande roll i utvecklingen av By Malina AB.\n\nVinges team bestod av Joacim Rydergård, Clara Sohlberg och Philip Moré.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-agaren-av-by-malina-i-samband-med-stella-capitals-majoritetsinvestering-i-bolaget/","date":"2022-03-10","month":3},{"year":2022,"client":"Ägarna av Soft Goat","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder ägarna av Soft Goat i samband med Stella Capitals majoritetsinvestering i bolaget","caption":"Kapitalanskaffning · 10 mars 2022","preamble":"Vinge företräder grundarna och övriga aktieägare av Soft Goat AB i samband med Stella Capital AB:s majoritetsinvesting i bolaget.","body":"Soft Goat AB grundades 2011 och är verksamt inom försäljning av kläder under varumärket Soft Goat. Grundarna kommer fortsatt vara verksamma i sina nuvarande roller i utvecklingen av Soft Goat AB.\n\nVinges team bestod av Joacim Rydergård, Clara Sohlberg och Philip Moré.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-agarna-av-soft-goat-i-samband-med-stella-capitals-majoritetsinvestering-i-bolaget/","date":"2022-03-10","month":3},{"year":2022,"client":"Schibsted","work":"Kapitalanskaffning","disciplines":["M&A","Bank och finans","Immaterialrätt"],"title":"Vinge biträder Schibsted vid investering i Savr","caption":"Kapitalanskaffning · 8 mars 2022","preamble":"Vinge har biträtt Schibsted vid investering i Savr AB. Investeringsrundan, som leds av Schibsted, tillför bolaget 162 milj kr. Savr är en fondplattform som återbetalar alla fondprovisioner till sina kunder.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Emma Stuart-Beck, Henrik Schön, Caroline Krassén, Anton Sjökvist och Sofia Bergenstråhle.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-schibsted-vid-investering-i-savr/","date":"2022-03-08","month":3},{"year":2022,"client":"Eleda Infra Services Group (Eleda)","work":"Förvärv","disciplines":["Bank och finans","M&A","Corporate Crime & Compliance","Kommersiella avtal","Arbetsrätt"],"title":"Vinge har företrätt Eleda Infra Services Group (”Eleda”) i samband med förvärv av Mats Wåhlin AB (”MWAB”)","caption":"Förvärv · 8 mars 2022","preamble":"MWAB är baserat i Stockholm och är specialiserat inom dyk- och undervattensentreprenader i trånga och kontaminerade miljöer på uppdrag av kunder inom offentlig sektor samt privata beställare. Bolaget har över 40 års erfarenhet och omsätter cirka 35 miljoner kronor på årsbasis.","body":"Vinges team bestod huvudsakligen av delägare Christina Kokko tillsammans med de biträdande juristerna Manne Bergström och Carl Fredrik Wachtmeister (M&A), Ellen Åkerdahl Flygt (M&A och Banking & Finance), Isak Willborg (Agreements), Elin Broman (Employment), Tove Tullberg (Compliance) samt Sara Dahlros Sköld och Elin Kollin (VDR-assistenter).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-infra-services-group-eleda-i-samband-med-forvarv-av-mats-wahlin-ab-mwab/","date":"2022-03-08","month":3},{"year":2022,"client":"Insight Partners","work":"Kapitalanskaffning","disciplines":["Arbetsrätt","Försäkring","IT, Telekom och Outsourcing","M&A","Corporate Crime & Compliance","Finansiella tillståndsfrågor","Immaterialrätt"],"title":"Vinge har företrätt Insight Partners i samband med deras deltagande i en investeringsrunda i Insurely om 190 MSEK.","caption":"Kapitalanskaffning · 8 mars 2022","preamble":"Vinge har företrätt Insight Partners i samband med deras deltagande i en investeringsrunda om 190 MSEK i Insurely. Insurely erbjuder en digital plattform som möjliggör för försäkringstagare att enkelt få en översikt över sina försäkringar.","body":"Vinges team har bestått av Christina Kokko, Johan Larsson, Isabelle Wållgren och Nando Basic (M&A), Viveka Classon och Elin Samara (Insurance regulatory), Fredrika Hjelmberg (IT), Nicklas Thorgerzon (GDPR), Elin Broman (Arbetsrätt), Axel Lennartsson (IPR), Tove Tullberg (Compliance) och Sara Dahlros Sköld (VDR).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-insight-partners-i-samband-med-deras-deltagande-i-en-investeringsrunda-i-insurely-om-190-msek/","date":"2022-03-08","month":3},{"year":2022,"client":"Lexington","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder Lexington i budet från Manna & Co","caption":"Övrigt · 8 mars 2022","preamble":"Manna & Co Oy har lämnat ett uppköpserbjudande till aktieägarna i The Lexington Company AB (publ). Erbjudandet värderar samtliga aktier i Lexington till cirka 215 miljoner kronor.","body":"Vinges team består av Erik Sjöman och Agaton Lindgren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lexington-i-budet-fran-manna-co/","date":"2022-03-08","month":3},{"year":2022,"client":"Road Rental","work":"Förvärv","disciplines":["M&A"],"title":"Vinge biträder Road Rental vid förvärv av Trafik & TA i Sverige AB","caption":"Förvärv · 7 mars 2022","preamble":"Vinge har biträtt Road Rental vid förvärv av det familjeägda bolaget Trafik & TA i Sverige AB, som bl.a. upprättar och projekterar TA-planer, APD-planer samt TF-planer.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Gunilla Nyman.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-road-rental-vid-forvarv-av-trafik-ta-i-sverige-ab/","date":"2022-03-07","month":3},{"year":2022,"client":"GHP","work":"Övrigt","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge biträder GHP i budet från Capio","caption":"Övrigt · 7 mars 2022","preamble":"Capio Group Services AB har lämnat ett uppköpserbjudande till aktieägarna i GHP Specialty Care AB (publ). Erbjudandet värderar samtliga aktier i GHP till cirka 2,5 miljarder kronor.","body":"Vinges team består av Erik Sjöman, Anna Palmérus, Magnus Pauli och Agaton Lindgren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-ghp-i-budet-fran-capio/","date":"2022-03-07","month":3},{"year":2022,"client":"EQT Infrastructure och Meine Radiologie / Blikk","work":"Förvärv","disciplines":["Kommersiella avtal","M&A","Bank och finans","Rekonstruktioner och obestånd","Arbetsrätt","IT, Telekom och Outsourcing"],"title":"Vinge företräder EQT Infrastructure och Meine Radiologie / Blikk vid förvärv av Aleris radiologiverksamhet","caption":"Förvärv · 28 februari 2022","preamble":"Vinge företräder EQT Infrastructure och dess portföljbolag Meine Radiologie Holding GmbH samt Blikk Holding GmbH vid förvärv av Aleris radiologiverksamhet.","body":"Förvärvet omfattar hela Aleris radiologiverksamhet med 22 mottagningar i Sverige och 14 i Norge samt teleradiologiverksamhet i Baltikum, som tillsammans utför mer än 1 miljon radiologiundersökningar årligen inom ett brett spektrum av diagnostiska avbildningsmetoder.\n\nTransaktionen är villkorad av tillämpliga konkurrensmyndigheters godkännande.\n\nVinges team bestod av ansvarig delägare Daniel Rosvall tillsammans med Carl Sander, Elsie Nassar, Clara Sohlberg och Ebba Nyberg (M&A), Sam Fakhraie Ardekani (Kommersiella avtal), Benjamin Vafaeian (Bank- och finans), Christoffer Nordin (Tillstånd), Ulf Pyk (Fastighetsrätt), Tove Lövgren Frisk (Regelefterlevand), Gustav Lindgren (Arbetsrätt), Lisa Hörnqvist och Karolina Fuhrman (IT och GDPR), Jolene Reimerson (Separationsfrågor), Emma Gustavsson (IPR) och Ellinor Gyllenhammar (Projekt- och VDR-assistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-eqt-infrastructure-och-meine-radiologie-blikk-vid-forvarv-av-aleris-radiologiverksamhet/","date":"2022-02-28","month":2},{"year":2022,"client":"BHG Group","work":"Förvärv","disciplines":["Arbetsrätt","M&A"],"title":"Vinge företräder BHG Group i samband med förvärv av Hemmy","caption":"Förvärv · 24 februari 2022","preamble":"Vinge har företrätt BHG Group AB:s koncernbolag inom vitvaror och hushållsprodukter, Vitvaruexperten.com Nordic AB, i samband med dess förvärv av drygt 51 % av Hemmy AB med en option om att förvärva upp till 100 %.","body":"Hemmy.se säljer vitvaror, hushållsapparater samt hem- och trädgårdsprodukter online i Sverige. År 2021 omsatte Hemmy.se 103 MSEK.\n\nBHG Group är den största onlineaktören inom konsumenthandel i Norden och den största onlineaktören i Europa inom Home Improvement, som innefattar både Do-It-Yourself och Heminredning. BHG Groups e- handelsverksamheter har drygt 2.000 anställda och inkluderar över 100 onlinedestinationer och 70 showrooms. Huvudkontoret ligger i Malmö med verksamheter i de flesta europeiska länder. BHG Group är noterat på Nasdaq Stockholm.\n\nVinges team bestod av Kristian Ford, Sofie Nordgren, Carl Trolle Olsson, Daniel Melander Björner, Lisa Bourghardt, Simona Mullai, Martin Svanberg och Johanne Örnfeldt Svensson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-bhg-group-i-samband-med-forvarv-av-hemmy/","date":"2022-02-24","month":2},{"year":2022,"client":"FSN Capital","work":"Förvärv","disciplines":["Immaterialrätt","M&A","Corporate Crime & Compliance","Arbetsrätt","Bank och finans","IT, Telekom och Outsourcing","Kommersiella avtal"],"title":"Vinge företräder FSN Capital i samband med förvärv av Seriline","caption":"Förvärv · 23 februari 2022","preamble":"Vinge har företrätt FSN Capital i samband med förvärvet av majoritetsägandet i Seriline AB från dess befintliga ägare, som kommer fortsätta inneha en betydande andel.","body":"Serline grundades 1990 och är en leverantör av IAM-lösningar (s.k. Identity and Access Management). Seriline har utvecklat programvaror, webblösningar, säkerhetssystem, hårdvaror samt tjänster som förenklar flöden till användarvänliga processer med sekretess och integritetshantering av identiteter. Bolaget förväntas bli den första plattformen i FSN:s ”buy-and-build”-strategi för att skapa en marknadsledande nordisk aktör inom IAM.\n\nVinges team bestod huvudsakligen av Johan Winnerblad, Maria Dahlin Kolvik, Eléonore Friberg och Ebba Nyberg (M&A), Mathilda Persson och Karolina Fuhrman (IT/GDPR), Martin Boström (Avtal), Felix Möller (Bank och Finans), Gustav Lindgren (Arbetsrätt), Sofia Bergenstråhle och Axel Lennartsson (IP), Tove Lövgren Frisk (Compliance), Ellinor Gyllenhammar och Elin Kollin (VDR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-fsn-capital-i-samband-med-forvarv-av-seriline/","date":"2022-02-23","month":2},{"year":2022,"client":"Säljarna av Refensa","work":"Avyttring","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder säljarna av Refensa vid försäljning till Viking Ventures portföljbolag Grade","caption":"Avyttring · 23 februari 2022","preamble":"Refensa är en molnbaserad lösning för digital referenstagning vid rekrytering. Förvärvet av Refensa förstärker Grades erbjudande av best-of-breed-lösningar inom HR och är ett naturligt steg i koncernens tillväxtstrategi.","body":"Den växande koncernen Grade består efter förvärvet av bolagen Varbi, Grade, Workbuster och Refensa. I samband med förvärvet av Refensa samlas koncernen under det gemensamma namnet Grade.\n\nVinge företräder grundarna av Refensa i samband med transaktionen.\n\nVinges team bestod av Karl Klackenberg, Ulrich Ziche och Egil Svensson.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-saljarna-av-refensa-vid-forsaljning-till-viking-ventures-portfoljbolag-grade/","date":"2022-02-23","month":2},{"year":2022,"client":"Main Capital och Björn Lundén","work":"Förvärv","disciplines":["Arbetsrätt","M&A"],"title":"Vinge företräder Main Capital och Björn Lundén i samband med förvärvet av QLogic","caption":"Förvärv · 22 februari 2022","preamble":"QLogic tillhandahåller en lösning för tids-, projekt- och kostnadshantering och är kända för sin molnbaserade lösning QBIS. Genom förvärvet stärker Björn Lundén sin tjänst med helhetslösningar för tids-, projekt- och kostnadshantering.","body":"Vinges team bestod av Filip Öhrner, Per Kling, Linus Adolfsson, Rebecka Målquist, Lisa Hörnqvist, Veronika Garemark, Karolina Fuhrman och Ellinor Gyllenhammar.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-main-capital-och-bjorn-lunden-i-samband-med-forvarvet-av-qlogic/","date":"2022-02-22","month":2},{"year":2022,"client":"Main Capital och Alfa eCare","work":"Förvärv","disciplines":["M&A","Immaterialrätt"],"title":"Vinge har biträtt Main Capital och Alfa eCare vid dess strategiska förvärv av Swedish Care System","caption":"Förvärv · 21 februari 2022","preamble":"Alfa eCare-koncernen är en erkänd mjukvaruleverantör inom e-hälsobranschen som tillhandahåller lösningar åt både privata och offentliga vårdgivare i hela Sverige.","body":"Swedish Care System tillhandahåller olika mjukvarulösningar för vårdplanering och digitalisering inom tandvård, såsom digitala journal- och bokningssystem. Bolagets produkter bidrar till en mer effektiv journalföring för vårdgivare.\n\nVinges team bestod av Filip Öhrner, Jonas Johansson, Per Kling, Linus Adolfsson, Arvid Axelryd, Karolina Fuhrman och Elin Broman.","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-main-capital-och-alfa-ecare-vid-dess-strategiska-forvarv-av-swedish-care-system/","date":"2022-02-21","month":2},{"year":2022,"client":"Carnegie","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge har företrätt Carnegie i samband med investering i Opti","caption":"Kapitalanskaffning · 21 februari 2022","preamble":"Vinge har företrätt Carnegie Investment Bank AB (publ) i samband med Carnegies investering i Opti, Sveriges största app för digital kapitalförvaltning, idag värderad till 1 miljard SEK. I ett första steg kommer Carnegie äga 9,9 procent av Opti och efter erforderligt godkännande från Finansinspektionen kommer ägarandelen öka till 16,7 procent.","body":"Vinges team bestod huvudsakligen av Kristian Ford, Sofie Nordgren och Carl Trolle Olson.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-carnegie-i-samband-med-investering-i-opti/","date":"2022-02-21","month":2},{"year":2022,"client":"Lantmännen","work":"Förvärv","disciplines":["EU‑ och konkurrensrätt","M&A"],"title":"Vinge företräder Lantmännen i samband med förvärv av resterande andelar i Scandbio","caption":"Förvärv · 21 februari 2022","preamble":"Vinge företräder Lantmännen i samband med förvärv av resterande andelar i Scandbio AB. Scandbio AB bildades år 2014 då Lantmännen och finska Neova slog ihop sina verksamheter, båda ägarna har sedan 2014 ägt lika delar i bolaget som drivits som ett joint venture.","body":"Scandbio är med en årlig omsättning på cirka 1 000 MSEK Sveriges största företag inom fasta förädlade trädbränslen. Bolaget har sitt huvudkontor i Jönköping och verksamhet vid fem anläggningar i Sverige och en i Lettland. Scandbio tillverkar, marknadsför och säljer träpellets till förbränning i Sverige, Danmark och Baltikum samt stallpellets för den svenska marknaden. Bolaget försörjer såväl industrier som kommunala och statliga verksamheter, lokala entreprenörer och enskilda villaägare med 100 procent förnybar energi.\n\nTransaktionen är villkorad av tillämpliga konkurrensmyndigheters godkännande.\n\nVinges team bestod av Christina Kokko och Elsie Nassar (M&A) tillsammans med Marcus Glader, Johan Wahlbom och Jesper Ekman (Merger filing).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-lantmannen-i-samband-med-forvarv-av-resterande-andelar-i-scandbio/","date":"2022-02-21","month":2},{"year":2022,"client":"Borgo","work":"Obligationsemission","disciplines":["Bank och finans","M&A"],"title":"Vinge biträder Borgo i samband förvärv av bolåneportfölj, övertagande av säkerställda obligationer och upprättande av certifikatprogram","caption":"Obligationsemission · 15 februari 2022","preamble":"Vinge har biträtt Borgo AB (publ) (”Borgo”) i samband med dess förvärv av merparten av Ålandsbankens svenska bolåneportfölj om SEK 10.5 miljarder och dess simultana övertagande av Ålandsbankens emitterade säkerställda obligationer om SEK 7.5 miljarder. Vinge har även biträtt Borgo med upprättandet av dess program för emission av företagscertifikat denominerade i SEK eller EUR, med ett totalt rambelopp om SEK 10 miljarder.","body":"Förvärvet av bolåneportföljen är en fortsättning på det samarbete som inleddes hösten 2019 mellan ICA Banken, Ikano Bank, Söderberg & Partners, Ålandsbanken och Borgo. Inom samarbetet är Borgo kreditgivare, och ICA Banken, Ikano Bank, Söderberg & Partners, Ålandsbanken samt Sparbanken Syd kreditförmedlare, med förmedling av bolån under egna varumärken och med egna erbjudanden\n\nVinges team bestod huvudsakligen av Johan Larsson, Joacim Rydegård och Carl Fredrik Wachtmeister (M&A), Mikael Ståhl, Lionardo Ojeda, Axel Jansson och Felix Möller (Bank och Finans) samt Caroline Krassén (Financial Services).","href":"https://www.vinge.se/uppdrag/vinge-bitrader-borgo-i-samband-forvarv-av-bolaneportfolj-overtagande-av-sakerstallda-obligationer-och-upprattande-av-certifikatprogram/","date":"2022-02-15","month":2},{"year":2022,"client":"Trellis Road","work":"Fondetablering","disciplines":[],"title":"Vinge har företrätt Trellis Road i samband med fondetablering","caption":"Fondetablering · 11 februari 2022","preamble":"Vinge har agerat rådgivare till Trellis Road i samband med struktureringen, fondresningen och etableringen av Trellis Roads första mikrofond.","body":"Trellis Road är en svensk venture capital-fond med ett globalt investeringsmandat som fokuserar på tidiga investeringar i food tech-bolag. Fonden, som backas av ett antal framgångsrika entreprenörer stängde i december 2021 med ett totalt belopp om 18 miljoner USD.\n\nVinges team bestod huvudsakligen av Rickard Vernet och Viveka Claesson (regulatoriska frågor).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-trellis-road-i-samband-med-fondetablering/","date":"2022-02-11","month":2},{"year":2022,"client":"Beontag","work":"Förvärv","disciplines":["M&A","Arbetsrätt"],"title":"Vinge har företrätt Beontag – CCRR Group i samband med förvärvet av Scandstick AB med dotterbolag och Linerless AB","caption":"Förvärv · 10 februari 2022","preamble":"Vinge har företrätt Beontag i samband med förvärvet av Scandstick koncernen. Scandstick är en internationell koncern med bolag inom tillverkning och försäljning av självhäftande material för etikettindustrin med huvudkontor i Höganäs, Sverige.","body":"Verksamheten bedrivs med produktionsanläggningar i Sverige, Belgien, Slovenien och Polen och har totalt cirka 150 anställda.\n\nBeontag är den största tillverkaren i Latinamerika av RAIN RFID-inlägg och taggar.\n\nVinges team bestod huvudsakligen av Magnus Pauli, Sofie Nordgren (Projektledare), Johanna Hamrefält (M&A manager), Tilda Hall (Avtal och Fastighetsrätt), Agaton Lindgren (Finans) och Anna Ståhlklo (Arbetsrätt), samt flera andra.\n\nSelih & Partnerji i Slovenien, Wardynski & Partners i Polen och Liedekerke i Belgien har agerat lokala ombud i transaktionen.","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-beontag-ccrr-group-beontag-i-samband-med-forvarvet-av-scandstick-ab-med-dotterbolag-och-linerless-ab-scandstick-koncernen/","date":"2022-02-10","month":2},{"year":2022,"client":"Intracto Group","work":"Förvärv","disciplines":["Arbetsrätt","M&A"],"title":"Vinge har företrätt Intracto Group i samband med förvärvet av den digitala webbyrån Awave Group.","caption":"Förvärv · 10 februari 2022","preamble":"Awave är en digital webbyrå med erfarenhet inom webbutveckling, UX, UI och digital marknadsföring. Awave-koncernen har cirka 55 anställda i Sverige, Danmark och Lettland. Intracto Group är en innovativ digital servicekoncern i Benelux och Norden.","body":"Vinges team bestod huvudsakligen av Magnus Pauli, Johanna Hamrefält (Projektledare), Anna Ståhlklo (M&A), Alexander Lindeberg (IP/IT) and Gabriella Varga (Arbetsrätt).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-intracto-group-i-samband-med-forvarvet-av-den-digitala-webbyran-awave-group/","date":"2022-02-10","month":2},{"year":2022,"client":"Borgo","work":"Obligationsemission","disciplines":["Bank och finans"],"title":"Vinge biträder Borgo i samband med upprättandet av dess MTN- och covered bond-program samt dess första emission av seniora obligationer","caption":"Obligationsemission · 3 februari 2022","preamble":"Vinge har biträtt Borgo AB (publ) (”Borgo”) i samband med upprättandet av dess obligationsprogram om SEK 50 miljarder för emissioner av seniora icke-säkerställda obligationer och säkerställda obligationer (”Programmet”) samt i samband med dess första emission av seniora icke-säkerställda obligationer till ett belopp om SEK 1,75 miljarder (”Obligationerna”). Borgo har under Programmet möjlighet att även emittera gröna seniora icke-säkerställda obligationer.","body":"De säkerställda obligationerna som emitteras under Programmet säkerställs av underliggande bolån på den svenska marknaden i enlighet med lag (2003:1223) om utgivning av säkerställda obligationer. Obligationerna löper med en rörlig ränta om STIBOR 3M + 0.90% och avses noteras på listan för företagsobligationer på Nasdaq Stockholm.\n\nBorgo är ett nytt svenskt hypoteksbolag som samägs av ICA Banken, Ikano Bank, Söderberg & Partners och Ålandsbanken. Ytterligare investerare samt Sparbanken Syd har förbundit sig att investera i Borgo. Borgo drivs fristående och fokuserar på att finansiera och erbjuda bostadskrediter. Genom en struktur där flera starka aktörer går samman som ägare och förmedlare av krediter, kombinerat med moderna processer, skapas förutsättningar för att kunna erbjuda attraktiva bolån till konsumenter, samt attraktiva sparkonton, på ett ekonomiskt hållbart sätt.\n\nVinges team bestod av Mikael Ståhl, Lionardo Ojeda, Axel Jansson och Felix Möller.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-borgo-i-samband-med-upprattandet-av-dess-mtn-och-covered-bond-program-samt-dess-forsta-emission-av-seniora-obligationer/","date":"2022-02-03","month":2},{"year":2022,"client":"Annotell","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Annotell i finansieringsrunda","caption":"Kapitalanskaffning · 3 februari 2022","preamble":"Vinge har biträtt Annotell AB i en A-runda när bolaget tar in ca 220 milj kr från Mediaplanet och Nordicninja. Dessutom deltar de befintliga investerarna Ernström & C:o och Stena Sessan i rundan. Annotell erbjuder marknadsledande mjukvara för utveckling av avancerade förarassistanssystem och självkörande fordon.","body":"Vinges team bestod i huvudsak av Johan Winnerblad och Veronika Garemark.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-annotell-i-finansieringsrunda/","date":"2022-02-03","month":2},{"year":2022,"client":"APM Human Services International Limited","work":"Förvärv","disciplines":["M&A","Arbetsrätt","Immaterialrätt"],"title":"Vinge har företrätt APM Human Services International Limited i samband med förvärv av Clustera Sverige AB","caption":"Förvärv · 1 februari 2022","preamble":"Clustera Sverige AB är en av Sveriges ledande aktörer inom arbetsförmedlingsmarknaden. Förvärvet är ett steg i APMs inträde på den svenska marknaden. Med kontor på cirka 40 orter över Sverige är Clustera en licensierad leverantör för Arbetsförmedlingen.","body":"Vinges team bestod av Johanna Hamrefält (projektledare), Christian Riddarbo, Linus Adolfsson (M&A), Adam Loewenstein (Fastighet), Beatrice Randow (fastighet), Anna Ståhlklo (arbetsrätt) och Anna Högsten (IP/IT).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-apm-human-services-international-limited-apm-i-samband-med-forvarv-av-clustera-sverige-ab/","date":"2022-02-01","month":2},{"year":2022,"client":"Gunnebo","work":"Avyttring","disciplines":["Bolagsrätt","IT, Telekom och Outsourcing","M&A","Immaterialrätt","Carve-Outs"],"title":"Vinge företräder Gunnebo i samband med försäljningen av dess Cash Management-verksamhet","caption":"Avyttring · 1 februari 2022","preamble":"Vinge företräder Gunnebo Aktiebolag (”Gunnebo”) i samband med försäljningen av dess Cash Management-verksamhet till Sesami Cash Management Technologies Corporation, ett kontanthanteringsbolag kontrollerat av GardaWorld Security Corporation.","body":"Cash Management-verksamheten innefattar lösningar för automatiserade kontanthanteringssystem, mjukvaror och tjänster inom sluten kontanthantering samt recirkulering och deposition av kontanter, med syftet att skapa en effektivare och säkrare kontantprocess samt minska kostnader för hantering av sedlar och mynt.\n\nAvyttringen ingår i Gunnebos transformationsresa som startade 2020 där man avyttrat flera delar inom bolaget inom integrerad säkerhet och kontanthantering, för att kunna fokusera på Gunnebos ledande position globalt inom affärsenheterna Entrance Control och Safe Storage.\n\nTransaktionen förväntas vara avslutad den 1 mars 2022.\n\nVinges team bestod av Christina Kokko, Matthias Pannier, Maria Dahlin Kolvik, Viktor Lennartsson och Nina Fathjalali (M&A), Mathilda Persson och Martin Boström (Commercial Agreements/IT), Stojan Arnerstål och Michael Montner (IP) samt Cathrin Larsson, Sara Dahlros Sköld och Christoffer Widström (VDR).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-gunnebo-i-samband-med-forsaljningen-av-dess-cash-management-verksamhet/","date":"2022-02-01","month":2},{"year":2022,"client":"Lassila & Tikanoja","work":"Förvärv","disciplines":["Arbetsrätt","M&A"],"title":"Vinge biträder Lassila & Tikanoja vid förvärv av aktier i SVB","caption":"Förvärv · 1 februari 2022","preamble":"Vinge har biträtt finska Lassila & Tikanoja vid förvärv av 70% av aktierna i Sand & Vattenbläst i Tyringe AB, SVB. SVB levererar industri- och miljösaneringstjänster samt betong- och ytbehandlingsarbeten till företagskunder inom industri-, bygg- och fastighetssektorn.","body":"Vinges team bestod i huvudsak av Johan Winnerblad, Stina Bengtsson, Åsa Gotthardsson och Jonna Skog.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-lassila-tikanoja-vid-forvarv-av-aktier-i-svb/","date":"2022-02-01","month":2},{"year":2022,"client":"Allianz Real Estate","work":"Partnerskap","disciplines":["Fastigheter och Entreprenad","M&A","Bank och finans"],"title":"Vinge har biträtt Allianz Real Estate i samband med joint venture med Heimstaden Bostad","caption":"Partnerskap · 31 januari 2022","preamble":"Vinge har biträtt Allianz Real Estate i samband med en investering om 7,9 miljarder i Heimstaden Bostads svenska portfölj som nyligen förvärvades från Akelius, genom bildandet av ett joint venture. Portföljen består av centralt belägna fastigheter i Malmö och Stockholm med ett värde om 30,4 miljarder.","body":"Vinges team bestod av Assur Badur, Karolina Cohrs och Frida Ställborn (Real Estate), Joacim Rydergård och Clara Sohlberg (Private M&A) samt Mikael Ståhl och Arvid Weimers (finansiering).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-allianz-real-estate-i-samband-med-joint-venture-med-heimstaden-bostad/","date":"2022-01-31","month":1},{"year":2022,"client":"Nabo","work":"Övrigt","disciplines":["M&A"],"title":"Vinge har företrätt Nabo i samband med förväv","caption":"Övrigt · 28 januari 2022","preamble":"Vinge har företrätt Nabo, ett ledande mjukvaru- och serviceföretag som riktar sig till fastighetsmarknaden, i samband med dess förvärv av två fastighetsförvaltningsbolag i Finland, MTR-Isännöinti Oy och Suomen Tekninen Isännöinti Oy.","body":"Vinges team bestod av Jonas Bergström, Johanna Wiberg, Christa Anttila och Nando Basic (M&A).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-nabo-i-samband-med-forvav/","date":"2022-01-28","month":1},{"year":2022,"client":"Eleda Infra Services Group (Eleda)","work":"Förvärv","disciplines":["Arbetsrätt","M&A","Fastigheter och Entreprenad","Bank och finans"],"title":"Vinge har företrätt Eleda Infra Services Group (”Eleda”) i samband med förvärv av G Construct AB (”G Construct”)","caption":"Förvärv · 27 januari 2022","preamble":"G Construct är ett mark- och anläggningsföretag som är baserat i Enköping och är specialiserade på uppförande av industrigrunder, på uppdrag av kunder inom privat sektor. Bolaget har 25 medarbetare och omsätter cirka 250 miljoner kronor på årsbasis.","body":"Vinges team bestod huvudsakligen av delägare Christina Kokko tillsammans med de biträdande juristerna Manne Bergström, Hannah Kajlinger och Ellen Åkerdahl Flygt (M&A), Isak Willborg (Entreprenadrätt), Daniel Melander Björner (Employment), Jolinn Uhlin och Calle Tengwall Pagels (Banking & Finance) samt Klara Lundquist och Jessica Henning (VDR-assistenter).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-eleda-infra-services-group-eleda-i-samband-med-forvarv-av-g-construct-ab-g-construct/","date":"2022-01-27","month":1},{"year":2022,"client":"AtNorths ägare","work":"Avyttring","disciplines":["M&A"],"title":"Vinge företräder atNorths ägare i samband med försäljningen till Partners Group","caption":"Avyttring · 27 januari 2022","preamble":"Vinge har företrätt aktieägarna i atNorth Holding AB vid försäljningen av bolaget till det schweiziska private equity-bolaget Partners Group.","body":"atNorth är ett ledande datacenterbolag med två center på Island och ett under uppbyggnad i Stockholm. Bolagets datahallar drivs uteslutande av förnybar energi och använder lokalt klimat och värmeåtervinningssystem för att upprätthålla en extremt hög energieffektivitet.\n\nVinges team bestod huvudsakligen av delägare Peter Sundgren tilsammans med de biträdande juristerna Vilhelm Rondahl, Gustav Persson och Linus Adolfsson (M&A), Maria Schultzberg (Skatt) samt Viktoria Owetz Leyva och Sara Dahlros Sköld (VDR-assistenter).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-atnorths-agare-i-samband-med-forsaljningen-till-partners-group/","date":"2022-01-27","month":1},{"year":2022,"client":"Aktieägarna","work":"Avyttring","disciplines":["M&A","Bank och finans"],"title":"Vinge företräder aktieägarna, däribland Bridgepoint, i FCG Group AB i samband med försäljningen till IK Partners","caption":"Avyttring · 19 januari 2022","preamble":"FCG är en GRC-tjänsteleverantör som erbjuder rådgivning, outsourcing, fondadministrativa tjänster och tech-lösningar inom GRC till finansbranschen.","body":"FCG som grundades 2008 och med huvudkontor i Stockholm, har utvecklats till att bli en ledande aktör inom GRC i Norden. FCG har en diversifierad kundbas som sträcker sig från snabbväxande fintech-start-ups till stora banker.\n\nTransaktionen är villkorad av tillämpliga godkännanden från myndigheter.\n\nVinges team bestod av Daniel Rosvall, Samra Baytar, Per Kling, Linnea Petersson och Caroline Krassén.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-aktieagarna-daribland-bridgepoint-i-fcg-group-ab-i-samband-med-forsaljningen-till-ik-partners/","date":"2022-01-19","month":1},{"year":2022,"client":"Axcel VI och Currentum","work":"Förvärv","disciplines":["Arbetsrätt","Fastigheter och Entreprenad","Bank och finans","M&A"],"title":"Vinge företräder Axcel VI och Currentum vid förvärv av Ipart-koncernen","caption":"Förvärv · 18 januari 2022","preamble":"Vinge företräder Axcel VI och Currentum-koncernen vid förvärv av tillväxtkoncernen Ipart vilket inkluderar bolagen SP-gruppen AB, Klimatentreprenad Värmland AB, Rörinstallationer i Karlstad AB, Ulvsby Rör AB, MeR El AB, och GÖREL Norden AB.","body":"Bolagen tillhandahåller tjänster inom ventilation, VS, el och säkerhet och är verksamma i Väst- och Mellansverige. Ipart-koncernen omsätter årligen cirka 350 miljoner kronor och har drygt 100 medarbetare. Genom förvärvet av Ipart-koncernen förväntas Currentum omsätta cirka 2,5 miljarder kronor och sysselsätta drygt 900 medarbetare. Transaktionen är villkorad av sedvanliga myndighetsgodkännanden.\n\nVinges team bestod av ansvarig delägare Christina Kokko tillsammans med Karl Klackenberg, Hannah Kajlinger och Linnea Petersson (M&A), Isak Willborg (Entreprenadrätt), Elin Broman (Arbetsrätt), Michaela Ådén (Finansiering), Ulf Pyk (Fastighetsrätt) och Julia Hagelberg (Projekt- och VDR-assistent).","href":"https://www.vinge.se/uppdrag/vinge-foretrader-axcel-vi-och-currentum-vid-forvarv-av-ipart-koncernen/","date":"2022-01-18","month":1},{"year":2022,"client":"Stena Sessan","work":"Kapitalanskaffning","disciplines":["M&A"],"title":"Vinge biträder Stena Sessan vid investering i Matilda FoodTech","caption":"Kapitalanskaffning · 18 januari 2022","preamble":"Vinge biträder Stena Sessan vid investering i det svenska mjukvarubolaget Matilda FoodTech. I samband med investeringen går Stena Sessan in som minoritetsägare bredvid huvudägaren Monterro.","body":"Vinges team bestod av Johan Winnerblad och Desirée Hagenfeldt.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-stena-sessan-vid-investering-i-matilda-foodtech/","date":"2022-01-18","month":1},{"year":2022,"client":"Oncorena","work":"Övrigt","disciplines":[],"title":"Vinge biträder Oncorena","caption":"Övrigt · 13 januari 2022","preamble":"Vinge biträder Oncorena Holding AB i samband med en investering om initialt 66 miljoner kronor från Linc, HealthCap och Fåhraeus Startup and Growth.","body":"Investeringen ska främst finansiera Oncorenas första kliniska studie, en fas I/II-studie med orellanin i patienter med avancerad njurcancer. I det fall den initiala delen av den kliniska studien ger positiva resultat har investerarna för avsikt att finansiera den andra delen av studien med ytterligare 94 miljoner kronor.\n\nVinges team består av Christian Lindhé, Martin Svanberg och Sofie Nordgren.","href":"https://www.vinge.se/uppdrag/vinge-bitrader-oncorena/","date":"2022-01-13","month":1},{"year":2022,"client":"Bonhams 1793 Limited","work":"Förvärv","disciplines":["M&A"],"title":"Vinge har företrätt Bonhams 1793 Limited i dess förvärv av Bukowski","caption":"Förvärv · 11 januari 2022","preamble":"Vinge har företrätt Bonhams 1793 Limited, ett internationellt auktionshus med huvudkontor i London och portföljbolag till Epiris LLP, i samband med förvärvet av Bukowski Auktioner Aktiebolag (”Bukowski”).","body":"Bukowski är ett auktionshus inom konst och antikviteter och har sitt huvudkontor vid Berzelii Park i Stockholm. Bolaget har även ett finskt dotterbolag, Bukowski Oy. Genom förvärvet utökar Bonhams sin geografiska närvaro i Europa.\n\nVinges team bestod av bland andra Christina Kokko, Isabelle Wållgren, Hannah Kajlinger, Christa Anttila, Vilhelm Rondahl och Ellen Åkerdahl Flygt (M&A), Anton Sjökvist och Caroline Krassén (Financial Services), Tove Lövgren Frisk (Compliance), Karl-Hugo Engdahl (GDPR, IT), Ulf Pyk (Fastighet), Karolina Fuhrman och Isabell Nielsen (Corporate Commercial), Arvid Axelryd (IPR), Emil Lindvall och Gustav Lindgren (Arbetsrätt) och Sara Dahlros Sköld (VDR).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-bonhams-1793-limited-i-dess-forvarv-av-bukowski-auktioner-aktiebolag/","date":"2022-01-11","month":1},{"year":2022,"client":"Inspecs Group","work":"Förvärv","disciplines":["M&A"],"title":"Vinge företräder Inspecs Group i förvärv av Ego Eyewear Limite","caption":"Förvärv · 7 januari 2022","preamble":"Vinge företräder Inspecs Group plc i förvärv av Ego Eyewear Limited.","body":"För mer information om transaktion se klientens pressmeddelande.\n\nVinges team bestod av delägare Christina Kokko, counsel Ulrich Ziche, tillsammans med bland andra biträdande juristerna Nina Gransäter, Robin Fagerström, Ebba Nyberg, Isabell Nielsen, Veronika Garemark, Rebecka Målquist, Ulf Pyk och projektassistenter Jessica Henning och Sara Dahlros Sköld. Counsel Maria Schultzberg och biträdande juristerna Karl-Gustaw Tobola biträdde avseende skattefrågor.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-inspecs-group-i-forvarv-av-ego-eyewear-limited/","date":"2022-01-07","month":1},{"year":2022,"client":"Procuritas","work":"Avyttring","disciplines":["EU‑ och konkurrensrätt","IT, Telekom och Outsourcing","M&A","Immaterialrätt"],"title":"Vinge har företrätt Procuritas i samband med försäljningen av Ouriginal Group","caption":"Avyttring · 7 januari 2022","preamble":"Vinge har företrätt Procuritas, ett Private Equity-bolag som fokuserar på investeringar i nordiska tillväxtbolag inom mid-market-segmentet, i samband med försäljningen av Ouriginal Group till Turnitin LLC, en global ledare inom akademisk integritet och EdTech.","body":"Ouriginal, som bildats genom en sammanslagning av Urkund och PlagScan, har över trettio års erfarenhet av textanalys och erbjuder ett enkelt, pålitligt och effektivt verktyg för plagiatkontroll.\n\nVinges team bestod av Jonas Johansson, Karl Klackenberg och Ellinor Wargenbrant (M&A), Mathilda Persson (IT), Tobias Kempas (IP), Sebastian Örndahl och Victoria Fredén (konkurrensrätt) och Viktoria Owetz Leyva (VDR).","href":"https://www.vinge.se/uppdrag/vinge-har-foretratt-procuritas-i-samband-med-forsaljningen-av-ouriginal-group/","date":"2022-01-07","month":1},{"year":2022,"client":"Randviken Fastigheter","work":"Förvärv","disciplines":["Fastigheter och Entreprenad"],"title":"Vinge har biträtt Randviken Fastigheter med förvärv och förvärvsfinansiering till ett sammanlagt värde om cirka 2,8 miljarder kronor","caption":"Förvärv · 3 januari 2022","preamble":"Vinge har biträtt Randviken Fastigheter AB (publ) med dess förvärv och förvärvsfinansiering av fastigheter till ett sammanlagt överenskommet fastighetsvärde om cirka 2,8 miljarder kronor. Förvärvet finansierades bland annat genom bankfaciliteter om cirka 2,3 miljarder kronor och slutfördes under december 2021.","body":"De förvärvade fastigheterna är huvudsakligen belägna i Stockholm, Västerås och Malmö och den primära användningen är lager/lätt industri, vård och skola samt kontor. Förvärvet omfattar även ett nybyggnadsprojekt avseende kontorslokaler.\n\nEn betydande andel av det totala lånebeloppet är förvärvslån och merparten av förvärvslånen utgörs av seniorlån och en mindre andel är ett brygglån med en kortare löptid. I bankfinansieringen ingår också ett Capex-lån vilket till del ska finansiera slutförandet av nybyggnadsprojektet.\n\nVinges team bestod av Niclas Winnberg och Kristoffer Larson (Fastighet), samt Fabian Ekeblad, Arvid Weimers och Elin Samara (Bank och Finans).","href":"https://www.vinge.se/uppdrag/vinge-har-bitratt-randviken-fastigheter-med-dess-forvarv-och-forvarvsfinansiering-av-fastigheter-till-ett-sammanlagt-overenskommet-fastighetsvarde-om-cirka-2-8-miljarder-kronor/","date":"2022-01-03","month":1},{"year":2022,"client":"Cinclus Pharma","work":"Kapitalanskaffning","disciplines":["Kapitalmarknad och publik M&A"],"title":"Vinge företräder Cinclus Pharma i samband med kapitalanskaffning","caption":"Kapitalanskaffning · 5 mars 2020","preamble":"Vinge har företrätt läkemedelsutvecklingsbolaget Cinclus Pharma i samband med en kapitalanskaffning om cirka 250 miljoner kronor genom en riktad nyemission till ett antal nya investerare och befintliga ägare.","body":"Syftet med emissionen är att finansiera den fortsatta kliniska utvecklingen av läkemedelskandidaten X824 mot gastroesofagal refluxsjukdom (GERD).\n\nVinges team bestod huvudsakligen av Dain Hård Nevonen, Kristina Ekberg, Amanda Knutsson och Fredric Reissmüller.","href":"https://www.vinge.se/uppdrag/vinge-foretrader-cinclus-pharma-i-samband-med-kapitalanskaffning/","date":"2020-03-05","month":3}];
